def _evidence_rank(evidence: object) -> int:
    """证据等级序：E0 > E1 > E2 > E3 > unknown（同 path_naturalization 口径）。"""
    return {
        "E0": 4,
        "E1": 3,
        "E2": 2,
        "E3": 1,
    }.get(str(evidence or ""), 0)


def irq_delivery_enabled() -> bool:
    """r31 P3：模型驱动中断投递总开关（默认关，保持历史行为便于配对 A/B）。

    打开后器件模型（TIM5/ICSR/OTG_FS）经 SemanticProfileRegistry 注册为读路径
    优先级 3 的语义 profile，投递由「固件自己写的 CR1/DIER/CCR1」驱动，速率旋钮
    显式可配（LSGEMU_IRQ_US_PER_INSN）。旋钮式强制投递不存在——没有该代码路径。
    """
    return _env_flag("LSGEMU_IRQ_DELIVERY", "0")


def baseline_irq_delivery_enabled() -> bool:
    """r36 K1：主流程投递安装开关（默认关）。

    r40 P2/C8 起，k.5 的「baseline 返回后装到常驻 self.emulator」安装点
    （``install_post_baseline_irq_delivery``）已删除——其后相位走
    ``fresh_emulator=True``，钩子挂在不执行的实例上（smokeZ 实测
    instructions=0 / delivery_count=0）。主流程/相位投递统一走
    ``LSGEMU_IRQ_DELIVERY_PHASES`` 相位白名单
    （``install_irq_delivery_for``，装进各相位自建 temp emulator）。
    本开关保留读面兼容（老臂配置解释），不再有生产消费点。
    """
    return _env_flag("LSGEMU_IRQ_DELIVERY_BASELINE", "0")


# r40 P2/C8：明确不装投递的相位（k.4 P0-1）。semantic_entry_prefix 的
# 摘要前缀口径不得引入投递/svc 派发——白名单里写了也拒绝并告警一次。
_IRQ_DELIVERY_REFUSED_PHASES = ("semantic_entry_prefix",)
_irq_delivery_refused_warned: set = set()


def irq_delivery_phase_enabled(phase_name: Optional[str]) -> bool:
    """r40 P2/C8：LSGEMU_IRQ_DELIVERY_PHASES 相位白名单（缺省空 = 现状逐位不变）。

    背景：k.5 P2 把主流程投递装到常驻 ``self.emulator``，而其后相位走
    ``fresh_emulator=True`` → ``_new_temp_emulator`` ⇒ 钩子挂在不执行的
    实例上（smokeZ 实测 instructions=0 / delivery_count=0）。白名单机制
    把安装点搬进相位自建 temp emulator 的重放原语（样板
    ``_dfs_flip_replay_once``）：MMIO 快照恢复之后装、finally 摘、审计随
    run_result。

    语法：逗号分隔；条目 ``name`` 精确匹配，``prefix*`` 前缀匹配（相位名
    带轮次号，如 ``branch_reservoir_round_*``）。master 开关
    ``LSGEMU_IRQ_DELIVERY=1`` 仍然必开——白名单不越权。
    """
    if not phase_name:
        return False
    name = str(phase_name)
    raw = os.environ.get("LSGEMU_IRQ_DELIVERY_PHASES", "") or ""
    entries = [entry.strip() for entry in raw.split(",") if entry.strip()]
    if not entries:
        return False
    if name in _IRQ_DELIVERY_REFUSED_PHASES:
        if name not in _irq_delivery_refused_warned:
            _irq_delivery_refused_warned.add(name)
            logger.warning(
                "r40 P2：相位 %s 在拒绝清单上（摘要前缀口径不得引入投递），"
                "即使写进 LSGEMU_IRQ_DELIVERY_PHASES 也不安装",
                name,
            )
        return False
    if not irq_delivery_enabled():
        return False
    for entry in entries:
        if entry.endswith("*"):
            if name.startswith(entry[:-1]):
                return True
        elif entry == name:
            return True
    return False


def join_discovery_direction_oracle(
    oracle_events: Iterable[Mapping[str, object]],
    records: Iterable[Mapping[str, object]],
    *,
    rv_branches: Optional[Iterable[int]] = None,
) -> Dict[str, object]:
    """P1-F（cycle3 k.5 C4）：探索期方向 oracle 的同域 join。

    主键 = ``(bb, local_occ, identity)``——**双域同源**：两侧的 occ 都是
    重放域本地出现数、identity 都是根快照四元组（k.4 R2/R4 裁定：catalog
    全局 occ 键与 record root_occurrence 分属不同执行域，硬拼必错位，
    本函数禁用该键）。回退次序：

    1. 主键唯一命中 ⇒ ``primary``；
    2. K1 = ``(bb,)`` + 单边唯一（该 bb 在 oracle 池恰一条事件 ⇒ 方向无
       歧义）⇒ ``k1_single_edge``——legacy（无 identity）记录的回退；
    3. 同 bb 多事件且主键未命中 ⇒ ``ambiguous``（宁缺毋错拼）；
    4. 该 bb 无事件 ⇒ ``oracle_unavailable``，子标 ``rv_root_no_direction``
       （bb 在 rv 变体表但无方向）或 ``no_root_at_all``。
    """
    primary: Dict[Tuple[int, int, Tuple[int, ...]], Optional[Mapping[str, object]]] = {}
    by_bb: Dict[int, List[Mapping[str, object]]] = {}
    for event in oracle_events or []:
        bb = int(event.get("bb_int", int(str(event.get("bb", "0")), 0)) or 0) & 0xFFFFFFFF
        by_bb.setdefault(bb, []).append(event)
        identity = event.get("identity")
        if isinstance(identity, (tuple, list)) and len(identity) == 4:
            try:
                key = (
                    bb,
                    int(event.get("local_occ", 1) or 1),
                    tuple(int(part) for part in identity),
                )
            except (TypeError, ValueError):
                continue
            if key in primary:
                # 主键重复 = oracle 池自身歧义，降级为不可用（不硬拼）。
                primary[key] = None
            else:
                primary[key] = event

    rv_set = {int(bb) & 0xFFFFFFFF for bb in (rv_branches or [])}

    joined = ambiguous = unavailable = 0
    by_source: Dict[str, int] = {}
    labelled: List[Dict[str, object]] = []
    for record in records or []:
        bb_raw = record.get(
            "bb_int",
            int(str(record.get("bb", record.get("snapshot_address", "0"))), 0),
        )
        bb = int(bb_raw or 0) & 0xFFFFFFFF
        occ = int(record.get("root_occurrence", record.get("local_occ", 1)) or 1)
        identity = record.get("identity")
        events_at_bb = by_bb.get(bb, [])
        label: Optional[str] = None
        if isinstance(identity, (tuple, list)) and len(identity) == 4:
            try:
                key = (bb, occ, tuple(int(part) for part in identity))
            except (TypeError, ValueError):
                key = None
            if key is not None and primary.get(key) is not None:
                label = "primary"
        if label is None and len(events_at_bb) == 1:
            # K1：单边唯一（edge-keyed catalog 不变量）——legacy 与主键未
            # 命中记录共用这一无歧义回退。
            label = "k1_single_edge"
        if label is None:
            if not events_at_bb:
                label = (
                    "oracle_unavailable:rv_root_no_direction"
                    if bb in rv_set
                    else "oracle_unavailable:no_root_at_all"
                )
                unavailable += 1
            else:
                label = "ambiguous"
                ambiguous += 1
        if label in {"primary", "k1_single_edge"}:
            joined += 1
        by_source[label] = by_source.get(label, 0) + 1
        labelled.append({"bb": f"0x{bb:08x}", "occurrence": occ, "label": label})
    return {
        "joined": joined,
        "ambiguous": ambiguous,
        "oracle_unavailable": unavailable,
        "by_source": by_source,
        "records": labelled,
    }


def coverage_accounting_three_number(
    *,
    covered_bbs: int,
    validated_bbs: int,
    canonical_counterfactual_only_bbs: int,
    counterfactual_face_bbs: Optional[int] = None,
) -> Dict[str, object]:
    """P0-C（cycle3 k.5 C5）：记账三数 schema（cycle4 k.5 C3 集合式口径）。

    恒等式 ``covered = validated + direction_confirmed_counterfactual_only
    + fidelity_gap``（k.4 复算 armP3：1450 = 1448 + 2 + 0）。构造性保证：
    ``canonical_counterfactual_only_bbs`` 必须喂集合基数 ``len(cf ∩ V)``
    （方向经反事实重放确证、且已计入 validated 的 BB），于是
    ``validated_bbs = |V ∖ cf|`` 是合法集合减数，各桶按构造互斥，不依赖
    跨轴数值（账本水位之类）。调用点守卫 ``cf_subset_validated`` 在集合
    作用域内复核发射槽 == ``len(cf ∩ V)``。``counterfactual_face_bbs``
    （可选）是 legacy 证据分区整脸 ``|cf|`` 的**只读披露**
    （268 = 107 进 validated + 161 diagnostic），不得当减数用。Q4 粗口径：
    三数 ``fidelity_gap`` 是五数末两桶（exploration ∪ unclassified）的
    合并（结构恒等 ``三.gap = |cov ∖ V| = |D ∪ U|``）。警示：validated
    同名键跨上下文多值——锚名 ``validated_replay_bbs``=|V|（1555）、本槽
    ``validated_bbs``=|V∖cf|（1448）、相位层
    ``canonical_evidence_by_phase/*/validated_bbs``=各相位自身计数，
    勿混读。纯记账，零执行语义。
    """
    counterfactual_only = int(canonical_counterfactual_only_bbs)
    validated_strict = max(0, int(validated_bbs) - counterfactual_only)
    fidelity_gap = max(0, int(covered_bbs) - int(validated_bbs))
    result: Dict[str, object] = {
        "schema": (
            "covered_bbs = validated_bbs + "
            "direction_confirmed_counterfactual_only_bbs + "
            "fidelity_gap_bbs"
        ),
        "covered_bbs": int(covered_bbs),
        "validated_bbs": validated_strict,
        "validated_bbs_caliber": (
            "validated_replay_minus_direction_confirmed_counterfactual_only"
        ),
        "direction_confirmed_counterfactual_only_bbs": counterfactual_only,
        "fidelity_gap_bbs": fidelity_gap,
        "counterfactual_only_source": "canonical_cf_intersect_validated",
    }
    if counterfactual_face_bbs is not None:
        result["counterfactual_face_bbs"] = int(counterfactual_face_bbs)
        result["counterfactual_face_source"] = "legacy_evidence_partition"
    return result


def u2_fixed_criterion(phase_meta: Optional[Mapping[str, object]]) -> Dict[str, object]:
    """P1-D（cycle3 k.5 C7）：U2 修复版判据的单相位读数面（纯读数，不做门控）。

    修复版五联词（R2 v3 冻结）：baseline 相位集==Y ∧ 报告级零丢失 ∧
    ``no_new_bb_tail=0`` ∧ ``stop_reason=fatal_sink_terminal`` ∧ 计数达标
    （单位=BB，``is_bb_counted``）。前两词是跨臂对照（k.6 验收面），本
    函数给出后三词 + 单位旗标的机读形态。
    """
    meta = phase_meta if isinstance(phase_meta, Mapping) else {}
    run_result = meta.get("run_result")
    if not isinstance(run_result, Mapping):
        run_result = {}
    instruction_count = int(run_result.get("instruction_count", meta.get("instruction_count", 0)) or 0)
    stop_reason = str(run_result.get("stop_reason", meta.get("stop_reason", "")) or "")
    no_new_bb_tail = int(meta.get("no_new_bb_tail", 0) or 0)
    return {
        "no_new_bb_tail": no_new_bb_tail,
        "no_new_bb_tail_zero": no_new_bb_tail == 0,
        "stop_reason": stop_reason,
        "fatal_sink_terminal": stop_reason == "fatal_sink_terminal",
        "instruction_count": instruction_count,
        "is_bb_counted": bool(
            run_result.get("is_bb_counted", meta.get("is_bb_counted", False))
        ),
    }


def termination_merged_denominator(
    *,
    covered_bbs: int,
    validated_bbs: int,
    counterfactual_only_bbs: int,
    exploration_only_bbs: int,
    unclassified_bbs: int,
    e4_red_face_records: int = 0,
    not_accepted_bbs: int = 0,
) -> Dict[str, object]:
    """P0-C/P1-E（cycle3 k.5 C8）：终止条件合并计分母 schema。

    合并计 = ``{validated(direction_confirmed), direction_confirmed_
    counterfactual_only, exploration_only, fidelity_gap} ∪ 不接受项``，各桶
    按构造互斥（cf ⊆ validated 先行剥离；exploration=canonical
    diagnostic_only 与 validated 不相交；fidelity_gap=unclassified）。
    ``e4_red_face_records`` 是 E4 红面**记录数**（P0-C‴ 分类器产线面的
    实测读数，k.6 离线喂入），只在 fidelity_gap 桶内披露、不进 BB 求和
    （单位不同）。``identity_holds`` = 桶求和 == covered——任何强式口径
    渗入（如删减 validated 而不动 cf）都会打破恒等式而被检出。
    """
    counterfactual_only = int(counterfactual_only_bbs)
    validated_strict = max(0, int(validated_bbs) - counterfactual_only)
    exploration_only = int(exploration_only_bbs)
    fidelity_gap = int(unclassified_bbs)
    not_accepted = int(not_accepted_bbs)
    merged_total = (
        validated_strict + counterfactual_only + exploration_only + fidelity_gap + not_accepted
    )
    return {
        "schema": (
            "merged_total_bbs = validated_direction_confirmed_bbs + "
            "direction_confirmed_counterfactual_only_bbs + exploration_only_bbs"
            " + fidelity_gap_bbs + not_accepted_bbs"
        ),
        "covered_bbs": int(covered_bbs),
        "validated_direction_confirmed_bbs": validated_strict,
        "direction_confirmed_counterfactual_only_bbs": counterfactual_only,
        "exploration_only_bbs": exploration_only,
        "fidelity_gap_bbs": fidelity_gap,
        "fidelity_gap": {
            "unclassified_bbs": fidelity_gap,
            "e4_red_face_records": int(e4_red_face_records),
        },
        "not_accepted_bbs": not_accepted,
        "merged_total_bbs": merged_total,
        "identity_holds": merged_total == int(covered_bbs),
    }


def candidate_generation_mechanism_metrics(
    phase_map: Mapping[str, object],
) -> Dict[str, object]:
    """r42：候选生成消融的四机制指标（full vs no_constraint_guided_candidates）。

    从既有 phase metadata 聚合，不反馈调度：原目标到达次数 =
    promoted_paths（原始目标出现被复现且证据接受）；候选尝试数 =
    候选重放三类计数之和；提前偏离次数 = upstream_prefix_interference
    失败类；恢复耗时 = local_constraint_recovery elapsed_seconds。
    成功率口径：分母=全部候选尝试（含失败），见 generation.note。
    """
    def _int(value: object) -> int:
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            return 0

    def _float(value: object) -> float:
        try:
            return float(value or 0.0)
        except (TypeError, ValueError):
            return 0.0

    original_target_reached = 0
    candidate_attempts = 0
    early_deviations = 0
    recovery_elapsed = 0.0
    recovery_calls = 0
    candidates_generated = 0
    mode_counts = {"constraint_guided": 0, "generic": 0}
    for phase in (phase_map or {}).values():
        if not isinstance(phase, Mapping):
            continue
        original_target_reached += _int(phase.get("promoted_paths"))
        for key in (
            "candidate_replays",
            "bootstrap_candidate_replays",
            "compound_candidate_replays",
        ):
            candidate_attempts += _int(phase.get(key))
        failures = phase.get("failure_category_counts")
        if isinstance(failures, Mapping):
            early_deviations += _int(failures.get("upstream_prefix_interference"))
        local_recovery = phase.get("local_constraint_recovery")
        if isinstance(local_recovery, Mapping):
            recovery_elapsed += _float(local_recovery.get("elapsed_seconds"))
            recovery_calls += _int(local_recovery.get("calls"))
            candidates_generated += _int(local_recovery.get("hypotheses"))
            for mode in mode_counts:
                mode_counts[mode] += _int(
                    local_recovery.get(f"candidate_generation_mode_{mode}")
                )
    return {
        "original_target_reached_count": original_target_reached,
        "candidate_attempt_count": candidate_attempts,
        "early_deviation_count": early_deviations,
        "recovery_elapsed_seconds": round(recovery_elapsed, 3),
        "generation": {
            "note": "denominator includes failed attempts",
            "candidates_generated": candidates_generated,
            "recovery_calls": recovery_calls,
            "mode_counts": mode_counts,
        },
    }


@dataclass
class HistoricalRunner(TempEmulatorLifecycleMixin):
    firmware_path: str | Path
    max_snapshots: int = 5
    use_llm: bool = False
    constraint_file: Optional[str] = None
    llm_config: Optional[Dict[str, object]] = None
    llm_config_path: Optional[str | Path] = None
    entry_point_override: Optional[int] = None
    load_base_override: Optional[int] = None
    raw_static_mode: str = "auto"
    replay_time_skip_mode: str = "stateful"
    replay_time_increment: int = 1000
    semantic_obligation_enabled: bool = True
    scoped_replay_enabled: bool = True
    causal_constraint_recovery_enabled: bool = True
    # r42：候选生成消融臂——False 时 LocalConstraintRecovery 走固定通用
    # 策略（generic_candidate_values），不再构造/求解符号问题；出现身份、
    # 恢复宽度、重放验证链路全部保留。
    constraint_guided_candidates_enabled: bool = True
    firmware_input_provenance: Optional[Dict[str, object]] = None
    execution_thumb_override: Optional[bool] = None
    prepared: PreparedFirmware = field(init=False)
    emulator: IntelligentEmulator = field(init=False)
    mmio_handler: EnhancedMMIOHandler = field(init=False)
    llm_guide: LLMGuide = field(init=False)
    register_tracer: RegisterTracer = field(init=False)
    phase_coverage: Dict[str, Set[int]] = field(default_factory=dict, init=False)
    phase_metadata: Dict[str, Dict[str, object]] = field(default_factory=dict, init=False)
    # ``phase_coverage``/``phase_metadata`` are retained as latest-value
    # compatibility maps.  These histories are the canonical source for
    # repeated stage invocations and per-execution evidence.
    phase_metadata_history: Dict[str, List[Dict[str, object]]] = field(
        default_factory=dict,
        init=False,
    )
    phase_execution_records: List[Dict[str, object]] = field(
        default_factory=list,
        init=False,
    )
    execution_evidence_validated_bbs: Set[int] = field(
        default_factory=set,
        init=False,
    )
    execution_evidence_diagnostic_bbs: Set[int] = field(
        default_factory=set,
        init=False,
    )
    execution_evidence_unclassified_bbs: Set[int] = field(
        default_factory=set,
        init=False,
    )
    # Per-BB ownership counts make late evidence invalidation reversible
    # without retaining a second full copy of every execution record.  The
    # public sets above remain compatibility/reporting fields; these maps are
