    def _ensure_scheduler_components(self) -> None:
        """Create components lazily for legacy ``__new__`` test doubles."""
        if not isinstance(getattr(self, "obligation_discovery", None), ObligationDiscovery):
            self.obligation_discovery = ObligationDiscovery(self)
        if not isinstance(getattr(self, "queue_policy", None), QueuePolicy):
            self.queue_policy = QueuePolicy(self)
        if not isinstance(getattr(self, "replay_executor", None), ReplayExecutor):
            self.replay_executor = ReplayExecutor(self)
        if not isinstance(getattr(self, "outcome_feedback", None), OutcomeFeedback):
            self.outcome_feedback = OutcomeFeedback(self)
        context_recovery = getattr(self, "context_recovery", None)
        if (
            not isinstance(context_recovery, ContextRecovery)
            or context_recovery.runner is not self
        ):
            self.context_recovery = ContextRecovery(self)

    def _scheduler_component(self, name: str, expected_type):
        """Fast component access with lazy support for legacy test doubles."""
        component = getattr(self, name, None)
        if not isinstance(component, expected_type):
            self._ensure_scheduler_components()
            component = getattr(self, name)
        return component

    def scheduler_component_summary(self) -> Dict[str, object]:
        """Describe the active scheduler boundaries for reports and audits."""
        self._ensure_scheduler_components()
        return {
            "schema": "lsgemu.scheduler_components.v1",
            "compatibility_facade": "HistoricalRunner",
            "stage_order_owner": "interleaved_pipeline",
            "coverage_oracle_owner": "HistoricalRunner.validate_coverage/_record_coverage_evidence",
            "components": [
                {
                    "name": "obligation_discovery",
                    "responsibility": "semantic gating, classification, and target discovery",
                    "executes_replay": False,
                    "awards_coverage": False,
                },
                {
                    "name": "queue_policy",
                    "responsibility": "deterministic ordering, queue selection, and budget arithmetic",
                    "executes_replay": False,
                    "awards_coverage": False,
                    "queue_sizes": self.queue_policy.queue_sizes(),
                },
                {
                    "name": "replay_executor",
                    "responsibility": "stage lifecycle, resource cleanup, and replay-kernel invocation",
                    "executes_replay": True,
                    "awards_coverage": False,
                    "runtime_bound": bool(self.replay_executor.runtime is not None),
                    "active_stage_depth": self.replay_executor.active_stage_depth,
                    "active_stage_names": self.replay_executor.active_stage_names(),
                },
                {
                    "name": "outcome_feedback",
                    "responsibility": "valid-BB phase accounting, evidence aggregation, and scheduler feedback",
                    "executes_replay": False,
                    "awards_coverage": "through_existing_oracle_only",
                },
                {
                    "name": "context_recovery",
                    "responsibility": "validated ISR, stream, and RTOS-thread context entry",
                    "executes_replay": "through_existing_context_kernels_under_executor_lifecycle",
                    "awards_coverage": False,
                },
            ],
            "invariants": {
                "stage_order_unchanged": True,
                "budget_callbacks_preserved": True,
                "candidate_kernels_preserved": True,
                "coverage_oracle_preserved": True,
            },
        }

    def _runner_state_lock(self):
        """Return the state lock, including for legacy ``__new__`` test doubles."""
        lock = getattr(self, "_state_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._state_lock = lock
        return lock

    def _validated_firmware_input_provenance(self) -> Dict[str, object]:
        """Bind caller-supplied source metadata to the prepared analysis file."""
        analysis_path = Path(self.prepared.firmware_path).resolve()
        analysis_sha256 = str(getattr(self.prepared, "firmware_sha256", "") or "")
        analysis_size = int(analysis_path.stat().st_size)
        supplied = self.firmware_input_provenance
        if supplied is None:
            try:
                with analysis_path.open("rb") as handle:
                    is_elf = handle.read(4) == b"\x7fELF"
            except OSError:
                is_elf = False
            record = {
                "path": str(analysis_path),
                "size": analysis_size,
                "sha256": analysis_sha256,
            }
            return {
                "schema": INPUT_PROVENANCE_SCHEMA,
                "source_kind": "elf" if is_elf else "legacy_raw_bin",
                "adapter": "none",
                "transformed": False,
                "source": dict(record),
                "analysis": dict(record),
            }
        try:
            provenance = json.loads(json.dumps(supplied, ensure_ascii=True))
        except (TypeError, ValueError, RecursionError) as exc:
            raise ValueError(f"firmware input provenance must be JSON-serializable: {exc}") from exc
        if not isinstance(provenance, dict):
            raise ValueError("firmware input provenance must be a JSON object")
        if str(provenance.get("schema") or "") != INPUT_PROVENANCE_SCHEMA:
            raise ValueError(
                "unsupported firmware input provenance schema: "
                f"{provenance.get('schema')!r}"
            )
        source = provenance.get("source")
        analysis = provenance.get("analysis")
        if not isinstance(source, dict) or not isinstance(analysis, dict):
            raise ValueError("firmware input provenance requires source and analysis objects")
        try:
            recorded_analysis_path = Path(str(analysis["path"])).expanduser().resolve()
        except (KeyError, OSError, ValueError) as exc:
            raise ValueError("firmware input provenance has an invalid analysis path") from exc
        if recorded_analysis_path != analysis_path:
            raise ValueError(
                "firmware input provenance does not describe the prepared file: "
                f"{recorded_analysis_path} != {analysis_path}"
            )
        recorded_analysis_sha = str(analysis.get("sha256") or "")
        if recorded_analysis_sha != analysis_sha256:
            raise ValueError(
                "firmware input provenance analysis SHA-256 does not match the prepared file"
            )
        if int(analysis.get("size", -1)) != analysis_size:
            raise ValueError("firmware input provenance analysis size does not match the prepared file")

        source_path_text = str(source.get("path") or "")
        source_sha256 = str(source.get("sha256") or "")
        if not source_path_text or not source_sha256:
            raise ValueError("firmware input provenance source identity is incomplete")
        source_path = Path(source_path_text).expanduser().resolve()
        if bool(provenance.get("transformed")):
            if not source_path.is_file():
                raise ValueError(f"firmware input provenance source file is missing: {source_path}")
            if int(source.get("size", -1)) != int(source_path.stat().st_size):
                raise ValueError("firmware input provenance source size does not match the raw input")
            if sha256_file(source_path) != source_sha256:
                raise ValueError("firmware input provenance source SHA-256 does not match the raw input")
        else:
            if source_path != analysis_path:
                raise ValueError(
                    "untransformed firmware provenance requires identical source and analysis paths"
                )
            if source_sha256 != analysis_sha256:
                raise ValueError(
                    "untransformed firmware provenance requires identical source and analysis SHA-256"
                )
            if int(source.get("size", -1)) != analysis_size:
                raise ValueError(
                    "untransformed firmware provenance requires identical source and analysis sizes"
                )
        source["path"] = str(source_path)
        analysis["path"] = str(analysis_path)
        provenance["source"] = source
        provenance["analysis"] = analysis
        return provenance

    def __post_init__(self):
        self._ensure_scheduler_components()
        # r42：CLI 关闭（constraint_guided_candidates_enabled=False）与等价
        # 环境开关（LSGEMU_DISABLE_CONSTRAINT_GUIDED_CANDIDATES=1）取并集，
        # 供下方两处 LocalConstraintRecovery 构造共用。
        if _env_flag("LSGEMU_DISABLE_CONSTRAINT_GUIDED_CANDIDATES"):
            self.constraint_guided_candidates_enabled = False
        if not self.scoped_replay_enabled:
            # The scoped-replay ablation keeps only per-task, address-global
            # MMIO fallback values. Learned PC/occurrence-scoped constraints
            # must not leak back in through the shared constraint file.
            self.runtime_branch_mmio_file_mode = "unscoped-global"
        transformed_input = bool(
            (self.firmware_input_provenance or {}).get("transformed")
        )
        self.prepared = PreparedFirmware.from_firmware(
            self.firmware_path,
            use_ghidra=True,
            entry_point_override=self.entry_point_override,
            load_base_override=self.load_base_override,
            raw_static_mode=self.raw_static_mode,
            execution_thumb_override=self.execution_thumb_override,
            resolve_valid_bb_metadata=not transformed_input,
        )
        self.firmware_input_provenance = self._validated_firmware_input_provenance()
        if self.load_base_override is not None:
            self.prepared.raw_load_base = int(self.load_base_override) & 0xFFFFFFFF
        if self.entry_point_override is not None:
            entry = int(self.entry_point_override) & ~1
            self.prepared.result.arch_info.entry_point = entry
            if self.load_base_override is not None:
                self.prepared.raw_load_base = int(self.load_base_override) & 0xFFFFFFFF
            should_rebuild = (
                str(self.raw_static_mode or "auto").lower() in {"auto", "arm", "thumb"}
                and entry not in self.prepared.instruction_lookup
                and not self._firmware_is_elf()
            )
            if should_rebuild:
                thumb = str(self.raw_static_mode or "auto").lower() == "thumb" or bool(int(self.entry_point_override) & 1)
                rebuilt = self.prepared.rebuild_raw_arm_static_view(
                    entry,
                    thumb=thumb,
                    load_base=self.load_base_override,
                )
                if rebuilt:
                    print(f"      raw静态视图: Capstone {'Thumb' if thumb else 'ARM'} 重建 {rebuilt} BBs")
        if self.llm_config_path is None:
            default_config = configured_path("LSGEMU_LLM_CONFIG", PROJECT_ROOT / "LLM.yaml")
            if default_config.exists():
                self.llm_config_path = default_config
        self._write_static_constraints()
        self.emulator = self.prepared.new_emulator(
            max_snapshots=self.max_snapshots,
            llm_config_path=self._effective_llm_config_path(),
            constraint_json_path=self.constraint_file,
            branch_mmio_file_mode=self.baseline_branch_mmio_file_mode,
        )
        self._configure_emulator_feedback(self.emulator)
        self.mmio_handler = EnhancedMMIOHandler(
            self.emulator.uc,
            self.constraint_file,
            branch_mmio_file_mode=self.baseline_branch_mmio_file_mode,
        )
        self.llm_guide = LLMGuide(
            self.prepared.static_bbs,
            use_llm=self.use_llm,
            llm_config=self.llm_config,
            instruction_lookup=self.prepared.instruction_lookup,
            compare_lookup=self.prepared.compare_lookup,
        )
        # 「符号求解失败 → 大模型求解切片」升级链的上层实现：包装 LLMGuide，
        # 注入 RegisterTracer；z3/校验和枚举均失败后按调用触发，结果仍走
        # 与 z3 相同的无强制重放验证。
        self.llm_slice_solver = LLMGuideSliceSolver(self.llm_guide)
        # 二级定位（设计 §4.2）：表达式图无该分支记录时的差分扰动探测；
        # 候选来自运行时 MMIO 访问历史 + 静态地址清单，重放 oracle 复用
        # 快照重放原语，全程有界（次数/超时），结果同走 hypothesis 通道。
        self.differential_probe_solver = DifferentialProbeSolver(self)
        self.local_constraint_recovery = LocalConstraintRecovery(
            self.prepared.static_bbs,
            instruction_to_bb=self.prepared.instruction_to_bb,
            compare_lookup=self.prepared.compare_lookup,
            producer_index=getattr(self.prepared, "producer_index", None),
            solver_timeout_ms=_env_int("LSGEMU_LOCAL_SOLVER_TIMEOUT_MS", 40),
            generic_candidates=not self.constraint_guided_candidates_enabled,
        )
        self.register_tracer = RegisterTracer(
            self.emulator.uc,
            self.prepared.static_bbs,
            instruction_lookup=self.prepared.instruction_lookup,
            compare_lookup=self.prepared.compare_lookup,
            external_memory_input_predicate=(
                self.emulator._is_external_input_memory_range
            ),
            external_input_event_source=self.emulator,
            dynamic_graph_enabled=self._causal_constraint_recovery_available(),
            dynamic_llm_fallback=self.llm_slice_solver,
            differential_probe_fallback=self.differential_probe_solver,
            producer_index=getattr(self.prepared, "producer_index", None),
        )
        self.run_profile = collect_run_profile(
            firmware_path=str(self.firmware_path),
            cli_args={
                "max_snapshots": self.max_snapshots,
                "use_llm": self.use_llm,
                "llm_guide_client_available": bool(
                    getattr(self.llm_guide, "use_llm", False)
                    and getattr(self.llm_guide, "llm_client", None) is not None
                ),
                "llm_code_analyzer_client_available": bool(
                    getattr(getattr(self.emulator, "code_analyzer", None), "client", None)
                ),
                "llm_deadlock_solver_available": bool(
                    getattr(self.emulator, "deadlock_solver", None) is not None
                ),
                "raw_static_mode": self.raw_static_mode,
                "replay_time_skip_mode": self.replay_time_skip_mode,
                "replay_time_increment": self.replay_time_increment,
                "semantic_obligation_enabled": self.semantic_obligation_enabled,
                "scoped_replay_enabled": self.scoped_replay_enabled,
                "causal_constraint_recovery_enabled": self.causal_constraint_recovery_enabled,
                "constraint_guided_candidates_enabled": self.constraint_guided_candidates_enabled,
                "entry_point_override": self.entry_point_override,
                "load_base_override": self.load_base_override,
                "execution_thumb_override": self.execution_thumb_override,
                "firmware_input_schema": str(
                    (self.firmware_input_provenance or {}).get("schema") or ""
                ),
                "firmware_input_transformed": bool(
                    (self.firmware_input_provenance or {}).get("transformed")
                ),
                "valid_bb_metadata_auto_match": not transformed_input,
            },
            extra={
                "toolchain_fingerprint": dict(
                    getattr(self.prepared, "toolchain_fingerprint", {}) or {}
                ),
                "static_cache_identity": dict(
                    getattr(self.prepared, "static_cache_identity", {}) or {}
                ),
                "firmware_input_identity": {
                    "schema": str(
                        (self.firmware_input_provenance or {}).get("schema") or ""
                    ),
                    "source_sha256": str(
                        (
                            (self.firmware_input_provenance or {}).get("source")
                            or {}
                        ).get("sha256")
                        or ""
                    ),
                    "analysis_sha256": str(
                        (
                            (self.firmware_input_provenance or {}).get("analysis")
                            or {}
                        ).get("sha256")
                        or ""
                    ),
                    "conversion_identity": str(
                        (
                            (self.firmware_input_provenance or {}).get("conversion")
                            or {}
                        ).get("identity_hash")
                        or ""
                    ),
                    "execution_mode": str(
                        (self.firmware_input_provenance or {}).get("execution_mode")
                        or "auto"
                    ),
                },
            },
        )

    def _scoped_replay_available(self) -> bool:
        return bool(getattr(self, "scoped_replay_enabled", True))

    def _causal_constraint_recovery_available(self) -> bool:
        return bool(
            getattr(self, "causal_constraint_recovery_enabled", True)
        )

    def _firmware_is_elf(self) -> bool:
        try:
            with open(self.firmware_path, "rb") as f:
                return f.read(4) == b"\x7fELF"
        except Exception:
            return False

    def _write_static_constraints(self) -> int:
        """Persist conservative static MMIO constraints before emulation starts."""
        if not self.constraint_file:
            return 0
        try:
            Path(self.constraint_file).parent.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        analyzer = StaticConstraintAnalyzer(self.prepared.static_bbs)
        return analyzer.write_constraints(self.constraint_file)

    def _effective_llm_config_path(self) -> Optional[str | Path]:
        return self.llm_config_path if self.use_llm else None

    def _configure_emulator_feedback(self, emulator: IntelligentEmulator):
        discovery = self._scheduler_component(
            "obligation_discovery", ObligationDiscovery
        )
        discovery.configure_emulator_feedback(emulator)

    def _restore_branch_snapshot(
        self,
        emulator: IntelligentEmulator,
        snapshot: object,
        *,
        lineage_source: object = None,
    ) -> bool:
        """Restore a branch snapshot and preserve runtime-written page provenance.

        Snapshot memory restoration brings back the bytes, but the emulator also
        needs the page-level write provenance before it can safely decode SRAM
        code as a real dynamic basic block.
        """
        def finish(success: bool, errors: Iterable[object] = ()) -> bool:
            normalized_errors = tuple(
                dict.fromkeys(
                    str(error)[:500]
                    for error in errors
                    if str(error)
                )
            )
            payload = {
                "success": bool(success) and not normalized_errors,
                "errors": list(normalized_errors),
                "snapshot_address": int(
                    getattr(snapshot, "address", 0) or 0
                )
                & 0xFFFFFFFF,
            }
            if not payload["success"]:
                # Memory/external-state restoration is not guaranteed to be
                # transactional at the Unicorn boundary.  Prevent a caller
                # from accidentally executing or restoring another path on a
                # mixed-state engine.
                try:
                    emulator.replay_state_poisoned = True
                except Exception:
                    pass
            # Keep this status on the temporary emulator rather than the runner:
            # several replay workers may be active over the lifetime of one
            # runner, while a restore status belongs to exactly one engine.
            try:
                emulator.last_snapshot_restore_errors = list(normalized_errors)
                emulator.last_snapshot_restore = dict(payload)
            except Exception:
                # Diagnostics must never turn a valid restore into a failure.
                pass
            return bool(payload["success"])

        manager = getattr(emulator, "branch_snapshot_manager", None)
        uc = getattr(emulator, "uc", None)
        if bool(getattr(emulator, "replay_state_poisoned", False)):
            return finish(False, ("emulator_replay_state_poisoned",))
        if manager is None or uc is None or snapshot is None:
            return finish(
                False,
                ("snapshot_restore_prerequisite_missing",),
            )

        try:
            restored = bool(manager.restore_snapshot(uc, snapshot))
        except Exception as exc:
            logger.warning(
                "分支快照恢复异常 @ 0x%08x: %s",
                int(getattr(snapshot, "address", 0) or 0) & 0xFFFFFFFF,
                exc,
            )
            return finish(
                False,
                (f"snapshot_restore_exception:{type(exc).__name__}",),
            )
        if not restored:
            return finish(False, ("snapshot_restore_returned_false",))

        errors = []
        restore_external = getattr(emulator, "restore_snapshot_external_state", None)
        if callable(restore_external):
            try:
                if restore_external(snapshot) is False:
                    errors.append("external_state_restore_returned_false")
            except Exception as exc:
                errors.append(f"external_state_restore_exception:{type(exc).__name__}")

        if not errors and lineage_source is not None and lineage_source is not snapshot:
            lineage_setter = getattr(
                emulator,
                "_set_active_prefix_provenance",
                None,
            )
            if callable(lineage_setter):
                try:
                    lineage_setter(lineage_source)
                except Exception as exc:
                    errors.append(
                        f"prefix_provenance_restore_exception:{type(exc).__name__}"
                    )

        # Runtime-written pages are part of the executable-state contract.  If
        # a snapshot says that such pages exist, silently dropping their
        # provenance could make a later SRAM target look like a valid static
        # instruction.  Empty dirty-page sets remain compatible with old test
        # doubles that do not expose the optional bookkeeping attribute.
        dirty_pages = getattr(snapshot, "dirty_pages", set()) or set()
        runtime_pages = getattr(emulator, "runtime_written_pages", None)
        if runtime_pages is None and dirty_pages:
            errors.append("runtime_written_page_provenance_unavailable")
        elif runtime_pages is not None:
            try:
                runtime_pages.update(
                    int(page) & ~0xFFF for page in dirty_pages
                )
            except Exception as exc:
                errors.append(
                    f"runtime_written_page_provenance_restore_failed:{type(exc).__name__}"
                )

        if errors:
            logger.warning(
                "拒绝使用不完整的分支快照 @ 0x%08x: %s",
                int(getattr(snapshot, "address", 0) or 0) & 0xFFFFFFFF,
                ", ".join(errors),
            )
            return finish(False, errors)
        return finish(True)

    def _is_safe_replay_pc(self, emulator: IntelligentEmulator, address: int, snapshot: object = None) -> bool:
        """Allow continuation only if the PC is executable or recovered from runtime-written provenance."""
        target = int(address) & ~1
        if target <= 1:
            return False
        if emulator._is_executable_address(target):
            return True
        dirty_pages = set()
        if snapshot is not None:
            try:
                dirty_pages = {int(page) & ~0xFFF for page in (getattr(snapshot, "dirty_pages", set()) or set())}
            except Exception:
                dirty_pages = set()
        runtime_pages = set(getattr(emulator, "runtime_written_pages", set()) or set())
        if (target & ~0xFFF) in runtime_pages or (target & ~0xFFF) in dirty_pages:
            return True
        return False

    def _configure_replay_skip_function_returns(
        self,
        emulator: IntelligentEmulator,
        *,
        include_time: bool = True,
        time_increment: int = 1000,
        exclude_addresses: Optional[Set[int]] = None,
        exclude_stream_input_summaries: bool = False,
    ) -> None:
        mode = str(
            os.environ.get("LSGEMU_REPLAY_TIME_SKIP_MODE")
            or self.replay_time_skip_mode
            or "stateful"
        ).strip().lower()
        effective_include_time = bool(include_time) and mode not in {
            "0",
            "false",
            "no",
            "off",
            "none",
            "legacy",
            "legacy-time",
            "legacy_time",
        }
        try:
            configured_increment = int(
                os.environ.get("LSGEMU_REPLAY_TIME_INCREMENT")
                or self.replay_time_increment
                or time_increment
            )
        except (TypeError, ValueError):
            configured_increment = int(time_increment)
        excluded = {int(address) & ~1 for address in (exclude_addresses or set())}
        if exclude_stream_input_summaries:
            for address, symbol in getattr(self.prepared, "symbols_by_addr", {}).items():
                try:
                    if IntelligentEmulator._stream_input_summary_for_symbol(symbol) is not None:
                        excluded.add(int(address) & ~1)
                except Exception:
                    continue

        try:
            emulator.configure_skip_function_returns(
                getattr(self.prepared, "symbols_by_addr", {}),
                enabled=True,
                include_time=effective_include_time,
                time_increment=max(1, int(configured_increment)),
                exclude_addresses=excluded,
            )
        except TypeError:
            emulator.configure_skip_function_returns(
                getattr(self.prepared, "symbols_by_addr", {}),
                enabled=True,
            )
        except Exception:
            pass

    def _stream_context_state_key(self, profile: StreamInputProfile, context: object) -> Tuple[object, ...]:
        """Identify a stream replay context by both API/profile and captured state variant."""
        snapshot = self._interrupt_context_snapshot(context)
        if snapshot is None:
            snapshot = context
        origin = "snapshot"
        context_evidence = EVIDENCE_E0
        prefix_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple()
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple()
        if isinstance(context, PrefixReplaySnapshot):
            origin = str(getattr(context, "origin", "snapshot-entry") or "snapshot-entry")
            context_evidence = self._snapshot_entry_evidence_class(context)
            prefix_signature = tuple(getattr(context, "prefix_signature", tuple()) or tuple())
            source_path_signature = tuple(getattr(context, "source_path_signature", tuple()) or tuple())
        elif isinstance(context, dict):
            origin = str(context.get("origin", "dict-snapshot") or "dict-snapshot")
            prefix_signature = tuple(context.get("prefix_signature", tuple()) or tuple())
            source_path_signature = tuple(context.get("source_path_signature", tuple()) or tuple())
            context_evidence = self._capture_evidence_class(
                source_path_signature,
                context.get("evidence_class"),
            )
        return (
            str(profile.profile_kind),
            str(profile.object_symbol),
            origin,
            context_evidence,
            int(getattr(snapshot, "address", 0) or 0) & ~1,
            int(getattr(snapshot, "occurrence_index", 1) or 1),
            int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
            int(getattr(context, "branch_depth", getattr(snapshot, "depth", 0)) or 0),
            prefix_signature,
            source_path_signature,
        )

    def _stream_context_key_record(
        self,
        key: Tuple[object, ...],
        count: int,
    ) -> Dict[str, object]:
        """Serialize current and legacy stream-context cache keys safely."""

        def key_int(index: int, default: Optional[int] = None) -> Optional[int]:
            if index >= len(key):
                return default
            try:
                return int(key[index])
            except (TypeError, ValueError):
                return default

        evidence_class: Optional[str] = None
        if (
            len(key) >= 10
            and str(key[3])
            in {EVIDENCE_E0, EVIDENCE_E1, EVIDENCE_E2, EVIDENCE_E3}
        ):
            origin = str(key[2])
            evidence_class = str(key[3])
            context_index, occurrence_index, capture_index, depth_index = 4, 5, 6, 7
        elif len(key) >= 9 and isinstance(key[2], str):
            origin = str(key[2])
            context_index, occurrence_index, capture_index, depth_index = 3, 4, 5, 6
        else:
            origin = "legacy"
            context_index, occurrence_index, capture_index, depth_index = 2, 3, 4, 5

        context_bb = key_int(context_index, 0) or 0
        return {
            "profile_kind": key[0] if len(key) > 0 else None,
            "object_symbol": key[1] if len(key) > 1 else None,
            "origin": origin,
            "evidence_class": evidence_class,
            "context_bb": f"0x{context_bb & 0xFFFFFFFF:08x}",
            "occurrence_index": key_int(occurrence_index),
            "capture_order": key_int(capture_index),
            "depth": key_int(depth_index),
            "zero_new_count": int(count),
            "persistent_zero_new_count": int(
                self.stream_context_zero_new_counts.get(key, 0) or 0
            ),
        }

    def _harvest_emulator_feedback(self, emulator: IntelligentEmulator) -> bool:
        feedback = self._scheduler_component("outcome_feedback", OutcomeFeedback)
        return feedback.harvest_emulator_feedback(emulator)

    @property
    def result(self):
        return self.prepared.result

    @property
    def static_bbs(self):
        return self.prepared.static_bbs

    @property
    def static_bb_set(self):
        return self.prepared.static_bb_set

    def validate_coverage(self, covered_bbs: Iterable[int]) -> Set[int]:
        return {bb for bb in covered_bbs if bb in self.prepared.static_bb_set}

    @contextmanager
    def capture_execution_trace(self, emulator: IntelligentEmulator):
        trace = ExecutionTrace(
            history_limit=max(
                512,
                _env_int("LSGEMU_EXECUTION_TRACE_HISTORY_LIMIT", 8192),
            )
        )

        def is_skipped_entry(bb_addr: int) -> bool:
            return int(bb_addr) in (getattr(emulator, "skipped_function_entry_bbs", set()) or set())

        def code_hook(uc, address, size, user_data):
            bb_addr = self.prepared.resolve_basic_block(address)
            if bb_addr is not None and not is_skipped_entry(bb_addr):
                trace.covered_bbs.add(bb_addr)
                trace.record_basic_block(bb_addr)

        hook = emulator._add_owned_hook(UC_HOOK_CODE, code_hook)
        try:
            yield trace
        finally:
            cleanup_errors: List[str] = []

            def remember(operation: str, error: BaseException) -> None:
                text = f"{operation}:{type(error).__name__}:{str(error)[:512]}"
                if text not in cleanup_errors:
                    cleanup_errors.append(text)

            try:
                stop_reason = str(
                    getattr(emulator, "last_run_result", {}).get("stop_reason")
                    or getattr(emulator, "stop_requested_reason", "")
                    or ""
                )
            except Exception as exc:
                stop_reason = ""
                remember("trace_stop_reason", exc)
            if stop_reason != "unproven_dynamic_code_target":
                try:
                    discovered = self.prepared.absorb_runtime_basic_blocks(emulator)
                    if discovered:
                        print(f"      运行时补齐静态BB: {discovered}")
                except Exception as exc:
                    remember("trace_dynamic_bb_absorb", exc)
            # UC_HOOK_BLOCK runs before UC_HOOK_CODE. Some terminal/sink blocks
            # intentionally stop emulation from the block hook, so the code hook
            # never observes their first instruction even though the BB was
            # genuinely reached from the current entry-derived state.
            try:
                for bb_addr in getattr(emulator, "bb_addr_set", set()) or set():
                    resolved = self.prepared.resolve_basic_block(int(bb_addr))
                    if resolved is not None and not is_skipped_entry(resolved):
                        trace.covered_bbs.add(resolved)
            except Exception as exc:
                remember("trace_bb_collection", exc)
            try:
                emulator_edges = set(
                    getattr(emulator, "runtime_successor_edges", set()) or set()
                )
                filtered_edges: Set[Tuple[int, int]] = set()
                for source, target in emulator_edges:
                    source_bb = self.prepared.resolve_basic_block(int(source))
                    target_bb = self.prepared.resolve_basic_block(int(target))
                    if (
                        source_bb is not None
                        and target_bb is not None
                        and not is_skipped_entry(source_bb)
                        and not is_skipped_entry(target_bb)
                    ):
                        filtered_edges.add((source_bb, target_bb))
                trace.merge_successor_edges(filtered_edges)
            except Exception as exc:
                remember("trace_successor_collection", exc)
            try:
                emulator._remove_owned_hook(hook)
            except Exception as exc:
                remember("trace_hook_remove", exc)
            if cleanup_errors:
                try:
                    existing = list(
                        getattr(emulator, "_lsgemu_trace_cleanup_errors", []) or []
                    )
                    emulator._lsgemu_trace_cleanup_errors = list(
                        dict.fromkeys(existing + cleanup_errors)
                    )
                except Exception:
                    pass

    @contextmanager
    def capture_coverage(self, emulator: IntelligentEmulator):
        with self.capture_execution_trace(emulator) as trace:
            yield trace.covered_bbs

    @contextmanager
    def guided_modules(
        self,
        mmio_handler: EnhancedMMIOHandler,
        register_tracer: Optional[RegisterTracer] = None,
        *,
        hook_mmio: bool = True,
    ):
        if hook_mmio:
            mmio_handler.start_hooking()
        if register_tracer:
            register_tracer.start_tracing()
        try:
            yield
        finally:
            cleanup_errors: List[str] = []

            def remember(operation: str, error: BaseException) -> None:
                text = f"{operation}:{type(error).__name__}:{str(error)[:512]}"
                if text not in cleanup_errors:
                    cleanup_errors.append(text)

            if register_tracer:
                try:
                    register_tracer.stop_tracing()
                except Exception as exc:
                    remember("register_tracer_stop", exc)
            if hook_mmio:
                try:
                    mmio_handler.stop_hooking()
                except Exception as exc:
                    remember("mmio_stop_hooking", exc)
            if cleanup_errors:
                for owner in (mmio_handler, register_tracer):
                    if owner is None:
                        continue
                    try:
                        existing = list(
                            getattr(owner, "_lsgemu_guided_cleanup_errors", [])
                            or []
                        )
                        owner._lsgemu_guided_cleanup_errors = list(
                            dict.fromkeys(existing + cleanup_errors)
                        )
                    except Exception:
                        pass

    def _record_phase(
        self,
        name: str,
        covered: Iterable[int],
        *,
        count_coverage: bool = True,
        **metadata,
    ) -> Set[int]:
        # Every replay phase owns the temporary engines it creates.  Most
        # callsites also dispose them locally, while this backstop covers an
        # exception during setup (MMIO/tracer construction or snapshot
        # restoration) before a local ``finally`` could be installed.  It is
        # resource cleanup only; it does not alter the phase's candidate set,
        # ordering, budget, or coverage oracle.
        try:
            cleaned = self._dispose_active_temp_emulators(
                stage_name=str(name or "unknown"),
                reason="phase_end",
            )
            if cleaned:
                metadata.setdefault("active_temp_emulators_cleaned", int(cleaned))
        except Exception as exc:
            metadata.setdefault("active_temp_emulator_cleanup_error", str(exc))
        feedback = self._scheduler_component("outcome_feedback", OutcomeFeedback)
        return feedback.record_phase(
            name,
            covered,
            count_coverage=count_coverage,
            **metadata,
        )

    def _invalidate_temp_emulator_snapshot_provenance(
        self,
        emulator: Optional[IntelligentEmulator],
        *,
        evidence_record: Optional[Dict[str, object]] = None,
        run_result: Optional[Dict[str, object]] = None,
        execution_baseline: Optional[Mapping[str, object]] = None,
        reason: str = "replay_cleanup_exception",
        error: Optional[BaseException | str] = None,
    ) -> Dict[str, object]:
        """Invalidate snapshots owned by a failed replay execution.

        Cleanup can finish after a direct child record or a prefix wrapper has
        already been materialized.  The native observations remain useful for
        diagnostics, but the corresponding source snapshots must no longer be
        eligible to establish a strict witness.  This helper is deliberately
        fail-safe: a missing id/manager is recorded on the affected record and
        never causes cleanup to raise or fall back to an unrelated execution.
        """
        result: Dict[str, object] = {
            "execution_id": "",
            "invalidated_snapshots": 0,
            "error": "",
        }

        def read_id(source: object) -> str:
            if isinstance(source, Mapping):
                return str(
                    source.get("execution_id")
                    or source.get("source_execution_id")
                    or ""
                )
            return str(
                getattr(source, "execution_id", None)
                or getattr(source, "source_execution_id", "")
                or ""
            )

        def read_bool(source: object, key: str) -> bool:
            if isinstance(source, Mapping):
                return coerce_bool(source.get(key), False)
            return coerce_bool(getattr(source, key, False), False)

        # A compact child record may use a logical task id (for example
        # ``stream_input_replay-attempt-3``), while snapshots captured by the
        # emulator are owned by a concrete id (``emu-...``).  A canonical
        # evidence id is usable only when the attempt is marked as started and
        # the manager confirms the exact owner; otherwise it remains a report
        # field and cannot drive invalidation.
        direct_baseline = (
            getattr(emulator, "_direct_execution_baseline", None)
            if emulator is not None
            else None
        )
        explicit_baseline_id = read_id(execution_baseline)
        direct_baseline_id = read_id(direct_baseline)
        emulator_id = read_id(emulator)
        run_result_id = read_id(run_result)
        evidence_id = read_id(evidence_record)
        execution_is_active = (
            emulator is not None
            and read_bool(emulator, "_execution_active")
        )
        execution_started = any(
            read_bool(source, "execution_started")
            for source in (run_result, evidence_record)
        )
        execution_attempted = any(
            read_bool(source, "execution_attempted")
            for source in (run_result, evidence_record)
        )
        has_current_boundary = bool(
            explicit_baseline_id
            or execution_is_active
            or execution_started
            or (execution_attempted and run_result_id)
        )

        # Keep the source label alongside each id.  A result record can carry
        # a logical task id, while a direct baseline and the emulator carry the
        # concrete id used by BranchSnapshotManager.  The source label makes
        # the precedence auditable and prevents an old emulator id from
        # silently replacing a current run id.
        trusted_candidates: List[Tuple[str, str]] = []

        def add_candidate(source: str, value: str) -> None:
            normalized = str(value or "").strip()
            if not normalized:
                return
            if any(candidate == normalized for _source, candidate in trusted_candidates):
                return
            trusted_candidates.append((str(source), normalized))

        if explicit_baseline_id:
            add_candidate("execution_baseline", explicit_baseline_id)
        # ``run_result`` is produced by the invocation that just attempted to
        # execute.  Prefer it to a potentially stale compatibility attribute
        # on the emulator when both are available.
        if run_result_id and (execution_started or execution_attempted):
            add_candidate("run_result", run_result_id)
        if evidence_id and execution_started:
            add_candidate("evidence_record", evidence_id)
        # Once the invocation returned an execution id, that id is the only
        # result-side identity available for this attempt.  Do not append a
        # stale direct-baseline/emulator id merely because it happens to be
        # present in the manager's historical catalog.
        if has_current_boundary and not run_result_id:
            if direct_baseline_id and (
                not evidence_id or direct_baseline_id == evidence_id
            ):
                add_candidate("direct_execution_baseline", direct_baseline_id)
            if (
                execution_is_active
                and not evidence_id
                and not direct_baseline_id
            ):
                add_candidate("emulator", emulator_id)

        # Prefer a trusted id that is actually present in the snapshot manager.
        # This also handles adapters that update the emulator id at the start
        # of a run but expose an older id in a compatibility result.  Reading
        # the bounded snapshot catalog is cleanup-time bookkeeping and does
        # not alter replay scheduling or coverage.
        manager = None
        if emulator is not None:
            manager = getattr(emulator, "branch_snapshot_manager", None)
            if manager is None:
                manager = getattr(emulator, "snapshot_manager", None)

        def manager_execution_ids(owner: object) -> Tuple[set[str], bool]:
            if owner is None:
                return set(), False
            ids: set[str] = set()

            def add(source: object) -> None:
                value = read_id(source)
                if value:
                    ids.add(value)

            iterator = getattr(owner, "_iter_unique_snapshots", None)
            if callable(iterator):
                try:
                    for snapshot in iterator():
                        add(snapshot)
                    return ids, True
                except Exception:
                    # A legacy manager may not expose a safe iterator.  Fall
                    # through to its public/current containers below.
                    pass
            catalog_known = False
            for container_name in ("snapshots", "snapshot_history"):
                container = getattr(owner, container_name, None)
                if isinstance(container, Mapping):
                    catalog_known = True
                    values = container.values()
                    for value in values:
                        if isinstance(value, (list, tuple, set)):
                            for item in value:
                                add(item)
                        else:
                            add(value)
            return ids, catalog_known

        catalog_ids, catalog_known = manager_execution_ids(manager)
        result["snapshot_catalog_known"] = bool(catalog_known)
        result["snapshot_catalog_execution_count"] = len(catalog_ids)
        execution_id = ""
        selected_source = ""
        selection_error = ""
        if catalog_known and catalog_ids:
            # Once the manager exposes a non-empty catalog, an id that is not
            # present is proof that it belongs to another execution (or that
            # the adapter lost the current snapshot).  Never fall back to an
            # older emulator/evidence id in this case.
            if trusted_candidates:
                for source, candidate in trusted_candidates:
                    if candidate in catalog_ids:
                        selected_source = source
                        execution_id = candidate
                        break
            if not trusted_candidates:
                selection_error = "snapshot_provenance_execution_id_missing"
            elif not execution_id:
                selection_error = "snapshot_provenance_execution_id_unmatched"
        elif trusted_candidates:
            # An empty, known catalog is a valid no-snapshot execution.  An
            # unknown legacy catalog can still be handled when the caller
            # supplied a concrete current id; the manager's invalidator
            # remains exact-match and therefore cannot mutate another id.
            selected_source, execution_id = trusted_candidates[0]
        else:
            selection_error = "snapshot_provenance_execution_id_missing"
        result["execution_id"] = execution_id[:256]

        reason_text = str(reason or "replay_cleanup_exception")[:256]
        error_text = str(error)[:2000] if error not in (None, "") else ""
        result["error"] = selection_error or error_text

        invalidated = 0
        if execution_id and emulator is not None:
            invalidator = getattr(manager, "invalidate_snapshot_provenance", None)
            if callable(invalidator):
                try:
                    invalidated = int(
                        invalidator(
                            execution_id,
                            reason=reason_text,
                            error=error_text,
                        )
                        or 0
                    )
                except Exception as exc:
                    result["error"] = (
                        f"{error_text}; provenance_invalidation:"
                        f"{type(exc).__name__}:{str(exc)[:512]}"
                    )[:2000] if error_text else (
                        f"provenance_invalidation:{type(exc).__name__}:"
                        f"{str(exc)[:512]}"
                    )[:2000]
            else:
                result["error"] = (
                    "snapshot_provenance_manager_unavailable"
                )
        elif not execution_id:
            # Do not guess an id from an older execution.  Mark the current
            # record diagnostic, but leave every unrelated snapshot untouched.
            if not selection_error and not result["error"]:
                result["error"] = "snapshot_provenance_execution_id_missing"
        else:
            result["error"] = "snapshot_provenance_emulator_missing"
        if selected_source:
            result["execution_id_source"] = selected_source
        result["invalidated_snapshots"] = max(0, invalidated)

        def mark(target: Optional[Dict[str, object]]) -> None:
            if not isinstance(target, dict):
                return
            target["provenance_invalidated"] = True
            existing = target.get("provenance_invalidation_reasons", [])
            if isinstance(existing, str):
                existing_values = [existing]
            elif isinstance(existing, (list, tuple, set)):
                existing_values = [str(item) for item in existing if str(item)]
            else:
                existing_values = []
            if reason_text not in existing_values:
                existing_values.append(reason_text)
            target["provenance_invalidation_reasons"] = list(
                dict.fromkeys(existing_values)
            )[:16]
            target["snapshot_provenance_invalidated_snapshots"] = max(
                int(target.get("snapshot_provenance_invalidated_snapshots", 0) or 0),
                invalidated,
            )
            if result["error"]:
                target["provenance_invalidation_error"] = str(
                    result["error"]
                )[:2000]

        mark(evidence_record)
        mark(run_result)
        return result

    def _safe_dispose_temp_emulator(
        self,
        emulator: Optional[IntelligentEmulator],
        *,
        mmio_handler: Optional[EnhancedMMIOHandler] = None,
        register_tracer: Optional[RegisterTracer] = None,
        quarantine: Optional[bool] = None,
        stage_name: Optional[str] = None,
        evidence_record: Optional[Dict[str, object]] = None,
        run_result: Optional[Dict[str, object]] = None,
    ) -> Optional[str]:
        """Dispose one replay engine without escaping its evidence boundary.

        Normal cleanup is intentionally unchanged.  This adapter only handles
        the exceptional case where a test double, hook owner, or native close
        reports an error after the replay has already produced observations.
        The attempt is then downgraded in place, so the observed BBs remain
        diagnostic data and cannot become a strict witness.
        """
        if emulator is None:
            return None
        errors: List[str] = []
        try:
            self._dispose_temp_emulator(
                emulator,
                mmio_handler=mmio_handler,
                register_tracer=register_tracer,
                quarantine=quarantine,
                stage_name=stage_name,
            )
        except Exception as exc:
            errors.append(
                f"dispose:{type(exc).__name__}:{str(exc)[:512]}"
            )

        errors.extend(
            self._collect_temp_emulator_cleanup_errors(
                emulator,
                mmio_handler=mmio_handler,
                register_tracer=register_tracer,
            )
        )

        deduped = list(dict.fromkeys(errors))
        if not deduped:
            return None
        error_text = "; ".join(deduped)[:2000]
        self._invalidate_temp_emulator_snapshot_provenance(
            emulator,
            evidence_record=evidence_record,
            run_result=run_result,
            reason="replay_cleanup_exception",
            error=error_text,
        )
        if evidence_record is not None:
            self._downgrade_execution_evidence_record(
                evidence_record,
                reason="replay_cleanup_exception",
                error=error_text,
            )
        if isinstance(run_result, dict):
            run_result["execution_failed"] = True
            run_result["execution_completed_normally"] = False
            run_result["execution_telemetry_complete"] = False
            run_result["failure_reason"] = "replay_cleanup_exception"
            run_result["cleanup_errors"] = list(deduped)
            previous_error = str(run_result.get("execution_error") or "")
            run_result["execution_error"] = (
                f"{previous_error}; {error_text}"[:2000]
                if previous_error
                else error_text
            )
        logger.debug(
            "temporary replay cleanup failed%s: %s",
            (
                f" for {stage_name}"
                if stage_name
                else ""
            ),
            error_text,
        )
        return error_text

    def _safe_replay_postprocess(
        self,
        operation: str,
        callback,
        *,
        evidence_record: Optional[Dict[str, object]] = None,
        run_result: Optional[Dict[str, object]] = None,
        default=None,
    ):
        """Run non-emulation bookkeeping without escaping a replay child.

        A replay has already produced useful observations by the time branch
        catalogs, scheduler feedback, or debug metadata are collected.  Those
        consumers are deliberately outside the Unicorn execution oracle: a
        failure in one of them must not abort the stage or strand the native
        emulator.  The caller still receives a typed failure through the
        result/record, so the observations remain diagnostic rather than being
        promoted to a strict witness.
        """
        try:
            return callback()
        except Exception as exc:
            operation_name = str(operation or "unknown")
            reason = f"replay_postprocess_exception:{operation_name}"
            error_text = f"{reason}:{type(exc).__name__}:{str(exc)[:512]}"
            if evidence_record is not None:
                try:
                    self._downgrade_execution_evidence_record(
                        evidence_record,
                        reason=reason,
                        error=error_text,
                    )
                except Exception as downgrade_error:
                    # The original post-processing failure is the useful
                    # diagnostic.  Keep a bounded log if a malformed record
                    # prevents in-place downgrade.
                    logger.debug(
                        "replay evidence downgrade failed after %s: %s",
                        reason,
                        downgrade_error,
                    )
            if isinstance(run_result, dict):
                run_result["execution_failed"] = True
                run_result["execution_completed_normally"] = False
                run_result["execution_telemetry_complete"] = False
                previous_reason = str(run_result.get("failure_reason") or "")
                run_result["failure_reason"] = (
                    previous_reason
                    if previous_reason
                    else reason
                )
                failure_reasons = list(
                    run_result.get("execution_failure_reasons", []) or []
                )
                if reason not in failure_reasons:
                    failure_reasons.append(reason)
                run_result["execution_failure_reasons"] = list(
                    dict.fromkeys(str(item) for item in failure_reasons if str(item))
                )
                previous_error = str(run_result.get("execution_error") or "")
                run_result["execution_error"] = (
                    f"{previous_error}; {error_text}"[:2000]
                    if previous_error
                    else error_text
                )
            logger.debug(
                "replay post-processing failed for %s: %s",
                operation_name,
                error_text,
            )
            return default

    def _finalize_temp_replay(
        self,
        emulator: Optional[IntelligentEmulator],
        *,
        mmio_handler: Optional[EnhancedMMIOHandler] = None,
        register_tracer: Optional[RegisterTracer] = None,
        run_result: Optional[Dict[str, object]] = None,
        evidence_record: Optional[Dict[str, object]] = None,
        harvest_feedback: bool = True,
        stage_name: Optional[str] = None,
    ) -> List[str]:
        """Finish replay-side telemetry and cleanup without masking failures."""
        errors: List[str] = []
        if emulator is None:
            return errors
        if harvest_feedback:
            try:
                self._harvest_emulator_feedback(emulator)
            except Exception as exc:
                errors.append(
                    f"harvest:{type(exc).__name__}:{str(exc)[:512]}"
                )
        if register_tracer is not None:
            try:
                self.register_tracer.merge_from(register_tracer)
            except Exception as exc:
                errors.append(
                    f"register_tracer_merge:{type(exc).__name__}:{str(exc)[:512]}"
                )
        cleanup_error = self._safe_dispose_temp_emulator(
            emulator,
            mmio_handler=mmio_handler,
            register_tracer=register_tracer,
            quarantine=None,
            stage_name=stage_name,
            evidence_record=evidence_record,
            run_result=run_result,
        )
        if cleanup_error:
            errors.append(cleanup_error)
        errors = list(dict.fromkeys(str(item) for item in errors if str(item)))
        if errors and isinstance(run_result, dict):
            detail = "; ".join(errors)[:2000]
            run_result["execution_failed"] = True
            run_result["execution_completed_normally"] = False
            run_result["execution_telemetry_complete"] = False
            run_result["failure_reason"] = "replay_cleanup_exception"
            run_result["cleanup_errors"] = list(errors)
            previous_error = str(run_result.get("execution_error") or "")
            run_result["execution_error"] = (
                f"{previous_error}; {detail}"[:2000]
                if previous_error
                else detail
            )
        if errors and isinstance(evidence_record, dict):
            self._downgrade_execution_evidence_record(
                evidence_record,
                reason="replay_cleanup_exception",
                error="; ".join(errors)[:2000],
            )
        return errors

    def _execution_evidence_refcount_maps(
        self,
    ) -> Dict[str, Dict[int, int]]:
        """Return lazily initialized per-BB evidence ownership maps.

        The long-lived evidence sets predate late replay finalization and do
        not encode which execution supplied a BB.  Refcounts add that missing
        ownership information with O(valid-BB) memory, rather than retaining
        every compact execution record solely for possible invalidation.
        """
        names = {
            VALIDATED_REPLAY: "execution_evidence_validated_refcounts",
            DIAGNOSTIC_REPLAY: "execution_evidence_diagnostic_refcounts",
            UNCLASSIFIED_REPLAY: "execution_evidence_unclassified_refcounts",
        }
        maps: Dict[str, Dict[int, int]] = {}
        for status, name in names.items():
            value = getattr(self, name, None)
            if not isinstance(value, dict):
                value = {}
                setattr(self, name, value)
            maps[status] = value
        if not bool(getattr(self, "execution_evidence_ledger_initialized", False)):
            legacy_names = {
                VALIDATED_REPLAY: "execution_evidence_validated_bbs",
                DIAGNOSTIC_REPLAY: "execution_evidence_diagnostic_bbs",
                UNCLASSIFIED_REPLAY: "execution_evidence_unclassified_bbs",
            }
            legacy = {
                status: set(getattr(self, name, set()) or set())
                for status, name in legacy_names.items()
            }
            self.execution_evidence_legacy_bbs = legacy
            self.execution_evidence_ledger_initialized = True
        return maps

    def _rebuild_execution_evidence_sets(self) -> None:
        """Synchronize compatibility sets after a witness status change."""
        maps = self._execution_evidence_refcount_maps()
        set_names = {
            VALIDATED_REPLAY: "execution_evidence_validated_bbs",
            DIAGNOSTIC_REPLAY: "execution_evidence_diagnostic_bbs",
            UNCLASSIFIED_REPLAY: "execution_evidence_unclassified_bbs",
        }
        for status, set_name in set_names.items():
            target = getattr(self, set_name, None)
            if not isinstance(target, set):
                target = set()
                setattr(self, set_name, target)
            counts = maps[status]
            legacy = set(
                dict(getattr(self, "execution_evidence_legacy_bbs", {}) or {}).get(
                    status,
                    set(),
                )
                or set()
            )
            target.clear()
            target.update(int(bb) for bb in legacy)
            target.update(
                int(bb)
                for bb, count in counts.items()
                if int(count or 0) > 0
            )

    def _account_execution_evidence_record(
        self,
        record: Mapping[str, object],
        status: str,
        covered_bbs: Iterable[int],
        *,
        archived: bool = False,
    ) -> str:
        """Archive one record omitted from the bounded detailed ledger.

        Retained records remain authoritative in ``phase_execution_records``.
        Only records dropped by its retention bound are folded into per-BB
        refcounts.  Consequently memory grows with the firmware's valid BB
        denominator, not with the number of replay attempts.
        """
        normalized_status = str(status or UNCLASSIFIED_REPLAY).strip().lower()
        if normalized_status not in {
            VALIDATED_REPLAY,
            DIAGNOSTIC_REPLAY,
            UNCLASSIFIED_REPLAY,
        }:
            normalized_status = UNCLASSIFIED_REPLAY
        if not archived:
            return normalized_status
        try:
            valid = self.validate_coverage(covered_bbs)
        except Exception:
            valid = set()
        maps = self._execution_evidence_refcount_maps()
        previous_status = str(
            record.get("_lsgemu_archived_evidence_status") or ""
        ).strip().lower()
        previous_bbs = {
            int(value)
            for value in list(
                record.get("_lsgemu_archived_evidence_bbs", []) or []
            )
        }
        if previous_status == normalized_status and previous_bbs == valid:
            self._rebuild_execution_evidence_sets()
            return normalized_status
        if previous_status in maps:
            previous_counts = maps[previous_status]
            for bb in previous_bbs:
                key = int(bb)
                previous_counts[key] = max(
                    0,
                    int(previous_counts.get(key, 0) or 0) - 1,
                )
        counts = maps[normalized_status]
        for bb in valid:
            key = int(bb)
            counts[key] = int(counts.get(key, 0) or 0) + 1
        if isinstance(record, dict):
            record["_lsgemu_archived_evidence_status"] = normalized_status
            record["_lsgemu_archived_evidence_bbs"] = sorted(valid)
        self._rebuild_execution_evidence_sets()
        return normalized_status

    def _move_archived_execution_evidence(
        self,
        record: Mapping[str, object],
        to_status: str,
    ) -> None:
        """Move one dropped record between archival evidence statuses."""
        target = str(to_status or UNCLASSIFIED_REPLAY).strip().lower()
        allowed = {VALIDATED_REPLAY, DIAGNOSTIC_REPLAY, UNCLASSIFIED_REPLAY}
        if target not in allowed:
            target = UNCLASSIFIED_REPLAY
        source = str(
            record.get("_lsgemu_archived_evidence_status") or ""
        ).strip().lower()
        if source not in allowed or source == target:
            return
        self._account_execution_evidence_record(
            record,
            target,
            record.get("covered_bbs", []),
            archived=True,
        )

    def _sync_retained_execution_evidence_record(
        self,
        record: Mapping[str, object],
    ) -> None:
        """Propagate a late downgrade to the bounded retained copy."""
        execution_id = str(record.get("execution_id") or "")
        if not execution_id:
            return
        retained_records = getattr(self, "phase_execution_records", None)
        if not isinstance(retained_records, list):
            return
        for retained in retained_records:
            if not isinstance(retained, dict):
                continue
            if str(retained.get("execution_id") or "") != execution_id:
                continue
            try:
                retained_bbs = self.validate_coverage(
                    retained.get("covered_bbs", [])
                )
                record_bbs = self.validate_coverage(record.get("covered_bbs", []))
            except Exception:
                continue
            if retained_bbs != record_bbs:
                continue
            # Keep the compact record's identity and covered BBs intact while
            # copying only mutable evidence-contract fields.  Large diagnostic
            # payloads are never duplicated by this synchronization.
            for key in (
                "status",
                "telemetry_complete",
                "execution_telemetry_complete",
                "execution_failed",
                "execution_completed_normally",
                "failure_reason",
                "reasons",
                "execution_failure_reasons",
                "actual_intervention_reasons",
                "execution_error",
            ):
                if key in record:
                    value = record[key]
                    if isinstance(value, (list, dict, set, tuple)):
                        value = copy.deepcopy(value)
                    retained[key] = value

    @staticmethod
    def _child_execution_summary(
        child_count: int,
        intervention_reasons: Mapping[str, int] | Counter[str] | None,
        *,
        expected_count: Optional[int] = None,
        attempted_count: Optional[int] = None,
        completed_count: Optional[int] = None,
        execution_records: Optional[Iterable[Mapping[str, object]]] = None,
    ) -> Dict[str, object]:
        """Serialize child execution facts without self-comparing counters.

        ``child_count`` is a scheduler counter and is intentionally not used
        as proof that a worker returned an execution result when per-child
        records are available.  A phase may still pass no records for
        compatibility with an older kernel; that aggregate remains explicitly
        incomplete so it cannot promote the phase's BBs to a validated
        witness.
        """
        def safe_count(value: object) -> int:
            try:
                return max(0, int(value or 0))
            except (TypeError, ValueError, OverflowError):
                return 0

        records_supplied = execution_records is not None
        records = [
            dict(item)
            for item in (execution_records or ())
            if isinstance(item, Mapping)
        ]

        attempted = safe_count(
            attempted_count if attempted_count is not None else child_count
        )
        expected = (
            safe_count(expected_count)
            if expected_count is not None
            else max(attempted, len(records))
        )
        reasons: Dict[str, int] = {}
        configured: Dict[str, int] = {}
        validated_bbs: Set[int] = set()
        diagnostic_bbs: Set[int] = set()
        unclassified_bbs: Set[int] = set()
        successful = 0
        failures = 0
        validated_executions = 0
        diagnostic_executions = 0
        unclassified_executions = 0
        execution_facts = 0

        for key, value in dict(intervention_reasons or {}).items():
            parsed = safe_count(value)
            if parsed:
                reasons[str(key)] = parsed

        if records_supplied:
            # A materialized record, including a failed execution record, is a
            # completed reporting slot.  Telemetry completeness is tracked
            # separately so a failed child is not mistaken for a missing one.
            completed = len(records)
            incomplete = 0
            for record in records:
                status = str(record.get("status") or "unclassified")
                if status == VALIDATED_REPLAY and not compact_record_is_verified_validated(
                    record
                ):
                    status = "unclassified"
                    record["status"] = status
                    record["reasons"] = list(record.get("reasons", []) or []) + [
                        "compact_record_not_verified"
                    ]
                record_covered_bbs = safe_basic_block_list(
                    record.get("covered_bbs", [])
                )
                if status == VALIDATED_REPLAY:
                    validated_executions += 1
                    validated_bbs.update(record_covered_bbs)
                elif status == DIAGNOSTIC_REPLAY:
                    diagnostic_executions += 1
                    diagnostic_bbs.update(record_covered_bbs)
                else:
                    unclassified_executions += 1
                    unclassified_bbs.update(record_covered_bbs)
                for reason in record.get("reasons", []) or []:
                    if str(reason):
                        reasons[str(reason)] = reasons.get(str(reason), 0) + 1
                for reason, value in dict(
                    record.get("actual_intervention_reasons", {}) or {}
                ).items():
                    parsed = safe_count(value)
                    if parsed:
                        reasons[str(reason)] = max(
                            reasons.get(str(reason), 0), parsed
                        )
                for reason, value in dict(
                    record.get("configured_intervention_counts", {}) or {}
                ).items():
                    parsed = safe_count(value)
                    if parsed:
                        configured[str(reason)] = max(
                            configured.get(str(reason), 0), parsed
                        )
                facts_available = coerce_bool(
                    record.get("execution_facts_available"), False
                )
                telemetry_complete = coerce_bool(
                    record.get("telemetry_complete"), False
                )
                failure_reasons = list(
                    record.get("execution_failure_reasons", []) or []
                )
                explicit_failed = any(
                    coerce_bool(record.get(key), False)
                    for key in (
                        "execution_failed",
                        "preflight_failed",
                        "runtime_failure",
                        "restore_failed",
                    )
                ) or any(
                    record.get(key) not in (None, "", False)
                    for key in (
                        "failure_reason",
                        "execution_error",
                        "restore_error",
                    )
                )
                if facts_available:
                    execution_facts += 1
                if failure_reasons or explicit_failed:
                    failures += 1
                elif facts_available and telemetry_complete:
                    successful += 1
                if not (facts_available and telemetry_complete):
                    incomplete += 1
            # A materialized failure record is an observed attempt, not a
            # missing worker result.  Keep missing slots distinct from failed
            # or incomplete executions in the report.
            missing = max(0, expected - len(records))
            complete = bool(
                expected > 0
                and len(records) >= expected
                and incomplete == 0
                and all(
                    coerce_bool(record.get("execution_facts_available"), False)
                    and coerce_bool(record.get("telemetry_complete"), False)
                    and not any(
                        coerce_bool(record.get(key), False)
                        for key in (
                            "execution_failed",
                            "runtime_failure",
                            "restore_failed",
                            "preflight_failed",
                        )
                    )
                    and not any(
                        record.get(key) not in (None, "", False)
                        for key in (
                            "failure_reason",
                            "execution_error",
                            "restore_error",
                        )
                    )
                    for record in records
                )
            )
            if missing or incomplete or not complete:
                reasons["incomplete_child_execution_telemetry"] = max(
                    1,
                    int(reasons.get("incomplete_child_execution_telemetry", 0) or 0),
                )
        else:
            # Compatibility aggregates have no BB-to-child attribution.  Keep
            # their counters for diagnostics, but never claim complete
            # telemetry or derive a validated BB from them.
            completed = safe_count(
                completed_count if completed_count is not None else child_count
            )
            missing = max(0, expected - completed)
            incomplete = completed
            complete = False
            successful = 0
            failures = 0
            validated_executions = 0
            diagnostic_executions = 0
            unclassified_executions = completed
            execution_facts = 0
            reasons["missing_child_execution_records"] = max(
                1,
                int(reasons.get("missing_child_execution_records", 0) or 0),
            )
            reasons["incomplete_child_execution_telemetry"] = max(
                1,
                int(reasons.get("incomplete_child_execution_telemetry", 0) or 0),
            )

        return {
            "child_replay_count": attempted,
            "child_attempt_count": attempted,
            "child_completed_with_result_count": completed,
            "child_successful_execution_count": successful,
            "child_failure_count": failures,
            "child_validated_execution_count": validated_executions,
            "child_diagnostic_execution_count": diagnostic_executions,
            "child_unclassified_execution_count": unclassified_executions,
            "child_execution_facts_count": execution_facts,
            "child_materialized_record_count": len(records),
            "child_missing_result_count": missing,
            "child_incomplete_result_count": incomplete,
            "expected_child_replay_count": expected,
            "execution_telemetry_complete": bool(complete),
            "execution_records_available": bool(records_supplied),
            "execution_record_count": len(records),
            "intervention_reasons": reasons,
            "configured_intervention_counts": configured,
            "validated_bbs": sorted(validated_bbs),
            "diagnostic_bbs": sorted(diagnostic_bbs),
            "unclassified_bbs": sorted(unclassified_bbs),
            "child_execution_records": records,
        }

    @staticmethod
    def _new_direct_execution_id(
        emulator: IntelligentEmulator,
        phase_name: str,
    ) -> str:
        """Allocate an id for one manually driven ``emu_start`` attempt."""
        try:
            sequence = int(
                getattr(emulator, "_direct_execution_sequence", 0) or 0
            ) + 1
            setattr(emulator, "_direct_execution_sequence", sequence)
        except Exception:
            sequence = 1
        return (
            f"direct-{str(phase_name or 'execution')}-"
            f"{id(emulator):x}-{sequence}"
        )

    def _record_probe_diagnostic(
        self,
        probe_kind: str,
        reason: str,
        *,
        run_result: Optional[Mapping[str, object]] = None,
        execution_id: Optional[str] = None,
        error: Optional[BaseException | str] = None,
        **metadata: object,
    ) -> Dict[str, object]:
        """Retain a bounded, non-coverage record for an advisory probe.

        Probes are used to derive candidates, not to establish coverage.  A
        failed probe therefore must not be inserted into the child replay
        ledger (which would change expected-child accounting), but dropping it
        entirely makes a missing candidate indistinguishable from a deliberate
        empty result.  Keep only scalar/short diagnostic fields so this list
        cannot retain a Unicorn engine, trace, or snapshot.
        """
        record: Dict[str, object] = {
            "probe_kind": str(probe_kind or "unknown"),
            "reason": str(reason or "probe_failure")[:512],
        }
        if execution_id:
            record["execution_id"] = str(execution_id)[:256]
        if error is not None:
            record["error"] = str(error)[:2000]
        if isinstance(run_result, Mapping):
            for key in (
                "stop_reason",
                "execution_started",
                "execution_failed",
                "preflight_failed",
                "execution_completed_normally",
                "execution_telemetry_complete",
                "execution_id",
            ):
                value = run_result.get(key)
                if value not in (None, ""):
                    if key == "stop_reason" or key == "execution_id":
                        record[key] = str(value)[:256]
                    else:
                        record[key] = bool(value)
        for key, value in metadata.items():
            if value in (None, ""):
                continue
            if isinstance(value, (str, int, float, bool)):
                record[str(key)] = (
                    str(value)[:512] if isinstance(value, str) else value
                )
        try:
            history = getattr(self, "probe_diagnostics", None)
            if not isinstance(history, list):
                history = []
                setattr(self, "probe_diagnostics", history)
            history.append(record)
            del history[:-128]
        except Exception:
            # Diagnostics must never affect scheduling or execution.
            pass
        return record

    @staticmethod
    def _direct_peripheral_input_stats(
        emulator: object,
        mmio_handler: Optional[object] = None,
    ) -> Tuple[Dict[str, int], str]:
        """Read RX telemetry from the handler that actually owns execution.

        Direct ISR/task explorers install ``EnhancedMMIOHandler`` as an
        overlay.  The primary stateful handler registered for the Unicorn
        instance performs the semantic read and owns
        ``peripheral_input_stats``.  The explicit handler argument is retained
        for adapters where that overlay is itself the semantic owner.
        """
        candidates: List[Tuple[str, object]] = []
        primary = get_primary_mmio_handler(getattr(emulator, "uc", None))
        if primary is not None:
            candidates.append(("primary_mmio_handler", primary))
        owner = getattr(emulator, "mmio_handler", None)
        if owner is not None and not any(
            owner is item for _name, item in candidates
        ):
            candidates.append(("emulator_mmio_handler", owner))
        if mmio_handler is not None and not any(
            mmio_handler is item for _name, item in candidates
        ):
            candidates.append(("direct_mmio_handler", mmio_handler))
        for source, handler in candidates:
            stats = getattr(handler, "peripheral_input_stats", None)
            if not isinstance(stats, Mapping):
                continue
            normalized: Dict[str, int] = {}
            for key, value in stats.items():
                try:
                    normalized[str(key)] = int(value or 0)
                except (TypeError, ValueError, OverflowError):
                    continue
            return normalized, source
        return {}, "none"

    @classmethod
    def _capture_direct_execution_baseline(
        cls,
        emulator: IntelligentEmulator,
        phase_name: str,
        mmio_handler: Optional[object] = None,
    ) -> Dict[str, object]:
        """Capture cumulative emulator state immediately before execution.

        Direct ISR/task explorers do not pass through ``IntelligentEmulator.run``.
        Their diagnostic counters are cumulative over the emulator lifetime, so
        a record made after a second direct execution must use a delta rather
        than the lifetime total.  Keep both the direct adapter baseline and the
        emulator's normal provenance baseline in sync: the latter is consulted
        by ``_current_execution_provenance`` when a direct execution creates a
        snapshot or evidence record.  This helper does not alter execution
        configuration or control flow.
        """
        counter_snapshot: Dict[str, object] = {}
        snapshot_reader = getattr(emulator, "_execution_counter_snapshot", None)
        if callable(snapshot_reader):
            try:
                value = snapshot_reader()
                if isinstance(value, Mapping):
                    counter_snapshot = dict(value)
            except Exception:
                counter_snapshot = {}
        forced_trace = list(getattr(emulator, "forced_branch_trace", []) or [])
        execution_id = cls._new_direct_execution_id(emulator, phase_name)
        # Direct ``emu_start`` does not enter IntelligentEmulator.run(), so it
        # otherwise keeps the previous execution id and can attach the wrong
        # provenance to this attempt.
        try:
            setattr(emulator, "execution_id", execution_id)
        except Exception:
            pass
        direct_peripheral_stats, direct_peripheral_source = (
            cls._direct_peripheral_input_stats(emulator, mmio_handler)
        )
        baseline = {
            "counter_snapshot": counter_snapshot,
            "forced_trace_len": len(forced_trace),
            "instruction_count": int(
                getattr(emulator, "instruction_count", 0) or 0
            ),
            "bb_addr_set": set(
                int(item) & 0xFFFFFFFF
                for item in (getattr(emulator, "bb_addr_set", set()) or set())
                if isinstance(item, int)
            ),
            "stream_summary_event_len": len(
                list(getattr(emulator, "stream_input_summary_events", []) or [])
            ),
            "stream_payload_write_len": len(
                list(getattr(emulator, "stream_input_payload_writes", []) or [])
            ),
            "execution_id": execution_id,
            "direct_peripheral_input_stats": direct_peripheral_stats,
            "direct_peripheral_input_stats_source": direct_peripheral_source,
        }
        try:
            # Direct ``emu_start`` does not initialize the fields that
            # ``IntelligentEmulator.run`` normally uses for provenance deltas.
            # Synchronizing them here prevents a restored prefix or a prior
            # direct attempt from leaking intervention reasons into this one.
            setattr(emulator, "_execution_counter_baseline", dict(counter_snapshot))
            setattr(emulator, "_forced_trace_baseline_len", len(forced_trace))
            setattr(
                emulator,
                "_stream_summary_event_baseline_len",
                len(list(getattr(emulator, "stream_input_summary_events", []) or [])),
            )
            setattr(
                emulator,
                "_stream_payload_write_baseline_len",
                len(list(getattr(emulator, "stream_input_payload_writes", []) or [])),
            )
            setattr(emulator, "_direct_execution_baseline", baseline)
        except Exception:
            pass
        return baseline

    @staticmethod
    def _begin_direct_execution(emulator: Optional[object]) -> None:
        """Mark a manually driven Unicorn interval as provenance-pending.

        ``IntelligentEmulator.run`` owns this state for ordinary executions.
        ISR explorers call ``emu_start`` through a separate adapter, so they
        need the same marker before a branch hook captures a new snapshot.
        This helper only changes bookkeeping; it does not touch CPU or MMIO
        state.
        """
        if emulator is None:
            return
        try:
            setattr(emulator, "_execution_active", True)
        except Exception:
            # Legacy test doubles may expose no writable attribute.  The
            # direct evidence record remains usable, but such a snapshot is
            # conservatively handled by the existing provenance contract.
            pass

    @staticmethod
    def _finalize_direct_execution(
        emulator: Optional[object],
        execution_baseline: Optional[Mapping[str, object]],
        *,
        execution_started: bool,
        execution_error: Optional[BaseException | str] = None,
    ) -> Dict[str, object]:
        """Close one manually driven execution and finalize its snapshots.

        Direct ISR execution bypasses ``IntelligentEmulator.run`` and hence
        would otherwise leave snapshots captured by branch hooks either
        permanently pending or incorrectly finalized before the native call
        has returned.  Finalization is deliberately best-effort for legacy
        adapters, while the returned diagnostics make failures observable to
        callers and tests.
        """
        result: Dict[str, object] = {
            "execution_id": "",
            "actual_intervention_reasons": [],
            "finalized_snapshots": 0,
            "finalization_error": "",
            "finalization_errors": [],
        }
        if emulator is None:
            result["finalization_error"] = "missing_emulator"
            result["finalization_errors"] = ["missing_emulator"]
            return result

        finalization_errors: List[str] = []

        try:
            setattr(emulator, "_execution_active", False)
        except Exception as exc:
            finalization_errors.append(
                f"execution_active_reset:{type(exc).__name__}"
            )

        execution_id = ""
        if isinstance(execution_baseline, Mapping):
            execution_id = str(execution_baseline.get("execution_id") or "")
        if not execution_id:
            execution_id = str(getattr(emulator, "execution_id", "") or "")
        result["execution_id"] = execution_id

        actual_reasons: List[str] = []
        if isinstance(execution_baseline, Mapping):
            try:
                actual_reasons = list(
                    execution_intervention_counts_from_emulator(
                        emulator,
                        baseline=execution_baseline,
                    )
                )
            except Exception as exc:
                finalization_errors.append(
                    f"counter_delta:{type(exc).__name__}"
                )
        result["actual_intervention_reasons"] = actual_reasons

        manager = getattr(emulator, "branch_snapshot_manager", None)
        finalizer = getattr(manager, "finalize_snapshot_provenance", None)
        if execution_id and callable(finalizer) and (
            isinstance(execution_baseline, Mapping) or execution_started
        ):
            try:
                result["finalized_snapshots"] = int(
                    finalizer(
                        execution_id,
                        successful=bool(
                            execution_started and execution_error is None
                        ),
                        telemetry_complete=bool(
                            execution_started and execution_error is None
                        ),
                        actual_intervention_reasons=actual_reasons,
                    )
                    or 0
                )
            except Exception as exc:
                finalization_errors.append(
                    f"snapshot_provenance:{type(exc).__name__}"
                )
                logger.debug(
                    "direct execution snapshot provenance finalize failed: %s",
                    exc,
                )
        result["finalization_errors"] = list(dict.fromkeys(finalization_errors))
        result["finalization_error"] = "; ".join(finalization_errors)[:2000]
        return result

    @staticmethod
    def _direct_execution_evidence_record(
        *,
        phase_name: str,
        emulator: IntelligentEmulator,
        covered_bbs: Iterable[int],
        metadata: Optional[Mapping[str, object]] = None,
        stop_reason: str = "direct_unicorn_execution_completed",
        execution_started: bool = True,
        execution_error: Optional[BaseException | str] = None,
        additional_intervention_reasons: Optional[Iterable[str]] = None,
        execution_baseline: Optional[Mapping[str, object]] = None,
        run_result: Optional[Mapping[str, object]] = None,
        execution_id: Optional[str] = None,
        mmio_handler: Optional[object] = None,
        finalization_result: Optional[Mapping[str, object]] = None,
    ) -> Dict[str, object]:
        """Materialize facts for phases that call Unicorn outside ``run()``.

        ISR and task-entry explorers invoke ``emu_start`` directly.  Without
        this adapter those executions only contributed a counter and could not
        be distinguished from a missing child result.  The adapter is
        observational: it reads the temporary emulator after execution and
        never changes its control flow or coverage set.
        """
        # Direct ISR execution does not call ``IntelligentEmulator.run``.
        # Never copy ``last_run_result`` here: a reused emulator could expose
        # facts belonging to an earlier child execution.
        started = bool(execution_started)
        normalized_covered = safe_basic_block_list(covered_bbs)
        supplied_run_result = isinstance(run_result, Mapping)
        result: Dict[str, object] = dict(run_result or {})
        if isinstance(finalization_result, Mapping):
            # Finalization runs in the direct-emulation ``finally`` block,
            # before this record is materialized.  Merge its outcome into the
            # same child record so a teardown/provenance failure cannot hide in
            # a side channel or create a duplicate child record.
            compact_finalization = {
                key: value
                for key, value in finalization_result.items()
                if key in {
                    "execution_id",
                    "finalized_snapshots",
                    "finalization_error",
                    "finalization_errors",
                    "actual_intervention_reasons",
                    "provenance_invalidated",
                    "provenance_invalidation_reasons",
                    "invalidated_snapshots",
                }
            }
            if compact_finalization:
                result["direct_execution_finalization"] = compact_finalization
                if "finalized_snapshots" in compact_finalization:
                    result["direct_finalized_snapshots"] = int(
                        compact_finalization.get("finalized_snapshots") or 0
                    )
                if "finalization_error" in compact_finalization:
                    result["direct_finalization_error"] = str(
                        compact_finalization.get("finalization_error") or ""
                    )[:2000]
                if "finalization_errors" in compact_finalization:
                    result["direct_finalization_errors"] = [
                        str(item)[:512]
                        for item in list(
                            compact_finalization.get("finalization_errors", [])
                            or []
                        )
                        if str(item)
                        ][:16]
                if compact_finalization.get("provenance_invalidated"):
                    result["provenance_invalidated"] = True
                    result["provenance_invalidation_reasons"] = [
                        str(item)[:512]
                        for item in list(
                            compact_finalization.get(
                                "provenance_invalidation_reasons",
                                [],
                            )
                            or []
                        )
                        if str(item)
                    ][:16]
                    result["snapshot_provenance_invalidated_snapshots"] = int(
                        compact_finalization.get("invalidated_snapshots") or 0
                    )
            finalization_error = str(
                finalization_result.get("finalization_error") or ""
            )
            if finalization_error:
                result["execution_failed"] = True
                result["execution_completed_normally"] = False
                result["execution_telemetry_complete"] = False
                result["failure_reason"] = (
                    "direct_execution_finalization_failed"
                )
                previous_error = str(result.get("execution_error") or "")
                result["execution_error"] = (
                    f"{previous_error}; {finalization_error}"[:2000]
                    if previous_error
                    else finalization_error
                )
                failure_reasons = list(
                    result.get("execution_failure_reasons", []) or []
                )
                if "direct_execution_finalization_failed" not in failure_reasons:
                    failure_reasons.append(
                        "direct_execution_finalization_failed"
                    )
                result["execution_failure_reasons"] = list(
                    dict.fromkeys(str(item) for item in failure_reasons if str(item))
                )
        result.setdefault("execution_started", started)
        result.setdefault("execution_attempted", True)
        result.setdefault(
            "stop_reason",
            (
                "execution_not_started"
                if not started and execution_error is None
                else "exception"
                if execution_error is not None
                else str(stop_reason)
            ),
        )
        baseline = execution_baseline
        if not isinstance(baseline, Mapping):
            candidate_baseline = getattr(
                emulator, "_direct_execution_baseline", None
            )
            baseline = candidate_baseline if isinstance(candidate_baseline, Mapping) else None
        current_instruction_count = int(
            getattr(emulator, "instruction_count", 0) or 0
        )
        if isinstance(baseline, Mapping):
            try:
                current_instruction_count = max(
                    0,
                    current_instruction_count
                    - int(baseline.get("instruction_count", 0) or 0),
                )
            except (TypeError, ValueError, OverflowError):
                pass
        result.setdefault("instruction_count", current_instruction_count)
        # P1-D（cycle3 k.5 C7）：该计数器按**规范化 BB** 自增
        # （intelligent_emulator 块回调），键名 instruction_count 实为 BB
        # 数——读数单位由此键显式化（报告计量坑：U2 修复版判据的前提）。
        result.setdefault("is_bb_counted", True)
        current_bbs = set(
            int(item) & 0xFFFFFFFF
            for item in (getattr(emulator, "bb_addr_set", set()) or set())
            if isinstance(item, int)
        )
        if isinstance(baseline, Mapping):
            current_bbs -= set(baseline.get("bb_addr_set", set()) or set())
        result.setdefault("unique_bbs", len(current_bbs))
        result.setdefault("covered_bb_list", normalized_covered)
        if execution_error is not None:
            result["execution_failed"] = True
            current_error = str(execution_error)[:2000]
            previous_error = str(result.get("execution_error") or "")
            if previous_error and current_error and current_error not in previous_error:
                current_error = f"{previous_error}; {current_error}"[:2000]
            result["execution_error"] = current_error or previous_error
            result["execution_completed_normally"] = False
        else:
            result.setdefault("execution_failed", False)
            result.setdefault("execution_completed_normally", bool(started))

        try:
            result["registers"] = {
                str(name): f"0x{int(value) & 0xFFFFFFFF:08x}"
                for name, value in emulator._get_registers().items()
            }
        except Exception:
            result["registers"] = {}

        native_result_is_authoritative = bool(
            supplied_run_result
            and coerce_bool(
                result.get("execution_intervention_reasons_authoritative"),
            )
        )
        actual_counts = (
            {}
            if native_result_is_authoritative
            else execution_intervention_counts_from_emulator(
                emulator,
                baseline=baseline,
            )
        )
        actual_reasons = list(actual_counts)
        for reason in additional_intervention_reasons or ():
            reason_text = str(reason)
            if reason_text and reason_text not in actual_reasons:
                actual_reasons.append(reason_text)
                actual_counts[reason_text] = max(
                    1,
                    int(actual_counts.get(reason_text, 0) or 0),
                )
        stream_event_start = 0
        payload_write_start = 0
        if isinstance(baseline, Mapping):
            try:
                stream_event_start = max(
                    0, int(baseline.get("stream_summary_event_len", 0) or 0)
                )
            except (TypeError, ValueError, OverflowError):
                stream_event_start = 0
            try:
                payload_write_start = max(
                    0, int(baseline.get("stream_payload_write_len", 0) or 0)
                )
            except (TypeError, ValueError, OverflowError):
                payload_write_start = 0
        stream_events = list(
            getattr(emulator, "stream_input_summary_events", []) or []
        )[stream_event_start:]
        stream_payload_writes = list(
            getattr(emulator, "stream_input_payload_writes", []) or []
        )[payload_write_start:]
        current_environment_stats = getattr(
            emulator, "environment_input_delivery_stats", {}
        )
        baseline_environment_stats = {}
        if isinstance(baseline, Mapping):
            baseline_snapshot = baseline.get("counter_snapshot")
            if isinstance(baseline_snapshot, Mapping):
                baseline_environment_stats = dict(
                    baseline_snapshot.get("environment_input_delivery_stats", {})
                    or {}
                )
        environment_delta_stats: Dict[str, int] = {}
        if isinstance(current_environment_stats, Mapping):
            for key, value in current_environment_stats.items():
                try:
                    delta = int(value or 0) - int(
                        baseline_environment_stats.get(key, 0) or 0
                    )
                except (TypeError, ValueError, OverflowError):
                    delta = 0
                if delta > 0:
                    environment_delta_stats[str(key)] = delta
        current_peripheral_stats: Mapping[str, object] = {}
        counter_reader = getattr(emulator, "_execution_counter_snapshot", None)
        if callable(counter_reader):
            try:
                current_counter_snapshot = counter_reader()
            except Exception:
                current_counter_snapshot = {}
            if isinstance(current_counter_snapshot, Mapping):
                candidate = current_counter_snapshot.get("peripheral_input_stats", {})
                if isinstance(candidate, Mapping):
                    current_peripheral_stats = candidate
        baseline_peripheral_stats: Mapping[str, object] = {}
        if isinstance(baseline, Mapping):
            baseline_snapshot = baseline.get("counter_snapshot")
            if isinstance(baseline_snapshot, Mapping):
                candidate = baseline_snapshot.get("peripheral_input_stats", {})
                if isinstance(candidate, Mapping):
                    baseline_peripheral_stats = candidate
        peripheral_delta_stats: Dict[str, int] = {}
        for key, value in current_peripheral_stats.items():
            try:
                delta = int(value or 0) - int(
                    baseline_peripheral_stats.get(key, 0) or 0
                )
            except (TypeError, ValueError, OverflowError):
                delta = 0
            if delta > 0:
                peripheral_delta_stats[str(key)] = delta
        direct_peripheral_stats, direct_peripheral_source = (
            HistoricalRunner._direct_peripheral_input_stats(
                emulator,
                mmio_handler,
            )
        )
        baseline_direct_peripheral_stats: Mapping[str, object] = {}
        if isinstance(baseline, Mapping):
            candidate = baseline.get("direct_peripheral_input_stats", {})
            if isinstance(candidate, Mapping):
                baseline_direct_peripheral_stats = candidate
        direct_peripheral_delta_stats: Dict[str, int] = {}
        for key, value in direct_peripheral_stats.items():
            try:
                delta = int(value or 0) - int(
                    baseline_direct_peripheral_stats.get(key, 0) or 0
                )
            except (TypeError, ValueError, OverflowError):
                delta = 0
            if delta > 0:
                direct_peripheral_delta_stats[str(key)] = delta
        # The handler selected by ``_direct_peripheral_input_stats`` owns the
        # read.  When it exists, its delta must replace the emulator-counter
        # delta even when that delta is empty: otherwise a stale overlay or a
        # second handler can manufacture RX facts for the current attempt.
        # The counter-snapshot path remains a compatibility fallback for
        # adapters that expose no handler-level telemetry.
        if direct_peripheral_source != "none":
            peripheral_delta_stats = dict(direct_peripheral_delta_stats)
            peripheral_stats_source = direct_peripheral_source
        else:
            peripheral_stats_source = (
                "emulator_counter_snapshot" if peripheral_delta_stats else "none"
            )

        # Older callers may provide a complete per-run result but omit the new
        # direct baseline.  Prefer that already-delta-normalized payload over
        # a lifetime handler total; never reinterpret a cumulative counter as
        # this attempt's environmental fact in that compatibility case.
        supplied_peripheral_stats = result.get("peripheral_input_stats")
        if (
            not isinstance(execution_baseline, Mapping)
            and supplied_run_result
            and isinstance(supplied_peripheral_stats, Mapping)
        ):
            peripheral_delta_stats = {
                str(key): int(value or 0)
                for key, value in supplied_peripheral_stats.items()
                if isinstance(value, (int, float)) and int(value or 0) > 0
            }
            peripheral_stats_source = str(
                result.get("peripheral_input_stats_source")
                or "run_result"
            )
            direct_peripheral_delta_stats = {}
        environment_facts = environment_input_facts(
            {
                "environment_input_delivery_stats": environment_delta_stats,
                "peripheral_input_stats": peripheral_delta_stats,
                "stream_input_summary_events": stream_events,
                "stream_input_payload_writes": stream_payload_writes,
            }
        )
        environment_diagnostics = environment_model_diagnostics(
            {
                "peripheral_input_stats": peripheral_delta_stats,
                "stream_input_summary_events": stream_events,
            }
        )
        result["environment_facts"] = dict(environment_facts)
        result["environment_input_facts"] = dict(environment_facts)
        result["environment_input_delivery_stats"] = environment_delta_stats
        result["peripheral_input_stats"] = peripheral_delta_stats
        result["peripheral_input_stats_source"] = peripheral_stats_source
        if direct_peripheral_delta_stats:
            result["direct_peripheral_input_stats"] = direct_peripheral_delta_stats
            result["direct_peripheral_input_stats_source"] = direct_peripheral_source
        result["environment_model_diagnostics"] = dict(environment_diagnostics)
        result["stream_input_summary_events"] = [
            dict(item) for item in stream_events if isinstance(item, Mapping)
        ][-256:]
        result["stream_input_payload_writes"] = [
            dict(item) for item in stream_payload_writes if isinstance(item, Mapping)
        ][-256:]
        allowed_stream_summaries = max(
            int(environment_facts.get("stream_input_delivery", 0) or 0),
            int(environment_delta_stats.get("accepted", 0) or 0),
        )
        if allowed_stream_summaries and int(
            actual_counts.get("function_summary_or_skip", 0) or 0
        ):
            remaining_summary_count = max(
                0,
                int(actual_counts.get("function_summary_or_skip", 0) or 0)
                - allowed_stream_summaries,
            )
            if remaining_summary_count:
                actual_counts["function_summary_or_skip"] = remaining_summary_count
            else:
                actual_counts.pop("function_summary_or_skip", None)
            actual_reasons = list(actual_counts)
        if not native_result_is_authoritative:
            result["execution_intervention_reasons"] = actual_reasons
            result["execution_intervention_reasons_authoritative"] = True
            result["execution_intervention_counts"] = dict(actual_counts)
        else:
            existing_counts = dict(
                result.get("execution_intervention_counts", {}) or {}
            )
            for reason, count in actual_counts.items():
                try:
                    existing_counts[str(reason)] = max(
                        int(existing_counts.get(str(reason), 0) or 0),
                        int(count or 0),
                    )
                except (TypeError, ValueError, OverflowError):
                    existing_counts[str(reason)] = int(count or 0)
            if existing_counts:
                result["execution_intervention_counts"] = existing_counts
                result["execution_intervention_reasons"] = list(existing_counts)
        result.setdefault(
            "configured_intervention_counts",
            dict(
                configured_intervention_counts(
                    {
                        "forced_branch_choices_configured": len(
                            dict(getattr(emulator, "forced_branch_choices", {}) or {})
                        ),
                        "forced_choices_requested": len(
                            list(getattr(emulator, "forced_branch_sequence", []) or [])
                        ),
                        "runtime_loop_branch_force_stats": getattr(
                            emulator, "runtime_loop_branch_force_stats", {}
                        ),
                        "skip_function_stats": getattr(
                            emulator, "skip_function_stats", {}
                        ),
                    }
                )
            ),
        )
        resolved_execution_id = str(execution_id or "")
        if not resolved_execution_id and isinstance(baseline, Mapping):
            resolved_execution_id = str(baseline.get("execution_id") or "")
        if not resolved_execution_id and supplied_run_result:
            resolved_execution_id = str(result.get("execution_id") or "")
        if not resolved_execution_id:
            resolved_execution_id = HistoricalRunner._new_direct_execution_id(
                emulator,
                phase_name,
            )
        result["execution_id"] = resolved_execution_id
        provenance_reader = getattr(emulator, "_current_execution_provenance", None)
        if callable(provenance_reader):
            try:
                provenance = provenance_reader()
            except Exception as exc:
                provenance = {
                    "status": "diagnostic",
                    "reasons": [f"provenance_capture_failed:{type(exc).__name__}"],
                    "telemetry_complete": False,
                }
            if isinstance(provenance, Mapping):
                result["execution_provenance"] = dict(provenance)

        # A direct child is complete only when the native engine returned
        # normally.  Failed setup/start attempts retain their counters for
        # diagnostics, but cannot establish a strict witness.
        if "execution_telemetry_complete" not in result:
            result["execution_telemetry_complete"] = bool(
                started and execution_error is None
            )
        elif execution_error is not None:
            result["execution_telemetry_complete"] = False

        return build_execution_evidence_record(
            phase_name=phase_name,
            run_result=result,
            covered_bbs=covered_bbs,
            metadata=metadata,
            execution_id=resolved_execution_id,
        )

    @staticmethod
    def _execution_failure_evidence_record(
        *,
        phase_name: str,
        execution_id: str,
        reason: str,
        metadata: Optional[Mapping[str, object]] = None,
        covered_bbs: Iterable[int] = (),
        execution_started: bool = False,
        execution_error: Optional[BaseException | str] = None,
        run_result: Optional[Mapping[str, object]] = None,
    ) -> Dict[str, object]:
        """Materialize one replay attempt that failed before normal return.

        Replay kernels historically used ``continue`` for constructor,
        setup, restore, and Unicorn failures.  That made the attempt vanish
        from the evidence ledger and made a phase look artificially healthy.
        This adapter deliberately contains no retry or scheduling policy; it
        only turns the failure into an auditable canonical record.
        """
        result: Dict[str, object] = dict(run_result or {})
        result.setdefault("execution_attempted", True)
        result.setdefault("execution_started", bool(execution_started))
        result.setdefault("execution_completed_normally", False)
        result["execution_failed"] = True
        result["execution_telemetry_complete"] = False
        result.setdefault("stop_reason", str(reason or "replay_failure"))
        if execution_error is not None:
            result["execution_error"] = str(execution_error)[:2000]
        result["execution_id"] = str(execution_id or "")
        record = build_execution_evidence_record(
            phase_name=phase_name,
            run_result=result,
            covered_bbs=covered_bbs,
            metadata=metadata,
            execution_id=execution_id,
        )
        # Keep a stable machine-readable reason even when a producer supplied
        # an unusual stop string that the generic classifier does not know.
        reasons = list(record.get("reasons", []) or [])
        failure_reason = str(reason or "replay_failure")
        if failure_reason and failure_reason not in reasons:
            reasons.append(failure_reason)
        record["reasons"] = list(dict.fromkeys(reasons))
        record["failure_reason"] = failure_reason
        record["execution_error"] = (
            str(execution_error)[:2000]
            if execution_error is not None
            else record.get("execution_error")
        )
        return record

    def _downgrade_execution_evidence_record(
        self,
        record: Optional[Dict[str, object]],
        *,
        reason: str,
        error: Optional[BaseException | str] = None,
    ) -> None:
        """Atomically downgrade one materialized replay evidence record."""
        with self._runner_state_lock():
            self._downgrade_execution_evidence_record_unlocked(
                record,
                reason=reason,
                error=error,
            )

    def _downgrade_execution_evidence_record_unlocked(
        self,
        record: Optional[Dict[str, object]],
        *,
        reason: str,
        error: Optional[BaseException | str] = None,
    ) -> None:
        """Downgrade one already-materialized replay without duplicating it.

        Result collection and teardown happen after the emulator has executed.
        If either step fails, the observed BBs remain useful diagnostics, but
        the attempt no longer satisfies the strict witness contract.  Mutating
        the existing record is important: appending a second failure record
        would count one execution twice and could hide which BBs were observed
        by the failed attempt.
        """
        if not isinstance(record, dict):
            return
        self._move_archived_execution_evidence(
            record,
            DIAGNOSTIC_REPLAY,
        )
        failure_reason = str(reason or "replay_failure")
        record["status"] = DIAGNOSTIC_REPLAY
        record["telemetry_complete"] = False
        record["execution_telemetry_complete"] = False
        record["execution_failed"] = True
        record["execution_completed_normally"] = False
        record["failure_reason"] = failure_reason

        raw_reasons = record.get("reasons", [])
        if isinstance(raw_reasons, (list, tuple, set)):
            reasons = [str(item) for item in raw_reasons]
        elif raw_reasons in (None, ""):
            reasons = []
        else:
            reasons = [str(raw_reasons)]
        if failure_reason and failure_reason not in reasons:
            reasons.append(failure_reason)
        record["reasons"] = list(dict.fromkeys(reasons))

        raw_failure_reasons = record.get("execution_failure_reasons", [])
        if isinstance(raw_failure_reasons, (list, tuple, set)):
            execution_failure_reasons = [
                str(item) for item in raw_failure_reasons
            ]
        elif raw_failure_reasons in (None, ""):
            execution_failure_reasons = []
        else:
            execution_failure_reasons = [str(raw_failure_reasons)]
        if failure_reason and failure_reason not in execution_failure_reasons:
            execution_failure_reasons.append(failure_reason)
        record["execution_failure_reasons"] = list(
            dict.fromkeys(execution_failure_reasons)
        )

        actual_reasons = record.get("actual_intervention_reasons", {})
        if not isinstance(actual_reasons, Mapping):
            actual_reasons = {}
        updated_actual_reasons: Dict[str, int] = {}
        for item, value in dict(actual_reasons).items():
            try:
                parsed_value = max(0, int(value or 0))
            except (TypeError, ValueError, OverflowError):
                parsed_value = 0
            updated_actual_reasons[str(item)] = parsed_value
        updated_actual_reasons[failure_reason] = max(
            1,
            int(updated_actual_reasons.get(failure_reason, 0) or 0),
        )
        record["actual_intervention_reasons"] = updated_actual_reasons

        if error is not None:
            error_text = str(error)[:2000]
            previous_error = str(record.get("execution_error") or "")
            if previous_error and error_text and error_text not in previous_error:
                error_text = f"{previous_error}; {error_text}"[:2000]
            record["execution_error"] = error_text
        self._sync_retained_execution_evidence_record(record)

    def _snapshot_restore_failure_metadata(
        self,
        snapshot_entry: Optional[PrefixReplaySnapshot],
        restore_error: object,
    ) -> Dict[str, object]:
        """Return bounded identity facts for a failed snapshot restore.

        Restore failures are execution attempts, not coverage witnesses.  The
        metadata is intentionally compact so a large snapshot object or trace
        can never be retained merely to explain why the attempt was rejected.
        """
        metadata: Dict[str, object] = {
            "snapshot_origin": str(
                getattr(snapshot_entry, "origin", "unknown") or "unknown"
            ),
            "restore_error": str(restore_error or "snapshot_restore_failed")[:2000],
        }
        if snapshot_entry is None:
            metadata["snapshot_identity"] = "none"
            return metadata
        try:
            metadata["snapshot_identity"] = repr(
                self._snapshot_entry_identity(snapshot_entry)
            )[:2000]
        except Exception:
            metadata["snapshot_identity"] = "unavailable"
        snapshot = getattr(snapshot_entry, "snapshot", None)
        if snapshot is not None:
            try:
                metadata["snapshot_address"] = (
                    f"0x{int(getattr(snapshot, 'address', 0) or 0) & 0xFFFFFFFF:08x}"
                )
            except Exception:
                pass
            try:
                metadata["snapshot_order"] = int(
                    getattr(snapshot, "order", 0) or 0
                )
            except Exception:
                pass
        try:
            provenance = self._snapshot_provenance_record(snapshot_entry)
            source_execution_id = str(provenance.get("execution_id") or "")
            if source_execution_id:
                metadata["snapshot_source_execution_id"] = source_execution_id[:256]
        except Exception:
            pass
        return metadata

    def _record_coverage_evidence(self, evidence_class: str, covered: Iterable[int]) -> None:
        evidence = str(evidence_class or "")
        if evidence not in {EVIDENCE_E0, EVIDENCE_E1, EVIDENCE_E2, EVIDENCE_E3}:
            return
        valid = self.validate_coverage(covered)
        with self._runner_state_lock():
            self.coverage_by_evidence.setdefault(evidence, set()).update(valid)

    @staticmethod
    def _copy_phase_metadata_for_telemetry(
        phase_metadata: Dict[str, Dict[str, object]],
        retries: int = 8,
    ) -> Tuple[Dict[str, Dict[str, object]], Optional[str]]:
        """Copy externally updated phase metadata without exposing live dict views."""
        last_error: Optional[str] = None
        for _attempt in range(max(1, int(retries))):
            try:
                items = list(phase_metadata.items())
                copied: Dict[str, Dict[str, object]] = {}
                for name, metadata in items:
                    copied[str(name)] = dict(metadata) if isinstance(metadata, dict) else {
                        "value": metadata,
                    }
                return copied, None
            except RuntimeError as exc:
                last_error = str(exc)
                time.sleep(0)
        return {}, last_error or "phase_metadata_copy_failed"

    def telemetry_state_snapshot(self) -> Dict[str, object]:
        """Return Python-owned runner state suitable for a background monitor."""
        with self._runner_state_lock():
            phase_metadata, phase_copy_error = self._copy_phase_metadata_for_telemetry(
                getattr(self, "phase_metadata", {}) or {}
            )
            phase_metadata_history = {
                str(name): [
                    dict(item) if isinstance(item, dict) else {"value": item}
                    for item in list(entries or [])
                ]
                for name, entries in dict(
                    getattr(self, "phase_metadata_history", {}) or {}
                ).items()
            }
            phase_execution_records = [
                dict(record) if isinstance(record, dict) else {"value": record}
                for record in list(
                    getattr(self, "phase_execution_records", []) or []
                )
            ]
            snapshot = {
                "global_coverage": set(getattr(self, "global_coverage", set()) or set()),
                "coverage_by_evidence": {
                    str(evidence): set(covered)
                    for evidence, covered in list(
                        getattr(self, "coverage_by_evidence", {}).items()
                    )
                },
                "phase_metadata": phase_metadata,
                "phase_coverage": {
                    str(name): set(covered)
                    for name, covered in list(
                        getattr(self, "phase_coverage", {}).items()
                    )
                },
                "phase_metadata_history": phase_metadata_history,
                "phase_execution_records": phase_execution_records,
                "execution_evidence_validated_bbs": set(
                    getattr(self, "execution_evidence_validated_bbs", set()) or set()
                ),
                "execution_evidence_diagnostic_bbs": set(
                    getattr(self, "execution_evidence_diagnostic_bbs", set()) or set()
                ),
                "execution_evidence_unclassified_bbs": set(
                    getattr(self, "execution_evidence_unclassified_bbs", set()) or set()
                ),
                "dynamic_successors": {
                    int(source): set(successors)
                    for source, successors in list(
                        getattr(self, "dynamic_successors", {}).items()
                    )
                },
                "run_profile": dict(getattr(self, "run_profile", {}) or {}),
            }
        if phase_copy_error:
            snapshot["phase_metadata_copy_error"] = phase_copy_error
        return snapshot

    def _canonical_evidence_partitions(self) -> Dict[str, object]:
        """Derive binary evidence from execution witnesses and their lineage.

        A BB can have both diagnostic and validated witnesses.  The latter
        wins for the final partition, while the former remains represented in
        ``diagnostic`` for audit purposes.  Legacy E0--E3 sets are never used
        as an unconditional validated fallback: old records without canonical
        execution facts are explicitly left unclassified.
        """
        validated: Set[int] = set()
        diagnostic: Set[int] = set()
        unclassified: Set[int] = set()
        status_by_phase: Dict[str, Dict[str, object]] = {}
        phase_execution_records = list(
            getattr(self, "phase_execution_records", []) or []
        )
        # r36 K4：灰账归因集合（在两分支外初始化，legacy 路径恒为空）。
        unclassified_reason_sets: Dict[str, Set[int]] = {}
        # r41 D4：相位分组同样在两分支外初始化（legacy 路径恒为空），
        # 末尾的压倒对账循环才能无条件引用。
        grouped: Dict[str, Dict[str, object]] = {}

        if phase_execution_records:
            for record in phase_execution_records:
                if not isinstance(record, Mapping):
                    continue
                phase_name = str(record.get("phase") or "unknown")
                group = grouped.setdefault(
                    phase_name,
                    {
                        "statuses": set(),
                        "reasons": set(),
                        "covered": set(),
                        "validated": set(),
                        "diagnostic": set(),
                        "unclassified": set(),
                        "records": 0,
                    },
                )
                group["records"] = int(group.get("records", 0) or 0) + 1
                try:
                    covered = self.validate_coverage(record.get("covered_bbs", []))
                except Exception:
                    covered = set()
                group["covered"].update(covered)
                status = str(record.get("status") or "unclassified").strip().lower()
                facts_available = coerce_bool(
                    record.get("execution_facts_available"), False
                )
                telemetry_complete = coerce_bool(
                    record.get("telemetry_complete"), False
                )
                record_reasons = [
                    str(reason)
                    for reason in list(record.get("reasons", []) or [])
                    if str(reason)
                ]
                # A compact record is trusted only when its producer supplied
                # the two explicit execution facts and did not leave a
                # contract failure attached to a supposedly validated status.
                # This protects the partition from stale or hand-written
                # legacy records that merely contain a status string.
                if status == VALIDATED_REPLAY and not compact_record_is_verified_validated(
                    record
                ):
                    status = "unclassified"
                    record_reasons.append("validated_record_not_verified")
                if status not in {
                    VALIDATED_REPLAY,
                    DIAGNOSTIC_REPLAY,
                    "unclassified",
                }:
                    status = "unclassified"
                    record_reasons.append("unknown_evidence_status")
                group["statuses"].add(status)
                group["reasons"].update(record_reasons)
                if status == VALIDATED_REPLAY:
                    validated.update(covered)
                    group["validated"].update(covered)
                elif status == DIAGNOSTIC_REPLAY:
                    diagnostic.update(covered)
                    group["diagnostic"].update(covered)
                else:
                    unclassified.update(covered)
                    group["unclassified"].update(covered)
                    for reason in record_reasons or ("missing_run_result",):
                        unclassified_reason_sets.setdefault(
                            str(reason), set()
                        ).update(covered)

            # These sets are maintained at insertion time and survive bounded
            # record retention.  They are still filtered through the same BB
            # oracle before being exposed.
            validated.update(
                self.validate_coverage(
                    getattr(self, "execution_evidence_validated_bbs", set()) or set()
                )
            )
            diagnostic.update(
                self.validate_coverage(
                    getattr(self, "execution_evidence_diagnostic_bbs", set()) or set()
                )
            )
            unclassified.update(
                self.validate_coverage(
                    getattr(self, "execution_evidence_unclassified_bbs", set()) or set()
                )
            )
            for phase_name, group in grouped.items():
                statuses = set(group.get("statuses", set()) or set())
                reasons = sorted(str(item) for item in group.get("reasons", set()) or set())
                if VALIDATED_REPLAY in statuses and (
                    DIAGNOSTIC_REPLAY in statuses or "unclassified" in statuses
                ):
                    phase_status = "mixed"
                elif VALIDATED_REPLAY in statuses:
                    phase_status = VALIDATED_REPLAY
                elif DIAGNOSTIC_REPLAY in statuses:
                    phase_status = DIAGNOSTIC_REPLAY
                else:
                    phase_status = "unclassified"
                status_by_phase[phase_name] = {
                    "status": phase_status,
                    "reasons": reasons,
                    "records": int(group.get("records", 0) or 0),
                    "covered_bbs": len(group.get("covered", set()) or set()),
                    "validated_bbs": len(group.get("validated", set()) or set()),
                    "diagnostic_bbs": len(group.get("diagnostic", set()) or set()),
                    "unclassified_bbs": len(group.get("unclassified", set()) or set()),
                }
        else:
            # Compatibility path for a runner created by an older version.
            # It intentionally does not promote legacy E1: without a
            # canonical execution fact, the status is unclassified.
            phase_coverage = getattr(self, "phase_coverage", {}) or {}
            phase_metadata = getattr(self, "phase_metadata", {}) or {}
            for phase_name, covered in phase_coverage.items():
                metadata = phase_metadata.get(phase_name, {})
                legacy = metadata.get("evidence_class") if isinstance(metadata, dict) else None
                status, reasons = classify_phase(
                    phase_name,
                    metadata,
                    legacy_evidence=legacy,
                )
                phase_valid = self.validate_coverage(covered)
                counted = not (
                    isinstance(metadata, dict)
                    and metadata.get("coverage_counted", True) is False
                )
                if not counted:
                    unclassified.update(phase_valid)
                elif status == VALIDATED_REPLAY:
                    validated.update(phase_valid)
                else:
                    diagnostic.update(phase_valid)
                status_by_phase[str(phase_name)] = {
                    "status": status,
                    "reasons": reasons,
                    "covered_bbs": len(phase_valid),
                    "counted": counted,
                    "legacy_fallback": True,
                }

        observed = self.validate_coverage(
            getattr(self, "global_coverage", set()) or set()
        )
        # Anything observed but absent from a typed witness remains explicitly
        # unclassified.  It is not silently folded into diagnostic coverage.
        unclassified.update(observed - validated - diagnostic - unclassified)
        validated &= observed
        diagnostic &= observed
        # The final view is mutually exclusive.  A later validated witness
        # supersedes an earlier diagnostic/unclassified observation for the
        # same BB, while the raw ``diagnostic`` set remains available for audit.
        diagnostic_only = diagnostic - validated
        unclassified = (unclassified - validated - diagnostic_only) & observed
        # r36 K4：最终分区的按原因灰账（纯增量字段，不改口径）。同一 BB
        # 可能被多条原因记到（多记录各执一词），所以各行之和可以大于
        # unclassified 总数；不在任何记录里的观测单独记 no_typed_witness。
        unclassified_reason_counts: Dict[str, int] = {
            str(reason): len(bbs & unclassified)
            for reason, bbs in unclassified_reason_sets.items()
            if bbs & unclassified
        }
        attributed = set()
        for bbs in unclassified_reason_sets.values():
            attributed |= bbs
        remainder = len(unclassified - attributed)
        if remainder:
            unclassified_reason_counts["no_typed_witness"] = remainder
        # r41 D4：相位级灰账与报告级互斥分区的显式对账。相位记录里的
        # unclassified BB 若在**其它相位**拿到更优见证（validated 压倒
        # diagnostic 压倒 unclassified），报告级 canonical_unclassified 就
        # 不再含它——两级读数表面矛盾（相位 50/55 vs 报告 0）实为压倒。
        # 逐相位披露被压倒数量，两级可互相复算：
        #   相位 unclassified_bbs − unclassified_superseded_bbs
        #     = 该相位 unclassified BB 落入报告级 validated/diagnostic 的
        #       数量之外的部分（多相位同 BB 按并集去重）。
        # 报告级仍是验收口径（canonical_* 为权威指标，相位级为审计面）。
        superseded_pool = validated | diagnostic_only
        for phase_name, group in grouped.items():
            phase_unclassified = set(group.get("unclassified", set()) or set())
            if not phase_unclassified:
                continue
            entry = status_by_phase.get(phase_name)
            if isinstance(entry, dict):
                entry["unclassified_superseded_bbs"] = len(
                    phase_unclassified & superseded_pool
                )
        return {
            "schema": EVIDENCE_SCHEMA,
            "validated": validated,
            "diagnostic": diagnostic,
            "diagnostic_only": diagnostic_only,
            "unclassified": unclassified,
            "status_by_phase": status_by_phase,
            "unclassified_reason_counts": unclassified_reason_counts,
        }

    def _coverage_evidence_partitions(self) -> Dict[str, object]:
        """Return raw evidence sets plus mutually exclusive report partitions."""
        evidence_sets = {
            evidence: self.validate_coverage(
                self.coverage_by_evidence.get(evidence, set())
            )
            for evidence in (
                EVIDENCE_E0,
                EVIDENCE_E1,
                EVIDENCE_E2,
                EVIDENCE_E3,
            )
        }
        witness = evidence_sets[EVIDENCE_E0] | evidence_sets[EVIDENCE_E1]
        e2_without_witness = evidence_sets[EVIDENCE_E2] - witness
        e3_without_witness = evidence_sets[EVIDENCE_E3] - witness
        e2_e3_shared = e2_without_witness & e3_without_witness
        return {
            "evidence_sets": evidence_sets,
            "witness": witness,
            "e2_only": e2_without_witness - e2_e3_shared,
            "e3_only": e3_without_witness - e2_e3_shared,
            "e2_e3_shared": e2_e3_shared,
            "counterfactual_only": e2_without_witness | e3_without_witness,
        }

    def _path_naturalization_ledger(self) -> PathNaturalizationLedger:
        ledger = getattr(self, "path_naturalization_ledger", None)
        if not isinstance(ledger, PathNaturalizationLedger):
            ledger = PathNaturalizationLedger()
            self.path_naturalization_ledger = ledger
        return ledger

    def _capture_evidence_class(
        self,
        source_path_signature: Iterable[Tuple[Tuple[int, int], object]],
        evidence_class: object = None,
    ) -> str:
        explicit = normalize_evidence_class(evidence_class)
        if explicit != EVIDENCE_UNKNOWN:
            return explicit
        signature = self._ordered_source_path_signature(
            tuple(source_path_signature or tuple())
        )
        # A later E1 witness for the same decisions does not prove that an old
        # snapshot has the same RAM, MMIO transaction, or timing state. Legacy
        # non-empty snapshots therefore remain E2 unless capture-time evidence
        # was stored explicitly.
        return EVIDENCE_E0 if not signature else EVIDENCE_E2

    def _snapshot_entry_evidence_class(
        self,
        snapshot_entry: Optional[PrefixReplaySnapshot],
    ) -> str:
        if snapshot_entry is None:
            return EVIDENCE_E0
        explicit = normalize_evidence_class(
            getattr(snapshot_entry, "evidence_class", EVIDENCE_UNKNOWN)
        )
        if explicit != EVIDENCE_UNKNOWN:
            return explicit
        return self._capture_evidence_class(
            self._scope_signature_from_snapshot_entry(snapshot_entry)
        )

    @staticmethod
    def _snapshot_entry_occurrence_prefix(
        snapshot_entry: Optional[PrefixReplaySnapshot],
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        if snapshot_entry is None:
            return tuple()
        trace = tuple(
            getattr(snapshot_entry, "source_occurrence_trace", tuple())
            or tuple()
        )
        try:
            prefix_len = max(
                0,
                min(
                    len(trace),
                    int(
                        getattr(
                            snapshot_entry,
                            "source_occurrence_prefix_len",
                            0,
                        )
                        or 0
                    ),
                ),
            )
        except (TypeError, ValueError):
            prefix_len = 0
        return trace[:prefix_len]

    def _extend_occurrence_signature(
        self,
        source_signature: Iterable[Tuple[Tuple[int, int], object]],
        events: Iterable[object],
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        """Append a snapshot-local occurrence stream to its entry prefix."""
        source = normalize_naturalization_signature(
            tuple(source_signature or tuple())
        )
        base_occurrences: Dict[int, int] = {}
        for key, _choice in source:
            address = int(key[0]) & 0xFFFFFFFF
            base_occurrences[address] = max(
                int(base_occurrences.get(address, 0) or 0),
                max(1, int(key[1])),
            )

        appended = []
        for event in events or []:
            address = int(getattr(event, "address", 0) or 0) & 0xFFFFFFFF
            if address <= 0:
                continue
            local_occurrence = max(
                1,
                int(getattr(event, "occurrence_index", 1) or 1),
            )
            appended.append((
                (
                    address,
                    int(base_occurrences.get(address, 0) or 0)
                    + local_occurrence,
                ),
                self._branch_event_evidence_choice(event),
            ))
        return normalize_naturalization_signature(
            tuple(list(source) + appended)
        )

    def _occurrence_prefix_before_snapshot(
        self,
        source_signature: Iterable[Tuple[Tuple[int, int], object]],
        events: Iterable[object],
        snapshot: object,
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        """Return only dynamic decisions observed before a captured state."""

        source = normalize_naturalization_signature(
            tuple(source_signature or tuple())
        )
        event_list = list(events or ())
        combined = self._extend_occurrence_signature(source, event_list)
        base_occurrences: Dict[int, int] = {}
        for key, _choice in source:
            address = int(key[0]) & 0xFFFFFFFF
            base_occurrences[address] = max(
                int(base_occurrences.get(address, 0) or 0),
                max(1, int(key[1])),
            )

        snapshot_address = int(getattr(snapshot, "address", 0) or 0) & 0xFFFFFFFF
        snapshot_occurrence = max(
            1,
            int(getattr(snapshot, "occurrence_index", 1) or 1),
        )
        target_key = (
            snapshot_address,
            int(base_occurrences.get(snapshot_address, 0) or 0)
            + snapshot_occurrence,
        )
        for index, (key, _choice) in enumerate(combined):
            if key == target_key:
                return combined[:index]

        snapshot_order = int(
            getattr(
                snapshot,
                "capture_order",
                getattr(snapshot, "order", 0),
            )
            or 0
        )
        if snapshot_order <= 0:
            return source
        preceding = [
            event
            for event in event_list
            if int(getattr(event, "order", 0) or 0) < snapshot_order
        ]
        return self._extend_occurrence_signature(source, preceding)

    @staticmethod
    def _compose_replay_path_signature(
        source_signature: Iterable[Tuple[Tuple[int, int], object]],
        verified_suffix: Iterable[Tuple[Tuple[int, int], object]],
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        return normalize_naturalization_signature(
            tuple(list(source_signature or tuple()) + list(verified_suffix or tuple()))
        )

    @staticmethod
    def _occurrence_trace_through_signature(
        occurrence_trace: Iterable[Tuple[Tuple[int, int], object]],
        signature: Iterable[Tuple[Tuple[int, int], object]],
        *,
        fallback_prefix: Iterable[Tuple[Tuple[int, int], object]] = tuple(),
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        trace = normalize_naturalization_signature(
            tuple(occurrence_trace or tuple())
        )
        expected = normalize_naturalization_signature(
            tuple(signature or tuple())
        )
        if not expected:
            return normalize_naturalization_signature(
                tuple(fallback_prefix or tuple())
            )

        cursor = 0
        last_index = -1
        for expected_key, expected_choice in expected:
            found_index = None
            for index in range(cursor, len(trace)):
                observed_key, observed_choice = trace[index]
                if observed_key != expected_key:
                    continue
                if isinstance(expected_choice, bool):
                    choice_matches = (
                        isinstance(observed_choice, bool)
                        and bool(observed_choice) == bool(expected_choice)
                    )
                elif isinstance(expected_choice, int):
                    choice_matches = (
                        isinstance(observed_choice, int)
                        and not isinstance(observed_choice, bool)
                        and int(observed_choice) == int(expected_choice)
                    )
                else:
                    choice_matches = observed_choice == expected_choice
                if choice_matches:
                    found_index = index
                    break
            if found_index is None:
                return normalize_naturalization_signature(
                    tuple(fallback_prefix or tuple())
                )
            cursor = int(found_index) + 1
            last_index = int(found_index)
        return trace[: last_index + 1]

    def _register_forced_path_obligation(
        self,
        signature: Iterable[Tuple[Tuple[int, int], object]],
        *,
        target_bbs: Iterable[int],
        discovered_bbs: Iterable[int],
        discovery_trace_signature: Iterable[
            Tuple[Tuple[int, int], object]
        ] = tuple(),
        source_phase: str,
    ) -> bool:
        discovery = self._scheduler_component(
            "obligation_discovery", ObligationDiscovery
        )
        return discovery.register_forced_path_obligation(
            signature,
            target_bbs=target_bbs,
            discovered_bbs=discovered_bbs,
            discovery_trace_signature=discovery_trace_signature,
            source_phase=source_phase,
        )

    def _remember_naturalization_fact(
        self,
        *,
        branch_key: Tuple[int, int],
        branch_choice: object,
        constraints: Iterable[BranchConstraintCandidate],
        scope_signature: Iterable[Tuple[Tuple[int, int], object]],
        source_phase: str,
        strategy: str,
        constraint_feedback: Optional[Dict[str, object]],
        paired_control: bool,
        local_success: bool,
    ) -> bool:
        if not getattr(self, "semantic_obligation_enabled", True):
            return False
        normalized_constraints = tuple(
            candidate.normalized()
            for candidate in constraints or tuple()
            if isinstance(candidate, BranchConstraintCandidate)
        )
        environment_constraints = [
            candidate
            for candidate in normalized_constraints
            if candidate.is_environment_fact
        ]
        feedback = dict(constraint_feedback or {})
        consumed = bool(
            normalized_constraints
            and len(environment_constraints) == len(normalized_constraints)
            and feedback.get("all_constraint_reads_matched")
        )
        normalized_scope = normalize_naturalization_signature(
            tuple(scope_signature or tuple())
        )
        fact = NaturalizationFact(
            branch_key=(int(branch_key[0]), int(branch_key[1])),
            choice=branch_choice,
            constraints=normalized_constraints,
            scope_signature=normalized_scope,
            source_phase=str(source_phase or ""),
            strategy=str(strategy or ""),
            paired_control=bool(paired_control),
            candidate_consumed=consumed,
            local_success=bool(local_success),
        )
        # A paired local replay establishes a candidate fact, not an entry-level
        # path witness.  Path evidence is upgraded only by the force-free
        # naturalization gate below.
        return self._path_naturalization_ledger().register_fact(fact)

    @staticmethod
    def _branch_event_evidence_choice(event: object) -> object:
        condition = _normalize_mnemonic(getattr(event, "condition", ""))
        if _is_call_frontier_mnemonic(condition):
            try:
                return int(getattr(event, "target", 0) or 0) & ~1
            except (TypeError, ValueError):
                return getattr(event, "target", None)
        if condition in SWITCH_DISPATCH_MNEMONICS:
            original_index = getattr(event, "original_index", None)
            if original_index is not None:
                try:
                    return int(original_index)
                except (TypeError, ValueError):
                    return original_index
        return bool(getattr(event, "original_taken", False))

    def _remember_branch_direction_evidence(
        self,
        events: Iterable[object],
        evidence_class: str,
    ) -> int:
        evidence = str(evidence_class or "")
        if evidence not in {EVIDENCE_E0, EVIDENCE_E1, EVIDENCE_E2, EVIDENCE_E3}:
            return 0
        if not hasattr(self, "branch_direction_evidence"):
            self.branch_direction_evidence = {}
        added = 0
        for event in events or []:
            if not bool(getattr(event, "original_direction_known", True)):
                # A dynamic successor set is useful for scheduling, but it is
                # not a witness for either the observed or natural direction.
                continue
            address = int(getattr(event, "address", 0) or 0)
            if address <= 0:
                continue
            choice = self._branch_event_evidence_choice(event)
            if isinstance(choice, bool):
                choice_key = ("bool", bool(choice))
            elif isinstance(choice, int):
                choice_key = ("int", int(choice))
            else:
                choice_key = (type(choice).__name__, str(choice))
            by_choice = self.branch_direction_evidence.setdefault(address, {})
            classes = by_choice.setdefault(choice_key, set())
            before = len(classes)
            classes.add(evidence)
            added += int(len(classes) > before)
        return added

    @staticmethod
    def _serialize_constraint_candidate(candidate) -> Dict[str, object]:
        return serialize_constraint_candidate(candidate)

    @staticmethod
    def _normalize_constraint_candidate(candidate) -> Optional[BranchConstraintCandidate]:
        return normalize_constraint_candidate(candidate)

    def _branch_event_key(self, event) -> Tuple[int, int]:
        return (
            int(getattr(event, "address", 0)),
            int(getattr(event, "occurrence_index", 1)),
        )

    def _branch_choice_sort_key(self, key: Tuple[int, int]) -> Tuple[int, int, Tuple[int, int]]:
        event = self.known_main_branch_events.get(key)
        if event is None:
            return (0, 0, key)
        return (
            int(getattr(event, "first_depth", getattr(event, "depth", 0))),
            int(getattr(event, "first_order", getattr(event, "order", 0))),
            key,
        )

    def _branch_root_key_for_start(self, branch_bb_start: int) -> Tuple[int, int]:
        candidates = [
            key
            for key, event in self.known_main_branch_events.items()
            if int(getattr(event, "address", 0)) == int(branch_bb_start)
        ]
        if not candidates:
            return (int(branch_bb_start), 1)
        return min(candidates, key=self._branch_choice_sort_key)

    def _ordered_source_path_signature(
        self,
        signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        return tuple(
            sorted(
                tuple(signature or tuple()),
                key=lambda item: self._branch_choice_sort_key(item[0]),
            )
        )

    @staticmethod
    def _ordered_replay_exact_occurrence_enabled() -> bool:
        return ordered_replay_exact_occurrence_enabled()

    @staticmethod
    def _root_provenance_replay_order_enabled() -> bool:
        return root_provenance_replay_order_enabled()

    @staticmethod
    def _scoped_subsequence_match_enabled() -> bool:
        return scoped_subsequence_match_enabled()

    @staticmethod
    def _root_snapshot_variant_limit() -> int:
        return root_snapshot_variant_limit()

    @staticmethod
    def _root_provenance_signature_limit() -> int:
        return root_provenance_signature_limit()

    @staticmethod
    def _direct_call_snapshot_variant_limit() -> int:
        # Zero is intentionally unbounded for compatibility with historical runs.
        return max(
            0,
            _env_int("LSGEMU_DIRECT_CALL_SNAPSHOT_VARIANTS_PER_ADDRESS", 0),
        )

    @staticmethod
    def _stream_summary_snapshot_variant_limit() -> int:
        return max(
            1,
            _env_int("LSGEMU_STREAM_SUMMARY_ENTRY_VARIANTS_PER_ADDRESS", 8),
        )

    @staticmethod
    def _prefix_snapshot_limit() -> int:
        # Zero disables prefix checkpoint capture, matching the existing contract.
        return max(0, _env_int("LSGEMU_PREFIX_SNAPSHOT_LIMIT", 96))

    @staticmethod
    def _dfs_trunk_first_enabled() -> bool:
        """P1 (r7)：主干优先调度键开关（默认关，保持历史行为便于配对 A/B）。"""
        return _env_flag("LSGEMU_DFS_TRUNK_FIRST", "0")

    @staticmethod
    def _retry_dispatch_order_score(
        historical_score: tuple,
        *,
        depth: int,
        trunk_first: bool,
    ) -> tuple:
        """P1 (r7)：retry 派发队列的排序键重排。

        历史语义（17 元组）：静态未覆盖后继数为主键（广而浅贪心），深度以
        ``-len(prefix)`` 作倒数第二位 ⇒ 同分时浅者胜。主干优先语义：深度
        （前缀分支点数）升为主键，未覆盖后继数降为次键，其余相对次序不变；
        原尾部的 ``-depth`` 与新主键矛盾，移除，仅保留 root_key 决胜。
        """
        if not trunk_first:
            return historical_score
        body = historical_score[:-2]
        root_key = historical_score[-1]
        return (int(depth),) + body + (root_key,)

    def _dfs_anchor_pool_or_none(self) -> Optional[DFSAnchorPool]:
        """r7 P0-B：惰性创建锚点池；冷层目录来自入口设置的 run storage env。"""
        pool = getattr(self, "dfs_anchor_pool", None)
        if pool is not None:
            return pool
        if dfs_anchor_limit() <= 0:
            return None
        cold_store = None
        storage_dir = snapshot_storage_directory(None)
        if storage_dir is not None:
            try:
                cold_store = DFSColdAnchorStore(storage_dir)
            except OSError:
                cold_store = None
        pool = DFSAnchorPool(cold_store=cold_store)
        self.dfs_anchor_pool = pool
        return pool

    @property
    def dfs_anchor_snapshots(self) -> Dict[Tuple[tuple, Tuple[int, int]], DFSAnchorEntry]:
        """任务书口径的锚点容器名；真实存储在 DFSAnchorPool.anchors。"""
        pool = getattr(self, "dfs_anchor_pool", None)
        return pool.anchors if pool is not None else {}

    def _reset_reservoir_dispatch_state(self) -> None:
        """清空阶段间调度派发状态（原 load_reservoir_state 内联块，r7 抽方法以便行为测试）。

        刻意不清 ``reservoir_prefix_snapshots`` 与 ``dfs_anchor_pool``：前缀快照池
        与 DFS 锚点池按插入序/锚点序自我管理，跨阶段存活是回退语义的一部分。
        """
        self.reservoir_task_queue.clear()
        self.reservoir_deferred_tasks.clear()
        self.reservoir_scoped_probe_tasks.clear()
        self.reservoir_explored_paths.clear()
        self.reservoir_incomplete_paths.clear()
        self.reservoir_pending_paths.clear()
        self.reservoir_task_contexts.clear()
        self.reservoir_explored_edges.clear()
        self.reservoir_root_budget_used.clear()
        self.reservoir_roots_started.clear()
        self.reservoir_discovered_branch_keys.clear()
        self.reservoir_new_branch_points.clear()
        self.reservoir_discovery_events.clear()
        self.reservoir_discovery_events_truncated = 0
        self.reservoir_state_signatures.clear()
        self.reservoir_saturated_edges.clear()
        self.reservoir_interrupt_contexts.clear()
        self.reservoir_hotset_retried_paths.clear()
        self.deadlock_failed_directions.clear()
        self.reservoir_initialized = False

    def _dfs_consider_prefix_anchor(
        self, entry: Optional[PrefixReplaySnapshot]
    ) -> Optional[DFSAnchorEntry]:
        """P0-B 挂钩：把刚登记的前缀快照按深度步进纳入锚点候选。

        前缀约束表快照 = 以该前缀签名为 scope 时重放引擎会重新注入的
        runner scoped 约束子集（R5 §4.3 缺口 4：这些输入假设必须随锚点
        保存，翻转重放的等价性才可论证）。捕获失败 ⇒ 表为 None ⇒
        该锚点 flip_eligible=False（拒绝翻转而不是凑合）。

        r9 C 件修正：①空前缀（入口快照）不登记——它成不了翻转主干
        （trunk_items 为空 ⇒ planner 早退 planned=0），还会占掉深度步进
        额度；②步进深度改用**前缀长度**（翻转真正导航的坐标）。原先的
        branch_depth 是含轮询环迭代的事件深度——90min 长跑里被 a6 环
        顶到 2729，令首个跨门槛的候选恰是空前缀入口快照、其后 21 个
        候选全部 depth<2733 被拒（considered=22/registered=1）。
        """
        pool = self._dfs_anchor_pool_or_none()
        if pool is None or entry is None:
            return None
        prefix_signature = tuple(
            getattr(entry, "prefix_signature", tuple()) or tuple()
        )
        if not prefix_signature:
            pool.stats["skipped_empty_prefix"] = (
                int(pool.stats.get("skipped_empty_prefix", 0) or 0) + 1
            )
            return None
        prefix_constraint_tables: Optional[Dict[str, object]] = None
        try:
            constraint_items = self._matching_scoped_branch_constraints(
                prefix_signature
            )
            prefix_constraint_tables = {
                "runner_scoped_constraints": list(constraint_items or [])
            }
        except Exception:
            prefix_constraint_tables = None
        anchor = pool.consider(
            entry,
            depth=len(prefix_signature),
            prefix_constraint_tables=prefix_constraint_tables,
        )
        if anchor is not None:
            self._record_snapshot_resource_event("dfs_anchor_registered")
        return anchor

    def _configure_semantic_replay_defaults(self, emulator) -> None:
        """r22：采集/锚点翻转共用的执行语义配置（campaign semantic_entry_prefix 同款）。

        函数摘要（``_configure_replay_skip_function_returns``）+ 流 token
        种子（``_stream_branch_token_seeds``）。摘要/种子不设 forced
        choices、不改控制流方向；campaign 基线阶段（r10 现场 220→850 BB
        的覆盖大跳变）用的正是这组配置。
        """
        self._configure_replay_skip_function_returns(
            emulator,
            include_time=True,
            exclude_stream_input_summaries=False,
        )
        token_seeds = self._stream_branch_token_seeds(max_tokens=64)
        if token_seeds:
            combined_seed = b"".join(seed for seed in token_seeds if seed)
            if combined_seed:
                emulator.stream_input_default_bytes = combined_seed[:4096]
                emulator.stream_input_state.clear()

    # ------------------------------------------------------------------
    # r34 I1：函数摘要的覆盖记账审计
    # ------------------------------------------------------------------
    def _summary_skip_coverage_accounting(
        self,
        emulator: object,
        covered: Iterable[int],
    ) -> Dict[str, object]:
        """把「函数摘要跳过的函数体」从 canonical 覆盖里单列出来（只读审计）。

        口径与 ``coverage_counting_rule`` 一字对应：摘要跳过的 callee **不得**
        计入 covered。本方法不改任何覆盖数字，只把该规则的执行结果做成可复算的
        数字与逐 BB 清单：

          * ``skipped_entry_bbs``：本相位被摘要拦截的入口 BB（会计账 hook 的
            ``is_skipped_entry`` 明确排除，故不应出现在 covered 里）；
          * ``credited_callee_body_bbs``：本相位 covered 中落在**被跳过符号区间**
            内的 BB —— 即「函数体没执行却计入 covered」的候选。按契约应为空；
            非空时必须逐 BB 解释来源（另相位真实执行 / 入口本身在册）。
          * ``skipped_entry_bbs_in_coverage``：入口 BB 出现在 covered 里的那些。
            入口 BB 是**真实被执行到的**（hook 在 entry 处触发过），只是被排除
            出本相位记账；若它仍在 covered，说明另有真实执行证据，不算虚记。
        """
        try:
            stats = dict(getattr(emulator, "skip_function_stats", {}) or {})
            entry_bbs = {
                int(bb) & ~1
                for bb in (getattr(emulator, "skipped_function_entry_bbs", set()) or set())
            }
        except Exception as exc:  # 审计通道绝不打断相位
            return {
                "schema": "lsgemu.summary_skip_accounting.v1",
                "error": f"{type(exc).__name__}:{exc}",
            }

        covered_set = {int(bb) & ~1 for bb in (covered or set())}
        applied = int(stats.get("applied", 0) or 0)
        by_symbol = {str(k): int(v or 0) for k, v in (stats.get("by_symbol") or {}).items()}

        # 被跳过符号的函数区间：符号起址 → 下一个符号起址。
        body_ranges: List[Tuple[int, int, str]] = []
        symbols_by_name = getattr(self.prepared, "symbols_by_name", None) or {}
        symbols_by_addr = getattr(self.prepared, "symbols_by_addr", None) or {}
        addr_sorted = sorted(int(a) for a in symbols_by_addr)
        for symbol in by_symbol:
            start = symbols_by_name.get(symbol)
            if start is None:
                continue
            start = int(start) & ~1
            nxt = next((a for a in addr_sorted if a > start), None)
            body_ranges.append((start, int(nxt) if nxt else start + 0x10000, symbol))

        credited: List[str] = []
        credited_by_symbol: Dict[str, List[str]] = {}
        for start, end, symbol in body_ranges:
            for bb in covered_set:
                if start <= bb < end:
                    entry = bb in entry_bbs
                    text = f"0x{bb:08x}" + ("(entry)" if entry else "")
                    credited.append(text)
                    credited_by_symbol.setdefault(symbol, []).append(text)

        non_entry_credited = sorted(
            bb for bb in credited if not bb.endswith("(entry)")
        )

        return {
            "schema": "lsgemu.summary_skip_accounting.v1",
            "enabled": bool(getattr(emulator, "skip_function_returns", None)),
            "installed": int(stats.get("installed", 0) or 0),
            "applied": applied,
            "by_symbol": by_symbol,
            "skipped_entry_bbs": sorted(f"0x{bb:08x}" for bb in entry_bbs),
            "skipped_entry_bbs_in_coverage": sorted(
                f"0x{bb:08x}" for bb in (entry_bbs & covered_set)
            ),
            "credited_callee_body_bbs": sorted(set(credited)),
            "credited_callee_body_bbs_non_entry": non_entry_credited,
            "credited_callee_body_by_symbol": {
                k: sorted(set(v)) for k, v in credited_by_symbol.items()
            },
            "callee_body_credit_is_zero": not non_entry_credited,
            "policy": (
                "摘要跳过的 callee 体不计入本相位 covered（is_skipped_entry 排除入口，"
                "体 BB 未被 hook 观测）；被跳过符号区间内若仍有在册 BB，需另有真实执行证据"
            ),
        }

    # ------------------------------------------------------------------
    # r34 I3：逐墙取证（默认关，LSGEMU_WALL_FORENSICS=1 打开）
    # ------------------------------------------------------------------
    def _enclosing_symbol(self, address: int) -> str:
        """返回包含该地址的符号名（取不超过它的最大符号起址）。

        直接查 ``symbols_by_addr[addr]`` 只能命中函数入口；墙的停点通常落在
        函数体中段（例如 memset 的 `bx lr`），所以这里做区间归属。
        """
        try:
            table = getattr(self.prepared, "symbols_by_addr", None) or {}
            if not table:
                return ""
            addrs = getattr(self, "_wall_symbol_addrs_cache", None)
            if addrs is None:
                addrs = sorted(int(a) for a in table)
                self._wall_symbol_addrs_cache = addrs
            index = bisect.bisect_right(addrs, int(address) & ~1) - 1
            if index < 0:
                return ""
            return str(table[addrs[index]] or "")
        except Exception:
            return ""

    def _wall_forensics(
        self,
        emulator: object,
        run_result: Mapping[str, object],
        *,
        tail: int = 32,
    ) -> Dict[str, object]:
        """把「本次重放停在哪、为什么停、停点依赖什么」做成一段可引用的证据。

        复用 r33 的取证口径（``LSGEMU_MMIO_SOURCE_AUDIT`` 的读来源计数 +
        循环分类器/终态 sink 表），只增不改：不参与任何覆盖记账。

        默认**关**（``LSGEMU_WALL_FORENSICS=1`` 打开），以免改动既有报告
        的逐位可比性（r33 的验收线是「零注入臂与豁免臂逐位相同」）。
        """
        if str(os.environ.get("LSGEMU_WALL_FORENSICS", "0")).strip().lower() not in {
            "1", "true", "yes", "on",
        }:
            return {}
        result: Dict[str, object] = {"schema": "lsgemu.wall_forensics.v1"}
        try:
            registers = dict((run_result or {}).get("registers") or {})
            result["stop_reason"] = str((run_result or {}).get("stop_reason") or "")
            result["stop_registers"] = registers
            pc_text = str(registers.get("pc") or "")
            stop_pc = int(pc_text, 16) if pc_text else None
            if stop_pc is not None:
                resolved_bb = self.prepared.resolve_basic_block(stop_pc)
                bb = int(resolved_bb if resolved_bb is not None else stop_pc) & ~1
                result["stop_pc"] = f"0x{bb:08x}"
                result["stop_symbol"] = self._enclosing_symbol(bb)
                sinks = getattr(emulator, "terminal_self_loop_bbs", set()) or set()
                result["stop_pc_is_terminal_self_loop"] = int(bb) in {
                    int(x) & ~1 for x in sinks
                }
            lr_text = str(registers.get("lr") or "")
            if lr_text:
                lr = int(lr_text, 16) & ~1
                result["return_symbol"] = self._enclosing_symbol(lr)
        except Exception as exc:
            result["stop_analysis_error"] = f"{type(exc).__name__}:{exc}"

        try:
            history = [int(bb) & ~1 for bb in (getattr(emulator, "bb_history", None) or [])]
            window = history[-max(1, int(tail)) :]
            counts: Counter = Counter(window)
            result["tail_bb_window"] = len(window)
            result["tail_bb_unique"] = len(counts)
            result["tail_bb_top"] = [
                {"bb": f"0x{bb:08x}",
                 "symbol": self._enclosing_symbol(bb),
                 "visits": int(n)}
                for bb, n in counts.most_common(8)
            ]
        except Exception as exc:
            result["tail_analysis_error"] = f"{type(exc).__name__}:{exc}"

        try:
            classifier = getattr(emulator, "loop_classifier", None)
            loops = getattr(classifier, "loop_heads", None) or {}
            hot = sorted(
                (
                    (int(getattr(info, "iteration_count", 0) or 0), int(head))
                    for head, info in loops.items()
                ),
                reverse=True,
            )[:6]
            result["hottest_loops"] = [
                {"bb": f"0x{head:08x}", "iterations": int(it),
                 "symbol": self._enclosing_symbol(head)}
                for it, head in hot
            ]
        except Exception as exc:
            result["loop_analysis_error"] = f"{type(exc).__name__}:{exc}"
        return result

    # ------------------------------------------------------------------
    # r34 I2：输入轨迹记录 / 真实重放校验（默认关）
    # ------------------------------------------------------------------
    @staticmethod
    def _input_trace_artifact_paths() -> Tuple[str, str]:
        return (
            str(os.environ.get("LSGEMU_INPUT_TRACE_PATH", "") or "").strip(),
            str(os.environ.get("LSGEMU_INPUT_REPLAY_PATH", "") or "").strip(),
        )

    @staticmethod
    def _load_input_trace_items(path: str) -> List[Dict[str, int]]:
        """读取记录的 MMIO 读值序列；格式见 ``_dump_input_trace``。"""
        payload = json.loads(Path(path).read_text())
        if isinstance(payload, Mapping):
            payload = payload.get("reads") or []
        items: List[Dict[str, int]] = []
        for item in payload or []:
            if not isinstance(item, Mapping):
                continue
            try:
                items.append(
                    {
                        "pc": int(item["pc"]) & 0xFFFFFFFF,
                        "address": int(item["address"]) & 0xFFFFFFFF,
                        # 原样保留：0 表示生产者是 bridge 镜像（无 occurrence 语义），
                        # 重放侧改用 (pc, address) 级约束，而不是硬塞成 1。
                        "occurrence": int(item.get("occurrence", 0) or 0),
                        "value": int(item["value"]) & 0xFFFFFFFF,
                    }
                )
            except (KeyError, TypeError, ValueError):
                continue
        return items

    def _apply_recorded_input_trace(
        self,
        mmio_handler: EnhancedMMIOHandler,
        phase_name: str,
    ) -> Dict[str, object]:
        """I2 上半：把记录下来的读值装成 occurrence 级约束（真实重放校验）。

        只钉住 (read_pc, address, occurrence) 三元组；控制流一旦分叉，未命中的
        条目由原模型继续供值——这正是「同输入」的可判定边界，报告里要如实写。
        """
        _trace_out, replay_path = self._input_trace_artifact_paths()
        if not replay_path:
            return {}
        try:
            items = self._load_input_trace_items(replay_path)
        except Exception as exc:
            logger.warning("r34 I2 输入轨迹读取失败 %s: %s", replay_path, exc)
            return {"input_trace_replay_path": replay_path, "input_trace_replay_error": str(exc)}
        occurrence_scoped = site_scoped = 0
        for item in items:
            if item["occurrence"] > 0:
                mmio_handler.add_occurrence_constraint(
                    item["pc"],
                    item["address"],
                    item["occurrence"],
                    item["value"],
                    added_by="r34_input_trace_replay",
                )
                occurrence_scoped += 1
            else:
                # bridge 镜像条目没有 occurrence 语义（生产者写 0）⇒ 退到读点级。
                mmio_handler.add_pc_constraint(
                    item["pc"],
                    item["address"],
                    item["value"],
                    added_by="r34_input_trace_replay",
                )
                site_scoped += 1
        logger.warning(
            "r34 I2 输入重放: %s 装载 %d 条读值约束（occurrence %d / 读点 %d）",
            phase_name, len(items), occurrence_scoped, site_scoped,
        )
        return {
            "input_trace_replay_path": replay_path,
            "input_trace_replay_items": len(items),
            "input_trace_replay_occurrence_scoped": occurrence_scoped,
            "input_trace_replay_site_scoped": site_scoped,
        }

    def _dump_input_trace(
        self,
        mmio_handler: EnhancedMMIOHandler,
        phase_name: str,
        run_result: Mapping[str, object],
    ) -> Dict[str, object]:
        """I2 下半：把本相位真实发生的 MMIO 读值序列落盘，供后续真实重放。"""
        trace_out, _replay_path = self._input_trace_artifact_paths()
        if not trace_out:
            return {}
        reads: List[Dict[str, int]] = []
        try:
            for entry in list(getattr(mmio_handler, "access_occurrence_history", []) or []):
                try:
                    pc, address, value, is_read, occurrence = entry
                except (TypeError, ValueError):
                    continue
                if not is_read:
                    continue
                reads.append(
                    {
                        "pc": int(pc) & 0xFFFFFFFF,
                        "address": int(address) & 0xFFFFFFFF,
                        "occurrence": int(occurrence),
                        "value": int(value) & 0xFFFFFFFF,
                    }
                )
        except Exception as exc:
            logger.warning("r34 I2 输入轨迹采集失败: %s", exc)
            return {"input_trace_error": str(exc)}
        payload = {
            "schema": "lsgemu.input_trace.v1",
            "phase": str(phase_name),
            "stop_reason": str((run_result or {}).get("stop_reason") or ""),
            "read_count": len(reads),
            "reads": reads,
        }
        try:
            Path(trace_out).write_text(json.dumps(payload))
        except Exception as exc:
            logger.warning("r34 I2 输入轨迹写盘失败 %s: %s", trace_out, exc)
            return {"input_trace_write_error": str(exc)}
        logger.warning("r34 I2 输入轨迹: %s 落盘 %d 条读值", phase_name, len(reads))
        return {"input_trace_path": trace_out, "input_trace_read_count": len(reads)}

    def collect_dfs_anchors(
        self,
        *,
        max_instructions: int = 600000,
        timeout_seconds: Optional[float] = None,
        enable_function_summaries: bool = True,
        phase_name: str = "dfs_anchor_collect",
        dump_directory: Optional[str] = None,
    ) -> Dict[str, object]:
        """r22：非 campaign 场景的锚点采集——一次有界重放填充锚点池。

        语义 = ``_dfs_flip_replay_once`` 的 force-free 重放原语（同款临时
        emulator/护栏/快转政策）+ ``semantic_entry_prefix`` 阶段的函数摘要
        与流 token 种子配置（campaign 覆盖大跳变的来源，r10 现场 220→850
        BB）。重放结束（``emulator.run`` 内部已收尾快照血统）后，把顺序
        occurrence 事件逐点配对最近发生号快照，经
        ``_dfs_consider_prefix_anchor`` 按深度步进登记进锚点池——与
        campaign 的 ``remember_prefix_snapshot`` 通路完全同一登记语义。

        ``dump_directory`` 给定时把整池落盘（``DFSAnchorPool.dump``），
        供后续进程 ``DFSAnchorPool.load`` 复用。全程不设 forced choices、
        不装循环强转（与翻转重放同一红线）；摘要/快转不改控制流方向。
        """
        pool = self._dfs_anchor_pool_or_none()
        if pool is None:
            return {"error": "anchor_pool_disabled"}
        stage = self._temp_stage_for(phase_name)
        emulator = None
        temp_mmio = None
        temp_tracer = None
        run_result: Dict[str, object] = {"stop_reason": "not_started"}
        covered: Set[int] = set()
        report: Dict[str, object] = {}
        replay_started = time.perf_counter()
        try:
            emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=None,
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=stage,
            )
            self._configure_emulator_feedback(emulator)
            emulator.enable_branch_snapshot = True
            emulator.enable_loop_intervention = False
            emulator.dfs_flip_deterministic_fast_forward = (
                dfs_flip_fast_forward_enabled()
            )
            if enable_function_summaries:
                self._configure_semantic_replay_defaults(emulator)
            temp_mmio = EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            temp_tracer = self._new_temp_register_tracer(emulator)
            with self.guided_modules(temp_mmio, temp_tracer), self.capture_coverage(
                emulator
            ) as temp_covered:
                raw_run_result = emulator.run(
                    entry_point=self.prepared.entry_point,
                    max_instructions=max_instructions,
                    timeout_seconds=timeout_seconds,
                )
                run_result = self._normalize_replay_run_result(
                    raw_run_result,
                    execution_started=True,
                )
                covered = self.validate_coverage(temp_covered)
            report["stop_reason"] = str(run_result.get("stop_reason") or "")
            report["covered_bbs"] = len(covered)
            report["covered_bb_list"] = sorted(int(bb) for bb in covered)

            # 采集：顺序 occurrence 事件 × 最近发生号快照 → 锚点池。
            manager = getattr(emulator, "branch_snapshot_manager", None)
            events = list(
                manager.get_ordered_occurrence_events()
            ) if manager is not None else []
            path_items: List[Tuple[Tuple[int, int], object]] = []
            for event in events:
                item = self._occurrence_path_item(event)
                if item is not None:
                    path_items.append(item)
            try:
                self._remember_main_branch_events(
                    events,
                    evidence_class=EVIDENCE_E2,
                )
            except Exception:
                self._record_snapshot_resource_event(
                    "dfs_anchor_collect_event_errors"
                )
            snapshots_by_address: Dict[int, List[object]] = {}
            for snapshot in self._ordered_replay_snapshots(emulator):
                address = int(getattr(snapshot, "address", 0) or 0)
                if address:
                    snapshots_by_address.setdefault(address, []).append(snapshot)
            considered = 0
            for index, (key, _choice) in enumerate(path_items):
                candidates = snapshots_by_address.get(int(key[0]) & 0xFFFFFFFF)
                if not candidates:
                    continue
                event_occurrence = int(key[1])
                snapshot = min(
                    candidates,
                    key=lambda item: abs(
                        int(getattr(item, "occurrence_index", 1) or 1)
                        - event_occurrence
                    ),
                )
                prefix_signature = self._ordered_source_path_signature(
                    tuple(path_items[:index])
                )
                if not prefix_signature:
                    continue
                considered += 1
                entry = PrefixReplaySnapshot(
                    prefix_signature=prefix_signature,
                    next_branch_key=(int(key[0]) & 0xFFFFFFFF, int(key[1])),
                    snapshot=snapshot,
                    mmio_state=self._interrupt_context_mmio_state(snapshot),
                    branch_depth=index,
                    origin="prefix",
                    evidence_class=EVIDENCE_E2,
                )
                try:
                    self._dfs_consider_prefix_anchor(entry)
                except Exception:
                    self._record_snapshot_resource_event(
                        "dfs_anchor_collect_errors"
                    )
            report["replay_events"] = len(path_items)
            report["anchor_candidates"] = considered
            report["path_items"] = [
                [int(key[0]) & 0xFFFFFFFF, int(key[1]),
                 (bool(choice) if isinstance(choice, bool) else int(choice))]
                for key, choice in path_items
            ]
            # r32 D1：与 campaign 翻转 pass 同款兜底登记，让一次有界采集
            # 也能给出「有无候选跨过 stride / 最深可用是几」的完整账。
            try:
                reported_fallback = pool.promote_deepest_below_stride()
            except Exception:
                reported_fallback = None
            report["anchor_fallback"] = {
                "promoted_depth": (
                    None if reported_fallback is None else int(reported_fallback.depth)
                ),
                "promoted_flip_eligible": (
                    None
                    if reported_fallback is None
                    else bool(reported_fallback.flip_eligible)
                ),
            }
            report["anchor_pool"] = pool.statistics()
            if dump_directory:
                try:
                    dump_store = DFSColdAnchorStore(dump_directory)
                    report["anchor_dump"] = dict(pool.dump(dump_store))
                    report["anchor_dump"]["directory"] = str(
                        dump_store.directory
                    )
                except (OSError, ValueError) as exc:
                    report["anchor_dump"] = {"error": str(exc)[:200]}
        except Exception as exc:
            run_result = self._materialize_replay_failure_result(
                "dfs_anchor_collect_exception",
                execution_started=True,
                execution_error=exc,
            )
            report["error"] = f"{type(exc).__name__}:{str(exc)[:400]}"
        finally:
            if emulator is not None:
                try:
                    self._finalize_temp_replay(
                        emulator,
                        mmio_handler=temp_mmio,
                        register_tracer=temp_tracer,
                        run_result=run_result,
                        stage_name=stage,
                    )
                except Exception:
                    self._record_snapshot_resource_event(
                        "dfs_anchor_collect_finalize_errors"
                    )
        report["replay_wall_s"] = round(
            max(0.0, time.perf_counter() - replay_started), 1
        )
        return report

    def _occurrence_path_item(
        self, event: object
    ) -> Optional[Tuple[Tuple[int, int], object]]:
        """把 occurrence 事件归一成 (key, choice) 路径项（None = 非方向性）。"""
        condition = str(getattr(event, "condition", "") or "").upper()
        try:
            if condition in {"BX", "BXJ", "BLX", "CALL"}:
                target = int(getattr(event, "target", 0) or 0)
                if target:
                    return (
                        (
                            int(getattr(event, "address", 0) or 0) & 0xFFFFFFFF,
                            max(1, int(getattr(event, "occurrence_index", 1) or 1)),
                        ),
                        (target & ~1),
                    )
            taken = getattr(event, "original_taken", None)
            if isinstance(taken, bool):
                return (
                    (
                        int(getattr(event, "address", 0) or 0) & 0xFFFFFFFF,
                        max(1, int(getattr(event, "occurrence_index", 1) or 1)),
                    ),
                    bool(taken),
                )
        except (TypeError, ValueError):
            return None
        return None

    def _flip_no_candidate_evidence(
        self, branch_key: Tuple[int, int]
    ) -> Dict[str, object]:
        """r11 ④：无外部输入候选的分类证据（静态锥分类 + 动态依赖摘要）。

        供翻转账本 ``no_external_input_directions[].evidence`` 使用：论文口径
        要求「工具限制」与「不可达」可区分，且工具限制须可归因——锥分类
        （mmio/const/internal_ram/call_return/undefined_in_window）说明卡在
        哪一类依赖上，而不是笼统的「求解不出」。
        """
        branch_bb = int(branch_key[0]) & 0xFFFFFFFF
        evidence: Dict[str, object] = {}
        try:
            branch_instruction = self._branch_instruction(branch_bb) or {}
            branch_pc = int(
                branch_instruction.get("address")
                or getattr(
                    self.known_main_branch_events.get(
                        (branch_bb, max(1, int(branch_key[1])))
                    ),
                    "branch_pc",
                    0,
                )
                or branch_bb
            )
            evidence["branch_pc"] = f"0x{branch_pc:08x}"
            evidence["condition"] = str(branch_instruction.get("mnemonic") or "")
            precise = self._precise_branch_mmio_analysis(branch_pc)
            evidence["cone_classification"] = dict(
                precise.get("cone_classification", {}) or {}
            )
            evidence["scan_bb_count"] = int(precise.get("scan_bb_count", 0) or 0)
            evidence["static_candidates"] = len(precise.get("candidates", []) or [])
            if precise.get("skip_reason"):
                evidence["precise_skip_reason"] = precise.get("skip_reason")
        except Exception:
            evidence["static_analysis_unavailable"] = True
        try:
            deps = self.register_tracer.analyze_branch_dependencies(branch_pc)
            evidence["dynamic_snapshot_count"] = int(deps.get("snapshot_count", 0) or 0)
            evidence["dynamic_dependency_types"] = sorted(
                {
                    str(item.get("type", ""))
                    for item in (deps.get("dependencies", []) or [])
                    if item.get("type")
                }
            )
        except Exception:
            evidence["dynamic_analysis_unavailable"] = True
        return evidence

    # ------------------------------------------------------------------
    # r7 P2：翻转 = 求解 → 回填输入 → 从锚点/入口重放 → 真实执行自证。
    # ------------------------------------------------------------------

    def _build_irq_delivery_controller(self, emulator):
        """Build + install an IrqDeliveryController with the shared env knobs.

        r40 P2/C8 从 ``_install_irq_delivery`` 提取的共用构造体：旋钮
        （IRQ 号 / 帧格式）与安装失败降级告警逐字保留。调用方负责门控
        （master 开关 / 相位白名单）与卸载。
        """
        from .isr_explorer.isr_explorer import IrqDeliveryController

        try:
            irq = int(os.environ.get("LSGEMU_IRQ_DELIVERY_IRQ", "50") or 50)
        except ValueError:
            irq = 50
        frame_format = str(
            os.environ.get("LSGEMU_IRQ_DELIVERY_FRAME", "ext104") or "ext104"
        ).strip() or "ext104"
        controller = IrqDeliveryController(
            emulator, irq=irq, frame_format=frame_format
        )
        if not controller.install():
            logger.warning("r31 中断投递安装失败（向量表/MMIO 句柄不可用）")
            return None
        return controller

    def _install_irq_delivery(self, emulator):
        """Install the r31 model-driven interrupt delivery path (opt-in).

        ``LSGEMU_IRQ_DELIVERY=1`` turns it on; the IRQ number and the frame
        format are separate knobs so the 104B/32B counterexample arm can be run
        without touching code.  Returns the controller, or ``None`` when the
        feature is off (the default, byte-identical to the pre-r31 replay).
        """
        if not irq_delivery_enabled():
            return None
        controller = self._build_irq_delivery_controller(emulator)
        if controller is None:
            return None
        self.irq_delivery_controller = controller
        return controller

    def install_irq_delivery_for(self, emulator, phase_name):
        """r40 P2/C8：把投递控制器装到**该相位真执行的** emulator 上。

        相位白名单（``LSGEMU_IRQ_DELIVERY_PHASES``）命中才装；缺省空 ⇒
        恒 None = 现状逐位不变。与 ``_install_irq_delivery``（翻转 pass 专属，
        会写 ``self.irq_delivery_controller`` 槽位）不同，本方法**不写**该
        槽位——控制器由调用方持有并在 finally 卸载（样板
        ``_dfs_flip_replay_once``）。
        """
        if not irq_delivery_phase_enabled(phase_name):
            return None
        return self._build_irq_delivery_controller(emulator)

    def _dfs_flip_replay_once(
        self,
        *,
        anchor: Optional[DFSAnchorEntry],
        flip_candidates: List[BranchConstraintCandidate],
        replay_instructions: int,
        timeout_seconds: float,
        enable_function_summaries: bool = False,
    ) -> Tuple[Dict[str, object], List[object], Dict[str, object], Set[int]]:
        """force-free 重放原语：不设 forced choices、不装循环强转、不跳函数。

        从锚点快照恢复（血统须 validated 且带前缀约束表，否则拒绝）后按
        改后的外部输入继续真实执行；无锚点时从入口起跑（用户口径：同为
        「入口点可达」）。返回 (run_result, occurrence_events, guard_violations,
        covered)；护栏违例时调用方不得入账。

        ``enable_function_summaries=True``（r22）再叠加采集语义配置
        （函数摘要 + 流 token 种子，与 ``collect_dfs_anchors`` /
        campaign ``semantic_entry_prefix`` 同款）：锚点若采集自摘要重放，
        翻转重放从该锚点继续时必须用同一执行语义，前缀比对才同构。
        摘要不设 forced choices、不改控制流方向，护栏口径不变。
        """
        run_result: Dict[str, object] = {"stop_reason": "not_started"}
        covered: Set[int] = set()
        events: List[object] = []
        guard_violations: Dict[str, object] = {}
        emulator = None
        temp_mmio = None
        temp_tracer = None
        delivery_controller = None
        stage = self._temp_stage_for("dfs_flip_replay")
        try:
            if anchor is not None and not anchor.flip_eligible:
                run_result = {
                    "stop_reason": "anchor_not_flip_eligible",
                    "ineligibility_reasons": list(anchor.ineligibility_reasons),
                }
                return run_result, events, {"anchor_not_flip_eligible": True}, covered
            emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=None,
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=stage,
            )
            self._configure_emulator_feedback(emulator)
            emulator.enable_branch_snapshot = True
            emulator.enable_loop_intervention = False
            # r15 D1：force-free 重放开启确定性循环快转族（纯内存写 + 确定
            # 退出 + 不改控制流方向；触 MMIO 的环模拟器侧一律不快转）。快转
            # 事件按 loop_fast_forward_emulation 家族单列，护栏只统计方向性
            # 强制——不是放宽「不得强制转分支」。
            emulator.dfs_flip_deterministic_fast_forward = (
                dfs_flip_fast_forward_enabled()
            )
            if enable_function_summaries:
                self._configure_semantic_replay_defaults(emulator)
            temp_mmio = EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            temp_tracer = self._new_temp_register_tracer(emulator)
            entry_point = self.prepared.entry_point
            preserve_cpu_state = False
            if anchor is not None and anchor.entry is not None:
                if not self._restore_branch_snapshot(
                    emulator,
                    anchor.entry.snapshot,
                    lineage_source=anchor.entry,
                ):
                    run_result = {
                        "stop_reason": "anchor_restore_failed",
                        "restore_errors": list(
                            getattr(emulator, "last_snapshot_restore_errors", []) or []
                        )[:4],
                    }
                    return run_result, events, guard_violations, covered
                if not self._restore_replay_mmio_state(
                    emulator,
                    temp_mmio,
                    anchor.entry.mmio_state,
                ):
                    run_result = {"stop_reason": "anchor_mmio_restore_failed"}
                    return run_result, events, guard_violations, covered
                # 快照已恢复到主干前缀末尾：从恢复的 PC 继续真实执行。
                entry_point = None
                preserve_cpu_state = True
            # 回填输入：先锚点前缀约束表（重放等价性前提），再翻转候选值。
            prefix_items = (
                (anchor.prefix_constraint_tables or {}).get(
                    "runner_scoped_constraints", []
                )
                if anchor is not None
                else []
            )
            if prefix_items:
                self._apply_temp_mmio_constraints(
                    temp_mmio,
                    list(prefix_items),
                    emulator=emulator,
                    mmio_added_by="dfs_anchor_prefix",
                )
            if flip_candidates:
                self._apply_temp_mmio_constraints(
                    temp_mmio,
                    flip_candidates,
                    emulator=emulator,
                    mmio_added_by="dfs_flip_candidate",
                )
            # r31 P3：模型驱动中断投递（默认关）。必须在 MMIO 快照恢复之后安装，
            # 否则 restore 会用快照里的 profile 列表覆盖掉刚注册的器件模型。
            delivery_controller = self._install_irq_delivery(emulator)
            try:
                with self.guided_modules(temp_mmio, temp_tracer), self.capture_coverage(
                    emulator
                ) as temp_covered:
                    raw_run_result = emulator.run(
                        entry_point=entry_point,
                        max_instructions=replay_instructions,
                        timeout_seconds=timeout_seconds,
                        preserve_cpu_state=preserve_cpu_state,
                    )
                    run_result = self._normalize_replay_run_result(
                        raw_run_result,
                        execution_started=True,
                    )
                    covered = self.validate_coverage(temp_covered)
            finally:
                if delivery_controller is not None:
                    delivery_controller.uninstall()
            if delivery_controller is not None:
                # 证据生产者（F6）：投递事实只由本次投递产生，且带完整审计。
                run_result.update(delivery_controller.run_result_fields())
            events = list(
                emulator.branch_snapshot_manager.get_ordered_occurrence_events()
            )
            run_result["forced_branch_trace_count"] = len(
                list(getattr(emulator, "forced_branch_trace", []) or [])
            )
            run_result["forced_branch_choices_configured"] = (
                len(dict(getattr(emulator, "forced_branch_choices", {}) or {}))
                + len(list(getattr(emulator, "forced_branch_sequence", []) or []))
            )
            guard_ok, guard_violations = DFSFlipGuardrails.evaluate(
                emulator=emulator, run_result=run_result
            )
            run_result["dfs_guardrails_clean"] = bool(guard_ok)
            run_result["dfs_guardrail_violations"] = dict(guard_violations)
            # r15 D1 证据负载：快转发生次数 + 环地址（审计「哪些环被 O(1)
            # 物化」；等价性举证对照此表）。
            ff_stats = dict(
                getattr(emulator, "loop_fast_forward_emulation", {}) or {}
            )
            run_result["fast_forward_events"] = {
                "total": int(ff_stats.get("total", 0) or 0),
                "by_handler": dict(ff_stats.get("by_handler", {}) or {}),
            }
            run_result["fast_forward_loop_heads"] = [
                {"loop_head": f"0x{int(pc) & 0xFFFFFFFF:08x}", "handler": str(name)}
                for pc, name in (
                    getattr(emulator, "loop_fast_forward_events", []) or []
                )
            ]
            return run_result, events, guard_violations, covered
        except Exception as exc:
            run_result = self._materialize_replay_failure_result(
                "dfs_flip_replay_exception",
                execution_started=True,
                execution_error=exc,
            )
            return run_result, events, guard_violations, covered
        finally:
            if emulator is not None:
                try:
                    self._finalize_temp_replay(
                        emulator,
                        mmio_handler=temp_mmio,
                        register_tracer=temp_tracer,
                        run_result=run_result,
                        stage_name=stage,
                    )
                except Exception:
                    self._record_snapshot_resource_event("dfs_flip_finalize_errors")

    def _dfs_execute_flip_pass(
        self,
        *,
        known_coverage: Optional[Set[int]] = None,
    ) -> Dict[str, object]:
        """自底向上翻转驱动：深到浅遍历主干分支点，每点试未走方向。

        每个候选：求解（naturalization bootstrap，内部走 LocalConstraintRecovery
        求候选 MMIO 读值）→ 回填 → 从最近可用祖先锚点 force-free 重放 →
        match_path_signature 自证方向确实变了。护栏违例的重放一律不入账。

        ``known_coverage`` = 翻转前 phase 已知覆盖（调用方传
        ``path_base_coverage | phase_covered``）；翻转重放覆盖里的 BB 只有
        落在该集合之外才计入 ``flip_new_covered_bbs``（诚实记账：重放会
        重新经过大量已知 BB，不能算翻转新增）。调用方不得传任务循环残留
        的单任务快照（r9D 现场曾在实参求值处 UnboundLocalError）。
        """
        known_covered = self.validate_coverage(known_coverage or set())
        ledger = getattr(self, "dfs_flip_ledger", None)
        if ledger is None:
            ledger = DFSFlipLedger()
            self.dfs_flip_ledger = ledger
        pool = self._dfs_anchor_pool_or_none()
        # r32 D1：兜底登记。r31 4h 现场 327 个候选前缀深度全部 < stride(8) ⇒
        # 锚点池恒空 ⇒ 翻转 pass planned 恒 0 ⇒ 装在翻转重放里的投递/SVC
        # 机制一次都执行不到。兜底只登记「当前最深可用」候选（血统/flip_eligible
        # 判定走 _register 同一路径，不放宽），且在池里已有正常锚点时永不介入。
        if pool is not None:
            # r32 D1b：锚点登记发生在源重放收尾之前，那一刻血统必然未定稿；
            # 消费时点（阶段末尾）重导才拿得到真实 provenance。
            try:
                pool.refresh_eligibility()
            except Exception:
                self._record_snapshot_resource_event("dfs_anchor_refresh_errors")
            try:
                promoted = pool.promote_deepest_below_stride()
                if promoted is not None:
                    logger.warning(
                        "r32 锚点兜底登记: depth=%d flip_eligible=%s lineage=%s "
                        "reasons=%s histogram=%s",
                        int(promoted.depth),
                        bool(promoted.flip_eligible),
                        dict(promoted.lineage).get("status"),
                        list(promoted.ineligibility_reasons),
                        dict(pool.candidate_depth_histogram),
                    )
            except Exception:
                self._record_snapshot_resource_event("dfs_anchor_fallback_errors")
        if pool is None or not pool.anchors:
            payload = ledger.report_payload()
            # r9 C 件：planned=0 必须能从报告反推原因（90min 长跑里这曾是黑盒）。
            payload["planned_zero_reason"] = (
                "no_anchor_pool" if pool is None else "no_anchors"
            )
            payload["trunk_depth"] = 0
            payload["anchor_fallback"] = (
                None
                if pool is None
                else {
                    "deepest_below_stride": pool.statistics()[
                        "deepest_below_stride"
                    ],
                    "candidate_depth_histogram": dict(
                        pool.candidate_depth_histogram
                    ),
                }
            )
            return payload
        # 主干代理 = 最深锚点的前缀签名（P1 主干优先调度使最深前缀即主干）。
        deepest = max(pool.anchors.values(), key=lambda a: a.depth)
        trunk_items = list(deepest.anchor_key[0])
        if not trunk_items:
            payload = ledger.report_payload()
            payload["planned_zero_reason"] = "empty_trunk_prefix"
            payload["trunk_depth"] = 0
            return payload

        # 锚点按「前缀长度」映射到主干索引（作为各深度的回退祖先）。
        prefix_anchors: List[Tuple[int, DFSAnchorEntry]] = []
        for anchor in pool.anchors.values():
            signature = list(anchor.anchor_key[0])
            if len(signature) > len(trunk_items):
                continue
            if any(
                self._ordered_keys_differ(trunk_items[index], signature[index])
                for index in range(len(signature))
            ):
                continue
            prefix_anchors.append((len(signature), anchor))
        prefix_anchors.sort(key=lambda item: -item[0])

        def anchor_for_index(index: int) -> Optional[DFSAnchorEntry]:
            for prefix_len, anchor in prefix_anchors:
                if prefix_len <= index and anchor.flip_eligible:
                    return anchor
            return None

        anchor_by_index = {
            index: anchor_for_index(index) for index in range(len(trunk_items) + 1)
        }
        trunk_directions: Dict[Tuple[int, int], object] = {}
        next_key = deepest.anchor_key[1]
        next_event = self.known_main_branch_events.get(next_key)
        if next_event is not None and isinstance(
            getattr(next_event, "original_taken", None), bool
        ):
            trunk_directions[next_key] = bool(next_event.original_taken)

        explored = {
            (edge[0], edge[1]) for edge in (self.reservoir_explored_edges or set())
        }
        tasks = DFSFlipPlanner.plan(
            trunk_items,
            anchor_by_index=anchor_by_index,
            already_explored=explored,
            trunk_directions=trunk_directions,
        )
        # r11 ③：已判「无外部输入候选」的方向不再重规划（负结果缓存）——
        # r10 现场 5 轮 pass 重复打同样 6 个内核分支点，账本里重复记 30 条。
        no_candidate_edges = ledger.no_candidate_edge_set()
        cached_skips = 0
        if no_candidate_edges:
            filtered: List[object] = []
            for task in tasks:
                if (task.branch_key, task.target_direction) in no_candidate_edges:
                    cached_skips += 1
                    continue
                filtered.append(task)
            tasks = filtered
        max_attempts = dfs_flip_max_attempts()
        replay_instructions = dfs_flip_replay_instructions()
        timeout_seconds = dfs_flip_timeout_seconds()
        ledger.attempt_stats["planned"] += len(tasks)
        if cached_skips:
            ledger.attempt_stats["no_candidate_cached"] += cached_skips
        attempts = 0
        new_covered: Set[int] = set()

        for task in tasks:
            if attempts >= max_attempts:
                break
            if not isinstance(task.target_direction, bool):
                continue
            candidates = self._naturalization_bootstrap_candidates(
                task.branch_key,
                task.target_direction,
                max_candidates=3,
                max_values_per_source=4,
            )
            candidates = [item for item in candidates or [] if item is not None]
            if not candidates:
                ledger.attempt_stats["no_candidates"] += 1
                # r11 ④：工具限制 ≠ 不可达；附静态锥分类 + 动态依赖摘要证据。
                ledger.record_no_external_input(
                    task.branch_key,
                    task.target_direction,
                    evidence=self._flip_no_candidate_evidence(task.branch_key),
                )
                continue
            anchor = (
                pool.lookup(task.anchor_key)
                if task.anchor_key is not None
                else None
            )
            succeeded = False
            stop_reasons: List[str] = []
            for candidate in candidates:
                if attempts >= max_attempts:
                    break
                attempts += 1
                ledger.attempt_stats["attempts"] += 1
                ledger.attempt_stats["replays"] += 1
                run_result, events, violations, covered = self._dfs_flip_replay_once(
                    anchor=anchor,
                    flip_candidates=[candidate],
                    replay_instructions=replay_instructions,
                    timeout_seconds=timeout_seconds,
                )
                stop_reason = str(run_result.get("stop_reason") or "")
                stop_reasons.append(stop_reason)
                # r32 D2/D3：把该次重放的模型驱动投递 / SVC 派发证据随 attempt
                # 记账（此前 run_result 里的字段在翻转 pass 里被丢弃，报告无法
                # 反推机制是否真的执行过）。
                mechanism_evidence = self._flip_attempt_mechanism_evidence(run_result)
                if str(stop_reason).startswith("anchor_"):
                    ledger.attempt_stats["anchor_restore_failures"] += 1
                    break
                if violations:
                    ledger.attempt_stats["guardrail_rejections"] += 1
                    ledger.record_attempt(
                        {
                            "branch": f"0x{task.branch_key[0] & 0xFFFFFFFF:08x}",
                            "occurrence": int(task.branch_key[1]),
                            "direction": bool(task.target_direction),
                            "candidate_value": int(candidate.value),
                            "stop_reason": stop_reason,
                            "verdict": "guardrail_rejected",
                            "violations": dict(violations),
                            **mechanism_evidence,
                        }
                    )
                    continue
                verdict, detail = verify_flip_by_real_execution(task, events)
                ledger.record_attempt(
                    {
                        "branch": f"0x{task.branch_key[0] & 0xFFFFFFFF:08x}",
                        "occurrence": int(task.branch_key[1]),
                        "direction": bool(task.target_direction),
                        "candidate_value": int(candidate.value),
                        "stop_reason": stop_reason,
                        "verdict": verdict,
                        "detail": {
                            key: (
                                f"0x{value:08x}"
                                if isinstance(value, int)
                                else value
                            )
                            for key, value in (detail or {}).items()
                        },
                        **mechanism_evidence,
                    }
                )
                if verdict == "flipped":
                    ledger.record_success(
                        task.branch_key,
                        task.target_direction,
                        flip_edge_evidence(),
                    )
                    # 诚实差集：只有 phase 已知覆盖之外的 BB 才是翻转新增。
                    new_covered |= set(covered or set()) - known_covered
                    succeeded = True
                    break
                if verdict == "direction_not_changed":
                    ledger.attempt_stats["candidate_rejections"] += 1
                    continue
                if verdict == "prefix_diverged":
                    ledger.attempt_stats["prefix_divergences"] += 1
                    continue
                ledger.attempt_stats["candidate_rejections"] += 1
            if not succeeded and attempts >= max_attempts:
                ledger.record_unresolved(
                    task.branch_key,
                    task.target_direction,
                    "attempt_budget_exhausted:" + ",".join(stop_reasons[:3]),
                )
            elif not succeeded:
                ledger.record_unresolved(
                    task.branch_key,
                    task.target_direction,
                    "all_candidates_failed:" + ",".join(stop_reasons[:3]),
                )
        payload = ledger.report_payload()
        payload["trunk_depth"] = len(trunk_items)
        payload["flip_new_covered_bbs"] = sorted(
            int(bb) for bb in new_covered or set()
        )
        return payload

    @staticmethod
    def _flip_attempt_mechanism_evidence(
        run_result: Dict[str, object]
    ) -> Dict[str, object]:
        """把一次翻转重放的投递/SVC 证据压成 attempt 记录里的紧凑字段。

        r32 之前这两类字段只活在 ``run_result`` 里、随翻转 pass 丢弃，报告
        无法审计「机制到底执行过没有」。这里只搬事实，不做任何升降级；
        没有发生就返回空 dict（字段缺席 = 未发生，而不是 0 值填充）。

        r41 D1：``run_result_fields`` 零投递时也携带 ``irq_delivery`` 审计
        blob（装到没装/跑没跑到）。本压实函数只收**事实**：delivery_count
        为 0 的审计 blob 不进 attempt 证据——审计走相位 irq_delivery 聚合面。
        """
        evidence: Dict[str, object] = {}
        delivery = run_result.get("irq_delivery")
        if isinstance(delivery, dict) and int(delivery.get("delivery_count", 0) or 0) > 0:
            evidence["irq_delivery"] = {
                "source": delivery.get("source"),
                "knob": delivery.get("knob"),
                "delivery_count": delivery.get("delivery_count"),
                "unstack_count": delivery.get("unstack_count"),
                "vector": delivery.get("vector"),
                "frame_size": delivery.get("frame_size"),
                "exc_return": delivery.get("exc_return"),
                "delivered_at_pc": delivery.get("delivered_at_pc"),
            }
        svc = run_result.get("svc_dispatch")
        if isinstance(svc, dict):
            evidence["svc_dispatch"] = {
                "source": svc.get("source"),
                "irq": svc.get("irq"),
                "svc_number": svc.get("svc_number"),
                "dispatch_count": svc.get("dispatch_count"),
                "handler_vector": svc.get("handler_vector"),
                "dispatched_at_pc": svc.get("dispatched_at_pc"),
                "frame_size": svc.get("frame_size"),
                "exc_return": svc.get("exc_return"),
                "unstack_count": svc.get("unstack_count"),
            }
        return evidence

    def _write_dfs_trunk_report(
        self, flip_payload: Optional[Dict[str, object]]
    ) -> Optional[str]:
        """P3：落盘 dfs_trunk_report.json（主干深度/锚点冷热/翻转/不可达清单）。"""
        pool = self._dfs_anchor_pool_or_none()
        payload: Dict[str, object] = {
            "phase": str(self.current_stage_name or "unknown"),
            "flip": dict(flip_payload or {}),
            "anchors": (
                {
                    "statistics": pool.statistics(),
                    "depth_curve": pool.depth_curve(),
                }
                if pool is not None
                else None
            ),
        }
        path = os.environ.get("LSGEMU_DFS_TRUNK_REPORT")
        if not path:
            progress = os.environ.get("LSGEMU_RESERVOIR_PROGRESS")
            if progress:
                path = str(Path(progress).parent / "dfs_trunk_report.json")
        if not path:
            return None
        _write_json_debug_record(Path(path), payload)
        return path

    @staticmethod
    def _ordered_keys_differ(
        left: Tuple[Tuple[int, int], object],
        right: Tuple[Tuple[int, int], object],
    ) -> bool:
        return (
            int(left[0][0]) != int(right[0][0])
            or int(left[0][1]) != int(right[0][1])
            or left[1] != right[1]
        )

    @staticmethod
    def _reservoir_isr_context_limit() -> int:
        # Zero disables retained ISR contexts, matching the existing contract.
        return max(0, _env_int("LSGEMU_RESERVOIR_ISR_CONTEXT_LIMIT", 96))

    def _record_snapshot_resource_event(self, name: str, count: int = 1) -> None:
        stats = getattr(self, "snapshot_resource_stats", None)
        if not isinstance(stats, Counter):
            stats = Counter(stats or {})
            self.snapshot_resource_stats = stats
        stats[str(name)] += max(0, int(count))

    def _record_reservoir_explored_edge(
        self,
        key: Tuple[int, int],
        direction: object,
        evidence: str,
    ) -> None:
        """r7 P3：边集元素升级为 ((addr,occ), dir, evidence)。

        同一 (key, dir) 重复到达时保留更强证据（E0>E1>E2>E3>unknown），
        避免集合随证据等级抖动膨胀。
        """
        normalized = normalize_evidence_class(evidence)
        target = (key, direction, normalized)
        for existing in list(self.reservoir_explored_edges):
            if existing[0] == key and existing[1] == direction:
                if _evidence_rank(existing[2]) >= _evidence_rank(normalized):
                    return
                self.reservoir_explored_edges.discard(existing)
                break
        self.reservoir_explored_edges.add(target)

    def _ordered_replay_token(self, key: Tuple[int, int]) -> object:
        if self._ordered_replay_exact_occurrence_enabled():
            return (int(key[0]), int(key[1]))
        return int(key[0])

    @staticmethod
    def _branch_trace_matches_token(trace_item: Dict[str, object], token: object) -> bool:
        return branch_trace_matches_token(trace_item, token)

    def _remember_observed_branch_directions(self, events: Iterable[object]) -> int:
        added = 0
        for event in events or []:
            if self._is_switch_branch_event(event):
                continue
            if not bool(getattr(event, "original_direction_known", True)):
                continue
            if self._remember_single_observed_branch_direction(
                int(getattr(event, "address", 0) or 0),
                bool(getattr(event, "original_taken", False)),
            ):
                added += 1
        return added

    def _remember_single_observed_branch_direction(
        self,
        branch_bb_start: int,
        direction: bool,
    ) -> bool:
        branch_bb_start = int(branch_bb_start)
        if branch_bb_start <= 0:
            return False
        directions = self.observed_branch_directions.setdefault(branch_bb_start, set())
        before = len(directions)
        directions.add(bool(direction))
        return len(directions) > before

    def _observed_branch_directions(self, branch_bb_start: int) -> Set[bool]:
        observed = set()
        evidence_by_choice = getattr(self, "branch_direction_evidence", {}).get(
            int(branch_bb_start)
        )
        if evidence_by_choice is None:
            # Backward compatibility for old state files and unit fixtures that
            # predate evidence-aware branch observations.
            for event in self.known_main_branch_events.values():
                if int(getattr(event, "address", 0)) != int(branch_bb_start):
                    continue
                observed.add(bool(getattr(event, "original_taken", False)))
        else:
            for (choice_type, choice), evidence_classes in evidence_by_choice.items():
                if choice_type != "bool":
                    continue
                if not set(evidence_classes) & {EVIDENCE_E0, EVIDENCE_E1}:
                    continue
                observed.add(bool(choice))
        observed.update(
            bool(direction)
            for direction in self.observed_branch_directions.get(int(branch_bb_start), set())
        )
        return observed

    def _branch_mmio_replay_context_signature(
        self,
        strategy: str,
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> Tuple[object, ...]:
        family = str(strategy or "")
        if snapshot_entry is None:
            return (family,)
        scope_signature = self._scope_signature_from_snapshot_entry(snapshot_entry)
        if family == "snapshot":
            snapshot = getattr(snapshot_entry, "snapshot", None)
            return (
                family,
                str(getattr(snapshot_entry, "origin", "unknown")),
                int(getattr(snapshot, "address", 0) or 0),
                int(getattr(snapshot, "order", 0) or 0),
                scope_signature,
            )
        return (
            family,
            scope_signature,
        )

    def _branch_mmio_already_target_key(
        self,
        branch_pc: int,
        target_direction: bool,
        strategy: str,
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> Tuple[object, ...]:
        return (
            int(branch_pc),
            bool(target_direction),
        ) + self._branch_mmio_replay_context_signature(
            strategy,
            snapshot_entry=snapshot_entry,
        )

    def _branch_mmio_unreachable_key(
        self,
        branch_pc: int,
        target_direction: bool,
        strategy: str,
        constraint_items: Iterable[BranchConstraintCandidate],
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> Tuple[object, ...]:
        return self._branch_mmio_already_target_key(
            branch_pc,
            target_direction,
            strategy,
            snapshot_entry=snapshot_entry,
        ) + (
            self._constraint_items_signature(constraint_items),
        )

    def _remember_branch_mmio_already_target(
        self,
        branch_pc: int,
        target_direction: bool,
        strategy: str,
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> None:
        self.branch_mmio_already_target_replays.add(
            self._branch_mmio_already_target_key(
                branch_pc,
                target_direction,
                strategy,
                snapshot_entry=snapshot_entry,
            )
        )

    def _remember_branch_mmio_unreachable_replay(
        self,
        branch_pc: int,
        target_direction: bool,
        strategy: str,
        constraint_items: Iterable[BranchConstraintCandidate],
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> None:
        self.branch_mmio_unreachable_replays.add(
            self._branch_mmio_unreachable_key(
                branch_pc,
                target_direction,
                strategy,
                constraint_items,
                snapshot_entry=snapshot_entry,
            )
        )

    def _branch_mmio_cached_skip_reason(
        self,
        branch_pc: int,
        target_direction: bool,
        strategy: str,
        constraint_items: Iterable[BranchConstraintCandidate],
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> Optional[str]:
        if self._branch_mmio_already_target_key(
            branch_pc,
            target_direction,
            strategy,
            snapshot_entry=snapshot_entry,
        ) in self.branch_mmio_already_target_replays:
            return "cached_already_target_without_constraint"
        if self._branch_mmio_unreachable_key(
            branch_pc,
            target_direction,
            strategy,
            constraint_items,
            snapshot_entry=snapshot_entry,
        ) in self.branch_mmio_unreachable_replays:
            return "cached_unreachable_replay"
        return None

    def _branch_replay_succeeded(
        self,
        replay_events: Iterable[object],
        branch_bb_start: int,
        take_branch: bool,
        desired_successor: Optional[int],
        covered_bbs: Set[int],
    ) -> bool:
        return bool(
            self._evaluate_branch_replay(
                replay_events,
                branch_bb_start,
                take_branch,
                desired_successor,
                covered_bbs,
            )["success"]
        )

    def _evaluate_branch_replay(
        self,
        replay_events: Iterable[object],
        branch_bb_start: int,
        take_branch: bool,
        desired_successor: Optional[int],
        covered_bbs: Set[int],
    ) -> Dict[str, object]:
        expected_direction = bool(take_branch)
        observed_directions: List[bool] = []
        for event in replay_events or []:
            if int(getattr(event, "address", 0)) != int(branch_bb_start):
                continue
            observed_directions.append(bool(getattr(event, "original_taken", False)))

        unique_directions = []
        for direction in observed_directions:
            if direction not in unique_directions:
                unique_directions.append(direction)

        branch_seen = bool(observed_directions)
        matched_direction = expected_direction in unique_directions
        successor_seen = desired_successor is None or desired_successor in covered_bbs

        success = branch_seen and matched_direction and successor_seen
        failure_reason = None
        if not branch_seen:
            failure_reason = "branch_not_reached"
        elif not matched_direction:
            failure_reason = "wrong_direction"
        elif not successor_seen:
            failure_reason = "successor_not_covered"

        return {
            "success": success,
            "failure_reason": failure_reason,
            "branch_seen": branch_seen,
            "matched_direction": matched_direction,
            "desired_successor_seen": successor_seen,
            "observed_directions": [
                "taken" if direction else "not-taken"
                for direction in unique_directions
            ],
            "observed_event_count": len(observed_directions),
        }

    def _paired_replay_changed_branch_key(
        self,
        *,
        branch_bb_start: int,
        target_direction: bool,
        control_events: Iterable[object],
        result_events: Iterable[object],
        fallback_key: Optional[Tuple[int, int]] = None,
        allow_snapshot_occurrence_translation: bool = False,
    ) -> Optional[Tuple[int, int]]:
        """Return the exact occurrence whose natural direction changed in a pair."""
        branch_start = int(branch_bb_start)
        expected = bool(target_direction)
        control_choices = {
            self._branch_event_key(event): bool(getattr(event, "original_taken", False))
            for event in control_events or []
            if int(getattr(event, "address", 0) or 0) == branch_start
        }
        changed: List[Tuple[int, int]] = []
        for event in result_events or []:
            if int(getattr(event, "address", 0) or 0) != branch_start:
                continue
            key = self._branch_event_key(event)
            if bool(getattr(event, "original_taken", False)) != expected:
                continue
            if control_choices.get(key) == expected:
                continue
            if key not in changed:
                changed.append(key)
        if not changed:
            return None

        normalized_fallback = None
        if fallback_key is not None:
            try:
                normalized_fallback = (int(fallback_key[0]), max(1, int(fallback_key[1])))
            except (TypeError, ValueError, IndexError):
                normalized_fallback = None
        if normalized_fallback in changed:
            return normalized_fallback
        if (
            allow_snapshot_occurrence_translation
            and normalized_fallback is not None
            and int(normalized_fallback[0]) == branch_start
        ):
            # Snapshot-local event counters restart at one.  The snapshot's
            # next_branch_key carries the corresponding reset-entry occurrence.
            return normalized_fallback
        return changed[0]

    def _snapshot_entry_identity(self, snapshot_entry: PrefixReplaySnapshot) -> Tuple[object, ...]:
        snapshot = getattr(snapshot_entry, "snapshot", None)
        return (
            str(getattr(snapshot_entry, "origin", "unknown")),
            int(getattr(getattr(snapshot_entry, "snapshot", None), "address", 0) or 0),
            int(getattr(getattr(snapshot_entry, "snapshot", None), "order", 0) or 0),
            int(getattr(snapshot_entry, "branch_depth", 0) or 0),
            self._snapshot_entry_evidence_class(snapshot_entry),
            tuple(getattr(snapshot_entry, "prefix_signature", tuple()) or tuple()),
            tuple(getattr(snapshot_entry, "source_path_signature", tuple()) or tuple()),
            tuple(self._snapshot_entry_occurrence_prefix(snapshot_entry)),
            tuple(sorted(
                (int(address), int(value) & 0xFFFFFFFF)
                for address, value in getattr(snapshot_entry, "mmio_state", {}).items()
            )),
            int(getattr(snapshot, "target", 0) or 0) if snapshot is not None else 0,
            int(getattr(snapshot, "fallthrough", 0) or 0) if snapshot is not None else 0,
        )

    def _direct_call_attempt_constraint_signature(
        self,
        snapshot_entry: PrefixReplaySnapshot,
    ) -> Tuple[object, ...]:
        scope_signature = self._scope_signature_from_snapshot_entry(snapshot_entry)
        scoped_items = self._matching_scoped_branch_constraints(scope_signature)
        return tuple(
            (
                item.constraint_type,
                int(item.address),
                int(item.value),
                int(item.read_pc or 0),
                int(item.constraint_pc or 0),
            )
            for item in scoped_items
        )

    def _direct_call_attempt_key(
        self,
        pred_bb: int,
        snapshot_entry: PrefixReplaySnapshot,
    ) -> Tuple[int, Tuple[object, ...], Tuple[object, ...]]:
        return (
            int(pred_bb),
            self._snapshot_entry_identity(snapshot_entry),
            self._direct_call_attempt_constraint_signature(snapshot_entry),
        )

    def _direct_call_failure_record(
        self,
        pred_bb: int,
        snapshot_entry: PrefixReplaySnapshot,
    ) -> Dict[str, object]:
        return self.direct_call_candidate_failures.setdefault(
            self._direct_call_attempt_key(pred_bb, snapshot_entry),
            {
                "attempts": 0,
                "new_bbs": 0,
                "stop_reasons": Counter(),
            },
        )

    def _direct_call_failure_penalty(
        self,
        pred_bb: int,
        snapshot_entry: PrefixReplaySnapshot,
    ) -> int:
        record = self.direct_call_candidate_failures.get(
            self._direct_call_attempt_key(pred_bb, snapshot_entry)
        )
        if not record:
            return 0
        attempts = int(record.get("attempts", 0) or 0)
        new_bbs = int(record.get("new_bbs", 0) or 0)
        if attempts <= 0 or new_bbs > 0:
            return 0
        stop_reasons = record.get("stop_reasons", Counter()) or Counter()
        penalty = attempts * 8
        for reason, count in stop_reasons.items():
            reason_text = str(reason)
            if (
                "Unhandled CPU exception" in reason_text
                or "Invalid memory" in reason_text
                or "Invalid instruction" in reason_text
                or reason_text == "fatal_sink_terminal"
            ):
                penalty += int(count) * 24
            elif reason_text == "timeout_or_max_instructions_reached":
                penalty += int(count) * 16
            elif reason_text == "quiescence_no_new_bbs":
                penalty += int(count) * 12
            else:
                penalty += int(count) * 6
        return penalty

    def _record_direct_call_attempt_outcome(
        self,
        pred_bb: int,
        snapshot_entry: PrefixReplaySnapshot,
        *,
        new_bbs: int,
        stop_reason: str,
    ) -> None:
        record = self._direct_call_failure_record(pred_bb, snapshot_entry)
        record["attempts"] = int(record.get("attempts", 0) or 0) + 1
        record["new_bbs"] = int(record.get("new_bbs", 0) or 0) + max(0, int(new_bbs))
        stop_reasons = record.get("stop_reasons")
        if not isinstance(stop_reasons, Counter):
            stop_reasons = Counter(stop_reasons or {})
            record["stop_reasons"] = stop_reasons
        stop_reasons[str(stop_reason or "unknown")] += 1

    def _remember_direct_call_snapshot(
        self,
        snapshot: object,
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
        evidence_class: object = None,
        source_occurrence_signature: Tuple[
            Tuple[Tuple[int, int], object], ...
        ] = tuple(),
    ) -> bool:
        condition = self._snapshot_dispatch_mnemonic(snapshot)
        if not _is_direct_call_mnemonic(condition):
            return False
        address = int(getattr(snapshot, "address", 0) or 0)
        if address <= 0:
            return False
        normalized_signature = self._ordered_source_path_signature(
            tuple(source_path_signature or tuple())
        )
        capture_evidence = self._capture_evidence_class(
            normalized_signature,
            evidence_class,
        )
        normalized_occurrence_signature = normalize_naturalization_signature(
            tuple(source_occurrence_signature or tuple())
        )
        entry = PrefixReplaySnapshot(
            prefix_signature=tuple(),
            next_branch_key=(address, 1),
            snapshot=snapshot,
            mmio_state=self._interrupt_context_mmio_state(snapshot),
            source_path_signature=normalized_signature,
            branch_depth=int(getattr(snapshot, "depth", 0) or 0),
            origin="direct-call",
            evidence_class=capture_evidence,
            source_occurrence_trace=normalized_occurrence_signature,
            source_occurrence_prefix_len=len(normalized_occurrence_signature),
        )
        entries = self.direct_call_snapshots.setdefault(address, {})
        variant_signature = (
            normalized_signature,
            normalized_occurrence_signature,
        )
        existing = entries.get(variant_signature)
        if existing is None:
            entries[variant_signature] = entry
            self._trim_direct_call_snapshot_variants(address)
            return True
        existing_snapshot = getattr(existing, "snapshot", None)
        if (
            int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
            int(getattr(snapshot, "depth", 0) or 0),
        ) >= (
            int(getattr(existing_snapshot, "capture_order", getattr(existing_snapshot, "order", 0)) or 0),
            int(getattr(existing_snapshot, "depth", 0) or 0),
        ):
            entries[variant_signature] = entry
            self._trim_direct_call_snapshot_variants(address)
        return False

    def _trim_direct_call_snapshot_variants(self, address: int) -> None:
        limit = self._direct_call_snapshot_variant_limit()
        if limit <= 0:
            return
        entries = self.direct_call_snapshots.get(int(address), {})
        if not isinstance(entries, dict) or len(entries) <= limit:
            return
        ordered_items = sorted(
            entries.items(),
            key=lambda item: self._root_snapshot_entry_rank(
                self._scope_signature_from_snapshot_entry(item[1]),
                item[1],
            ),
        )
        removed = max(0, len(ordered_items) - limit)
        self.direct_call_snapshots[int(address)] = dict(ordered_items[:limit])
        self._record_snapshot_resource_event(
            "direct_call_variant_evictions",
            removed,
        )

    def _remember_stream_summary_entry_snapshot(
        self,
        snapshot: object,
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
        evidence_class: object = None,
        source_occurrence_signature: Tuple[
            Tuple[Tuple[int, int], object], ...
        ] = tuple(),
    ) -> bool:
        condition = self._snapshot_dispatch_mnemonic(snapshot)
        if not str(condition or "").upper().startswith("SUMMARY"):
            return False
        address = int(getattr(snapshot, "address", 0) or 0)
        if address <= 0:
            return False
        normalized_signature = self._ordered_source_path_signature(
            tuple(source_path_signature or tuple())
        )
        capture_evidence = self._capture_evidence_class(
            normalized_signature,
            evidence_class,
        )
        normalized_occurrence_signature = normalize_naturalization_signature(
            tuple(source_occurrence_signature or tuple())
        )
        variant_signature = (
            normalized_signature,
            normalized_occurrence_signature,
            int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
            int(getattr(snapshot, "depth", 0) or 0),
            int(getattr(snapshot, "occurrence_index", 1) or 1),
            int(getattr(snapshot, "target", 0) or 0),
            int(getattr(snapshot, "fallthrough", 0) or 0),
            tuple(sorted(
                (int(mmio_addr), int(value) & 0xFFFFFFFF)
                for mmio_addr, value in getattr(snapshot, "mmio_state", {}).items()
            )),
        )
        entry = PrefixReplaySnapshot(
            prefix_signature=tuple(),
            next_branch_key=(address, 1),
            snapshot=snapshot,
            mmio_state=self._interrupt_context_mmio_state(snapshot),
            source_path_signature=normalized_signature,
            branch_depth=int(getattr(snapshot, "depth", 0) or 0),
            origin="stream-summary-entry",
            evidence_class=capture_evidence,
            source_occurrence_trace=normalized_occurrence_signature,
            source_occurrence_prefix_len=len(normalized_occurrence_signature),
        )
        entries = self.stream_summary_entry_snapshots.setdefault(address, {})
        existing = entries.get(variant_signature)
        if existing is None:
            entries[variant_signature] = entry
            self._trim_stream_summary_entry_variants(address)
            return True
        existing_snapshot = getattr(existing, "snapshot", None)
        if (
            int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
            int(getattr(snapshot, "depth", 0) or 0),
        ) >= (
            int(getattr(existing_snapshot, "capture_order", getattr(existing_snapshot, "order", 0)) or 0),
            int(getattr(existing_snapshot, "depth", 0) or 0),
        ):
            entries[variant_signature] = entry
            self._trim_stream_summary_entry_variants(address)
        return False

    def _trim_stream_summary_entry_variants(self, address: int) -> None:
        max_variants = self._stream_summary_snapshot_variant_limit()
        entries = self.stream_summary_entry_snapshots.get(int(address), {})
        if not isinstance(entries, dict):
            return
        while len(entries) > max_variants:
            oldest_key = None
            oldest_score = None
            for key, entry in entries.items():
                snapshot = getattr(entry, "snapshot", None)
                score = (
                    int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
                    int(getattr(snapshot, "depth", 0) or 0),
                )
                if oldest_score is None or score < oldest_score:
                    oldest_score = score
                    oldest_key = key
            if oldest_key is None:
                break
            entries.pop(oldest_key, None)
            self._record_snapshot_resource_event(
                "stream_summary_variant_evictions"
            )

    def _direct_call_snapshot_entries(self, bb_addr: int) -> List[PrefixReplaySnapshot]:
        entries = list(self.direct_call_snapshots.get(int(bb_addr), {}).values())
        if not entries:
            try:
                snapshot = self.emulator.branch_snapshot_manager.get_snapshot(int(bb_addr))
            except Exception:
                snapshot = None
            if snapshot is not None and _is_direct_call_mnemonic(self._snapshot_dispatch_mnemonic(snapshot)):
                self._remember_direct_call_snapshot(snapshot, evidence_class=EVIDENCE_E0)
                entries = list(self.direct_call_snapshots.get(int(bb_addr), {}).values())
        entries.sort(
            key=lambda entry: (
                len(self._scope_signature_from_snapshot_entry(entry)),
                int(getattr(getattr(entry, "snapshot", None), "capture_order", 0) or 0),
                int(getattr(entry, "branch_depth", 0) or 0),
            ),
            reverse=True,
        )
        return entries

    def _stream_summary_entry_snapshot_entries(self, bb_addr: int) -> List[PrefixReplaySnapshot]:
        entries = list(self.stream_summary_entry_snapshots.get(int(bb_addr), {}).values())
        if not entries:
            try:
                snapshot = self.emulator.branch_snapshot_manager.get_snapshot(int(bb_addr))
            except Exception:
                snapshot = None
            if snapshot is not None and self._snapshot_dispatch_mnemonic(snapshot).upper().startswith("SUMMARY"):
                self._remember_stream_summary_entry_snapshot(
                    snapshot,
                    evidence_class=EVIDENCE_E0,
                )
                entries = list(self.stream_summary_entry_snapshots.get(int(bb_addr), {}).values())
        try:
            manager = getattr(self.emulator, "branch_snapshot_manager", None)
            for snapshot in list(getattr(manager, "snapshot_history", {}).get(int(bb_addr), []) or []):
                if self._snapshot_dispatch_mnemonic(snapshot).upper().startswith("SUMMARY"):
                    self._remember_stream_summary_entry_snapshot(
                        snapshot,
                        evidence_class=EVIDENCE_E0,
                    )
            entries = list(self.stream_summary_entry_snapshots.get(int(bb_addr), {}).values())
        except Exception:
            pass
        entries.sort(
            key=lambda entry: (
                len(self._scope_signature_from_snapshot_entry(entry)),
                int(getattr(getattr(entry, "snapshot", None), "capture_order", 0) or 0),
                int(getattr(entry, "branch_depth", 0) or 0),
            ),
            reverse=True,
        )
        return entries

    @staticmethod
    def _is_rtos_thread_create_symbol(name: object) -> bool:
        text = str(name or "").strip().lower()
        if not text:
            return False
        return (
            "thread_create" in text
            or "task_create" in text
            or "taskcreate" in text
            or "osthreadnew" in text
            or "os_thread_create" in text
        )

    def _direct_call_target_symbol(self, insn: Dict[str, object]) -> Tuple[Optional[int], str]:
        target = _parse_direct_target(insn.get("operands"))
        if target is None:
            return None, ""
        resolved = self.prepared.resolve_basic_block(target)
        target_addr = int(resolved if resolved is not None else target) & ~1
        name = getattr(self.prepared, "symbols_by_addr", {}).get(target_addr, "")
        if not name or str(name).startswith("$"):
            name = self._function_name_for_addr(target_addr)
        return target_addr, str(name or "")

    def _read_snapshot_word(self, snapshot: object, address: int) -> Optional[int]:
        try:
            address = int(address) & 0xFFFFFFFF
        except Exception:
            return None
        memory_regions = getattr(snapshot, "memory_regions", {}) or {}
        for (base, size), data in memory_regions.items():
            base_i = int(base)
            size_i = int(size)
            if base_i <= address <= base_i + size_i - 4:
                offset = address - base_i
                try:
                    return int.from_bytes(bytes(data)[offset:offset + 4], "little") & 0xFFFFFFFF
                except Exception as exc:
                    self._record_probe_diagnostic(
                        "rtos_thread_arg_probe",
                        "probe_run_exception",
                        error=exc,
                        pred_bb=int(pred_bb),
                        branch_pc=int(branch_pc),
                    )
                    return None
        memory_base = int(getattr(snapshot, "memory_base", 0) or 0)
        memory_data = getattr(snapshot, "memory_data", b"") or b""
        if memory_base <= address <= memory_base + len(memory_data) - 4:
            offset = address - memory_base
            try:
                return int.from_bytes(bytes(memory_data)[offset:offset + 4], "little") & 0xFFFFFFFF
            except Exception:
                return None
        return None

    def _entry_addr_from_thread_create_snapshot(self, snapshot: object) -> Optional[int]:
        call_args = self._thread_create_call_args(snapshot)
        if call_args.get("entry") is not None:
            return int(call_args["entry"])
        registers = getattr(snapshot, "registers", {}) or {}
        candidate_values: List[int] = []
        for reg_name in ("r0", "r1", "r2", "r3"):
            try:
                candidate_values.append(int(registers.get(reg_name, 0) or 0))
            except Exception:
                pass
        try:
            sp = int(registers.get("sp", 0) or 0)
        except Exception:
            sp = 0
        if sp:
            for offset in range(0, 64, 4):
                value = self._read_snapshot_word(snapshot, sp + offset)
                if value is not None:
                    candidate_values.append(value)
        for value in candidate_values:
            resolved = self.prepared.resolve_basic_block(int(value) & ~1)
            if resolved is not None:
                return int(resolved)
        return None

    def _thread_create_call_args(self, snapshot: object) -> Dict[str, int]:
        registers = getattr(snapshot, "registers", {}) or {}

        def reg(name: str) -> int:
            try:
                return int(registers.get(name, 0) or 0) & 0xFFFFFFFF
            except Exception:
                return 0

        args: List[int] = [reg("r0"), reg("r1"), reg("r2"), reg("r3")]
        sp = reg("sp")
        if sp:
            for offset in range(0, 64, 4):
                value = self._read_snapshot_word(snapshot, sp + offset)
                args.append(int(value) & 0xFFFFFFFF if value is not None else 0)

        entry = None
        for value in args:
            resolved = self.prepared.resolve_basic_block(int(value) & ~1)
            if resolved is not None:
                entry = int(resolved)
                break

        result = {
            "stack_base": args[0] if len(args) > 0 else 0,
            "stack_size": args[1] if len(args) > 1 else 0,
            "priority": args[2] if len(args) > 2 else 0,
            "flags": args[3] if len(args) > 3 else 0,
            "entry": int(entry) if entry is not None else 0,
            "arg": 0,
        }
        if entry is not None:
            entry_raw = int(entry) & ~1
            for index, value in enumerate(args):
                if (int(value) & ~1) == entry_raw:
                    if index + 1 < len(args):
                        result["arg"] = int(args[index + 1]) & 0xFFFFFFFF
                    break
        return result

    def _decode_thread_create_args_from_registers(
        self,
        registers: Dict[str, int],
        read_word,
    ) -> Dict[str, int]:
        def reg(name: str) -> int:
            try:
                return int(registers.get(name, 0) or 0) & 0xFFFFFFFF
            except Exception:
                return 0

        args: List[int] = [reg("r0"), reg("r1"), reg("r2"), reg("r3")]
        sp = reg("sp")
        if sp:
            for offset in range(0, 64, 4):
                try:
                    value = read_word(sp + offset)
                except Exception:
                    value = None
                args.append(int(value) & 0xFFFFFFFF if value is not None else 0)

        entry = None
        for value in args:
            resolved = self.prepared.resolve_basic_block(int(value) & ~1)
            if resolved is not None:
                entry = int(resolved)
                break

        result = {
            "stack_base": args[0] if len(args) > 0 else 0,
            "stack_size": args[1] if len(args) > 1 else 0,
            "priority": args[2] if len(args) > 2 else 0,
            "flags": args[3] if len(args) > 3 else 0,
            "entry": int(entry) if entry is not None else 0,
            "arg": 0,
        }
        if entry is not None:
            entry_raw = int(entry) & ~1
            for index, value in enumerate(args):
                if (int(value) & ~1) == entry_raw:
                    if index + 1 < len(args):
                        result["arg"] = int(args[index + 1]) & 0xFFFFFFFF
                    break
        return result

    def _thread_create_call_args_from_live_pre_call(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        pred_bb: int,
    ) -> Optional[Dict[str, int]]:
        cache_key = (int(pred_bb), self._snapshot_entry_identity(snapshot_entry))
        cached = self.rtos_thread_call_arg_cache.get(cache_key)
        if cached is not None:
            return dict(cached)

        snapshot = getattr(snapshot_entry, "snapshot", None)
        if snapshot is None:
            return None
        insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
        branch_pc = int(insn.get("address", pred_bb) or pred_bb)
        if branch_pc <= int(pred_bb):
            call_args = self._thread_create_call_args(snapshot)
            self.rtos_thread_call_arg_cache[cache_key] = call_args
            return dict(call_args)

        try:
            emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=self._effective_llm_config_path(),
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=self._temp_stage_for("rtos_thread_arg_probe"),
            )
        except Exception as exc:
            # Argument recovery is an optional preflight probe.  The caller has
            # a snapshot-based fallback, so a temporary engine construction
            # failure must not abort the whole RTOS stage.
            logger.debug("RTOS thread argument probe creation failed: %s", exc)
            return None
        temp_mmio = None
        temp_tracer = None
        try:
            self._configure_emulator_feedback(emulator)
            emulator.enable_branch_snapshot = False
            temp_mmio = EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            temp_tracer = self._new_temp_register_tracer(emulator)
            restored = self._restore_branch_snapshot(
                emulator,
                snapshot,
                lineage_source=snapshot_entry,
            )
            if not restored:
                return None
            if not self._restore_replay_mmio_state(
                emulator,
                temp_mmio,
                snapshot_entry.mmio_state,
            ):
                return None
            self._apply_scoped_branch_constraints(
                temp_mmio,
                self._scope_signature_from_snapshot_entry(snapshot_entry),
                emulator=emulator,
            )
            run_result: Dict[str, object] = {"stop_reason": "not_started"}
            with self.guided_modules(temp_mmio, temp_tracer):
                try:
                    try:
                        run_result = emulator.run(
                            entry_point=None,
                            max_instructions=max(
                                1,
                                len(self.prepared.static_bbs.get(int(pred_bb), []))
                                + 8,
                            ),
                            timeout_seconds=0.25,
                            preserve_cpu_state=True,
                            stop_before_pc=branch_pc,
                        )
                    except TypeError:
                        # Older emulator adapters do not expose
                        # ``stop_before_pc``. Keep the compatibility retry,
                        # but make a failure in that retry observable too.
                        try:
                            run_result = emulator.run(
                                entry_point=None,
                                max_instructions=max(
                                    1,
                                    len(
                                        self.prepared.static_bbs.get(
                                            int(pred_bb), []
                                        )
                                    )
                                    + 8,
                                ),
                                timeout_seconds=0.25,
                                preserve_cpu_state=True,
                            )
                        except Exception as exc:
                            self._record_probe_diagnostic(
                                "rtos_thread_arg_probe",
                                "probe_run_exception",
                                error=exc,
                                pred_bb=int(pred_bb),
                                branch_pc=int(branch_pc),
                                compatibility_retry=True,
                            )
                            return None
                except Exception as exc:
                    self._record_probe_diagnostic(
                        "rtos_thread_arg_probe",
                        "probe_run_exception",
                        error=exc,
                        pred_bb=int(pred_bb),
                        branch_pc=int(branch_pc),
                    )
                    return None
            run_result = self._normalize_replay_run_result(
                run_result,
                execution_started=True,
                reason="rtos_thread_arg_probe_non_mapping_result",
            )
            if self._replay_result_has_failure(run_result):
                reason = str(
                    run_result.get("failure_reason")
                    or run_result.get("stop_reason")
                    or "rtos_thread_arg_probe_execution_failed"
                )
                self._record_probe_diagnostic(
                    "rtos_thread_arg_probe",
                    "probe_execution_failed",
                    run_result=run_result,
                    error=run_result.get("execution_error"),
                    pred_bb=int(pred_bb),
                    branch_pc=int(branch_pc),
                    failure_reason=reason,
                )
                return None
            if bool(getattr(emulator, "replay_state_poisoned", False)):
                self._record_probe_diagnostic(
                    "rtos_thread_arg_probe",
                    "probe_replay_state_poisoned",
                    run_result=run_result,
                    pred_bb=int(pred_bb),
                    branch_pc=int(branch_pc),
                )
                return None
            live_pc = int(emulator.uc.reg_read(UC_ARM_REG_PC)) & ~1
            if live_pc != branch_pc and str(run_result.get("stop_reason") or "") != "stop_before_pc":
                return None

            registers = emulator._get_registers()

            def read_word(address: int) -> Optional[int]:
                try:
                    return int.from_bytes(bytes(emulator.uc.mem_read(int(address), 4)), "little") & 0xFFFFFFFF
                except Exception:
                    return None

            call_args = self._decode_thread_create_args_from_registers(registers, read_word)
            self.rtos_thread_call_arg_cache[cache_key] = call_args
            return dict(call_args)
        finally:
            cleanup_error = self._safe_dispose_temp_emulator(
                emulator,
                mmio_handler=temp_mmio,
                register_tracer=temp_tracer,
                quarantine=None,
                stage_name=self._temp_stage_for("rtos_thread_arg_probe"),
            )
            if cleanup_error:
                self._record_probe_diagnostic(
                    "rtos_thread_arg_probe",
                    "probe_cleanup_exception",
                    error=cleanup_error,
                    pred_bb=int(pred_bb),
                    branch_pc=int(branch_pc),
                )

    def _rtos_thread_entry_candidates(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 0,
    ) -> List[Dict[str, object]]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if self.prepared.valid_bb_set else self.prepared.static_bb_set
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        candidates: List[Dict[str, object]] = []

        for pred_bb in sorted(covered):
            insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
            if not _is_direct_call_mnemonic(insn.get("mnemonic")):
                continue
            target_addr, target_symbol = self._direct_call_target_symbol(insn)
            if not target_symbol or not self._is_rtos_thread_create_symbol(target_symbol):
                continue
            snapshot_entries = self._direct_call_snapshot_entries(int(pred_bb))
            if not snapshot_entries:
                continue
            entry_items: List[Tuple[PrefixReplaySnapshot, int, int, List[int]]] = []
            for snapshot_entry in snapshot_entries:
                snapshot = getattr(snapshot_entry, "snapshot", None)
                if snapshot is None:
                    continue
                call_args = self._thread_create_call_args_from_live_pre_call(
                    snapshot_entry,
                    int(pred_bb),
                )
                if call_args is None:
                    call_args = self._thread_create_call_args(snapshot)
                entry_bb = int(call_args.get("entry", 0) or 0)
                if entry_bb is None or entry_bb not in scope:
                    continue
                attempt_key = (
                    int(pred_bb),
                    int(entry_bb),
                    self._snapshot_entry_identity(snapshot_entry),
                )
                if attempt_key in self.rtos_thread_entry_attempts_seen:
                    continue
                reachable = self._static_reachable_from_cached(
                    int(entry_bb),
                    effective_successors,
                    reachable_cache,
                )
                uncovered_downstream = (reachable & scope) - covered
                target_matches = sorted(reachable & target_filter)[:32] if target_filter else []
                if target_filter and not target_matches:
                    continue
                if not target_filter and not uncovered_downstream:
                    continue
                entry_items.append((
                    snapshot_entry,
                    int(entry_bb),
                    len(uncovered_downstream),
                    [int(bb) for bb in target_matches],
                ))
            if not entry_items:
                continue
            entry_items.sort(
                key=lambda item: (
                    len(item[3]),
                    item[2],
                    -int(item[1]),
                    len(tuple(getattr(item[0], "source_path_signature", tuple()) or tuple())),
                    int(getattr(getattr(item[0], "snapshot", None), "capture_order", 0) or 0),
                ),
                reverse=True,
            )
            candidates.append({
                "pred_bb": int(pred_bb),
                "thread_create_target": target_addr,
                "thread_create_symbol": target_symbol,
                "entry_items": entry_items,
                "priority": (
                    max(len(item[3]) for item in entry_items),
                    max(item[2] for item in entry_items),
                    len(entry_items),
                    -int(pred_bb),
                ),
            })

        candidates.sort(key=lambda item: item["priority"], reverse=True)
        candidates = _segment_rotate_sequence(candidates, "rtos_thread_candidates")
        if max_targets and max_targets > 0:
            candidates = candidates[:max_targets]
        return candidates

    def _ordered_replay_snapshots(self, emulator: IntelligentEmulator) -> List[object]:
        manager = getattr(emulator, "branch_snapshot_manager", None)
        if manager is None:
            return []
        try:
            history = list(manager.get_ordered_snapshot_history())
        except Exception:
            history = []
        if history:
            return history
        try:
            return list(manager.get_ordered_snapshots())
        except Exception:
            return []

    def _snapshot_dispatch_mnemonic(self, snapshot: object) -> str:
        address = int(getattr(snapshot, "address", 0) or 0)
        condition = _normalize_mnemonic(getattr(snapshot, "condition", ""))
        if (
            condition.startswith("SUMMARY")
            or condition in SWITCH_DISPATCH_MNEMONICS
            or _is_call_frontier_mnemonic(condition)
            or _is_frontier_branch_mnemonic(condition)
            or _is_direct_call_mnemonic(condition)
        ):
            return condition

        insn = self.prepared.branch_instruction_by_bb.get(address, {})
        mnemonic = _dispatch_mnemonic_for_instruction(insn) if insn else ""
        if mnemonic:
            if condition in THUMB_CONDITION_CODES and (
                mnemonic.startswith("B") or mnemonic.startswith("IT")
            ):
                return mnemonic
            if _is_dispatch_frontier_mnemonic(mnemonic) or _is_direct_call_mnemonic(mnemonic):
                return mnemonic

        if condition in THUMB_CONDITION_CODES:
            return f"B{condition}"
        return condition

    @staticmethod
    def _queue_path_signature(
        choices: Dict[Tuple[int, int], object],
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        return queue_path_signature(choices)

    @staticmethod
    def _is_switch_branch_event(event: object) -> bool:
        return is_switch_branch_event(event)

    def _compact_branch_events(self, events: Iterable[object]) -> List[object]:
        first_by_edge = {}
        last_order_by_edge = {}
        for event in events or []:
            if self._is_switch_branch_event(event):
                edge = (int(getattr(event, "address", 0)), getattr(event, "original_index", None))
            else:
                edge = (int(getattr(event, "address", 0)), bool(getattr(event, "original_taken", False)))
            first_by_edge.setdefault(edge, event)
            last_order_by_edge[edge] = int(getattr(event, "order", 0))
        return [
            first_by_edge[edge]
            for edge in sorted(first_by_edge, key=lambda item: last_order_by_edge[item])
        ]

    def _branch_event_choice_values(self, event: object) -> List[object]:
        if self._is_switch_branch_event(event):
            values = []
            seen_targets = set()
            original_index = getattr(event, "original_index", None)
            for index, target in enumerate(getattr(event, "alternatives", []) or []):
                if target == 0 or index == original_index or target in seen_targets:
                    continue
                seen_targets.add(target)
                values.append(index)
            return values
        if _is_call_frontier_mnemonic(getattr(event, "condition", "")):
            values = []
            seen_targets = set()
            alternatives = list(getattr(event, "alternatives", []) or [])
            if not alternatives:
                alternatives = [
                    int(getattr(event, "target", 0) or 0),
                    int(getattr(event, "fallthrough", 0) or 0),
                ]
            for target in alternatives:
                successor = self.prepared.resolve_basic_block(int(target or 0))
                if successor is None or successor in seen_targets:
                    continue
                seen_targets.add(successor)
                values.append(int(successor))
            return values
        return [not bool(getattr(event, "original_taken", False))]

    def _branch_event_choice_successor_bb(
        self,
        event: object,
        choice: Optional[object] = None,
    ) -> Optional[int]:
        if self._is_switch_branch_event(event):
            alternatives = list(getattr(event, "alternatives", []) or [])
            if choice is None:
                for candidate in self._branch_event_choice_values(event):
                    successor = self._branch_event_choice_successor_bb(event, candidate)
                    if successor is not None and successor not in self.global_coverage:
                        return successor
                return None
            try:
                index = int(choice)
            except (TypeError, ValueError):
                return None
            if index < 0 or index >= len(alternatives) or int(alternatives[index] or 0) == 0:
                return None
            return self.prepared.resolve_basic_block(int(alternatives[index]))

        if _is_call_frontier_mnemonic(getattr(event, "condition", "")):
            if choice is None:
                for candidate in self._branch_event_choice_values(event):
                    successor = self._branch_event_choice_successor_bb(event, candidate)
                    if successor is not None and successor not in self.global_coverage:
                        return successor
                return None
            try:
                return self.prepared.resolve_basic_block(int(choice))
            except (TypeError, ValueError):
                return None

        direction = (not bool(getattr(event, "original_taken", False))) if choice is None else bool(choice)
        target = int(getattr(event, "target", 0) or 0)
        fallthrough = int(getattr(event, "fallthrough", 0) or 0)
        return self.prepared.resolve_basic_block(target if direction else fallthrough)

    def _harvest_branch_mmio_success(
        self,
        branch_key: Tuple[int, int],
        branch_choice: object,
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...],
        replay_events: Iterable[object],
        replay_snapshots: Iterable[object],
        *,
        evidence_class: object = None,
        enqueue_child_tasks: bool = False,
        remember_main_events: bool = True,
        overwrite_main_events: bool = True,
    ) -> Dict[str, int]:
        normalized_source = self._ordered_source_path_signature(tuple(source_path_signature or tuple()))
        successful_path_signature = self._ordered_source_path_signature(
            tuple(list(normalized_source) + [((int(branch_key[0]), int(branch_key[1])), branch_choice)])
        )
        replay_evidence = normalize_evidence_class(evidence_class)
        if replay_evidence == EVIDENCE_UNKNOWN:
            # A successful replay is not E1 merely because this helper was
            # reached. E1 requires explicit feedback that an external fact was
            # consumed; callers with that proof pass the evidence class.
            replay_evidence = EVIDENCE_E2
        replay_assumption = {
            EVIDENCE_E0: "reset_entry_execution",
            EVIDENCE_E1: "consumed_environment_fact",
            EVIDENCE_E2: "forced_control",
            EVIDENCE_E3: "execution_context_recovery",
        }.get(replay_evidence, "unknown")
        self._path_naturalization_ledger().register_path_evidence(
            successful_path_signature,
            replay_evidence,
            source_phase="branch_mmio_harvest",
            assumptions=(replay_assumption,),
        )
        observed_direction_updates = (
            self._remember_observed_branch_directions(replay_events)
            if replay_evidence in {EVIDENCE_E0, EVIDENCE_E1}
            else 0
        )
        remembered_events = (
            self._remember_main_branch_events(
                replay_events,
                overwrite_existing=overwrite_main_events,
                evidence_class=replay_evidence,
            )
            if remember_main_events
            else 0
        )
        remembered_snapshots = self._remember_branch_root_snapshots(
            replay_events,
            replay_snapshots,
            source_path_signature=successful_path_signature,
            evidence_class=replay_evidence,
        )
        dynamic_edges = self._record_dynamic_successors(replay_events)

        root_choices = {
            (int(key[0]), int(key[1])): choice
            for key, choice in successful_path_signature
        }
        root_edge = ((int(branch_key[0]), int(branch_key[1])), branch_choice)
        root_queue_signature = self._queue_path_signature(root_choices)
        self.reservoir_pending_paths.discard(root_queue_signature)
        self.reservoir_incomplete_paths.discard(root_queue_signature)
        self.reservoir_explored_paths.add(root_queue_signature)
        self._record_reservoir_explored_edge(root_edge[0], root_edge[1], replay_evidence)

        root_depth = None
        for event in replay_events or []:
            if self._branch_event_key(event) == branch_key:
                root_depth = int(getattr(event, "depth", 0))
                break
        if root_depth is None:
            known_root_event = self.known_main_branch_events.get(branch_key)
            if known_root_event is not None:
                root_depth = int(getattr(known_root_event, "depth", 0))

        compacted_children = [
            event
            for event in self._compact_branch_events(replay_events)
            if self._branch_event_key(event) not in root_choices
        ]
        if root_depth is not None:
            deeper_children = [
                event
                for event in compacted_children
                if int(getattr(event, "depth", 0)) > int(root_depth)
            ]
            if deeper_children:
                first_child_depth = min(int(getattr(event, "depth", 0)) for event in deeper_children)
                compacted_children = [
                    event
                    for event in deeper_children
                    if int(getattr(event, "depth", 0)) == first_child_depth
                ]

        harvested_seed_roots = 0
        for child in compacted_children:
            child_key = self._branch_event_key(child)
            if child_key == branch_key:
                continue
            if child_key not in self.branch_mmio_pending_root_keys:
                self.branch_mmio_pending_root_keys.add(child_key)
                harvested_seed_roots += 1

        child_tasks_enqueued = 0
        if enqueue_child_tasks:
            for child in reversed(compacted_children):
                child_key = self._branch_event_key(child)
                for child_choice in self._branch_event_choice_values(child):
                    successor = self._branch_event_choice_successor_bb(child, child_choice)
                    if successor is not None and successor in self.global_coverage:
                        continue
                    child_choices = dict(root_choices)
                    child_choices[child_key] = child_choice
                    child_signature = self._queue_path_signature(child_choices)
                    if (
                        child_signature in self.reservoir_explored_paths
                        or child_signature in self.reservoir_incomplete_paths
                        or child_signature in self.reservoir_pending_paths
                    ):
                        continue
                    if self._is_switch_branch_event(child):
                        self.reservoir_task_queue.append((branch_key, child_choices, root_edge))
                    else:
                        self.reservoir_task_queue.appendleft((branch_key, child_choices, root_edge))
                    self.reservoir_pending_paths.add(child_signature)
                    child_tasks_enqueued += 1

        return {
            "remembered_branch_events": int(remembered_events),
            "observed_direction_updates": int(observed_direction_updates),
            "remembered_branch_root_snapshots": int(remembered_snapshots),
            "dynamic_successor_edges_added": int(dynamic_edges),
            "harvested_seed_roots": int(harvested_seed_roots),
            "child_tasks_enqueued": int(child_tasks_enqueued),
        }

    def _harvest_dispatch_state_seed(
        self,
        root_key: Tuple[int, int],
        root_choices: Dict[Tuple[int, int], object],
        replay_events: Iterable[object],
        replay_snapshots: Iterable[object],
        *,
        max_child_depth_delta: int = -1,
        max_children_per_depth: int = 0,
        anchor_key: Optional[Tuple[int, int]] = None,
    ) -> Dict[str, int]:
        normalized_choices = {
            (int(key[0]), int(key[1])): choice
            for key, choice in dict(root_choices or {}).items()
        }
        if not normalized_choices:
            return {
                "remembered_branch_events": 0,
                "remembered_branch_root_snapshots": 0,
                "dynamic_successor_edges_added": 0,
                "harvested_seed_roots": 0,
            }

        source_path_signature = self._ordered_source_path_signature(
            tuple(normalized_choices.items())
        )
        remembered_events = self._remember_main_branch_events(
            replay_events,
            overwrite_existing=False,
            evidence_class=EVIDENCE_E2,
        )
        remembered_snapshots = self._remember_branch_root_snapshots(
            replay_events,
            replay_snapshots,
            source_path_signature=source_path_signature,
            evidence_class=EVIDENCE_E2,
        )
        dynamic_edges = self._record_dynamic_successors(replay_events)
        replay_position_by_key: Dict[Tuple[int, int], Tuple[int, int]] = {}
        for event in replay_events or []:
            key = self._branch_event_key(event)
            position = (
                int(getattr(event, "depth", 0) or 0),
                int(getattr(event, "order", 0) or 0),
            )
            existing_position = replay_position_by_key.get(key)
            if existing_position is None or position < existing_position:
                replay_position_by_key[key] = position

        root_depth = None
        effective_anchor_key = (
            (int(anchor_key[0]), int(anchor_key[1]))
            if isinstance(anchor_key, (list, tuple)) and len(anchor_key) == 2
            else (int(root_key[0]), int(root_key[1]))
        )
        known_root_event = self.known_main_branch_events.get(effective_anchor_key)
        if known_root_event is not None:
            root_depth = int(getattr(known_root_event, "depth", 0) or 0)
        if root_depth is None:
            for event in replay_events or []:
                if self._branch_event_key(event) == effective_anchor_key:
                    root_depth = int(getattr(event, "depth", 0) or 0)
                    break

        depth_buckets: Dict[int, List[object]] = {}
        dispatch_child_keys = set()
        for child in self._compact_branch_events(replay_events):
            child_key = self._branch_event_key(child)
            if child_key in normalized_choices or child_key == root_key:
                continue
            child_depth = int(getattr(child, "depth", 0) or 0)
            if root_depth is not None:
                if child_depth <= root_depth:
                    continue
                if max_child_depth_delta >= 0 and child_depth - root_depth > max_child_depth_delta:
                    continue
            depth_buckets.setdefault(child_depth, []).append(child)
            if self._is_switch_branch_event(child) or _is_call_frontier_mnemonic(
                getattr(child, "condition", "")
            ):
                dispatch_child_keys.add(child_key)

        remembered_provenance_signatures = 0
        harvested_seed_roots = 0
        harvested_root_keys: List[Tuple[int, int]] = []
        selected_children: List[object] = []
        for child_depth in sorted(depth_buckets):
            children = depth_buckets[child_depth]
            children.sort(
                key=lambda event: (
                    1 if self._is_switch_branch_event(event) else 0,
                    1 if _is_call_frontier_mnemonic(getattr(event, "condition", "")) else 0,
                    int(getattr(event, "order", 0) or 0),
                    self._branch_event_key(event),
                ),
                reverse=True,
            )
            if max_children_per_depth > 0:
                children = children[:max_children_per_depth]
            selected_children.extend(children)

        for child in selected_children:
            child_key = self._branch_event_key(child)
            child_source_signature = self._event_source_signature(
                child,
                source_path_signature,
                position_lookup=(
                    replay_position_by_key
                    if self._root_provenance_replay_order_enabled()
                    else None
                ),
            )
            provenance_signatures = self.known_branch_root_provenance_signatures.setdefault(
                child_key,
                set(),
            )
            if child_source_signature not in provenance_signatures:
                provenance_signatures.add(child_source_signature)
                remembered_provenance_signatures += 1
            self.branch_mmio_harvested_root_keys.add(child_key)
            harvested_root_keys.append(child_key)
            if child_key not in self.branch_mmio_pending_root_keys:
                self.branch_mmio_pending_root_keys.add(child_key)
                harvested_seed_roots += 1

        return {
            "remembered_branch_events": int(remembered_events),
            "remembered_branch_root_snapshots": int(remembered_snapshots),
            "dynamic_successor_edges_added": int(dynamic_edges),
            "remembered_provenance_signatures": int(remembered_provenance_signatures),
            "harvested_seed_roots": int(harvested_seed_roots),
            "harvested_root_keys": [
                (int(key[0]), int(key[1]))
                for key in harvested_root_keys
            ],
            "selected_child_count": int(len(selected_children)),
            "selected_dispatch_child_count": int(
                sum(
                    1
                    for child in selected_children
                    if self._branch_event_key(child) in dispatch_child_keys
                )
            ),
            "anchor_key": (
                int(effective_anchor_key[0]),
                int(effective_anchor_key[1]),
            ),
            "max_child_depth_delta": int(max_child_depth_delta),
            "max_children_per_depth": int(max_children_per_depth),
        }

    def _clone_branch_event(self, event, order: Optional[int] = None):
        assigned_order = self.known_main_branch_event_order if order is None else int(order)
        return SimpleNamespace(
            address=int(getattr(event, "address", 0)),
            branch_pc=int(getattr(event, "branch_pc", 0)),
            target=int(getattr(event, "target", 0) or 0),
            fallthrough=int(getattr(event, "fallthrough", 0) or 0),
            condition=str(getattr(event, "condition", "")),
            original_taken=bool(getattr(event, "original_taken", False)),
            order=assigned_order,
            depth=int(getattr(event, "depth", 0)),
            occurrence_index=int(getattr(event, "occurrence_index", 1)),
            alternatives=[int(item or 0) for item in getattr(event, "alternatives", [])],
            original_index=getattr(event, "original_index", None),
            first_order=int(getattr(event, "first_order", getattr(event, "order", assigned_order))),
            first_depth=int(getattr(event, "first_depth", getattr(event, "depth", 0))),
            first_occurrence_index=int(
                getattr(event, "first_occurrence_index", getattr(event, "occurrence_index", 1))
            ),
            original_direction_known=bool(
                getattr(event, "original_direction_known", True)
            ),
            direction_provenance=str(
                getattr(event, "direction_provenance", "unicorn_execution")
                or "unicorn_execution"
            ),
            synthetic=bool(getattr(event, "synthetic", False)),
            context_signature=dict(
                getattr(event, "context_signature", {}) or {}
            ),
        )

    def _refresh_loop_exit_iteration_hints(self):
        hints: Dict[int, int] = {}
        for event in self.known_main_branch_events.values():
            address = int(getattr(event, "address", 0) or 0)
            target = int(getattr(event, "target", 0) or 0)
            occurrence_index = int(
                getattr(
                    event,
                    "first_occurrence_index",
                    getattr(event, "occurrence_index", 1),
                ) or 1
            )
            condition = _normalize_mnemonic(getattr(event, "condition", ""))
            if (
                not address
                or not bool(getattr(event, "original_direction_known", True))
                or condition in SWITCH_DISPATCH_MNEMONICS
                or bool(getattr(event, "original_taken", False))
                or occurrence_index <= 1
                or target != address
            ):
                continue
            natural_loop_iterations = occurrence_index - 1
            existing = hints.get(address)
            if existing is None or natural_loop_iterations > existing:
                hints[address] = natural_loop_iterations

        self.loop_exit_iteration_hints = hints
        self.prepared.loop_exit_iteration_hints = dict(hints)
        if _loop_exit_hints_enabled() and getattr(self, "emulator", None) is not None:
            self.emulator.loop_exit_iteration_hints = dict(hints)
            self.emulator.loop_intervention_threshold_cache.clear()

    def _remember_main_branch_events(
        self,
        events: Iterable[object],
        *,
        overwrite_existing: bool = True,
        evidence_class: Optional[str] = None,
    ) -> int:
        event_list = list(events or [])
        if evidence_class in {EVIDENCE_E0, EVIDENCE_E1}:
            self._remember_observed_branch_directions(event_list)
        if evidence_class is not None:
            self._remember_branch_direction_evidence(event_list, evidence_class)
        added = 0
        for event in event_list:
            key = self._branch_event_key(event)
            clone = self._clone_branch_event(event, order=self.known_main_branch_event_order)
            self.known_main_branch_event_order += 1
            existing = self.known_main_branch_events.get(key)
            if existing is None:
                self.known_main_branch_events[key] = clone
                added += 1
                continue
            existing_direction_known = bool(
                getattr(existing, "original_direction_known", True)
            )
            clone_direction_known = bool(
                getattr(clone, "original_direction_known", True)
            )
            if existing_direction_known != clone_direction_known:
                observed = clone if clone_direction_known else existing
                inferred = existing if clone_direction_known else clone
                merged_alternatives = []
                for candidate in list(
                    getattr(observed, "alternatives", []) or []
                ) + list(getattr(inferred, "alternatives", []) or []):
                    candidate_i = int(candidate or 0)
                    if candidate_i and candidate_i not in merged_alternatives:
                        merged_alternatives.append(candidate_i)
                observed.alternatives = merged_alternatives
                self.known_main_branch_events[key] = observed
                # A concrete execution direction always owns provenance; the
                # inferred successor set contributes candidates only.
                continue
            if not overwrite_existing:
                continue
            existing_first = (
                int(getattr(existing, "first_depth", getattr(existing, "depth", 0))),
                int(getattr(existing, "first_order", getattr(existing, "order", 0))),
                int(
                    getattr(
                        existing,
                        "first_occurrence_index",
                        getattr(existing, "occurrence_index", 1),
                    )
                ),
            )
            clone_first = (
                int(getattr(clone, "first_depth", getattr(clone, "depth", 0))),
                int(getattr(clone, "first_order", getattr(clone, "order", 0))),
                int(
                    getattr(
                        clone,
                        "first_occurrence_index",
                        getattr(clone, "occurrence_index", 1),
                    )
                ),
            )
            if existing_first <= clone_first:
                clone.first_depth = existing_first[0]
                clone.first_order = existing_first[1]
                clone.first_occurrence_index = existing_first[2]
            if (
                getattr(clone, "depth", 0),
                getattr(clone, "order", 0),
                getattr(clone, "address", 0),
            ) >= (
                getattr(existing, "depth", 0),
                getattr(existing, "order", 0),
                getattr(existing, "address", 0),
            ):
                self.known_main_branch_events[key] = clone
        self._refresh_loop_exit_iteration_hints()
        return added

    def _remember_branch_root_snapshots(
        self,
        events: Iterable[object],
        snapshots: Iterable[object],
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
        evidence_class: object = None,
        occurrence_events: Optional[Iterable[object]] = None,
        source_occurrence_signature: Tuple[
            Tuple[Tuple[int, int], object], ...
        ] = tuple(),
    ) -> int:
        event_list = list(events or [])
        occurrence_event_list = list(
            occurrence_events
            if occurrence_events is not None
            else event_list
        )
        snapshots_by_address: Dict[int, List[object]] = {}
        for snapshot in snapshots or []:
            address = int(getattr(snapshot, "address", 0) or 0)
            if not address:
                continue
            snapshots_by_address.setdefault(address, []).append(snapshot)
        for address in list(snapshots_by_address):
            snapshots_by_address[address].sort(
                key=lambda snapshot: (
                    int(getattr(snapshot, "occurrence_index", 1) or 1),
                    int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
                    int(getattr(snapshot, "order", 0) or 0),
                )
            )

        def snapshot_for_event(event):
            address = int(getattr(event, "address", 0) or 0)
            candidates = snapshots_by_address.get(address, [])
            if not candidates:
                return None
            event_occurrence = int(getattr(event, "occurrence_index", 1) or 1)
            event_order = int(getattr(event, "order", 0) or 0)
            event_depth = int(getattr(event, "depth", 0) or 0)
            return min(
                candidates,
                key=lambda snapshot: (
                    abs(int(getattr(snapshot, "occurrence_index", 1) or 1) - event_occurrence),
                    0
                    if int(getattr(snapshot, "occurrence_index", 1) or 1) <= event_occurrence
                    else 1,
                    abs(int(getattr(snapshot, "order", 0) or 0) - event_order),
                    abs(int(getattr(snapshot, "depth", 0) or 0) - event_depth),
                    int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
                ),
            )

        added = 0
        normalized_source_signature = self._ordered_source_path_signature(
            tuple(source_path_signature or tuple())
        )
        capture_evidence = self._capture_evidence_class(
            normalized_source_signature,
            evidence_class,
        )
        normalized_source_occurrences = normalize_naturalization_signature(
            tuple(source_occurrence_signature or tuple())
        )
        combined_occurrence_trace = self._extend_occurrence_signature(
            normalized_source_occurrences,
            occurrence_event_list,
        )
        source_occurrence_counts: Dict[int, int] = {}
        for source_key, _source_choice in normalized_source_occurrences:
            source_address = int(source_key[0]) & 0xFFFFFFFF
            source_occurrence_counts[source_address] = max(
                int(source_occurrence_counts.get(source_address, 0) or 0),
                max(1, int(source_key[1])),
            )
        local_to_global_key: Dict[Tuple[int, int], Tuple[int, int]] = {}
        for event in occurrence_event_list:
            local_key = self._branch_event_key(event)
            local_to_global_key[local_key] = (
                int(local_key[0]) & 0xFFFFFFFF,
                int(source_occurrence_counts.get(int(local_key[0]), 0) or 0)
                + max(1, int(local_key[1])),
            )
        occurrence_position_by_key = {
            key: (index, index)
            for index, (key, _choice) in enumerate(combined_occurrence_trace)
        }
        occurrence_index_by_key = {
            key: index
            for index, (key, _choice) in enumerate(combined_occurrence_trace)
        }
        matched_snapshot_addresses: Set[int] = set()
        snapshot_occurrence_prefixes: Dict[
            int,
            Tuple[Tuple[Tuple[int, int], object], ...],
        ] = {}
        for event in event_list:
            key = self._branch_event_key(event)
            global_key = local_to_global_key.get(key, key)
            snapshot = snapshot_for_event(event)
            if snapshot is None:
                continue
            matched_snapshot_addresses.add(int(getattr(event, "address", 0)))
            source_event = event
            if global_key != key:
                # BranchEvent is slotted to reduce per-event memory.  A
                # shallow copy preserves the event schema for both slotted
                # dataclasses and legacy namespace-like event objects without
                # relying on ``__dict__``.
                source_event = copy.copy(event)
                source_event.occurrence_index = int(global_key[1])
            normalized_signature = self._event_source_signature(
                source_event,
                normalized_source_signature,
                position_lookup=(
                    occurrence_position_by_key
                    if self._root_provenance_replay_order_enabled()
                    else None
                ),
            )
            occurrence_prefix_len = int(
                occurrence_index_by_key.get(
                    global_key,
                    len(normalized_source_occurrences),
                )
            )
            snapshot_prefix = combined_occurrence_trace[:occurrence_prefix_len]
            existing_snapshot_prefix = snapshot_occurrence_prefixes.get(
                id(snapshot)
            )
            if (
                existing_snapshot_prefix is None
                or len(snapshot_prefix) < len(existing_snapshot_prefix)
            ):
                snapshot_occurrence_prefixes[id(snapshot)] = snapshot_prefix
            existing = self.known_branch_root_snapshots.get(key)
            entry = PrefixReplaySnapshot(
                prefix_signature=tuple(),
                next_branch_key=key,
                snapshot=snapshot,
                mmio_state=self._interrupt_context_mmio_state(snapshot),
                source_path_signature=normalized_signature,
                branch_depth=int(getattr(event, "depth", 0)),
                origin="root",
                evidence_class=capture_evidence,
                source_occurrence_trace=combined_occurrence_trace,
                source_occurrence_prefix_len=occurrence_prefix_len,
            )
            variant_key = self._root_snapshot_variant_key(
                normalized_signature,
                snapshot_prefix,
            )
            if existing is None:
                self.known_branch_root_snapshots[key] = {
                    variant_key: entry,
                }
                added += 1
                self._trim_root_snapshot_variants(key)
                continue
            existing_entry = existing.get(variant_key)
            if existing_entry is None:
                existing[variant_key] = entry
                added += 1
                self._trim_root_snapshot_variants(key)
                continue
            if (
                int(getattr(snapshot, "order", 0)),
                int(getattr(event, "depth", 0)),
            ) <= (
                int(getattr(existing_entry.snapshot, "order", 0)),
                int(getattr(existing_entry, "branch_depth", 0)),
            ):
                existing[variant_key] = entry
                self._trim_root_snapshot_variants(key)

        def occurrence_prefix_for_snapshot(snapshot: object):
            known_prefix = snapshot_occurrence_prefixes.get(id(snapshot))
            if known_prefix is not None:
                return known_prefix
            return self._occurrence_prefix_before_snapshot(
                normalized_source_occurrences,
                occurrence_event_list,
                snapshot,
            )

        for snapshot in snapshots or []:
            snapshot_occurrence_prefix = occurrence_prefix_for_snapshot(
                snapshot
            )
            if self._remember_direct_call_snapshot(
                snapshot,
                normalized_source_signature,
                evidence_class=capture_evidence,
                source_occurrence_signature=snapshot_occurrence_prefix,
            ):
                added += 1
            if self._remember_stream_summary_entry_snapshot(
                snapshot,
                normalized_source_signature,
                evidence_class=capture_evidence,
                source_occurrence_signature=snapshot_occurrence_prefix,
            ):
                added += 1

        # Entry snapshots for TBB/TBH and register-indirect dispatches can
        # exist even when no post-branch event was recorded. Preserve them as
        # synthetic roots so frontier targeting can schedule only states that
        # were first reached by Unicorn from an entry-derived replay.
        for snapshot in snapshots or []:
            address = int(getattr(snapshot, "address", 0) or 0)
            if not address or address in matched_snapshot_addresses:
                continue
            condition = self._snapshot_dispatch_mnemonic(snapshot)
            alternatives = [
                int(target or 0)
                for target in getattr(snapshot, "alternatives", []) or []
            ]
            if condition in SWITCH_DISPATCH_MNEMONICS:
                target = next((target for target in alternatives if target), 0)
                fallthrough = 0
                original_taken = False
                original_index = getattr(snapshot, "original_index", None)
            elif _is_call_frontier_mnemonic(condition) and any(alternatives):
                target = next((target for target in alternatives if target), 0)
                fallthrough = next((target for target in alternatives[1:] if target), 0)
                original_taken = True
                original_index = 0
            elif _is_frontier_branch_mnemonic(condition):
                target = int(getattr(snapshot, "target", 0) or 0)
                fallthrough = int(getattr(snapshot, "fallthrough", 0) or 0)
                if target <= 0 and fallthrough <= 0:
                    continue
                original_taken = bool(getattr(snapshot, "original_taken", False))
                snapshot_original_index = getattr(snapshot, "original_index", None)
                original_index = (
                    int(snapshot_original_index)
                    if snapshot_original_index is not None
                    else 0 if original_taken else 1
                )
                alternatives = [
                    int(item)
                    for item in (target, fallthrough)
                    if int(item or 0) > 0
                ]
            else:
                continue
            key = (address, 1)
            if key not in self.known_main_branch_events:
                insn = self.prepared.branch_instruction_by_bb.get(address, {})
                event = SimpleNamespace(
                    address=address,
                    branch_pc=int(insn.get("address", address)),
                    target=target,
                    fallthrough=fallthrough,
                    condition=condition,
                    original_taken=original_taken,
                    order=self.known_main_branch_event_order,
                    depth=int(getattr(snapshot, "depth", 0)),
                    occurrence_index=1,
                    alternatives=alternatives,
                    original_index=original_index,
                    first_order=self.known_main_branch_event_order,
                    first_depth=int(getattr(snapshot, "depth", 0)),
                    first_occurrence_index=1,
                    original_direction_known=False,
                    direction_provenance="entry_snapshot_without_branch_event",
                    synthetic=True,
                    context_signature={},
                )
                self.known_main_branch_events[key] = event
                self.known_main_branch_event_order += 1
            synthetic_event = self.known_main_branch_events[key]
            normalized_signature = self._event_source_signature(synthetic_event, normalized_source_signature)
            entry = PrefixReplaySnapshot(
                prefix_signature=tuple(),
                next_branch_key=key,
                snapshot=snapshot,
                mmio_state=self._interrupt_context_mmio_state(snapshot),
                source_path_signature=normalized_signature,
                branch_depth=int(getattr(snapshot, "depth", 0)),
                origin="root",
                evidence_class=capture_evidence,
                source_occurrence_trace=combined_occurrence_trace,
                source_occurrence_prefix_len=len(
                    normalized_source_occurrences
                ),
            )
            existing = self.known_branch_root_snapshots.setdefault(key, {})
            variant_key = self._root_snapshot_variant_key(
                normalized_signature,
                normalized_source_occurrences,
            )
            if variant_key not in existing:
                existing[variant_key] = entry
                added += 1
                self._trim_root_snapshot_variants(key)
        return added

    def _ensure_dynamic_dispatch_root_events(
        self,
        covered_bbs: Iterable[int],
        *,
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
        evidence_class: object = None,
    ) -> int:
        """
        Synthesize root events for covered call-like dispatch BBs whose dynamic
        successors are known but which never appear in branch_event history.

        This keeps replay semantics natural: the task still replays from an
        entry/prefix snapshot and reaches the dispatch BB honestly, but the
        scheduler can now treat uncovered BL/BLX/BX frontiers as roots instead
        of merely reporting them in uncovered_summary().
        """
        covered = self.validate_coverage(covered_bbs or set())
        if not covered:
            return 0

        added = 0
        effective_successors = self._effective_successor_map()
        normalized_source_signature = self._ordered_source_path_signature(
            tuple(source_path_signature or tuple())
        )
        capture_evidence = self._capture_evidence_class(
            normalized_source_signature,
            evidence_class,
        )
        source_depths = []
        source_orders = []
        for choice_key, _choice in normalized_source_signature:
            source_event = self.known_main_branch_events.get(choice_key)
            if source_event is None:
                continue
            source_depths.append(int(getattr(source_event, "first_depth", getattr(source_event, "depth", 0)) or 0))
            source_orders.append(int(getattr(source_event, "first_order", getattr(source_event, "order", 0)) or 0))
        synthesized_depth = (max(source_depths) + 1) if source_depths else 0
        synthesized_first_order = (max(source_orders) + 1) if source_orders else self.known_main_branch_event_order
        for bb_addr in sorted(covered):
            insn = self.prepared.branch_instruction_by_bb.get(int(bb_addr), {})
            mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
            if not _is_indirect_dispatch_mnemonic(mnemonic):
                continue
            successors = sorted(
                int(successor)
                for successor in effective_successors.get(int(bb_addr), set())
                if int(successor) in self.prepared.static_bb_set
            )
            if len(successors) < 2:
                continue
            key = (int(bb_addr), 1)
            if key not in self.known_main_branch_events:
                observed_successor = successors[0]
                fallback_successor = successors[1] if len(successors) > 1 else 0
                event = SimpleNamespace(
                    address=int(bb_addr),
                    branch_pc=int(insn.get("address", bb_addr)),
                    target=int(observed_successor),
                    fallthrough=int(fallback_successor),
                    condition=mnemonic,
                    original_taken=True,
                    order=self.known_main_branch_event_order,
                    depth=synthesized_depth,
                    occurrence_index=1,
                    alternatives=[int(item) for item in successors],
                    original_index=0,
                    first_order=synthesized_first_order,
                    first_depth=synthesized_depth,
                    first_occurrence_index=1,
                    original_direction_known=False,
                    direction_provenance="dynamic_successor_set",
                    synthetic=True,
                )
                self.known_main_branch_events[key] = event
                self.known_main_branch_event_order += 1
                added += 1

            normalized_signature = self._event_source_signature(
                self.known_main_branch_events[key],
                normalized_source_signature,
            )
            if not hasattr(self, "known_branch_root_provenance_signatures"):
                self.known_branch_root_provenance_signatures = {}
            self.known_branch_root_provenance_signatures.setdefault(key, set()).add(
                normalized_signature
            )

            snapshot = None
            try:
                snapshot = self.emulator.branch_snapshot_manager.get_snapshot(int(bb_addr))
            except Exception:
                snapshot = None
            if snapshot is None:
                continue
            entry = PrefixReplaySnapshot(
                prefix_signature=tuple(),
                next_branch_key=key,
                snapshot=snapshot,
                mmio_state=self._interrupt_context_mmio_state(snapshot),
                source_path_signature=normalized_signature,
                branch_depth=int(getattr(snapshot, "depth", 0) or 0),
                origin="dispatch-root",
                evidence_class=capture_evidence,
            )
            existing = self.known_branch_root_snapshots.setdefault(key, {})
            if normalized_signature not in existing:
                existing[normalized_signature] = entry
                self._trim_root_snapshot_variants(key)
        return added

    def _normalize_root_source_signature(
        self,
        root_key: Tuple[int, int],
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        return self._ordered_source_path_signature(
            tuple(
                item
                for item in tuple(source_path_signature or tuple())
                if item[0] != root_key
            )
        )

    def _event_source_signature(
        self,
        event: object,
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
        position_lookup: Optional[Dict[Tuple[int, int], Tuple[int, int]]] = None,
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        target_key = self._branch_event_key(event)
        normalized_signature = self._normalize_root_source_signature(target_key, source_path_signature)
        if not normalized_signature:
            return tuple()

        target_depth = int(getattr(event, "first_depth", getattr(event, "depth", 0)))
        target_order = int(getattr(event, "first_order", getattr(event, "order", 0)))
        target_position = position_lookup.get(target_key) if position_lookup else None
        filtered = []
        for choice_key, choice in normalized_signature:
            if position_lookup and target_position is not None:
                source_position = position_lookup.get(choice_key)
                if source_position is None or source_position < target_position:
                    filtered.append((choice_key, choice))
                continue
            source_event = self.known_main_branch_events.get(choice_key)
            if source_event is None:
                filtered.append((choice_key, choice))
                continue
            source_depth = int(getattr(source_event, "first_depth", getattr(source_event, "depth", 0)))
            source_order = int(getattr(source_event, "first_order", getattr(source_event, "order", 0)))
            if (
                source_depth < target_depth
                or (source_depth == target_depth and source_order < target_order)
            ):
                filtered.append((choice_key, choice))
        return self._ordered_source_path_signature(tuple(filtered))

    def _root_snapshot_entry_rank(
        self,
        signature: Tuple[Tuple[Tuple[int, int], object], ...],
        entry: PrefixReplaySnapshot,
    ) -> Tuple[object, ...]:
        normalized = self._ordered_source_path_signature(tuple(signature or tuple()))
        latest_source_depth = -1
        latest_source_order = -1
        for choice_key, _choice in normalized:
            source_sort = self._branch_choice_sort_key(choice_key)
            latest_source_depth = max(latest_source_depth, int(source_sort[0]))
            latest_source_order = max(latest_source_order, int(source_sort[1]))
        snapshot = getattr(entry, "snapshot", None)
        return (
            0 if not normalized else 1,
            len(normalized),
            -latest_source_depth,
            -latest_source_order,
            int(getattr(entry, "branch_depth", 0) or 0),
            int(getattr(snapshot, "order", 0) or 0),
            int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
        )

    @staticmethod
    def _root_snapshot_variant_key(
        source_path_signature: Tuple[
            Tuple[Tuple[int, int], object], ...
        ],
        source_occurrence_signature: Tuple[
            Tuple[Tuple[int, int], object], ...
        ] = tuple(),
    ) -> Tuple[object, ...]:
        source_path = normalize_naturalization_signature(
            source_path_signature
        )
        occurrence_path = normalize_naturalization_signature(
            source_occurrence_signature
        )
        if not occurrence_path:
            return source_path
        return ("occurrence", source_path, occurrence_path)

    def _trim_root_snapshot_variants(self, key: Tuple[int, int]) -> None:
        limit = self._root_snapshot_variant_limit()
        if limit <= 0:
            return
        entries = self.known_branch_root_snapshots.get(key)
        if not entries or len(entries) <= limit:
            return
        ordered_items = sorted(
            entries.items(),
            key=lambda item: self._root_snapshot_entry_rank(
                self._scope_signature_from_snapshot_entry(item[1]),
                item[1],
            ),
        )
        removed = max(0, len(ordered_items) - limit)
        self.known_branch_root_snapshots[key] = dict(ordered_items[:limit])
        self._record_snapshot_resource_event(
            "branch_root_variant_evictions",
            removed,
        )

    def _root_snapshot_entries(self, root_key: Tuple[int, int]) -> List[PrefixReplaySnapshot]:
        entries = self.known_branch_root_snapshots.get(root_key)
        if not entries:
            same_address_entries: Dict[
                Tuple[object, ...],
                PrefixReplaySnapshot,
            ] = {}
            root_address = int(root_key[0])
            for candidate_key, candidate_entries in self.known_branch_root_snapshots.items():
                if int(candidate_key[0]) != root_address:
                    continue
                for variant_key, entry in candidate_entries.items():
                    same_address_entries.setdefault(tuple(variant_key), entry)
            entries = same_address_entries
        if not entries:
            return []
        return [
            entry
            for _signature, entry in sorted(
                entries.items(),
                key=lambda item: self._root_snapshot_entry_rank(
                    self._scope_signature_from_snapshot_entry(item[1]),
                    item[1],
                ),
            )
        ]

    def _root_snapshot_provenance_signatures(
        self,
        root_key: Tuple[int, int],
    ) -> List[Tuple[Tuple[Tuple[int, int], object], ...]]:
        signatures = []
        seen = set()
        for signature in sorted(
            getattr(self, "known_branch_root_provenance_signatures", {}).get(root_key, set()),
            key=lambda item: (len(item), item),
        ):
            normalized = self._ordered_source_path_signature(tuple(signature or tuple()))
            if normalized in seen:
                continue
            seen.add(normalized)
            signatures.append(normalized)
        for entry in self._root_snapshot_entries(root_key):
            signature = self._ordered_source_path_signature(
                tuple(getattr(entry, "source_path_signature", tuple()) or tuple())
            )
            if signature in seen:
                continue
            seen.add(signature)
            signatures.append(signature)
        limit = self._root_provenance_signature_limit()
        if limit > 0:
            signatures = signatures[:limit]
        return signatures

    def _root_snapshot_entry(
        self,
        root_key: Tuple[int, int],
        source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple(),
    ) -> Optional[PrefixReplaySnapshot]:
        entries = self.known_branch_root_snapshots.get(root_key)
        normalized_signature = self._normalize_root_source_signature(root_key, source_path_signature)
        if entries:
            exact_entries = [
                entry
                for entry in entries.values()
                if self._normalize_root_source_signature(
                    root_key,
                    tuple(
                        getattr(entry, "source_path_signature", tuple())
                        or tuple()
                    ),
                ) == normalized_signature
            ]
            if exact_entries:
                return min(
                    exact_entries,
                    key=lambda entry: self._root_snapshot_entry_rank(
                        self._scope_signature_from_snapshot_entry(entry),
                        entry,
                    ),
                )
        root_address = int(root_key[0])
        for candidate_key, candidate_entries in self.known_branch_root_snapshots.items():
            if int(candidate_key[0]) != root_address:
                continue
            exact_entries = [
                entry
                for entry in candidate_entries.values()
                if self._normalize_root_source_signature(
                    candidate_key,
                    tuple(
                        getattr(entry, "source_path_signature", tuple())
                        or tuple()
                    ),
                ) == normalized_signature
            ]
            if exact_entries:
                return min(
                    exact_entries,
                    key=lambda entry: self._root_snapshot_entry_rank(
                        self._scope_signature_from_snapshot_entry(entry),
                        entry,
                    ),
                )
        ordered_entries = self._root_snapshot_entries(root_key)
        if not ordered_entries:
            return None
        return ordered_entries[0]

    def _validate_root_snapshot_entry(
        self,
        snapshot_entry: Optional[PrefixReplaySnapshot],
        *,
        root_key: Optional[Tuple[int, int]] = None,
    ) -> Tuple[bool, str]:
        if snapshot_entry is None:
            return False, "missing_root_snapshot"

        snapshot = getattr(snapshot_entry, "snapshot", None)
        if snapshot is None:
            return False, "missing_snapshot_object"

        registers = getattr(snapshot, "registers", {}) or {}
        try:
            pc = int(registers.get("pc", 0) or 0) & 0xFFFFFFFF
            sp = int(registers.get("sp", 0) or 0) & 0xFFFFFFFF
            cpsr = int(getattr(snapshot, "cpsr", 0) or 0) & 0xFFFFFFFF
            snapshot_address = int(getattr(snapshot, "address", 0) or 0) & 0xFFFFFFFF
        except Exception:
            return False, "snapshot_register_parse_failed"

        if pc <= 0:
            return False, "snapshot_pc_zero"
        if sp <= 0:
            return False, "snapshot_sp_zero"
        if ((cpsr >> 5) & 1) == 0:
            return False, "snapshot_thumb_bit_clear"

        normalized_pc = pc & ~1
        if normalized_pc not in self.prepared.instruction_lookup:
            return False, "snapshot_pc_not_in_instruction_lookup"
        if snapshot_address <= 0:
            return False, "snapshot_address_zero"

        # Root snapshot replay assumes the saved CPU state is positioned at the
        # entry of the target BB. Mid-instruction / post-instruction PCs can
        # trigger native Unicorn crashes during preserve_cpu_state replays.
        if normalized_pc != snapshot_address:
            return False, "snapshot_pc_mismatch"

        if root_key is not None and int(root_key[0]) != snapshot_address:
            return False, "snapshot_root_key_mismatch"

        return True, "ok"

    def _known_branch_root_snapshot_variant_count(self) -> int:
        return sum(len(entries) for entries in self.known_branch_root_snapshots.values())

    def _snapshot_resource_summary(self) -> Dict[str, object]:
        """Audit retained replay states without changing retention policy."""
        emulator = getattr(self, "emulator", None)
        branch_manager = getattr(emulator, "branch_snapshot_manager", None)
        unique_manager = getattr(emulator, "snapshot_manager", None)

        def unwrap(entry: object) -> Optional[object]:
            if entry is None:
                return None
            if isinstance(entry, dict):
                return entry.get("snapshot")
            nested = getattr(entry, "snapshot", None)
            return nested if nested is not None else entry

        def nested_values(container: object) -> List[object]:
            values: List[object] = []
            for entries in dict(container or {}).values():
                if isinstance(entries, dict):
                    values.extend(entries.values())
                elif isinstance(entries, (list, tuple, set, deque)):
                    values.extend(entries)
                elif entries is not None:
                    values.append(entries)
            return values

        stores: Dict[str, List[object]] = {
            "current": list(
                dict(getattr(branch_manager, "snapshots", {}) or {}).values()
            ),
            "history": nested_values(
                getattr(branch_manager, "snapshot_history", {}) or {}
            ),
            "causal": list(
                getattr(emulator, "causal_input_snapshots", []) or []
            ),
            "root": nested_values(
                getattr(self, "known_branch_root_snapshots", {}) or {}
            ),
            "direct": nested_values(
                getattr(self, "direct_call_snapshots", {}) or {}
            ),
            "stream": nested_values(
                getattr(self, "stream_summary_entry_snapshots", {}) or {}
            ),
            "prefix": list(
                dict(
                    getattr(self, "reservoir_prefix_snapshots", {}) or {}
                ).values()
            ),
            "isr": list(
                getattr(self, "reservoir_interrupt_contexts", []) or []
            ),
            "unique_bb": list(
                getattr(unique_manager, "snapshots", []) or []
            ),
        }
        resolved_stores: Dict[str, List[object]] = {}
        memberships: Dict[int, Set[str]] = defaultdict(set)
        objects_by_id: Dict[int, object] = {}
        references_by_store: Dict[str, Dict[str, int]] = {}
        for store_name, entries in stores.items():
            resolved = [snapshot for snapshot in map(unwrap, entries) if snapshot is not None]
            resolved_stores[store_name] = resolved
            identities = {id(snapshot) for snapshot in resolved}
            references_by_store[store_name] = {
                "references": len(resolved),
                "unique_snapshot_objects": len(identities),
                "duplicate_references_within_store": max(
                    0,
                    len(resolved) - len(identities),
                ),
            }
            for snapshot in resolved:
                identity = id(snapshot)
                objects_by_id[identity] = snapshot
                memberships[identity].add(store_name)

        total_references = sum(
            item["references"] for item in references_by_store.values()
        )
        memory_region_references = 0
        logical_memory_bytes = 0
        paged_region_references = 0
        legacy_blob_region_references = 0
        storage_objects: Dict[int, int] = {}
        paged_storage_objects: Set[int] = set()
        legacy_storage_objects: Set[int] = set()
        external_state_blob_objects = 0
        external_state_dict_objects = 0
        external_state_raw_bytes = 0
        external_state_stored_bytes = 0
        external_state_materialized_blobs = 0
        external_state_disk_backed_blobs = 0
        mmio_state_entries = 0
        input_occurrence_entries = 0
        dirty_page_entries = 0
        register_entries = 0
        region_hash_entries = 0
        alternatives_entries = 0
        for snapshot in objects_by_id.values():
            external_state = getattr(snapshot, "external_model_state", None)
            if isinstance(external_state, SnapshotStateBlob):
                external_state_blob_objects += 1
                external_state_raw_bytes += int(external_state.raw_size)
                external_state_stored_bytes += int(external_state.stored_size)
                if external_state.is_materialized:
                    external_state_materialized_blobs += 1
                if bool(getattr(external_state, "is_disk_backed", False)):
                    external_state_disk_backed_blobs += 1
            elif isinstance(external_state, dict):
                external_state_dict_objects += 1
            try:
                snapshot_mmio_state = getattr(snapshot, "mmio_state", {}) or {}
                mmio_state_entries += len(snapshot_mmio_state)
            except Exception:
                pass
            try:
                input_occurrence_entries += len(
                    getattr(snapshot, "input_occurrence_counts", {}) or {}
                )
            except Exception:
                pass
            try:
                dirty_page_entries += len(getattr(snapshot, "dirty_pages", set()) or set())
            except Exception:
                pass
            try:
                register_entries += len(getattr(snapshot, "registers", {}) or {})
            except Exception:
                pass
            try:
                region_hash_entries += len(getattr(snapshot, "region_hashes", {}) or {})
            except Exception:
                pass
            try:
                alternatives_entries += len(getattr(snapshot, "alternatives", []) or [])
            except Exception:
                pass
            regions = dict(getattr(snapshot, "memory_regions", {}) or {})
            if not regions:
                memory_data = getattr(snapshot, "memory_data", None)
                if memory_data is not None:
                    regions = {
                        (
                            int(getattr(snapshot, "memory_base", 0) or 0),
                            int(getattr(snapshot, "memory_size", len(memory_data)) or len(memory_data)),
                        ): memory_data,
                    }
            for data in regions.values():
                try:
                    logical_size = len(data)
                except Exception:
                    continue
                memory_region_references += 1
                logical_memory_bytes += int(logical_size)
                page_iterator = getattr(data, "iter_page_bytes", None)
                page_objects = getattr(data, "iter_page_objects", None)
                if callable(page_objects):
                    paged_region_references += 1
                    for page in page_objects():
                        identity = id(page)
                        storage_objects.setdefault(
                            identity,
                            int(getattr(page, "size", 0) or 0),
                        )
                        paged_storage_objects.add(identity)
                elif callable(page_iterator):
                    # Compatibility with legacy page-like implementations
                    # that expose bytes but not stable page identities.
                    paged_region_references += 1
                    for page_data in page_iterator():
                        identity = id(page_data)
                        storage_objects.setdefault(identity, len(page_data))
                        paged_storage_objects.add(identity)
                else:
                    legacy_blob_region_references += 1
                    identity = id(data)
                    storage_objects.setdefault(identity, int(logical_size))
                    legacy_storage_objects.add(identity)

        try:
            primary_page_store = dict(
                getattr(emulator, "snapshot_page_store").get_statistics()
            )
        except Exception:
            primary_page_store = {}
        try:
            primary_metadata_store = dict(
                getattr(emulator, "snapshot_metadata_store").get_statistics()
            )
        except Exception:
            primary_metadata_store = {}
        try:
            branch_stats = dict(branch_manager.get_statistics())
        except Exception:
            branch_stats = {}
        try:
            unique_stats = dict(unique_manager.get_statistics())
        except Exception:
            unique_stats = {}

        return {
            "schema": "lsgemu.snapshot_resources.v1",
            "policy": (
                "audit_only; limits retain existing zero semantics and do not "
                "remove branch/event catalogs or coverage"
            ),
            "snapshot_store_scope": "prepared_firmware_shared_across_emulators",
            "references_by_store": references_by_store,
            "total_snapshot_references": int(total_references),
            "unique_snapshot_objects": len(objects_by_id),
            "duplicate_snapshot_references": max(
                0,
                total_references - len(objects_by_id),
            ),
            "objects_referenced_by_multiple_stores": sum(
                1 for store_names in memberships.values() if len(store_names) > 1
            ),
            "limits": {
                "unique_bb_current": int(getattr(unique_manager, "max_snapshots", 0) or 0),
                "lightweight_anchors": int(getattr(unique_manager, "max_lightweight_anchors", 0) or 0),
                "branch_current": int(getattr(branch_manager, "max_current_snapshots", 0) or 0),
                "branch_history_per_address": int(getattr(branch_manager, "max_history_per_address", 0) or 0),
                "branch_history_total": int(getattr(branch_manager, "max_history_total", 0) or 0),
                "branch_occurrence_events": int(getattr(branch_manager, "max_occurrence_events", 0) or 0),
                "causal_input_events": int(getattr(emulator, "max_causal_input_events", 0) or 0),
                "causal_input_snapshots": int(getattr(emulator, "max_causal_input_snapshots", 0) or 0),
                "causal_input_snapshots_per_site": int(getattr(emulator, "max_causal_input_snapshots_per_site", 0) or 0),
                "root_variants_per_occurrence": int(self._root_snapshot_variant_limit()),
                "direct_variants_per_address": int(self._direct_call_snapshot_variant_limit()),
                "stream_variants_per_address": int(self._stream_summary_snapshot_variant_limit()),
                "reservoir_prefix": int(self._prefix_snapshot_limit()),
                "reservoir_isr_contexts": int(self._reservoir_isr_context_limit()),
            },
            "zero_limit_semantics": {
                "unbounded": [
                    "branch_current",
                    "root_variants_per_occurrence",
                    "direct_variants_per_address",
                ],
                "disabled": [
                    "branch_history_per_address",
                    "branch_history_total",
                    "causal_input_snapshots",
                    "reservoir_prefix",
                    "reservoir_isr_contexts",
                ],
            },
            "retained_memory": {
                "memory_region_references": int(memory_region_references),
                "logical_memory_bytes": int(logical_memory_bytes),
                "paged_region_references": int(paged_region_references),
                "legacy_blob_region_references": int(legacy_blob_region_references),
                "unique_storage_objects": len(storage_objects),
                "unique_storage_bytes": sum(storage_objects.values()),
                "interned_page_storage_objects": len(paged_storage_objects),
                "legacy_blob_storage_objects": len(legacy_storage_objects),
                "external_state": {
                    "blob_objects": int(external_state_blob_objects),
                    "fallback_dict_objects": int(external_state_dict_objects),
                    "raw_bytes": int(external_state_raw_bytes),
                    "stored_bytes": int(external_state_stored_bytes),
                    "disk_backed_blob_objects": int(
                        external_state_disk_backed_blobs
                    ),
                    "materialized_blob_objects": int(
                        external_state_materialized_blobs
                    ),
                },
                "metadata_entries": {
                    "mmio_state": int(mmio_state_entries),
                    "input_occurrence_counts": int(input_occurrence_entries),
                    "dirty_pages": int(dirty_page_entries),
                    "registers": int(register_entries),
                    "region_hashes": int(region_hash_entries),
                    "alternatives": int(alternatives_entries),
                },
            },
            "primary_page_store": primary_page_store,
            "primary_metadata_store": primary_metadata_store,
            "primary_blob_store": dict(
                getattr(emulator, "snapshot_blob_store", None).get_statistics()
                if getattr(emulator, "snapshot_blob_store", None) is not None
                else {}
            ),
            "retention_events": {
                "runner": dict(
                    getattr(self, "snapshot_resource_stats", Counter()) or {}
                ),
                "branch": dict(branch_stats.get("capture", {}) or {}),
                "branch_occurrence_events_truncated": int(
                    branch_stats.get("occurrence_events_truncated", 0) or 0
                ),
                "causal": dict(
                    getattr(emulator, "causal_input_retention_stats", Counter())
                    or {}
                ),
                "unique_bb": dict(unique_stats.get("capture", {}) or {}),
            },
            "lightweight_anchors": int(
                unique_stats.get("lightweight_anchors", 0) or 0
            ),
        }

    def _snapshot_provenance_summary(self) -> Dict[str, object]:
        stores = {
            "branch_root": [
                entry
                for entries in getattr(self, "known_branch_root_snapshots", {}).values()
                for entry in entries.values()
            ],
            "direct_call": [
                entry
                for entries in getattr(self, "direct_call_snapshots", {}).values()
                for entry in entries.values()
            ],
            "stream_summary": [
                entry
                for entries in getattr(self, "stream_summary_entry_snapshots", {}).values()
                for entry in entries.values()
            ],
            "reservoir_prefix": list(
                getattr(self, "reservoir_prefix_snapshots", {}).values()
            ),
            "interrupt_context": list(
                getattr(self, "reservoir_interrupt_contexts", [])
            ),
        }
        effective_counts: Counter[str] = Counter()
        explicit_counts: Counter[str] = Counter()
        by_store: Dict[str, Dict[str, object]] = {}
        for store_name, entries in stores.items():
            store_effective: Counter[str] = Counter()
            store_explicit: Counter[str] = Counter()
            lossless_occurrence_contexts = 0
            for entry in entries:
                if isinstance(entry, dict):
                    explicit = normalize_evidence_class(entry.get("evidence_class"))
                    effective = self._capture_evidence_class(
                        tuple(entry.get("source_path_signature", tuple()) or tuple()),
                        explicit,
                    )
                else:
                    explicit = normalize_evidence_class(
                        getattr(entry, "evidence_class", EVIDENCE_UNKNOWN)
                    )
                    effective = (
                        EVIDENCE_E2
                        if store_name == "interrupt_context" and explicit == EVIDENCE_UNKNOWN
                        else self._snapshot_entry_evidence_class(entry)
                    )
                explicit_counts[explicit] += 1
                effective_counts[effective] += 1
                store_explicit[explicit] += 1
                store_effective[effective] += 1
                lossless_occurrence_contexts += int(bool(
                    self._interrupt_context_occurrence_signature(entry)
                ))
            by_store[store_name] = {
                "entries": len(entries),
                "lossless_occurrence_contexts": lossless_occurrence_contexts,
                "effective_evidence_counts": dict(store_effective),
                "explicit_evidence_counts": dict(store_explicit),
            }
        return {
            "entries": sum(len(entries) for entries in stores.values()),
            "effective_evidence_counts": dict(effective_counts),
            "explicit_evidence_counts": dict(explicit_counts),
            "legacy_or_unknown_entries": int(explicit_counts.get(EVIDENCE_UNKNOWN, 0)),
            "by_store": by_store,
        }

    def _invalidate_dynamic_successor_caches(self) -> None:
        with self._runner_state_lock():
            self.dynamic_successor_version += 1
            self.effective_successor_cache = None
            self.static_reachable_cache_by_successor_version.clear()
            self.static_reachable_cache_node_count = 0
            self.static_reachable_cache_bytes = 0

    def _effective_successor_map(self) -> Dict[int, Set[int]]:
        with self._runner_state_lock():
            cached = self.effective_successor_cache
            if cached is not None and int(cached[0]) == int(self.dynamic_successor_version):
                return cached[1]
            merged = {
                int(bb_addr): set(successors)
                for bb_addr, successors in self.prepared.static_successors.items()
            }
            for bb_addr, successors in list(self.dynamic_successors.items()):
                merged.setdefault(int(bb_addr), set()).update(
                    int(successor)
                    for successor in successors
                    if successor in self.prepared.static_bb_set
                )
            self.effective_successor_cache = (int(self.dynamic_successor_version), merged)
            return merged

    def _record_dynamic_successors(self, events: Iterable[object]) -> int:
        added = 0
        changed = False
        with self._runner_state_lock():
            for event in events or []:
                try:
                    source_bb = self.prepared.resolve_basic_block(int(getattr(event, "address", 0)))
                except Exception:
                    source_bb = None
                if source_bb is None:
                    continue

                condition = str(getattr(event, "condition", ""))
                raw_targets: List[int] = []
                if condition in SWITCH_DISPATCH_MNEMONICS:
                    raw_targets.extend(
                        int(target or 0)
                        for target in getattr(event, "alternatives", []) or []
                        if int(target or 0) != 0
                    )
                else:
                    target = int(getattr(event, "target", 0) or 0)
                    fallthrough = int(getattr(event, "fallthrough", 0) or 0)
                    if target:
                        raw_targets.append(target)
                    if fallthrough:
                        raw_targets.append(fallthrough)

                if not raw_targets:
                    continue

                target_set = self.dynamic_successors.setdefault(int(source_bb), set())
                static_targets = self.prepared.static_successors.get(int(source_bb), set())
                for raw_target in raw_targets:
                    successor_bb = self.prepared.resolve_basic_block(raw_target)
                    if successor_bb is None or successor_bb not in self.prepared.static_bb_set:
                        continue
                    if successor_bb in target_set:
                        continue
                    target_set.add(int(successor_bb))
                    changed = True
                    if successor_bb not in static_targets:
                        added += 1
            if changed:
                self._invalidate_dynamic_successor_caches()
        return added

    def _record_runtime_successor_edges(
        self,
        successor_edges: Iterable[Tuple[int, int]],
    ) -> int:
        """Merge exact observed BB edges without retaining their full trace."""
        added = 0
        changed = False
        with self._runner_state_lock():
            for raw_source, raw_target in successor_edges or []:
                try:
                    source_bb = int(raw_source)
                    target_bb = int(raw_target)
                except (TypeError, ValueError):
                    continue
                if (
                    source_bb == target_bb
                    or source_bb not in self.prepared.static_bb_set
                    or target_bb not in self.prepared.static_bb_set
                ):
                    continue
                target_set = self.dynamic_successors.setdefault(source_bb, set())
                static_targets = self.prepared.static_successors.get(source_bb, set())
                if target_bb in target_set:
                    continue
                target_set.add(target_bb)
                changed = True
                if target_bb not in static_targets:
                    added += 1
            if changed:
                self._invalidate_dynamic_successor_caches()
        return added

    def _record_runtime_successors(
        self,
        executed_bbs: Iterable[int] | ExecutionTrace,
    ) -> int:
        """
        Learn concrete successor edges directly from the executed BB sequence.

        Branch events only model conditional branches and TBB/TBH dispatches.
        Real execution also reveals dynamic BLX/BX/function-pointer successors,
        which should influence frontier selection and reachability scoring.
        """
        if isinstance(executed_bbs, ExecutionTrace):
            return self._record_runtime_successor_edges(
                executed_bbs.successor_edges
            )
        added = 0
        changed = False
        previous_bb: Optional[int] = None
        with self._runner_state_lock():
            for raw_bb in executed_bbs or []:
                try:
                    current_bb = int(raw_bb)
                except (TypeError, ValueError):
                    previous_bb = None
                    continue
                if current_bb not in self.prepared.static_bb_set:
                    previous_bb = None
                    continue
                if previous_bb is None or previous_bb == current_bb:
                    previous_bb = current_bb
                    continue
                target_set = self.dynamic_successors.setdefault(previous_bb, set())
                static_targets = self.prepared.static_successors.get(previous_bb, set())
                if current_bb not in target_set:
                    target_set.add(current_bb)
                    changed = True
                    if current_bb not in static_targets:
                        added += 1
                previous_bb = current_bb
            if changed:
                self._invalidate_dynamic_successor_caches()
        return added

    def _record_emulator_runtime_successors(
        self,
        emulator: IntelligentEmulator,
    ) -> int:
        """Prefer the emulator's exact edge ledger, with legacy fallback."""
        if hasattr(emulator, "runtime_successor_edges"):
            return self._record_runtime_successor_edges(
                getattr(emulator, "runtime_successor_edges", set()) or set()
            )
        return self._record_runtime_successors(
            getattr(emulator, "bb_history", []) or []
        )

    def _serialize_branch_event(self, event) -> Dict[str, object]:
        return {
            "bb": f"0x{event.address:08x}",
            "branch_pc": f"0x{event.branch_pc:08x}",
            "condition": event.condition,
            "target": f"0x{event.target:08x}" if event.target else None,
            "fallthrough": f"0x{event.fallthrough:08x}" if event.fallthrough else None,
            "original_taken": event.original_taken,
            "occurrence_index": event.occurrence_index,
            "order": event.order,
            "depth": event.depth,
            "first_occurrence_index": getattr(event, "first_occurrence_index", event.occurrence_index),
            "first_order": getattr(event, "first_order", event.order),
            "first_depth": getattr(event, "first_depth", event.depth),
            "alternatives": [f"0x{target:08x}" if target else None for target in getattr(event, "alternatives", [])],
            "original_index": getattr(event, "original_index", None),
            "original_direction_known": bool(
                getattr(event, "original_direction_known", True)
            ),
            "direction_provenance": str(
                getattr(event, "direction_provenance", "unicorn_execution")
                or "unicorn_execution"
            ),
            "synthetic": bool(getattr(event, "synthetic", False)),
            "context_signature": dict(
                getattr(event, "context_signature", {}) or {}
            ),
        }

    # -- P1-F (cycle3 k.5 C4): discovery-point oracle events ----------------
    RESERVOIR_DISCOVERY_EVENT_LIMIT: ClassVar[int] = 4096

    def _record_reservoir_discovery_event(
        self,
        child: object,
        replay_snapshot_by_addr: Optional[Mapping[int, object]],
    ) -> None:
        """Append the oracle facts of a discovered branch event (bounded).

        记录字段与 join 主键同域：``bb``/``local_occ``（本重放域出现数，
        即 ``child.occurrence_index``——**不是** catalog 的全局 occ）、
        ``original_taken``/``direction_provenance``（方向事实与来源）、
        ``identity``（根快照的 ``(era,bb,c2,c3)``，legacy 快照无此键则
        None，走 K1 回退）。超限计数不保留（防长跑膨胀）。
        """
        if len(self.reservoir_discovery_events) >= self.RESERVOIR_DISCOVERY_EVENT_LIMIT:
            self.reservoir_discovery_events_truncated += 1
            return
        bb = int(getattr(child, "address", 0) or 0) & 0xFFFFFFFF
        identity = None
        snapshot = (replay_snapshot_by_addr or {}).get(bb)
        state = getattr(snapshot, "external_model_state", None)
        if isinstance(state, Mapping):
            raw_identity = state.get("snapshot_identity")
            if isinstance(raw_identity, (tuple, list)) and len(raw_identity) == 4:
                try:
                    identity = [int(part) for part in raw_identity]
                except (TypeError, ValueError):
                    identity = None
        self.reservoir_discovery_events.append({
            "bb": f"0x{bb:08x}",
            "local_occ": int(getattr(child, "occurrence_index", 1) or 1),
            "original_taken": bool(getattr(child, "original_taken", False)),
            "direction_provenance": str(
                getattr(child, "direction_provenance", "") or ""
            ),
            "identity": identity,
        })

    def save_branch_catalog(self, output_path: str | Path) -> Dict[str, object]:
        """Persist static and dynamic branch locations for auditability."""
        conditional_names = {
            "BEQ", "BNE", "BCS", "BCC", "BHS", "BLO", "BMI", "BPL",
            "BVS", "BVC", "BHI", "BLS", "BGE", "BLT", "BGT", "BLE",
            "CBZ", "CBNZ", "TBB", "TBH",
        } | SWITCH_DISPATCH_MNEMONICS
        static_branches = []
        for bb_addr, insn in sorted(self.prepared.branch_instruction_by_bb.items()):
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if mnemonic not in conditional_names:
                continue
            static_branches.append({
                "bb": f"0x{bb_addr:08x}",
                "branch_pc": f"0x{int(insn.get('address', bb_addr)):08x}",
                "mnemonic": mnemonic,
                "operands": insn.get("operands", ""),
            })

        main_events = self.emulator.branch_snapshot_manager.get_ordered_events()
        root_snapshot_variants_by_branch = []
        for key, entries in sorted(
            self.known_branch_root_snapshots.items(),
            key=lambda item: (len(item[1]), item[0]),
            reverse=True,
        )[:256]:
            event = self.known_main_branch_events.get(key)
            root_snapshot_variants_by_branch.append({
                "bb": f"0x{int(key[0]):08x}",
                "occurrence": int(key[1]),
                "condition": str(getattr(event, "condition", "")) if event is not None else "",
                "variants": len(entries),
                "sample_signature_lengths": [
                    len(tuple(signature or tuple()))
                    for signature in list(entries.keys())[:8]
                ],
            })
        payload = {
            "firmware": str(self.prepared.firmware_path),
            "static_conditional_branch_points": len(static_branches),
            "main_path_branch_events": len(main_events),
            "main_path_branch_points": len({event.address for event in main_events}),
            "reservoir_discovered_branch_events": len(self.reservoir_discovered_branch_keys),
            # P1-F（k.5 C4）：发现点 oracle 事件列表（有界）+ 截断计数，
            # 与上行计数键并列。
            "reservoir_discovery_events": list(self.reservoir_discovery_events),
            "reservoir_discovery_events_truncated": int(
                self.reservoir_discovery_events_truncated
            ),
            "reservoir_new_branch_points": len(self.reservoir_new_branch_points),
            "known_branch_root_snapshots": len(self.known_branch_root_snapshots),
            "known_branch_root_snapshot_variants": self._known_branch_root_snapshot_variant_count(),
            "static_branches": static_branches,
            "main_path_events": [self._serialize_branch_event(event) for event in main_events],
            "reservoir_new_branch_point_list": [f"0x{addr:08x}" for addr in sorted(self.reservoir_new_branch_points)],
            "root_snapshot_variants_by_branch": root_snapshot_variants_by_branch,
        }
        output_path = Path(output_path)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        atomic_json_dump(payload, output_path, indent=2)
        return payload

    def _extended_static_root_bbs(
        self,
        entry_bb: int,
        vector_bbs: Set[int],
    ) -> Tuple[Set[int], Dict[str, int], Dict[str, List[Dict[str, object]]]]:
        """
        Build a broader diagnostic root set for static reachability reporting.

        These roots do not affect executed coverage. They only explain whether a
        valid BB denominator contains task/callback/indirect-entry code that is
        outside the reset-entry + vector static slice.
        """
        all_bbs = self.prepared.static_bb_set
        roots: Set[int] = set()
        category_roots: Dict[str, Set[int]] = defaultdict(set)
        examples: Dict[str, List[Dict[str, object]]] = defaultdict(list)

        def resolve_root(raw_addr: object) -> Optional[int]:
            try:
                addr = int(raw_addr) & ~1
            except (TypeError, ValueError):
                return None
            resolved = self.prepared.resolve_basic_block(addr)
            if resolved is None and addr in all_bbs:
                resolved = addr
            if resolved is None or resolved not in all_bbs:
                return None
            return int(resolved)

        def add_root(raw_addr: object, category: str, source: str, detail: object = None) -> None:
            bb_addr = resolve_root(raw_addr)
            if bb_addr is None:
                return
            roots.add(bb_addr)
            category_roots[category].add(bb_addr)
            if len(examples[category]) < 8:
                item: Dict[str, object] = {
                    "bb": f"0x{bb_addr:08x}",
                    "source": source,
                }
                if detail is not None:
                    item["detail"] = detail
                examples[category].append(item)

        add_root(entry_bb, "reset_entry", "entry_point")
        for bb_addr in sorted(vector_bbs):
            add_root(bb_addr, "vector_handler", "vector_table")

        # Generic semantic roots cover RTOS task entries, protocol callbacks and
        # input handlers without hardcoding a specific firmware or address.
        for name, addr in sorted(self._function_starts_by_name().items(), key=lambda item: (item[1], item[0])):
            categories = (
                self._semantic_entry_categories_for_name(name)
                if self.semantic_obligation_enabled
                else set()
            )
            selected = categories & EXTENDED_STATIC_ROOT_CATEGORIES
            if not selected:
                continue
            normalized = _normalize_name(name)
            if "error_or_fault_path" in categories and "interrupt_or_vector_handler" not in categories:
                continue
            if (
                "interrupt_or_vector_handler" in selected
                and "error_or_fault_path" in categories
                and resolve_root(addr) not in vector_bbs
                and any(token in normalized for token in ("default", "fault", "panic", "assert", "abort"))
            ):
                continue
            if categories & {"libc_or_runtime_path", "libgcc_runtime_path", "io_output_path"}:
                selected = selected - {"startup_teardown_path"}
                if not selected:
                    continue
            for category in sorted(selected):
                add_root(addr, f"semantic_{category}", "symbol", name)

        # Dynamically observed control-flow roots are evidence-backed: Unicorn
        # has already seen these BBs or their successor edge during execution.
        with self._runner_state_lock():
            dynamic_successors = {
                int(source): set(successors)
                for source, successors in list(self.dynamic_successors.items())
            }
        for source_bb, successors in sorted(dynamic_successors.items()):
            add_root(source_bb, "dynamic_successor_source", "dynamic_successors")
            for successor in sorted(successors):
                add_root(
                    successor,
                    "dynamic_successor_target",
                    "dynamic_successors",
                    f"0x{int(source_bb):08x}->0x{int(successor):08x}",
                )

        for root_key in sorted(self.known_branch_root_snapshots):
            add_root(root_key[0], "branch_root_snapshot", "known_branch_root_snapshots", f"occurrence={int(root_key[1])}")
        for call_bb in sorted(self.direct_call_snapshots):
            add_root(call_bb, "direct_call_snapshot", "direct_call_snapshots")
        for entry in getattr(self, "reservoir_prefix_snapshots", {}).values():
            snapshot = getattr(entry, "snapshot", None)
            snapshot_addr = int(getattr(snapshot, "address", 0) or 0)
            if snapshot_addr:
                add_root(snapshot_addr, "reservoir_prefix_snapshot", "reservoir_prefix_snapshots")
                continue
            next_branch_key = getattr(entry, "next_branch_key", None)
            if isinstance(next_branch_key, tuple) and next_branch_key:
                add_root(next_branch_key[0], "reservoir_prefix_snapshot", "reservoir_prefix_snapshots")

        return (
            roots,
            {category: len(root_set) for category, root_set in sorted(category_roots.items())},
            {category: values for category, values in sorted(examples.items())},
        )

    def _static_reachability_sets(self) -> Dict[str, object]:
        """Compute static CFG reachability from reset entry and vector ISRs."""
        successor_map = self._effective_successor_map()
        all_bbs = set(self.prepared.static_bb_set)

        def reachable(starts: Iterable[int]) -> Set[int]:
            queue = deque([start for start in starts if start in all_bbs])
            seen = set(queue)
            while queue:
                current = queue.popleft()
                for succ in sorted(successor_map.get(current, set())):
                    if succ in all_bbs and succ not in seen:
                        seen.add(succ)
                        queue.append(succ)
            return seen

        entry_bb = self.prepared.resolve_basic_block(self.prepared.entry_point & ~1) or (self.prepared.entry_point & ~1)
        entry_reachable = reachable([entry_bb])

        vector_bbs: Set[int] = set()
        try:
            vtor = self._vector_table_base()
            for index in range(2, 16 + 240):
                handler = self._read_firmware_word(vtor + index * 4)
                if handler is None:
                    continue
                handler &= ~1
                if handler and self._is_code_address(handler):
                    vector_bbs.add(self.prepared.resolve_basic_block(handler) or handler)
        except Exception:
            vector_bbs = set()

        vector_reachable = reachable(vector_bbs)
        combined_reachable = reachable([entry_bb] + list(vector_bbs))
        extended_roots, extended_root_categories, extended_root_examples = self._extended_static_root_bbs(
            entry_bb,
            vector_bbs,
        )
        extended_reachable = reachable(extended_roots)
        return {
            "all_bbs": all_bbs,
            "entry_reachable": entry_reachable,
            "vector_bbs": vector_bbs,
            "vector_table_base": self._vector_table_base(),
            "vector_reachable": vector_reachable,
            "combined_reachable": combined_reachable,
            "extended_roots": extended_roots,
            "extended_root_categories": extended_root_categories,
            "extended_root_examples": extended_root_examples,
            "extended_reachable": extended_reachable,
        }

    def static_reachability_summary(
        self,
        coverage: Optional[Iterable[int]] = None,
    ) -> Dict[str, object]:
        """Compute static CFG reachability from reset entry and vector ISRs."""
        reachability = self._static_reachability_sets()
        all_bbs = reachability["all_bbs"]
        entry_reachable = reachability["entry_reachable"]
        vector_bbs = reachability["vector_bbs"]
        vector_reachable = reachability["vector_reachable"]
        combined_reachable = reachability["combined_reachable"]
        extended_roots = reachability.get("extended_roots", set())
        extended_reachable = reachability.get("extended_reachable", set())
        extended_root_categories = reachability.get("extended_root_categories", {})
        extended_root_examples = reachability.get("extended_root_examples", {})
        valid_bbs = set(self.prepared.valid_bb_set)
        with self._runner_state_lock():
            covered = set(self.global_coverage if coverage is None else coverage)
        valid_entry_reachable = entry_reachable & valid_bbs if valid_bbs else set()
        valid_combined_reachable = combined_reachable & valid_bbs if valid_bbs else set()
        valid_extended_reachable = extended_reachable & valid_bbs if valid_bbs else set()
        valid_covered = covered & valid_bbs if valid_bbs else set()
        total = len(all_bbs)
        extended_roots_available = bool(extended_roots)
        return {
            "total_static_bbs": total,
            "vector_table_base": f"0x{int(reachability.get('vector_table_base', 0)) & 0xFFFFFFFF:08x}",
            "entry_static_reachable_bbs": len(entry_reachable),
            "vector_entry_points": len(vector_bbs),
            "vector_static_reachable_bbs": len(vector_reachable),
            "entry_plus_vector_static_reachable_bbs": len(combined_reachable),
            "static_unreachable_from_entry_or_vectors": len(all_bbs - combined_reachable),
            "extended_static_roots_available": extended_roots_available,
            "extended_static_root_bbs": len(extended_roots),
            "extended_static_root_categories": dict(extended_root_categories),
            "extended_static_root_examples": dict(extended_root_examples),
            "extended_static_reachable_bbs": len(extended_reachable),
            "static_unreachable_from_extended_roots": len(all_bbs - extended_reachable),
            "entry_static_reachable_covered_bbs": len(covered & entry_reachable),
            "entry_static_reachable_uncovered_bbs": len(entry_reachable - covered),
            "entry_plus_vector_static_reachable_covered_bbs": len(covered & combined_reachable),
            "entry_plus_vector_static_reachable_uncovered_bbs": len(combined_reachable - covered),
            "extended_static_reachable_covered_bbs": len(covered & extended_reachable),
            "extended_static_reachable_uncovered_bbs": len(extended_reachable - covered),
            "static_unreachable_dynamic_covered_bbs": len(covered - combined_reachable),
            "static_unreachable_dynamic_uncovered_bbs": len((all_bbs - combined_reachable) - covered),
            "entry_static_reachable_coverage_rate": (
                len(covered & entry_reachable) / len(entry_reachable) * 100
                if entry_reachable else 0.0
            ),
            "entry_plus_vector_reachable_coverage_rate": (
                len(covered & combined_reachable) / len(combined_reachable) * 100
                if combined_reachable else 0.0
            ),
            "extended_static_reachable_coverage_rate": (
                len(covered & extended_reachable) / len(extended_reachable) * 100
                if extended_reachable else 0.0
            ),
            "valid_total_bbs": len(valid_bbs),
            "valid_entry_static_reachable_bbs": len(valid_entry_reachable),
            "valid_entry_static_reachable_covered_bbs": len(valid_covered & valid_entry_reachable),
            "valid_entry_static_reachable_uncovered_bbs": len(valid_entry_reachable - valid_covered),
            "valid_entry_static_reachable_coverage_rate": (
                len(valid_covered & valid_entry_reachable) / len(valid_entry_reachable) * 100
                if valid_entry_reachable else 0.0
            ),
            "valid_entry_plus_vector_static_reachable_bbs": len(valid_combined_reachable),
            "valid_entry_plus_vector_static_reachable_covered_bbs": len(valid_covered & valid_combined_reachable),
            "valid_entry_plus_vector_static_reachable_uncovered_bbs": len(valid_combined_reachable - valid_covered),
            "valid_entry_plus_vector_reachable_coverage_rate": (
                len(valid_covered & valid_combined_reachable) / len(valid_combined_reachable) * 100
                if valid_combined_reachable else 0.0
            ),
            "valid_static_unreachable_from_entry_or_vectors": len(valid_bbs - valid_combined_reachable),
            "valid_extended_static_reachable_bbs": len(valid_extended_reachable),
            "valid_extended_static_reachable_covered_bbs": len(valid_covered & valid_extended_reachable),
            "valid_extended_static_reachable_uncovered_bbs": len(valid_extended_reachable - valid_covered),
            "valid_extended_static_reachable_coverage_rate": (
                len(valid_covered & valid_extended_reachable) / len(valid_extended_reachable) * 100
                if valid_extended_reachable else 0.0
            ),
            "valid_static_unreachable_from_extended_roots": len(valid_bbs - valid_extended_reachable),
        }

    def stream_summary_reachability_diagnostics(self, max_samples: int = 16) -> Dict[str, object]:
        """Explain whether modeled stream/read summaries are reachable from real entry-derived paths."""
        successor_map = self._effective_successor_map()
        all_bbs = set(self.prepared.static_bb_set)
        valid_bbs = set(self.prepared.valid_bb_set)
        covered = self.validate_coverage(self.global_coverage)
        reachability = self._static_reachability_sets()
        entry_vector_reachable = set(reachability.get("combined_reachable", set()) or set())
        extended_reachable = set(reachability.get("extended_reachable", set()) or set())
        predecessors: Dict[int, Set[int]] = {bb: set() for bb in all_bbs}
        for pred, successors in successor_map.items():
            for successor in successors:
                if int(successor) in all_bbs:
                    predecessors.setdefault(int(successor), set()).add(int(pred))

        def nearest_covered_predecessor(target: int, max_depth: int = 24) -> Optional[Dict[str, object]]:
            queue = deque([(int(target), 0)])
            seen = {int(target)}
            while queue:
                current, depth = queue.popleft()
                if current in covered:
                    return {
                        "bb": f"0x{int(current) & 0xFFFFFFFF:08x}",
                        "depth": int(depth),
                        "symbol": self._function_name_for_addr(int(current)),
                    }
                if depth >= max_depth:
                    continue
                for pred in sorted(predecessors.get(current, set())):
                    if pred in seen:
                        continue
                    seen.add(pred)
                    queue.append((pred, depth + 1))
            return None

        summary_records: List[Dict[str, object]] = []
        counters: Counter[str] = Counter()
        for address, symbol in sorted(getattr(self.prepared, "symbols_by_addr", {}).items()):
            summary = IntelligentEmulator._stream_input_summary_for_symbol(str(symbol))
            if summary is None:
                continue
            bb = self.prepared.resolve_basic_block(int(address) & ~1)
            if bb is None:
                continue
            bb = int(bb)
            pred_set = set(predecessors.get(bb, set()))
            record = {
                "symbol": str(symbol),
                "address": f"0x{int(address) & 0xFFFFFFFF:08x}",
                "bb": f"0x{bb & 0xFFFFFFFF:08x}",
                "summary_kind": str(summary.get("kind", "")),
                "arg_style": str(summary.get("arg_style", "")),
                "valid_bb": (bb in valid_bbs) if valid_bbs else None,
                "covered": bb in covered,
                "entry_vector_reachable": bb in entry_vector_reachable,
                "extended_reachable": bb in extended_reachable,
                "static_predecessors": len(pred_set),
                "covered_static_predecessors": len(pred_set & covered),
                "nearest_covered_predecessor": nearest_covered_predecessor(bb),
                "predecessor_sample": [
                    {
                        "bb": f"0x{int(pred) & 0xFFFFFFFF:08x}",
                        "symbol": self._function_name_for_addr(int(pred)),
                        "covered": pred in covered,
                        "entry_vector_reachable": pred in entry_vector_reachable,
                    }
                    for pred in sorted(pred_set)[:8]
                ],
            }
            if not record["covered"]:
                counters["uncovered"] += 1
            if not record["entry_vector_reachable"]:
                counters["not_entry_vector_reachable"] += 1
            if not record["extended_reachable"]:
                counters["not_extended_reachable"] += 1
            if not pred_set:
                counters["no_static_predecessor"] += 1
            if pred_set and not (pred_set & covered):
                counters["no_covered_static_predecessor"] += 1
            if record["nearest_covered_predecessor"] is None:
                counters["no_covered_reverse_reachable_predecessor"] += 1
            summary_records.append(record)

        return {
            "stream_summary_bbs": len(summary_records),
            "uncovered_stream_summary_bbs": int(counters.get("uncovered", 0)),
            "not_entry_vector_reachable": int(counters.get("not_entry_vector_reachable", 0)),
            "not_extended_reachable": int(counters.get("not_extended_reachable", 0)),
            "no_static_predecessor": int(counters.get("no_static_predecessor", 0)),
            "no_covered_static_predecessor": int(counters.get("no_covered_static_predecessor", 0)),
            "no_covered_reverse_reachable_predecessor": int(counters.get("no_covered_reverse_reachable_predecessor", 0)),
            "samples": summary_records[: max(0, int(max_samples))],
        }

    def uncovered_coverage_summary(
        self,
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        max_frontier_predecessors: int = 32,
    ) -> Dict[str, object]:
        """
        Categorize uncovered BBs to explain why coverage is still missing.

        This is intentionally coverage-centric rather than path-centric:
        it answers whether a missing BB is already on the immediate frontier,
        only reachable through still-uncovered predecessors, vector-only, or
        currently absent even from the entry+vector static CFG slice.
        """
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)
        uncovered = scope - covered

        reachability = self._static_reachability_sets()
        entry_reachable = reachability["entry_reachable"] & scope
        vector_reachable = reachability["vector_reachable"] & scope
        combined_reachable = reachability["combined_reachable"] & scope

        effective_successors = self._effective_successor_map()
        predecessors: Dict[int, Set[int]] = {bb: set() for bb in self.prepared.static_bb_set}
        for bb_addr, successors in effective_successors.items():
            for successor in successors:
                predecessors.setdefault(successor, set()).add(bb_addr)
        reachable_cache: Dict[int, Set[int]] = {}

        def uncovered_downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        frontier_targets: List[int] = []
        frontier_target_seen: Set[int] = set()
        frontier_predecessors = []
        frontier_category_counts: Counter[str] = Counter()
        uncovered_function_category_counts: Counter[str] = Counter()
        uncovered_function_examples: Dict[str, List[Dict[str, object]]] = defaultdict(list)
        uncovered_with_covered_predecessor = 0
        uncovered_without_covered_predecessor = 0
        uncovered_reachable_but_predecessor_uncovered = 0
        uncovered_without_static_predecessor = 0

        for bb in sorted(uncovered):
            function_name = self._function_name_for_addr(int(bb))
            # Post-hoc report label only. Active scheduling categories go
            # through _semantic_categories_for_bb(), which the ablation empties.
            categories = self._semantic_entry_categories_for_name(function_name)
            if not categories:
                categories = {"uncategorized_static_code"}
            for category in categories:
                uncovered_function_category_counts[category] += 1
                if len(uncovered_function_examples[category]) < 8:
                    uncovered_function_examples[category].append({
                        "bb": f"0x{int(bb):08x}",
                        "function": function_name or None,
                    })
            preds = predecessors.get(bb, set())
            covered_preds = sorted(pred for pred in preds if pred in covered)
            if covered_preds:
                uncovered_with_covered_predecessor += 1
            else:
                uncovered_without_covered_predecessor += 1
                if any(pred in combined_reachable for pred in preds):
                    uncovered_reachable_but_predecessor_uncovered += 1
                else:
                    uncovered_without_static_predecessor += 1

        for pred_bb, successors in sorted(effective_successors.items()):
            if pred_bb not in covered:
                continue
            uncovered_successors = sorted(bb for bb in successors if bb in uncovered)
            if not uncovered_successors:
                continue
            successor_potential = {
                int(bb): uncovered_downstream_potential(int(bb))
                for bb in uncovered_successors
            }
            successor_semantic_priority_by_bb = {
                int(bb): self._semantic_priority_for_bb(int(bb))
                for bb in uncovered_successors
            }
            uncovered_successors.sort(
                key=lambda bb: (
                    successor_semantic_priority_by_bb.get(int(bb), 0),
                    successor_potential.get(int(bb), 0),
                    -int(bb),
                ),
                reverse=True,
            )
            insn = self.prepared.branch_instruction_by_bb.get(pred_bb, {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            is_branch_frontier = _is_replayable_frontier_mnemonic(mnemonic)
            is_switch_frontier = _is_switch_frontier_mnemonic(mnemonic)
            is_call_frontier = _is_call_frontier_mnemonic(mnemonic) or _is_direct_call_mnemonic(mnemonic)
            if is_switch_frontier:
                frontier_category = "switch_case_frontier"
            elif _is_call_frontier_mnemonic(mnemonic):
                frontier_category = "indirect_call_or_return_frontier"
            elif _is_direct_call_mnemonic(mnemonic):
                frontier_category = "direct_call_continuation_frontier"
            elif is_branch_frontier:
                frontier_category = "conditional_branch_frontier"
            else:
                frontier_category = "non_replayable_successor_frontier"
            frontier_category_counts[frontier_category] += len(uncovered_successors)
            pred_function = self._function_name_for_addr(int(pred_bb))
            successor_categories: Counter[str] = Counter()
            for bb in uncovered_successors:
                categories = self._semantic_categories_for_bb(int(bb))
                for category in categories:
                    successor_categories[category] += 1
            successor_semantic_priority = self._semantic_category_priority(successor_categories.keys())
            for bb in uncovered_successors:
                if is_branch_frontier and bb not in frontier_target_seen:
                    frontier_target_seen.add(bb)
                    frontier_targets.append(bb)
            known_event_keys = [
                key for key in self.known_main_branch_events
                if int(key[0]) == int(pred_bb)
            ]
            started_for_address = any(
                int(key[0]) == int(pred_bb)
                for key in self.reservoir_roots_started
            ) or any(
                int(key[0]) == int(pred_bb)
                for key in self.reservoir_roots_started_cumulative
            )
            snapshot_variant_count = sum(
                len(entries)
                for key, entries in self.known_branch_root_snapshots.items()
                if int(key[0]) == int(pred_bb)
            )
            direct_call_snapshot_variant_count = (
                len(self.direct_call_snapshots.get(int(pred_bb), {}))
                if _is_direct_call_mnemonic(mnemonic)
                else 0
            )
            direct_call_attempt_count = (
                sum(1 for key in self.direct_call_snapshot_attempts_seen if int(key[0]) == int(pred_bb))
                if _is_direct_call_mnemonic(mnemonic)
                else 0
            )
            total_snapshot_variant_count = snapshot_variant_count + direct_call_snapshot_variant_count
            frontier_predecessors.append({
                "bb": f"0x{pred_bb:08x}",
                "mnemonic": mnemonic,
                "is_branch_frontier": is_branch_frontier,
                "is_switch_frontier": is_switch_frontier,
                "is_call_frontier": is_call_frontier,
                "frontier_category": frontier_category,
                "function": pred_function or None,
                "uncovered_successors": len(uncovered_successors),
                "downstream_uncovered_potential": sum(successor_potential.values()),
                "max_successor_downstream_potential": max(successor_potential.values(), default=0),
                "total_successors": len(successors),
                "known_branch_events": len(known_event_keys),
                "known_snapshot_variants": total_snapshot_variant_count,
                "known_branch_snapshot_variants": snapshot_variant_count,
                "known_direct_call_snapshot_variants": direct_call_snapshot_variant_count,
                "direct_call_attempts_seen": direct_call_attempt_count,
                "root_started": started_for_address or direct_call_attempt_count > 0,
                "successor_semantic_priority": successor_semantic_priority,
                "successor_semantic_categories": dict(successor_categories),
                "sample_uncovered_successors": [
                    f"0x{bb:08x}" for bb in uncovered_successors[:8]
                ],
            })

        frontier_predecessors.sort(
            key=lambda item: (
                int(item.get("successor_semantic_priority", 0) or 0),
                int(item.get("downstream_uncovered_potential", 0) or 0),
                int(item.get("max_successor_downstream_potential", 0) or 0),
                int(item["uncovered_successors"]),
                int(item["total_successors"]),
                item["bb"],
            ),
            reverse=True,
        )
        switch_frontiers = [
            item for item in frontier_predecessors
            if item.get("is_switch_frontier")
        ]
        call_frontiers = [
            item for item in frontier_predecessors
            if item.get("is_call_frontier")
        ]
        blocking_hints = []
        if frontier_category_counts.get("switch_case_frontier", 0):
            blocking_hints.append({
                "kind": "switch_case_frontier",
                "uncovered_successors": int(frontier_category_counts["switch_case_frontier"]),
                "method": "expand TBB/TBH/LDRPC alternatives from entry-derived snapshots; keep per-case provenance and replay state, not direct PC jumps",
            })
        if frontier_category_counts.get("indirect_call_or_return_frontier", 0):
            blocking_hints.append({
                "kind": "indirect_call_or_return_frontier",
                "uncovered_successors": int(frontier_category_counts["indirect_call_or_return_frontier"]),
                "method": "record dynamic BLX/BX target provenance and replay from the closest pre-dispatch snapshot with equivalent memory/register state",
            })
        if uncovered_function_category_counts.get("stream_or_protocol_input", 0) or uncovered_function_category_counts.get("protocol_callback", 0):
            blocking_hints.append({
                "kind": "stream_or_protocol_input",
                "uncovered_bbs": int(
                    uncovered_function_category_counts.get("stream_or_protocol_input", 0)
                    + uncovered_function_category_counts.get("protocol_callback", 0)
                ),
                "method": "inject protocol-shaped bytes into discovered stream/ring-buffer profiles from initialized snapshots; do not cold-call parser functions",
            })
        if uncovered_function_category_counts.get("interrupt_or_vector_handler", 0):
            blocking_hints.append({
                "kind": "interrupt_or_vector_handler",
                "uncovered_bbs": int(uncovered_function_category_counts["interrupt_or_vector_handler"]),
                "method": "inject IRQs from reservoir/prefix snapshots with enabled-state and pending-flag modeling, then continue normal replay",
            })
        if uncovered_function_category_counts.get("hal_or_peripheral_state", 0):
            blocking_hints.append({
                "kind": "hal_or_peripheral_state",
                "uncovered_bbs": int(uncovered_function_category_counts["hal_or_peripheral_state"]),
                "method": "infer peripheral state transitions and MMIO status sequences, not isolated random register values",
            })
        if uncovered_function_category_counts.get("rtos_or_task_entry", 0):
            blocking_hints.append({
                "kind": "rtos_or_task_entry",
                "uncovered_bbs": int(uncovered_function_category_counts["rtos_or_task_entry"]),
                "method": "decode task/thread create arguments at the callsite and replay the entry with captured stack/global state",
            })

        return {
            "scope": "valid_basic_blocks" if valid_only and self.prepared.valid_bb_set else "refined_static_bbs",
            "total_scope_bbs": len(scope),
            "covered_scope_bbs": len(covered & scope),
            "uncovered_scope_bbs": len(uncovered),
            "entry_reachable_uncovered_bbs": len(entry_reachable - covered),
            "vector_only_uncovered_bbs": len((vector_reachable - entry_reachable) - covered),
            "static_unreachable_uncovered_bbs": len((scope - combined_reachable) - covered),
            "uncovered_with_covered_predecessor_bbs": uncovered_with_covered_predecessor,
            "uncovered_without_covered_predecessor_bbs": uncovered_without_covered_predecessor,
            "uncovered_reachable_but_predecessor_uncovered_bbs": uncovered_reachable_but_predecessor_uncovered,
            "uncovered_without_static_predecessor_bbs": uncovered_without_static_predecessor,
            "frontier_target_bbs": len(frontier_targets),
            "frontier_target_bb_list": [f"0x{bb:08x}" for bb in frontier_targets],
            "frontier_category_counts": dict(frontier_category_counts),
            "uncovered_function_category_counts": dict(uncovered_function_category_counts),
            "uncovered_function_category_examples": dict(uncovered_function_examples),
            "blocking_hints": blocking_hints,
            "frontier_predecessor_count": len(frontier_predecessors),
            "top_frontier_predecessors": frontier_predecessors[:max(0, max_frontier_predecessors)],
            "top_switch_frontiers": switch_frontiers[:max(0, max_frontier_predecessors)],
            "top_call_frontiers": call_frontiers[:max(0, max_frontier_predecessors)],
        }

    def hotspot_frontier_target_bb_list(
        self,
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        *,
        max_predecessors: int = 16,
        max_targets: int = 0,
        switch_only: bool = False,
        min_uncovered_successors: int = 1,
    ) -> List[int]:
        """
        Expand uncovered frontier BBs starting from the hottest covered predecessors.

        This complements frontier_target_bb_list(): instead of globally sorting all
        uncovered successors, it first picks the most promising covered predecessor
        BBs (typically wide TBB/TBH dispatchers) and then drains their remaining
        uncovered successors together.
        """
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}

        def uncovered_downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        predecessor_items: List[Tuple[Tuple[int, ...], int, List[int]]] = []
        for pred_bb, successors in sorted(effective_successors.items()):
            if pred_bb not in covered:
                continue
            insn = self.prepared.branch_instruction_by_bb.get(pred_bb, {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if not _is_replayable_frontier_mnemonic(mnemonic):
                continue
            if switch_only and not _is_switch_frontier_mnemonic(mnemonic):
                continue
            uncovered_successors = sorted(
                bb for bb in successors
                if bb in scope and bb not in covered
            )
            if len(uncovered_successors) < max(1, min_uncovered_successors):
                continue
            successor_potential = {
                int(bb): uncovered_downstream_potential(int(bb))
                for bb in uncovered_successors
            }
            uncovered_successors.sort(
                key=lambda bb: (successor_potential.get(int(bb), 0), -int(bb)),
                reverse=True,
            )
            known_event_keys = [
                key for key in self.known_main_branch_events
                if int(key[0]) == int(pred_bb)
            ]
            snapshot_variant_count = sum(
                len(entries)
                for key, entries in self.known_branch_root_snapshots.items()
                if int(key[0]) == int(pred_bb)
            )
            priority = (
                sum(successor_potential.values()),
                max(successor_potential.values(), default=0),
                len(uncovered_successors),
                1 if _is_switch_frontier_mnemonic(mnemonic) else 0,
                1 if _is_call_frontier_mnemonic(mnemonic) else 0,
                snapshot_variant_count,
                len(known_event_keys),
                -int(pred_bb),
            )
            predecessor_items.append((priority, pred_bb, uncovered_successors))

        predecessor_items.sort(key=lambda item: item[0], reverse=True)

        targets: List[int] = []
        seen: Set[int] = set()
        chosen_predecessors = predecessor_items[:max(1, max_predecessors)] if max_predecessors > 0 else predecessor_items
        for _priority, _pred_bb, uncovered_successors in chosen_predecessors:
            for bb in uncovered_successors:
                if bb in seen:
                    continue
                seen.add(bb)
                targets.append(bb)
                if max_targets and max_targets > 0 and len(targets) >= max_targets:
                    return targets
        return targets

    def uncovered_bb_sets(
        self,
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
    ) -> Dict[str, Set[int]]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)

        reachability = self._static_reachability_sets()
        entry_reachable = reachability["entry_reachable"] & scope
        vector_reachable = reachability["vector_reachable"] & scope
        combined_reachable = reachability["combined_reachable"] & scope

        return {
            "scope": scope,
            "covered": covered,
            "uncovered": scope - covered,
            "entry_reachable": entry_reachable - covered,
            "vector_only": (vector_reachable - entry_reachable) - covered,
            "static_unreachable": (scope - combined_reachable) - covered,
        }

    def frontier_target_bb_list(
        self,
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        min_uncovered_successors: int = 1,
        switch_only: bool = False,
        max_targets: int = 0,
        target_filter: Optional[Set[int]] = None,
        include_nearby_uncovered: bool = False,
        nearby_limit: int = 0,
    ) -> List[int]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)
        filtered_targets = None
        if target_filter is not None:
            filtered_targets = self.validate_coverage(target_filter) & scope
            if not filtered_targets:
                return []

        candidates = []
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}

        def uncovered_downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        for pred_bb, successors in sorted(effective_successors.items()):
            if pred_bb not in covered:
                continue
            uncovered_successors = sorted(
                bb
                for bb in successors
                if bb in scope
                and bb not in covered
                and (filtered_targets is None or bb in filtered_targets)
            )
            if len(uncovered_successors) < max(1, min_uncovered_successors):
                continue
            insn = self.prepared.branch_instruction_by_bb.get(pred_bb, {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if not _is_replayable_frontier_mnemonic(mnemonic):
                continue
            if switch_only and not _is_switch_frontier_mnemonic(mnemonic):
                continue
            successor_potential = {
                int(bb): uncovered_downstream_potential(int(bb))
                for bb in uncovered_successors
            }
            successor_semantic_priority = {
                int(bb): self._semantic_priority_for_bb(int(bb))
                for bb in uncovered_successors
            }
            uncovered_successors.sort(
                key=lambda bb: (
                    successor_semantic_priority.get(int(bb), 0),
                    successor_potential.get(int(bb), 0),
                    -int(bb),
                ),
                reverse=True,
            )
            candidates.append((
                pred_bb,
                mnemonic,
                uncovered_successors,
                sum(successor_potential.values()),
                max(successor_potential.values(), default=0),
                max(successor_semantic_priority.values(), default=0),
                sum(successor_semantic_priority.values()),
            ))

        candidates.sort(
            key=lambda item: (
                item[5],
                item[6],
                item[3],
                item[4],
                len(item[2]),
                1 if _is_switch_frontier_mnemonic(item[1]) else 0,
                1 if _is_call_frontier_mnemonic(item[1]) else 0,
                item[0],
            ),
            reverse=True,
        )

        targets: List[int] = []
        seen: Set[int] = set()
        round_robin_frontiers = (
            os.environ.get("LSGEMU_FRONTIER_TARGET_ROUND_ROBIN", "1").lower()
            not in {"0", "false", "no", "off"}
        )
        if round_robin_frontiers and len(candidates) > 1:
            # A few high-potential parser/switch predecessors can otherwise
            # monopolize every max_targets-sized window.  Round-robin preserves
            # predecessor priority while still giving lower-ranked real
            # frontiers a chance to seed entry-derived replay states.
            rows: List[List[int]] = [list(item[2]) for item in candidates if item[2]]
            row_index = 0
            while rows:
                row = rows[row_index]
                bb = int(row.pop(0))
                if bb not in seen:
                    seen.add(bb)
                    targets.append(bb)
                    if max_targets and max_targets > 0 and len(targets) >= max_targets:
                        return targets
                if not row:
                    rows.pop(row_index)
                    if not rows:
                        break
                    row_index %= len(rows)
                else:
                    row_index = (row_index + 1) % len(rows)
        else:
            for _pred_bb, _mnemonic, uncovered_successors, _total_potential, _max_potential, _max_semantic, _total_semantic in candidates:
                for bb in uncovered_successors:
                    if bb in seen:
                        continue
                    seen.add(bb)
                    targets.append(bb)
                    if max_targets and max_targets > 0 and len(targets) >= max_targets:
                        return targets

        if not include_nearby_uncovered:
            return targets

        effective_successors = self._effective_successor_map()
        predecessors: Dict[int, Set[int]] = {bb: set() for bb in self.prepared.static_bb_set}
        for bb_addr, successors in sorted(effective_successors.items()):
            for successor in sorted(successors):
                predecessors.setdefault(successor, set()).add(bb_addr)

        frontier_distance: Dict[int, int] = {}
        queue = deque((bb, 0) for bb in sorted(covered) if bb in self.prepared.static_bb_set)
        visited = {bb for bb, _distance in queue}
        while queue:
            current, distance = queue.popleft()
            for successor in sorted(effective_successors.get(current, set())):
                if successor not in self.prepared.static_bb_set or successor in visited:
                    continue
                visited.add(successor)
                frontier_distance[successor] = min(frontier_distance.get(successor, distance + 1), distance + 1)
                queue.append((successor, distance + 1))

        uncovered_scope = [
            bb
            for bb in (filtered_targets if filtered_targets is not None else (scope - covered))
            if bb not in seen and bb in self.prepared.static_bb_set
        ]
        if not uncovered_scope:
            return targets

        def nearby_priority(bb: int) -> Tuple[int, int, int, int]:
            preds = predecessors.get(bb, set())
            covered_pred_count = sum(1 for pred in preds if pred in covered)
            total_pred_count = len(preds)
            distance = frontier_distance.get(bb, 1_000_000_000)
            return (
                1 if covered_pred_count > 0 else 0,
                -distance,
                covered_pred_count,
                -total_pred_count,
            )

        ordered_nearby = sorted(
            uncovered_scope,
            key=lambda bb: (nearby_priority(bb), -int(bb)),
            reverse=True,
        )

        limit = nearby_limit if nearby_limit and nearby_limit > 0 else len(ordered_nearby)
        nearby_added = 0
        uncovered_scope_set = set(uncovered_scope)
        for bb in ordered_nearby:
            if bb in seen:
                continue
            seen.add(bb)
            targets.append(bb)
            if bb in uncovered_scope_set:
                nearby_added += 1
            if max_targets and max_targets > 0 and len(targets) >= max_targets:
                break
            if nearby_added >= limit:
                break
        return targets

    def frontier_target_bb_list_from_anchors(
        self,
        anchor_bbs: Iterable[int],
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        min_uncovered_successors: int = 1,
        switch_only: bool = False,
        max_targets: int = 0,
    ) -> List[int]:
        """
        Return immediate frontier targets exposed by recently covered anchors.

        This is used after semantic entry stages such as stream input, IRQ, or
        task replay. It keeps exploration local to state that was just reached
        by Unicorn, instead of letting a global frontier queue bury the newly
        exposed callback/parser/switch branches behind older libc/HAL edges.
        """
        anchors = self.validate_coverage(anchor_bbs or set())
        if not anchors:
            return []
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}

        def uncovered_downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        candidates: List[Tuple[Tuple[int, ...], int, List[int]]] = []
        for pred_bb in sorted(anchors):
            if pred_bb not in covered:
                continue
            insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if not _is_replayable_frontier_mnemonic(mnemonic):
                continue
            if switch_only and not _is_switch_frontier_mnemonic(mnemonic):
                continue
            uncovered_successors = sorted(
                int(bb)
                for bb in effective_successors.get(int(pred_bb), set())
                if int(bb) in scope and int(bb) not in covered
            )
            if len(uncovered_successors) < max(1, min_uncovered_successors):
                continue
            successor_potential = {
                int(bb): uncovered_downstream_potential(int(bb))
                for bb in uncovered_successors
            }
            successor_semantic_priority = {
                int(bb): self._semantic_priority_for_bb(int(bb))
                for bb in uncovered_successors
            }
            uncovered_successors.sort(
                key=lambda bb: (
                    successor_semantic_priority.get(int(bb), 0),
                    successor_potential.get(int(bb), 0),
                    -int(bb),
                ),
                reverse=True,
            )
            priority = (
                max(successor_semantic_priority.values(), default=0),
                sum(successor_semantic_priority.values()),
                1 if _is_switch_frontier_mnemonic(mnemonic) else 0,
                1 if _is_call_frontier_mnemonic(mnemonic) else 0,
                sum(successor_potential.values()),
                max(successor_potential.values(), default=0),
                len(uncovered_successors),
                -int(pred_bb),
            )
            candidates.append((priority, int(pred_bb), uncovered_successors))

        candidates.sort(key=lambda item: item[0], reverse=True)
        targets: List[int] = []
        seen: Set[int] = set()
        for _priority, _pred_bb, uncovered_successors in candidates:
            for bb in uncovered_successors:
                if bb in seen:
                    continue
                seen.add(bb)
                targets.append(bb)
                if max_targets and max_targets > 0 and len(targets) >= max_targets:
                    return targets
        return targets

    def prioritized_target_bb_list(
        self,
        target_bbs: Iterable[int],
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        prefer_frontier: bool = True,
        switch_only: bool = False,
        min_uncovered_successors: int = 1,
        max_targets: int = 0,
        include_nearby_uncovered: bool = True,
        nearby_limit: int = 0,
        exclude_targets: Optional[Set[int]] = None,
        prefer_expandable: bool = False,
    ) -> List[int]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)
        filtered_targets = self.validate_coverage(target_bbs) & scope
        if exclude_targets:
            filtered_targets -= self.validate_coverage(exclude_targets)
        if not filtered_targets:
            return []
        if not getattr(self, "scheduler_feedback", {}):
            try:
                self._scheduler_feedback_summary()
            except Exception:
                pass

        prioritized = self.frontier_target_bb_list(
            coverage=covered,
            valid_only=valid_only,
            min_uncovered_successors=min_uncovered_successors,
            switch_only=switch_only,
            max_targets=0,
            target_filter=filtered_targets,
            include_nearby_uncovered=include_nearby_uncovered,
            nearby_limit=nearby_limit,
        )
        feedback_target_priority: Dict[int, Tuple[int, int]] = {}
        feedback = getattr(self, "scheduler_feedback", {})
        if not isinstance(feedback, dict):
            feedback = {}
        feedback_targets = feedback.get("target_bbs_by_action", {}) if isinstance(feedback, dict) else {}
        recommended_actions = list(feedback.get("recommended_next_stages", []) or [])
        for action_rank, action in enumerate(recommended_actions):
            raw_targets = feedback_targets.get(action, []) if isinstance(feedback_targets, dict) else []
            action_priority = max(0, 1000 - (action_rank * 25))
            for raw_target in raw_targets:
                try:
                    if isinstance(raw_target, str):
                        target_bb = int(raw_target, 16) & 0xFFFFFFFF
                    else:
                        target_bb = int(raw_target) & 0xFFFFFFFF
                except (TypeError, ValueError):
                    continue
                if target_bb not in filtered_targets:
                    continue
                existing = feedback_target_priority.get(target_bb)
                if existing is None or action_priority > existing[0]:
                    feedback_target_priority[target_bb] = (action_priority, action_rank)
        if feedback_target_priority:
            prioritized.sort(
                key=lambda bb: (
                    feedback_target_priority.get(int(bb), (0, 9999))[0],
                    -feedback_target_priority.get(int(bb), (0, 9999))[1],
                    self._semantic_priority_for_bb(int(bb)),
                    -int(bb),
                ),
                reverse=True,
            )
        if prefer_expandable and prioritized:
            effective_successors = self._effective_successor_map()

            def expandable_priority(bb: int) -> Tuple[int, int, int, int]:
                successors = effective_successors.get(bb, set())
                non_self_successors = {succ for succ in successors if succ != bb}
                uncovered_non_self = {succ for succ in non_self_successors if succ not in covered}
                return (
                    self._semantic_priority_for_bb(int(bb)),
                    1 if uncovered_non_self else 0,
                    1 if non_self_successors else 0,
                    len(uncovered_non_self) if uncovered_non_self else len(non_self_successors),
                )

            prioritized.sort(
                key=lambda bb: (expandable_priority(bb), -int(bb)),
                reverse=True,
            )
        if not prefer_frontier:
            prioritized = [bb for bb in prioritized if bb in filtered_targets]

        if max_targets and max_targets > 0:
            return prioritized[:max_targets]
        return prioritized

    def scheduler_feedback_target_bb_list(
        self,
        *,
        actions: Optional[Iterable[str]] = None,
        max_targets: int = 0,
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        switch_only: bool = False,
        include_nearby_uncovered: bool = True,
        nearby_limit: int = 0,
        exclude_targets: Optional[Set[int]] = None,
        target_filter: Optional[Set[int]] = None,
    ) -> List[int]:
        """Return uncovered BB targets directly recommended by diagnostics."""
        if not getattr(self, "semantic_obligation_enabled", True):
            return []
        try:
            feedback = self._scheduler_feedback_summary()
        except Exception:
            feedback = getattr(self, "scheduler_feedback", {}) or {}
        if not isinstance(feedback, dict):
            return []

        requested_actions = [str(item) for item in (actions or feedback.get("recommended_next_stages", []) or [])]
        if not requested_actions:
            return []
        targets_by_action = feedback.get("target_bbs_by_action", {})
        if not isinstance(targets_by_action, dict):
            return []

        raw_targets: List[int] = []
        for action in requested_actions:
            for raw in targets_by_action.get(action, []) or []:
                parsed = _hex_to_int(raw)
                if parsed is not None:
                    raw_targets.append(parsed)
        if not raw_targets:
            return []

        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if valid_only and self.prepared.valid_bb_set else self.prepared.static_bb_set
        candidate_targets = self.validate_coverage(raw_targets) & set(scope)
        if target_filter is not None:
            candidate_targets &= self.validate_coverage(target_filter)
        candidate_targets -= covered
        if exclude_targets:
            candidate_targets -= self.validate_coverage(exclude_targets)
        if switch_only:
            candidate_targets = {
                bb
                for bb in candidate_targets
                if any(
                    item.get("is_switch_frontier")
                    and f"0x{int(bb) & 0xFFFFFFFF:08x}" in set(item.get("sample_uncovered_successors", []) or [])
                    for item in (feedback.get("uncovered_summary", {}) or {}).get("top_frontier_predecessors", []) or []
                    if isinstance(item, dict)
                )
            }
        if not candidate_targets:
            return []

        prioritized = self.frontier_target_bb_list(
            coverage=covered,
            valid_only=valid_only,
            min_uncovered_successors=1,
            switch_only=switch_only,
            max_targets=0,
            target_filter=candidate_targets,
            include_nearby_uncovered=include_nearby_uncovered,
            nearby_limit=nearby_limit,
        )
        if not prioritized:
            prioritized = list(candidate_targets)
        if max_targets and max_targets > 0:
            return prioritized[:max_targets]
        return prioritized

    def scheduler_feedback_summary_for_progress(self, max_actions: int = 6) -> Dict[str, object]:
        """Small progress-safe scheduler summary."""
        try:
            feedback = self._scheduler_feedback_summary()
        except Exception:
            feedback = getattr(self, "scheduler_feedback", {}) or {}
        if not isinstance(feedback, dict):
            return {}
        actions = []
        for item in (feedback.get("actions", []) or [])[:max(0, int(max_actions))]:
            if not isinstance(item, dict):
                continue
            actions.append({
                "action": item.get("action"),
                "priority": int(item.get("priority", 0) or 0),
                "count": int(item.get("count", 0) or 0),
                "target_bbs": list(item.get("target_bbs", []) or [])[:8],
                "sources": list(item.get("sources", []) or [])[:4],
            })
        return {
            "has_actionable_feedback": bool(feedback.get("has_actionable_feedback")),
            "recommended_next_stages": list(feedback.get("recommended_next_stages", []) or [])[:max(0, int(max_actions))],
            "reason_counts": dict(feedback.get("reason_counts", {}) or {}),
            "actions": actions,
        }

    def differential_probe_progress_summary(self) -> Dict[str, object]:
        """差分扰动（二级定位）计数快照，供周期 checkpoint 落盘。

        solver/tracer 两侧计数此前只活在进程内，而 campaign 的 attempt 以
        SIGTERM 收尾、finalize 报告不可靠（第 7 轮 campaign 无
        *_interleaved_report.json）——这里是周期性、SIGTERM 安全的观测点。
        ``probe_phase_ran`` 与 ``path_naturalization_skip_reason`` 用于区分
        「宿主阶段被 skip」与「跑了但 0 工作量」：默认臂的宿主阶段是
        path_naturalization（消融臂下它整体早退，探针改挂在 branch_mmio
        的 generic_dynamic_fallback 上），两者在纯计数上同为全 0。
        只读、无副作用，任何异常都退化为空字典而非中断 checkpoint。
        """
        summary: Dict[str, object] = {}
        try:
            tracer = getattr(self, "register_tracer", None)
            summary["tracer"] = (
                dict(getattr(tracer, "differential_probe_stats", {}) or {})
                if tracer is not None
                else {}
            )
            solver = getattr(self, "differential_probe_solver", None)
            summary["solver"] = (
                dict(solver.get_statistics() or {})
                if solver is not None and hasattr(solver, "get_statistics")
                else {}
            )
            phase_metadata = getattr(self, "phase_metadata", None) or {}
            naturalization = (
                dict(phase_metadata.get("path_naturalization") or {})
                if isinstance(phase_metadata, dict)
                else {}
            )
            summary["probe_phase_ran"] = bool(naturalization) and not bool(
                naturalization.get("skipped")
            )
            summary["path_naturalization_skip_reason"] = naturalization.get(
                "skip_reason"
            )
            summary["path_naturalization_elapsed_seconds"] = naturalization.get(
                "elapsed_seconds"
            )
        except Exception:
            return dict(summary)
        return summary

    def current_replay_state_fingerprint_summary(self) -> Dict[str, object]:
        """Best-effort current state fingerprint for progress/checkpoint files."""
        emulator = getattr(self, "emulator", None)
        mmio_handler = getattr(self, "mmio_handler", None)
        uc = getattr(emulator, "uc", None)
        if uc is None or mmio_handler is None:
            return {}
        try:
            pc = int(uc.reg_read(UC_ARM_REG_PC)) & 0xFFFFFFFF
        except Exception:
            return {}
        bb = self.prepared.resolve_basic_block(pc & ~1)
        if bb is None:
            bb = pc & ~1
        try:
            fingerprint = build_replay_state_fingerprint(
                uc=uc,
                bb_addr=int(bb),
                mmio_handler=mmio_handler,
                emulator=emulator,
                call_stack=getattr(getattr(emulator, "register_tracer", None), "call_stack", None),
                max_dirty_pages=max(0, _env_int("LSGEMU_PROGRESS_STATE_FP_MAX_DIRTY_PAGES", 4)),
                ram_sample_bytes=max(4, _env_int("LSGEMU_PROGRESS_STATE_FP_RAM_SAMPLE_BYTES", 128)),
                include_ram=_env_flag("LSGEMU_PROGRESS_STATE_FP_INCLUDE_RAM", "1"),
            )
        except Exception:
            return {
                "pc": f"0x{pc:08x}",
                "bb_addr": f"0x{int(bb) & 0xFFFFFFFF:08x}",
                "fingerprint_error": True,
            }
        return {
            "pc": f"0x{pc:08x}",
            "bb_addr": fingerprint.get("bb_addr"),
            "fingerprint_sha256": fingerprint.get("fingerprint_sha256"),
            "ram_dirty_sha256": fingerprint.get("ram_dirty_sha256"),
            "dirty_pages": len(fingerprint.get("dirty_pages", []) or []),
            "mmio_state_entries": len(fingerprint.get("mmio_state", {}) or {}),
            "constraint_hit_keys": len(fingerprint.get("constraint_hits", []) or []),
            "call_stack_depth": len(fingerprint.get("call_stack", []) or []),
        }

    def _replay_state_fingerprint_summary(
        self,
        *,
        emulator: Optional[IntelligentEmulator],
        mmio_handler: Optional[EnhancedMMIOHandler],
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
        bb_addr: Optional[int] = None,
        max_dirty_pages: int = 4,
        ram_sample_bytes: int = 128,
        include_candidate_configuration: bool = True,
        include_observed_constraint_hits: bool = True,
    ) -> Dict[str, object]:
        """Compact state-equivalence summary for replay attempt records."""
        if emulator is None or mmio_handler is None:
            return {}
        uc = getattr(emulator, "uc", None)
        if uc is None:
            return {}
        if bb_addr is None:
            try:
                pc = int(uc.reg_read(UC_ARM_REG_PC)) & 0xFFFFFFFF
            except Exception:
                pc = 0
            bb_addr = self.prepared.resolve_basic_block(pc & ~1) or (pc & ~1)
        constraint_hits = []
        for attr_name in (
            "pc_constraint_hit_keys",
            "branch_mmio_pc_constraint_hit_keys",
            "branch_mmio_scoped_pc_constraint_hit_keys",
        ):
            try:
                constraint_hits.extend(list(getattr(mmio_handler, attr_name, set()) or []))
            except Exception:
                continue
        try:
            fingerprint = build_replay_state_fingerprint(
                uc=uc,
                bb_addr=int(bb_addr),
                mmio_handler=mmio_handler,
                emulator=emulator,
                snapshot_entry=snapshot_entry,
                constraint_hit_keys=constraint_hits,
                call_stack=getattr(getattr(emulator, "register_tracer", None), "call_stack", None),
                max_dirty_pages=max(0, int(max_dirty_pages)),
                ram_sample_bytes=max(4, int(ram_sample_bytes)),
                include_ram=_env_flag("LSGEMU_REPLAY_ATTEMPT_FP_INCLUDE_RAM", "1"),
                include_candidate_configuration=bool(
                    include_candidate_configuration
                ),
                include_observed_constraint_hits=bool(
                    include_observed_constraint_hits
                ),
            )
        except Exception:
            return {
                "bb_addr": f"0x{int(bb_addr) & 0xFFFFFFFF:08x}",
                "fingerprint_error": True,
            }
        return {
            "bb_addr": fingerprint.get("bb_addr"),
            "fingerprint_sha256": fingerprint.get("fingerprint_sha256"),
            "ram_dirty_sha256": fingerprint.get("ram_dirty_sha256"),
            "dirty_pages": len(fingerprint.get("dirty_pages", []) or []),
            "mmio_state_entries": len(fingerprint.get("mmio_state", {}) or []),
            "constraint_hit_keys": len(fingerprint.get("constraint_hits", []) or []),
            "call_stack_depth": len(fingerprint.get("call_stack", []) or []),
            "context_hard_sha256": dict(
                fingerprint.get("causal_context", {}) or {}
            ).get("hard_compatibility_sha256"),
            "context_transition_digest": dict(
                fingerprint.get("causal_context", {}) or {}
            ).get("transition_digest"),
            "snapshot": fingerprint.get("snapshot"),
            "candidate_configuration": dict(
                fingerprint.get("candidate_configuration", {}) or {}
            ),
            "fingerprint_scope": str(
                fingerprint.get("fingerprint_scope") or "restored_state"
            ),
        }

    @staticmethod
    def _state_equivalence_record(
        control_run_result: Optional[Dict[str, object]],
        result_run_result: Optional[Dict[str, object]],
    ) -> Dict[str, object]:
        return state_equivalence_record(control_run_result, result_run_result)

    @staticmethod
    def _environment_feasibility_record(
        *,
        strategy: str,
        outcome: str,
        constraint_items: Iterable[Dict[str, object]],
        constraint_feedback: Optional[Dict[str, object]],
        result_eval: Dict[str, object],
        state_equivalence: Optional[Dict[str, object]],
        coverage: Optional[Dict[str, object]],
    ) -> Dict[str, object]:
        return environment_feasibility_record(
            strategy=strategy,
            outcome=outcome,
            constraint_items=constraint_items,
            constraint_feedback=constraint_feedback,
            result_eval=result_eval,
            state_equivalence=state_equivalence,
            coverage=coverage,
        )

    def expandable_target_bb_list(
        self,
        target_bbs: Iterable[int],
        coverage: Optional[Iterable[int]] = None,
        require_uncovered_non_self_successor: bool = False,
    ) -> List[int]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        effective_successors = self._effective_successor_map()
        expandable_targets: List[int] = []
        fallback_targets: List[int] = []

        for bb in _dedupe_preserve_order(target_bbs):
            successors = effective_successors.get(bb, set())
            non_self_successors = {successor for successor in successors if successor != bb}
            if not non_self_successors:
                continue
            uncovered_non_self_successors = {successor for successor in non_self_successors if successor not in covered}
            if uncovered_non_self_successors:
                expandable_targets.append(bb)
            elif not require_uncovered_non_self_successor:
                fallback_targets.append(bb)

        return expandable_targets or fallback_targets

    def frontier_target_bbs(
        self,
        coverage: Optional[Iterable[int]] = None,
        valid_only: bool = True,
        min_uncovered_successors: int = 1,
        switch_only: bool = False,
        max_targets: int = 0,
        target_filter: Optional[Set[int]] = None,
    ) -> Set[int]:
        """
        Return uncovered successor BBs whose predecessors are already covered.

        This target set is useful for a focused post-phase after the broad
        reservoir pass: it tells the scheduler to drain immediate uncovered
        frontier edges such as TBH/TBB dispatch cases.
        """
        feedback_targets = self.scheduler_feedback_target_bb_list(
            actions=[
                "target_switch_case_expansion",
                "target_dynamic_call_successor",
                "target_direct_call_continuation",
                "target_branch_frontier",
                "drain_ready_frontier_candidates",
            ],
            max_targets=max_targets,
            coverage=coverage,
            valid_only=valid_only,
            switch_only=switch_only,
            include_nearby_uncovered=False,
            target_filter=target_filter,
        )
        ordered_targets = _dedupe_preserve_order(
            feedback_targets
            + self.frontier_target_bb_list(
                coverage=coverage,
                valid_only=valid_only,
                min_uncovered_successors=min_uncovered_successors,
                switch_only=switch_only,
                max_targets=max_targets,
                target_filter=target_filter,
            )
        )
        if max_targets and max_targets > 0:
            ordered_targets = ordered_targets[:max_targets]
        return set(ordered_targets)

    def conditional_branches(self):
        return self.prepared.conditional_branch_bbs

    def _all_elf_symbols(self) -> List[Dict[str, object]]:
        """Load all ELF symbols, including data objects used as framework state."""
        symbols: List[Dict[str, object]] = []
        tools = ("arm-none-eabi-nm", "llvm-nm", "nm")
        output = ""
        for tool in tools:
            try:
                completed = subprocess.run(
                    [tool, "-S", "--defined-only", "-n", str(self.prepared.firmware_path)],
                    check=False,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.DEVNULL,
                    text=True,
                    timeout=30,
                )
            except Exception:
                continue
            if completed.returncode == 0 and completed.stdout:
                output = completed.stdout
                break
        if not output:
            return symbols

        for line in output.splitlines():
            parts = line.strip().split()
            if len(parts) < 3:
                continue
            try:
                address = int(parts[0], 16)
            except ValueError:
                continue
            size = 0
            if len(parts) >= 4 and re.fullmatch(r"[0-9a-fA-F]+", parts[1]):
                try:
                    size = int(parts[1], 16)
                except ValueError:
                    size = 0
                symbol_type = parts[2]
                symbol_name = parts[3]
            else:
                symbol_type = parts[1]
                symbol_name = parts[2]
            # Only Thumb code symbols carry a low-bit ISA tag. Data symbols are
            # often byte-granular state fields; clearing bit 0 aliases adjacent
            # fields such as length/index_r in packed queues.
            normalized_address = int(address)
            if str(symbol_type).lower() in {"t", "w"}:
                normalized_address &= ~1
            symbols.append({
                "address": int(normalized_address),
                "size": int(size),
                "type": symbol_type,
                "name": symbol_name,
            })
        return symbols

    def _function_starts_by_name(self) -> Dict[str, int]:
        cached = getattr(self, "_function_starts_cache", None)
        if cached is not None:
            return cached
        result = {
            str(name): int(addr) & ~1
            for name, addr in getattr(self.prepared, "symbols_by_name", {}).items()
            if int(addr) in self.prepared.instruction_lookup
            and not str(name).startswith("$")
        }
        self._function_starts_cache = result
        return result

    def _sorted_function_starts(self) -> List[Tuple[int, str]]:
        """Sorted (addr, name) pairs; cached because _function_name_for_addr is
        called once per BB in uncovered_coverage_summary (O(BBs) callers must
        not each re-sort the full symbol table)."""
        cached = getattr(self, "_sorted_function_starts_cache", None)
        cached_addrs = getattr(self, "_function_start_addrs_cache", None)
        if cached is not None and cached_addrs is not None:
            return cached
        functions = sorted(
            (addr, name) for name, addr in self._function_starts_by_name().items()
        )
        self._sorted_function_starts_cache = functions
        # cycle2 k.5 H1：地址列与排序表同缓存同失效（一次性物化），消掉
        # _function_name_for_addr/_function_entry_for_addr 的每调用重建
        # （每次 13k 元素 × 每写 10 万 BB ≈ 1.4e9 次元素物化的主项）。
        self._function_start_addrs_cache = [start_addr for start_addr, _name in functions]
        return functions

    def _function_start_addrs(self) -> List[int]:
        """Address column of _sorted_function_starts, cached beside it."""
        cached = getattr(self, "_function_start_addrs_cache", None)
        if cached is not None:
            return cached
        self._sorted_function_starts()
        return self._function_start_addrs_cache

    def _function_name_for_addr(self, address: int) -> str:
        import bisect as _bisect

        functions = self._sorted_function_starts()
        if not functions:
            return ""
        addresses = self._function_start_addrs()
        idx = _bisect.bisect_right(addresses, int(address)) - 1
        if idx < 0:
            return ""
        return functions[idx][1]

    def _function_entry_for_addr(self, address: int) -> Optional[int]:
        import bisect as _bisect

        functions = self._sorted_function_starts()
        if not functions:
            return None
        addresses = self._function_start_addrs()
        idx = _bisect.bisect_right(addresses, int(address) & ~1) - 1
        if idx < 0:
            return None
        return functions[idx][0]

    # cycle2 k.5 H1：名→类别记忆表（键 = str(name)，值 = frozenset 拷贝
    # 不可变——调用方拿不到可污染缓存的引用）。
    _SEMANTIC_ENTRY_CATEGORY_MEMO: ClassVar[Dict[str, FrozenSet[str]]] = {}

    @staticmethod
    def _semantic_entry_categories_for_name(name: object) -> FrozenSet[str]:
        key = str(name or "")
        memo = HistoricalRunner._SEMANTIC_ENTRY_CATEGORY_MEMO
        cached = memo.get(key)
        if cached is None:
            cached = frozenset(semantic_entry_categories_for_name(key))
            memo[key] = cached
        return cached

    def _semantic_category_priority(self, categories: Iterable[str]) -> int:
        discovery = self._scheduler_component(
            "obligation_discovery", ObligationDiscovery
        )
        return discovery.category_priority(categories)

    def _semantic_categories_for_bb(self, bb_addr: int) -> Set[str]:
        discovery = self._scheduler_component(
            "obligation_discovery", ObligationDiscovery
        )
        return discovery.categories_for_bb(bb_addr)

    def _semantic_priority_for_bb(self, bb_addr: int) -> int:
        discovery = self._scheduler_component(
            "obligation_discovery", ObligationDiscovery
        )
        return discovery.priority_for_bb(bb_addr)

    def _function_instructions_by_symbol_substring(self, substring: str) -> List[Dict[str, object]]:
        functions = self._function_starts_by_name()
        matches = sorted(
            (addr, name)
            for name, addr in functions.items()
            if substring in name
        )
        if not matches:
            return []
        start, _name = matches[0]
        following = sorted(addr for addr in functions.values() if addr > start)
        end = following[0] if following else start + 0x400
        return [
            self.prepared.instruction_lookup[addr]
            for addr in sorted(self.prepared.instruction_lookup)
            if start <= addr < end
        ]

    def _infer_arduino_hardware_serial_layout(self) -> Optional[Dict[str, int]]:
        """
        Infer an Arduino HardwareSerial RX ring layout from code, not addresses.

        The method is framework-specific but firmware-independent: it reads the
        compiled methods to discover object offsets instead of relying on a
        board or Gateway constant.
        """
        read_insns = self._function_instructions_by_symbol_substring("HardwareSerial4read")
        available_insns = self._function_instructions_by_symbol_substring("HardwareSerial9available")
        init_insns = self._function_instructions_by_symbol_substring("HardwareSerial4init")
        if not read_insns and not available_insns:
            return None

        halfword_offsets: List[int] = []
        word_offsets: List[int] = []
        capacity = 0
        for insn in read_insns + available_insns:
            mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
            offset = _parse_mem_offset(insn.get("operands"), "r0")
            if offset is None:
                continue
            if mnemonic.startswith("LDRH"):
                if offset not in halfword_offsets:
                    halfword_offsets.append(offset)
            elif mnemonic.startswith("LDR") and not mnemonic.startswith("LDRB"):
                if offset not in word_offsets:
                    word_offsets.append(offset)
            if mnemonic == "AND":
                operands = str(insn.get("operands", ""))
                immediates = re.findall(r"#\s*(0x[0-9a-fA-F]+|[0-9]+)", operands)
                if immediates:
                    parsed = _parse_int_token(immediates[-1])
                    if parsed is not None and parsed > 0:
                        capacity = max(capacity, int(parsed) + 1)

        if len(halfword_offsets) < 2 or not word_offsets:
            return None

        inline_candidates: Dict[str, int] = {}
        last_add_immediate_by_reg: Dict[str, int] = {}
        for insn in init_insns:
            add_info = _parse_add_base_immediate(insn.get("operands"), "r0")
            if add_info is not None:
                reg, immediate = add_info
                last_add_immediate_by_reg[reg] = immediate
                continue
            mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
            if not mnemonic.startswith("STR"):
                continue
            src = _parse_dest_register(insn.get("operands"))
            offset = _parse_mem_offset(insn.get("operands"), "r0")
            if src is None or offset is None:
                continue
            if src in last_add_immediate_by_reg:
                inline_candidates[f"0x{offset:x}"] = last_add_immediate_by_reg[src]

        buffer_pointer_offset = int(word_offsets[0])
        return {
            "buffer_pointer_offset": buffer_pointer_offset,
            "head_offset": int(halfword_offsets[0]),
            "tail_offset": int(halfword_offsets[1]),
            "capacity": max(2, int(capacity or 64)),
            "inline_buffer_offset": int(inline_candidates.get(f"0x{buffer_pointer_offset:x}", 0) or 0),
        }

    def discover_stream_input_profiles(self, max_profiles: int = 8) -> List[StreamInputProfile]:
        """
        Discover replay-mutable byte-stream inputs.

        This is intentionally a profile registry. Each profile is a generic
        framework recognizer that infers addresses/offsets from the binary, and
        new frameworks can be added without changing the replay engine.
        """
        profiles: List[StreamInputProfile] = []
        all_symbols = self._all_elf_symbols()
        symbols_by_normalized_name = {
            _normalize_name(str(symbol.get("name", ""))): symbol
            for symbol in all_symbols
            if str(symbol.get("name", ""))
        }
        symbol_names = {
            _normalize_name(str(symbol.get("name", "")))
            for symbol in all_symbols
            if str(symbol.get("name", ""))
        }

        def append_profile(profile: StreamInputProfile) -> None:
            if max_profiles and max_profiles > 0 and len(profiles) >= max_profiles:
                return
            identity = (
                profile.profile_kind,
                profile.object_symbol,
                int(profile.object_addr),
                int(profile.absolute_buffer_addr or 0),
            )
            for existing in profiles:
                if (
                    existing.profile_kind,
                    existing.object_symbol,
                    int(existing.object_addr),
                    int(existing.absolute_buffer_addr or 0),
                    int(existing.auxiliary_addr or 0),
                    int(existing.auxiliary_buffer_addr or 0),
                ) == (
                    *identity,
                    int(profile.auxiliary_addr or 0),
                    int(profile.auxiliary_buffer_addr or 0),
                ):
                    return
            profiles.append(profile)

        gcode_queue_symbol = symbols_by_normalized_name.get("queue")
        gcode_buffer_symbol = symbols_by_normalized_name.get("zn10gcodequeue14commandbuffere")
        gcode_length_symbol = symbols_by_normalized_name.get("zn10gcodequeue6lengthe")
        gcode_index_r_symbol = symbols_by_normalized_name.get("zn10gcodequeue7indexre")
        gcode_index_w_symbol = symbols_by_normalized_name.get("zn10gcodequeue7indexwe")
        if gcode_buffer_symbol and gcode_length_symbol and (
            "zn10gcodequeue19getserialcommandsev" in symbol_names
            or "zn10gcodequeue8enqueueepkcb" in symbol_names
        ):
            append_profile(StreamInputProfile(
                profile_kind="gcode_command_queue",
                object_symbol="GCodeQueue::command_buffer",
                object_addr=int(gcode_queue_symbol.get("address", 0) or 0) if gcode_queue_symbol else 0,
                buffer_pointer_offset=0,
                head_offset=0,
                tail_offset=0,
                capacity=96,
                absolute_buffer_addr=int(gcode_buffer_symbol.get("address", 0) or 0),
                absolute_head_addr=int(gcode_index_w_symbol.get("address", 0) or 0) if gcode_index_w_symbol else None,
                absolute_tail_addr=int(gcode_index_r_symbol.get("address", 0) or 0) if gcode_index_r_symbol else None,
                absolute_length_addr=int(gcode_length_symbol.get("address", 0) or 0),
            ))

        rx_head = symbols_by_normalized_name.get("rxhead")
        rx_tail = symbols_by_normalized_name.get("rxtail")
        vcom_rx = symbols_by_normalized_name.get("vcombufferrx")
        if rx_head and rx_tail and vcom_rx:
            append_profile(StreamInputProfile(
                profile_kind="usb_cdc_flat_ring",
                object_symbol="vcomBufferRx",
                object_addr=int(vcom_rx.get("address", 0) or 0),
                buffer_pointer_offset=0,
                head_offset=0,
                tail_offset=0,
                capacity=256,
                absolute_buffer_addr=int(vcom_rx.get("address", 0) or 0),
                absolute_head_addr=int(rx_head.get("address", 0) or 0),
                absolute_tail_addr=int(rx_tail.get("address", 0) or 0),
            ))

        input_function_terms = (
            "serialgetc",
            "serialread",
            "serialreadable",
            "uartgetc",
            "uartread",
            "uartreadable",
            "basegetc",
            "directserial4read",
            "xmlparse",
            "gnrc",
            "bleattrx",
            "blegaprx",
            "rxdispatch",
        )
        has_generic_input_consumer = any(
            any(term in name for term in input_function_terms)
            for name in symbol_names
        )
        if has_generic_input_consumer:
            generic_buffer_terms = (
                "buff",
                "buffer",
                "rxdata",
                "rxbuf",
                "rxbuffer",
                "uartbuf",
                "serialbuf",
                "packet",
                "pkt",
                "input",
            )
            reject_buffer_terms = (
                "callback",
                "handler",
                "config",
                "pinmap",
                "vtable",
                "vtv",
                "guard",
                "inited",
                "head",
                "tail",
                "allocated",
                "index",
                "length",
                "len",
                "count",
                "state",
                "lock",
                "mutex",
                "stdio",
            )
            generic_candidates: List[Tuple[int, str, int]] = []
            for symbol in all_symbols:
                symbol_type = str(symbol.get("type", ""))
                name = str(symbol.get("name", ""))
                addr = int(symbol.get("address", 0) or 0)
                if symbol_type.lower() not in {"b", "d", "v", "s", "g"}:
                    continue
                if not (0x20000000 <= addr < 0x40000000):
                    continue
                normalized_name = _normalize_name(name)
                if not normalized_name:
                    continue
                if any(term in normalized_name for term in reject_buffer_terms):
                    continue
                if not any(term in normalized_name for term in generic_buffer_terms):
                    continue
                try:
                    size = int(symbol.get("size", 0) or 0)
                except (TypeError, ValueError):
                    size = 0
                if size and size < 8:
                    continue
                capacity = max(16, min(2048, size if size > 0 else 256))
                generic_candidates.append((-capacity, normalized_name, addr))
            for _neg_capacity, _normalized_name, addr in sorted(generic_candidates)[: max(1, max_profiles or 8)]:
                symbol = next((item for item in all_symbols if int(item.get("address", 0) or 0) == addr), None)
                if not symbol:
                    continue
                try:
                    size = int(symbol.get("size", 0) or 0)
                except (TypeError, ValueError):
                    size = 0
                append_profile(StreamInputProfile(
                    profile_kind="generic_global_input_buffer",
                    object_symbol=str(symbol.get("name", "")),
                    object_addr=addr,
                    buffer_pointer_offset=0,
                    head_offset=0,
                    tail_offset=0,
                    capacity=max(16, min(2048, size if size > 0 else 256)),
                    absolute_buffer_addr=addr,
                ))

        has_stream_api_summary = any(
            IntelligentEmulator._stream_input_summary_for_symbol(str(symbol.get("name", ""))) is not None
            for symbol in all_symbols
            if str(symbol.get("type", "")).lower() in {"t", "w"}
        )
        if has_stream_api_summary:
            append_profile(StreamInputProfile(
                profile_kind="stream_api_summary",
                object_symbol="stream_api_summary",
                object_addr=0,
                buffer_pointer_offset=0,
                head_offset=0,
                tail_offset=0,
                capacity=256,
            ))

        has_hardware_serial = bool(
            self._function_instructions_by_symbol_substring("HardwareSerial4read")
            or self._function_instructions_by_symbol_substring("HardwareSerial9available")
        )
        if has_hardware_serial:
            for symbol in all_symbols:
                symbol_type = str(symbol.get("type", ""))
                name = str(symbol.get("name", ""))
                addr = int(symbol.get("address", 0) or 0)
                if symbol_type.lower() not in {"b", "d", "v", "s", "g"}:
                    continue
                if not (0x20000000 <= addr < 0x40000000):
                    continue
                normalized_name = _normalize_name(name)
                if not re.fullmatch(r"serial[0-9]*", normalized_name):
                    continue
                serial_index = normalized_name[len("serial"):]
                if serial_index:
                    device_symbol = symbols_by_normalized_name.get(f"usart{serial_index}") or symbols_by_normalized_name.get(f"uart{serial_index}")
                    rx_ring_symbol = symbols_by_normalized_name.get(f"usart{serial_index}rb") or symbols_by_normalized_name.get(f"uart{serial_index}rb")
                else:
                    device_symbol = None
                    rx_ring_symbol = None
                append_profile(StreamInputProfile(
                    profile_kind="hardware_serial_nested_ring",
                    object_symbol=name,
                    object_addr=addr,
                    buffer_pointer_offset=16,
                    head_offset=6,
                    tail_offset=4,
                    capacity=64,
                    auxiliary_addr=(
                        int(device_symbol.get("address", 0) or 0)
                        if device_symbol else None
                    ),
                    auxiliary_buffer_addr=(
                        int(rx_ring_symbol.get("address", 0) or 0)
                        if rx_ring_symbol else None
                    ),
                ))

        layout = self._infer_arduino_hardware_serial_layout()
        if layout:
            for symbol in all_symbols:
                symbol_type = str(symbol.get("type", ""))
                name = str(symbol.get("name", ""))
                addr = int(symbol.get("address", 0) or 0)
                if symbol_type.lower() not in {"b", "d", "v", "s", "g"}:
                    continue
                if not (0x20000000 <= addr < 0x40000000):
                    continue
                normalized_name = _normalize_name(name)
                if not (
                    re.fullmatch(r"serial[0-9a-z]*", normalized_name)
                    and name[:1].isupper()
                ):
                    continue
                if normalized_name.startswith("global") or "subi" in normalized_name:
                    continue
                append_profile(StreamInputProfile(
                    profile_kind="arduino_hardware_serial",
                    object_symbol=name,
                    object_addr=addr,
                    buffer_pointer_offset=int(layout["buffer_pointer_offset"]),
                    head_offset=int(layout["head_offset"]),
                    tail_offset=int(layout["tail_offset"]),
                    capacity=int(layout["capacity"]),
                    inline_buffer_offset=(
                        int(layout["inline_buffer_offset"])
                        if int(layout.get("inline_buffer_offset") or 0) > 0
                        else None
                    ),
                ))
                if max_profiles and max_profiles > 0 and len(profiles) >= max_profiles:
                    break

        stripped_profile_enabled = str(
            os.environ.get("LSGEMU_ENABLE_STRIPPED_STREAM_PROFILES", "")
        ).strip().lower() in {"1", "true", "yes", "on"}
        if stripped_profile_enabled and (not max_profiles or len(profiles) < max_profiles):
            remaining = max(0, int(max_profiles or 8) - len(profiles)) if max_profiles else 8
            for profile in self._discover_snapshot_pointer_stream_profiles(remaining):
                append_profile(profile)
        observed_memory_profile_enabled = str(
            os.environ.get("LSGEMU_ENABLE_OBSERVED_MEMORY_STREAM_PROFILES", "")
        ).strip().lower() in {"1", "true", "yes", "on"}
        if observed_memory_profile_enabled and (not max_profiles or len(profiles) < max_profiles):
            remaining = max(0, int(max_profiles or 8) - len(profiles)) if max_profiles else 8
            for profile in self._discover_observed_memory_stream_profiles(remaining):
                append_profile(profile)

        force_stream_api = str(
            os.environ.get("LSGEMU_FORCE_STREAM_API_PROFILE", "")
        ).strip().lower() in {"1", "true", "yes", "on"}
        if force_stream_api and (not max_profiles or len(profiles) < max_profiles):
            append_profile(StreamInputProfile(
                profile_kind="stream_api_summary",
                object_symbol="forced_stream_api_summary",
                object_addr=0,
                buffer_pointer_offset=0,
                head_offset=0,
                tail_offset=0,
                capacity=256,
            ))
        return profiles

    def _discover_observed_memory_stream_profiles(self, max_profiles: int = 8) -> List[StreamInputProfile]:
        """Build conservative state-probe profiles from memory read history.

        These profiles are deliberately weaker evidence than a named UART/ring
        buffer. They answer "would changing an observed SRAM/external state byte
        affect execution?" without claiming that the address is attacker input.
        """
        if max_profiles is not None and max_profiles <= 0:
            return []
        profiles: List[StreamInputProfile] = []
        seen_pages: Set[int] = set()
        seen_addresses: Set[int] = set()
        history = list(getattr(self.emulator, "memory_access_history", []) or [])
        external_addresses = set(getattr(self.emulator, "external_memory_input_addresses", set()) or set())
        try:
            sp = int(self.emulator.uc.reg_read(UC_ARM_REG_SP)) & 0xFFFFFFFF
        except Exception:
            sp = 0

        def plausible_state_probe_address(address: int) -> bool:
            address &= 0xFFFFFFFF
            if address == 0:
                return False
            if sp and abs(address - sp) < 0x400:
                return False
            return (
                0x20000000 <= address < 0x40000000
                or address in external_addresses
            )

        def add_profile(address: int, source_pc: int) -> None:
            if max_profiles and len(profiles) >= max_profiles:
                return
            address &= 0xFFFFFFFF
            if not plausible_state_probe_address(address):
                return
            aligned = address & ~0x3
            page = aligned & ~0x3F
            if aligned in seen_addresses or page in seen_pages:
                return
            seen_addresses.add(aligned)
            seen_pages.add(page)
            profiles.append(StreamInputProfile(
                profile_kind="observed_memory_read_buffer",
                object_symbol=f"observed_read_0x{source_pc & 0xFFFFFFFF:08x}",
                object_addr=aligned,
                buffer_pointer_offset=0,
                head_offset=0,
                tail_offset=0,
                capacity=64,
                absolute_buffer_addr=aligned,
                auxiliary_addr=source_pc & 0xFFFFFFFF,
            ))

        for entry in reversed(history):
            if max_profiles and len(profiles) >= max_profiles:
                break
            try:
                pc, address, is_read, _value = entry
            except Exception:
                continue
            if not bool(is_read):
                continue
            add_profile(int(address), int(pc))
        return profiles

    def _discover_snapshot_pointer_stream_profiles(self, max_profiles: int = 8) -> List[StreamInputProfile]:
        """Infer input-buffer candidates for stripped/raw firmware.

        Symbol-based recognizers do not work for vendor raw images.  This
        fallback stays entry-derived: it only uses RAM pointers present in
        snapshots captured during normal execution, then stream replay mutates
        those pointed-to buffers and continues from the same snapshot state.
        """
        if max_profiles is not None and max_profiles <= 0:
            return []

        snapshots = list(reversed(self._ordered_replay_snapshots(self.emulator)))
        profiles: List[StreamInputProfile] = []
        seen_addrs: Set[int] = set()

        def snapshot_regions(snapshot: object) -> List[Tuple[int, int]]:
            regions: List[Tuple[int, int]] = []
            raw_regions = getattr(snapshot, "memory_regions", None) or {}
            for key, data in raw_regions.items():
                try:
                    base, size = key
                    size_i = int(size)
                    if size_i <= 0:
                        size_i = len(bytes(data))
                    regions.append((int(base), size_i))
                except Exception:
                    continue
            if not regions:
                try:
                    base = int(getattr(snapshot, "memory_base", 0) or 0)
                    size = int(getattr(snapshot, "memory_size", 0) or 0)
                    if base and size > 0:
                        regions.append((base, size))
                except Exception:
                    pass
            return regions

        def region_containing(regions: List[Tuple[int, int]], address: int) -> Optional[Tuple[int, int]]:
            for base, size in regions:
                if int(base) <= address < int(base) + int(size):
                    return int(base), int(size)
            return None

        def add_profile(address: int, capacity: int, symbol: str) -> None:
            nonlocal profiles
            if max_profiles and len(profiles) >= max_profiles:
                return
            address &= 0xFFFFFFFF
            if address in seen_addrs:
                return
            if capacity < 4:
                return
            seen_addrs.add(address)
            profiles.append(StreamInputProfile(
                profile_kind="snapshot_register_pointer_buffer",
                object_symbol=symbol,
                object_addr=address,
                buffer_pointer_offset=0,
                head_offset=0,
                tail_offset=0,
                capacity=max(8, min(512, int(capacity))),
                absolute_buffer_addr=address,
            ))

        preferred_regs = ("r0", "r1", "r2", "r3", "r4", "r5", "r12")
        for snapshot in snapshots[: max(16, int(max_profiles or 8) * 4)]:
            if max_profiles and len(profiles) >= max_profiles:
                break
            regions = snapshot_regions(snapshot)
            if not regions:
                continue
            registers = getattr(snapshot, "registers", {}) or {}
            snapshot_addr = int(getattr(snapshot, "address", 0) or 0) & 0xFFFFFFFF
            for reg_name in preferred_regs:
                if max_profiles and len(profiles) >= max_profiles:
                    break
                ptr = int(registers.get(reg_name, 0) or 0) & 0xFFFFFFFF
                region = region_containing(regions, ptr)
                if region is None:
                    continue
                base, size = region
                remaining = base + size - ptr
                if remaining < 8:
                    continue
                add_profile(
                    ptr,
                    min(remaining, 256),
                    f"{reg_name}@snapshot_0x{snapshot_addr:08x}",
                )

            sp = int(registers.get("sp", 0) or 0) & 0xFFFFFFFF
            stack_region = region_containing(regions, sp)
            if stack_region is None:
                continue
            raw_regions = getattr(snapshot, "memory_regions", None) or {}
            stack_bytes = None
            stack_base = 0
            for key, data in raw_regions.items():
                try:
                    base, size = int(key[0]), int(key[1])
                except Exception:
                    continue
                if base <= sp < base + size:
                    stack_base = base
                    stack_bytes = bytes(data)
                    break
            if stack_bytes is None:
                continue
            start = max(0, sp - stack_base)
            end = min(len(stack_bytes), start + 0x80)
            for offset in range(start, max(start, end - 3), 4):
                if max_profiles and len(profiles) >= max_profiles:
                    break
                try:
                    ptr = int.from_bytes(stack_bytes[offset:offset + 4], "little") & 0xFFFFFFFF
                except Exception:
                    continue
                region = region_containing(regions, ptr)
                if region is None:
                    continue
                base, size = region
                remaining = base + size - ptr
                if remaining < 8:
                    continue
                add_profile(
                    ptr,
                    min(remaining, 256),
                    f"stackptr_0x{sp + offset - start:08x}@snapshot_0x{snapshot_addr:08x}",
                )
        return profiles

    def _firmware_contains_any_bytes(self, needles: Iterable[bytes], max_scan_bytes: int = 4 * 1024 * 1024) -> bool:
        try:
            data = Path(self.firmware_path).read_bytes()[:max_scan_bytes].lower()
        except Exception:
            return False
        for needle in needles:
            if bytes(needle).lower() in data:
                return True
        return False

    @staticmethod
    def _parse_extra_stream_seed_env() -> List[bytes]:
        seeds: List[bytes] = []

        def add_seed(data: bytes) -> None:
            if data and data not in seeds:
                seeds.append(bytes(data))

        text = os.environ.get("LSGEMU_STREAM_EXTRA_SEEDS", "")
        for token in re.split(r"[\n;,]", text):
            token = token.strip()
            if not token:
                continue
            if token.lower().startswith("hex:"):
                try:
                    add_seed(bytes.fromhex(re.sub(r"[^0-9a-fA-F]", "", token[4:])))
                except ValueError:
                    continue
            else:
                add_seed(token.encode("utf-8", errors="ignore"))

        hex_text = os.environ.get("LSGEMU_STREAM_EXTRA_SEEDS_HEX", "")
        for token in re.split(r"[\n;,]", hex_text):
            cleaned = re.sub(r"[^0-9a-fA-F]", "", token)
            if cleaned and len(cleaned) % 2 == 0:
                try:
                    add_seed(bytes.fromhex(cleaned))
                except ValueError:
                    continue
        return seeds

    def _firmware_debug_download_seeds(self) -> List[bytes]:
        has_debug_or_download = self._firmware_contains_any_bytes((
            b"debug",
            b"boot-->",
            b"download",
            b"ethernet",
            b"md5",
            b"cannv",
        ))
        if not has_debug_or_download:
            return []
        seeds: List[bytes] = []

        def add(data: bytes) -> None:
            if data and data not in seeds:
                seeds.append(data)

        for command in (
            b"HELP",
            b"?",
            b"DEBUG",
            b"BOOT",
            b"BOOT-->",
            b"DUMP",
            b"MD5",
            b"CANNV",
            b"DOWNLOAD",
            b"CP/IP download",
            b"route: ethernet",
            b"GET / HTTP/1.0",
        ):
            for suffix in (b"\r", b"\n", b"\r\n", b"\x00"):
                add(command + suffix)
        add(b"DEBUG " + b"A" * 64 + b"\r\n")
        add(b"BOOT " + b"A" * 64 + b"\r\n")
        add(b"DOWNLOAD " + b"A" * 128 + b"\r\n")
        add(b"CP/IP download enable\r\n")
        add(b"route: ethernet\r\n")
        add(b"CANNV " + b"A" * 128 + b"\r\n")
        return seeds

    def _stream_seed_portfolio(self, max_seeds: int = 64) -> List[bytes]:
        seeds: List[bytes] = []

        def add(values: Iterable[int]):
            data = bytes(int(value) & 0xFF for value in values)
            if data and data not in seeds:
                seeds.append(data)

        def add_bytes(data: bytes):
            if data and data not in seeds:
                seeds.append(bytes(data))

        symbol_text = "\n".join(self._function_starts_by_name())
        normalized_symbol_text = _normalize_name(symbol_text)
        for seed in self._parse_extra_stream_seed_env():
            add_bytes(seed)
        for seed in self._firmware_debug_download_seeds():
            add_bytes(seed)
        if "gcode" in normalized_symbol_text or "marlin" in normalized_symbol_text:
            # Protocol-shaped seeds must reach the queue/parser before
            # single-byte branch tokens consume the short replay budget.
            for seed in (
                b"G0\n",
                b"G0 X0 Y0\n",
                b"G1 X1 Y1 E1\n",
                b"G28\n",
                b"M105\n",
                b"M104 S200\n",
                b"M114\n",
                b"N1 G0 X0*0\n",
            ):
                add_bytes(seed)
        if any(term in normalized_symbol_text for term in ("gps", "nmea", "gpgga", "gprmc")):
            for seed in (
                b"$GPRMC,000000.00,A,0000.0000,N,00000.0000,E,0.0,0.0,010100,,,A*68\r\n",
                b"$GPGGA,000000.00,0000.0000,N,00000.0000,E,1,08,1.0,0.0,M,0.0,M,,*47\r\n",
                b"$GPGSA,A,3,01,02,03,04,05,06,07,08,,,,,1.0,1.0,1.0*30\r\n",
                b"$GPGSV,1,1,04,01,45,000,40,02,45,090,40,03,45,180,40,04,45,270,40*7F\r\n",
            ):
                add_bytes(seed)
        if "Firmata" in symbol_text or "firmata" in symbol_text:
            # Prefer complete protocol transactions over single status bytes.
            # This reaches parser callbacks instead of only toggling the parser
            # state machine into "waiting for more data".
            def sysex(command: int, payload: Iterable[int] = ()) -> List[int]:
                return [0xF0, int(command) & 0x7F, *[int(item) & 0x7F for item in payload], 0xF7]

            for command in (0x6A, 0x6B, 0x6C, 0x6D, 0x6E, 0x71, 0x76, 0x77, 0x78, 0x79, 0x7A):
                add([0xF0, command, 0xF7])
                add([0xF0, command, 0x00, 0x00, 0xF7])
                add([0xF0, command, 0x02, 0x00, 0xF7])
            for pin in (0, 1, 2, 13):
                add([0xF4, pin, 0])
                add([0xF4, pin, 1])
                add([0xF5, pin, 0])
                add([0xF5, pin, 1])
            for command in (0x90, 0xC0, 0xD0, 0xE0):
                add([command, 0x00, 0x00])
                add([command, 0x01, 0x00])
            compound_sequences = [
                sysex(0x6B) + sysex(0x6A) + sysex(0x79),
                sysex(0x6D, [0x00, 0x00]) + sysex(0x6E) + sysex(0x71),
                sysex(0x76) + sysex(0x77) + sysex(0x78) + sysex(0x7A, [0x00, 0x00]),
                [0xF4, 0x00, 0x01, 0x90, 0x00, 0x01, 0xD0, 0x01, 0xF4, 0x00, 0x00],
                [0xF5, 0x00, 0x01, 0xE0, 0x00, 0x00, 0xC0, 0x01, 0x00],
            ]
            for sequence in compound_sequences:
                add(sequence)

        if any(term in normalized_symbol_text for term in ("msgreceive", "eventloop", "gnrc", "riot", "ccnl")):
            for seed in self._stream_message_type_seeds(max_types=64):
                add_bytes(seed)

        branch_token_seeds = self._stream_branch_token_seeds(max_tokens=64)
        for seed in branch_token_seeds:
            add_bytes(seed)

        for seed in (
            b";\n",
            b"G0\n",
            b"G0 X0 Y0\n",
            b"G1 X1 Y1 E1\n",
            b"G1 X1 ;comment\n",
            b"G1 X1\\\n",
            b"G2 X1 Y1 I1 J1\n",
            b"G3 X1 Y1 I1 J1\n",
            b"G28\n",
            b"G90\n",
            b"G91\n",
            b"M17\n",
            b"M18\n",
            b"M20\n",
            b"M23 test.g\n",
            b"M24\n",
            b"M28 test.g\n",
            b"M30 test.g\n",
            b"M31\n",
            b"M105\n",
            b"M104 S200\n",
            b"M106 S255\n",
            b"M107\n",
            b"M109 S200\n",
            b"M114\n",
            b"M115\n",
            b"M119\n",
            b"M140 S60\n",
            b"M190 S60\n",
            b"M500\n",
            b"M501\n",
            b"M502\n",
            b"M503\n",
            b"M112\n",
            b"<a/>",
            b"<root>1</root>",
            b"<?xml version=\"1.0\"?><root/>",
            b"<root><child attr=\"1\">text</child></root>",
            b"AT\r\n",
            b"AT+RST\r\n",
        ):
            add(seed)

        for value in (0x00, 0x01, 0x7F, 0x80, 0x90, 0xC0, 0xD0, 0xE0, 0xF0, 0xF4, 0xF5, 0xF7, 0xFF):
            add([value])
        for command in (0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0):
            add([command, 0x00, 0x00])
            add([command, 0x01, 0x00])
        for command in (0xF4, 0xF5):
            for pin in (0, 1, 2, 13):
                add([command, pin, 0])
                add([command, pin, 1])

        def gcode_checksum(line: bytes) -> bytes:
            checksum = 0
            for value in line:
                checksum ^= int(value) & 0xFF
            return line + b"*" + str(checksum).encode("ascii") + b"\n"

        for line in (
            b"N1 G0 X0",
            b"N2 M105",
            b"N3 G1 X1 Y1 E1",
        ):
            add(gcode_checksum(line))

        # Keep these here as a deduplicated fallback if a caller requests more
        # seeds than the high-priority protocol prefix above.
        for seed in (
            b"G0 X0 Y0\n",
            b"G1 X1 Y1 E1\n",
            b"G28\n",
            b"M105\n",
            b"M104 S200\n",
            b"M114\n",
            b"N1 G0 X0*0\n",
            b"<a/>",
            b"<root>1</root>",
            b"<?xml version=\"1.0\"?><root/>",
            b"<root><child attr=\"1\">text</child></root>",
            b"AT\r\n",
            b"AT+RST\r\n",
        ):
            add(seed)

        if max_seeds and max_seeds > 0:
            return seeds[:max_seeds]
        return seeds

    def _stream_message_type_seeds(self, max_types: int = 64) -> List[bytes]:
        """
        Extract 16-bit RTOS/event-loop message type constants.

        RIOT-like code often receives `msg_t`, then compares `msg.type`
        against constants loaded via MOVW before CMP. Byte-only branch tokens
        cannot hit those dispatch cases, so encode plausible 16-bit immediates
        as the first two stream bytes consumed by the msg_receive summary.
        """
        function_names = self._function_starts_by_name()
        terms = (
            "msg",
            "message",
            "eventloop",
            "event",
            "gnrc",
            "netapi",
            "ccnl",
            "ble",
            "hci",
            "rx",
            "receive",
            "recv",
            "dispatch",
        )
        reject_terms = (
            "printf",
            "print",
            "puts",
            "putc",
            "write",
            "mem",
            "aeabi",
            "initarray",
            "startup",
        )
        ordered_functions = sorted((int(addr), str(name)) for name, addr in function_names.items())
        function_ranges: List[Tuple[int, int, str]] = []
        for index, (addr, name) in enumerate(ordered_functions):
            end = ordered_functions[index + 1][0] if index + 1 < len(ordered_functions) else addr + 0x800
            normalized = _normalize_name(name)
            if not normalized:
                continue
            if any(term in normalized for term in reject_terms):
                continue
            if not any(term in normalized for term in terms):
                continue
            function_ranges.append((addr, end, normalized))
        if not function_ranges:
            return []

        candidates: Dict[int, Tuple[int, int]] = {}
        discovery_order = 0
        function_index = 0
        sorted_instructions = sorted(self.prepared.instruction_lookup.items())

        def mov_immediate_feeds_compare(index: int, insn: Dict[str, object]) -> bool:
            operands = str(insn.get("operands", "") or "")
            dst = operands.split(",", 1)[0].strip().lower()
            if not dst:
                return False
            for _next_addr, next_insn in sorted_instructions[index + 1 : index + 5]:
                next_mnemonic = str(next_insn.get("mnemonic", "") or "").upper().split(".", 1)[0]
                next_operands = str(next_insn.get("operands", "") or "").lower()
                if next_mnemonic in {"STR", "STRH", "STRB", "STM", "PUSH"} and dst in next_operands:
                    return False
                if next_mnemonic in {"CMP", "CMN", "TST", "TEQ"} and any(
                    part.strip() == dst for part in next_operands.split(",")
                ):
                    return True
            return False

        for insn_index, (insn_addr, insn) in enumerate(sorted_instructions):
            addr = int(insn_addr)
            while function_index < len(function_ranges) and addr >= function_ranges[function_index][1]:
                function_index += 1
            if function_index >= len(function_ranges):
                break
            start, end, function_name = function_ranges[function_index]
            if addr < start or addr >= end:
                continue
            mnemonic = str(insn.get("mnemonic", "") or "").upper().split(".", 1)[0]
            if mnemonic not in {"MOV", "MOVS", "MOVW", "CMP", "CMN", "SUB", "SUBS", "SUBW"}:
                continue
            if mnemonic in {"MOV", "MOVS", "MOVW"} and not mov_immediate_feeds_compare(insn_index, insn):
                continue
            operands = str(insn.get("operands", "") or "")
            for token in re.findall(r"#\s*(-?0x[0-9a-fA-F]+|-?\d+)", operands):
                try:
                    value = int(token, 0) & 0xFFFFFFFF
                except ValueError:
                    continue
                if not (0x0100 <= value <= 0x7FFF):
                    continue
                if "eventloop" in function_name:
                    priority = 0
                elif any(term in function_name for term in ("receive", "recv", "rx", "dispatch")):
                    priority = 1
                elif any(term in function_name for term in ("netapi", "getset", "sendreceive")):
                    priority = 3
                else:
                    priority = 2
                existing = candidates.get(value)
                if existing is None or (priority, discovery_order) < existing:
                    candidates[value] = (priority, discovery_order)
                discovery_order += 1

        values = [
            value
            for value, _rank in sorted(
                candidates.items(),
                key=lambda item: (
                    item[1][0],
                    1 if item[0] in {0x205, 0x1706} else 0,
                    item[1][1],
                ),
            )
        ]
        if max_types and max_types > 0:
            values = values[:max_types]

        seeds: List[bytes] = []
        for value in values:
            msg_type = int(value) & 0xFFFF
            # Include a small payload tail so consumers that dereference
            # msg.content.ptr do not immediately see an empty external object.
            seed = msg_type.to_bytes(2, "little") + bytes([
                0x00,
                0x01,
                ord("/"),
                ord("x"),
                0x00,
                0xFF,
            ])
            if seed not in seeds:
                seeds.append(seed)
        return seeds

    @staticmethod
    def _stream_seed_relevant_for_profile(profile: StreamInputProfile, seed: bytes) -> bool:
        if not seed:
            return False
        if profile.profile_kind == "gcode_command_queue":
            line = bytes(seed)
            for separator in (b"\n", b"\r"):
                if separator in line:
                    line = line.split(separator, 1)[0]
            line = line.strip()
            if not line:
                return False
            first = line[:1].upper()
            return first in {b"G", b"M", b"N", b"T"}
        return True

    def _parse_branch_compare_immediate(self, insn: Dict[str, object]) -> Optional[int]:
        mnemonic = str(insn.get("mnemonic", "") or "").upper().split(".", 1)[0]
        if mnemonic not in {"CMP", "CMN", "TST", "TEQ"}:
            return None
        operands = str(insn.get("operands", "") or "")
        for operand in reversed([part.strip() for part in operands.split(",") if part.strip()]):
            if not operand.startswith("#"):
                continue
            token = operand[1:].strip()
            if not token:
                continue
            token = token.split()[0]
            try:
                return int(token, 0) & 0xFFFFFFFF
            except ValueError:
                continue
        return None

    def _stream_branch_token_seeds(self, max_tokens: int = 64) -> List[bytes]:
        """
        Build protocol-token seeds from static branch guards near input/parser code.

        Many MCU command loops are byte dispatchers (`getc(); cmp #imm; beq ...`).
        Generic G-code/XML/Firmata seeds miss small menu protocols like 's', 't',
        'h'.  Extracting printable one-byte branch immediates is still generic and
        preserves real execution: it only changes stream bytes consumed by normal
        entry-derived reads.
        """
        function_names = self._function_starts_by_name()
        input_terms = (
            "main",
            "loop",
            "read",
            "getc",
            "available",
            "readable",
            "receive",
            "recv",
            "rx",
            "serial",
            "uart",
            "usart",
            "stream",
            "parse",
            "parser",
            "process",
            "command",
            "menu",
        )
        reject_terms = (
            "write",
            "putc",
            "print",
            "printf",
            "format",
            "baud",
            "init",
            "clock",
            "ticker",
            "timer",
            "time",
            "delay",
            "aeabi",
            "mem",
        )
        ordered_functions = sorted((int(addr), str(name)) for name, addr in function_names.items())
        function_ranges: List[Tuple[int, int, str]] = []
        for index, (addr, name) in enumerate(ordered_functions):
            end = ordered_functions[index + 1][0] if index + 1 < len(ordered_functions) else addr + 0x800
            normalized = _normalize_name(name)
            if not normalized:
                continue
            if any(term in normalized for term in reject_terms):
                continue
            categories = (
                self._semantic_entry_categories_for_name(name)
                if self.semantic_obligation_enabled
                else set()
            )
            if not (
                any(term in normalized for term in input_terms)
                or categories & {"stream_or_protocol_input", "protocol_callback", "rtos_or_task_entry"}
            ):
                continue
            function_ranges.append((addr, end, normalized))

        if not function_ranges:
            return []

        tokens: List[int] = []
        seen_tokens: Set[int] = set()
        function_index = 0
        sorted_instructions = sorted(self.prepared.instruction_lookup.items())
        for insn_addr, insn in sorted_instructions:
            addr = int(insn_addr)
            while function_index < len(function_ranges) and addr >= function_ranges[function_index][1]:
                function_index += 1
            if function_index >= len(function_ranges):
                break
            start, end, _name = function_ranges[function_index]
            if addr < start or addr >= end:
                continue
            immediate = self._parse_branch_compare_immediate(insn)
            if immediate is None or not (1 <= immediate <= 0xFF):
                continue
            value = int(immediate) & 0xFF
            if value in seen_tokens:
                continue
            # Prefer externally plausible command bytes: printable ASCII,
            # delimiters, and common binary command/status bytes.
            if not (
                0x20 <= value <= 0x7E
                or value in {0x00, 0x0A, 0x0D, 0x1B, 0x7F, 0x80, 0x90, 0xC0, 0xD0, 0xE0, 0xF0, 0xF4, 0xF5, 0xF7, 0xFF}
            ):
                continue
            seen_tokens.add(value)
            tokens.append(value)
            if max_tokens and len(tokens) >= max_tokens:
                break

        seeds: List[bytes] = []

        def append_seed(data: bytes) -> None:
            if data and data not in seeds:
                seeds.append(data)

        printable_tokens = [value for value in tokens if 0x20 <= value <= 0x7E]
        for value in tokens:
            byte = bytes([value])
            append_seed(byte)
            if 0x20 <= value <= 0x7E:
                append_seed(byte + b"\r")
                append_seed(byte + b"\n")
                append_seed(byte + b"\r\n")
        if printable_tokens:
            append_seed(bytes(printable_tokens[: min(len(printable_tokens), 32)]))
            append_seed(b"".join(bytes([value]) + b"\r" for value in printable_tokens[:16]))
            append_seed(b"".join(bytes([value]) + b"\n" for value in printable_tokens[:16]))
        return seeds

    def _select_stream_replay_contexts(
        self,
        max_contexts: int = 16,
        *,
        prefer_stream_summary_contexts: bool = False,
    ) -> List[object]:
        snapshots: List[object] = []
        context_source_counts: Counter[str] = Counter()
        seen_contexts: Set[Tuple[object, ...]] = set()

        def context_snapshot(context: object) -> Optional[object]:
            return self._interrupt_context_snapshot(context)

        def context_origin(context: object) -> str:
            if isinstance(context, PrefixReplaySnapshot):
                return str(getattr(context, "origin", "snapshot-entry") or "snapshot-entry")
            if isinstance(context, dict):
                return str(context.get("origin", "dict-snapshot") or "dict-snapshot")
            return "ordered"

        def context_identity(context: object) -> Tuple[object, ...]:
            snapshot = context_snapshot(context)
            if snapshot is None:
                snapshot = context
            prefix_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple()
            source_path_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple()
            context_evidence = EVIDENCE_E0
            next_branch_key: Tuple[int, int] = (
                int(getattr(snapshot, "address", 0) or 0),
                int(getattr(snapshot, "occurrence_index", 1) or 1),
            )
            if isinstance(context, PrefixReplaySnapshot):
                prefix_signature = tuple(getattr(context, "prefix_signature", tuple()) or tuple())
                source_path_signature = tuple(getattr(context, "source_path_signature", tuple()) or tuple())
                context_evidence = self._snapshot_entry_evidence_class(context)
                next_key = tuple(getattr(context, "next_branch_key", next_branch_key) or next_branch_key)
                if len(next_key) >= 2:
                    next_branch_key = (int(next_key[0]), int(next_key[1]))
            elif isinstance(context, dict):
                prefix_signature = tuple(context.get("prefix_signature", tuple()) or tuple())
                source_path_signature = tuple(context.get("source_path_signature", tuple()) or tuple())
                context_evidence = self._capture_evidence_class(
                    source_path_signature,
                    context.get("evidence_class"),
                )
            return (
                context_origin(context),
                context_evidence,
                int(getattr(snapshot, "address", 0) or 0),
                int(getattr(snapshot, "occurrence_index", 1) or 1),
                int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
                int(getattr(snapshot, "depth", 0) or 0),
                next_branch_key,
                prefix_signature,
                source_path_signature,
            )

        def add_context(context: object, source: str) -> None:
            snapshot = context_snapshot(context)
            if snapshot is None:
                return
            address = int(getattr(snapshot, "address", 0) or 0)
            if address <= 0:
                return
            identity = context_identity(context)
            if identity in seen_contexts:
                return
            seen_contexts.add(identity)
            snapshots.append(context)
            context_source_counts[str(source or context_origin(context))] += 1

        for snapshot in self._ordered_replay_snapshots(self.emulator):
            add_context(snapshot, "ordered")
        stream_summary_callsite_bbs_for_context = {
            int(bb_addr)
            for bb_addr, insn in getattr(self.prepared, "branch_instruction_by_bb", {}).items()
            if _is_direct_call_mnemonic(_normalize_mnemonic(insn.get("mnemonic", "")))
            for target_addr, _target_symbol in [self._direct_call_target_symbol(insn)]
            if (
                target_addr is not None
                and IntelligentEmulator._stream_input_summary_for_symbol(
                    str(getattr(self.prepared, "symbols_by_addr", {}).get(int(target_addr), ""))
                    or self._function_name_for_addr(int(target_addr))
                ) is not None
            )
        }
        for callsite_bb in sorted(stream_summary_callsite_bbs_for_context):
            try:
                snapshot = self.emulator.branch_snapshot_manager.get_snapshot(int(callsite_bb))
            except Exception:
                snapshot = None
            if snapshot is not None:
                add_context(snapshot, "stream_summary_callsite")
        for entries in getattr(self, "known_branch_root_snapshots", {}).values():
            if not isinstance(entries, dict):
                continue
            for entry in entries.values():
                add_context(entry, "branch_root")
        for entries in getattr(self, "direct_call_snapshots", {}).values():
            if not isinstance(entries, dict):
                continue
            for entry in entries.values():
                add_context(entry, "direct_call")
        for entries in getattr(self, "stream_summary_entry_snapshots", {}).values():
            if not isinstance(entries, dict):
                continue
            for entry in entries.values():
                add_context(entry, "stream_summary_entry")
        for entry in getattr(self, "reservoir_prefix_snapshots", {}).values():
            add_context(entry, "reservoir_prefix")
        if not snapshots:
            return []

        preferred_terms = (
            "loop",
            "main",
            "available",
            "processinput",
            "parse",
            "parser",
            "gcode",
            "queue",
            "serial",
            "usb",
            "cdc",
            "read",
        )
        high_preferred_terms = (
            "loop",
            "advance",
            "gcode",
            "queue",
            "parse",
            "parser",
            "process",
            "processnextcommand",
            "getserialcommands",
            "getavailablecommands",
            "availablecommands",
            "nextcommand",
            "read",
            "available",
            "getc",
            "receive",
            "recv",
            "rx",
        )
        input_consumer_terms = STREAM_INPUT_CONSUMER_TERMS
        output_context_terms = STREAM_OUTPUT_OR_CONFIG_CONTEXT_TERMS
        semantic_terms = (
            "stream_or_protocol_input",
            "protocol_callback",
            "callback_or_hook",
            "interrupt_or_vector_handler",
        )
        low_semantic_terms = (
            "libgcc_runtime_path",
            "libc_or_runtime_path",
            "startup_teardown_path",
            "error_or_fault_path",
        )
        low_value_terms = (
            "rcc",
            "clock",
            "clk",
            "begin",
            "enable",
            "disable",
            "deinit",
            "init",
            "startup",
            "mulsf",
            "muldf",
            "divsf",
            "divdf",
            "aeabi",
            "gnu",
            "format",
            "baud",
            "serialformat",
            "serialbaud",
        )
        semantic_frontiers = {
            int(bb)
            for bb in self.frontier_target_bb_list(max_targets=512)
            if self._semantic_categories_for_bb(int(bb)) & set(semantic_terms)
        }
        successor_map = self._effective_successor_map()
        semantic_frontier_predecessors = {
            int(pred)
            for pred, successors in successor_map.items()
            if any(int(successor) in semantic_frontiers for successor in successors)
        }
        stream_summary_bbs = {
            int(resolved)
            for address, symbol in getattr(self.prepared, "symbols_by_addr", {}).items()
            if IntelligentEmulator._stream_input_summary_for_symbol(str(symbol)) is not None
            for resolved in [self.prepared.resolve_basic_block(int(address) & ~1)]
            if resolved is not None
        }
        stream_summary_predecessors = {
            int(pred)
            for pred, successors in successor_map.items()
            if any(int(successor) in stream_summary_bbs for successor in successors)
        }
        stream_summary_callsite_bbs = {
            int(bb_addr)
            for bb_addr, insn in getattr(self.prepared, "branch_instruction_by_bb", {}).items()
            if _is_direct_call_mnemonic(_normalize_mnemonic(insn.get("mnemonic", "")))
            for target_addr, _target_symbol in [self._direct_call_target_symbol(insn)]
            if target_addr is not None and int(target_addr) in stream_summary_bbs
        }
        stream_summary_callsite_contexts: List[PrefixReplaySnapshot] = []
        seen_stream_callsite_contexts: Set[Tuple[object, ...]] = set()

        def add_stream_summary_context(entry: PrefixReplaySnapshot) -> None:
            identity = self._snapshot_entry_identity(entry)
            if identity in seen_stream_callsite_contexts:
                return
            seen_stream_callsite_contexts.add(identity)
            stream_summary_callsite_contexts.append(entry)

        for callsite_bb in sorted(stream_summary_callsite_bbs):
            for entry in self._direct_call_snapshot_entries(int(callsite_bb)):
                add_stream_summary_context(entry)
        for summary_bb in sorted(stream_summary_bbs):
            for entry in self._stream_summary_entry_snapshot_entries(int(summary_bb)):
                add_stream_summary_context(entry)
        raw_snapshots_total = len(snapshots)
        summary_fast_path_used = False
        summary_fast_path_candidates = 0
        if prefer_stream_summary_contexts and stream_summary_callsite_contexts:
            try:
                summary_fast_path_limit = max(
                    int(max_contexts or 16),
                    int(os.environ.get("LSGEMU_STREAM_SUMMARY_CONTEXT_FAST_POOL", "24") or 24),
                )
            except ValueError:
                summary_fast_path_limit = max(int(max_contexts or 16), 24)
            fast_candidates: List[object] = []
            seen_fast_candidates: Set[Tuple[object, ...]] = set()

            def add_fast_candidate(context: object) -> None:
                snapshot = context_snapshot(context)
                if snapshot is None:
                    return
                address = int(getattr(snapshot, "address", 0) or 0)
                bb_addr = self.prepared.resolve_basic_block(address)
                bb_int = int(bb_addr if bb_addr is not None else address)
                origin = context_origin(context)
                if (
                    bb_int not in stream_summary_bbs
                    and bb_int not in stream_summary_predecessors
                    and bb_int not in stream_summary_callsite_bbs
                    and origin not in {"stream_summary_entry", "stream_summary_callsite"}
                ):
                    return
                identity = context_identity(context)
                if identity in seen_fast_candidates:
                    return
                seen_fast_candidates.add(identity)
                fast_candidates.append(context)

            for context in stream_summary_callsite_contexts:
                add_fast_candidate(context)
            for context in snapshots:
                add_fast_candidate(context)
            summary_fast_path_candidates = len(fast_candidates)
            if fast_candidates:
                snapshots = fast_candidates[:summary_fast_path_limit]
                summary_fast_path_used = True
        stream_reachable_score_enabled = (
            os.environ.get("LSGEMU_STREAM_CONTEXT_STREAM_REACHABLE_SCORE", "1").strip().lower()
            not in {"", "0", "false", "no", "off"}
        )
        stream_summary_reachable_cache: Dict[int, bool] = {}

        def reaches_stream_summary(bb_addr: int, max_depth: int = 12, max_nodes: int = 512) -> bool:
            bb_int = int(bb_addr)
            if not stream_summary_bbs:
                return False
            cached = stream_summary_reachable_cache.get(bb_int)
            if cached is not None:
                return cached
            if bb_int in stream_summary_bbs or bb_int in stream_summary_predecessors:
                stream_summary_reachable_cache[bb_int] = True
                return True
            if bb_int in stream_summary_callsite_bbs:
                stream_summary_reachable_cache[bb_int] = True
                return True
            if not stream_reachable_score_enabled:
                stream_summary_reachable_cache[bb_int] = False
                return False
            queue = deque([(bb_int, 0)])
            seen = {bb_int}
            visited = 0
            while queue and visited < max_nodes:
                current, depth = queue.popleft()
                visited += 1
                if current in stream_summary_bbs:
                    stream_summary_reachable_cache[bb_int] = True
                    return True
                if depth >= max_depth:
                    continue
                for successor in successor_map.get(current, set()):
                    succ_int = int(successor)
                    if succ_int in seen:
                        continue
                    if succ_int in stream_summary_bbs:
                        stream_summary_reachable_cache[bb_int] = True
                        return True
                    seen.add(succ_int)
                    queue.append((succ_int, depth + 1))
            stream_summary_reachable_cache[bb_int] = False
            return False

        def snapshot_context_features(snapshot: object) -> Dict[str, object]:
            raw_context = snapshot
            resolved_snapshot = context_snapshot(snapshot)
            if resolved_snapshot is not None:
                snapshot = resolved_snapshot
            address = int(getattr(snapshot, "address", 0) or 0)
            bb_addr = self.prepared.resolve_basic_block(address)
            bb_int = int(bb_addr) if bb_addr is not None else address
            name = _normalize_name(self._function_name_for_addr(address))
            categories = self._semantic_categories_for_bb(bb_int)
            category_priority = self._semantic_category_priority(categories)
            init_context = 1 if any(
                term in name
                for term in (
                    "constructor",
                    "global",
                    "subi",
                    "libcinitarray",
                    "systeminit",
                    "startup",
                    "initarray",
                )
            ) or re.search(r"c[12]e", name) is not None else 0
            high_preferred = 1 if any(term in name for term in high_preferred_terms) else 0
            input_consumer = 1 if any(term in name for term in input_consumer_terms) else 0
            output_context = 1 if any(term in name for term in output_context_terms) else 0
            preferred = 1 if any(term in name for term in preferred_terms) else 0
            low_value = 1 if any(term in name for term in low_value_terms) else 0
            low_semantic = 1 if categories & set(low_semantic_terms) else 0
            direct_semantic = 1 if categories & set(semantic_terms) else 0
            frontier_adjacent = 1 if bb_int in semantic_frontiers or bb_int in semantic_frontier_predecessors else 0
            stream_summary_here = 1 if bb_int in stream_summary_bbs else 0
            stream_summary_adjacent = 1 if bb_int in stream_summary_predecessors else 0
            stream_summary_callsite = 1 if bb_int in stream_summary_callsite_bbs else 0
            stream_summary_reachable = 1 if reaches_stream_summary(bb_int) else 0
            covered_here = 1 if bb_int in self.global_coverage else 0
            return {
                "address": address,
                "bb_addr": bb_int,
                "name": name,
                "categories": categories,
                "category_priority": category_priority,
                "init_context": init_context,
                "high_preferred": high_preferred,
                "input_consumer": input_consumer,
                "output_context": output_context,
                "preferred": preferred,
                "low_value": low_value,
                "low_semantic": low_semantic,
                "direct_semantic": direct_semantic,
                "frontier_adjacent": frontier_adjacent,
                "stream_summary_here": stream_summary_here,
                "stream_summary_adjacent": stream_summary_adjacent,
                "stream_summary_callsite": stream_summary_callsite,
                "stream_summary_reachable": stream_summary_reachable,
                "covered_here": covered_here,
                "depth": int(getattr(raw_context, "branch_depth", getattr(snapshot, "depth", 0)) or 0),
                "capture_order": int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
                "origin": context_origin(raw_context),
            }

        def cheap_score(snapshot: object) -> Tuple[int, int, int, int, int, int]:
            features = snapshot_context_features(snapshot)
            return (
                int(features["stream_summary_here"]),
                int(features["stream_summary_adjacent"]),
                int(features["stream_summary_callsite"]),
                int(features["stream_summary_reachable"]),
                int(features["frontier_adjacent"]),
                int(features["direct_semantic"]),
                int(features["input_consumer"]),
                int(features["high_preferred"]),
                int(features["preferred"]),
                int(features["category_priority"]),
                -int(features["low_semantic"]),
                -int(features["init_context"]),
                -int(features["output_context"]),
                -int(features["low_value"]),
                int(features["depth"]),
                int(features["capture_order"]),
            )

        if summary_fast_path_used:
            default_prescreen_limit = max(int(max_contexts or 16), min(32, int(max_contexts or 16) * 2))
        else:
            default_prescreen_limit = max(64, int(max_contexts or 16) * 8)
        prescreen_limit = max(
            int(max_contexts or 16),
            int(os.environ.get("LSGEMU_STREAM_CONTEXT_PRESCREEN_LIMIT", str(default_prescreen_limit)) or default_prescreen_limit),
        )
        sorted_prescreen = sorted(snapshots, key=cheap_score, reverse=True)
        diversified: List[object] = []
        seen_bb_pass1: Set[int] = set()
        for snapshot in sorted_prescreen:
            resolved_snapshot = context_snapshot(snapshot) or snapshot
            bb_addr = self.prepared.resolve_basic_block(int(getattr(resolved_snapshot, "address", 0) or 0))
            bb_key = int(bb_addr if bb_addr is not None else int(getattr(resolved_snapshot, "address", 0) or 0))
            if bb_key in seen_bb_pass1:
                continue
            seen_bb_pass1.add(bb_key)
            diversified.append(snapshot)
            if len(diversified) >= prescreen_limit:
                break
        if len(diversified) < prescreen_limit:
            counts_by_bb: Counter[int] = Counter()
            for snapshot in diversified:
                resolved_snapshot = context_snapshot(snapshot) or snapshot
                bb_addr = self.prepared.resolve_basic_block(int(getattr(resolved_snapshot, "address", 0) or 0))
                bb_key = int(bb_addr if bb_addr is not None else int(getattr(resolved_snapshot, "address", 0) or 0))
                counts_by_bb[bb_key] += 1
            try:
                per_bb_cap = max(1, int(os.environ.get("LSGEMU_STREAM_CONTEXT_VARIANTS_PER_BB", "2")))
            except ValueError:
                per_bb_cap = 2
            existing_ids = {
                (
                    int(getattr(context_snapshot(snapshot) or snapshot, "address", 0) or 0),
                    int(getattr(context_snapshot(snapshot) or snapshot, "occurrence_index", 1) or 1),
                    int(getattr(context_snapshot(snapshot) or snapshot, "capture_order", getattr(context_snapshot(snapshot) or snapshot, "order", 0)) or 0),
                )
                for snapshot in diversified
            }
            for snapshot in sorted_prescreen:
                resolved_snapshot = context_snapshot(snapshot) or snapshot
                identity = (
                    int(getattr(resolved_snapshot, "address", 0) or 0),
                    int(getattr(resolved_snapshot, "occurrence_index", 1) or 1),
                    int(getattr(resolved_snapshot, "capture_order", getattr(resolved_snapshot, "order", 0)) or 0),
                )
                if identity in existing_ids:
                    continue
                bb_addr = self.prepared.resolve_basic_block(int(getattr(resolved_snapshot, "address", 0) or 0))
                bb_key = int(bb_addr if bb_addr is not None else int(getattr(resolved_snapshot, "address", 0) or 0))
                if counts_by_bb[bb_key] >= per_bb_cap:
                    continue
                existing_ids.add(identity)
                counts_by_bb[bb_key] += 1
                diversified.append(snapshot)
                if len(diversified) >= prescreen_limit:
                    break
        snapshots = diversified[:prescreen_limit]
        reachable_cache: Dict[int, Set[int]] = {}
        enable_reachable_score = str(
            os.environ.get("LSGEMU_STREAM_CONTEXT_ENABLE_REACHABLE_SCORE", "0")
        ).strip().lower() in {"1", "true", "yes", "on"}

        def score(snapshot: object) -> Tuple[int, int, int, int, int, int, int, int]:
            features = snapshot_context_features(snapshot)
            bb_addr = features["bb_addr"]
            downstream_semantic = 0
            downstream_size = 0
            if enable_reachable_score and bb_addr is not None:
                reachable = self._static_reachable_from_cached(
                    int(bb_addr),
                    successor_map,
                    reachable_cache,
                )
                downstream_size = min(len(reachable), 100000)
                for candidate_bb in reachable:
                    categories = self._semantic_categories_for_bb(int(candidate_bb))
                    if any(term in categories for term in semantic_terms):
                        downstream_semantic = 1
                        break
            return (
                int(features["stream_summary_here"]),
                int(features["stream_summary_adjacent"]),
                int(features["stream_summary_callsite"]),
                int(features["stream_summary_reachable"]),
                int(features["frontier_adjacent"]),
                int(features["direct_semantic"]),
                int(features["input_consumer"]),
                int(features["high_preferred"]),
                downstream_semantic,
                int(features["preferred"]),
                int(features["category_priority"]),
                -int(features["low_semantic"]),
                -int(features["init_context"]),
                -int(features["output_context"]),
                -int(features["low_value"]),
                downstream_size,
                int(features["depth"]),
                int(features["capture_order"]),
            )

        ordered = sorted(snapshots, key=score, reverse=True)
        selected: List[object] = []
        seen = set()
        seen_addresses: Set[int] = set()
        try:
            selection_limit = max(
                int(max_contexts or 16),
                int(os.environ.get("LSGEMU_STREAM_CONTEXT_CANDIDATE_POOL", "64") or 64),
            )
        except ValueError:
            selection_limit = max(int(max_contexts or 16), 64)

        def append_selected(snapshot: object, *, require_new_address: bool) -> bool:
            resolved_snapshot = context_snapshot(snapshot) or snapshot
            identity = (
                int(getattr(resolved_snapshot, "address", 0) or 0),
                int(getattr(resolved_snapshot, "occurrence_index", 1) or 1),
                int(getattr(resolved_snapshot, "capture_order", getattr(resolved_snapshot, "order", 0)) or 0),
                context_identity(snapshot),
            )
            if identity in seen:
                return False
            address = int(getattr(resolved_snapshot, "address", 0) or 0)
            if require_new_address and address in seen_addresses:
                return False
            seen.add(identity)
            seen_addresses.add(address)
            selected.append(snapshot)
            return True

        def feature_bool(snapshot: object, key: str) -> bool:
            return bool(snapshot_context_features(snapshot).get(key, 0))

        def feature_name(snapshot: object) -> str:
            return str(snapshot_context_features(snapshot).get("name", ""))

        def has_name_term(snapshot: object, terms: Iterable[str]) -> bool:
            name = feature_name(snapshot)
            return any(term in name for term in terms)

        def bad_stream_context(snapshot: object) -> bool:
            features = snapshot_context_features(snapshot)
            name = str(features.get("name", ""))
            return bool(
                int(features.get("low_semantic", 0) or 0)
                or int(features.get("init_context", 0) or 0)
                or int(features.get("output_context", 0) or 0)
                or int(features.get("low_value", 0) or 0)
                or any(term in name for term in STREAM_RUNTIME_NONCONSUMER_CONTEXT_TERMS)
            )

        def useful_stream_context(snapshot: object) -> bool:
            features = snapshot_context_features(snapshot)
            if bad_stream_context(snapshot):
                return False
            categories = set(features.get("categories", set()) or set())
            name = str(features.get("name", ""))
            strict_reader_terms = (
                "read",
                "readable",
                "available",
                "getc",
                "receive",
                "recv",
                "rx",
                "parse",
                "parser",
                "xmlparse",
                "processinput",
                "processparsedcommand",
                "processnextcommand",
                "getserialcommands",
                "getavailablecommands",
                "availablecommands",
                "nextcommand",
            )
            steady_entry_terms = ("loop", "main", "advance")
            return bool(
                categories & {"stream_or_protocol_input", "protocol_callback", "callback_or_hook"}
                or any(term in name for term in strict_reader_terms)
                or any(term in name for term in steady_entry_terms)
            )

        def add_bucket(predicate, quota: int) -> None:
            if selection_limit and selection_limit > 0 and len(selected) >= selection_limit:
                return
            added = 0
            quota = max(0, int(quota))
            if quota <= 0:
                return
            for snapshot in ordered:
                if selection_limit and selection_limit > 0 and len(selected) >= selection_limit:
                    break
                if added >= quota:
                    break
                if not predicate(snapshot):
                    continue
                if append_selected(snapshot, require_new_address=True):
                    added += 1
            if added >= quota:
                return
            for snapshot in ordered:
                if selection_limit and selection_limit > 0 and len(selected) >= selection_limit:
                    break
                if added >= quota:
                    break
                if not predicate(snapshot):
                    continue
                if append_selected(snapshot, require_new_address=False):
                    added += 1

        parser_or_reader_terms = (
            "parse",
            "parser",
            "processinput",
            "processparsedcommand",
            "processnextcommand",
            "getserialcommands",
            "getavailablecommands",
            "availablecommands",
            "nextcommand",
            "read",
            "available",
            "getc",
            "receive",
            "recv",
            "rx",
        )
        steady_loop_terms = (
            "loop",
            "main",
            "advance",
            "process",
            "queue",
            "serial",
            "usb",
            "cdc",
        )
        ordered_before_filter = ordered
        hard_filtered_ordered = [snapshot for snapshot in ordered if useful_stream_context(snapshot)]
        hard_filter_min_contexts = max(
            int(max_contexts or 16),
            int(os.environ.get("LSGEMU_STREAM_CONTEXT_HARD_FILTER_MIN", "16") or 16),
        )
        hard_filter_used = bool(hard_filtered_ordered) and len(hard_filtered_ordered) >= hard_filter_min_contexts
        allow_selector_fallback = (
            os.environ.get("LSGEMU_STREAM_CONTEXT_FILL_FALLBACK", "1").strip().lower()
            not in {"", "0", "false", "no", "off"}
        )
        fallback_ordered = [
            snapshot for snapshot in ordered_before_filter
            if not bad_stream_context(snapshot)
        ]
        if hard_filter_used:
            ordered = hard_filtered_ordered
        elif (
            not allow_selector_fallback
            and os.environ.get("LSGEMU_STREAM_ALLOW_FALLBACK_CONTEXTS", "").strip().lower()
            not in {"1", "true", "yes", "on"}
        ):
            self._last_stream_context_filter_stats = {
                "snapshots_total": len(snapshots),
                "raw_snapshots_total": raw_snapshots_total,
                "snapshot_sources": dict(context_source_counts),
                "stream_summary_bbs": len(stream_summary_bbs),
                "stream_summary_predecessors": len(stream_summary_predecessors),
                "stream_summary_callsite_bbs": len(stream_summary_callsite_bbs),
                "stream_summary_entry_snapshot_addresses": len(self.stream_summary_entry_snapshots),
                "stream_summary_entry_snapshot_variants": sum(len(entries) for entries in self.stream_summary_entry_snapshots.values()),
                "ordered_before_filter": len(ordered_before_filter),
                "summary_fast_path_used": summary_fast_path_used,
                "summary_fast_path_candidates": summary_fast_path_candidates,
                "bad_contexts_before_filter": sum(1 for snapshot in ordered_before_filter if bad_stream_context(snapshot)),
                "useful_contexts_before_filter": 0,
                "hard_filter_min_contexts": hard_filter_min_contexts,
                "fallback_contexts_before_filter": len(fallback_ordered),
                "fallback_context_fill_enabled": allow_selector_fallback,
                "fallback_context_fill_used": False,
                "hard_filter_used": False,
                "skipped_no_useful_context": True,
            }
            return []
        else:
            ordered = list(hard_filtered_ordered)
            hard_filtered_ids = {id(snapshot) for snapshot in hard_filtered_ordered}
            ordered.extend(
                snapshot
                for snapshot in (fallback_ordered or ordered_before_filter)
                if id(snapshot) not in hard_filtered_ids
            )
        self._last_stream_context_filter_stats = {
            "snapshots_total": len(snapshots),
            "raw_snapshots_total": raw_snapshots_total,
            "snapshot_sources": dict(context_source_counts),
            "stream_summary_bbs": len(stream_summary_bbs),
            "stream_summary_predecessors": len(stream_summary_predecessors),
            "stream_summary_callsite_bbs": len(stream_summary_callsite_bbs),
            "stream_summary_entry_snapshot_addresses": len(self.stream_summary_entry_snapshots),
            "stream_summary_entry_snapshot_variants": sum(len(entries) for entries in self.stream_summary_entry_snapshots.values()),
            "ordered_before_filter": len(ordered_before_filter),
            "summary_fast_path_used": summary_fast_path_used,
            "summary_fast_path_candidates": summary_fast_path_candidates,
            "bad_contexts_before_filter": sum(1 for snapshot in ordered_before_filter if bad_stream_context(snapshot)),
            "useful_contexts_before_filter": len(hard_filtered_ordered),
            "hard_filter_min_contexts": hard_filter_min_contexts,
            "fallback_contexts_before_filter": len(fallback_ordered),
            "fallback_context_fill_enabled": allow_selector_fallback,
            "fallback_context_fill_used": bool((not hard_filter_used) and allow_selector_fallback),
            "hard_filter_used": hard_filter_used,
            "skipped_no_useful_context": False,
        }
        # Keep the pool diverse by semantic role. A pure global sort can spend
        # the whole stream budget on initialization/clock/output states before
        # late-discovered parser/read snapshots get a replay chance.
        add_bucket(
            lambda snapshot: (
                (
                    feature_bool(snapshot, "stream_summary_here")
                    or feature_bool(snapshot, "stream_summary_adjacent")
                    or feature_bool(snapshot, "stream_summary_callsite")
                    or feature_bool(snapshot, "stream_summary_reachable")
                )
                and not bad_stream_context(snapshot)
            ),
            max(8, selection_limit // 2),
        )
        add_bucket(
            lambda snapshot: has_name_term(snapshot, parser_or_reader_terms) and not bad_stream_context(snapshot),
            max(4, selection_limit // 3),
        )
        add_bucket(
            lambda snapshot: (
                feature_bool(snapshot, "frontier_adjacent")
                and (feature_bool(snapshot, "direct_semantic") or feature_bool(snapshot, "input_consumer"))
                and not bad_stream_context(snapshot)
            ),
            max(4, selection_limit // 4),
        )
        add_bucket(
            lambda snapshot: (
                has_name_term(snapshot, steady_loop_terms)
                and (feature_bool(snapshot, "input_consumer") or feature_bool(snapshot, "direct_semantic"))
                and not bad_stream_context(snapshot)
            ),
            max(4, selection_limit // 4),
        )
        for snapshot in ordered:
            if selection_limit and selection_limit > 0 and len(selected) >= selection_limit:
                break
            features = snapshot_context_features(snapshot)
            if bad_stream_context(snapshot) and len(selected) >= max(4, selection_limit // 2):
                continue
            if (
                int(features.get("init_context", 0) or 0)
                and len(selected) >= max(4, selection_limit // 4)
            ):
                continue
            append_selected(snapshot, require_new_address=True)
        if not (selection_limit and selection_limit > 0 and len(selected) >= selection_limit):
            for snapshot in ordered:
                append_selected(snapshot, require_new_address=False)
                if selection_limit and selection_limit > 0 and len(selected) >= selection_limit:
                    break
        if (
            allow_selector_fallback
            and selection_limit
            and selection_limit > 0
            and len(selected) < selection_limit
        ):
            for snapshot in fallback_ordered:
                append_selected(snapshot, require_new_address=True)
                if len(selected) >= selection_limit:
                    break
        if (
            allow_selector_fallback
            and selection_limit
            and selection_limit > 0
            and len(selected) < selection_limit
        ):
            for snapshot in fallback_ordered:
                append_selected(snapshot, require_new_address=False)
                if len(selected) >= selection_limit:
                    break
        return selected

    def _write_stream_seed_to_emulator(self, emulator: IntelligentEmulator, profile: StreamInputProfile, seed: bytes) -> bool:
        emulator.stream_input_injected_ranges = []

        def record_injected_range(address: int, payload: bytes, source: str) -> None:
            if not payload:
                return
            ranges = getattr(emulator, "stream_input_injected_ranges", None)
            if ranges is None:
                emulator.stream_input_injected_ranges = []
                ranges = emulator.stream_input_injected_ranges
            if len(ranges) >= 64:
                return
            ranges.append({
                "address": int(address) & 0xFFFFFFFF,
                "size": int(len(payload)),
                "seed_hex": bytes(seed).hex(),
                "payload_hex_preview": bytes(payload[:64]).hex(),
                "source": str(source or profile.profile_kind),
                "profile_kind": str(profile.profile_kind),
                "object_symbol": str(profile.object_symbol),
            })

        if not seed:
            return False
        if profile.profile_kind == "stream_api_summary":
            return True
        capacity = max(2, int(profile.capacity))
        data = bytes(seed[: max(1, capacity - 1)])
        if profile.profile_kind == "usb_cdc_flat_ring":
            buffer_addr = int(profile.absolute_buffer_addr or profile.object_addr or 0)
            head_addr = int(profile.absolute_head_addr or 0)
            tail_addr = int(profile.absolute_tail_addr or 0)
            if not buffer_addr or not head_addr or not tail_addr:
                return False
            try:
                emulator.uc.mem_write(buffer_addr, data)
                emulator.uc.mem_write(head_addr, len(data).to_bytes(4, "little"))
                emulator.uc.mem_write(tail_addr, (0).to_bytes(4, "little"))
                record_injected_range(buffer_addr, data, "usb_cdc_flat_ring")
                return True
            except Exception:
                return False

        if profile.profile_kind == "gcode_command_queue":
            buffer_addr = int(profile.absolute_buffer_addr or 0)
            index_w_addr = int(profile.absolute_head_addr or 0)
            index_r_addr = int(profile.absolute_tail_addr or 0)
            length_addr = int(profile.absolute_length_addr or 0)
            if not buffer_addr:
                return False
            line = data
            if b"\n" in line:
                line = line.split(b"\n", 1)[0]
            if b"\r" in line:
                line = line.split(b"\r", 1)[0]
            line = line[: max(1, capacity - 1)]
            if not line:
                return False
            try:
                slot_size = max(96, int(capacity))
                emulator.uc.mem_write(buffer_addr, line + b"\x00")
                if index_r_addr:
                    emulator.uc.mem_write(index_r_addr, (0).to_bytes(1, "little"))
                if index_w_addr:
                    emulator.uc.mem_write(index_w_addr, (1).to_bytes(1, "little"))
                if not length_addr and index_r_addr and index_r_addr > 0:
                    # Fallback for stripped Marlin-like queues where length is
                    # immediately before index_r. Prefer a real symbol when it
                    # exists because these fields are byte-addressed.
                    length_addr = index_r_addr - 1
                if length_addr:
                    emulator.uc.mem_write(length_addr, (1).to_bytes(1, "little"))
                record_injected_range(buffer_addr, line + b"\x00", "gcode_command_queue")
                return True
            except Exception:
                return False

        if profile.profile_kind in {
            "generic_global_input_buffer",
            "snapshot_register_pointer_buffer",
            "observed_memory_read_buffer",
        }:
            buffer_addr = int(profile.absolute_buffer_addr or profile.object_addr or 0)
            if profile.profile_kind == "generic_global_input_buffer" and not (0x20000000 <= buffer_addr < 0x40000000):
                return False
            try:
                payload = data[: max(1, min(len(data), int(profile.capacity)))]
                if profile.profile_kind in {"snapshot_register_pointer_buffer", "observed_memory_read_buffer"} and not emulator._ensure_memory_mapped(
                    buffer_addr,
                    max(1, len(payload) + 1),
                ):
                    return False
                emulator.uc.mem_write(buffer_addr, payload)
                if len(payload) < int(profile.capacity):
                    emulator.uc.mem_write(buffer_addr + len(payload), b"\x00")
                record_injected_range(buffer_addr, payload, profile.profile_kind)
                return True
            except Exception:
                return False

        object_addr = int(profile.object_addr)
        if profile.profile_kind == "hardware_serial_nested_ring":
            try:
                usart_dev = int.from_bytes(
                    emulator.uc.mem_read(object_addr + int(profile.buffer_pointer_offset), 4),
                    "little",
                ) & 0xFFFFFFFF
                if not (0x20000000 <= usart_dev < 0x40000000):
                    usart_dev = int(profile.auxiliary_addr or 0)
                    if not (0x20000000 <= usart_dev < 0x40000000):
                        return False
                    emulator.uc.mem_write(
                        object_addr + int(profile.buffer_pointer_offset),
                        int(usart_dev).to_bytes(4, "little"),
                    )
                ring_ptr = int.from_bytes(emulator.uc.mem_read(usart_dev + 4, 4), "little") & 0xFFFFFFFF
                if not (0x20000000 <= ring_ptr < 0x40000000):
                    ring_ptr = int(profile.auxiliary_buffer_addr or 0)
                    if not (0x20000000 <= ring_ptr < 0x40000000):
                        return False
                    emulator.uc.mem_write(usart_dev + 4, int(ring_ptr).to_bytes(4, "little"))
                buffer_ptr = int.from_bytes(emulator.uc.mem_read(ring_ptr, 4), "little") & 0xFFFFFFFF
                if not (0x20000000 <= buffer_ptr < 0x40000000):
                    # libmaple-style usart_init stores the RX byte array at
                    # usart_dev + 0x10 and the ring metadata in *_rb.
                    buffer_ptr = usart_dev + 16
                    emulator.uc.mem_write(ring_ptr, int(buffer_ptr).to_bytes(4, "little"))
                    try:
                        emulator.uc.mem_write(ring_ptr + 8, (max(1, int(profile.capacity) - 1)).to_bytes(2, "little"))
                    except Exception:
                        pass
                try:
                    max_index = int.from_bytes(emulator.uc.mem_read(ring_ptr + 8, 2), "little")
                    capacity = max(2, min(256, int(max_index) + 1))
                    data = bytes(seed[: max(1, capacity - 1)])
                except Exception:
                    pass
                if not (0x20000000 <= buffer_ptr < 0x40000000):
                    return False
                emulator.uc.mem_write(buffer_ptr, data)
                emulator.uc.mem_write(ring_ptr + int(profile.tail_offset), (0).to_bytes(2, "little"))
                emulator.uc.mem_write(ring_ptr + int(profile.head_offset), len(data).to_bytes(2, "little"))
                record_injected_range(buffer_ptr, data, "hardware_serial_nested_ring")
                return True
            except Exception:
                return False

        try:
            buffer_ptr_bytes = emulator.uc.mem_read(object_addr + int(profile.buffer_pointer_offset), 4)
            buffer_ptr = int.from_bytes(buffer_ptr_bytes, "little") & 0xFFFFFFFF
        except Exception:
            buffer_ptr = 0
        if not (0x20000000 <= buffer_ptr < 0x40000000):
            if profile.inline_buffer_offset is None:
                return False
            buffer_ptr = object_addr + int(profile.inline_buffer_offset)
            try:
                emulator.uc.mem_write(
                    object_addr + int(profile.buffer_pointer_offset),
                    int(buffer_ptr).to_bytes(4, "little"),
                )
            except Exception:
                return False
        try:
            emulator.uc.mem_write(buffer_ptr, data)
            emulator.uc.mem_write(object_addr + int(profile.head_offset), len(data).to_bytes(2, "little"))
            emulator.uc.mem_write(object_addr + int(profile.tail_offset), (0).to_bytes(2, "little"))
            record_injected_range(buffer_ptr, data, profile.profile_kind)
            return True
        except Exception:
            return False

    def run_stream_input_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        max_profiles: int = 8,
        max_contexts: int = 16,
        max_seeds: int = 64,
        max_tasks: int = 256,
        max_instructions: int = 120000,
        replay_timeout: int = 1_000_000,
        no_new_bb_limit: int = 8192,
        phase_name: str = "stream_input_replay",
        prefer_stream_summary_contexts: bool = False,
    ) -> Set[int]:
        """
        Replay protocol/input bytes from real entry-derived states.

        Unlike cold function harnessing, this preserves the initialized memory
        state and only mutates the modeled external input channel. It is the
        methodical fix for callback/parser paths whose entry condition is
        "data arrives on a stream", not "flip one already-reached branch".
        """
        start_time = time.time()
        profiles = self.discover_stream_input_profiles(max_profiles=max_profiles)
        normalized_symbol_text = _normalize_name("\n".join(self._function_starts_by_name()))
        message_replay_mode = any(
            term in normalized_symbol_text
            for term in ("msgreceive", "eventloop", "gnrc", "riot", "ccnl")
        )
        if message_replay_mode:
            profiles = sorted(
                profiles,
                key=lambda profile: (
                    0 if profile.profile_kind == "stream_api_summary" else 1,
                    2 if profile.profile_kind == "generic_global_input_buffer" else 1,
                    profile.object_symbol,
                ),
            )
        contexts = self._select_stream_replay_contexts(
            max_contexts=max_contexts,
            prefer_stream_summary_contexts=prefer_stream_summary_contexts,
        )
        successor_map = self._effective_successor_map()
        stream_summary_bbs = {
            int(resolved)
            for address, symbol in getattr(self.prepared, "symbols_by_addr", {}).items()
            if IntelligentEmulator._stream_input_summary_for_symbol(str(symbol)) is not None
            for resolved in [self.prepared.resolve_basic_block(int(address) & ~1)]
            if resolved is not None
        }
        stream_summary_predecessors = {
            int(pred)
            for pred, successors in successor_map.items()
            if any(int(successor) in stream_summary_bbs for successor in successors)
        }
        stream_summary_callsite_bbs = {
            int(bb_addr)
            for bb_addr, insn in getattr(self.prepared, "branch_instruction_by_bb", {}).items()
            if _is_direct_call_mnemonic(_normalize_mnemonic(insn.get("mnemonic", "")))
            for target_addr, _target_symbol in [self._direct_call_target_symbol(insn)]
            if target_addr is not None and int(target_addr) in stream_summary_bbs
        }
        stream_summary_callsite_contexts: List[PrefixReplaySnapshot] = []
        seen_stream_callsite_contexts: Set[Tuple[object, ...]] = set()

        def add_stream_summary_context(entry: PrefixReplaySnapshot) -> None:
            identity = self._snapshot_entry_identity(entry)
            if identity in seen_stream_callsite_contexts:
                return
            seen_stream_callsite_contexts.add(identity)
            stream_summary_callsite_contexts.append(entry)

        for callsite_bb in sorted(stream_summary_callsite_bbs):
            for entry in self._direct_call_snapshot_entries(int(callsite_bb)):
                add_stream_summary_context(entry)
        for summary_bb in sorted(stream_summary_bbs):
            for entry in self._stream_summary_entry_snapshot_entries(int(summary_bb)):
                add_stream_summary_context(entry)
        stream_summary_reachable_cache: Dict[int, bool] = {}

        def reaches_stream_summary(bb_addr: int, max_depth: int = 12, max_nodes: int = 512) -> bool:
            bb_int = int(bb_addr)
            if not stream_summary_bbs:
                return False
            cached = stream_summary_reachable_cache.get(bb_int)
            if cached is not None:
                return cached
            if (
                bb_int in stream_summary_bbs
                or bb_int in stream_summary_predecessors
                or bb_int in stream_summary_callsite_bbs
            ):
                stream_summary_reachable_cache[bb_int] = True
                return True
            queue = deque([(bb_int, 0)])
            seen = {bb_int}
            visited = 0
            while queue and visited < max_nodes:
                current, depth = queue.popleft()
                visited += 1
                if current in stream_summary_bbs:
                    stream_summary_reachable_cache[bb_int] = True
                    return True
                if depth >= max_depth:
                    continue
                for successor in successor_map.get(current, set()):
                    succ_int = int(successor)
                    if succ_int in seen:
                        continue
                    if succ_int in stream_summary_bbs:
                        stream_summary_reachable_cache[bb_int] = True
                        return True
                    seen.add(succ_int)
                    queue.append((succ_int, depth + 1))
            stream_summary_reachable_cache[bb_int] = False
            return False

        context_filter_stats = dict(getattr(self, "_last_stream_context_filter_stats", {}) or {})
        seeds = self._stream_seed_portfolio(max_seeds=max_seeds)
        setup_elapsed_seconds = time.time() - start_time
        phase_covered: Set[int] = set()
        tasks_run = 0
        tasks_injected = 0
        tasks_with_new_bbs = 0
        child_execution_interventions: Counter[str] = Counter()
        child_execution_records: List[Dict[str, object]] = []
        task_attempts = 0
        restore_failed = 0
        budget_exhausted_before_task = False
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        stop_reasons: Counter[str] = Counter()
        profile_hits: Counter[str] = Counter()
        seed_hits: Counter[str] = Counter()
        profile_task_counts: Counter[str] = Counter()
        profile_injected_counts: Counter[str] = Counter()
        debug_records: List[Dict[str, object]] = []
        debug_record_limit = max(0, _env_int("LSGEMU_STREAM_DEBUG_RECORD_LIMIT", 32))
        task_bb_list_limit = max(0, _env_int("LSGEMU_STREAM_TASK_BB_LIST_LIMIT", 2048))
        zero_new_context_counts: Counter[Tuple[object, ...]] = Counter()
        skipped_zero_new_context_tasks = 0
        selected_context_records: List[Dict[str, object]] = [
            {
                "context_bb": f"0x{int(getattr(self._interrupt_context_snapshot(context), 'address', 0) or 0):08x}",
                "context_function": self._function_name_for_addr(
                    int(getattr(self._interrupt_context_snapshot(context), "address", 0) or 0)
                ),
                "depth": int(getattr(context, "branch_depth", getattr(self._interrupt_context_snapshot(context), "depth", 0)) or 0),
                "capture_order": int(getattr(self._interrupt_context_snapshot(context), "capture_order", getattr(self._interrupt_context_snapshot(context), "order", 0)) or 0),
                "origin": str(getattr(context, "origin", "ordered") if not isinstance(context, dict) else context.get("origin", "dict-snapshot")),
                "source_occurrence_prefix_len": len(
                    self._interrupt_context_occurrence_signature(context)
                ),
            }
            for context in contexts[:64]
            if self._interrupt_context_snapshot(context) is not None
        ]
        profile_selected_contexts: Dict[str, List[Dict[str, object]]] = {}
        setup_exceeded_time_budget = bool(
            time_limit_seconds
            and time_limit_seconds > 0
            and setup_elapsed_seconds > float(time_limit_seconds)
        )
        try:
            min_startup_tasks = int(os.environ.get("LSGEMU_STREAM_MIN_STARTUP_TASKS", "4"))
        except ValueError:
            min_startup_tasks = 4
        min_startup_tasks = max(0, min(int(max_tasks or min_startup_tasks or 0), min_startup_tasks))
        startup_task_override_available = bool(profiles and contexts and seeds and min_startup_tasks > 0)

        def budget_exhausted() -> bool:
            if max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks:
                return True
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                if startup_task_override_available and tasks_run < min_startup_tasks:
                    return False
                return True
            return False

        first_pass_seed_count = min(len(seeds), max(1, int(os.environ.get("LSGEMU_STREAM_FIRST_PASS_SEEDS", "8") or 8)))
        seed_batches = [seeds[:first_pass_seed_count], seeds[first_pass_seed_count:]]
        seed_batches = [batch for batch in seed_batches if batch]
        try:
            contexts_per_profile_seed = int(
                os.environ.get("LSGEMU_STREAM_CONTEXTS_PER_PROFILE_SEED", "2")
            )
        except ValueError:
            contexts_per_profile_seed = 2
        contexts_per_profile_seed = max(1, contexts_per_profile_seed)
        try:
            zero_new_context_limit = int(
                os.environ.get("LSGEMU_STREAM_ZERO_NEW_CONTEXT_LIMIT", "8")
            )
        except ValueError:
            zero_new_context_limit = 8
        zero_new_context_limit = max(0, zero_new_context_limit)
        effect_trace_enabled = _env_flag("LSGEMU_STREAM_EFFECT_TRACE", "0")
        effect_event_limit = max(0, _env_int("LSGEMU_STREAM_EFFECT_EVENT_LIMIT", 64))
        effect_sink_terms = (
            "strcpy",
            "strncpy",
            "strcat",
            "sprintf",
            "snprintf",
            "memcpy",
            "memmove",
            "digitalwrite",
            "flashfirmware",
            "fnwritebytesflash",
            "fneraseflashsector",
            "gcodesuite4m997",
            "kill",
        )
        effect_sink_watchpoints: List[Tuple[int, str]] = []
        if effect_trace_enabled:
            for symbol_name, symbol_addr in sorted(
                self._function_starts_by_name().items(),
                key=lambda item: int(item[1]),
            ):
                normalized_symbol = _normalize_name(symbol_name)
                if any(term in normalized_symbol for term in effect_sink_terms):
                    effect_sink_watchpoints.append((int(symbol_addr) & ~1, str(symbol_name)))
            effect_sink_watchpoints = effect_sink_watchpoints[:128]

        def read_preview(uc, address: int, size: int = 96) -> str:
            try:
                if not address:
                    return ""
                data = bytes(uc.mem_read(int(address) & 0xFFFFFFFF, max(1, int(size))))
                nul = data.find(b"\x00")
                if nul >= 0:
                    data = data[:nul]
                return data[:size].decode("ascii", errors="replace")
            except Exception:
                return ""

        def read_c_string_info(uc, address: int, max_size: int = 512) -> Dict[str, object]:
            if not address:
                return {"preview": "", "observed_length": 0, "nul_seen": False}
            try:
                data = bytes(uc.mem_read(int(address) & 0xFFFFFFFF, max(1, int(max_size))))
            except Exception:
                return {"preview": "", "observed_length": 0, "nul_seen": False}
            nul = data.find(b"\x00")
            nul_seen = nul >= 0
            payload = data[:nul] if nul_seen else data
            return {
                "preview": payload[:96].decode("ascii", errors="replace"),
                "observed_length": len(payload),
                "nul_seen": bool(nul_seen),
            }

        data_symbols: List[Tuple[int, int, str]] = []
        for symbol in self._all_elf_symbols():
            symbol_addr = int(symbol.get("address", 0) or 0) & 0xFFFFFFFF
            symbol_type = str(symbol.get("type", "")).lower()
            if symbol_addr < 0x20000000 or symbol_type in {"t", "w"}:
                continue
            data_symbols.append((symbol_addr, max(0, int(symbol.get("size", 0) or 0)), str(symbol.get("name", ""))))
        data_symbols.sort(key=lambda item: item[0])

        def pointer_symbol(address: int) -> Optional[str]:
            normalized = int(address) & 0xFFFFFFFF
            selected: Optional[Tuple[int, int, str]] = None
            for symbol_addr, symbol_size, symbol_name in data_symbols:
                if symbol_addr > normalized:
                    break
                selected = (symbol_addr, symbol_size, symbol_name)
            if selected is None:
                return None
            selected_addr, selected_size, selected_name = selected
            offset = normalized - selected_addr
            if selected_size > 0 and offset >= selected_size:
                return None
            if selected_size <= 0 and offset > 0x400:
                return None
            return selected_name if offset == 0 else f"{selected_name}+0x{offset:x}"

        def make_effect_hook(symbol_name: str, symbol_addr: int, task_effect_records: List[Dict[str, object]]):
            def effect_hook(uc, address, size, user_data):
                if effect_event_limit > 0 and len(task_effect_records) >= effect_event_limit:
                    return
                try:
                    regs = {
                        "r0": int(uc.reg_read(UC_ARM_REG_R0)) & 0xFFFFFFFF,
                        "r1": int(uc.reg_read(UC_ARM_REG_R1)) & 0xFFFFFFFF,
                        "r2": int(uc.reg_read(UC_ARM_REG_R2)) & 0xFFFFFFFF,
                        "r3": int(uc.reg_read(UC_ARM_REG_R3)) & 0xFFFFFFFF,
                    }
                except Exception:
                    regs = {"r0": 0, "r1": 0, "r2": 0, "r3": 0}
                normalized_symbol = _normalize_name(symbol_name)
                event = {
                    "pc": f"0x{int(address) & 0xFFFFFFFF:08x}",
                    "symbol": symbol_name,
                    "r0": f"0x{regs['r0']:08x}",
                    "r1": f"0x{regs['r1']:08x}",
                    "r2": f"0x{regs['r2']:08x}",
                    "r3": f"0x{regs['r3']:08x}",
                }
                if any(term in normalized_symbol for term in ("strcpy", "strncpy", "strcat")):
                    src_info = read_c_string_info(uc, regs["r1"])
                    event.update({
                        "dest": f"0x{regs['r0']:08x}",
                        "src": f"0x{regs['r1']:08x}",
                        "dest_symbol": pointer_symbol(regs["r0"]),
                        "src_symbol": pointer_symbol(regs["r1"]),
                        "src_preview": src_info["preview"],
                        "src_observed_length": src_info["observed_length"],
                        "src_nul_seen": src_info["nul_seen"],
                    })
                elif any(term in normalized_symbol for term in ("sprintf", "snprintf")):
                    event.update({
                        "dest": f"0x{regs['r0']:08x}",
                        "format": f"0x{regs['r1']:08x}",
                        "format_preview": read_preview(uc, regs["r1"]),
                    })
                elif any(term in normalized_symbol for term in ("memcpy", "memmove")):
                    event.update({
                        "dest": f"0x{regs['r0']:08x}",
                        "src": f"0x{regs['r1']:08x}",
                        "dest_symbol": pointer_symbol(regs["r0"]),
                        "src_symbol": pointer_symbol(regs["r1"]),
                        "length": int(regs["r2"]),
                        "src_preview": read_preview(uc, regs["r1"], min(96, max(1, int(regs["r2"]) if int(regs["r2"]) < 4096 else 96))),
                    })
                elif "digitalwrite" in normalized_symbol:
                    event.update({"pin": int(regs["r0"]), "value": int(regs["r1"])})
                task_effect_records.append(event)
            return effect_hook

        for seed_batch in seed_batches:
            if budget_exhausted():
                break
            ordered_contexts_by_profile: Dict[int, List[object]] = {}
            for profile_index, profile in enumerate(profiles):
                if profile.profile_kind == "gcode_command_queue":
                    profile_terms = (
                        "gcode",
                        "queue",
                        "getserialcommands",
                        "getavailablecommands",
                        "processnextcommand",
                        "advance",
                        "parse",
                        "parser",
                        "loop",
                    )
                    strong_terms = (
                        "getserialcommands",
                        "getavailablecommands",
                        "processnextcommand",
                        "advance",
                        "loop",
                    )
                elif profile.profile_kind == "usb_cdc_flat_ring":
                    profile_terms = (
                        "usb",
                        "cdc",
                        "vcom",
                        "serial",
                        "available",
                        "read",
                        "getc",
                        "getserialcommands",
                        "loop",
                    )
                    strong_terms = (
                        "available",
                        "read",
                        "getc",
                        "getserialcommands",
                        "loop",
                    )
                elif profile.profile_kind == "hardware_serial_nested_ring":
                    profile_terms = (
                        "hardwareserial",
                        "serial",
                        "available",
                        "read",
                        "getc",
                        "getserialcommands",
                        "gcode",
                        "queue",
                        "loop",
                    )
                    strong_terms = (
                        "hardwareserial4readev",
                        "hardwareserial9availableev",
                        "read",
                        "available",
                        "getc",
                        "getserialcommands",
                        "loop",
                    )
                elif profile.profile_kind in {
                    "generic_global_input_buffer",
                    "snapshot_register_pointer_buffer",
                    "observed_memory_read_buffer",
                }:
                    profile_terms = STREAM_INPUT_CONSUMER_TERMS
                    strong_terms = (
                        "read",
                        "getc",
                        "receive",
                        "recv",
                        "rx",
                        "parse",
                        "parser",
                        "xmlparse",
                        "serialread",
                        "serialgetc",
                        "uartgetc",
                        "directserial4read",
                    )
                elif profile.profile_kind == "stream_api_summary":
                    profile_terms = (
                        "serial",
                        "uart",
                        "usart",
                        "stream",
                        "getc",
                        "readable",
                        "available",
                        "directserial",
                        "stream4read",
                        "stream4getc",
                        "basegetc",
                        "recv",
                        "receive",
                        "parser",
                        "parse",
                        "loop",
                    )
                    strong_terms = (
                        "serialgetc",
                        "serialread",
                        "serialreadable",
                        "serialbase",
                        "uartgetc",
                        "usartgetc",
                        "directserial",
                        "stream4read",
                        "stream4getc",
                        "basegetc",
                        "readable",
                        "available",
                        "getc",
                        "recv",
                        "receive",
                        "rx",
                    )
                else:
                    profile_terms = STREAM_INPUT_CONSUMER_TERMS
                    strong_terms = STREAM_INPUT_CONSUMER_TERMS

                runtime_or_nonconsumer_terms = STREAM_RUNTIME_NONCONSUMER_CONTEXT_TERMS

                def profile_context_score(snapshot: object) -> Tuple[int, ...]:
                    raw_context = snapshot
                    resolved_snapshot = self._interrupt_context_snapshot(snapshot) or snapshot
                    address = int(getattr(resolved_snapshot, "address", 0) or 0)
                    bb_addr = self.prepared.resolve_basic_block(address)
                    bb_int = int(bb_addr if bb_addr is not None else address)
                    observed_source_pc = int(profile.auxiliary_addr or 0) & ~1
                    observed_source_bb = (
                        self.prepared.resolve_basic_block(observed_source_pc)
                        if observed_source_pc
                        else None
                    )
                    observed_source_match = 1 if (
                        profile.profile_kind == "observed_memory_read_buffer"
                        and observed_source_pc
                        and (
                            (int(address) & ~1) == observed_source_pc
                            or (observed_source_bb is not None and bb_int == int(observed_source_bb))
                        )
                    ) else 0
                    name = _normalize_name(self._function_name_for_addr(address))
                    categories = self._semantic_categories_for_bb(bb_int)
                    penalty_terms = (
                        "begin",
                        "init",
                        "constructor",
                        "foreach",
                        "write",
                        "print",
                        "puts",
                        "tx",
                        "begin",
                        "enable",
                        "disable",
                        "deinit",
                        "rcc",
                        "clock",
                        "clk",
                        "mulsf",
                        "muldf",
                        "divsf",
                        "divdf",
                        "aeabi",
                        "ticker",
                        "systick",
                        "timer",
                        "time",
                        "timeout",
                        "delay",
                        "millis",
                        "micros",
                    )
                    stream_api_time_terms = (
                        "ticker",
                        "systick",
                        "timer",
                        "clock",
                        "clk",
                        "time",
                        "timeout",
                        "delay",
                        "millis",
                        "micros",
                    )
                    stream_api_output_or_config_terms = (
                        "putc",
                        "putchar",
                        "print",
                        "printf",
                        "write",
                        "flush",
                        "format",
                        "baud",
                        "init",
                        "begin",
                        "deinit",
                        "send",
                        "transmit",
                        "serialputc",
                        "serialformat",
                        "serialbaud",
                    )
                    stream_api_specific_terms = (
                        "serial",
                        "uart",
                        "usart",
                        "directserial",
                        "serialbase",
                        "stream4read",
                        "stream4getc",
                        "basegetc",
                        "readable",
                        "available",
                        "getc",
                        "recv",
                        "receive",
                        "rx",
                    )
                    strong_match = 1 if any(term in name for term in strong_terms) else 0
                    profile_match = 1 if any(term in name for term in profile_terms) else 0
                    consumer_category = 1 if "stream_or_protocol_input" in categories or "protocol_callback" in categories else 0
                    penalty = 1 if any(term in name for term in penalty_terms) else 0
                    runtime_nonconsumer = 1 if any(term in name for term in runtime_or_nonconsumer_terms) else 0
                    low_category = 1 if "libgcc_runtime_path" in categories or "startup_teardown_path" in categories else 0
                    bad_api_context = 1 if (
                        profile.profile_kind == "stream_api_summary"
                        and (
                            any(term in name for term in stream_api_time_terms)
                            or any(term in name for term in stream_api_output_or_config_terms)
                        )
                    ) else 0
                    api_specific_context = 1 if (
                        profile.profile_kind == "stream_api_summary"
                        and any(term in name for term in stream_api_specific_terms)
                    ) else 0
                    message_loop_context = 1 if (
                        message_replay_mode
                        and any(term in name for term in ("eventloop", "msgreceive", "msgtryreceive", "msgsendreceive"))
                    ) else 0
                    message_peripheral_context = 1 if (
                        message_replay_mode
                        and any(term in name for term in ("ble", "hci"))
                    ) else 0
                    context_key = self._stream_context_state_key(profile, snapshot)
                    success_score = min(16, int(self.stream_context_success_counts.get(context_key, 0) or 0))
                    zero_new_penalty = min(16, int(self.stream_context_zero_new_counts.get(context_key, 0) or 0))
                    stream_summary_here = 1 if bb_int in stream_summary_bbs else 0
                    stream_summary_adjacent = 1 if bb_int in stream_summary_predecessors else 0
                    stream_summary_callsite = 1 if bb_int in stream_summary_callsite_bbs else 0
                    stream_summary_reachable = 1 if reaches_stream_summary(bb_int) else 0
                    return (
                        stream_summary_here,
                        stream_summary_adjacent,
                        stream_summary_callsite,
                        stream_summary_reachable,
                        observed_source_match,
                        message_loop_context,
                        -message_peripheral_context,
                        success_score,
                        -zero_new_penalty,
                        -bad_api_context,
                        -runtime_nonconsumer,
                        api_specific_context,
                        strong_match,
                        profile_match,
                        -penalty,
                        -low_category,
                        consumer_category,
                        self._semantic_category_priority(categories),
                        int(getattr(raw_context, "branch_depth", getattr(resolved_snapshot, "depth", 0)) or 0),
                        int(getattr(resolved_snapshot, "capture_order", getattr(resolved_snapshot, "order", 0)) or 0),
                    )

                def useful_profile_context(snapshot: object) -> bool:
                    resolved_snapshot = self._interrupt_context_snapshot(snapshot) or snapshot
                    address = int(getattr(resolved_snapshot, "address", 0) or 0)
                    bb_addr = self.prepared.resolve_basic_block(address)
                    bb_int = int(bb_addr if bb_addr is not None else address)
                    if profile.profile_kind == "observed_memory_read_buffer":
                        observed_source_pc = int(profile.auxiliary_addr or 0) & ~1
                        observed_source_bb = (
                            self.prepared.resolve_basic_block(observed_source_pc)
                            if observed_source_pc
                            else None
                        )
                        if observed_source_pc and (
                            (int(address) & ~1) == observed_source_pc
                            or (observed_source_bb is not None and bb_int == int(observed_source_bb))
                        ):
                            return True
                    name = _normalize_name(self._function_name_for_addr(address))
                    categories = self._semantic_categories_for_bb(bb_int)
                    if (
                        profile.profile_kind == "stream_api_summary"
                        and (
                            bb_int in stream_summary_bbs
                            or bb_int in stream_summary_predecessors
                            or bb_int in stream_summary_callsite_bbs
                            or reaches_stream_summary(bb_int)
                        )
                    ):
                        return True
                    if any(
                        term in name
                        for term in (
                            "constructor",
                            "global",
                            "subi",
                            "libcinitarray",
                            "systeminit",
                            "startup",
                            "initarray",
                            "setup",
                            "foreach",
                        )
                    ) or re.search(r"c[12]e", name) is not None:
                        return False
                    if any(term in name for term in runtime_or_nonconsumer_terms):
                        return False
                    if "libgcc_runtime_path" in categories or "startup_teardown_path" in categories:
                        return False
                    if any(
                        term in name
                        for term in (
                            "write",
                            "writable",
                            "print",
                            "puts",
                            "putc",
                            "putchar",
                            "printf",
                            "flush",
                            "echo",
                            "send",
                            "transmit",
                            "usartput",
                            "serialput",
                            "putudec",
                            "isatty",
                            "size",
                            "config",
                            "regread",
                            "readreg",
                            "trxregread",
                            "irq",
                            "callbackif",
                            "callbackassign",
                            "callbackd2",
                            "callbackc2",
                            "workq",
                            "workqueue",
                            "zworkq",
                            "stdouthook",
                            "hookinstall",
                            "alreadyattached",
                        )
                    ):
                        return False
                    if profile.profile_kind == "stream_api_summary" and any(
                        term in name for term in STREAM_OUTPUT_OR_CONFIG_CONTEXT_TERMS
                    ):
                        return False
                    if any(term in name for term in ("ticker", "systick", "timer", "clock", "delay")):
                        return False
                    return bool(
                        any(term in name for term in strong_terms)
                        or any(term in name for term in ("eventloop", "loop", "main", "advance"))
                        or "stream_or_protocol_input" in categories
                        or "protocol_callback" in categories
                    )

                ordered_contexts = sorted(contexts, key=profile_context_score, reverse=True)
                if profile.profile_kind == "stream_api_summary" and stream_summary_callsite_contexts:
                    existing_context_keys = {
                        self._stream_context_state_key(profile, context)
                        for context in ordered_contexts
                    }
                    for context in sorted(stream_summary_callsite_contexts, key=profile_context_score, reverse=True):
                        context_key = self._stream_context_state_key(profile, context)
                        if context_key in existing_context_keys:
                            continue
                        existing_context_keys.add(context_key)
                        ordered_contexts.insert(0, context)
                filtered_contexts = [context for context in ordered_contexts if useful_profile_context(context)]
                profile_fallback_contexts = [
                    context for context in ordered_contexts
                    if not any(
                        term in _normalize_name(
                            self._function_name_for_addr(
                                int(getattr(self._interrupt_context_snapshot(context), "address", 0) or 0)
                            )
                        )
                        for term in STREAM_RUNTIME_NONCONSUMER_CONTEXT_TERMS
                    )
                ]
                profile_filter_fallback_used = False
                allow_profile_fallback = (
                    profile.profile_kind == "stream_api_summary"
                    or os.environ.get("LSGEMU_STREAM_ALLOW_FALLBACK_CONTEXTS", "").strip().lower()
                    in {"1", "true", "yes", "on"}
                )
                if filtered_contexts:
                    ordered_contexts = filtered_contexts
                elif allow_profile_fallback:
                    ordered_contexts = profile_fallback_contexts
                    profile_filter_fallback_used = bool(ordered_contexts)
                else:
                    ordered_contexts = filtered_contexts
                if message_replay_mode and prefer_stream_summary_contexts and stream_summary_callsite_contexts:
                    try:
                        configured_message_budget = int(
                            os.environ.get("LSGEMU_STREAM_MESSAGE_CONTEXTS_PER_PROFILE_SEED", "0") or 0
                        )
                    except ValueError:
                        configured_message_budget = 0
                    if configured_message_budget > 0:
                        profile_context_budget = configured_message_budget
                    elif time_limit_seconds and time_limit_seconds <= 12:
                        # Short probes must diversify across profiles first.
                        # Otherwise one chatty summary API consumes the whole
                        # stream budget before buffer-backed profiles run.
                        profile_context_budget = 1
                    else:
                        profile_context_budget = max(
                            2,
                            contexts_per_profile_seed,
                            min(len(stream_summary_callsite_contexts), int(max_contexts or 16), 4),
                        )
                else:
                    profile_context_budget = 1 if message_replay_mode else contexts_per_profile_seed
                context_limit = max(
                    1,
                    min(
                        len(ordered_contexts),
                        profile_context_budget,
                    ),
                )
                ordered_contexts_by_profile[profile_index] = ordered_contexts[:context_limit]
                profile_selected_contexts[profile.object_symbol] = [
                    {
                        "context_bb": f"0x{int(getattr(self._interrupt_context_snapshot(context), 'address', 0) or 0):08x}",
                        "context_function": self._function_name_for_addr(
                            int(getattr(self._interrupt_context_snapshot(context), "address", 0) or 0)
                        ),
                        "depth": int(getattr(context, "branch_depth", getattr(self._interrupt_context_snapshot(context), "depth", 0)) or 0),
                        "capture_order": int(getattr(self._interrupt_context_snapshot(context), "capture_order", getattr(self._interrupt_context_snapshot(context), "order", 0)) or 0),
                        "origin": str(getattr(context, "origin", "ordered") if not isinstance(context, dict) else context.get("origin", "dict-snapshot")),
                        "profile_filter_fallback": profile_filter_fallback_used,
                    }
                    for context in ordered_contexts[:context_limit]
                    if self._interrupt_context_snapshot(context) is not None
                ]

            for seed in seed_batch:
                if budget_exhausted():
                    break
                for profile_index, profile in enumerate(profiles):
                    if budget_exhausted():
                        break
                    if not self._stream_seed_relevant_for_profile(profile, seed):
                        continue
                    ordered_contexts = ordered_contexts_by_profile.get(profile_index, [])
                    for context in ordered_contexts:
                        if budget_exhausted():
                            break
                        context_key = self._stream_context_state_key(profile, context)
                        if (
                            zero_new_context_limit > 0
                            and self.stream_context_zero_new_counts[context_key] >= zero_new_context_limit
                        ):
                            skipped_zero_new_context_tasks += 1
                            continue
                        task_attempts += 1
                        attempt_execution_id = (
                            f"{str(phase_name or 'stream_input_replay')}"
                            f"-attempt-{task_attempts}"
                        )
                        try:
                            emulator = self._new_temp_emulator(
                                max_snapshots=max(3, self.max_snapshots),
                                llm_config_path=self._effective_llm_config_path(),
                                constraint_json_path=self.constraint_file,
                                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                                stage_name=self._temp_stage_for("stream_input_replay_task"),
                            )
                        except Exception as exc:
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "stream_input_replay"),
                                execution_id=attempt_execution_id,
                                reason="emulator_create_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_stream_input_snapshot_replay"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "profile_kind": profile.profile_kind,
                                    "object_symbol": profile.object_symbol,
                                },
                                execution_started=False,
                                execution_error=exc,
                            )
                            child_execution_records.append(failure_record)
                            child_execution_interventions.update(
                                failure_record.get("actual_intervention_reasons", []) or []
                            )
                            stop_reasons["emulator_create_exception"] += 1
                            logger.debug("stream replay emulator创建失败: %s", exc)
                            continue
                        temp_mmio = None
                        try:
                            emulator.stream_input_default_bytes = bytes(seed)
                            emulator.stream_input_state.clear()
                            self._configure_emulator_feedback(emulator)
                            self._configure_replay_skip_function_returns(
                                emulator,
                                include_time=True,
                                exclude_stream_input_summaries=profile.profile_kind != "stream_api_summary",
                                exclude_addresses={
                                    int(addr) & ~1
                                    for addr, _symbol in effect_sink_watchpoints
                                } if effect_trace_enabled else None,
                            )
                            emulator.enable_branch_snapshot = True
                            temp_mmio = EnhancedMMIOHandler(
                                emulator.uc,
                                self.constraint_file,
                                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                            )
                            context_snapshot = self._interrupt_context_snapshot(context)
                            if context_snapshot is None:
                                restore_failed += 1
                                failure_record = self._execution_failure_evidence_record(
                                    phase_name=str(phase_name or "stream_input_replay"),
                                    execution_id=attempt_execution_id,
                                    reason="snapshot_restore_failed",
                                    metadata={
                                        "entry_derivation": (
                                            "entry_derived_stream_input_snapshot_replay"
                                        ),
                                        "context_snapshot_mode": True,
                                        "coverage_counted": True,
                                        "profile_kind": profile.profile_kind,
                                        "object_symbol": profile.object_symbol,
                                    },
                                    execution_started=False,
                                    execution_error="context_snapshot_missing",
                                )
                                child_execution_records.append(failure_record)
                                child_execution_interventions.update(
                                    failure_record.get("actual_intervention_reasons", []) or []
                                )
                                stop_reasons["snapshot_restore_failed"] += 1
                                self._safe_dispose_temp_emulator(
                                    emulator,
                                    mmio_handler=temp_mmio,
                                    quarantine=None,
                                    stage_name=self._temp_stage_for("stream_input_replay_task"),
                                    evidence_record=failure_record,
                                )
                                continue
                            restored = self._restore_branch_snapshot(
                                emulator,
                                context_snapshot,
                                lineage_source=(
                                    context
                                    if isinstance(context, PrefixReplaySnapshot)
                                    else None
                                ),
                            )
                            if not restored:
                                restore_failed += 1
                                failure_record = self._execution_failure_evidence_record(
                                    phase_name=str(phase_name or "stream_input_replay"),
                                    execution_id=attempt_execution_id,
                                    reason="snapshot_restore_failed",
                                    metadata={
                                        "entry_derivation": (
                                            "entry_derived_stream_input_snapshot_replay"
                                        ),
                                        "context_snapshot_mode": True,
                                        "coverage_counted": True,
                                        "profile_kind": profile.profile_kind,
                                        "object_symbol": profile.object_symbol,
                                    },
                                    execution_started=False,
                                    execution_error="external_or_memory_restore_failed",
                                )
                                child_execution_records.append(failure_record)
                                child_execution_interventions.update(
                                    failure_record.get("actual_intervention_reasons", []) or []
                                )
                                stop_reasons["snapshot_restore_failed"] += 1
                                self._safe_dispose_temp_emulator(
                                    emulator,
                                    mmio_handler=temp_mmio,
                                    quarantine=None,
                                    stage_name=self._temp_stage_for("stream_input_replay_task"),
                                    evidence_record=failure_record,
                                )
                                continue
                            if not self._restore_replay_mmio_state(
                                emulator,
                                temp_mmio,
                                self._interrupt_context_mmio_state(context),
                            ):
                                raise RuntimeError(
                                    self._replay_mmio_restore_failure_reason(emulator)
                                )
                            injected = self._write_stream_seed_to_emulator(emulator, profile, seed)
                        except Exception as exc:
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "stream_input_replay"),
                                execution_id=attempt_execution_id,
                                reason="replay_setup_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_stream_input_snapshot_replay"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "profile_kind": profile.profile_kind,
                                    "object_symbol": profile.object_symbol,
                                },
                                execution_started=False,
                                execution_error=exc,
                            )
                            child_execution_records.append(failure_record)
                            child_execution_interventions.update(
                                failure_record.get("actual_intervention_reasons", []) or []
                            )
                            stop_reasons["replay_setup_exception"] += 1
                            self._safe_dispose_temp_emulator(
                                emulator,
                                mmio_handler=temp_mmio,
                                quarantine=None,
                                stage_name=self._temp_stage_for("stream_input_replay_task"),
                                evidence_record=failure_record,
                            )
                            logger.debug("stream replay setup失败: %s", exc)
                            continue
                        if injected:
                            tasks_injected += 1
                            profile_injected_counts[profile.object_symbol] += 1
                        input_read_hits: List[Dict[str, object]] = []
                        input_read_hooks: List[int] = []
                        effect_hooks: List[int] = []
                        hook_installation_errors: List[str] = []
                        task_effect_records: List[Dict[str, object]] = []

                        def make_input_read_hook(injected_range: Dict[str, object]):
                            range_start = int(injected_range.get("address", 0) or 0) & 0xFFFFFFFF
                            range_size = int(injected_range.get("size", 0) or 0)
                            range_end = range_start + max(0, range_size)
                            payload = bytes.fromhex(str(injected_range.get("payload_hex_preview") or ""))

                            def input_read_hook(uc, access, address, size, value, user_data):
                                if len(input_read_hits) >= 128:
                                    return
                                read_start = int(address) & 0xFFFFFFFF
                                read_end = read_start + max(0, int(size or 0))
                                if read_start >= range_end or read_end <= range_start:
                                    return
                                try:
                                    pc = int(uc.reg_read(UC_ARM_REG_PC)) & 0xFFFFFFFF
                                except Exception:
                                    pc = 0
                                overlap_start = max(read_start, range_start)
                                overlap_end = min(read_end, range_end)
                                payload_offset = max(0, overlap_start - range_start)
                                overlap_len = max(0, overlap_end - overlap_start)
                                input_read_hits.append({
                                    "pc": f"0x{pc:08x}",
                                    "address": f"0x{read_start:08x}",
                                    "size": int(size or 0),
                                    "overlap_address": f"0x{overlap_start:08x}",
                                    "overlap_size": overlap_len,
                                    "payload_offset": payload_offset,
                                    "payload_hex": payload[payload_offset:payload_offset + min(overlap_len, 32)].hex(),
                                    "source": injected_range.get("source"),
                                    "profile_kind": injected_range.get("profile_kind"),
                                    "object_symbol": injected_range.get("object_symbol"),
                                })

                            return input_read_hook

                        for injected_range in list(getattr(emulator, "stream_input_injected_ranges", []) or []):
                            range_start = int(injected_range.get("address", 0) or 0) & 0xFFFFFFFF
                            range_size = int(injected_range.get("size", 0) or 0)
                            if range_start and range_size > 0:
                                try:
                                    hook = emulator._add_owned_hook(
                                        UC_HOOK_MEM_READ,
                                        make_input_read_hook(injected_range),
                                        None,
                                        range_start,
                                        range_start + range_size - 1,
                                    )
                                    input_read_hooks.append(hook)
                                except Exception as exc:
                                    hook_installation_errors.append(
                                        f"input_read_hook@0x{range_start:08x}:{type(exc).__name__}"
                                    )
                        if effect_trace_enabled and effect_sink_watchpoints:
                            for sink_addr, sink_symbol in effect_sink_watchpoints:
                                try:
                                    effect_hooks.append(
                                        emulator._add_owned_hook(
                                            UC_HOOK_CODE,
                                            make_effect_hook(sink_symbol, sink_addr, task_effect_records),
                                            None,
                                            sink_addr,
                                            sink_addr + 1,
                                        )
                                    )
                                except Exception as exc:
                                    hook_installation_errors.append(
                                        f"effect_hook@0x{int(sink_addr) & 0xFFFFFFFF:08x}:{type(exc).__name__}"
                                    )
                        known_before = self.global_coverage | phase_covered
                        previous_quiescence_limit = emulator.stop_after_no_new_bbs
                        emulator.stop_after_no_new_bbs = (
                            max(1, int(no_new_bb_limit))
                            if no_new_bb_limit and no_new_bb_limit > 0
                            else None
                        )
                        run_result: Dict[str, object] = {"stop_reason": "not_started"}
                        run_exception: Optional[BaseException] = None
                        with self.guided_modules(temp_mmio), self.capture_execution_trace(emulator) as trace:
                            try:
                                run_result = emulator.run(
                                    entry_point=None,
                                    max_instructions=max_instructions,
                                    timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                                    preserve_cpu_state=True,
                                )
                            except Exception as exc:
                                run_exception = exc
                                run_result = self._materialize_replay_failure_result(
                                    "execution_exception",
                                    execution_started=True,
                                    execution_error=exc,
                                )
                            finally:
                                emulator.stop_after_no_new_bbs = previous_quiescence_limit

                                for hook in input_read_hooks:
                                    try:
                                        emulator._remove_owned_hook(hook)
                                    except Exception:
                                        pass
                                for hook in effect_hooks:
                                    try:
                                        emulator._remove_owned_hook(hook)
                                    except Exception:
                                        pass

                        if hook_installation_errors:
                            if not isinstance(run_result, dict):
                                run_result = dict(run_result or {})
                            run_result["hook_installation_errors"] = list(
                                hook_installation_errors
                            )
                        self._annotate_replay_run_result(run_result, context)
                        child_execution_interventions.update(
                            execution_intervention_reasons(run_result)
                        )
                        valid = self.validate_coverage(trace.covered_bbs)
                        execution_record = build_execution_evidence_record(
                                phase_name=str(phase_name or "stream_input_replay"),
                                run_result=run_result,
                                covered_bbs=valid,
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_stream_input_snapshot_replay"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "environment_input_consumed": bool(injected),
                                },
                                execution_id=attempt_execution_id,
                            )
                        if run_exception is not None:
                            execution_record["failure_reason"] = "execution_exception"
                            stop_reasons["execution_exception"] += 1
                        child_execution_records.append(execution_record)

                        def safe_postprocess(operation: str, callback, default=None):
                            return self._safe_replay_postprocess(
                                operation,
                                callback,
                                evidence_record=execution_record,
                                run_result=run_result,
                                default=default,
                            )

                        child_execution_interventions.update(
                            execution_record.get("actual_intervention_reasons", {})
                            or {}
                        )
                        new_bbs = valid - known_before
                        if new_bbs:
                            tasks_with_new_bbs += 1
                            profile_hits[profile.object_symbol] += len(new_bbs)
                            seed_hits[seed.hex()] += len(new_bbs)
                            zero_new_context_counts[context_key] = 0
                            self.stream_context_zero_new_counts[context_key] = 0
                            self.stream_context_success_counts[context_key] += 1
                            self.stream_context_new_bb_counts[context_key] += len(new_bbs)
                        else:
                            zero_new_context_counts[context_key] += 1
                            self.stream_context_zero_new_counts[context_key] += 1
                        phase_covered.update(valid)
    
                        replay_events = safe_postprocess(
                            "branch_event_collection",
                            lambda: emulator.branch_snapshot_manager.get_ordered_events(),
                            default=[],
                        ) or []
                        replay_snapshots = safe_postprocess(
                            "replay_snapshot_collection",
                            lambda: self._ordered_replay_snapshots(emulator),
                            default=[],
                        ) or []
                        context_source_signature = self._ordered_source_path_signature(
                            tuple((
                                getattr(context, "source_path_signature", tuple())
                                if not isinstance(context, dict)
                                else context.get("source_path_signature", tuple())
                            ) or tuple())
                        )
                        if isinstance(context, PrefixReplaySnapshot):
                            context_source_evidence = self._snapshot_entry_evidence_class(context)
                        elif isinstance(context, dict):
                            context_source_evidence = self._capture_evidence_class(
                                context_source_signature,
                                context.get("evidence_class"),
                            )
                        else:
                            context_source_evidence = EVIDENCE_E0
                        stream_replay_evidence = derived_replay_evidence(
                            context_source_evidence,
                            consumed_environment_fact=True,
                        )
                        if stream_replay_evidence == EVIDENCE_UNKNOWN:
                            stream_replay_evidence = EVIDENCE_E2
                        safe_postprocess(
                            "coverage_evidence",
                            lambda: self._record_coverage_evidence(
                                stream_replay_evidence,
                                valid,
                            ),
                        )
                        remembered_branch_events += safe_postprocess(
                            "branch_event_feedback",
                            lambda: self._remember_main_branch_events(
                                replay_events,
                                evidence_class=stream_replay_evidence,
                            ),
                            default=0,
                        ) or 0
                        remembered_branch_root_snapshots += safe_postprocess(
                            "branch_snapshot_feedback",
                            lambda: self._remember_branch_root_snapshots(
                                replay_events,
                                replay_snapshots,
                                source_path_signature=context_source_signature,
                                evidence_class=stream_replay_evidence,
                                occurrence_events=(
                                    emulator.branch_snapshot_manager
                                    .get_ordered_occurrence_events()
                                ),
                                source_occurrence_signature=(
                                    self._interrupt_context_occurrence_signature(
                                        context
                                    )
                                ),
                            ),
                            default=0,
                        ) or 0
                        dynamic_successor_edges_added += safe_postprocess(
                            "dynamic_successor_feedback",
                            lambda: self._record_dynamic_successors(replay_events),
                            default=0,
                        ) or 0
                        dynamic_successor_edges_added += safe_postprocess(
                            "runtime_successor_feedback",
                            lambda: self._record_emulator_runtime_successors(emulator),
                            default=0,
                        ) or 0
                        safe_postprocess(
                            "scheduler_feedback",
                            lambda: self._harvest_emulator_feedback(emulator),
                        )
                        tasks_run += 1
                        profile_task_counts[profile.object_symbol] += 1
                        stop_reason = str(run_result.get("stop_reason") or "unknown")
                        stop_reasons[stop_reason] += 1
                        if len(debug_records) < debug_record_limit:
                            replay_registers = dict(run_result.get("registers") or {})
                            if not replay_registers:
                                try:
                                    replay_registers = {
                                        name: f"0x{int(value) & 0xFFFFFFFF:08x}"
                                        for name, value in emulator._get_registers().items()
                                    }
                                except Exception:
                                    replay_registers = {}
                            trace_tail = [
                                f"0x{int(bb) & 0xFFFFFFFF:08x}"
                                for bb in list(getattr(trace, "executed_bbs", []) or [])[-32:]
                            ]
                            skip_stats = dict(getattr(emulator, "skip_function_stats", {}) or {})
                            stream_summary_events = list(
                                getattr(emulator, "stream_input_summary_events", []) or []
                            )
                            stream_payload_writes = list(
                                getattr(emulator, "stream_input_payload_writes", []) or []
                            )
                            injected_ranges = []
                            for injected_range in list(getattr(emulator, "stream_input_injected_ranges", []) or [])[:64]:
                                item = dict(injected_range)
                                if isinstance(item.get("address"), int):
                                    item["address"] = f"0x{int(item['address']) & 0xFFFFFFFF:08x}"
                                injected_ranges.append(item)
                            sorted_task_covered = sorted(valid)
                            sorted_task_new = sorted(new_bbs)
                            record = {
                                "profile_kind": profile.profile_kind,
                                "object_symbol": profile.object_symbol,
                                "object_addr": f"0x{profile.object_addr:08x}",
                                "absolute_buffer_addr": (
                                    f"0x{int(profile.absolute_buffer_addr):08x}"
                                    if profile.absolute_buffer_addr is not None else None
                                ),
                                "absolute_head_addr": (
                                    f"0x{int(profile.absolute_head_addr):08x}"
                                    if profile.absolute_head_addr is not None else None
                                ),
                                "absolute_tail_addr": (
                                    f"0x{int(profile.absolute_tail_addr):08x}"
                                    if profile.absolute_tail_addr is not None else None
                                ),
                                "absolute_length_addr": (
                                    f"0x{int(profile.absolute_length_addr):08x}"
                                    if profile.absolute_length_addr is not None else None
                                ),
                                "auxiliary_addr": (
                                    f"0x{int(profile.auxiliary_addr):08x}"
                                    if profile.auxiliary_addr is not None else None
                                ),
                                "auxiliary_buffer_addr": (
                                    f"0x{int(profile.auxiliary_buffer_addr):08x}"
                                    if profile.auxiliary_buffer_addr is not None else None
                                ),
                                "context_bb": f"0x{int(getattr(context_snapshot, 'address', 0) or 0):08x}",
                                "context_function": self._function_name_for_addr(int(getattr(context_snapshot, "address", 0) or 0)),
                                "context_origin": str(getattr(context, "origin", "ordered") if not isinstance(context, dict) else context.get("origin", "dict-snapshot")),
                                "seed_hex": seed.hex(),
                                "injected": bool(injected),
                                "covered_bbs": len(valid),
                                "new_bbs": len(new_bbs),
                                "stop_reason": stop_reason,
                                "run_result": run_result,
                                "registers": replay_registers,
                                "pc": replay_registers.get("pc"),
                                "lr": replay_registers.get("lr"),
                                "sp": replay_registers.get("sp"),
                                "trace_tail": trace_tail,
                                "mmio_access_tail": list(run_result.get("mmio_access_tail") or [])[-16:],
                                "memory_access_tail": list(run_result.get("memory_access_tail") or [])[-16:],
                                "watch_memory_events": list(run_result.get("watch_memory_events") or [])[-64:],
                                "watch_pc_events": list(run_result.get("watch_pc_events") or [])[-64:],
                                "injected_ranges": injected_ranges,
                                "input_read_hits": input_read_hits[:64],
                                "input_read_hit_count": len(input_read_hits),
                                "stream_input_summary_events": stream_summary_events[:64],
                                "stream_input_summary_event_count": len(stream_summary_events),
                                "stream_input_payload_writes": stream_payload_writes[:64],
                                "stream_input_payload_write_count": len(stream_payload_writes),
                                "sink_call_events": task_effect_records[:64],
                                "sink_call_event_count": len(task_effect_records),
                                "skip_function_stats": {
                                    "installed": skip_stats.get("installed"),
                                    "applied": skip_stats.get("applied"),
                                    "stateful_applied": skip_stats.get("stateful_applied"),
                                    "by_symbol": dict(skip_stats.get("by_symbol", {}) or {}),
                                },
                            }
                            if task_bb_list_limit <= 0 or len(sorted_task_covered) <= task_bb_list_limit:
                                record["covered_bb_list"] = sorted_task_covered
                            else:
                                record["covered_bb_list_sample"] = sorted_task_covered[:task_bb_list_limit]
                                record["covered_bb_list_truncated"] = True
                                record["covered_bb_list_total"] = len(sorted_task_covered)
                            if task_bb_list_limit <= 0 or len(sorted_task_new) <= task_bb_list_limit:
                                record["new_bb_list"] = sorted_task_new
                            else:
                                record["new_bb_list_sample"] = sorted_task_new[:task_bb_list_limit]
                                record["new_bb_list_truncated"] = True
                                record["new_bb_list_total"] = len(sorted_task_new)
                            debug_records.append(record)
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            quarantine=None,
                            stage_name=self._temp_stage_for("stream_input_replay_task"),
                            evidence_record=execution_record,
                        )
                        # Continue across seeds even after progress. Input-driven
                        # paths are command-family coverage, so the next seed often
                        # exercises a different callback rather than duplicating the
                        # same immediate frontier.

        budget_exhausted_before_task = bool(tasks_run == 0 and budget_exhausted())

        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation="entry_derived_stream_input_snapshot_replay",
            child_execution_summary=self._child_execution_summary(
                tasks_run,
                child_execution_interventions,
                expected_count=task_attempts,
                attempted_count=task_attempts,
                execution_records=child_execution_records,
            ),
            profiles_discovered=len(profiles),
            profiles=[
                {
                    "profile_kind": profile.profile_kind,
                    "object_symbol": profile.object_symbol,
                    "object_addr": f"0x{profile.object_addr:08x}",
                    "buffer_pointer_offset": profile.buffer_pointer_offset,
                    "head_offset": profile.head_offset,
                    "tail_offset": profile.tail_offset,
                    "capacity": profile.capacity,
                    "inline_buffer_offset": profile.inline_buffer_offset,
                    "absolute_buffer_addr": (
                        f"0x{int(profile.absolute_buffer_addr):08x}"
                        if profile.absolute_buffer_addr is not None else None
                    ),
                    "absolute_head_addr": (
                        f"0x{int(profile.absolute_head_addr):08x}"
                        if profile.absolute_head_addr is not None else None
                    ),
                    "absolute_tail_addr": (
                        f"0x{int(profile.absolute_tail_addr):08x}"
                        if profile.absolute_tail_addr is not None else None
                    ),
                    "absolute_length_addr": (
                        f"0x{int(profile.absolute_length_addr):08x}"
                        if profile.absolute_length_addr is not None else None
                    ),
                    "auxiliary_addr": (
                        f"0x{int(profile.auxiliary_addr):08x}"
                        if profile.auxiliary_addr is not None else None
                    ),
                    "auxiliary_buffer_addr": (
                        f"0x{int(profile.auxiliary_buffer_addr):08x}"
                        if profile.auxiliary_buffer_addr is not None else None
                    ),
                }
                for profile in profiles
            ],
            contexts_selected=len(contexts),
            context_filter_stats=context_filter_stats,
            stream_summary_callsite_bbs=len(stream_summary_callsite_bbs),
            stream_summary_callsite_contexts=len(stream_summary_callsite_contexts),
            stream_summary_entry_snapshot_addresses=len(self.stream_summary_entry_snapshots),
            stream_summary_entry_snapshot_variants=sum(len(entries) for entries in self.stream_summary_entry_snapshots.values()),
            selected_contexts=selected_context_records,
            profile_selected_contexts=profile_selected_contexts,
            seeds=len(seeds),
            setup_elapsed_seconds=round(setup_elapsed_seconds, 3),
            setup_exceeded_time_budget=setup_exceeded_time_budget,
            startup_task_override_available=startup_task_override_available,
            min_startup_tasks=min_startup_tasks,
            tasks_run=tasks_run,
            task_attempts=task_attempts,
            child_execution_failure_count=sum(
                1
                for record in child_execution_records
                if bool(record.get("failure_reason"))
                or str(record.get("status") or "") != VALIDATED_REPLAY
            ),
            tasks_injected=tasks_injected,
            tasks_with_new_bbs=tasks_with_new_bbs,
            restore_failed=restore_failed,
            budget_exhausted_before_task=budget_exhausted_before_task,
            zero_new_context_limit=zero_new_context_limit,
            stream_effect_trace_enabled=effect_trace_enabled,
            stream_effect_sink_watchpoints=[
                {"address": f"0x{addr:08x}", "symbol": symbol}
                for addr, symbol in effect_sink_watchpoints[:64]
            ],
            skipped_zero_new_context_tasks=skipped_zero_new_context_tasks,
            zero_new_context_suppressed=[
                self._stream_context_key_record(key, count)
                for key, count in zero_new_context_counts.most_common(16)
                if int(count) >= zero_new_context_limit > 0
            ],
            stream_context_successes=[
                {
                    **self._stream_context_key_record(key, 0),
                    "success_count": int(count),
                    "new_bbs": int(self.stream_context_new_bb_counts.get(key, 0) or 0),
                }
                for key, count in self.stream_context_success_counts.most_common(16)
            ],
            profile_tasks=dict(profile_task_counts),
            profile_injections=dict(profile_injected_counts),
            profile_new_bbs=dict(profile_hits),
            seed_new_bbs=dict(seed_hits.most_common(16)),
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            stop_reasons=dict(stop_reasons),
            time_limit_seconds=time_limit_seconds,
            max_tasks=max_tasks,
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            no_new_bb_limit=no_new_bb_limit,
            debug_records=debug_records,
        )

    def _write_trace_log(self, output_path: str | Path, trace: ExecutionTrace):
        output_path = Path(output_path)
        bb_counts = Counter(
            {
                int(bb_addr): int(count)
                for bb_addr, count in (trace.bb_counts or {}).items()
            }
        )
        lines = [
            "# 执行日志",
            f"# 固件: {self.prepared.firmware_path}",
            "",
            f"执行了 {int(trace.total_executed_bbs or len(trace.executed_bbs))} 个BB实例",
            f"唯一BB: {len(trace.covered_bbs)}",
            "",
            "BB执行次数（前20）:",
        ]
        lines.extend(
            f"  {hex(bb_addr)}: {count}次"
            for bb_addr, count in bb_counts.most_common(20)
        )
        atomic_write_text(output_path, "\n".join(lines) + "\n")

    def run_baseline(
        self,
        max_instructions: int = 200000,
        enable_branch_snapshots: bool = True,
        trace_output_path: Optional[str | Path] = None,
        quiescence_bb_limit: Optional[int] = None,
        enable_function_summaries: bool = False,
        phase_name: str = "baseline",
        fresh_emulator: bool = False,
        timeout_seconds: Optional[float] = None,
    ) -> Set[int]:
        emulator = self.emulator
        mmio_handler = self.mmio_handler
        register_tracer = self.register_tracer
        if fresh_emulator:
            fresh_stage = self._temp_stage_for(f"{phase_name}_fresh")
            emulator = None
            mmio_handler = None
            register_tracer = None
            try:
                emulator = self._new_temp_emulator(
                    max_snapshots=self.max_snapshots,
                    llm_config_path=self._effective_llm_config_path(),
                    constraint_json_path=self.constraint_file,
                    branch_mmio_file_mode=self.baseline_branch_mmio_file_mode,
                    stage_name=fresh_stage,
                )
                self._configure_emulator_feedback(emulator)
                mmio_handler = EnhancedMMIOHandler(
                    emulator.uc,
                    self.constraint_file,
                    branch_mmio_file_mode=self.baseline_branch_mmio_file_mode,
                )
                register_tracer = self._new_temp_register_tracer(emulator)
            except BaseException:
                if emulator is not None:
                    try:
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=mmio_handler,
                            register_tracer=register_tracer,
                            quarantine=None,
                            stage_name=fresh_stage,
                        )
                    except Exception as cleanup_error:
                        logger.debug("fresh baseline setup cleanup failed: %s", cleanup_error)
                raise
        emulator.enable_branch_snapshot = enable_branch_snapshots
        previous_quiescence_limit = emulator.stop_after_no_new_bbs
        emulator.stop_after_no_new_bbs = quiescence_bb_limit if quiescence_bb_limit and quiescence_bb_limit > 0 else None
        trace = None
        input_trace_setup_meta: Dict[str, object] = {}
        run_result: Dict[str, object] = self._materialize_replay_failure_result(
            "execution_not_started",
            execution_started=False,
        )
        # cycle2 k.5 P2（r36 口径后移）→ r40 P2/C8：主流程投递既不在
        # run_baseline 内安装（svc_intervention ⇒ diagnostic 化），也不在
        # 返回后装到常驻实例（k.5 死安装点已删——其后相位不执行该实例）。
        # baseline 保持 Y 型自然停点；投递统一走相位白名单
        # （install_irq_delivery_for）。
        try:
            if enable_function_summaries:
                self._configure_replay_skip_function_returns(
                    emulator,
                    include_time=True,
                    exclude_stream_input_summaries=False,
                )
                token_seeds = self._stream_branch_token_seeds(max_tokens=64)
                if token_seeds:
                    combined_seed = b"".join(seed for seed in token_seeds if seed)
                    if combined_seed:
                        emulator.stream_input_default_bytes = combined_seed[:4096]
                        emulator.stream_input_state.clear()
            # r34 I2：真实重放校验（默认关）——按记录的读值序列钉住外部输入。
            input_trace_setup_meta = self._apply_recorded_input_trace(
                mmio_handler,
                phase_name,
            )
            with self.guided_modules(mmio_handler, register_tracer):
                with self.capture_execution_trace(emulator) as trace:
                    try:
                        run_result = self._normalize_replay_run_result(
                            emulator.run(
                                entry_point=self.prepared.entry_point,
                                max_instructions=max_instructions,
                                timeout_seconds=timeout_seconds,
                            ),
                            execution_started=True,
                        )
                    except Exception as exc:
                        run_result = self._materialize_replay_failure_result(
                            "execution_exception",
                            execution_started=True,
                            execution_error=exc,
                        )
        except Exception as exc:
            # Configuration and trace-context failures occur outside the
            # Unicorn call itself.  Materialize them so a fresh baseline can
            # still release its engine and the phase report remains auditable.
            run_result = self._materialize_replay_failure_result(
                "baseline_setup_exception",
                execution_started=False,
                execution_error=exc,
            )
        finally:
            try:
                emulator.stop_after_no_new_bbs = previous_quiescence_limit
            except Exception:
                pass

        def safe_postprocess(operation: str, callback, default=None):
            return self._safe_replay_postprocess(
                operation,
                callback,
                run_result=run_result,
                default=default,
            )

        covered_bbs = safe_postprocess(
            "baseline_coverage_collection",
            lambda: trace.covered_bbs if trace is not None else emulator.bb_addr_set,
            default=set(),
        ) or set()
        baseline_events = safe_postprocess(
            "baseline_branch_event_collection",
            lambda: emulator.branch_snapshot_manager.get_ordered_events(),
            default=[],
        ) or []
        baseline_snapshots = safe_postprocess(
            "baseline_snapshot_collection",
            lambda: self._ordered_replay_snapshots(emulator),
            default=[],
        ) or []
        remembered_branch_events = safe_postprocess(
            "baseline_branch_event_feedback",
            lambda: self._remember_main_branch_events(
                baseline_events,
                evidence_class=EVIDENCE_E0,
            ),
            default=0,
        ) or 0
        remembered_branch_root_snapshots = safe_postprocess(
            "baseline_branch_snapshot_feedback",
            lambda: self._remember_branch_root_snapshots(
                baseline_events,
                baseline_snapshots,
                evidence_class=EVIDENCE_E0,
            ),
            default=0,
        ) or 0
        dynamic_successor_edges_added = safe_postprocess(
            "baseline_dynamic_successor_feedback",
            lambda: self._record_dynamic_successors(baseline_events),
            default=0,
        ) or 0
        dynamic_successor_edges_added += safe_postprocess(
            "baseline_runtime_successor_feedback",
            lambda: self._record_emulator_runtime_successors(emulator),
            default=0,
        ) or 0
        remembered_dynamic_dispatch_roots = safe_postprocess(
            "baseline_dispatch_root_feedback",
            lambda: self._ensure_dynamic_dispatch_root_events(
                covered_bbs,
                evidence_class=EVIDENCE_E0,
            ),
            default=0,
        ) or 0
        safe_postprocess(
            "baseline_scheduler_feedback",
            lambda: self._harvest_emulator_feedback(emulator),
        )
        if trace_output_path and trace is not None:
            safe_postprocess(
                "baseline_trace_write",
                lambda: self._write_trace_log(trace_output_path, trace),
            )

        stop_reason = str(run_result.get("stop_reason") or "")
        if stop_reason == "quiescence_no_new_bbs":
            main_path_status = "stable_loop_or_tail"
        elif stop_reason == "timeout_reached":
            main_path_status = "bounded_by_timeout"
        elif stop_reason == "max_instructions_reached":
            main_path_status = "bounded_by_instruction_count"
        elif stop_reason == "timeout_or_max_instructions_reached":
            main_path_status = (
                "bounded_by_timeout_or_instruction_count"
                if max_instructions and max_instructions > 0
                else "bounded_by_timeout"
            )
        else:
            main_path_status = stop_reason or "completed"

        # Dispose a fresh baseline engine before materializing the phase
        # record.  Otherwise a teardown failure can be discovered only after
        # ``_record_phase`` has already stored a falsely complete witness.
        if fresh_emulator:
            self._safe_dispose_temp_emulator(
                emulator,
                mmio_handler=mmio_handler,
                register_tracer=register_tracer,
                quarantine=None,
                stage_name=self._temp_stage_for(f"{phase_name}_fresh"),
                run_result=run_result,
            )

        no_new_bb_tail = safe_postprocess(
            "baseline_quiescence_stat",
            lambda: emulator._no_new_bb_run,
            default=0,
        )
        branch_snapshot_stats = safe_postprocess(
            "baseline_snapshot_stats",
            lambda: emulator.branch_snapshot_manager.get_statistics(),
            default={},
        ) or {}
        mmio_stats = safe_postprocess(
            "baseline_mmio_stats",
            lambda: mmio_handler.get_statistics(),
            default={},
        ) or {}
        tracer_stats = safe_postprocess(
            "baseline_tracer_stats",
            lambda: register_tracer.get_statistics(),
            default={},
        ) or {}
        # r34 I1：摘要跳过体的覆盖记账审计（只读，不改任何覆盖数字）。
        summary_skip_accounting = safe_postprocess(
            "baseline_summary_skip_accounting",
            lambda: self._summary_skip_coverage_accounting(emulator, covered_bbs),
            default={},
        ) or {}
        # r34 I2：记录本相位真实发生的 MMIO 读值序列，供后续真实重放校验。
        input_trace_meta = dict(input_trace_setup_meta or {})
        input_trace_meta.update(
            safe_postprocess(
                "baseline_input_trace_dump",
                lambda: self._dump_input_trace(mmio_handler, phase_name, run_result),
                default={},
            )
            or {}
        )
        # r34 I3：逐墙取证（默认关）。
        wall_forensics = safe_postprocess(
            "baseline_wall_forensics",
            lambda: self._wall_forensics(emulator, run_result),
            default={},
        ) or {}
        if input_trace_meta:
            run_result = dict(run_result)
            run_result["input_trace"] = input_trace_meta
        if wall_forensics:
            run_result = dict(run_result)
            run_result["wall_forensics"] = wall_forensics
        return self._record_phase(
            phase_name,
            covered_bbs,
            evidence_class=EVIDENCE_E0,
            counterfactual_control=False,
            max_instructions=max_instructions,
            timeout_seconds=timeout_seconds,
            quiescence_bb_limit=quiescence_bb_limit,
            function_summaries_enabled=bool(enable_function_summaries),
            fresh_emulator=bool(fresh_emulator),
            no_new_bb_tail=no_new_bb_tail,
            run_result=run_result,
            summary_skip_accounting=summary_skip_accounting,
            main_path_status=main_path_status,
            branch_snapshots=int(branch_snapshot_stats.get("total_snapshots", 0) or 0),
            branch_events=len(baseline_events),
            branch_points=len({event.address for event in baseline_events}),
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            remembered_dynamic_dispatch_roots=remembered_dynamic_dispatch_roots,
            known_main_branch_events=len(self.known_main_branch_events),
            known_branch_root_snapshots=len(self.known_branch_root_snapshots),
            known_branch_root_snapshot_variants=self._known_branch_root_snapshot_variant_count(),
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            mmio_stats=mmio_stats,
            tracer_stats=tracer_stats,
            trace_output=str(trace_output_path) if trace_output_path else None,
        )

    def run_isr_exploration(
        self,
        max_instructions: int = 10000,
        *,
        count_coverage: bool = True,
    ) -> Set[int]:
        emulator = None
        temp_mmio = None
        explorer = None
        explorer_stats: Dict[str, object] = {}
        covered: Set[int] = set()
        probe_error: Optional[str] = None
        probe_diagnostics: List[Dict[str, object]] = []
        mmio_stats: Dict[str, object] = {}
        try:
            try:
                emulator = self._new_temp_emulator(
                    max_snapshots=max(3, self.max_snapshots),
                    llm_config_path=self._effective_llm_config_path(),
                    constraint_json_path=self.constraint_file,
                    branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                    stage_name=self._temp_stage_for("isr_probe"),
                )
                # ISR probing frequently reaches vendor default handlers. Let
                # Unicorn's per-ISR count/timeout bound those paths instead of
                # invoking deadlock LLM analysis for the same handler repeatedly.
                emulator.enable_loop_intervention = False
                temp_mmio = EnhancedMMIOHandler(
                    emulator.uc,
                    self.constraint_file,
                    branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                )
                explorer = ISRExplorer(
                    emulator.uc,
                    self.prepared.static_bbs,
                    vtor=self._vector_table_base(),
                    mmio_handler=temp_mmio,
                    instruction_to_bb=self.prepared.instruction_to_bb,
                    code_ranges=self._code_address_ranges(),
                    start_validator=lambda start_pc: emulator._execution_preflight(start_pc),
                    causal_context=emulator.causal_context,
                )
                with self.guided_modules(temp_mmio):
                    explorer.explore_all_isrs(max_instructions=max_instructions)
                covered = self.validate_coverage(explorer.get_total_coverage())
                explorer_stats = dict(explorer.get_statistics() or {})
            except Exception as exc:
                probe_error = f"{type(exc).__name__}: {str(exc)[:512]}"
                probe_diagnostics.append(
                    self._record_probe_diagnostic(
                        "isr_probe",
                        "probe_execution_exception",
                        error=exc,
                    )
                )
                logger.debug("ISR probe failed: %s", exc)
                # Preserve any blocks observed before a non-fatal Python-side
                # failure, but mark the phase as diagnostic through run_result.
                if explorer is not None:
                    try:
                        covered = self.validate_coverage(explorer.get_total_coverage())
                    except Exception:
                        covered = set()
                    try:
                        explorer_stats = dict(explorer.get_statistics() or {})
                    except Exception:
                        explorer_stats = {}
            try:
                mmio_stats = (
                    dict(temp_mmio.get_statistics() or {})
                    if temp_mmio is not None
                    else {}
                )
            except Exception as exc:
                detail = f"{type(exc).__name__}: {str(exc)[:512]}"
                probe_error = (
                    f"{probe_error}; probe_result_collection_exception: {detail}"
                    if probe_error
                    else f"probe_result_collection_exception: {detail}"
                )
                probe_diagnostics.append(
                    self._record_probe_diagnostic(
                        "isr_probe",
                        "probe_result_collection_exception",
                        error=exc,
                    )
                )
                logger.debug("ISR probe result collection failed: %s", exc)
        finally:
            cleanup_error = self._safe_dispose_temp_emulator(
                emulator,
                mmio_handler=temp_mmio,
                quarantine=None,
                stage_name=self._temp_stage_for("isr_probe"),
            )
            if cleanup_error:
                probe_error = (
                    f"{probe_error}; probe_cleanup_exception: {cleanup_error}"
                    if probe_error
                    else f"probe_cleanup_exception: {cleanup_error}"
                )
                probe_diagnostics.append(
                    self._record_probe_diagnostic(
                        "isr_probe",
                        "probe_cleanup_exception",
                        error=cleanup_error,
                    )
                )

        failure_result = None
        if probe_error is not None:
            failure_result = self._materialize_replay_failure_result(
                "isr_probe_exception",
                execution_started=bool(explorer is not None),
                execution_error=probe_error,
            )
        return self._record_phase(
            "isr",
            covered,
            count_coverage=count_coverage,
            entry_derivation=(
                "cold_vector_handler_diagnostic"
                if not count_coverage
                else "cold_vector_handler_direct_entry"
            ),
            strict_real_entry_replayable=False,
            isr_started=bool(explorer is not None and probe_error is None),
            max_instructions=max_instructions,
            irq_count=len(getattr(explorer, "isr_addresses", {}) or {}),
            explored_irq_count=len(getattr(explorer, "isr_coverage", {}) or {}),
            mmio_stats=mmio_stats,
            isr_stack=explorer_stats.get("isr_stack", {}),
            isr_execution_start=explorer_stats.get("execution_start", {}),
            invalid_stack_samples=explorer_stats.get("invalid_stack_samples", []),
            isr_probe_error=probe_error,
            probe_diagnostics=probe_diagnostics[-32:],
            run_result=failure_result,
        )

    def _interrupt_context_snapshot(self, context):
        if isinstance(context, PrefixReplaySnapshot):
            return getattr(context, "snapshot", None)
        if isinstance(context, dict):
            return context.get("snapshot")
        return context

    def _interrupt_context_occurrence_signature(
        self,
        context,
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        if isinstance(context, PrefixReplaySnapshot):
            return normalize_naturalization_signature(
                self._snapshot_entry_occurrence_prefix(context)
            )
        if isinstance(context, dict):
            return normalize_naturalization_signature(
                tuple(
                    context.get("source_occurrence_signature", tuple())
                    or context.get("source_occurrence_trace", tuple())
                    or tuple()
                )
            )
        return tuple()

    def _interrupt_context_mmio_state(self, context) -> Dict[int, int]:
        def intern(normalized: Dict[int, int]):
            # Prefix/root entries are immutable replay descriptors.  Reuse the
            # emulator's weak metadata interner so the same MMIO state is not
            # copied once per provenance entry.
            store = getattr(getattr(self, "emulator", None), "snapshot_metadata_store", None)
            interner = getattr(store, "intern_mapping", None)
            if callable(interner):
                try:
                    return interner(normalized)
                except Exception:
                    pass
            return normalized

        if isinstance(context, PrefixReplaySnapshot):
            state = getattr(context, "mmio_state", {}) or getattr(getattr(context, "snapshot", None), "mmio_state", {}) or {}
            if getattr(state, "is_snapshot_mapping", False):
                return state
            normalized = {}
            for address, value in state.items():
                try:
                    normalized[int(address)] = int(value) & 0xFFFFFFFF
                except Exception:
                    continue
            return intern(normalized)
        if not isinstance(context, dict):
            snapshot_state = getattr(context, "mmio_state", {}) or {}
            if getattr(snapshot_state, "is_snapshot_mapping", False):
                return snapshot_state
            normalized = {}
            for address, value in snapshot_state.items():
                try:
                    normalized[int(address)] = int(value) & 0xFFFFFFFF
                except Exception:
                    continue
            return intern(normalized)
        state = context.get("mmio_state", {}) or {}
        if getattr(state, "is_snapshot_mapping", False):
            return state
        normalized = {}
        for address, value in state.items():
            try:
                normalized[int(address)] = int(value) & 0xFFFFFFFF
            except Exception:
                continue
        return intern(normalized)

    def _select_interrupt_contexts(
        self,
        max_contexts: int = 16,
        include_reservoir_contexts: bool = False,
        max_reservoir_contexts: int = 16,
    ):
        snapshots = self._ordered_replay_snapshots(self.emulator)
        if not snapshots:
            snapshots = []
        if max_contexts == 0:
            selected_main = []
        elif max_contexts is None or max_contexts < 0 or len(snapshots) <= max_contexts:
            selected_main = list(reversed(snapshots))
        else:
            # Latest contexts usually represent fully initialized firmware state.
            # Add a few evenly-spaced earlier contexts so initialization-only
            # interrupt paths are not completely ignored.
            latest_count = max(1, int(max_contexts * 0.75))
            latest = list(reversed(snapshots[-latest_count:]))
            remaining = max_contexts - len(latest)
            if remaining <= 0:
                selected_main = latest
            else:
                prefix = snapshots[:-latest_count]
                if not prefix:
                    selected_main = latest
                elif remaining >= len(prefix):
                    sampled = list(reversed(prefix))
                    selected_main = latest + sampled
                else:
                    sampled = []
                    for index in range(remaining):
                        position = int(index * (len(prefix) - 1) / max(1, remaining - 1))
                        sampled.append(prefix[position])
                    selected_main = latest + list(reversed(sampled))

        if include_reservoir_contexts and max_reservoir_contexts != 0:
            reservoir_contexts = list(reversed(self.reservoir_interrupt_contexts))
            if max_reservoir_contexts and max_reservoir_contexts > 0:
                reservoir_contexts = reservoir_contexts[:max_reservoir_contexts]
            selected_main = reservoir_contexts + selected_main

        seen = set()
        selected = []
        for context in selected_main:
            snapshot = self._interrupt_context_snapshot(context)
            if snapshot is None:
                continue
            registers = getattr(snapshot, "registers", {}) or {}
            identity = (
                snapshot.address,
                registers.get("sp"),
                registers.get("lr"),
                registers.get("pc"),
                self._interrupt_context_occurrence_signature(context),
                tuple(sorted(self._interrupt_context_mmio_state(context).items())),
            )
            if identity in seen:
                continue
            seen.add(identity)
            selected.append(context)
        return selected

    def _prioritized_isr_items(
        self,
        isr_items: Iterable[Tuple[int, int]],
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        max_isrs: int = 0,
        irq_priority: Optional[Dict[int, int]] = None,
    ) -> List[Tuple[int, int]]:
        """
        Rank vector handlers by real uncovered downstream potential.

        Vector tables often contain dozens of aliases to Default_Handler.  A
        plain IRQ-number slice spends the whole contextual-ISR budget on NMI,
        HardFault, and default stubs while high-value UART/USB/CAN/timer
        handlers remain untried.  The ranking keeps execution entry-derived
        but chooses interrupt injections that can actually unlock uncovered BBs.
        """
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        irq_priority = {int(key): int(value) for key, value in (irq_priority or {}).items()}
        scope = self.prepared.valid_bb_set if self.prepared.valid_bb_set else self.prepared.static_bb_set
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}

        def reachable_from(start_bb: Optional[int]) -> Set[int]:
            if start_bb is None or start_bb not in self.prepared.static_bb_set:
                return set()
            cached = reachable_cache.get(int(start_bb))
            if cached is not None:
                return cached
            queue = deque([int(start_bb)])
            seen = {int(start_bb)}
            while queue:
                current = queue.popleft()
                for successor in effective_successors.get(current, set()):
                    successor = int(successor)
                    if successor in seen:
                        continue
                    seen.add(successor)
                    queue.append(successor)
            reachable_cache[int(start_bb)] = seen
            return seen

        def default_like(name: str) -> bool:
            lowered = str(name or "").lower()
            return (
                not lowered
                or "default_handler" in lowered
                or "dummy" in lowered
                or "unused" in lowered
                or "reserved" in lowered
                or "weak" in lowered
            )

        best_by_handler: Dict[int, Tuple[Tuple[int, ...], Tuple[int, int]]] = {}
        for raw_irq, raw_addr in isr_items or []:
            try:
                irq_num = int(raw_irq)
                isr_addr = int(raw_addr) & ~1
            except Exception:
                continue
            start_bb = self.prepared.resolve_basic_block(isr_addr) or isr_addr
            if start_bb not in self.prepared.static_bb_set:
                continue
            reachable = reachable_from(start_bb) & scope
            uncovered = reachable - covered
            target_potential = len((reachable & target_filter) - covered) if target_filter else 0
            function_name = self._function_name_for_addr(int(start_bb))
            semantic_priority = self._semantic_priority_for_bb(int(start_bb))
            is_default = default_like(function_name)
            # Negative IRQs are system exceptions. They are still useful, but
            # external interrupts are more likely to unlock protocol paths.
            external_irq = 1 if irq_num >= 0 else 0
            score = (
                irq_priority.get(irq_num, 0),
                target_potential,
                len(uncovered),
                semantic_priority,
                external_irq,
                0 if is_default else 1,
                -abs(irq_num),
                -irq_num,
            )
            previous = best_by_handler.get(int(start_bb))
            if previous is None or score > previous[0]:
                best_by_handler[int(start_bb)] = (score, (irq_num, isr_addr))

        ranked = sorted(best_by_handler.values(), key=lambda item: item[0], reverse=True)
        selected = [item for _score, item in ranked]
        if max_isrs and max_isrs > 0:
            selected = selected[:max_isrs]
        return selected

    def run_contextual_isr_exploration(
        self,
        max_contexts: int = 16,
        max_isrs: int = 0,
        max_instructions: int = 10000,
        replay_timeout: int = 1_000_000,
        time_limit_seconds: Optional[int] = None,
        include_reservoir_contexts: bool = False,
        max_reservoir_contexts: int = 16,
        phase_name: str = "contextual_isr",
    ) -> Set[int]:
        """
        Trigger vector ISRs from real main-path dynamic states.

        Plain ISR probing starts each handler from a cold artificial context.
        This phase restores branch snapshots recorded on the main path, preserves
        the interrupted registers, primes common peripheral interrupt flags, and
        then enters the handler. It models "an interrupt fires here" without
        inventing arbitrary code-entry PCs.
        """
        start_time = time.time()
        contexts = self._select_interrupt_contexts(
            max_contexts,
            include_reservoir_contexts=include_reservoir_contexts,
            max_reservoir_contexts=max_reservoir_contexts,
        )
        phase_covered: Set[int] = set()
        context_attempts = 0
        isr_attempts = 0
        isr_started = 0
        contexts_with_new_coverage = 0
        isrs_with_new_coverage = 0
        total_new_from_contexts = 0
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        isr_stack_stats = Counter()
        isr_execution_start_stats = Counter()
        child_execution_interventions: Counter[str] = Counter()
        child_execution_count = 0
        child_execution_records: List[Dict[str, object]] = []
        invalid_stack_samples: List[Dict[str, object]] = []
        learned_irq_candidates: List[Dict[str, object]] = []
        isr_items: List[Tuple[int, int]] = []

        probe_emulator = None
        probe_mmio = None
        probe_error: Optional[str] = None
        probe_diagnostics: List[Dict[str, object]] = []
        try:
            probe_emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=self._effective_llm_config_path(),
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=self._temp_stage_for("contextual_isr_probe"),
            )
            probe_mmio = EnhancedMMIOHandler(
                probe_emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            probe_mmio.mmio_state.update(getattr(self.mmio_handler, "mmio_state", {}))
            probe_mmio.mark_mmio_state_explicit()
            probe_explorer = ISRExplorer(
                probe_emulator.uc,
                self.prepared.static_bbs,
                vtor=self._vector_table_base(),
                mmio_handler=probe_mmio,
                instruction_to_bb=self.prepared.instruction_to_bb,
                broad_interrupt_flags=True,
                code_ranges=self._code_address_ranges(),
                start_validator=lambda start_pc: probe_emulator._execution_preflight(start_pc),
                causal_context=probe_emulator.causal_context,
            )
            learned_irq_candidates = probe_explorer.learned_irq_candidates(limit=128)
            learned_irq_priority = {
                int(item["irq"]): int(item.get("score", 0) or 0)
                for item in learned_irq_candidates
            }
            isr_items = self._prioritized_isr_items(
                list(probe_explorer.isr_addresses.items()),
                coverage=self.global_coverage | phase_covered,
                max_isrs=max_isrs,
                irq_priority=learned_irq_priority,
            )
        except Exception as exc:
            probe_error = f"{type(exc).__name__}: {str(exc)[:512]}"
            isr_items = []
            probe_diagnostics.append(
                self._record_probe_diagnostic(
                    "contextual_isr_probe",
                    "probe_execution_exception",
                    error=exc,
                    contexts_selected=len(contexts),
                )
            )
            logger.debug("contextual ISR probe failed: %s", exc)
        finally:
            if probe_emulator is not None:
                try:
                    cleanup_error = self._safe_dispose_temp_emulator(
                        probe_emulator,
                        mmio_handler=probe_mmio,
                        quarantine=None,
                        stage_name=self._temp_stage_for("contextual_isr_probe"),
                    )
                    if cleanup_error:
                        probe_error = (
                            f"{probe_error}; probe_cleanup_exception: {cleanup_error}"
                            if probe_error
                            else f"probe_cleanup_exception: {cleanup_error}"
                        )
                        probe_diagnostics.append(
                            self._record_probe_diagnostic(
                                "contextual_isr_probe",
                                "probe_cleanup_exception",
                                error=cleanup_error,
                            )
                        )
                        logger.debug(
                            "contextual ISR probe cleanup failed: %s",
                            cleanup_error,
                        )
                except Exception as cleanup_error:
                    # The probe is advisory.  A teardown failure must be
                    # visible in phase metadata, but cannot prevent the
                    # context-derived ISR replays from being attempted.
                    cleanup_text = (
                        f"{type(cleanup_error).__name__}: "
                        f"{str(cleanup_error)[:512]}"
                    )
                    probe_error = (
                        f"{probe_error}; probe_cleanup_exception: {cleanup_text}"
                        if probe_error
                        else f"probe_cleanup_exception: {cleanup_text}"
                    )
                    probe_diagnostics.append(
                        self._record_probe_diagnostic(
                            "contextual_isr_probe",
                            "probe_cleanup_exception",
                            error=cleanup_error,
                        )
                    )
                    logger.debug(
                        "contextual ISR probe cleanup failed: %s",
                        cleanup_error,
                    )

        def budget_exhausted() -> bool:
            return bool(time_limit_seconds and time.time() - start_time > time_limit_seconds)

        for context in contexts:
            if budget_exhausted():
                break
            context_attempts += 1
            context_new_before = len(phase_covered - self.global_coverage)
            snapshot = self._interrupt_context_snapshot(context)
            if snapshot is None:
                continue

            for irq_num, isr_addr in isr_items:
                if budget_exhausted():
                    break
                child_execution_count += 1
                try:
                    emulator = self._new_temp_emulator(
                        max_snapshots=max(3, self.max_snapshots),
                        llm_config_path=self._effective_llm_config_path(),
                        constraint_json_path=self.constraint_file,
                        branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                        stage_name=self._temp_stage_for("contextual_isr_handler_replay"),
                    )
                except Exception as exc:
                    child_execution_records.append(
                        self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "contextual_isr"),
                            execution_id=(
                                f"{str(phase_name or 'contextual_isr')}-attempt-"
                                f"{child_execution_count}"
                            ),
                            reason="emulator_create_exception",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_context_snapshot_event_replay"
                                ),
                                "context_snapshot_mode": True,
                                "coverage_counted": True,
                                "irq": int(irq_num),
                                "isr_address": int(isr_addr) & 0xFFFFFFFF,
                            },
                            execution_started=False,
                            execution_error=exc,
                        )
                    )
                    child_execution_interventions["emulator_create_exception"] += 1
                    logger.debug("contextual ISR emulator创建失败: %s", exc)
                    continue
                temp_mmio = None
                explorer = None
                execution_baseline: Optional[Mapping[str, object]] = None
                finalization_result: Dict[str, object] = {}
                attempt_recorded = False
                execution_record: Optional[Dict[str, object]] = None
                covered: Set[int] = set()
                valid: Set[int] = set()

                try:
                    emulator.enable_branch_snapshot = True
                    emulator.enable_loop_intervention = False
                    temp_mmio = EnhancedMMIOHandler(
                        emulator.uc,
                        self.constraint_file,
                        branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                    )
                    temp_mmio.mmio_state.update(getattr(self.mmio_handler, "mmio_state", {}))
                    temp_mmio.mmio_state.update(self._interrupt_context_mmio_state(context))
                    temp_mmio.mark_mmio_state_explicit()
                    explorer = ISRExplorer(
                        emulator.uc,
                        self.prepared.static_bbs,
                        vtor=self._vector_table_base(),
                        mmio_handler=temp_mmio,
                        instruction_to_bb=self.prepared.instruction_to_bb,
                        broad_interrupt_flags=True,
                        code_ranges=self._code_address_ranges(),
                        start_validator=lambda start_pc: emulator._execution_preflight(start_pc),
                        causal_context=emulator.causal_context,
                    )
                    if not self._restore_branch_snapshot(
                        emulator,
                        snapshot,
                        lineage_source=(
                            context
                            if isinstance(context, PrefixReplaySnapshot)
                            else None
                        ),
                    ):
                        failed_record = self._direct_execution_evidence_record(
                            phase_name=str(phase_name or "contextual_isr"),
                            emulator=emulator,
                            covered_bbs=(),
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_context_snapshot_event_replay"
                                ),
                                "context_snapshot_mode": True,
                                "coverage_counted": True,
                                "irq": int(irq_num),
                                "isr_address": int(isr_addr) & 0xFFFFFFFF,
                            },
                            execution_started=False,
                            execution_error="snapshot_restore_failed",
                            execution_baseline=execution_baseline,
                            mmio_handler=temp_mmio,
                        )
                        child_execution_records.append(failed_record)
                        execution_record = failed_record
                        attempt_recorded = True
                        child_execution_interventions.update(
                            failed_record.get("actual_intervention_reasons", []) or []
                        )
                        continue

                    if not self._restore_replay_mmio_state(
                        emulator,
                        temp_mmio,
                        self._interrupt_context_mmio_state(context),
                    ):
                        failed_record = self._direct_execution_evidence_record(
                            phase_name=str(phase_name or "contextual_isr"),
                            emulator=emulator,
                            covered_bbs=(),
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_context_snapshot_event_replay"
                                ),
                                "context_snapshot_mode": True,
                                "coverage_counted": True,
                                "irq": int(irq_num),
                                "isr_address": int(isr_addr) & 0xFFFFFFFF,
                            },
                            execution_started=False,
                            execution_error=self._replay_mmio_restore_failure_reason(
                                emulator
                            ),
                            execution_baseline=execution_baseline,
                            mmio_handler=temp_mmio,
                        )
                        child_execution_records.append(failed_record)
                        execution_record = failed_record
                        attempt_recorded = True
                        child_execution_interventions.update(
                            failed_record.get("actual_intervention_reasons", []) or []
                        )
                        continue

                    isr_attempts += 1
                    known_before = self.global_coverage | phase_covered
                    started = False
                    execution_error: Optional[str] = None
                    with self.guided_modules(temp_mmio), self.capture_coverage(emulator) as covered:
                        try:
                            return_pc = emulator.uc.reg_read(UC_ARM_REG_PC)
                            explorer._setup_isr_context(
                                isr_addr,
                                irq_num,
                                preserve_registers=True,
                                return_pc=return_pc,
                            )
                            # The snapshot restores cumulative peripheral
                            # telemetry.  Establish the direct-attempt
                            # baseline only after every restore and context
                            # setup has completed, immediately before native
                            # execution begins.
                            execution_baseline = self._capture_direct_execution_baseline(
                                emulator,
                                str(phase_name or "contextual_isr"),
                                mmio_handler=temp_mmio,
                            )
                            self._begin_direct_execution(emulator)
                            started = bool(explorer.start_isr_execution(
                                isr_addr | 1,
                                timeout=replay_timeout,
                                count=max_instructions,
                            ))
                            if started:
                                isr_started += 1
                            else:
                                execution_error = "isr_start_failed"
                        except Exception as exc:
                            execution_error = (
                                f"{type(exc).__name__}: {str(exc)[:512]}"
                            )
                        finally:
                            finalization_result = self._finalize_direct_execution(
                                emulator,
                                execution_baseline,
                                execution_started=started,
                                execution_error=execution_error,
                            )

                    if finalization_result.get("finalization_error"):
                        invalidation = self._invalidate_temp_emulator_snapshot_provenance(
                            emulator,
                            execution_baseline=execution_baseline,
                            reason="direct_execution_finalization_exception",
                            error=finalization_result.get("finalization_error"),
                        )
                        finalization_result["provenance_invalidated"] = True
                        finalization_result[
                            "provenance_invalidation_reasons"
                        ] = ["direct_execution_finalization_exception"]
                        finalization_result[
                            "invalidated_snapshots"
                        ] = int(invalidation.get("invalidated_snapshots", 0) or 0)

                    execution_record = self._direct_execution_evidence_record(
                        phase_name=str(phase_name or "contextual_isr"),
                        emulator=emulator,
                        covered_bbs=covered,
                        metadata={
                            "entry_derivation": (
                                "entry_derived_context_snapshot_event_replay"
                            ),
                            "context_snapshot_mode": True,
                            "coverage_counted": True,
                            "irq": int(irq_num),
                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                        },
                        execution_started=started,
                        execution_error=execution_error,
                        execution_baseline=execution_baseline,
                        mmio_handler=temp_mmio,
                        finalization_result=finalization_result,
                    )
                    child_execution_records.append(execution_record)
                    attempt_recorded = True
                    child_execution_interventions.update(
                        execution_record.get("actual_intervention_reasons", []) or []
                    )

                    valid = self.validate_coverage(covered)
                    explorer_stats = explorer.get_statistics()
                    isr_stack_stats.update(explorer_stats.get("isr_stack", {}) or {})
                    isr_execution_start_stats.update(
                        explorer_stats.get("execution_start", {}) or {}
                    )
                    invalid_stack_samples.extend(explorer_stats.get("invalid_stack_samples", []) or [])
                    if len(invalid_stack_samples) > 32:
                        invalid_stack_samples = invalid_stack_samples[-32:]
                    new_bbs = valid - known_before
                    if new_bbs:
                        isrs_with_new_coverage += 1
                        total_new_from_contexts += len(new_bbs)
                    phase_covered.update(valid)
                    self._record_coverage_evidence(EVIDENCE_E3, valid)
                    context_events = emulator.branch_snapshot_manager.get_ordered_events()
                    context_snapshots = self._ordered_replay_snapshots(emulator)
                    remembered_branch_events += self._remember_main_branch_events(
                        context_events,
                        evidence_class=EVIDENCE_E3,
                    )
                    remembered_branch_root_snapshots += self._remember_branch_root_snapshots(
                        context_events,
                        context_snapshots,
                        source_path_signature=(
                            getattr(context, "source_path_signature", tuple())
                            if not isinstance(context, dict)
                            else context.get("source_path_signature", tuple())
                        ) or tuple(),
                        evidence_class=EVIDENCE_E3,
                        occurrence_events=(
                            emulator.branch_snapshot_manager
                            .get_ordered_occurrence_events()
                        ),
                        source_occurrence_signature=(
                            self._interrupt_context_occurrence_signature(context)
                        ),
                    )
                    dynamic_successor_edges_added += self._record_dynamic_successors(context_events)
                    dynamic_successor_edges_added += (
                        self._record_emulator_runtime_successors(emulator)
                    )
                except Exception as exc:
                    # Once a record exists, this is a result-collection
                    # failure for the same attempt.  Preserve observed BBs as
                    # diagnostics, but do not leave the earlier record
                    # looking like a strict witness.
                    try:
                        observed_valid = self.validate_coverage(covered)
                    except Exception:
                        observed_valid = set()
                    if execution_record is not None:
                        self._downgrade_execution_evidence_record(
                            execution_record,
                            reason=(
                                "replay_result_collection_exception"
                                if attempt_recorded
                                else "replay_setup_exception"
                            ),
                            error=exc,
                        )
                        phase_covered.update(observed_valid)
                        if observed_valid:
                            try:
                                self._record_coverage_evidence(
                                    EVIDENCE_E3,
                                    observed_valid,
                                )
                            except Exception:
                                pass
                        child_execution_interventions[
                            "replay_result_collection_exception"
                        ] += 1
                    else:
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "contextual_isr"),
                            execution_id=(
                                f"{str(phase_name or 'contextual_isr')}-attempt-"
                                f"{child_execution_count}"
                            ),
                            reason="replay_setup_exception",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_context_snapshot_event_replay"
                                ),
                                "context_snapshot_mode": True,
                                "coverage_counted": True,
                                "irq": int(irq_num),
                                "isr_address": int(isr_addr) & 0xFFFFFFFF,
                            },
                            covered_bbs=observed_valid,
                            execution_started=False,
                            execution_error=exc,
                            execution_baseline=execution_baseline,
                        )
                        child_execution_records.append(failure_record)
                        execution_record = failure_record
                        child_execution_interventions["replay_setup_exception"] += 1
                    logger.debug("contextual ISR replay failed: %s", exc)
                    continue
                finally:
                    try:
                        cleanup_error = self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            quarantine=None,
                            stage_name=self._temp_stage_for("contextual_isr_replay"),
                            evidence_record=execution_record,
                        )
                        if cleanup_error:
                            if execution_record is None:
                                child_execution_records.append(
                                    self._execution_failure_evidence_record(
                                        phase_name=str(
                                            phase_name or "contextual_isr"
                                        ),
                                        execution_id=(
                                            f"{str(phase_name or 'contextual_isr')}-"
                                            f"attempt-{child_execution_count}-cleanup"
                                        ),
                                        reason="replay_cleanup_exception",
                                        metadata={
                                            "entry_derivation": (
                                                "entry_derived_context_snapshot_event_replay"
                                            ),
                                            "context_snapshot_mode": True,
                                            "coverage_counted": True,
                                            "irq": int(irq_num),
                                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                                        },
                                        covered_bbs=valid or covered,
                                        execution_started=False,
                                        execution_error=cleanup_error,
                                    )
                                )
                            child_execution_interventions[
                                "replay_cleanup_exception"
                            ] += 1
                            logger.debug(
                                "contextual ISR replay cleanup failed: %s",
                                cleanup_error,
                            )
                    except Exception as cleanup_error:
                        # Teardown is part of the evidence boundary.  A
                        # failed teardown invalidates this child witness but
                        # must not abort the remaining contexts or ISRs.
                        if execution_record is not None:
                            self._downgrade_execution_evidence_record(
                                execution_record,
                                reason="replay_cleanup_exception",
                                error=cleanup_error,
                            )
                        else:
                            child_execution_records.append(
                                self._execution_failure_evidence_record(
                                    phase_name=str(
                                        phase_name or "contextual_isr"
                                    ),
                                    execution_id=(
                                        f"{str(phase_name or 'contextual_isr')}-"
                                        f"attempt-{child_execution_count}-cleanup"
                                    ),
                                    reason="replay_cleanup_exception",
                                    metadata={
                                        "entry_derivation": (
                                            "entry_derived_context_snapshot_event_replay"
                                        ),
                                        "context_snapshot_mode": True,
                                        "coverage_counted": True,
                                        "irq": int(irq_num),
                                        "isr_address": int(isr_addr) & 0xFFFFFFFF,
                                    },
                                    covered_bbs=valid or covered,
                                    execution_started=False,
                                    execution_error=cleanup_error,
                                )
                            )
                        child_execution_interventions[
                            "replay_cleanup_exception"
                        ] += 1
                        logger.debug(
                            "contextual ISR replay cleanup failed: %s",
                            cleanup_error,
                        )

            if len(phase_covered - self.global_coverage) > context_new_before:
                contexts_with_new_coverage += 1

        return self._record_phase(
            str(phase_name or "contextual_isr"),
            phase_covered,
            entry_derivation="entry_derived_context_snapshot_event_replay",
            context_snapshot_mode=True,
            child_execution_summary=self._child_execution_summary(
                child_execution_count,
                child_execution_interventions,
                expected_count=child_execution_count,
                execution_records=child_execution_records,
            ),
            contexts_selected=len(contexts),
            context_attempts=context_attempts,
            vector_isrs=len(isr_items),
            isr_attempts=isr_attempts,
            isr_started=isr_started,
            contexts_with_new_coverage=contexts_with_new_coverage,
            isrs_with_new_coverage=isrs_with_new_coverage,
            total_new_from_contexts=total_new_from_contexts,
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            known_branch_root_snapshots=len(self.known_branch_root_snapshots),
            known_branch_root_snapshot_variants=self._known_branch_root_snapshot_variant_count(),
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            learned_irq_candidates=learned_irq_candidates[:32],
            learned_irq_candidate_count=len(learned_irq_candidates),
            isr_probe_error=probe_error,
            probe_diagnostics=probe_diagnostics[-32:],
            isr_stack=dict(isr_stack_stats),
            isr_execution_start=dict(isr_execution_start_stats),
            invalid_stack_samples=invalid_stack_samples[-32:],
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            time_limit_seconds=time_limit_seconds,
            include_reservoir_contexts=include_reservoir_contexts,
            reservoir_contexts_available=len(self.reservoir_interrupt_contexts),
            max_reservoir_contexts=max_reservoir_contexts,
        )

    def _direct_call_frontier_candidates(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 0,
    ) -> List[Dict[str, object]]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if self.prepared.valid_bb_set else self.prepared.static_bb_set
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        far_target_distance = 1_000_000_000
        near_target_distance = max(
            0,
            _env_int("LSGEMU_DIRECT_CALL_DOWNSTREAM_NEAR_TARGET_DISTANCE", 2),
        )
        target_distance = self._static_target_distance_lookup(
            target_filter,
            effective_successors,
            far_target_distance,
        )
        candidates: List[Dict[str, object]] = []
        backup_with_primary_limit = max(
            0,
            _env_int("LSGEMU_DIRECT_CALL_DOWNSTREAM_BACKUP_WITH_PRIMARY", 0),
        )
        backup_only_successor_limit = max(
            0,
            _env_int(
                "LSGEMU_DIRECT_CALL_DOWNSTREAM_BACKUP_ONLY_SUCCESSORS",
                1 if target_filter else 0,
            ),
        )
        backup_candidate_limit = max(
            0,
            _env_int(
                "LSGEMU_DIRECT_CALL_DOWNSTREAM_BACKUP_CANDIDATES",
                8 if target_filter else 0,
            ),
        )

        def downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        def downstream_targets(start_bb: int) -> Set[int]:
            if not target_filter:
                return set()
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return reachable & target_filter

        def item_target_distance(item: Dict[str, object]) -> int:
            value = item.get("target_min_distance", far_target_distance)
            if value is None:
                return far_target_distance
            try:
                return int(value)
            except (TypeError, ValueError):
                return far_target_distance

        for pred_bb in sorted(covered):
            insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
            if not _is_direct_call_mnemonic(insn.get("mnemonic")):
                continue
            branch_pc = int(insn.get("address", pred_bb) or pred_bb)
            snapshot_entries = self._rank_direct_call_snapshot_entries(
                int(pred_bb),
                branch_pc,
                self._direct_call_snapshot_entries(int(pred_bb)),
            )
            if not snapshot_entries:
                continue
            unattempted_snapshot_entries = [
                entry
                for entry in snapshot_entries
                if self._direct_call_attempt_key(int(pred_bb), entry)
                not in self.direct_call_snapshot_attempts_seen
            ]
            if not unattempted_snapshot_entries:
                continue
            failure_penalties = {
                self._snapshot_entry_identity(entry): self._direct_call_failure_penalty(
                    int(pred_bb),
                    entry,
                )
                for entry in unattempted_snapshot_entries
            }
            min_failure_penalty = min(failure_penalties.values(), default=0)

            successors: List[int] = []
            direct_target_bb = None
            fallthrough_bb = None
            direct_target = _parse_direct_target(insn.get("operands"))
            if direct_target is not None:
                resolved = self.prepared.resolve_basic_block(direct_target)
                if resolved is not None:
                    direct_target_bb = int(resolved)
                    successors.append(direct_target_bb)
            try:
                fallthrough = int(insn.get("address", pred_bb) or pred_bb) + int(insn.get("size", 2) or 2)
                resolved_fallthrough = self.prepared.resolve_basic_block(fallthrough)
                if resolved_fallthrough is not None:
                    fallthrough_bb = int(resolved_fallthrough)
                    successors.append(fallthrough_bb)
            except Exception:
                pass
            successors.extend(sorted(effective_successors.get(int(pred_bb), set())))
            successors = _dedupe_preserve_order(
                successor
                for successor in successors
                if successor in scope
            )
            if not successors:
                continue

            successor_items: List[Dict[str, object]] = []
            for successor in successors:
                successor = int(successor)
                reachable = self._static_reachable_from_cached(
                    successor,
                    effective_successors,
                    reachable_cache,
                )
                uncovered_downstream = (reachable & scope) - covered
                target_matches = downstream_targets(successor)
                immediate_target_match = successor in target_filter if target_filter else False
                target_min_distance = target_distance(successor) if target_matches else far_target_distance
                semantic_categories = self._semantic_categories_for_bb(successor)
                semantic_priority = self._semantic_category_priority(semantic_categories)
                should_schedule = False
                reason = "none"
                if target_filter:
                    if target_matches:
                        should_schedule = True
                        reason = (
                            "target_filter_immediate"
                            if immediate_target_match
                            else (
                                "target_filter_near_downstream"
                                if target_min_distance <= near_target_distance
                                else "target_filter_downstream"
                            )
                        )
                elif successor not in covered:
                    should_schedule = True
                    reason = "uncovered_immediate_successor"
                elif uncovered_downstream:
                    should_schedule = True
                    reason = "covered_successor_downstream"
                if not should_schedule:
                    continue
                is_primary_successor = bool(
                    successor not in covered
                    or reason in {"target_filter_immediate", "target_filter_near_downstream"}
                )
                successor_items.append({
                    "successor": successor,
                    "uncovered_immediate": successor not in covered,
                    "backup_candidate": not is_primary_successor,
                    "schedule_reason": reason,
                    "downstream_potential": len(uncovered_downstream),
                    "target_min_distance": target_min_distance,
                    "semantic_priority": semantic_priority,
                    "semantic_categories": sorted(semantic_categories),
                    "target_filter_matches": len(target_matches),
                    "target_filter_match_list": sorted(target_matches)[:16],
                })
            if not successor_items:
                continue
            successor_items.sort(
                key=lambda item: (
                    1 if not bool(item.get("backup_candidate")) else 0,
                    -item_target_distance(item),
                    int(item.get("target_filter_matches", 0) or 0),
                    int(item.get("semantic_priority", 0) or 0),
                    1 if item.get("uncovered_immediate") else 0,
                    int(item.get("downstream_potential", 0) or 0),
                    -int(item.get("successor", 0) or 0),
                ),
                reverse=True,
            )
            primary_successor_items = [
                item for item in successor_items
                if not bool(item.get("backup_candidate"))
            ]
            backup_successor_items = [
                item for item in successor_items
                if bool(item.get("backup_candidate"))
            ]
            if primary_successor_items:
                successor_items = (
                    primary_successor_items
                    + backup_successor_items[:backup_with_primary_limit]
                )
            else:
                successor_items = backup_successor_items[:backup_only_successor_limit]
            if not successor_items:
                continue
            uncovered_successors = [
                int(item["successor"])
                for item in successor_items
                if bool(item.get("uncovered_immediate"))
            ]
            scheduled_successors = [int(item["successor"]) for item in successor_items]
            successor_potential = {
                int(successor): downstream_potential(int(successor))
                for successor in scheduled_successors
            }
            target_filter_matches = (
                sum(int(item.get("target_filter_matches", 0) or 0) for item in successor_items)
                if target_filter
                else 0
            )
            min_target_distance = min(
                (
                    item_target_distance(item)
                    for item in successor_items
                ),
                default=far_target_distance,
            )

            candidates.append({
                "pred_bb": int(pred_bb),
                "successors": successors,
                "uncovered_successors": uncovered_successors,
                "scheduled_successors": scheduled_successors,
                "successor_items": successor_items,
                "snapshot_entries": snapshot_entries,
                "unattempted_snapshot_entries": unattempted_snapshot_entries,
                "unattempted_snapshot_count": len(unattempted_snapshot_entries),
                "direct_target_successor": direct_target_bb,
                "fallthrough_successor": fallthrough_bb,
                "return_fallthrough_uncovered": bool(
                    fallthrough_bb is not None and fallthrough_bb in uncovered_successors
                ),
                "target_filter_matches": target_filter_matches,
                "target_min_distance": min_target_distance,
                "primary_successor_count": sum(
                    1 for item in successor_items
                    if not bool(item.get("backup_candidate"))
                ),
                "backup_successor_count": sum(
                    1 for item in successor_items
                    if bool(item.get("backup_candidate"))
                ),
                "downstream_potential": sum(successor_potential.values()),
                "max_successor_downstream_potential": max(successor_potential.values(), default=0),
                "semantic_priority": max(
                    int(item.get("semantic_priority", 0) or 0)
                    for item in successor_items
                ),
                "semantic_priority_total": sum(
                    int(item.get("semantic_priority", 0) or 0)
                    for item in successor_items
                ),
                "min_failure_penalty": min_failure_penalty,
                "snapshot_prelude_rank_sample": [
                    self._direct_call_snapshot_prelude_stats(
                        int(pred_bb),
                        branch_pc,
                        entry,
                        max_records=3,
                    )
                    for entry in snapshot_entries[:3]
                ],
            })

        candidates.sort(
            key=lambda item: (
                int(item.get("primary_successor_count", 0) or 0),
                -item_target_distance(item),
                int(item.get("target_filter_matches", 0) or 0),
                int(item.get("semantic_priority", 0) or 0),
                int(item.get("semantic_priority_total", 0) or 0),
                1 if item.get("return_fallthrough_uncovered") else 0,
                -int(item.get("min_failure_penalty", 0) or 0),
                int(item.get("downstream_potential", 0) or 0),
                int(item.get("max_successor_downstream_potential", 0) or 0),
                len(item["uncovered_successors"]),
                int(item.get("unattempted_snapshot_count", 0) or 0),
                -int(item["pred_bb"]),
            ),
            reverse=True,
        )
        primary_candidates = [
            item for item in candidates
            if int(item.get("primary_successor_count", 0) or 0) > 0
        ]
        backup_candidates = [
            item for item in candidates
            if int(item.get("primary_successor_count", 0) or 0) <= 0
        ]
        if primary_candidates:
            candidates = primary_candidates + backup_candidates[:backup_candidate_limit]
        elif backup_candidate_limit > 0:
            candidates = backup_candidates[:backup_candidate_limit]
        else:
            candidates = []
        candidates = _segment_rotate_sequence(candidates, "direct_call_candidates")
        if max_targets and max_targets > 0:
            candidates = candidates[:max_targets]
        return candidates

    def _direct_call_candidate_diagnostics(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        valid_only: bool = True,
        max_samples: int = 16,
    ) -> Dict[str, object]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = (
            self.prepared.valid_bb_set
            if valid_only and self.prepared.valid_bb_set
            else self.prepared.static_bb_set
        )
        scope = set(scope)
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        far_target_distance = 1_000_000_000
        near_target_distance = max(
            0,
            _env_int("LSGEMU_DIRECT_CALL_DOWNSTREAM_NEAR_TARGET_DISTANCE", 2),
        )
        target_distance = self._static_target_distance_lookup(
            target_filter,
            effective_successors,
            far_target_distance,
        )
        counters: Counter[str] = Counter()
        mnemonic_counters: Counter[str] = Counter()
        samples: Dict[str, List[Dict[str, object]]] = defaultdict(list)

        def remember(reason: str, pred_bb: int, successor: Optional[int] = None, extra: Optional[Dict[str, object]] = None) -> None:
            counters[reason] += 1
            mnemonic_counters["BL"] += 1
            if len(samples[reason]) >= max(0, max_samples):
                return
            record = {
                "pred_bb": f"0x{int(pred_bb) & 0xFFFFFFFF:08x}",
                "mnemonic": "BL",
            }
            if successor is not None:
                record["successor_bb"] = f"0x{int(successor) & 0xFFFFFFFF:08x}"
            if extra:
                record.update(extra)
            samples[reason].append(record)

        for pred_bb, insn in sorted(self.prepared.branch_instruction_by_bb.items()):
            pred_bb = int(pred_bb)
            if not _is_direct_call_mnemonic(insn.get("mnemonic")):
                continue
            if pred_bb not in covered:
                remember("pred_not_covered", pred_bb)
                continue

            snapshot_entries = self._direct_call_snapshot_entries(pred_bb)
            if not snapshot_entries:
                remember("no_direct_call_snapshot", pred_bb)
                continue
            unattempted_snapshot_entries = [
                entry
                for entry in snapshot_entries
                if self._direct_call_attempt_key(pred_bb, entry)
                not in self.direct_call_snapshot_attempts_seen
            ]
            if not unattempted_snapshot_entries:
                remember(
                    "all_snapshots_already_attempted",
                    pred_bb,
                    extra={"snapshot_count": len(snapshot_entries)},
                )
                continue
            runnable_entries = [
                entry
                for entry in unattempted_snapshot_entries
                if self._direct_call_failure_penalty(pred_bb, entry) < 64
            ]
            if not runnable_entries:
                remember(
                    "all_snapshots_failure_penalized",
                    pred_bb,
                    extra={"unattempted_snapshot_count": len(unattempted_snapshot_entries)},
                )
                continue

            successors: List[int] = []
            direct_target = _parse_direct_target(insn.get("operands"))
            if direct_target is not None:
                resolved = self.prepared.resolve_basic_block(direct_target)
                if resolved is not None:
                    successors.append(int(resolved))
            try:
                fallthrough = int(insn.get("address", pred_bb) or pred_bb) + int(insn.get("size", 2) or 2)
                resolved_fallthrough = self.prepared.resolve_basic_block(fallthrough)
                if resolved_fallthrough is not None:
                    successors.append(int(resolved_fallthrough))
            except Exception:
                pass
            successors.extend(sorted(effective_successors.get(pred_bb, set())))
            successors = _dedupe_preserve_order(
                successor
                for successor in successors
                if int(successor) in scope
            )
            if not successors:
                remember("no_successors", pred_bb)
                continue

            edge_had_candidate = False
            for successor in successors:
                successor = int(successor)
                if successor not in scope:
                    remember("successor_out_of_scope", pred_bb, successor)
                    continue
                reachable = self._static_reachable_from_cached(
                    successor,
                    effective_successors,
                    reachable_cache,
                )
                uncovered_downstream = (reachable & scope) - covered
                target_matches = (reachable & target_filter) if target_filter else set()
                immediate_target_match = successor in target_filter if target_filter else False
                target_min_distance = target_distance(successor) if target_matches else far_target_distance
                if target_filter:
                    if target_matches:
                        edge_had_candidate = True
                        candidate_reason = (
                            "candidate_ready_target_immediate"
                            if immediate_target_match
                            else (
                                "candidate_ready_target_near_downstream"
                                if target_min_distance <= near_target_distance
                                else "candidate_ready_target_downstream"
                            )
                        )
                        remember(
                            candidate_reason,
                            pred_bb,
                            successor,
                            extra={
                                "target_matches": len(target_matches),
                                "target_min_distance": target_min_distance,
                                "uncovered_downstream": len(uncovered_downstream),
                                "snapshot_count": len(snapshot_entries),
                            },
                        )
                    else:
                        remember("target_filter_no_downstream_match", pred_bb, successor)
                    continue
                if successor not in covered:
                    edge_had_candidate = True
                    remember(
                        "candidate_ready_uncovered_immediate",
                        pred_bb,
                        successor,
                        extra={
                            "uncovered_downstream": len(uncovered_downstream),
                            "snapshot_count": len(snapshot_entries),
                        },
                    )
                elif uncovered_downstream:
                    edge_had_candidate = True
                    remember(
                        "candidate_ready_covered_successor_downstream",
                        pred_bb,
                        successor,
                        extra={
                            "uncovered_downstream": len(uncovered_downstream),
                            "snapshot_count": len(snapshot_entries),
                        },
                    )
                else:
                    remember("successor_already_covered_no_downstream", pred_bb, successor)
            if not edge_had_candidate:
                counters["direct_call_without_candidate_successor"] += 1

        return {
            "coverage_bbs": len(covered),
            "direct_call_snapshot_addresses": len(self.direct_call_snapshots),
            "direct_call_snapshot_variants": sum(len(entries) for entries in self.direct_call_snapshots.values()),
            "direct_call_attempts_seen": len(self.direct_call_snapshot_attempts_seen),
            "effective_successor_sources": len(effective_successors),
            "effective_successor_edges": sum(len(successors) for successors in effective_successors.values()),
            "reason_counts": dict(counters),
            "top_mnemonics": dict(mnemonic_counters.most_common(8)),
            "samples": {reason: rows for reason, rows in samples.items()},
        }

    def _it_predicate_fallthrough_bb(self, pred_bb: int) -> Optional[int]:
        """Return the BB reached when a Thumb IT predicate is not satisfied."""
        instructions = self.prepared.static_bbs.get(int(pred_bb), [])
        if not instructions:
            return None
        last_insn = instructions[-1]
        if _it_predicate_token_for_instruction(last_insn) is None:
            return None

        it_insn = None
        for insn in reversed(instructions[:-1]):
            mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
            if mnemonic.startswith("IT"):
                it_insn = insn
                break
        if it_insn is None:
            return None

        it_mnemonic = _normalize_mnemonic(it_insn.get("mnemonic"))
        predicated_count = max(1, len(it_mnemonic) - 1)
        predicated_seen = 0
        fallthrough_addr = None
        for insn in instructions:
            if int(insn.get("address", 0) or 0) <= int(it_insn.get("address", 0) or 0):
                continue
            if _predicated_condition_for_mnemonic(insn.get("mnemonic")) is None:
                continue
            predicated_seen += 1
            fallthrough_addr = int(insn.get("address", pred_bb) or pred_bb) + int(insn.get("size", 2) or 2)

        if fallthrough_addr is None:
            return None

        remaining = max(0, predicated_count - predicated_seen)
        cursor = int(fallthrough_addr)
        while remaining > 0:
            owner = self.prepared.instruction_to_bb.get(cursor)
            next_insn = None
            if owner is not None:
                for candidate in self.prepared.static_bbs.get(owner, []):
                    if int(candidate.get("address", 0) or 0) == cursor:
                        next_insn = candidate
                        break
            if next_insn is None:
                break
            cursor = int(next_insn.get("address", cursor) or cursor) + int(next_insn.get("size", 2) or 2)
            remaining -= 1

        return self.prepared.resolve_basic_block(cursor)

    def _frontier_successor_choice(self, pred_bb: int, successor_bb: int) -> Optional[object]:
        insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
        mnemonic = _dispatch_mnemonic_for_instruction(insn)
        if not _is_dispatch_frontier_mnemonic(mnemonic):
            return None

        normalized_successor = int(successor_bb)
        if mnemonic.startswith("IT") and mnemonic[2:] in THUMB_CONDITION_CODES:
            fallthrough_bb = self._it_predicate_fallthrough_bb(int(pred_bb))
            if fallthrough_bb is not None and int(fallthrough_bb) == normalized_successor:
                return False

        event_items = [
            (key, event)
            for key, event in self.known_main_branch_events.items()
            if int(key[0]) == int(pred_bb)
        ]
        for _event_key, event in sorted(
            event_items,
            key=lambda item: (
                int(getattr(item[1], "first_occurrence_index", getattr(item[1], "occurrence_index", 1)) or 1),
                int(getattr(item[1], "first_order", getattr(item[1], "order", 0)) or 0),
            ),
        ):
            event_condition = _normalize_mnemonic(getattr(event, "condition", ""))
            if event_condition != mnemonic:
                if not (
                    _is_call_frontier_mnemonic(event_condition)
                    and _is_call_frontier_mnemonic(mnemonic)
                ):
                    continue
            for choice in self._branch_event_choice_values(event):
                resolved_successor = self._branch_event_choice_successor_bb(event, choice)
                if resolved_successor is None or int(resolved_successor) != normalized_successor:
                    continue
                if _is_call_frontier_mnemonic(mnemonic):
                    # Direct BLX immediate targets are only forceable when the
                    # requested successor is the encoded branch target itself.
                    if (
                        mnemonic == "BLX"
                        and _parse_dispatch_target_register(insn.get("operands")) is None
                    ):
                        direct_target = _parse_direct_target(insn.get("operands"))
                        direct_target_bb = (
                            self.prepared.resolve_basic_block(direct_target)
                            if direct_target is not None
                            else None
                        )
                        if direct_target_bb is None or int(direct_target_bb) != normalized_successor:
                            continue
                return choice

        branch_pc = int(insn.get("address", pred_bb) or pred_bb)
        size = int(insn.get("size", 2) or 2)
        target = _parse_direct_target(insn.get("operands"))
        target_bb = self.prepared.resolve_basic_block(target) if target is not None else None
        fallthrough_bb = self.prepared.resolve_basic_block(branch_pc + size)
        if target_bb is not None and int(target_bb) == int(successor_bb):
            return True
        if fallthrough_bb is not None and int(fallthrough_bb) == int(successor_bb):
            return False
        return None

    def _frontier_successor_replay_candidates(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 0,
    ) -> List[Dict[str, object]]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if self.prepared.valid_bb_set else self.prepared.static_bb_set
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        far_target_distance = 1_000_000_000
        near_target_distance = max(
            0,
            _env_int("LSGEMU_FRONTIER_SUCCESSOR_DOWNSTREAM_NEAR_TARGET_DISTANCE", 2),
        )
        target_distance = self._static_target_distance_lookup(
            target_filter,
            effective_successors,
            far_target_distance,
        )

        def schedule_reason_rank(reason: object) -> int:
            return {
                "target_filter_immediate": 60,
                "uncovered_immediate_successor": 50,
                "target_filter_near_downstream": 40,
                "target_filter_downstream": 30,
                "covered_successor_downstream": 10,
            }.get(str(reason), 0)

        def downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        candidates: List[Dict[str, object]] = []
        backup_with_primary_limit = max(
            0,
            _env_int("LSGEMU_FRONTIER_SUCCESSOR_DOWNSTREAM_BACKUP_WITH_PRIMARY", 0),
        )
        backup_only_successor_limit = max(
            0,
            _env_int("LSGEMU_FRONTIER_SUCCESSOR_DOWNSTREAM_BACKUP_ONLY_SUCCESSORS", 1),
        )
        backup_candidate_limit = max(
            0,
            _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_DOWNSTREAM_BACKUP_CANDIDATES",
                8 if target_filter else 4,
            ),
        )
        for pred_bb, successors in sorted(effective_successors.items()):
            if pred_bb not in covered:
                continue
            insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if not _is_dispatch_frontier_mnemonic(mnemonic):
                continue

            root_keys = [
                key for key in self.known_branch_root_snapshots
                if int(key[0]) == int(pred_bb)
            ]
            snapshot_entries: List[PrefixReplaySnapshot] = []
            for root_key in sorted(root_keys, key=lambda item: (int(item[1]), int(item[0]))):
                snapshot_entries.extend(self._root_snapshot_entries(root_key))
            if not snapshot_entries:
                continue

            choices: List[Tuple[int, object, int, int, str, bool, int, int]] = []
            for successor in sorted(successors):
                if successor not in scope:
                    continue
                successor = int(successor)
                reachable = self._static_reachable_from_cached(
                    successor,
                    effective_successors,
                    reachable_cache,
                )
                uncovered_downstream = (reachable & scope) - covered
                target_matches = (reachable & target_filter) if target_filter else set()
                immediate_uncovered = successor not in covered
                immediate_target_match = successor in target_filter if target_filter else False
                target_min_distance = target_distance(successor) if target_matches else far_target_distance
                if target_filter:
                    if not target_matches:
                        continue
                    schedule_reason = (
                        "target_filter_immediate"
                        if immediate_target_match
                        else (
                            "target_filter_near_downstream"
                            if target_min_distance <= near_target_distance
                            else "target_filter_downstream"
                        )
                    )
                elif immediate_uncovered:
                    schedule_reason = "uncovered_immediate_successor"
                elif uncovered_downstream:
                    schedule_reason = "covered_successor_downstream"
                else:
                    continue
                choice = self._frontier_successor_choice(int(pred_bb), int(successor))
                if choice is None:
                    continue
                choices.append((
                    successor,
                    choice,
                    len(uncovered_downstream),
                    self._semantic_priority_for_bb(successor),
                    schedule_reason,
                    immediate_uncovered,
                    len(target_matches),
                    target_min_distance,
                ))
            if not choices:
                continue
            choices.sort(
                key=lambda item: (
                    schedule_reason_rank(item[4]),
                    1 if item[5] else 0,
                    -item[7],
                    item[6],
                    item[3],
                    item[2],
                    -item[0],
                ),
                reverse=True,
            )
            primary_choices = [
                item for item in choices
                if (
                    bool(item[5])
                    or item[4] in {"target_filter_immediate", "target_filter_near_downstream"}
                )
            ]
            backup_choices = [
                item for item in choices
                if not (
                    bool(item[5])
                    or item[4] in {"target_filter_immediate", "target_filter_near_downstream"}
                )
            ]
            if primary_choices:
                choices = primary_choices + backup_choices[:backup_with_primary_limit]
            else:
                choices = backup_choices[:backup_only_successor_limit]
            if not choices:
                continue
            primary_choice_count = sum(
                1 for item in choices
                if (
                    bool(item[5])
                    or item[4] in {"target_filter_immediate", "target_filter_near_downstream"}
                )
            )
            backup_choice_count = len(choices) - primary_choice_count
            candidates.append({
                "pred_bb": int(pred_bb),
                "mnemonic": mnemonic,
                "choices": choices,
                "snapshot_entries": snapshot_entries,
                "primary_choice_count": primary_choice_count,
                "backup_choice_count": backup_choice_count,
                "priority": (
                    max(schedule_reason_rank(item[4]) for item in choices),
                    -min(item[7] for item in choices),
                    max(item[6] for item in choices),
                    max(item[3] for item in choices),
                    sum(item[3] for item in choices),
                    primary_choice_count,
                    sum(1 for item in choices if item[5]),
                    sum(item[2] for item in choices),
                    max(item[2] for item in choices),
                    len(choices),
                    len(snapshot_entries),
                    -int(pred_bb),
                ),
            })

        total_candidates_before_selection = len(candidates)
        total_choices_before_selection = sum(len(item.get("choices", []) or []) for item in candidates)
        reason_counts_before_selection: Counter[str] = Counter()
        for item in candidates:
            for choice_item in item.get("choices", []) or []:
                try:
                    reason_counts_before_selection[str(choice_item[4])] += 1
                except Exception:
                    reason_counts_before_selection["unknown"] += 1

        candidates.sort(key=lambda item: item["priority"], reverse=True)
        primary_candidates = [
            item for item in candidates
            if int(item.get("primary_choice_count", 0) or 0) > 0
        ]
        backup_candidates = [
            item for item in candidates
            if int(item.get("primary_choice_count", 0) or 0) <= 0
        ]
        if primary_candidates:
            candidates = primary_candidates + backup_candidates[:backup_candidate_limit]
        elif backup_candidate_limit > 0:
            candidates = backup_candidates[:backup_candidate_limit]
        else:
            candidates = []
        candidates = _segment_rotate_sequence(candidates, "frontier_successor_candidates")
        selected_before_max_targets = len(candidates)
        if max_targets and max_targets > 0:
            candidates = candidates[:max_targets]
        reason_counts_selected: Counter[str] = Counter()
        for item in candidates:
            for choice_item in item.get("choices", []) or []:
                try:
                    reason_counts_selected[str(choice_item[4])] += 1
                except Exception:
                    reason_counts_selected["unknown"] += 1
        self._last_frontier_successor_candidate_selection = {
            "target_filter_enabled": bool(target_filter),
            "candidates_before_selection": int(total_candidates_before_selection),
            "choices_before_selection": int(total_choices_before_selection),
            "primary_candidates": int(len(primary_candidates)),
            "backup_candidates": int(len(backup_candidates)),
            "selected_before_max_targets": int(selected_before_max_targets),
            "selected_candidates": int(len(candidates)),
            "selected_pred_diversity": int(len({int(item.get("pred_bb", 0) or 0) for item in candidates})),
            "selected_choices": int(sum(len(item.get("choices", []) or []) for item in candidates)),
            "suppressed_by_max_targets": int(
                max(0, selected_before_max_targets - len(candidates))
                if max_targets and max_targets > 0
                else 0
            ),
            "reason_counts_before_selection": dict(reason_counts_before_selection),
            "reason_counts_selected": dict(reason_counts_selected),
            "priority_model": "reason_rank_then_target_distance_then_semantic_then_potential",
        }
        return candidates

    def _frontier_successor_candidate_diagnostics(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        valid_only: bool = True,
        max_samples: int = 16,
    ) -> Dict[str, object]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = (
            self.prepared.valid_bb_set
            if valid_only and self.prepared.valid_bb_set
            else self.prepared.static_bb_set
        )
        scope = set(scope)
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        far_target_distance = 1_000_000_000
        near_target_distance = max(
            0,
            _env_int("LSGEMU_FRONTIER_SUCCESSOR_DOWNSTREAM_NEAR_TARGET_DISTANCE", 2),
        )
        target_distance = self._static_target_distance_lookup(
            target_filter,
            effective_successors,
            far_target_distance,
        )
        counters: Counter[str] = Counter()
        mnemonic_counters: Counter[str] = Counter()
        samples: Dict[str, List[Dict[str, object]]] = defaultdict(list)

        def remember(reason: str, pred_bb: int, successor: Optional[int], mnemonic: str, extra: Optional[Dict[str, object]] = None) -> None:
            counters[reason] += 1
            if mnemonic:
                mnemonic_counters[mnemonic] += 1
            if len(samples[reason]) >= max(0, max_samples):
                return
            record = {
                "pred_bb": f"0x{int(pred_bb) & 0xFFFFFFFF:08x}",
                "mnemonic": mnemonic,
            }
            if successor is not None:
                record["successor_bb"] = f"0x{int(successor) & 0xFFFFFFFF:08x}"
            if extra:
                record.update(extra)
            samples[reason].append(record)

        for pred_bb, successors in sorted(effective_successors.items()):
            pred_bb = int(pred_bb)
            if pred_bb not in covered:
                remember("pred_not_covered", pred_bb, None, "")
                continue
            insn = self.prepared.branch_instruction_by_bb.get(pred_bb, {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if not _is_dispatch_frontier_mnemonic(mnemonic):
                remember("non_dispatch_frontier_mnemonic", pred_bb, None, mnemonic)
                continue

            root_keys = [
                key for key in self.known_branch_root_snapshots
                if int(key[0]) == pred_bb
            ]
            snapshot_count = sum(len(self._root_snapshot_entries(key)) for key in root_keys)
            if snapshot_count <= 0:
                remember("no_root_snapshot", pred_bb, None, mnemonic)
                continue

            edge_had_candidate = False
            for successor in sorted(int(bb) for bb in successors):
                if successor not in scope:
                    remember("successor_out_of_scope", pred_bb, successor, mnemonic)
                    continue
                reachable = self._static_reachable_from_cached(
                    successor,
                    effective_successors,
                    reachable_cache,
                )
                uncovered_downstream = (reachable & scope) - covered
                target_matches = (reachable & target_filter) if target_filter else set()
                immediate_uncovered = successor not in covered
                immediate_target_match = successor in target_filter if target_filter else False
                target_min_distance = target_distance(successor) if target_matches else far_target_distance
                if target_filter:
                    if not target_matches:
                        remember(
                            "target_filter_no_downstream_match",
                            pred_bb,
                            successor,
                            mnemonic,
                            {"uncovered_downstream": len(uncovered_downstream)},
                        )
                        continue
                    candidate_reason = (
                        "candidate_ready_target_immediate"
                        if immediate_target_match
                        else (
                            "candidate_ready_target_near_downstream"
                            if target_min_distance <= near_target_distance
                            else "candidate_ready_target_downstream"
                        )
                    )
                elif immediate_uncovered:
                    candidate_reason = "candidate_ready_uncovered_immediate"
                elif uncovered_downstream:
                    candidate_reason = "candidate_ready_covered_successor_downstream"
                else:
                    remember("successor_already_covered_no_downstream", pred_bb, successor, mnemonic)
                    continue
                choice = self._frontier_successor_choice(pred_bb, successor)
                if choice is None:
                    remember(
                        "choice_unmapped",
                        pred_bb,
                        successor,
                        mnemonic,
                        {
                            "uncovered_downstream": len(uncovered_downstream),
                            "target_matches": len(target_matches),
                            "target_min_distance": target_min_distance,
                        },
                    )
                    continue
                edge_had_candidate = True
                remember(
                    candidate_reason,
                    pred_bb,
                    successor,
                    mnemonic,
                    {
                        "snapshot_count": snapshot_count,
                        "uncovered_downstream": len(uncovered_downstream),
                        "target_matches": len(target_matches),
                        "target_min_distance": target_min_distance,
                        "uncovered_immediate": immediate_uncovered,
                    },
                )
            if not edge_had_candidate:
                counters["dispatch_frontier_without_candidate_successor"] += 1

        return {
            "coverage_bbs": len(covered),
            "effective_successor_sources": len(effective_successors),
            "effective_successor_edges": sum(len(successors) for successors in effective_successors.values()),
            "reason_counts": dict(counters),
            "top_mnemonics": dict(mnemonic_counters.most_common(32)),
            "samples": {reason: rows for reason, rows in samples.items()},
        }

    def run_frontier_successor_replay_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        max_tasks: int = 128,
        max_instructions: int = 80000,
        replay_timeout: int = 1_000_000,
        no_new_bb_limit: int = 4096,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 128,
        variants_per_branch: int = 1,
        target_probe_after_hit_bbs: Optional[int] = None,
        refresh_after_progress_tasks: Optional[int] = None,
        max_successor_hits_per_stage: Optional[int] = None,
        max_successor_zero_new_per_stage: Optional[int] = None,
        phase_name: str = "frontier_successor_replay",
    ) -> Set[int]:
        """
        Replay immediate uncovered successors from entry-derived branch/dispatch
        snapshots.

        This stage is deliberately narrow: it does not jump to an uncovered BB.
        It restores a snapshot captured when reset-entry execution reached the
        frontier branch/dispatch BB, applies one requested successor at that
        already-reached frontier, and counts only BBs observed by Unicorn hooks
        during replay.
        """
        start_time = time.time()
        target_bb_set = self.validate_coverage(target_bbs or set())
        phase_covered: Set[int] = set()
        attempted_successor_edges: Set[Tuple[int, int, Tuple[str, object]]] = set()
        attempted_successor_snapshot_edges: Set[
            Tuple[int, int, Tuple[str, object], Tuple[object, ...], Tuple[object, ...]]
        ] = set()
        candidate_rounds = 0
        candidate_count_total = 0
        last_candidate_count = 0
        tasks_run = 0
        tasks_with_new_bbs = 0
        tasks_with_target_bbs = 0
        child_execution_interventions: Counter[str] = Counter()
        child_execution_records: List[Dict[str, object]] = []
        target_bbs_discovered: Set[int] = set()
        restore_failed = 0
        invalid_snapshots = 0
        invalid_reasons: Counter[str] = Counter()
        forced_choices_requested = 0
        forced_choices_hit = 0
        forced_choices_verified = 0
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        stop_reasons: Counter[str] = Counter()
        choices_suppressed_by_pred_limit = 0
        snapshots_suppressed_by_edge_limit = 0
        edges_suppressed_by_stage_target_hit = 0
        edges_suppressed_by_stage_zero_new = 0
        edges_suppressed_by_stage_attempt_limit = 0
        stage_edge_attempts: Counter[Tuple[int, int, Tuple[str, object]]] = Counter()
        stage_edge_target_hits: Counter[Tuple[int, int, Tuple[str, object]]] = Counter()
        stage_edge_zero_new: Counter[Tuple[int, int, Tuple[str, object]]] = Counter()
        last_candidate_selection: Dict[str, object] = {}
        candidate_debug_records: List[Dict[str, object]] = []
        child_execution_interventions: Counter[str] = Counter()
        child_execution_records: List[Dict[str, object]] = []
        task_attempts = 0
        last_candidate_diagnostics: Dict[str, object] = {}
        if target_probe_after_hit_bbs is None:
            target_probe_after_hit_bbs = _env_int("LSGEMU_FRONTIER_SUCCESSOR_TARGET_PROBE_BBS", 0)
        target_probe_after_hit_bbs = max(0, int(target_probe_after_hit_bbs or 0))
        if refresh_after_progress_tasks is None:
            refresh_after_progress_tasks = _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_REFRESH_AFTER_PROGRESS_TASKS",
                8 if target_probe_after_hit_bbs > 0 and not target_bb_set else 1,
            )
        refresh_after_progress_tasks = max(1, int(refresh_after_progress_tasks or 1))
        if max_successor_hits_per_stage is None:
            max_successor_hits_per_stage = _env_int("LSGEMU_FRONTIER_SUCCESSOR_MAX_HITS_PER_SUCCESSOR", 0)
        if max_successor_zero_new_per_stage is None:
            max_successor_zero_new_per_stage = _env_int("LSGEMU_FRONTIER_SUCCESSOR_MAX_ZERO_NEW_PER_SUCCESSOR", 0)
        max_successor_hits_per_stage = max(0, int(max_successor_hits_per_stage or 0))
        max_successor_zero_new_per_stage = max(0, int(max_successor_zero_new_per_stage or 0))
        target_probe_hits = 0
        target_probe_stops = 0
        task_wall_seconds: List[float] = []
        successor_hits: Counter[int] = Counter()
        successor_zero_new: Counter[int] = Counter()
        successors_suppressed_by_hit_limit = 0
        successors_suppressed_by_zero_new_limit = 0
        successors_suppressed_by_native_crash_blacklist = 0
        covered_downstream_suppressed = 0
        frontier_successor_debug_enabled = _env_flag("LSGEMU_FRONTIER_SUCCESSOR_DEBUG", "1")
        frontier_successor_debug_path = Path(
            os.environ.get(
                "LSGEMU_LAST_FRONTIER_SUCCESSOR_REPLAY_DEBUG",
                str(SRCV4_ROOT / ".lsgemu_runs" / "last_frontier_successor_replay_debug.json"),
            )
        )
        allow_covered_downstream_successor_replay = _env_flag(
            "LSGEMU_FRONTIER_SUCCESSOR_ALLOW_COVERED_DOWNSTREAM",
            "1",
        )

        target_filtered_replay = bool(target_bb_set)
        default_choices_per_pred_round = 1 if target_filtered_replay else 0
        max_choices_per_pred_round = max(
            0,
            _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_MAX_CHOICES_PER_PRED_PER_ROUND",
                default_choices_per_pred_round,
            ),
        )
        if target_filtered_replay:
            max_choices_per_pred_round = max(
                0,
                _env_int(
                    "LSGEMU_FRONTIER_SUCCESSOR_TARGET_MAX_CHOICES_PER_PRED_PER_ROUND",
                    max_choices_per_pred_round if max_choices_per_pred_round > 0 else 1,
                ),
            )
        default_snapshots_per_edge_round = 1 if target_filtered_replay else 0
        max_snapshots_per_edge_round = max(
            0,
            _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_MAX_SNAPSHOTS_PER_EDGE_PER_ROUND",
                default_snapshots_per_edge_round,
            ),
        )
        if target_filtered_replay:
            max_snapshots_per_edge_round = max(
                0,
                _env_int(
                    "LSGEMU_FRONTIER_SUCCESSOR_TARGET_MAX_SNAPSHOTS_PER_EDGE_PER_ROUND",
                    max_snapshots_per_edge_round if max_snapshots_per_edge_round > 0 else 1,
                ),
            )
        max_attempts_per_edge_stage = max(
            0,
            _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_MAX_ATTEMPTS_PER_EDGE_PER_STAGE",
                0,
            ),
        )
        if target_filtered_replay:
            max_attempts_per_edge_stage = max(
                0,
                _env_int(
                    "LSGEMU_FRONTIER_SUCCESSOR_TARGET_MAX_ATTEMPTS_PER_EDGE_PER_STAGE",
                    max_attempts_per_edge_stage,
                ),
            )
        target_hit_limit_per_edge_stage = max(
            0,
            _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_TARGET_HIT_LIMIT_PER_EDGE_PER_STAGE",
                0,
            ),
        )
        zero_new_limit_per_edge_stage = max(
            0,
            _env_int(
                "LSGEMU_FRONTIER_SUCCESSOR_ZERO_NEW_LIMIT_PER_EDGE_PER_STAGE",
                0,
            ),
        )

        def choice_identity(choice: object) -> Tuple[str, object]:
            if isinstance(choice, bool):
                return ("bool", bool(choice))
            try:
                return ("int", int(choice))
            except (TypeError, ValueError):
                return (type(choice).__name__, str(choice))

        def serialize_choice(choice: object) -> object:
            kind, value = choice_identity(choice)
            if kind == "bool":
                return bool(value)
            if kind == "int":
                return int(value)
            return str(value)

        def deserialize_debug_choice(kind: object, value: object) -> object:
            if str(kind) == "bool":
                if isinstance(value, bool):
                    return bool(value)
                return str(value).strip().lower() in {"1", "true", "yes", "on"}
            if str(kind) == "int":
                return int(str(value), 0)
            return str(value)

        def serialize_branch_key(key: object) -> Dict[str, object]:
            try:
                if isinstance(key, tuple):
                    branch = int(key[0]) if len(key) > 0 else 0
                    occurrence = int(key[1]) if len(key) > 1 else 1
                else:
                    branch = int(key)
                    occurrence = 1
                return {
                    "branch": f"0x{branch & 0xFFFFFFFF:08x}",
                    "occurrence": int(occurrence),
                }
            except Exception:
                return {"raw": str(key)}

        def live_registers(emulator: object) -> Dict[str, str]:
            registers = {
                name: "0x00000000"
                for name in (
                    "r0",
                    "r1",
                    "r2",
                    "r3",
                    "r4",
                    "r5",
                    "r6",
                    "r7",
                    "r8",
                    "r9",
                    "r10",
                    "r11",
                    "r12",
                    "sp",
                    "lr",
                    "pc",
                    "cpsr",
                )
            }
            uc = getattr(emulator, "uc", None)
            if uc is None:
                return registers
            for name, reg in (
                ("r0", UC_ARM_REG_R0),
                ("r1", UC_ARM_REG_R1),
                ("r2", UC_ARM_REG_R2),
                ("r3", UC_ARM_REG_R3),
                ("r4", UC_ARM_REG_R4),
                ("r5", UC_ARM_REG_R5),
                ("r6", UC_ARM_REG_R6),
                ("r7", UC_ARM_REG_R7),
                ("r8", UC_ARM_REG_R8),
                ("r9", UC_ARM_REG_R9),
                ("r10", UC_ARM_REG_R10),
                ("r11", UC_ARM_REG_R11),
                ("r12", UC_ARM_REG_R12),
                ("pc", UC_ARM_REG_PC),
                ("sp", UC_ARM_REG_SP),
                ("lr", UC_ARM_REG_LR),
                ("cpsr", UC_ARM_REG_CPSR),
            ):
                try:
                    registers[name] = f"0x{int(uc.reg_read(reg)) & 0xFFFFFFFF:08x}"
                except Exception:
                    pass
            return registers

        def write_frontier_successor_debug(debug_stage: str, payload: Dict[str, object]) -> None:
            if not frontier_successor_debug_enabled:
                return
            debug_payload = dict(payload)
            debug_payload.update({
                "debug_stage": str(debug_stage),
                "phase_name": str(phase_name),
                "firmware": str(self.firmware_path),
            })
            try:
                _write_json_debug_record(frontier_successor_debug_path, debug_payload)
            except Exception as exc:
                # Debug persistence is observational.  A full disk or a
                # malformed optional value must not strand the replay engine
                # or abort the successor stage.
                logger.debug("frontier replay debug write failed: %s", exc)

        def load_frontier_successor_native_crash_blacklist() -> Set[
            Tuple[int, int, Tuple[str, object], Tuple[int, int]]
        ]:
            if not _env_flag("LSGEMU_FRONTIER_SUCCESSOR_SKIP_LAST_NATIVE_CRASH", "0"):
                return set()
            try:
                with frontier_successor_debug_path.open() as f:
                    record = json.load(f)
            except Exception:
                return set()
            if not isinstance(record, dict):
                return set()
            if str(record.get("debug_stage") or "") != "pre_emu_start":
                return set()
            if str(record.get("firmware") or "") != str(self.firmware_path):
                return set()
            recorded_phase = str(record.get("phase_name") or "")
            if recorded_phase and recorded_phase != str(phase_name):
                return set()
            try:
                root_record = record.get("root_key") or {}
                if not isinstance(root_record, dict):
                    root_record = {}
                pred = int(str(record.get("pred_bb")), 0)
                successor = int(str(record.get("successor_bb")), 0)
                choice = deserialize_debug_choice(
                    record.get("choice_type"),
                    record.get("choice_value"),
                )
                root_branch = int(str(root_record.get("branch", record.get("pred_bb"))), 0)
                root_occurrence = int(root_record.get("occurrence", 1))
            except Exception:
                return set()
            return {
                (
                    pred & 0xFFFFFFFF,
                    successor & 0xFFFFFFFF,
                    choice_identity(choice),
                    (root_branch & 0xFFFFFFFF, root_occurrence),
                )
            }

        native_crash_blacklist = load_frontier_successor_native_crash_blacklist()

        def replay_attempt_metadata(
            *,
            pred_bb: int,
            successor_bb: int,
            choice: object,
            candidate_mnemonic: str,
            schedule_reason: object,
            snapshot_entry: Optional[PrefixReplaySnapshot] = None,
            root_identity: Optional[Tuple[int, int]] = None,
        ) -> Dict[str, object]:
            """Return compact context facts shared by every child record."""
            metadata: Dict[str, object] = {
                "entry_derivation": "entry_derived_frontier_branch_snapshot_replay",
                "context_snapshot_mode": True,
                "counterfactual_control": True,
                "coverage_counted": True,
                "pred_bb": int(pred_bb),
                "successor_bb": int(successor_bb),
                "choice_type": choice_identity(choice)[0],
                "choice_value": serialize_choice(choice),
                "candidate_mnemonic": str(candidate_mnemonic),
                "schedule_reason": str(schedule_reason),
            }
            if root_identity is not None:
                metadata["root_branch"] = int(root_identity[0])
                metadata["root_occurrence"] = int(root_identity[1])
            if snapshot_entry is not None:
                snapshot = getattr(snapshot_entry, "snapshot", None)
                # Read the wrapper first; it may carry lineage that is not
                # present on the underlying BranchSnapshot object.
                provenance = self._snapshot_provenance_record(snapshot_entry)
                try:
                    metadata["snapshot_identity"] = repr(
                        self._snapshot_entry_identity(snapshot_entry)
                    )[:2000]
                except Exception:
                    metadata["snapshot_identity"] = "unavailable"
                metadata["snapshot_origin"] = str(
                    getattr(snapshot_entry, "origin", "unknown") or "unknown"
                )
                if snapshot is not None:
                    try:
                        metadata["snapshot_address"] = (
                            f"0x{int(getattr(snapshot, 'address', 0) or 0) & 0xFFFFFFFF:08x}"
                        )
                    except Exception:
                        pass
                source_execution_id = str(provenance.get("execution_id") or "")
                if source_execution_id:
                    metadata["snapshot_source_execution_id"] = source_execution_id[:256]
                metadata.update(
                    {
                        "prefix_provenance_status": str(
                            provenance.get("status") or "unverified"
                        ),
                        "prefix_telemetry_complete": bool(
                            provenance.get("telemetry_complete", False)
                        ),
                        "snapshot_ancestor_validated": bool(
                            provenance.get("snapshot_ancestor_validated", False)
                        ),
                        "snapshot_provenance": dict(provenance),
                    }
                )
            return metadata

        def decorate_attempt_record(
            record: Dict[str, object],
            metadata: Mapping[str, object],
        ) -> Dict[str, object]:
            """Attach bounded candidate identity without retaining raw state."""
            for key in (
                "pred_bb",
                "successor_bb",
                "choice_type",
                "choice_value",
                "candidate_mnemonic",
                "schedule_reason",
                "root_branch",
                "root_occurrence",
                "snapshot_ancestor_validated",
                "prefix_provenance_status",
                "prefix_telemetry_complete",
                "snapshot_identity",
                "snapshot_origin",
                "snapshot_address",
                "snapshot_source_execution_id",
            ):
                if key in metadata:
                    record[key] = metadata[key]
            return record

        def append_replay_failure(
            *,
            execution_id: str,
            reason: str,
            metadata: Mapping[str, object],
            execution_started: bool = False,
            execution_error: Optional[BaseException | str] = None,
            detail: Optional[str] = None,
        ) -> Dict[str, object]:
            record = self._execution_failure_evidence_record(
                phase_name=str(phase_name or "frontier_successor_replay"),
                execution_id=execution_id,
                reason=reason,
                metadata=metadata,
                execution_started=execution_started,
                execution_error=execution_error,
                run_result={
                    "restore_failed": "restore" in str(reason),
                    "preflight_failed": "preflight" in str(reason),
                },
            )
            if detail:
                record["failure_detail"] = str(detail)[:500]
            decorate_attempt_record(record, metadata)
            child_execution_records.append(record)
            child_execution_interventions.update(
                record.get("actual_intervention_reasons", {}) or {}
            )
            return record

        def budget_exhausted() -> bool:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                return True
            if max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks:
                return True
            stall_watchdog = getattr(self, "stall_watchdog", None)
            if stall_watchdog is not None and stall_watchdog.should_stop():
                return True
            # Stage-level truncation: the watchdog flagged this stage (or an
            # enclosing budget-owner stage) as all-ledger frozen.  Breaking
            # here lands in the ordinary ``_record_phase`` exit below, so the
            # phase set -- including counterfactual evidence already recorded
            # per attempt -- is merged into ``global_coverage`` exactly as at
            # a natural stage end; nothing "earned but unrecorded" is lost.
            return (
                stall_watchdog is not None
                and stall_watchdog.should_truncate_stage(phase_name)
            )

        while not budget_exhausted():
            candidates = self._frontier_successor_replay_candidates(
                coverage=self.global_coverage | phase_covered,
                target_bbs=target_bb_set if target_bb_set else None,
                max_targets=max_targets,
            )
            candidate_rounds += 1
            last_candidate_count = len(candidates)
            candidate_count_total += len(candidates)
            last_candidate_selection = dict(
                getattr(self, "_last_frontier_successor_candidate_selection", {}) or {}
            )
            if not candidates:
                last_candidate_diagnostics = self._frontier_successor_candidate_diagnostics(
                    coverage=self.global_coverage | phase_covered,
                    target_bbs=target_bb_set if target_bb_set else None,
                )
                break

            tasks_before_round = tasks_run
            refreshed_after_progress = False
            progress_tasks_since_refresh = 0
            round_pred_choice_counts: Counter[int] = Counter()
            for candidate in candidates:
                if budget_exhausted() or refreshed_after_progress:
                    break
                pred_bb = int(candidate["pred_bb"])
                candidate_mnemonic = str(candidate.get("mnemonic") or "")
                choices = _segment_rotate_sequence(
                    candidate["choices"],
                    f"frontier_successor_choices:{pred_bb}",
                )
                snapshot_entries_all = _segment_rotate_sequence(
                    candidate["snapshot_entries"],
                    f"frontier_successor_snapshots:{pred_bb}",
                )
                variant_limit = max(1, variants_per_branch)
                if (
                    _is_switch_frontier_mnemonic(candidate_mnemonic)
                    or _is_call_frontier_mnemonic(candidate_mnemonic)
                ):
                    variant_limit = max(
                        variant_limit,
                        min(len(snapshot_entries_all), max(2, variants_per_branch * 2)),
                    )
                base_variant_limit = int(variant_limit)
                if max_snapshots_per_edge_round > 0:
                    variant_limit = min(variant_limit, max(1, int(max_snapshots_per_edge_round)))
                snapshot_entries = snapshot_entries_all[:variant_limit]
                for (
                    successor_bb,
                    choice,
                    potential,
                    semantic_priority,
                    schedule_reason,
                    immediate_uncovered,
                    target_filter_matches,
                    target_min_distance,
                ) in choices:
                    if budget_exhausted():
                        break
                    if (
                        max_choices_per_pred_round > 0
                        and round_pred_choice_counts[int(pred_bb)] >= max_choices_per_pred_round
                    ):
                        choices_suppressed_by_pred_limit += 1
                        continue
                    edge_key = (
                        int(pred_bb),
                        int(successor_bb),
                        choice_identity(choice),
                    )
                    if (
                        max_attempts_per_edge_stage > 0
                        and stage_edge_attempts[edge_key] >= max_attempts_per_edge_stage
                    ):
                        edges_suppressed_by_stage_attempt_limit += 1
                        continue
                    if (
                        target_hit_limit_per_edge_stage > 0
                        and stage_edge_target_hits[edge_key] >= target_hit_limit_per_edge_stage
                    ):
                        edges_suppressed_by_stage_target_hit += 1
                        continue
                    if (
                        zero_new_limit_per_edge_stage > 0
                        and stage_edge_zero_new[edge_key] >= zero_new_limit_per_edge_stage
                    ):
                        edges_suppressed_by_stage_zero_new += 1
                        continue
                    if (
                        max_successor_hits_per_stage > 0
                        and successor_hits[int(successor_bb)] >= max_successor_hits_per_stage
                    ):
                        successors_suppressed_by_hit_limit += 1
                        continue
                    if (
                        max_successor_zero_new_per_stage > 0
                        and successor_zero_new[int(successor_bb)] >= max_successor_zero_new_per_stage
                    ):
                        successors_suppressed_by_zero_new_limit += 1
                        continue
                    if (
                        not allow_covered_downstream_successor_replay
                        and not target_filtered_replay
                        and str(schedule_reason) == "covered_successor_downstream"
                        and not bool(immediate_uncovered)
                    ):
                        covered_downstream_suppressed += 1
                        continue
                    skip_exclude_addresses: Set[int] = {
                        int(pred_bb) & ~1,
                        int(successor_bb) & ~1,
                    }
                    pred_function_entry = self._function_entry_for_addr(int(pred_bb))
                    if pred_function_entry is not None:
                        skip_exclude_addresses.add(int(pred_function_entry) & ~1)
                    successor_function_entry = self._function_entry_for_addr(int(successor_bb))
                    if successor_function_entry is not None:
                        skip_exclude_addresses.add(int(successor_function_entry) & ~1)
                    edge_snapshot_entries: List[
                        Tuple[
                            PrefixReplaySnapshot,
                            Tuple[int, int, Tuple[str, object], Tuple[object, ...], Tuple[object, ...]],
                        ]
                    ] = []
                    edge_snapshot_candidate_count = 0
                    for snapshot_entry in snapshot_entries_all:
                        attempt_key = (
                            int(pred_bb),
                            int(successor_bb),
                            choice_identity(choice),
                            self._snapshot_entry_identity(snapshot_entry),
                            self._direct_call_attempt_constraint_signature(snapshot_entry),
                        )
                        if attempt_key in attempted_successor_snapshot_edges:
                            continue
                        edge_snapshot_candidate_count += 1
                        if len(edge_snapshot_entries) < variant_limit:
                            edge_snapshot_entries.append((snapshot_entry, attempt_key))
                    if not edge_snapshot_entries:
                        continue
                    if max_snapshots_per_edge_round > 0:
                        snapshots_suppressed_by_edge_limit += max(
                            0,
                            min(edge_snapshot_candidate_count, base_variant_limit)
                            - len(edge_snapshot_entries),
                        )
                    round_pred_choice_counts[int(pred_bb)] += 1
                    attempted_successor_edges.add(edge_key)
                    for snapshot_entry, attempt_key in edge_snapshot_entries:
                        if budget_exhausted():
                            break
                        attempted_successor_snapshot_edges.add(attempt_key)
                        root_key = tuple(getattr(snapshot_entry, "next_branch_key", (pred_bb, 1)) or (pred_bb, 1))
                        try:
                            root_identity = (
                                int(root_key[0]) & 0xFFFFFFFF,
                                int(root_key[1]) if len(root_key) > 1 else 1,
                            )
                        except Exception:
                            root_identity = (int(pred_bb) & 0xFFFFFFFF, 1)
                        native_crash_key = (
                            int(pred_bb) & 0xFFFFFFFF,
                            int(successor_bb) & 0xFFFFFFFF,
                            choice_identity(choice),
                            root_identity,
                        )
                        if native_crash_key in native_crash_blacklist:
                            successors_suppressed_by_native_crash_blacklist += 1
                            continue
                        task_attempts += 1
                        attempt_execution_id = (
                            f"{str(phase_name or 'frontier_successor_replay')}"
                            f"-attempt-{task_attempts}"
                        )
                        attempt_metadata = replay_attempt_metadata(
                            pred_bb=int(pred_bb),
                            successor_bb=int(successor_bb),
                            choice=choice,
                            candidate_mnemonic=candidate_mnemonic,
                            schedule_reason=schedule_reason,
                            snapshot_entry=snapshot_entry,
                            root_identity=root_identity,
                        )
                        valid_snapshot, reason = self._validate_root_snapshot_entry(
                            snapshot_entry,
                            root_key=(pred_bb, int(root_key[1]) if len(root_key) > 1 else 1),
                        )
                        if not valid_snapshot:
                            invalid_snapshots += 1
                            invalid_reasons[str(reason)] += 1
                            stop_reasons["invalid_snapshot"] += 1
                            append_replay_failure(
                                execution_id=attempt_execution_id,
                                reason="invalid_snapshot",
                                metadata=attempt_metadata,
                                execution_error=str(reason),
                                detail=str(reason),
                            )
                            continue

                        try:
                            emulator = self._new_temp_emulator(
                                max_snapshots=max(3, self.max_snapshots),
                                llm_config_path=self._effective_llm_config_path(),
                                constraint_json_path=self.constraint_file,
                                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                                stage_name=self._temp_stage_for("frontier_successor_replay_task"),
                            )
                        except Exception as exc:
                            append_replay_failure(
                                execution_id=attempt_execution_id,
                                reason="emulator_create_exception",
                                metadata=attempt_metadata,
                                execution_error=exc,
                            )
                            stop_reasons["emulator_create_exception"] += 1
                            logger.debug("frontier replay emulator创建失败: %s", exc)
                            continue
                        temp_mmio = None
                        temp_tracer = None
                        try:
                            self._configure_emulator_feedback(emulator)
                            scoped_skip_exclude_addresses = set(skip_exclude_addresses)
                            for source_key, _source_choice in getattr(snapshot_entry, "source_path_signature", tuple()) or tuple():
                                try:
                                    source_bb = int(source_key[0]) if isinstance(source_key, tuple) else int(source_key)
                                except (TypeError, ValueError):
                                    continue
                                scoped_skip_exclude_addresses.add(source_bb & ~1)
                                source_function_entry = self._function_entry_for_addr(source_bb)
                                if source_function_entry is not None:
                                    scoped_skip_exclude_addresses.add(int(source_function_entry) & ~1)
                            self._configure_replay_skip_function_returns(
                                emulator,
                                include_time=True,
                                exclude_addresses=scoped_skip_exclude_addresses,
                            )
                            emulator.enable_branch_snapshot = True
                            emulator.set_forced_branch_choices({pred_bb: choice})
                            temp_mmio = EnhancedMMIOHandler(
                                emulator.uc,
                                self.constraint_file,
                                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                            )
                            temp_tracer = self._new_temp_register_tracer(emulator)
                            restored = self._restore_branch_snapshot(
                                emulator,
                                snapshot_entry.snapshot,
                                lineage_source=snapshot_entry,
                            )
                        except Exception as exc:
                            failure_record = append_replay_failure(
                                execution_id=attempt_execution_id,
                                reason="replay_setup_exception",
                                metadata=attempt_metadata,
                                execution_error=exc,
                            )
                            self._safe_dispose_temp_emulator(
                                emulator,
                                mmio_handler=temp_mmio,
                                register_tracer=temp_tracer,
                                quarantine=None,
                                stage_name=self._temp_stage_for("frontier_successor_replay_task"),
                                evidence_record=failure_record,
                            )
                            stop_reasons["replay_setup_exception"] += 1
                            logger.debug("frontier replay setup失败: %s", exc)
                            continue
                        if not restored:
                            restore_failed += 1
                            stop_reasons["snapshot_restore_failed"] += 1
                            failure_record = append_replay_failure(
                                execution_id=attempt_execution_id,
                                reason="snapshot_restore_failed",
                                metadata=attempt_metadata,
                                execution_error="external_or_memory_restore_failed",
                            )
                            self._safe_dispose_temp_emulator(
                                emulator,
                                mmio_handler=temp_mmio,
                                register_tracer=temp_tracer,
                                quarantine=None,
                                stage_name=self._temp_stage_for("frontier_successor_replay_task"),
                                evidence_record=failure_record,
                            )
                            continue
                        if not self._restore_replay_mmio_state(
                            emulator,
                            temp_mmio,
                            snapshot_entry.mmio_state,
                        ):
                            failure_record = append_replay_failure(
                                execution_id=attempt_execution_id,
                                reason="replay_mmio_state_restore_failed",
                                metadata=attempt_metadata,
                                execution_error=self._replay_mmio_restore_failure_reason(
                                    emulator
                                ),
                            )
                            stop_reasons["replay_mmio_state_restore_failed"] += 1
                            self._safe_dispose_temp_emulator(
                                emulator,
                                mmio_handler=temp_mmio,
                                register_tracer=temp_tracer,
                                quarantine=None,
                                stage_name=self._temp_stage_for("frontier_successor_replay_task"),
                                evidence_record=failure_record,
                            )
                            continue
                        self._apply_scoped_branch_constraints(
                            temp_mmio,
                            self._scope_signature_from_snapshot_entry(snapshot_entry),
                            emulator=emulator,
                        )
                        replay_snapshot = getattr(snapshot_entry, "snapshot", None)
                        snapshot_registers = dict(getattr(replay_snapshot, "registers", {}) or {})
                        write_frontier_successor_debug(
                            "pre_emu_start",
                            {
                                "task_index": int(tasks_run + 1),
                                "candidate_round": int(candidate_rounds),
                                "pred_bb": f"0x{int(pred_bb) & 0xFFFFFFFF:08x}",
                                "successor_bb": f"0x{int(successor_bb) & 0xFFFFFFFF:08x}",
                                "choice_type": choice_identity(choice)[0],
                                "choice_value": serialize_choice(choice),
                                "mnemonic": candidate_mnemonic,
                                "schedule_reason": str(schedule_reason),
                                "downstream_potential": int(potential),
                                "semantic_priority": int(semantic_priority),
                                "immediate_uncovered": bool(immediate_uncovered),
                                "target_filter_matches": int(target_filter_matches),
                                "target_min_distance": int(target_min_distance),
                                "root_key": serialize_branch_key(root_key),
                                "snapshot_origin": str(getattr(snapshot_entry, "origin", "unknown")),
                                "snapshot_next_branch_key": serialize_branch_key(
                                    getattr(snapshot_entry, "next_branch_key", None)
                                ),
                                "snapshot_source_path_len": len(
                                    getattr(snapshot_entry, "source_path_signature", tuple()) or tuple()
                                ),
                                "snapshot_address": (
                                    f"0x{int(getattr(replay_snapshot, 'address', 0) or 0) & 0xFFFFFFFF:08x}"
                                    if replay_snapshot is not None
                                    else None
                                ),
                                "snapshot_target": (
                                    f"0x{int(getattr(replay_snapshot, 'target_addr', 0) or 0) & 0xFFFFFFFF:08x}"
                                    if replay_snapshot is not None
                                    else None
                                ),
                                "snapshot_fallthrough": (
                                    f"0x{int(getattr(replay_snapshot, 'fallthrough_addr', 0) or 0) & 0xFFFFFFFF:08x}"
                                    if replay_snapshot is not None
                                    else None
                                ),
                                "snapshot_registers": {
                                    key: f"0x{int(value) & 0xFFFFFFFF:08x}"
                                    for key, value in snapshot_registers.items()
                                    if key in {
                                        "r0",
                                        "r1",
                                        "r2",
                                        "r3",
                                        "r4",
                                        "r5",
                                        "r6",
                                        "r7",
                                        "r8",
                                        "r9",
                                        "r10",
                                        "r11",
                                        "r12",
                                        "pc",
                                        "sp",
                                        "lr",
                                        "cpsr",
                                    }
                                },
                                "live_registers": live_registers(emulator),
                                "max_instructions": int(max_instructions),
                                "replay_timeout_us": int(replay_timeout or 0),
                                "no_new_bb_limit": int(no_new_bb_limit or 0),
                                "target_probe_after_hit_bbs": int(target_probe_after_hit_bbs),
                                "target_bbs": [
                                    f"0x{int(bb) & 0xFFFFFFFF:08x}"
                                    for bb in sorted(target_bb_set)[:32]
                                ],
                            },
                        )

                        known_before = self.global_coverage | phase_covered
                        previous_quiescence_limit = emulator.stop_after_no_new_bbs
                        emulator.stop_after_no_new_bbs = (
                            max(1, int(no_new_bb_limit))
                            if no_new_bb_limit and no_new_bb_limit > 0
                            else None
                        )
                        run_result: Dict[str, object] = {"stop_reason": "not_started"}
                        target_probe_hook = None
                        target_probe_info = {
                            "hit": False,
                            "tail": 0,
                            "hit_bb": None,
                        }
                        probe_targets = {int(successor_bb)}
                        if target_bb_set:
                            probe_targets.update(int(bb) for bb in target_bb_set)
                        if target_probe_after_hit_bbs > 0 and probe_targets:
                            def target_probe_stop_hook(uc, address, size, user_data):
                                bb_addr = self.prepared.resolve_basic_block(int(address)) or int(address)
                                if not target_probe_info["hit"]:
                                    if bb_addr in probe_targets:
                                        target_probe_info["hit"] = True
                                        target_probe_info["hit_bb"] = bb_addr
                                    return
                                target_probe_info["tail"] = int(target_probe_info["tail"] or 0) + 1
                                if int(target_probe_info["tail"] or 0) >= target_probe_after_hit_bbs:
                                    emulator.stop_requested_reason = "target_probe_tail_complete"
                                    uc.emu_stop()

                            try:
                                target_probe_hook = emulator._add_owned_hook(
                                    UC_HOOK_BLOCK,
                                    target_probe_stop_hook,
                                )
                            except Exception as exc:
                                failure_record = append_replay_failure(
                                    execution_id=attempt_execution_id,
                                    reason="hook_installation_failed",
                                    metadata=attempt_metadata,
                                    execution_error=exc,
                                    detail="target_probe_hook",
                                )
                                stop_reasons["hook_installation_failed"] += 1
                                self._safe_dispose_temp_emulator(
                                    emulator,
                                    mmio_handler=temp_mmio,
                                    register_tracer=temp_tracer,
                                    quarantine=None,
                                    stage_name=self._temp_stage_for("frontier_successor_replay_task"),
                                    evidence_record=failure_record,
                                )
                                continue
                        with self.guided_modules(
                            temp_mmio,
                            temp_tracer,
                            hook_mmio=True,
                        ), self.capture_execution_trace(emulator) as trace:
                            task_wall_start = time.time()
                            try:
                                run_result = emulator.run(
                                    entry_point=None,
                                    max_instructions=max_instructions,
                                    timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                                    preserve_cpu_state=True,
                                )
                            except Exception as exc:
                                run_result = self._materialize_replay_failure_result(
                                    "execution_exception",
                                    execution_started=True,
                                    execution_error=exc,
                                )
                            finally:
                                task_wall_seconds.append(max(0.0, time.time() - task_wall_start))
                                emulator.stop_after_no_new_bbs = previous_quiescence_limit
                                if target_probe_hook is not None:
                                    try:
                                        emulator._remove_owned_hook(target_probe_hook)
                                    except Exception:
                                        pass

                        self._annotate_replay_run_result(run_result, snapshot_entry)
                        valid = self.validate_coverage(trace.covered_bbs)
                        attempt_metadata["candidate_consumed"] = bool(
                            getattr(emulator, "forced_branch_trace", [])
                        )
                        execution_record = build_execution_evidence_record(
                            phase_name=str(
                                phase_name or "frontier_successor_replay"
                            ),
                            run_result=run_result,
                            covered_bbs=valid,
                            metadata=attempt_metadata,
                            execution_id=attempt_execution_id,
                        )
                        decorate_attempt_record(execution_record, attempt_metadata)
                        child_execution_records.append(execution_record)

                        def safe_postprocess(operation: str, callback, default=None):
                            return self._safe_replay_postprocess(
                                operation,
                                callback,
                                evidence_record=execution_record,
                                run_result=run_result,
                                default=default,
                            )

                        child_execution_interventions.update(
                            execution_record.get(
                                "actual_intervention_reasons", {}
                            )
                            or {}
                        )
                        task_new_bbs = valid - known_before
                        task_new_targets = task_new_bbs & (target_bb_set or {int(successor_bb)})
                        if task_new_bbs:
                            tasks_with_new_bbs += 1
                        if task_new_targets:
                            tasks_with_target_bbs += 1
                            target_bbs_discovered.update(task_new_targets)
                        phase_covered.update(valid)
                        safe_postprocess(
                            "frontier_debug_record",
                            lambda: write_frontier_successor_debug(
                                "post_emu_stop",
                                {
                                    "task_index": int(tasks_run + 1),
                                    "candidate_round": int(candidate_rounds),
                                    "pred_bb": f"0x{int(pred_bb) & 0xFFFFFFFF:08x}",
                                    "successor_bb": f"0x{int(successor_bb) & 0xFFFFFFFF:08x}",
                                    "choice_type": choice_identity(choice)[0],
                                    "choice_value": serialize_choice(choice),
                                    "mnemonic": candidate_mnemonic,
                                    "schedule_reason": str(schedule_reason),
                                    "stop_reason": str(run_result.get("stop_reason") or "unknown"),
                                    "new_bbs": len(task_new_bbs),
                                    "target_bbs_hit": len(task_new_targets),
                                    "valid_trace_bbs": len(valid),
                                    "target_probe_hit": bool(target_probe_info.get("hit")),
                                    "target_probe_tail": int(target_probe_info.get("tail") or 0),
                                    "target_probe_hit_bb": (
                                        f"0x{int(target_probe_info.get('hit_bb')) & 0xFFFFFFFF:08x}"
                                        if target_probe_info.get("hit_bb") is not None
                                        else None
                                    ),
                                    "live_registers": live_registers(emulator),
                                },
                            ),
                        )

                        forced_choices_requested += 1
                        if emulator.forced_branch_trace:
                            forced_choices_hit += 1
                        if any(bool(item.get("verified", False)) for item in emulator.forced_branch_trace):
                            forced_choices_verified += 1

                        forced_choice_verified = any(
                            bool(item.get("verified", False))
                            for item in emulator.forced_branch_trace
                        )
                        source_signature = self._ordered_source_path_signature(
                            tuple(
                                getattr(snapshot_entry, "source_path_signature", tuple())
                                or tuple()
                            )
                        )
                        source_occurrence_signature = (
                            self._snapshot_entry_occurrence_prefix(
                                snapshot_entry
                            )
                        )
                        replay_source_signature = source_signature
                        if forced_choice_verified:
                            safe_postprocess(
                                "coverage_evidence",
                                lambda: self._record_coverage_evidence(EVIDENCE_E2, valid),
                            )
                            replay_source_signature = self._compose_replay_path_signature(
                                source_signature,
                                ((root_identity, choice),),
                            )
                        if forced_choice_verified and (task_new_bbs or task_new_targets):
                            safe_postprocess(
                                "forced_path_obligation",
                                lambda: self._register_forced_path_obligation(
                                    replay_source_signature,
                                    target_bbs={int(successor_bb)},
                                    discovered_bbs=task_new_bbs,
                                    discovery_trace_signature=(
                                        normalize_naturalization_signature(
                                            tuple(
                                                list(source_occurrence_signature)
                                                + [(root_identity, choice)]
                                            )
                                        )
                                    ),
                                    source_phase=phase_name,
                                ),
                            )

                        replay_events = safe_postprocess(
                            "branch_event_collection",
                            lambda: emulator.branch_snapshot_manager.get_ordered_events(),
                            default=[],
                        ) or []
                        replay_occurrence_events = safe_postprocess(
                            "branch_occurrence_collection",
                            lambda: emulator.branch_snapshot_manager.get_ordered_occurrence_events(),
                            default=[],
                        )
                        replay_occurrence_events = replay_occurrence_events or []
                        replay_snapshots = safe_postprocess(
                            "replay_snapshot_collection",
                            lambda: self._ordered_replay_snapshots(emulator),
                            default=[],
                        ) or []
                        remembered_branch_events += safe_postprocess(
                            "branch_event_feedback",
                            lambda: self._remember_main_branch_events(
                                replay_events,
                                evidence_class=EVIDENCE_E2,
                            ),
                            default=0,
                        )
                        remembered_branch_root_snapshots += safe_postprocess(
                            "branch_snapshot_feedback",
                            lambda: self._remember_branch_root_snapshots(
                                replay_events,
                                replay_snapshots,
                                source_path_signature=replay_source_signature,
                                evidence_class=EVIDENCE_E2,
                                occurrence_events=replay_occurrence_events,
                                source_occurrence_signature=(
                                    source_occurrence_signature
                                ),
                            ),
                            default=0,
                        )
                        dynamic_successor_edges_added += safe_postprocess(
                            "dynamic_successor_feedback",
                            lambda: self._record_dynamic_successors(replay_events),
                            default=0,
                        ) or 0
                        dynamic_successor_edges_added += safe_postprocess(
                            "runtime_successor_feedback",
                            lambda: self._record_emulator_runtime_successors(emulator),
                            default=0,
                        ) or 0
                        safe_postprocess(
                            "scheduler_feedback",
                            lambda: self._harvest_emulator_feedback(emulator),
                        )
                        safe_postprocess(
                            "register_tracer_merge",
                            lambda: self.register_tracer.merge_from(temp_tracer),
                        )

                        tasks_run += 1
                        stop_reason = str(run_result.get("stop_reason") or "unknown")
                        stop_reasons[stop_reason] += 1
                        stall_watchdog = getattr(self, "stall_watchdog", None)
                        if stall_watchdog is not None:
                            # Per-attempt feed for the run-level stall clock:
                            # progress is the phase-union coverage this stage
                            # has produced so far, and a completed attempt
                            # without new BBs is one zero-yield production unit.
                            stall_watchdog.observe(
                                stage=phase_name,
                                covered_bbs=len(self.global_coverage | phase_covered),
                                zero_yield_unit=not task_new_bbs,
                            )
                        if target_probe_info.get("hit"):
                            target_probe_hits += 1
                        if stop_reason == "target_probe_tail_complete":
                            target_probe_stops += 1
                        stage_edge_attempts[edge_key] += 1
                        if task_new_targets:
                            stage_edge_target_hits[edge_key] += 1
                        if not task_new_bbs:
                            stage_edge_zero_new[edge_key] += 1
                        if task_new_targets or (target_probe_info.get("hit") and int(successor_bb) in valid):
                            successor_hits[int(successor_bb)] += 1
                        if not task_new_bbs:
                            successor_zero_new[int(successor_bb)] += 1
                        if len(candidate_debug_records) < 32:
                            forced_trace = []
                            for item in list(getattr(emulator, "forced_branch_trace", []) or [])[-8:]:
                                record = dict(item)
                                for key in ("branch", "branch_pc", "actual_bb", "desired_bb"):
                                    if key in record:
                                        try:
                                            record[key] = f"0x{int(record[key]) & 0xFFFFFFFF:08x}"
                                        except Exception:
                                            record[key] = str(record[key])
                                forced_trace.append(record)
                            trace_tail = [
                                f"0x{int(bb) & 0xFFFFFFFF:08x}"
                                for bb in list(getattr(trace, "executed_bbs", []) or [])[-16:]
                            ]
                            skip_stats = dict(getattr(emulator, "skip_function_stats", {}) or {})
                            candidate_debug_records.append({
                                "pred_bb": f"0x{pred_bb:08x}",
                                "mnemonic": candidate_mnemonic,
                                "successor_bb": f"0x{int(successor_bb):08x}",
                                "choice_type": choice_identity(choice)[0],
                                "choice_value": serialize_choice(choice),
                                "downstream_potential": int(potential),
                                "semantic_priority": int(semantic_priority),
                                "schedule_reason": str(schedule_reason),
                                "uncovered_immediate": bool(immediate_uncovered),
                                "target_filter_matches": int(target_filter_matches),
                                "target_min_distance": int(target_min_distance),
                                "new_bbs": len(task_new_bbs),
                                "target_bbs": len(task_new_targets),
                                "forced_verified": any(bool(item.get("verified", False)) for item in emulator.forced_branch_trace),
                                "forced_trace": forced_trace,
                                "stop_reason": stop_reason,
                                "trace_tail": trace_tail,
                                "target_probe_hit": bool(target_probe_info.get("hit")),
                                "target_probe_tail": int(target_probe_info.get("tail") or 0),
                                "skip_function_stats": {
                                    "installed": skip_stats.get("installed"),
                                    "applied": skip_stats.get("applied"),
                                    "stateful_applied": skip_stats.get("stateful_applied"),
                                    "by_symbol": dict(skip_stats.get("by_symbol", {}) or {}),
                                },
                                "skip_excluded": [
                                    f"0x{int(address) & ~1:08x}"
                                    for address in sorted(scoped_skip_exclude_addresses)[:16]
                                ],
                                "snapshot_origin": str(getattr(snapshot_entry, "origin", "unknown")),
                                "source_path_len": len(getattr(snapshot_entry, "source_path_signature", tuple()) or tuple()),
                            })
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("frontier_successor_replay_task"),
                            evidence_record=execution_record,
                        )
                        multiway_candidate = _is_switch_frontier_mnemonic(candidate_mnemonic)
                        refreshable_progress = (
                            bool(task_new_bbs)
                            and not multiway_candidate
                            and not stop_reason.startswith("Invalid memory")
                            and stop_reason != "fatal_sink_terminal"
                        )
                        if refreshable_progress:
                            progress_tasks_since_refresh += 1
                            if progress_tasks_since_refresh >= refresh_after_progress_tasks:
                                refreshed_after_progress = True
                                break
                    if refreshed_after_progress:
                        break
            if tasks_run == tasks_before_round:
                break

        stall_watchdog = getattr(self, "stall_watchdog", None)
        stall_watchdog_stop_reason = None
        if stall_watchdog is not None and stall_watchdog.should_stop():
            stall_watchdog_stop_reason = str(
                (stall_watchdog.stop_report() or {}).get("reason")
                or STALL_WATCHDOG_STOP_REASON
            )
            stop_reasons[stall_watchdog_stop_reason] += 1
        elif (
            stall_watchdog is not None
            and stall_watchdog.should_truncate_stage(phase_name)
        ):
            stall_watchdog_stop_reason = "stall_watchdog_stage_truncated"
            stop_reasons[stall_watchdog_stop_reason] += 1

        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation="entry_derived_frontier_branch_snapshot_replay",
            evidence_class=EVIDENCE_E2,
            counterfactual_control=True,
            child_execution_summary=self._child_execution_summary(
                tasks_run,
                child_execution_interventions,
                expected_count=task_attempts,
                attempted_count=task_attempts,
                execution_records=child_execution_records,
            ),
            frontier_successor_candidates=last_candidate_count,
            frontier_successor_candidate_rounds=candidate_rounds,
            frontier_successor_candidate_total=candidate_count_total,
            frontier_successor_edges_attempted=len(attempted_successor_edges),
            frontier_successor_snapshot_attempts=len(attempted_successor_snapshot_edges),
            tasks_run=tasks_run,
            task_attempts=task_attempts,
            child_execution_failure_count=sum(
                1
                for record in child_execution_records
                if bool(record.get("failure_reason"))
            ),
            tasks_with_new_bbs=tasks_with_new_bbs,
            tasks_with_target_bbs=tasks_with_target_bbs,
            target_bbs=len(target_bb_set),
            target_bbs_discovered=len(target_bbs_discovered),
            target_bbs_discovered_list=[f"0x{bb:08x}" for bb in sorted(target_bbs_discovered)[:256]],
            restore_failed=restore_failed,
            invalid_snapshots=invalid_snapshots,
            invalid_snapshot_reasons=dict(invalid_reasons),
            forced_choices_requested=forced_choices_requested,
            forced_choices_hit=forced_choices_hit,
            forced_choices_verified=forced_choices_verified,
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            stop_reasons=dict(stop_reasons),
            stall_watchdog_stop_reason=stall_watchdog_stop_reason,
            target_filtered_replay=target_filtered_replay,
            max_choices_per_pred_round=max_choices_per_pred_round,
            max_snapshots_per_edge_round=max_snapshots_per_edge_round,
            max_attempts_per_edge_stage=max_attempts_per_edge_stage,
            target_hit_limit_per_edge_stage=target_hit_limit_per_edge_stage,
            zero_new_limit_per_edge_stage=zero_new_limit_per_edge_stage,
            choices_suppressed_by_pred_limit=choices_suppressed_by_pred_limit,
            snapshots_suppressed_by_edge_limit=snapshots_suppressed_by_edge_limit,
            edges_suppressed_by_stage_target_hit=edges_suppressed_by_stage_target_hit,
            edges_suppressed_by_stage_zero_new=edges_suppressed_by_stage_zero_new,
            edges_suppressed_by_stage_attempt_limit=edges_suppressed_by_stage_attempt_limit,
            stage_edge_attempts=len(stage_edge_attempts),
            stage_edge_target_hits=len(stage_edge_target_hits),
            stage_edge_zero_new=len(stage_edge_zero_new),
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            no_new_bb_limit=no_new_bb_limit,
            max_tasks=max_tasks,
            max_targets=max_targets,
            variants_per_branch=variants_per_branch,
            time_limit_seconds=time_limit_seconds,
            target_probe_after_hit_bbs=target_probe_after_hit_bbs,
            refresh_after_progress_tasks=refresh_after_progress_tasks,
            max_successor_hits_per_stage=max_successor_hits_per_stage,
            max_successor_zero_new_per_stage=max_successor_zero_new_per_stage,
            target_probe_hits=target_probe_hits,
            target_probe_stops=target_probe_stops,
            successors_suppressed_by_hit_limit=successors_suppressed_by_hit_limit,
            successors_suppressed_by_zero_new_limit=successors_suppressed_by_zero_new_limit,
            successors_suppressed_by_native_crash_blacklist=successors_suppressed_by_native_crash_blacklist,
            native_crash_blacklist_entries=len(native_crash_blacklist),
            covered_downstream_suppressed=covered_downstream_suppressed,
            covered_downstream_successor_replay_enabled=allow_covered_downstream_successor_replay,
            successor_hits=len(successor_hits),
            successor_zero_new=len(successor_zero_new),
            task_wall_seconds_min=round(min(task_wall_seconds), 6) if task_wall_seconds else 0.0,
            task_wall_seconds_max=round(max(task_wall_seconds), 6) if task_wall_seconds else 0.0,
            task_wall_seconds_avg=(
                round(sum(task_wall_seconds) / len(task_wall_seconds), 6)
                if task_wall_seconds
                else 0.0
            ),
            candidate_debug_records=candidate_debug_records,
            frontier_successor_candidate_selection=last_candidate_selection,
            frontier_successor_candidate_diagnostics=last_candidate_diagnostics,
        )

    def run_direct_call_continuation_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        max_tasks: int = 64,
        max_instructions: int = 80000,
        replay_timeout: int = 1_000_000,
        no_new_bb_limit: int = 4096,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 64,
        variants_per_call: int = 2,
        low_yield_stop_tasks: int = 0,
        low_yield_min_tasks: int = 0,
        phase_name: str = "direct_call_continuation",
    ) -> Set[int]:
        """
        Continue from direct BL states that were first reached from reset-entry execution.

        This does not invent a branch choice for BL. It restores an entry-derived
        snapshot at the BL BB and lets Unicorn execute the direct call/return
        path naturally under the same MMIO constraint machinery.
        """
        start_time = time.time()
        target_bb_set = self.validate_coverage(target_bbs or set())
        candidates = self._direct_call_frontier_candidates(
            target_bbs=target_bb_set if target_bb_set else None,
            max_targets=max_targets,
        )
        phase_covered: Set[int] = set()
        tasks_run = 0
        candidate_rounds = 0
        candidate_count_total = 0
        last_candidate_count = 0
        attempted_snapshot_entries: Set[Tuple[int, Tuple[object, ...]]] = set()
        skipped_attempted_snapshot_entries = 0
        restore_failed = 0
        invalid_snapshots = 0
        invalid_reasons: Counter[str] = Counter()
        tasks_with_new_bbs = 0
        tasks_with_target_bbs = 0
        target_bbs_discovered: Set[int] = set()
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        stop_reasons: Counter[str] = Counter()
        candidate_debug_records: List[Dict[str, object]] = []
        last_candidate_diagnostics: Dict[str, object] = {}
        consecutive_low_yield_tasks = 0
        low_yield_stop_triggered = False
        child_execution_interventions: Counter[str] = Counter()
        child_execution_records: List[Dict[str, object]] = []

        def budget_exhausted() -> bool:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                return True
            return max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks

        def low_yield_budget_exhausted() -> bool:
            return (
                low_yield_stop_tasks is not None
                and int(low_yield_stop_tasks) > 0
                and tasks_run >= max(0, int(low_yield_min_tasks))
                and consecutive_low_yield_tasks >= int(low_yield_stop_tasks)
            )

        while not budget_exhausted():
            if low_yield_budget_exhausted():
                low_yield_stop_triggered = True
                break
            candidates = self._direct_call_frontier_candidates(
                coverage=self.global_coverage | phase_covered,
                target_bbs=target_bb_set if target_bb_set else None,
                max_targets=max_targets,
            )
            candidate_rounds += 1
            last_candidate_count = len(candidates)
            candidate_count_total += len(candidates)
            if not candidates:
                last_candidate_diagnostics = self._direct_call_candidate_diagnostics(
                    coverage=self.global_coverage | phase_covered,
                    target_bbs=target_bb_set if target_bb_set else None,
                )
                break
            tasks_before_round = tasks_run
            refreshed_after_progress = False
            for candidate in candidates:
                if budget_exhausted() or low_yield_budget_exhausted() or refreshed_after_progress:
                    break
                pred_bb = int(candidate["pred_bb"])
                uncovered_successors = set(candidate["uncovered_successors"])
                scheduled_successors = set(candidate.get("scheduled_successors") or uncovered_successors)
                candidate_new_bbs: Set[int] = set()
                candidate_new_targets: Set[int] = set()
                last_stop_reason = "not_attempted"
                last_trace_tail: List[str] = []
                last_replay_registers: Dict[str, int] = {}
                last_snapshot_origin = "none"
                last_source_path_len = 0
                last_skip_function_stats: Dict[str, object] = {}
                last_prelude_memory_stats: Dict[str, object] = {}
                last_pointer_arg_repair_stats: Dict[str, object] = {}
                last_unmapped_access: Dict[str, object] = {}
                direct_target_successor = candidate.get("direct_target_successor")
                top_level_call_exclude_addresses: Set[int] = set()
                # A direct-call continuation restores a state inside the caller
                # at the callsite. Skip summaries are useful for unrelated
                # blocking IO/time helpers, but skipping the current caller
                # itself returns before the target callee can execute.
                top_level_call_exclude_addresses.add(int(pred_bb) & ~1)
                caller_entry = self._function_entry_for_addr(int(pred_bb))
                if caller_entry is not None:
                    top_level_call_exclude_addresses.add(int(caller_entry) & ~1)
                if (
                    direct_target_successor is not None
                    and int(direct_target_successor) in scheduled_successors
                ):
                    top_level_call_exclude_addresses.add(int(direct_target_successor))
                snapshot_entries = []
                candidate_entries = _segment_rotate_sequence(
                    list(candidate.get("unattempted_snapshot_entries") or candidate["snapshot_entries"]),
                    f"direct_call_snapshots:{pred_bb}",
                )
                for snapshot_entry in candidate_entries:
                    snapshot_key = self._direct_call_attempt_key(pred_bb, snapshot_entry)
                    if (
                        snapshot_key in attempted_snapshot_entries
                        or snapshot_key in self.direct_call_snapshot_attempts_seen
                    ):
                        skipped_attempted_snapshot_entries += 1
                        continue
                    if self._direct_call_failure_penalty(pred_bb, snapshot_entry) >= 64:
                        skipped_attempted_snapshot_entries += 1
                        continue
                    snapshot_entries.append(snapshot_entry)
                    if len(snapshot_entries) >= max(1, variants_per_call):
                        break
                if not snapshot_entries:
                    continue
                for snapshot_entry in snapshot_entries:
                    if budget_exhausted() or low_yield_budget_exhausted():
                        break
                    snapshot_key = self._direct_call_attempt_key(pred_bb, snapshot_entry)
                    attempted_snapshot_entries.add(snapshot_key)
                    self.direct_call_snapshot_attempts_seen.add(snapshot_key)
                    valid_snapshot, reason = self._validate_root_snapshot_entry(
                        snapshot_entry,
                        root_key=(pred_bb, 1),
                    )
                    if not valid_snapshot:
                        invalid_snapshots += 1
                        invalid_reasons[str(reason)] += 1
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_continuation"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_continuation')}-"
                                    f"invalid-snapshot-{len(child_execution_records) + 1}"
                                ),
                                reason=f"invalid_snapshot:{reason}",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_snapshot_continuation"
                                    ),
                                    "pred_bb": int(pred_bb),
                                    "coverage_counted": True,
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        reason,
                                    ),
                                },
                                execution_started=False,
                                execution_error=str(reason),
                                run_result={"execution_attempted": True},
                            )
                        )
                        child_execution_interventions[
                            "invalid_snapshot"
                        ] += 1
                        continue

                    try:
                        emulator = self._new_temp_emulator(
                            max_snapshots=max(3, self.max_snapshots),
                            llm_config_path=self._effective_llm_config_path(),
                            constraint_json_path=self.constraint_file,
                            branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                            stage_name=self._temp_stage_for("direct_call_continuation_task"),
                        )
                    except Exception as exc:
                        stop_reasons["emulator_create_exception"] += 1
                        logger.debug("direct-call continuation emulator创建失败: %s", exc)
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_continuation"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_continuation')}-"
                                    f"create-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="emulator_create_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_snapshot_continuation"
                                    ),
                                    "pred_bb": int(pred_bb),
                                    "coverage_counted": True,
                                },
                                execution_started=False,
                                execution_error=exc,
                            )
                        )
                        child_execution_interventions[
                            "emulator_create_exception"
                        ] += 1
                        continue
                    temp_mmio = None
                    temp_tracer = None
                    try:
                        self._configure_emulator_feedback(emulator)
                        self._configure_replay_skip_function_returns(
                            emulator,
                            include_time=True,
                            exclude_addresses=top_level_call_exclude_addresses,
                        )
                        emulator.enable_branch_snapshot = True
                        temp_mmio = EnhancedMMIOHandler(
                            emulator.uc,
                            self.constraint_file,
                            branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                        )
                        temp_tracer = self._new_temp_register_tracer(emulator)
                        restored = self._restore_branch_snapshot(
                            emulator,
                            snapshot_entry.snapshot,
                            lineage_source=snapshot_entry,
                        )
                    except Exception as exc:
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(
                                phase_name or "direct_call_continuation"
                            ),
                            execution_id=(
                                f"{str(phase_name or 'direct_call_continuation')}-"
                                f"setup-failure-{len(child_execution_records) + 1}"
                            ),
                            reason="replay_setup_exception",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_snapshot_continuation"
                                ),
                                "pred_bb": int(pred_bb),
                                "coverage_counted": True,
                            },
                            execution_started=False,
                            execution_error=exc,
                        )
                        child_execution_records.append(failure_record)
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("direct_call_continuation_task"),
                            evidence_record=failure_record,
                        )
                        stop_reasons["replay_setup_exception"] += 1
                        logger.debug("direct-call continuation setup失败: %s", exc)
                        child_execution_interventions[
                            "replay_setup_exception"
                        ] += 1
                        continue
                    if not restored:
                        restore_failed += 1
                        stop_reasons["snapshot_restore_failed"] += 1
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "direct_call_continuation"),
                            execution_id=(
                                f"{str(phase_name or 'direct_call_continuation')}"
                                f"-restore-failure-{len(child_execution_records) + 1}"
                            ),
                            reason="snapshot_restore_failed",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_snapshot_continuation"
                                ),
                                **self._snapshot_restore_failure_metadata(
                                    snapshot_entry,
                                    "branch snapshot restore returned false",
                                ),
                            },
                            execution_started=False,
                            execution_error="branch snapshot restore returned false",
                            run_result={"restore_failed": True},
                        )
                        child_execution_records.append(failure_record)
                        child_execution_interventions["snapshot_restore_failed"] += 1
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("direct_call_continuation_task"),
                            evidence_record=failure_record,
                        )
                        continue
                    if not self._restore_replay_mmio_state(
                        emulator,
                        temp_mmio,
                        snapshot_entry.mmio_state,
                    ):
                        restore_failed += 1
                        stop_reasons["replay_mmio_state_restore_failed"] += 1
                        restore_error = self._replay_mmio_restore_failure_reason(
                            emulator
                        )
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "direct_call_continuation"),
                            execution_id=(
                                f"{str(phase_name or 'direct_call_continuation')}"
                                f"-mmio-restore-failure-{len(child_execution_records) + 1}"
                            ),
                            reason="replay_mmio_state_restore_failed",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_snapshot_continuation"
                                ),
                                **self._snapshot_restore_failure_metadata(
                                    snapshot_entry,
                                    restore_error,
                                ),
                            },
                            execution_started=False,
                            execution_error=restore_error,
                            run_result={"restore_failed": True},
                        )
                        child_execution_records.append(failure_record)
                        child_execution_interventions[
                            "replay_mmio_state_restore_failed"
                        ] += 1
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("direct_call_continuation_task"),
                            evidence_record=failure_record,
                        )
                        continue
                    self._apply_scoped_branch_constraints(
                        temp_mmio,
                        self._scope_signature_from_snapshot_entry(snapshot_entry),
                        emulator=emulator,
                    )
                    last_prelude_memory_stats = self._materialize_direct_call_prelude_memory(
                        emulator,
                        pred_bb,
                        int(self.prepared.branch_instruction_by_bb.get(pred_bb, {}).get("address", pred_bb) or pred_bb),
                    )
                    last_pointer_arg_repair_stats = self._materialize_direct_call_callee_pointer_arguments(
                        emulator,
                        pred_bb,
                        int(self.prepared.branch_instruction_by_bb.get(pred_bb, {}).get("address", pred_bb) or pred_bb),
                    )

                    # The normal ``run`` result has its own counter delta, but
                    # the direct evidence adapter also reads the owning MMIO
                    # handler.  Capture that adapter baseline after snapshot
                    # restoration and all replay preparation so prefix RX
                    # telemetry cannot overwrite the per-task delta.
                    execution_baseline = self._capture_direct_execution_baseline(
                        emulator,
                        str(phase_name or "direct_call_continuation"),
                        mmio_handler=temp_mmio,
                    )

                    known_before = self.global_coverage | phase_covered
                    previous_quiescence_limit = emulator.stop_after_no_new_bbs
                    emulator.stop_after_no_new_bbs = (
                        max(1, int(no_new_bb_limit))
                        if no_new_bb_limit and no_new_bb_limit > 0
                        else None
                    )
                    run_result: Dict[str, object] = {"stop_reason": "not_started"}
                    with self.guided_modules(temp_mmio, temp_tracer), self.capture_execution_trace(emulator) as trace:
                        try:
                            run_result = emulator.run(
                                entry_point=None,
                                max_instructions=max_instructions,
                                timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                                preserve_cpu_state=True,
                            )
                        except Exception as exc:
                            run_result = self._materialize_replay_failure_result(
                                "execution_exception",
                                execution_started=True,
                                execution_error=exc,
                            )
                        finally:
                            emulator.stop_after_no_new_bbs = previous_quiescence_limit

                    execution_failed = bool(run_result.get("execution_failed")) or bool(
                        run_result.get("preflight_failed")
                    )
                    valid = (
                        set()
                        if execution_failed
                        else self.validate_coverage(trace.covered_bbs)
                    )
                    if execution_failed:
                        execution_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "direct_call_continuation"),
                            execution_id=(
                                f"{str(phase_name or 'direct_call_continuation')}"
                                f"-task-{tasks_run + 1}"
                            ),
                            reason=str(
                                run_result.get("stop_reason") or "execution_failed"
                            ),
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_snapshot_continuation"
                                ),
                                "pred_bb": int(pred_bb),
                            },
                            covered_bbs=(),
                            execution_started=bool(
                                run_result.get("execution_started", False)
                            ),
                            execution_error=run_result.get("execution_error"),
                            run_result=run_result,
                        )
                    else:
                        execution_record = self._direct_execution_evidence_record(
                            phase_name=str(phase_name or "direct_call_continuation"),
                            emulator=emulator,
                            covered_bbs=trace.covered_bbs,
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_snapshot_continuation"
                                ),
                                "coverage_counted": True,
                                "pred_bb": int(pred_bb),
                                "snapshot_origin": str(
                                    getattr(snapshot_entry, "origin", "unknown")
                                ),
                            },
                            stop_reason=str(
                                run_result.get("stop_reason")
                                or "direct_unicorn_execution_completed"
                            ),
                            execution_started=bool(
                                run_result.get("execution_started", True)
                            ),
                            run_result=run_result,
                            execution_baseline=execution_baseline,
                            execution_id=str(
                                run_result.get("execution_id")
                                or f"{str(phase_name or 'direct_call_continuation')}-task-{tasks_run + 1}"
                            ),
                            mmio_handler=temp_mmio,
                        )
                    child_execution_records.append(execution_record)

                    def safe_postprocess(operation: str, callback, default=None):
                        return self._safe_replay_postprocess(
                            operation,
                            callback,
                            evidence_record=execution_record,
                            run_result=run_result,
                            default=default,
                        )

                    child_execution_interventions.update(
                        execution_record.get("actual_intervention_reasons", {}) or {}
                    )
                    last_skip_function_stats = dict(getattr(emulator, "skip_function_stats", {}) or {})
                    task_new_bbs = valid - known_before
                    task_new_targets = task_new_bbs & (target_bb_set or scheduled_successors)
                    if task_new_bbs:
                        tasks_with_new_bbs += 1
                    if task_new_targets:
                        tasks_with_target_bbs += 1
                        target_bbs_discovered.update(task_new_targets)
                    phase_covered.update(valid)
                    safe_postprocess(
                        "coverage_evidence",
                        lambda: self._record_coverage_evidence(EVIDENCE_E3, valid),
                    )

                    replay_events = safe_postprocess(
                        "branch_event_collection",
                        lambda: emulator.branch_snapshot_manager.get_ordered_events(),
                        default=[],
                    ) or []
                    replay_snapshots = safe_postprocess(
                        "replay_snapshot_collection",
                        lambda: self._ordered_replay_snapshots(emulator),
                        default=[],
                    ) or []
                    task_remembered_branch_events = safe_postprocess(
                        "branch_event_feedback",
                        lambda: self._remember_main_branch_events(
                            replay_events,
                            evidence_class=EVIDENCE_E3,
                        ),
                        default=0,
                    ) or 0
                    task_remembered_branch_root_snapshots = safe_postprocess(
                        "branch_snapshot_feedback",
                        lambda: self._remember_branch_root_snapshots(
                            replay_events,
                            replay_snapshots,
                            source_path_signature=getattr(snapshot_entry, "source_path_signature", tuple()) or tuple(),
                            evidence_class=EVIDENCE_E3,
                        ),
                        default=0,
                    ) or 0
                    task_dynamic_successor_edges = safe_postprocess(
                        "dynamic_successor_feedback",
                        lambda: self._record_dynamic_successors(replay_events),
                        default=0,
                    ) or 0
                    task_dynamic_successor_edges += safe_postprocess(
                        "runtime_successor_feedback",
                        lambda: self._record_emulator_runtime_successors(emulator),
                        default=0,
                    ) or 0
                    remembered_branch_events += task_remembered_branch_events
                    remembered_branch_root_snapshots += task_remembered_branch_root_snapshots
                    dynamic_successor_edges_added += task_dynamic_successor_edges
                    safe_postprocess(
                        "scheduler_feedback",
                        lambda: self._harvest_emulator_feedback(emulator),
                    )
                    safe_postprocess(
                        "register_tracer_merge",
                        lambda: self.register_tracer.merge_from(temp_tracer),
                    )

                    tasks_run += 1
                    stop_reason = str(run_result.get("stop_reason") or "unknown")
                    stop_reasons[stop_reason] += 1
                    task_structural_progress = task_dynamic_successor_edges > 0
                    if task_new_bbs or task_new_targets or task_structural_progress:
                        consecutive_low_yield_tasks = 0
                    else:
                        consecutive_low_yield_tasks += 1
                    safe_postprocess(
                        "direct_call_outcome_feedback",
                        lambda: self._record_direct_call_attempt_outcome(
                            pred_bb,
                            snapshot_entry,
                            new_bbs=len(task_new_bbs),
                            stop_reason=stop_reason,
                        ),
                    )
                    candidate_new_bbs.update(task_new_bbs)
                    candidate_new_targets.update(task_new_targets)
                    last_stop_reason = stop_reason
                    last_trace_tail = [
                        f"0x{int(bb):08x}"
                        for bb in list(getattr(trace, "executed_bbs", []) or [])[-16:]
                    ]
                    try:
                        last_replay_registers = emulator._get_registers()
                    except Exception:
                        last_replay_registers = {}
                    last_snapshot_origin = str(getattr(snapshot_entry, "origin", "unknown"))
                    last_source_path_len = len(
                        getattr(snapshot_entry, "source_path_signature", tuple()) or tuple()
                    )
                    last_unmapped_access = dict(getattr(emulator, "last_run_result", {}).get("last_unmapped_access", {}) or {})
                    if not last_unmapped_access:
                        last_unmapped_access = dict(getattr(emulator, "last_unmapped_access", {}) or {})
                    self._safe_dispose_temp_emulator(
                        emulator,
                        mmio_handler=temp_mmio,
                        register_tracer=temp_tracer,
                        quarantine=None,
                        stage_name=self._temp_stage_for("direct_call_continuation_task"),
                        evidence_record=execution_record,
                    )
                    if low_yield_budget_exhausted():
                        low_yield_stop_triggered = True
                        break
                if len(candidate_debug_records) < 32:
                    candidate_debug_records.append({
                        "pred_bb": f"0x{pred_bb:08x}",
                        "uncovered_successors": [
                            f"0x{successor:08x}" for successor in sorted(uncovered_successors)[:8]
                        ],
                        "scheduled_successors": [
                            f"0x{successor:08x}" for successor in sorted(scheduled_successors)[:8]
                        ],
                        "successor_items": [
                            {
                                **{
                                    key: value
                                    for key, value in item.items()
                                    if key not in {"successor", "target_filter_match_list"}
                                },
                                "successor": f"0x{int(item.get('successor', 0) or 0):08x}",
                                "target_filter_match_list": [
                                    f"0x{int(bb):08x}"
                                    for bb in list(item.get("target_filter_match_list", []) or [])[:8]
                                ],
                            }
                            for item in list(candidate.get("successor_items", []) or [])[:8]
                        ],
                        "static_successors": [
                            f"0x{successor:08x}"
                            for successor in sorted(candidate.get("successors", []))[:8]
                        ],
                        "direct_target_successor": (
                            f"0x{int(candidate['direct_target_successor']):08x}"
                            if candidate.get("direct_target_successor") is not None
                            else None
                        ),
                        "fallthrough_successor": (
                            f"0x{int(candidate['fallthrough_successor']):08x}"
                            if candidate.get("fallthrough_successor") is not None
                            else None
                        ),
                        "return_fallthrough_uncovered": bool(candidate.get("return_fallthrough_uncovered")),
                        "target_filter_matches": int(candidate.get("target_filter_matches", 0) or 0),
                        "unattempted_snapshot_count": int(candidate.get("unattempted_snapshot_count", 0) or 0),
                        "downstream_potential": int(candidate.get("downstream_potential", 0) or 0),
                        "min_failure_penalty": int(candidate.get("min_failure_penalty", 0) or 0),
                        "snapshot_prelude_rank_sample": candidate.get("snapshot_prelude_rank_sample", []),
                        "top_level_skip_excluded": [
                            f"0x{int(address):08x}"
                            for address in sorted(top_level_call_exclude_addresses)
                        ],
                        "prelude_memory_stats": last_prelude_memory_stats,
                        "pointer_arg_repair_stats": last_pointer_arg_repair_stats,
                        "skip_function_stats": last_skip_function_stats,
                        "new_bbs": len(candidate_new_bbs),
                        "target_bbs": len(candidate_new_targets),
                        "stop_reason": last_stop_reason,
                        "last_unmapped_access": last_unmapped_access,
                        "trace_tail": last_trace_tail,
                        "pc": f"0x{int(last_replay_registers.get('pc', 0) or 0) & 0xFFFFFFFF:08x}",
                        "lr": f"0x{int(last_replay_registers.get('lr', 0) or 0) & 0xFFFFFFFF:08x}",
                        "sp": f"0x{int(last_replay_registers.get('sp', 0) or 0) & 0xFFFFFFFF:08x}",
                        "snapshot_origin": last_snapshot_origin,
                        "source_path_len": last_source_path_len,
                    })
                    if candidate_new_bbs:
                        refreshed_after_progress = True
                        break
                if refreshed_after_progress:
                    break
                if low_yield_stop_triggered:
                    break
            if tasks_run == tasks_before_round:
                break

        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation="entry_derived_direct_call_snapshot_continuation",
            direct_call_frontier_candidates=last_candidate_count,
            direct_call_candidate_rounds=candidate_rounds,
            direct_call_candidate_total=candidate_count_total,
            direct_call_snapshot_addresses=len(self.direct_call_snapshots),
            direct_call_snapshot_variants=sum(len(entries) for entries in self.direct_call_snapshots.values()),
            direct_call_snapshot_attempts=len(attempted_snapshot_entries),
            direct_call_global_snapshot_attempts_seen=len(self.direct_call_snapshot_attempts_seen),
            direct_call_snapshot_skipped_already_attempted=skipped_attempted_snapshot_entries,
            tasks_run=tasks_run,
            tasks_with_new_bbs=tasks_with_new_bbs,
            tasks_with_target_bbs=tasks_with_target_bbs,
            target_bbs=len(target_bb_set),
            target_bbs_discovered=len(target_bbs_discovered),
            target_bbs_discovered_list=[f"0x{bb:08x}" for bb in sorted(target_bbs_discovered)[:256]],
            restore_failed=restore_failed,
            invalid_snapshots=invalid_snapshots,
            invalid_snapshot_reasons=dict(invalid_reasons),
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            stop_reasons=dict(stop_reasons),
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            no_new_bb_limit=no_new_bb_limit,
            max_tasks=max_tasks,
            max_targets=max_targets,
            variants_per_call=variants_per_call,
            time_limit_seconds=time_limit_seconds,
            low_yield_stop_tasks=int(low_yield_stop_tasks or 0),
            low_yield_min_tasks=int(low_yield_min_tasks or 0),
            consecutive_low_yield_tasks=int(consecutive_low_yield_tasks),
            low_yield_stop_triggered=bool(low_yield_stop_triggered),
            candidate_debug_records=candidate_debug_records,
            direct_call_candidate_diagnostics=last_candidate_diagnostics,
            child_execution_summary=self._child_execution_summary(
                len(child_execution_records),
                child_execution_interventions,
                expected_count=len(attempted_snapshot_entries),
                attempted_count=len(attempted_snapshot_entries),
                execution_records=child_execution_records,
            ),
        )

    @staticmethod
    def _call_summary_return_symbol_enabled(symbol: str) -> bool:
        name = str(symbol or "").strip().lower()
        if not name:
            return False
        exact = {
            "__malloc_lock",
            "__malloc_unlock",
            "__retarget_lock_acquire_recursive",
            "__retarget_lock_release_recursive",
            "__retarget_lock_init_recursive",
            "__sinit",
            "__sinit_lock_acquire",
            "__sinit_lock_release",
            "_init",
            "_calloc_r",
            "_free_r",
            "_malloc_r",
            "_realloc_r",
            "_puts_r",
            "_read_r",
            "_sbrk_r",
            "_write_r",
            "calloc",
            "free",
            "iprintf",
            "malloc",
            "memcmp",
            "memchr",
            "putchar",
            "puts",
            "realloc",
            "sbrk",
            "sbrk_aligned",
            "strcmp",
            "strncmp",
            "strlen",
        }
        if name in exact:
            return True
        prefixes = (
            "auto_init",
            "board_init",
            "periph_init",
            "stdio_init",
            "uart_init",
            "timer_init",
            "gpio_init",
            "random_init",
        )
        if any(name.startswith(prefix) for prefix in prefixes):
            return True
        # These helpers often represent HAL/RTOS waits or side-effect-only I/O
        # wrappers.  Summarizing them does not credit the callee; it only resumes
        # from an entry-derived callsite.  Tokenized matching avoids treating
        # names like ``clock`` as lock primitives.
        return _summary_symbol_enabled(name)

    @staticmethod
    def _direct_call_summary_allowlist_eager_enabled() -> bool:
        return _env_flag("LSGEMU_DIRECT_CALL_SUMMARY_ALLOWLIST_EAGER", "0")

    def _direct_call_summary_fallback_allowed(
        self,
        pred_bb: int,
        snapshot_entries: Iterable[PrefixReplaySnapshot],
    ) -> Tuple[bool, str]:
        """
        Permit a call summary only after concrete callee replay has shown that
        this callsite is a low-yield blocker.  This keeps arbitrary function
        skipping out of the default path while still allowing the explorer to
        drain a real caller continuation when the callee repeatedly times out or
        faults under entry-derived state.
        """
        attempts = 0
        zero_new_attempts = 0
        blocking_attempts = 0
        blocking_stop_prefixes = (
            "timeout",
            "quiescence",
            "invalid memory",
            "invalid instruction",
            "fatal_sink",
            "exception",
        )
        for snapshot_entry in snapshot_entries or []:
            record = self.direct_call_candidate_failures.get(
                self._direct_call_attempt_key(int(pred_bb), snapshot_entry)
            )
            if not record:
                continue
            attempt_count = int(record.get("attempts", 0) or 0)
            attempts += attempt_count
            if int(record.get("new_bbs", 0) or 0) <= 0:
                zero_new_attempts += attempt_count
            stop_reasons = record.get("stop_reasons") or {}
            if isinstance(stop_reasons, Counter):
                reason_items = stop_reasons.items()
            elif isinstance(stop_reasons, dict):
                reason_items = stop_reasons.items()
            else:
                reason_items = []
            for reason, count in reason_items:
                reason_text = str(reason or "").strip().lower()
                if any(reason_text.startswith(prefix) for prefix in blocking_stop_prefixes):
                    blocking_attempts += int(count or 0)
        if attempts <= 0:
            return False, "no_prior_concrete_call_attempt"
        if zero_new_attempts <= 0:
            return False, "prior_call_attempt_had_new_bbs"
        if blocking_attempts <= 0:
            return False, "prior_call_attempt_not_blocking"
        return True, "fallback_after_blocking_concrete_call"

    @staticmethod
    def _direct_call_summary_outcome_key(pred_bb: int, fallthrough: int, symbol: object) -> Tuple[int, int, str]:
        return (
            int(pred_bb) & 0xFFFFFFFF,
            int(fallthrough) & 0xFFFFFFFF,
            str(symbol or "").strip().lower(),
        )

    def _direct_call_summary_yield_penalty(self, pred_bb: int, fallthrough: int, symbol: object) -> int:
        record = self.direct_call_summary_return_outcomes.get(
            self._direct_call_summary_outcome_key(pred_bb, fallthrough, symbol)
        )
        if not record:
            return 0
        attempts = int(record.get("attempts", 0) or 0)
        new_bbs = int(record.get("new_bbs", 0) or 0)
        target_bbs = int(record.get("target_bbs", 0) or 0)
        if attempts <= 0:
            return 0
        if new_bbs > 0 or target_bbs > 0:
            return -min(50, new_bbs + target_bbs)
        return min(200, attempts * (20 if _is_low_value_summary_symbol(symbol) else 10))

    def _record_direct_call_summary_outcome(
        self,
        pred_bb: int,
        fallthrough: int,
        symbol: object,
        *,
        new_bbs: int,
        target_bbs: int,
        stop_reason: str,
    ) -> None:
        record = self.direct_call_summary_return_outcomes.setdefault(
            self._direct_call_summary_outcome_key(pred_bb, fallthrough, symbol),
            {
                "attempts": 0,
                "new_bbs": 0,
                "target_bbs": 0,
                "stop_reasons": Counter(),
            },
        )
        record["attempts"] = int(record.get("attempts", 0) or 0) + 1
        record["new_bbs"] = int(record.get("new_bbs", 0) or 0) + int(new_bbs)
        record["target_bbs"] = int(record.get("target_bbs", 0) or 0) + int(target_bbs)
        stop_reasons = record.get("stop_reasons")
        if not isinstance(stop_reasons, Counter):
            stop_reasons = Counter(stop_reasons or {})
            record["stop_reasons"] = stop_reasons
        stop_reasons[str(stop_reason or "unknown")] += 1

    def _direct_call_summary_return_candidates(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 0,
    ) -> List[Dict[str, object]]:
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        scope = self.prepared.valid_bb_set if self.prepared.valid_bb_set else self.prepared.static_bb_set
        target_filter = self.validate_coverage(target_bbs or set()) if target_bbs else set()
        effective_successors = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        candidates: List[Dict[str, object]] = []

        def downstream_potential(start_bb: int) -> int:
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return len((reachable & scope) - covered)

        def downstream_targets(start_bb: int) -> Set[int]:
            if not target_filter:
                return set()
            reachable = self._static_reachable_from_cached(
                int(start_bb),
                effective_successors,
                reachable_cache,
            )
            return reachable & target_filter

        for pred_bb in sorted(covered):
            insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
            if not _is_direct_call_mnemonic(insn.get("mnemonic")):
                continue
            direct_target, direct_symbol = self._direct_call_target_symbol(insn)
            if direct_target is None:
                continue
            fallthrough = self._direct_call_fallthrough_bb(pred_bb)
            if fallthrough is None:
                continue
            fallthrough = int(fallthrough)
            potential = downstream_potential(fallthrough)
            target_matches = downstream_targets(fallthrough)
            # Broad summary-return from already-covered continuations tends to
            # re-enter hot main/scheduler loops. Keep those callsites only when
            # a targeted frontier is known downstream; otherwise spend the
            # budget on immediate uncovered continuations or real branch replay.
            if target_filter:
                if fallthrough in covered and not target_matches:
                    continue
            elif fallthrough in covered:
                continue
            branch_pc = int(insn.get("address", pred_bb) or pred_bb)
            snapshot_entries = self._rank_direct_call_snapshot_entries(
                int(pred_bb),
                branch_pc,
                self._direct_call_snapshot_entries(int(pred_bb)),
            )
            if not snapshot_entries:
                continue
            eager_allowlist = self._call_summary_return_symbol_enabled(direct_symbol)
            summary_policy = "symbol_allowlist_eager" if eager_allowlist else "fallback_only_symbol_not_allowlisted"
            if not eager_allowlist or not self._direct_call_summary_allowlist_eager_enabled():
                fallback_allowed, fallback_reason = self._direct_call_summary_fallback_allowed(
                    int(pred_bb),
                    snapshot_entries,
                )
                if not fallback_allowed:
                    continue
                if eager_allowlist and not self._direct_call_summary_allowlist_eager_enabled():
                    summary_policy = f"allowlist_but_{fallback_reason}"
                else:
                    summary_policy = fallback_reason
            candidates.append({
                "pred_bb": int(pred_bb),
                "call_insn": insn,
                "direct_target": int(direct_target),
                "direct_symbol": str(direct_symbol or ""),
                "summary_policy": summary_policy,
                "fallthrough": fallthrough,
                "fallthrough_semantic_priority": self._semantic_priority_for_bb(fallthrough),
                "summary_symbol_priority": _summary_symbol_priority(direct_symbol),
                "summary_yield_penalty": self._direct_call_summary_yield_penalty(
                    int(pred_bb),
                    fallthrough,
                    direct_symbol,
                ),
                "downstream_potential": int(potential),
                "target_matches": len(target_matches),
                "target_match_list": sorted(target_matches)[:32],
                "snapshot_entries": snapshot_entries,
                "summary_category": self._direct_call_summary_category(direct_symbol),
                "snapshot_prelude_rank_sample": [
                    self._direct_call_snapshot_prelude_stats(
                        int(pred_bb),
                        branch_pc,
                        entry,
                        max_records=3,
                    )
                    for entry in snapshot_entries[:3]
                ],
            })

        candidates.sort(
            key=lambda item: (
                int(item.get("target_matches", 0) or 0),
                1 if int(item.get("fallthrough", 0) or 0) not in covered else 0,
                -int(item.get("summary_yield_penalty", 0) or 0),
                int(item.get("summary_symbol_priority", 0) or 0),
                int(item.get("fallthrough_semantic_priority", 0) or 0),
                int(item.get("downstream_potential", 0) or 0),
                -int(item.get("pred_bb", 0) or 0),
            ),
            reverse=True,
        )
        candidates = _segment_rotate_sequence(candidates, "summary_return_candidates")
        return self._fair_direct_call_summary_candidates(
            candidates,
            max_targets if max_targets and max_targets > 0 else len(candidates),
        )

    @staticmethod
    def _direct_call_summary_category(symbol: object) -> str:
        if _is_blocking_summary_symbol(symbol):
            return "blocking_wait"
        if _is_time_summary_symbol(symbol):
            return "time"
        if _is_buffered_input_summary_symbol(symbol):
            return "buffered_input"
        if _is_input_state_summary_symbol(symbol):
            return "input_state"
        if _is_low_value_summary_symbol(symbol):
            return "low_value"
        return "generic"

    @staticmethod
    def _fair_direct_call_summary_candidates(
        candidates: List[Dict[str, object]],
        limit: int,
    ) -> List[Dict[str, object]]:
        """Keep top candidates but reserve budget for different summary classes."""
        if not candidates:
            return candidates
        limit = max(0, int(limit))
        if limit <= 0 or limit > len(candidates):
            limit = len(candidates)
        category_order = [
            "blocking_wait",
            "buffered_input",
            "input_state",
            "time",
            "generic",
            "low_value",
        ]
        category_queues: Dict[str, deque] = {category: deque() for category in category_order}
        for item in candidates:
            category = str(item.get("summary_category") or "generic")
            category_queues.setdefault(category, deque()).append(item)
        selected: List[Dict[str, object]] = []
        selected_ids: Set[Tuple[int, int, str]] = set()
        selected_by_symbol: Counter[str] = Counter()

        def candidate_id(item: Dict[str, object]) -> Tuple[int, int, str]:
            return (
                int(item.get("pred_bb", 0) or 0),
                int(item.get("fallthrough", 0) or 0),
                str(item.get("direct_symbol") or ""),
            )

        def symbol_limit(item: Dict[str, object]) -> int:
            category = str(item.get("summary_category") or "generic")
            if category == "low_value":
                return 2
            if category == "time":
                return 3
            if category == "blocking_wait":
                return 6
            return 4

        made_progress = True
        while len(selected) < limit and made_progress:
            made_progress = False
            for category in category_order:
                queue = category_queues.get(category)
                if not queue:
                    continue
                skipped: List[Dict[str, object]] = []
                picked = None
                while queue:
                    item = queue.popleft()
                    key = candidate_id(item)
                    symbol_key = str(item.get("direct_symbol") or "").strip().lower()
                    if key in selected_ids:
                        continue
                    if selected_by_symbol[symbol_key] >= symbol_limit(item):
                        skipped.append(item)
                        continue
                    picked = item
                    break
                queue.extendleft(reversed(skipped))
                if picked is None:
                    continue
                key = candidate_id(picked)
                selected.append(picked)
                selected_ids.add(key)
                selected_by_symbol[str(picked.get("direct_symbol") or "").strip().lower()] += 1
                made_progress = True
                if len(selected) >= limit:
                    break

        for item in candidates:
            if len(selected) >= limit:
                break
            key = candidate_id(item)
            if key in selected_ids:
                continue
            category = str(item.get("summary_category") or "generic")
            if category == "low_value" and any(
                str(other.get("summary_category") or "") != "low_value"
                for other in candidates
                if candidate_id(other) not in selected_ids
            ):
                continue
            selected.append(item)
            selected_ids.add(key)
        return selected

    def _direct_call_fallthrough_bb(self, pred_bb: int) -> Optional[int]:
        instructions = self.prepared.static_bbs.get(int(pred_bb), [])
        if not instructions:
            return None
        last = instructions[-1]
        try:
            fallthrough_addr = int(last.get("address", pred_bb) or pred_bb) + int(last.get("size", 2) or 2)
        except Exception:
            return None
        resolved = self.prepared.resolve_basic_block(fallthrough_addr)
        return int(resolved) if resolved is not None else None

    @staticmethod
    def _direct_call_prelude_access_size(insn: Dict[str, object]) -> int:
        mnemonic = _normalize_mnemonic(insn.get("mnemonic", ""))
        if mnemonic in {"LDRB", "LDRSB", "STRB"}:
            return 1
        if mnemonic in {"LDRH", "LDRSH", "STRH"}:
            return 2
        if mnemonic in {"LDRD", "STRD"}:
            return 8
        return 4

    def _direct_call_prelude_memory_accesses(
        self,
        pred_bb: int,
        branch_pc: int,
        *,
        max_accesses: int = 16,
    ) -> List[Dict[str, object]]:
        """Return simple memory operands that execute before a direct callsite."""
        accesses: List[Dict[str, object]] = []
        instructions = self.prepared.static_bbs.get(int(pred_bb), [])
        if not instructions:
            return accesses
        for insn in instructions:
            try:
                insn_addr = int(insn.get("address", pred_bb) or pred_bb) & ~1
            except Exception:
                continue
            if insn_addr >= (int(branch_pc) & ~1):
                break
            mnemonic = _normalize_mnemonic(insn.get("mnemonic", ""))
            if not (mnemonic.startswith("LDR") or mnemonic.startswith("STR")):
                continue
            try:
                operands = self._split_operands(insn.get("operands", ""))
            except Exception:
                operands = []
            for operand in operands:
                if "[" not in str(operand) or "]" not in str(operand):
                    continue
                accesses.append({
                    "pc": insn_addr,
                    "mnemonic": mnemonic,
                    "operand": str(operand),
                    "size": self._direct_call_prelude_access_size(insn),
                    "is_write": mnemonic.startswith("STR"),
                })
                if len(accesses) >= max(0, int(max_accesses)):
                    return accesses
        return accesses

    @staticmethod
    def _snapshot_memory_contains(snapshot_entry: PrefixReplaySnapshot, address: int, size: int = 1) -> bool:
        snapshot = getattr(snapshot_entry, "snapshot", None)
        if snapshot is None:
            return False
        address = int(address) & 0xFFFFFFFF
        size = max(1, int(size))
        memory_regions = getattr(snapshot, "memory_regions", None) or {}
        try:
            region_items = list(memory_regions.items())
        except Exception:
            region_items = []
        if not region_items:
            try:
                region_items = [((int(snapshot.memory_base), int(snapshot.memory_size)), bytes(snapshot.memory_data))]
            except Exception:
                region_items = []
        for key, data in region_items:
            try:
                start, region_size = key
                start = int(start)
                region_size = int(region_size)
            except Exception:
                continue
            end = start + region_size
            if start <= address and address + size <= end:
                return True
        return False

    @staticmethod
    def _snapshot_effective_memory_address(
        snapshot_entry: PrefixReplaySnapshot,
        operand: object,
        insn_addr: int,
    ) -> Tuple[Optional[int], Optional[str], str]:
        """
        Resolve a simple ``[reg, #imm]`` memory operand from snapshot registers.

        This is intentionally conservative: register-indexed operands are left
        unknown so replay still decides concretely instead of the ranker
        inventing an alias.
        """
        text = str(operand or "")
        match = re.search(r"\[\s*([^\],!\s]+)\s*(?:,\s*([^\]]+))?\]", text)
        if not match:
            return None, None, "not_memory_operand"
        base_name = match.group(1).strip().lower()
        if base_name not in {f"r{i}" for i in range(16)} | {"sp", "lr", "pc"}:
            return None, base_name, "unsupported_base_register"
        snapshot = getattr(snapshot_entry, "snapshot", None)
        registers = {
            str(key).lower(): int(value) & 0xFFFFFFFF
            for key, value in (getattr(snapshot, "registers", {}) or {}).items()
            if value is not None
        }
        register_aliases = {
            "r13": "sp",
            "r14": "lr",
            "r15": "pc",
        }
        canonical_base = register_aliases.get(base_name, base_name)
        if canonical_base == "pc":
            base = (int(insn_addr) + 4) & 0xFFFFFFFF
        elif canonical_base in registers:
            base = int(registers[canonical_base]) & 0xFFFFFFFF
        elif base_name in registers:
            base = int(registers[base_name]) & 0xFFFFFFFF
        else:
            return None, canonical_base, "missing_base_register"

        offset_text = (match.group(2) or "").strip()
        if not offset_text:
            return base, canonical_base, "ok"
        # Only simple immediate offsets are ranked.  Forms like
        # ``[r0, r1, lsl #2]`` remain unknown and are explored by Unicorn.
        first_offset = offset_text.split(",", 1)[0].strip().replace("#", "").replace(" ", "")
        if not first_offset:
            return base, canonical_base, "ok"
        if not re.fullmatch(r"[+-]?(?:0x[0-9a-fA-F]+|[0-9]+)", first_offset):
            return None, canonical_base, "non_immediate_offset"
        try:
            offset = int(first_offset, 0)
        except Exception:
            return None, canonical_base, "offset_parse_failed"
        return (base + offset) & 0xFFFFFFFF, canonical_base, "ok"

    def _snapshot_data_address_class(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        address: int,
        size: int,
        *,
        base_register: Optional[str],
        is_write: bool,
    ) -> str:
        address = int(address) & 0xFFFFFFFF
        size = max(1, int(size))
        if base_register == "pc" and not is_write:
            return "pc_literal"
        if address < 0x1000:
            return "null_or_low"
        if address >= 0xF0000000:
            return "wrap_or_system_high"
        if 0x40000000 <= address < 0x60000000 or 0xE0000000 <= address < 0xE0100000:
            return "mmio"
        if self.prepared.resolve_basic_block(address & ~1) is not None or (address & ~1) in self.prepared.instruction_lookup:
            return "code_pointer_write" if is_write else "code_or_rodata"
        if self._snapshot_memory_contains(snapshot_entry, address, size):
            return "saved_memory"
        if 0x10000000 <= address < 0x40000000:
            return "materializable_ram"
        return "unknown_external"

    def _direct_call_snapshot_prelude_stats(
        self,
        pred_bb: int,
        branch_pc: int,
        snapshot_entry: PrefixReplaySnapshot,
        *,
        max_records: int = 6,
    ) -> Dict[str, object]:
        stats: Dict[str, object] = {
            "checked": 0,
            "hard_invalid": 0,
            "soft_invalid": 0,
            "saved_memory": 0,
            "materializable_ram": 0,
            "pc_literal": 0,
            "mmio": 0,
            "unknown": 0,
            "records": [],
        }
        for access in self._direct_call_prelude_memory_accesses(pred_bb, branch_pc):
            stats["checked"] = int(stats.get("checked", 0) or 0) + 1
            effective, base_reg, reason = self._snapshot_effective_memory_address(
                snapshot_entry,
                access.get("operand"),
                int(access.get("pc", pred_bb) or pred_bb),
            )
            if effective is None:
                stats["unknown"] = int(stats.get("unknown", 0) or 0) + 1
                address_class = str(reason)
            else:
                address_class = self._snapshot_data_address_class(
                    snapshot_entry,
                    int(effective),
                    int(access.get("size", 4) or 4),
                    base_register=base_reg,
                    is_write=bool(access.get("is_write")),
                )
                if address_class in {"null_or_low", "wrap_or_system_high", "code_pointer_write"}:
                    stats["hard_invalid"] = int(stats.get("hard_invalid", 0) or 0) + 1
                elif address_class in {"unknown_external"}:
                    stats["soft_invalid"] = int(stats.get("soft_invalid", 0) or 0) + 1
                elif address_class == "saved_memory":
                    stats["saved_memory"] = int(stats.get("saved_memory", 0) or 0) + 1
                elif address_class == "materializable_ram":
                    stats["materializable_ram"] = int(stats.get("materializable_ram", 0) or 0) + 1
                elif address_class == "pc_literal":
                    stats["pc_literal"] = int(stats.get("pc_literal", 0) or 0) + 1
                elif address_class == "mmio":
                    stats["mmio"] = int(stats.get("mmio", 0) or 0) + 1
            records = stats.get("records")
            if isinstance(records, list) and len(records) < max(0, int(max_records)):
                records.append({
                    "pc": f"0x{int(access.get('pc', pred_bb) or pred_bb) & 0xFFFFFFFF:08x}",
                    "operand": str(access.get("operand") or ""),
                    "address": f"0x{int(effective) & 0xFFFFFFFF:08x}" if effective is not None else None,
                    "base_register": base_reg,
                    "class": address_class,
                })
        return stats

    def _direct_call_snapshot_prelude_sort_key(
        self,
        pred_bb: int,
        branch_pc: int,
        snapshot_entry: PrefixReplaySnapshot,
    ) -> Tuple[int, int, int, int, int, int, int, int]:
        stats = self._direct_call_snapshot_prelude_stats(pred_bb, branch_pc, snapshot_entry, max_records=0)
        snapshot = getattr(snapshot_entry, "snapshot", None)
        return (
            -int(stats.get("hard_invalid", 0) or 0),
            -int(stats.get("soft_invalid", 0) or 0),
            int(stats.get("saved_memory", 0) or 0),
            int(stats.get("materializable_ram", 0) or 0),
            int(stats.get("pc_literal", 0) or 0),
            -int(stats.get("unknown", 0) or 0),
            len(tuple(getattr(snapshot_entry, "source_path_signature", tuple()) or tuple())),
            int(getattr(snapshot, "capture_order", getattr(snapshot, "order", 0)) or 0),
        )

    def _rank_direct_call_snapshot_entries(
        self,
        pred_bb: int,
        branch_pc: int,
        snapshot_entries: Iterable[PrefixReplaySnapshot],
    ) -> List[PrefixReplaySnapshot]:
        entries = list(snapshot_entries or [])
        if len(entries) <= 1:
            return entries
        entries.sort(
            key=lambda entry: self._direct_call_snapshot_prelude_sort_key(pred_bb, branch_pc, entry),
            reverse=True,
        )
        return entries

    @staticmethod
    def _memory_operand_base_register(operand: object) -> Optional[str]:
        match = re.search(r"\[\s*([^\],!\s]+)", str(operand or "").lower())
        if not match:
            return None
        base = match.group(1).strip().lower()
        if base in {"sb", "sl", "fp", "ip"}:
            return {"sb": "r9", "sl": "r10", "fp": "r11", "ip": "r12"}[base]
        if re.fullmatch(r"r(?:[0-9]|1[0-2])|sp|lr|pc", base):
            return base
        return None

    @staticmethod
    def _memory_operand_registers(operand: object) -> List[str]:
        regs = []
        for token in re.findall(r"\b(?:r(?:[0-9]|1[0-2])|sp|lr|pc|sb|sl|fp|ip)\b", str(operand or "").lower()):
            reg = {"sb": "r9", "sl": "r10", "fp": "r11", "ip": "r12"}.get(token, token)
            if reg not in regs:
                regs.append(reg)
        return regs

    def _replay_pointer_value_is_valid(
        self,
        emulator: IntelligentEmulator,
        value: int,
        *,
        min_size: int = 1,
    ) -> bool:
        value = int(value) & 0xFFFFFFFF
        if value < 0x1000 or value >= 0xF0000000:
            return False
        try:
            if emulator._is_mmio_address(value):
                return False
        except Exception:
            pass
        try:
            if emulator._is_executable_address(value & ~1):
                return False
        except Exception:
            pass
        try:
            if emulator._is_memory_mapped(value, max(1, int(min_size))):
                return True
        except Exception:
            pass
        return 0x10000000 <= value < 0x40000000

    def _allocate_replay_pointer_object(
        self,
        emulator: IntelligentEmulator,
        *,
        min_size: int = 0x80,
    ) -> Optional[int]:
        try:
            ptr = int(emulator._model_heap_alloc(max(1, int(min_size)), zero=True, with_chunk_header=True)) & 0xFFFFFFFF
        except Exception:
            ptr = 0
        if ptr == 0:
            return None
        return ptr

    def _repair_replay_pointer_register(
        self,
        emulator: IntelligentEmulator,
        reg_name: str,
        *,
        reason: str,
        pc: int,
        operand: object = "",
        min_size: int = 0x80,
    ) -> Optional[Dict[str, object]]:
        reg_name = str(reg_name or "").lower()
        if reg_name in {"", "sp", "lr", "pc"}:
            return None
        reg_id = getattr(emulator, "_arm_reg_id", lambda _name: None)(reg_name)
        if reg_id is None:
            return None
        try:
            old_value = int(emulator.uc.reg_read(reg_id)) & 0xFFFFFFFF
        except Exception:
            return None
        if self._replay_pointer_value_is_valid(emulator, old_value, min_size=1):
            return None
        new_value = self._allocate_replay_pointer_object(emulator, min_size=min_size)
        if new_value is None:
            return None
        try:
            emulator.uc.reg_write(reg_id, int(new_value) & 0xFFFFFFFF)
        except Exception:
            return None
        return {
            "pc": f"0x{int(pc) & 0xFFFFFFFF:08x}",
            "register": reg_name,
            "old_value": f"0x{old_value:08x}",
            "new_value": f"0x{int(new_value) & 0xFFFFFFFF:08x}",
            "reason": str(reason),
            "operand": str(operand or ""),
        }

    def _direct_call_callee_argument_pointer_uses(
        self,
        target_bb: Optional[int],
        *,
        max_instructions: int = 48,
        max_bbs: int = 8,
    ) -> List[Dict[str, object]]:
        if target_bb is None:
            return []
        target_bb = int(target_bb) & ~1
        function_entry = self._function_entry_for_addr(target_bb) or target_bb
        function_name = self._function_name_for_addr(function_entry)
        function_starts = sorted(int(addr) for addr in self._function_starts_by_name().values())
        next_function = None
        for addr in function_starts:
            if addr > function_entry:
                next_function = int(addr)
                break

        queue = deque([target_bb])
        seen_bbs: Set[int] = set()
        aliases: Dict[str, str] = {f"r{i}": f"r{i}" for i in range(4)}
        uses: List[Dict[str, object]] = []
        inspected = 0

        while queue and len(seen_bbs) < max(1, int(max_bbs)) and inspected < max(1, int(max_instructions)):
            bb = int(queue.popleft()) & ~1
            if bb in seen_bbs:
                continue
            if next_function is not None and bb >= next_function:
                continue
            if self._function_entry_for_addr(bb) not in {function_entry, None}:
                continue
            instructions = self.prepared.static_bbs.get(bb, [])
            if not instructions:
                continue
            seen_bbs.add(bb)
            for insn in instructions:
                if inspected >= max(1, int(max_instructions)):
                    break
                inspected += 1
                mnemonic = _normalize_mnemonic(insn.get("mnemonic", ""))
                operands = self._split_operands(str(insn.get("operands", "")))
                if not operands:
                    continue
                if mnemonic in {"BL", "BLX"}:
                    continue

                if mnemonic.startswith("LDR") or mnemonic.startswith("STR"):
                    memory_operands = [operand for operand in operands if "[" in str(operand) and "]" in str(operand)]
                    for operand in memory_operands:
                        base = self._memory_operand_base_register(operand)
                        source = aliases.get(base or "")
                        if source in {"r0", "r1", "r2", "r3"}:
                            uses.append({
                                "pc": int(insn.get("address", bb) or bb) & ~1,
                                "register": source,
                                "base_register": base,
                                "operand": str(operand),
                                "mnemonic": mnemonic,
                                "function": function_name,
                            })
                    if operands:
                        dest = self._memory_operand_base_register(operands[0])
                        if dest in aliases and mnemonic.startswith("LDR"):
                            aliases.pop(dest, None)
                    continue

                if mnemonic in {"CMP", "CMN", "TST", "TEQ", "CBZ", "CBNZ", "IT"} or mnemonic.startswith("B"):
                    continue
                dest = self._reg_name(operands[0])
                if dest is None:
                    continue
                if mnemonic in {"MOV", "MOVS", "ADD", "ADDS", "SUB", "SUBS"} and len(operands) >= 2:
                    source_regs = self._memory_operand_registers(",".join(operands[1:]))
                    source_aliases = [aliases[reg] for reg in source_regs if reg in aliases]
                    if len(set(source_aliases)) == 1:
                        aliases[dest] = source_aliases[0]
                    else:
                        aliases.pop(dest, None)
                else:
                    aliases.pop(dest, None)

            for successor in sorted(self.prepared.static_successors.get(bb, set())):
                successor = int(successor) & ~1
                if successor in seen_bbs:
                    continue
                if next_function is not None and successor >= next_function:
                    continue
                if self._function_entry_for_addr(successor) not in {function_entry, None}:
                    continue
                queue.append(successor)

        deduped: List[Dict[str, object]] = []
        seen = set()
        for use in uses:
            key = (int(use.get("pc", 0) or 0), str(use.get("register") or ""), str(use.get("operand") or ""))
            if key in seen:
                continue
            seen.add(key)
            deduped.append(use)
        return deduped

    def _materialize_direct_call_callee_pointer_arguments(
        self,
        emulator: IntelligentEmulator,
        pred_bb: int,
        branch_pc: int,
        *,
        max_records: int = 16,
    ) -> Dict[str, object]:
        stats: Dict[str, object] = {
            "checked": 0,
            "repairs": 0,
            "skipped_valid": 0,
            "skipped": 0,
            "records": [],
        }
        insn = self.prepared.branch_instruction_by_bb.get(int(pred_bb), {})
        target_bb, target_symbol = self._direct_call_target_symbol(insn)
        if target_bb is None:
            return stats
        records = stats.get("records")
        repaired_regs: Set[str] = set()
        for use in self._direct_call_callee_argument_pointer_uses(target_bb):
            reg_name = str(use.get("register") or "")
            if reg_name in repaired_regs:
                continue
            stats["checked"] = int(stats.get("checked", 0) or 0) + 1
            reg_id = getattr(emulator, "_arm_reg_id", lambda _name: None)(reg_name)
            if reg_id is None:
                stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                continue
            try:
                current = int(emulator.uc.reg_read(reg_id)) & 0xFFFFFFFF
            except Exception:
                stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                continue
            if self._replay_pointer_value_is_valid(emulator, current, min_size=1):
                stats["skipped_valid"] = int(stats.get("skipped_valid", 0) or 0) + 1
                continue
            record = self._repair_replay_pointer_register(
                emulator,
                reg_name,
                reason=f"callee_early_pointer_use:{target_symbol or hex(int(target_bb))}",
                pc=int(use.get("pc", branch_pc) or branch_pc),
                operand=use.get("operand", ""),
            )
            if record is None:
                stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                continue
            repaired_regs.add(reg_name)
            stats["repairs"] = int(stats.get("repairs", 0) or 0) + 1
            record["callsite"] = f"0x{int(branch_pc) & 0xFFFFFFFF:08x}"
            record["target"] = f"0x{int(target_bb) & 0xFFFFFFFF:08x}"
            record["target_symbol"] = target_symbol or None
            record["base_register"] = use.get("base_register")
            if isinstance(records, list) and len(records) < max(0, int(max_records)):
                records.append(record)
        return stats

    def _materialize_direct_call_prelude_memory(
        self,
        emulator: IntelligentEmulator,
        pred_bb: int,
        branch_pc: int,
        *,
        max_records: int = 16,
    ) -> Dict[str, object]:
        """
        Pre-map simple data operands used before a direct-call instruction.

        Direct-call snapshots are captured at the static BB entry.  For BBs
        like allocator/free continuations, a few in-BB metadata loads can touch
        heap or external-input pages that were not declared by the ELF memory
        map.  Mapping those data holes lets Unicorn execute naturally to the
        reached callsite; skipped callees are still never credited as coverage.
        Fetches/code targets and MMIO are deliberately excluded.
        """
        stats: Dict[str, object] = {
            "checked": 0,
            "mapped": 0,
            "zero_filled": 0,
            "already_mapped": 0,
            "pointer_repairs": 0,
            "skipped": 0,
            "records": [],
        }
        instructions = self.prepared.static_bbs.get(int(pred_bb), [])
        if not instructions:
            return stats

        def address_allowed(address: int, size: int) -> bool:
            address = int(address) & 0xFFFFFFFF
            if size <= 0:
                return False
            # Do not mask null dereferences, wraparound pointers, code fetches,
            # or MMIO.  Those are different root causes from missing RAM/heap.
            if address < 0x1000 or address >= 0xF0000000:
                return False
            try:
                if emulator._is_mmio_address(address):
                    return False
            except Exception:
                pass
            try:
                if emulator._is_executable_address(address & ~1):
                    return False
            except Exception:
                pass
            if 0x10000000 <= address < 0x40000000:
                return True
            # Keep non-MCU external windows opt-in by prior observation; this
            # avoids turning arbitrary bad pointers into valid memory.
            try:
                observed = getattr(emulator, "external_memory_input_addresses", set()) or set()
                return any((int(item) & 0xFFFFF000) == (address & 0xFFFFF000) for item in observed)
            except Exception:
                return False

        def remember(record: Dict[str, object]) -> None:
            records = stats.get("records")
            if isinstance(records, list) and len(records) < max(0, max_records):
                records.append(record)

        for insn in instructions:
            try:
                insn_addr = int(insn.get("address", pred_bb) or pred_bb) & ~1
            except Exception:
                continue
            if insn_addr >= (int(branch_pc) & ~1):
                break
            mnemonic = _normalize_mnemonic(insn.get("mnemonic", ""))
            if not (
                mnemonic.startswith("LDR")
                or mnemonic.startswith("STR")
                or mnemonic in {"PUSH", "POP", "STM", "STMIA", "LDM", "LDMIA"}
            ):
                continue
            try:
                operands = emulator._split_operands(insn.get("operands", ""))
            except Exception:
                operands = []
            memory_operands = [operand for operand in operands if "[" in str(operand) and "]" in str(operand)]
            if not memory_operands:
                continue
            try:
                access_size = max(1, int(emulator._load_size_for_instruction(insn)))
            except Exception:
                access_size = self._direct_call_prelude_access_size(insn)
            for operand in memory_operands:
                stats["checked"] = int(stats.get("checked", 0) or 0) + 1
                try:
                    effective = emulator._effective_address_for_load_operand(
                        emulator.uc,
                        str(operand),
                        insn_addr,
                    )
                except Exception:
                    effective = None
                if effective is not None and not address_allowed(int(effective) & 0xFFFFFFFF, access_size):
                    base_reg = self._memory_operand_base_register(operand)
                    if (
                        mnemonic.startswith("LDR")
                        and "!" not in str(operand)
                        and base_reg in {"r0", "r1", "r2", "r3"}
                    ):
                        repair_record = self._repair_replay_pointer_register(
                            emulator,
                            str(base_reg),
                            reason="direct_call_prelude_invalid_pointer",
                            pc=insn_addr,
                            operand=operand,
                        )
                        if repair_record is not None:
                            stats["pointer_repairs"] = int(stats.get("pointer_repairs", 0) or 0) + 1
                            remember(repair_record)
                            try:
                                effective = emulator._effective_address_for_load_operand(
                                    emulator.uc,
                                    str(operand),
                                    insn_addr,
                                )
                            except Exception:
                                effective = None
                if effective is None:
                    stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                    continue
                effective = int(effective) & 0xFFFFFFFF
                if not address_allowed(effective, access_size):
                    stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                    remember({
                        "pc": f"0x{insn_addr:08x}",
                        "address": f"0x{effective:08x}",
                        "size": int(access_size),
                        "reason": "address_not_allowed",
                    })
                    continue
                try:
                    if emulator._is_memory_mapped(effective, access_size):
                        stats["already_mapped"] = int(stats.get("already_mapped", 0) or 0) + 1
                        continue
                except Exception:
                    pass
                try:
                    if not emulator._ensure_memory_mapped(effective, access_size):
                        stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                        remember({
                            "pc": f"0x{insn_addr:08x}",
                            "address": f"0x{effective:08x}",
                            "size": int(access_size),
                            "reason": "map_failed",
                        })
                        continue
                    stats["mapped"] = int(stats.get("mapped", 0) or 0) + 1
                    if mnemonic.startswith("LDR"):
                        emulator.uc.mem_write(effective, b"\x00" * access_size)
                        stats["zero_filled"] = int(stats.get("zero_filled", 0) or 0) + 1
                    remember({
                        "pc": f"0x{insn_addr:08x}",
                        "address": f"0x{effective:08x}",
                        "size": int(access_size),
                        "reason": "mapped_zero" if mnemonic.startswith("LDR") else "mapped_write_target",
                    })
                except Exception as exc:
                    stats["skipped"] = int(stats.get("skipped", 0) or 0) + 1
                    remember({
                        "pc": f"0x{insn_addr:08x}",
                        "address": f"0x{effective:08x}",
                        "size": int(access_size),
                        "reason": f"exception:{exc}",
                    })
        return stats

    @staticmethod
    def _direct_call_summary_default_return_value(symbol: object, registers: Dict[str, int]) -> int:
        name = str(symbol or "").strip().lower()

        def reg(name_: str) -> int:
            try:
                return int(registers.get(name_, 0) or 0) & 0xFFFFFFFF
            except Exception:
                return 0

        if name in {
            "__malloc_lock",
            "__malloc_unlock",
            "__retarget_lock_acquire_recursive",
            "__retarget_lock_release_recursive",
            "__retarget_lock_init_recursive",
            "__sinit",
            "__sinit_lock_acquire",
            "__sinit_lock_release",
            "_init",
            "_read_r",
            "_write_r",
            "memcmp",
            "memchr",
            "strcmp",
            "strncmp",
            "strlen",
        }:
            return 0
        if name in {"iprintf", "putchar", "puts", "_puts_r"}:
            return 1
        if name in {"memcpy", "memmove", "memset"}:
            return reg("r0")
        if _is_status_return_buffered_read_symbol(name):
            return 0
        if _is_buffered_input_summary_symbol(name):
            if name == "_read_r" or name == "__sread":
                size = reg("r3")
            elif name in {"read", "_read"}:
                size = reg("r2")
            else:
                size = reg("r2")
            return max(1, min(64, int(size or 1))) & 0xFFFFFFFF
        if (
            name.startswith("auto_init")
            or name.startswith("board_init")
            or name.startswith("periph_init")
            or name.startswith("stdio_init")
            or name.startswith("uart_init")
            or name.startswith("timer_init")
            or name.startswith("gpio_init")
            or name.startswith("random_init")
        ):
            return 0
        if _is_safe_io_summary_symbol(name):
            return 0
        if _is_status_return_buffered_read_symbol(name):
            return 0
        if _is_blocking_summary_symbol(name):
            return 0
        if _is_time_summary_symbol(name):
            return max(1, reg("r0"))
        return reg("r0")

    @staticmethod
    def _direct_call_summary_return_variants(
        symbol: object,
        default_value: Optional[int],
        registers: Dict[str, int],
    ) -> List[Tuple[int, str]]:
        name = str(symbol or "").strip().lower()

        def reg(name_: str) -> int:
            try:
                return int(registers.get(name_, 0) or 0) & 0xFFFFFFFF
            except Exception:
                return 0

        values: List[Tuple[int, str]] = []

        def add(value: int, reason: str) -> None:
            value = int(value) & 0xFFFFFFFF
            if value not in {existing for existing, _reason in values}:
                values.append((value, reason))

        if default_value is not None:
            add(int(default_value), "default")

        if _is_status_return_buffered_read_symbol(name):
            payload_values: List[int] = []

            def add_payload(value: int) -> None:
                value = int(value) & 0xFF
                if value not in payload_values:
                    payload_values.append(value)

            # Use common register conventions to prioritize likely identity and
            # ready-status bytes before broad generic payloads.
            memory_register = reg("r2") & 0xFF
            if memory_register == 0x75:
                for value in (0x71, 0x70, 0x73, 0x68):
                    add_payload(value)
            elif memory_register == 0x00:
                for value in (0x48, 0x68, 0x71):
                    add_payload(value)
            elif memory_register in {0x02, 0x03, 0x3A}:
                for value in (0x01, 0x02, 0x08, 0x10):
                    add_payload(value)
            for value in (0x00, 0x01, 0x02, 0x08, 0x10, 0x48, 0x68, 0x70, 0x71, 0x73, 0x7F, 0x80, 0xFF):
                add_payload(value)
            for payload in payload_values:
                item = (0, f"buffer_payload_0x{payload:02x}")
                if item not in values:
                    values.append(item)
            add(1, "status_error_variant")
            return values

        if _is_input_state_summary_symbol(name):
            for value in (
                0,
                1,
                2,
                4,
                7,
                8,
                16,
                0x7F,
                0x80,
                0xFF,
                # Common one-byte peripheral IDs / ready-status values seen in
                # sensor-heavy MCU firmware.  This is still generic value
                # exploration; skipped callees are not credited as coverage.
                0x48,
                0x68,
                0x70,
                0x71,
                0x73,
                0xE5,
                0x100,
                0x10001,
                0x10002,
                0x10004,
                0x20000,
                0x40000,
                0x80000,
                0x12340000,
                0x12345678,
                0x7FFF0000,
                0x80000000,
                0x7FFF,
                0x8000,
                0xFFFF,
                0x10000,
                0x7FFFFFFF,
                0x80000000,
                0xFFFFFFFF,
                reg("r0"),
                reg("r1"),
                reg("r2"),
            ):
                add(value, "input_state_variant")

        if _is_time_summary_symbol(name):
            base = int(default_value if default_value is not None else 0) & 0xFFFFFFFF
            register_hints = [reg("r0"), reg("r1"), reg("r2"), reg("r3")]
            for value in (
                base,
                max(1, base),
                base + 1,
                base + 10,
                base + 100,
                base + 1000,
                base + 10_000,
                base + 60_000,
                base + 1_000_000,
                1,
                10,
                100,
                1000,
                10_000,
                60_000,
                1_000_000,
                0x7FFFFFFF,
                0x80000000,
                0xFFFFFFFF,
                *register_hints,
            ):
                add(value, "time_progress_variant")

        if _is_buffered_input_summary_symbol(name):
            requested = reg("r3") if name in {"_read_r", "__sread"} else reg("r2")
            requested = max(1, min(64, int(requested or 1)))
            for sequence in (
                b"\xdd",
                b"\xff",
                b"\xbb",
                b"\xbb123\x00",
                b"\xffABC\n",
                b"G0 X0 Y0\n",
                b"G1 X1 Y1 E1\n",
                b"M105\n",
                b"M104 S200\n",
                b"<a/>",
                b"<root>1</root>",
                b"<?xml version=\"1.0\"?><root/>",
                b"\x00",
                b"\x01",
                b"\x70\x71\x73\x00",
            ):
                size = max(1, min(requested, len(sequence)))
                item = (size & 0xFFFFFFFF, f"payloadseq={sequence[:size].hex()}")
                if item not in values:
                    values.append(item)
            add(requested, "buffer_payload_pattern")

        if not values:
            add(0, "default")
        return values

    def _summary_output_buffer_candidates(
        self,
        symbol: object,
        registers: Dict[str, int],
        emulator: Optional[IntelligentEmulator] = None,
    ) -> List[Tuple[int, int, str]]:
        if not _is_buffered_input_summary_symbol(symbol):
            return []

        def reg(name_: str) -> int:
            try:
                return int(registers.get(name_, 0) or 0) & 0xFFFFFFFF
            except Exception:
                return 0

        def stack_word(offset: int) -> int:
            if emulator is None:
                return 0
            sp = reg("sp")
            if sp == 0:
                return 0
            try:
                data = bytes(emulator.uc.mem_read((sp + int(offset)) & 0xFFFFFFFF, 4))
                return int.from_bytes(data, "little") & 0xFFFFFFFF
            except Exception:
                return 0

        raw, normalized, _tokens = _summary_symbol_tokens(symbol)
        candidates: List[Tuple[int, int, str]] = []

        def add(address: int, size: int, reason: str) -> None:
            address = int(address) & 0xFFFFFFFF
            size = max(1, min(64, int(size)))
            if address == 0 or address < 0x20000000 or address >= 0x30000000:
                return
            item = (address, size, reason)
            if item not in candidates:
                candidates.append(item)

        if "memread" in normalized or "readmem" in normalized:
            add(reg("r2"), max(1, reg("r3") or 1), "mem_read_r2_len_r3")
            add(stack_word(0), max(1, stack_word(4) or 1), "mem_read_stack_pdata_size")
        if raw in {"read", "_read"}:
            add(reg("r1"), max(1, reg("r2") or 1), "posix_read_r1_len_r2")
        if raw in {"_read_r", "__sread"}:
            add(reg("r2"), max(1, reg("r3") or 1), "reent_read_r2_len_r3")
        if "directserial4read" in normalized or "mbed6stream4read" in normalized:
            add(reg("r1"), max(1, reg("r2") or 1), "mbed_read_r1_len_r2")
        if "mbed3i2c4read" in normalized or ("i2c4read" in normalized and "mbed" in normalized):
            add(reg("r2"), max(1, reg("r3") or 1), "mbed_i2c_read_r2_len_r3")
        if "readbyte" in normalized and not ("readbytes" in normalized):
            add(reg("r2"), 1, "readbyte_r2")
        if "readbytes" in normalized or "readdata" in normalized or "readraw" in normalized:
            add(reg("r2"), max(1, reg("r3") or reg("r1") or 1), "read_buffer_r2")
            add(reg("r1"), max(1, reg("r2") or reg("r3") or 1), "read_buffer_r1")
        if "readaccel" in normalized or "readgyro" in normalized or "readtemp" in normalized:
            add(reg("r0"), 8, "sensor_buffer_r0")
            add(reg("r2"), max(1, reg("r3") or 8), "sensor_buffer_r2")
        if "i2cread" in normalized or "uartread" in normalized or "serialread" in normalized:
            add(reg("r2"), max(1, reg("r3") or 1), "bus_read_r2")
            add(reg("r1"), max(1, reg("r2") or 1), "bus_read_r1")
        if "hali2c" in normalized and "read" in normalized:
            # HAL_I2C_Mem_Read passes pData/Size as stack args; Master_Receive
            # style APIs pass them in r2/r3.
            add(stack_word(0), max(1, stack_word(4) or 1), "hal_i2c_stack_pdata_size")
            add(reg("r2"), max(1, reg("r3") or 1), "hal_i2c_r2_r3_pdata_size")
        if ("haluart" in normalized or "halspi" in normalized) and "receive" in normalized:
            add(reg("r1"), max(1, reg("r2") or 1), "hal_bus_r1_r2_pdata_size")
        return candidates

    @staticmethod
    def _summary_output_payload(
        *,
        address: int,
        size: int,
        return_value: int,
        variant_reason: str,
    ) -> bytes:
        size = max(1, min(64, int(size)))
        seed = int(return_value) & 0xFFFFFFFF
        explicit_payload_seed = False
        payload_sequence_match = re.search(
            r"payloadseq=([0-9a-fA-F]+)",
            str(variant_reason or ""),
        )
        if payload_sequence_match:
            try:
                sequence = bytes.fromhex(payload_sequence_match.group(1))
                if sequence:
                    if len(sequence) >= size:
                        return sequence[:size]
                    repeats = (size + len(sequence) - 1) // len(sequence)
                    return (sequence * repeats)[:size]
            except Exception:
                pass
        payload_match = re.search(
            r"payload[_:=](0x[0-9a-fA-F]+|[0-9]+)",
            str(variant_reason or ""),
        )
        if payload_match:
            parsed_seed = _parse_int_token(payload_match.group(1))
            if parsed_seed is not None:
                seed = int(parsed_seed) & 0xFF
                explicit_payload_seed = True
        if seed == 0 and not explicit_payload_seed:
            if "zero" in str(variant_reason):
                seed = 0
            else:
                seed = 0x5A
        return bytes(((seed + int(address) + index * 0x11) & 0xFF) for index in range(size))

    def _apply_summary_output_side_effects(
        self,
        emulator: IntelligentEmulator,
        symbol: object,
        registers: Dict[str, int],
        *,
        return_value: int,
        variant_reason: str,
    ) -> List[Dict[str, object]]:
        writes: List[Dict[str, object]] = []
        for address, size, reason in self._summary_output_buffer_candidates(symbol, registers, emulator):
            payload = self._summary_output_payload(
                address=address,
                size=size,
                return_value=return_value,
                variant_reason=variant_reason,
            )
            try:
                if hasattr(emulator, "_ensure_memory_mapped") and not emulator._ensure_memory_mapped(address, len(payload)):
                    continue
                emulator.uc.mem_write(address, payload)
                writes.append({
                    "address": f"0x{int(address):08x}",
                    "size": len(payload),
                    "reason": reason,
                    "preview": payload[:8].hex(),
                })
            except Exception:
                continue
        return writes

    def _direct_call_summary_return_value(
        self,
        symbol: object,
        emulator: IntelligentEmulator,
        registers: Dict[str, int],
    ) -> Tuple[Optional[int], str]:
        name = str(symbol or "").strip().lower()

        def reg(name_: str) -> int:
            try:
                return int(registers.get(name_, 0) or 0) & 0xFFFFFFFF
            except Exception:
                return 0

        def read_memory(address: int, size: int) -> Optional[bytes]:
            if size < 0:
                return None
            if size == 0:
                return b""
            try:
                return bytes(emulator.uc.mem_read(int(address) & 0xFFFFFFFF, int(size)))
            except Exception:
                return None

        def bounded_len(value: int, *, max_len: int = 65536) -> Optional[int]:
            try:
                value = int(value) & 0xFFFFFFFF
            except Exception:
                return None
            if value > max_len:
                return None
            return value

        allocator_summary = IntelligentEmulator._allocator_summary_for_symbol(name)
        if allocator_summary is not None:
            try:
                value = emulator._apply_allocator_summary(
                    emulator.uc,
                    {
                        "symbol": name,
                        **allocator_summary,
                    },
                )
                return int(value) & 0xFFFFFFFF, f"model_allocator:{allocator_summary.get('kind')}"
            except Exception as exc:
                return None, f"allocator_summary_failed:{exc}"

        if name == "memcmp":
            length = bounded_len(reg("r2"))
            if length is None:
                return None, "memcmp_length_too_large"
            left = read_memory(reg("r0"), length)
            right = read_memory(reg("r1"), length)
            if left is None or right is None:
                return None, "memcmp_memory_unreadable"
            for left_byte, right_byte in zip(left, right):
                if left_byte != right_byte:
                    return (int(left_byte) - int(right_byte)) & 0xFFFFFFFF, "computed_memcmp"
            return 0, "computed_memcmp"

        if name == "memchr":
            length = bounded_len(reg("r2"))
            if length is None:
                return None, "memchr_length_too_large"
            data = read_memory(reg("r0"), length)
            if data is None:
                return None, "memchr_memory_unreadable"
            needle = reg("r1") & 0xFF
            index = data.find(bytes([needle]))
            if index < 0:
                return 0, "computed_memchr"
            return (reg("r0") + index) & 0xFFFFFFFF, "computed_memchr"

        if name == "strlen":
            base = reg("r0")
            max_scan = 65536
            data = read_memory(base, max_scan)
            if data is None:
                return None, "strlen_memory_unreadable"
            index = data.find(b"\x00")
            if index < 0:
                return None, "strlen_unterminated"
            return index & 0xFFFFFFFF, "computed_strlen"

        if name in {"strcmp", "strncmp"}:
            max_scan = 65536
            if name == "strncmp":
                length = bounded_len(reg("r2"))
                if length is None:
                    return None, "strncmp_length_too_large"
                max_scan = length
                if max_scan == 0:
                    return 0, "computed_strncmp"
            left = read_memory(reg("r0"), max_scan)
            right = read_memory(reg("r1"), max_scan)
            if left is None or right is None:
                return None, f"{name}_memory_unreadable"
            for left_byte, right_byte in zip(left, right):
                if left_byte != right_byte:
                    return (int(left_byte) - int(right_byte)) & 0xFFFFFFFF, f"computed_{name}"
                if left_byte == 0:
                    return 0, f"computed_{name}"
            if name == "strncmp":
                return 0, "computed_strncmp"
            return None, "strcmp_unterminated"

        if _is_time_summary_symbol(name):
            soft_tick = int(getattr(getattr(emulator, "time_handler", None), "soft_tick", 0) or 0)
            return max(1, soft_tick) & 0xFFFFFFFF, "time_soft_tick_summary"

        return (
            self._direct_call_summary_default_return_value(symbol, registers),
            "default_summary",
        )

    def run_direct_call_summary_return_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        max_tasks: int = 64,
        max_instructions: int = 80000,
        replay_timeout: int = 1_000_000,
        no_new_bb_limit: int = 4096,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 64,
        variants_per_call: int = 2,
        low_yield_stop_tasks: int = 0,
        low_yield_min_tasks: int = 0,
        phase_name: str = "direct_call_summary_return",
    ) -> Set[int]:
        """
        Continue after already-reached direct calls using a callee summary return.

        The start state is still entry-derived: a reset/replay reached the call
        BB and captured CPU/memory state. This phase only skips callee execution
        and counts BBs executed after the call fallthrough, so skipped callee
        bodies are never credited as coverage.
        """
        start_time = time.time()
        target_bb_set = self.validate_coverage(target_bbs or set())
        phase_covered: Set[int] = set()
        tasks_run = 0
        tasks_with_new_bbs = 0
        tasks_with_target_bbs = 0
        target_bbs_discovered: Set[int] = set()
        candidate_rounds = 0
        candidate_count_total = 0
        last_candidate_count = 0
        restore_failed = 0
        invalid_snapshots = 0
        invalid_reasons: Counter[str] = Counter()
        callsite_not_reached = 0
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        stop_reasons: Counter[str] = Counter()
        summary_return_reasons: Counter[str] = Counter()
        summary_side_effect_writes = 0
        unsupported_summary_returns = 0
        unsafe_summary_return_fallthroughs = 0
        unproven_dynamic_code_replays = 0
        candidate_debug_records: List[Dict[str, object]] = []
        attempted: Set[Tuple[object, ...]] = set()
        probe_attempts = 0
        consecutive_low_yield_tasks = 0
        low_yield_stop_triggered = False
        child_execution_interventions: Counter[str] = Counter()
        child_execution_records: List[Dict[str, object]] = []

        def dispose_temp_emulator(
            emulator: Optional[IntelligentEmulator],
            temp_mmio: Optional[EnhancedMMIOHandler] = None,
            temp_tracer: Optional[RegisterTracer] = None,
            evidence_record: Optional[Dict[str, object]] = None,
            run_result: Optional[Dict[str, object]] = None,
        ) -> Optional[str]:
            return self._safe_dispose_temp_emulator(
                emulator,
                mmio_handler=temp_mmio,
                register_tracer=temp_tracer,
                quarantine=None,
                stage_name=self._temp_stage_for("direct_call_summary_return"),
                evidence_record=evidence_record,
                run_result=run_result,
            )

        def finish_child_record(
            record: Dict[str, object],
            emulator: Optional[IntelligentEmulator],
            temp_mmio: Optional[EnhancedMMIOHandler],
            temp_tracer: Optional[RegisterTracer],
            *,
            run_result: Optional[Dict[str, object]] = None,
        ) -> Optional[str]:
            """Bind teardown to the exact probe/task record it can invalidate."""
            child_execution_records.append(record)
            child_execution_interventions.update(
                record.get("actual_intervention_reasons", {}) or {}
            )
            cleanup_error = dispose_temp_emulator(
                emulator,
                temp_mmio,
                temp_tracer,
                evidence_record=record,
                run_result=run_result,
            )
            if cleanup_error:
                child_execution_interventions["replay_cleanup_exception"] += 1
            return cleanup_error

        def prepare_summary_return_task(
            emulator: IntelligentEmulator,
            direct_symbol: str,
            summary_return_value: int,
            variant_reason: str,
            fallthrough_bb: int,
            snapshot_entry,
            pred_bb: int,
        ) -> Dict[str, object]:
            """Prepare one summary suffix while keeping all failure outcomes typed."""
            try:
                replay_call_registers = emulator._get_registers()
                effective_summary_value = int(summary_return_value) & 0xFFFFFFFF
                effective_variant_reason = str(variant_reason)
                if IntelligentEmulator._allocator_summary_for_symbol(
                    str(direct_symbol or "")
                ) is not None:
                    replay_value, replay_reason = self._direct_call_summary_return_value(
                        direct_symbol,
                        emulator,
                        replay_call_registers,
                    )
                    if replay_value is None:
                        return {
                            "kind": "unsupported",
                            "reason": str(replay_reason),
                        }
                    effective_summary_value = int(replay_value) & 0xFFFFFFFF
                    effective_variant_reason = (
                        f"{variant_reason}:replay_{replay_reason}"
                    )
                side_effects = self._apply_summary_output_side_effects(
                    emulator,
                    direct_symbol,
                    replay_call_registers,
                    return_value=effective_summary_value,
                    variant_reason=effective_variant_reason,
                )
                if not self._is_safe_replay_pc(
                    emulator,
                    fallthrough_bb,
                    snapshot_entry.snapshot,
                ):
                    return {
                        "kind": "unsafe_fallthrough",
                        "effective_summary_value": effective_summary_value,
                        "effective_variant_reason": effective_variant_reason,
                        "side_effects": side_effects,
                    }
                emulator.uc.reg_write(UC_ARM_REG_R0, effective_summary_value)
                emulator.uc.reg_write(UC_ARM_REG_LR, int(fallthrough_bb) | 1)
                emulator.uc.reg_write(UC_ARM_REG_PC, int(fallthrough_bb) | 1)
                return {
                    "kind": "ready",
                    "replay_call_registers": replay_call_registers,
                    "effective_summary_value": effective_summary_value,
                    "effective_variant_reason": effective_variant_reason,
                    "side_effects": side_effects,
                    "pred_bb": int(pred_bb),
                }
            except Exception as exc:
                return {"kind": "exception", "error": exc}

        def budget_exhausted() -> bool:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                return True
            return max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks

        def low_yield_budget_exhausted() -> bool:
            return (
                low_yield_stop_tasks is not None
                and int(low_yield_stop_tasks) > 0
                and tasks_run >= max(0, int(low_yield_min_tasks))
                and consecutive_low_yield_tasks >= int(low_yield_stop_tasks)
            )

        while not budget_exhausted():
            if low_yield_budget_exhausted():
                low_yield_stop_triggered = True
                break
            candidates = self._direct_call_summary_return_candidates(
                coverage=self.global_coverage | phase_covered,
                target_bbs=target_bb_set if target_bb_set else None,
                max_targets=max_targets,
            )
            candidate_rounds += 1
            last_candidate_count = len(candidates)
            candidate_count_total += len(candidates)
            if not candidates:
                break
            tasks_before_round = tasks_run
            refreshed_after_progress = False
            for candidate in candidates:
                if budget_exhausted() or low_yield_budget_exhausted() or refreshed_after_progress:
                    break
                pred_bb = int(candidate["pred_bb"])
                fallthrough_bb = int(candidate["fallthrough"])
                insn = dict(candidate.get("call_insn", {}) or {})
                branch_pc = int(insn.get("address", pred_bb) or pred_bb)
                entries = _segment_rotate_sequence(
                    list(candidate.get("snapshot_entries") or []),
                    f"summary_return_snapshots:{pred_bb}",
                )[:max(1, variants_per_call)]
                for snapshot_entry in entries:
                    if budget_exhausted() or low_yield_budget_exhausted():
                        break
                    probe_attempts += 1
                    valid_snapshot, reason = self._validate_root_snapshot_entry(
                        snapshot_entry,
                        root_key=(pred_bb, 1),
                    )
                    if not valid_snapshot:
                        invalid_snapshots += 1
                        invalid_reasons[str(reason)] += 1
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-invalid-snapshot-{len(child_execution_records) + 1}"
                                ),
                                reason=f"invalid_snapshot:{reason}",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        reason,
                                    ),
                                },
                                execution_started=False,
                                execution_error=str(reason),
                                run_result={"execution_attempted": True},
                            )
                        )
                        child_execution_interventions["invalid_snapshot"] += 1
                        continue

                    try:
                        emulator = self._new_temp_emulator(
                            max_snapshots=max(3, self.max_snapshots),
                            llm_config_path=self._effective_llm_config_path(),
                            constraint_json_path=self.constraint_file,
                            branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                            stage_name=self._temp_stage_for("direct_call_summary_return_callsite_probe"),
                        )
                    except Exception as exc:
                        stop_reasons["emulator_create_exception"] += 1
                        logger.debug("summary-return callsite probe emulator创建失败: %s", exc)
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-create-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="emulator_create_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                },
                                execution_started=False,
                                execution_error=exc,
                            )
                        )
                        child_execution_interventions[
                            "emulator_create_exception"
                        ] += 1
                        continue
                    temp_mmio = None
                    temp_tracer = None
                    try:
                        self._configure_emulator_feedback(emulator)
                        emulator.enable_branch_snapshot = True
                        temp_mmio = EnhancedMMIOHandler(
                            emulator.uc,
                            self.constraint_file,
                            branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                        )
                        temp_tracer = self._new_temp_register_tracer(emulator)
                        restored = self._restore_branch_snapshot(
                            emulator,
                            snapshot_entry.snapshot,
                            lineage_source=snapshot_entry,
                        )
                    except Exception as exc:
                        failure_result = self._materialize_replay_failure_result(
                            "replay_setup_exception",
                            execution_started=False,
                            execution_error=exc,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'direct_call_summary_return')}-"
                            f"probe-setup-failure-{len(child_execution_records) + 1}"
                        )
                        stop_reasons["replay_setup_exception"] += 1
                        logger.debug("summary-return callsite probe setup失败: %s", exc)
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(
                                phase_name or "direct_call_summary_return"
                            ),
                            execution_id=failure_execution_id,
                            reason="replay_setup_exception",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_summary_return"
                                ),
                                "coverage_counted": False,
                                "probe_only": True,
                            },
                            execution_started=False,
                            execution_error=exc,
                            run_result=failure_result,
                        )
                        child_execution_interventions[
                            "replay_setup_exception"
                        ] += 1
                        finish_child_record(
                            failure_record,
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            run_result=failure_result,
                        )
                        continue
                    if not restored:
                        restore_failed += 1
                        stop_reasons["snapshot_restore_failed"] += 1
                        failure_result = self._materialize_replay_failure_result(
                            "snapshot_restore_failed",
                            execution_started=False,
                            execution_error="branch snapshot restore returned false",
                            restore_failed=True,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'direct_call_summary_return')}"
                            f"-probe-restore-failure-{len(child_execution_records) + 1}"
                        )
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "direct_call_summary_return"),
                            execution_id=failure_execution_id,
                            reason="snapshot_restore_failed",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_summary_return"
                                ),
                                "coverage_counted": False,
                                "probe_only": True,
                                **self._snapshot_restore_failure_metadata(
                                    snapshot_entry,
                                    "branch snapshot restore returned false",
                                ),
                            },
                            execution_started=False,
                            execution_error="branch snapshot restore returned false",
                            run_result=failure_result,
                        )
                        child_execution_interventions["snapshot_restore_failed"] += 1
                        finish_child_record(
                            failure_record,
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            run_result=failure_result,
                        )
                        continue
                    if not self._restore_replay_mmio_state(
                        emulator,
                        temp_mmio,
                        snapshot_entry.mmio_state,
                    ):
                        restore_failed += 1
                        stop_reasons["replay_mmio_state_restore_failed"] += 1
                        restore_error = self._replay_mmio_restore_failure_reason(
                            emulator
                        )
                        failure_result = self._materialize_replay_failure_result(
                            "replay_mmio_state_restore_failed",
                            execution_started=False,
                            execution_error=restore_error,
                            restore_failed=True,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'direct_call_summary_return')}"
                            f"-probe-mmio-restore-failure-{len(child_execution_records) + 1}"
                        )
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "direct_call_summary_return"),
                            execution_id=failure_execution_id,
                            reason="replay_mmio_state_restore_failed",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_summary_return"
                                ),
                                "coverage_counted": False,
                                "probe_only": True,
                                **self._snapshot_restore_failure_metadata(
                                    snapshot_entry,
                                    restore_error,
                                ),
                            },
                            execution_started=False,
                            execution_error=restore_error,
                            run_result=failure_result,
                        )
                        child_execution_interventions[
                            "replay_mmio_state_restore_failed"
                        ] += 1
                        finish_child_record(
                            failure_record,
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            run_result=failure_result,
                        )
                        continue
                    try:
                        self._apply_scoped_branch_constraints(
                            temp_mmio,
                            self._scope_signature_from_snapshot_entry(snapshot_entry),
                            emulator=emulator,
                        )
                        prelude_memory_stats = self._materialize_direct_call_prelude_memory(
                            emulator,
                            pred_bb,
                            branch_pc,
                        )
                        pointer_arg_repair_stats = self._materialize_direct_call_callee_pointer_arguments(
                            emulator,
                            pred_bb,
                            branch_pc,
                        )
                    except Exception as exc:
                        failure_result = self._materialize_replay_failure_result(
                            "replay_preparation_exception",
                            execution_started=False,
                            execution_error=exc,
                        )
                        failure_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "direct_call_summary_return"),
                            execution_id=(
                                f"{str(phase_name or 'direct_call_summary_return')}-"
                                f"probe-preparation-failure-{len(child_execution_records) + 1}"
                            ),
                            reason="replay_preparation_exception",
                            metadata={
                                "entry_derivation": (
                                    "entry_derived_direct_call_summary_return"
                                ),
                                "coverage_counted": False,
                                "probe_only": True,
                                "pred_bb": int(pred_bb),
                            },
                            execution_started=False,
                            execution_error=exc,
                            run_result=failure_result,
                        )
                        stop_reasons["replay_preparation_exception"] += 1
                        child_execution_interventions[
                            "replay_preparation_exception"
                        ] += 1
                        finish_child_record(
                            failure_record,
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            run_result=failure_result,
                        )
                        continue

                    # ``_restore_branch_snapshot`` restores the primary
                    # handler's cumulative peripheral telemetry, and the
                    # preparation below may install the occurrence-scoped
                    # overlay.  The probe baseline must therefore be taken
                    # after all replay setup and immediately before the
                    # pre-call execution, otherwise prefix RX reads are
                    # reported as facts produced by this probe.
                    probe_execution_baseline = self._capture_direct_execution_baseline(
                        emulator,
                        f"{str(phase_name or 'direct_call_summary_return')}:probe",
                        mmio_handler=temp_mmio,
                    )
                    try:
                        with self.guided_modules(temp_mmio, temp_tracer):
                            pre_call_result = emulator.run(
                                entry_point=None,
                                max_instructions=max(1, len(self.prepared.static_bbs.get(int(pred_bb), [])) + 8),
                                timeout_seconds=0.25,
                                preserve_cpu_state=True,
                                stop_before_pc=branch_pc,
                            )
                    except Exception as exc:
                        pre_call_result = self._materialize_replay_failure_result(
                            "execution_exception",
                            execution_started=True,
                            execution_error=exc,
                        )
                    if bool(pre_call_result.get("execution_failed")) or bool(
                        pre_call_result.get("preflight_failed")
                    ):
                        failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-execution-failure-{len(child_execution_records) + 1}"
                                ),
                                reason=str(
                                    pre_call_result.get("stop_reason")
                                    or "pre_call_execution_failed"
                                ),
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=pre_call_result.get("execution_error"),
                                run_result=pre_call_result,
                        )
                        child_execution_records.append(failure_record)
                        child_execution_interventions["pre_call_execution_failed"] += 1
                        dispose_temp_emulator(
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            evidence_record=failure_record,
                            run_result=pre_call_result,
                        )
                        continue
                    try:
                        live_pc = int(emulator.uc.reg_read(UC_ARM_REG_PC)) & ~1
                    except Exception as exc:
                        callsite_not_reached += 1
                        failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-pc-read-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="callsite_pc_read_failed",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=exc,
                                run_result=pre_call_result,
                        )
                        child_execution_records.append(failure_record)
                        child_execution_interventions["callsite_pc_read_failed"] += 1
                        dispose_temp_emulator(
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            evidence_record=failure_record,
                            run_result=pre_call_result,
                        )
                        continue
                    if live_pc != branch_pc and str(pre_call_result.get("stop_reason") or "") != "stop_before_pc":
                        callsite_not_reached += 1
                        failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-callsite-not-reached-{len(child_execution_records) + 1}"
                                ),
                                reason="callsite_not_reached",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "callsite_pc": int(branch_pc),
                                    "observed_pc": int(live_pc),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=str(
                                    pre_call_result.get("stop_reason")
                                    or "callsite_not_reached"
                                ),
                                run_result=pre_call_result,
                        )
                        child_execution_records.append(failure_record)
                        child_execution_interventions["callsite_not_reached"] += 1
                        dispose_temp_emulator(
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            evidence_record=failure_record,
                            run_result=pre_call_result,
                        )
                        continue

                    try:
                        call_registers = emulator._get_registers()
                        summary_return_value, summary_return_reason = self._direct_call_summary_return_value(
                            candidate.get("direct_symbol", ""),
                            emulator,
                            call_registers,
                        )
                        if summary_return_value is None:
                            unsupported_summary_returns += 1
                            summary_return_reasons[str(summary_return_reason)] += 1
                            probe_failure = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-unsupported-summary-{len(child_execution_records) + 1}"
                                ),
                                reason="unsupported_summary_return",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "probe_only": True,
                                    "pred_bb": int(pred_bb),
                                    "summary_return_reason": str(summary_return_reason),
                                },
                                covered_bbs=(),
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=str(summary_return_reason),
                                run_result=pre_call_result,
                            )
                            child_execution_interventions[
                                "unsupported_summary_return"
                            ] += 1
                            finish_child_record(
                                probe_failure,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=pre_call_result,
                            )
                            continue
                        summary_variants = self._direct_call_summary_return_variants(
                            candidate.get("direct_symbol", ""),
                            summary_return_value,
                            call_registers,
                        )
                    except Exception as exc:
                        failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"probe-summary-value-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="summary_value_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=exc,
                                run_result=pre_call_result,
                        )
                        child_execution_records.append(failure_record)
                        child_execution_interventions["summary_value_exception"] += 1
                        dispose_temp_emulator(
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            evidence_record=failure_record,
                            run_result=pre_call_result,
                        )
                        continue

                    probe_record = self._direct_execution_evidence_record(
                        phase_name=str(phase_name or "direct_call_summary_return"),
                        emulator=emulator,
                        covered_bbs=(),
                        metadata={
                            "entry_derivation": (
                                "entry_derived_direct_call_summary_return"
                            ),
                            "coverage_counted": False,
                            "probe_only": True,
                            "pred_bb": int(pred_bb),
                            "callsite_pc": int(branch_pc),
                            "summary_return_supported": True,
                        },
                        stop_reason=str(
                            pre_call_result.get("stop_reason")
                            or "direct_call_summary_probe_completed"
                        ),
                        execution_started=bool(
                            pre_call_result.get("execution_started", False)
                        ),
                        execution_error=pre_call_result.get("execution_error"),
                        run_result=pre_call_result,
                        execution_baseline=probe_execution_baseline,
                        mmio_handler=temp_mmio,
                    )
                    finish_child_record(
                        probe_record,
                        emulator,
                        temp_mmio,
                        temp_tracer,
                        run_result=pre_call_result,
                    )

                    direct_symbol = candidate.get("direct_symbol", "")
                    summary_value_variants = _segment_rotate_sequence(
                        summary_variants,
                        f"summary_return_values:{pred_bb}:{direct_symbol}",
                    )
                    summary_value_limit = max(1, int(variants_per_call or 1))
                    if _is_time_summary_symbol(direct_symbol):
                        summary_value_limit = max(summary_value_limit, 8)
                    elif _is_buffered_input_summary_symbol(direct_symbol):
                        summary_value_limit = max(summary_value_limit, 8)
                    elif _is_input_state_summary_symbol(direct_symbol):
                        summary_value_limit = max(summary_value_limit, 6)
                    elif _is_low_value_summary_symbol(direct_symbol):
                        summary_value_limit = min(summary_value_limit, 2)
                    summary_value_variants = summary_value_variants[:summary_value_limit]

                    for summary_return_value, variant_reason in summary_value_variants:
                        if budget_exhausted() or low_yield_budget_exhausted():
                            break
                        attempt_key = (
                            int(pred_bb),
                            int(fallthrough_bb),
                            int(summary_return_value) & 0xFFFFFFFF,
                            str(variant_reason),
                            self._snapshot_entry_identity(snapshot_entry),
                        )
                        if attempt_key in attempted:
                            continue
                        attempted.add(attempt_key)

                        try:
                            emulator = self._new_temp_emulator(
                                max_snapshots=max(3, self.max_snapshots),
                                llm_config_path=self._effective_llm_config_path(),
                                constraint_json_path=self.constraint_file,
                                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                                stage_name=self._temp_stage_for("direct_call_summary_return_task"),
                            )
                        except Exception as exc:
                            stop_reasons["emulator_create_exception"] += 1
                            logger.debug("summary-return emulator创建失败: %s", exc)
                            child_execution_records.append(
                                self._execution_failure_evidence_record(
                                    phase_name=str(
                                        phase_name or "direct_call_summary_return"
                                    ),
                                    execution_id=(
                                        f"{str(phase_name or 'direct_call_summary_return')}-"
                                        f"task-create-failure-{len(child_execution_records) + 1}"
                                    ),
                                    reason="emulator_create_exception",
                                    metadata={
                                        "entry_derivation": (
                                            "entry_derived_direct_call_summary_return"
                                        ),
                                        "coverage_counted": True,
                                        "pred_bb": int(pred_bb),
                                    },
                                    execution_started=False,
                                    execution_error=exc,
                                )
                            )
                            child_execution_interventions[
                                "emulator_create_exception"
                            ] += 1
                            continue
                        temp_mmio = None
                        temp_tracer = None
                        try:
                            self._configure_emulator_feedback(emulator)
                            self._configure_replay_skip_function_returns(emulator, include_time=True)
                            emulator.enable_branch_snapshot = True
                            temp_mmio = EnhancedMMIOHandler(
                                emulator.uc,
                                self.constraint_file,
                                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                            )
                            temp_tracer = self._new_temp_register_tracer(emulator)
                            restored = self._restore_branch_snapshot(
                                emulator,
                                snapshot_entry.snapshot,
                                lineage_source=snapshot_entry,
                            )
                        except Exception as exc:
                            failure_result = self._materialize_replay_failure_result(
                                "replay_setup_exception",
                                execution_started=False,
                                execution_error=exc,
                            )
                            failure_execution_id = (
                                f"{str(phase_name or 'direct_call_summary_return')}-"
                                f"task-setup-failure-{len(child_execution_records) + 1}"
                            )
                            stop_reasons["replay_setup_exception"] += 1
                            logger.debug("summary-return replay setup失败: %s", exc)
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=failure_execution_id,
                                reason="replay_setup_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                                run_result=failure_result,
                            )
                            child_execution_interventions[
                                "replay_setup_exception"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=failure_result,
                            )
                            continue
                        if not restored:
                            restore_failed += 1
                            stop_reasons["snapshot_restore_failed"] += 1
                            failure_result = self._materialize_replay_failure_result(
                                "snapshot_restore_failed",
                                execution_started=False,
                                execution_error="branch snapshot restore returned false",
                                restore_failed=True,
                            )
                            failure_execution_id = (
                                f"{str(phase_name or 'direct_call_summary_return')}"
                                f"-task-restore-failure-{len(child_execution_records) + 1}"
                            )
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "direct_call_summary_return"),
                                execution_id=failure_execution_id,
                                reason="snapshot_restore_failed",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        "branch snapshot restore returned false",
                                    ),
                                },
                                execution_started=False,
                                execution_error="branch snapshot restore returned false",
                                run_result=failure_result,
                            )
                            child_execution_interventions[
                                "snapshot_restore_failed"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=failure_result,
                            )
                            continue
                        if not self._restore_replay_mmio_state(
                            emulator,
                            temp_mmio,
                            snapshot_entry.mmio_state,
                        ):
                            restore_failed += 1
                            stop_reasons["replay_mmio_state_restore_failed"] += 1
                            restore_error = self._replay_mmio_restore_failure_reason(
                                emulator
                            )
                            failure_result = self._materialize_replay_failure_result(
                                "replay_mmio_state_restore_failed",
                                execution_started=False,
                                execution_error=restore_error,
                                restore_failed=True,
                            )
                            failure_execution_id = (
                                f"{str(phase_name or 'direct_call_summary_return')}"
                                f"-task-mmio-restore-failure-{len(child_execution_records) + 1}"
                            )
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "direct_call_summary_return"),
                                execution_id=failure_execution_id,
                                reason="replay_mmio_state_restore_failed",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        restore_error,
                                    ),
                                },
                                execution_started=False,
                                execution_error=restore_error,
                                run_result=failure_result,
                            )
                            child_execution_interventions[
                                "replay_mmio_state_restore_failed"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=failure_result,
                            )
                            continue
                        try:
                            self._apply_scoped_branch_constraints(
                                temp_mmio,
                                self._scope_signature_from_snapshot_entry(snapshot_entry),
                                emulator=emulator,
                            )
                            replay_prelude_memory_stats = self._materialize_direct_call_prelude_memory(
                                emulator,
                                pred_bb,
                                branch_pc,
                            )
                            replay_pointer_arg_repair_stats = self._materialize_direct_call_callee_pointer_arguments(
                                emulator,
                                pred_bb,
                                branch_pc,
                            )
                        except Exception as exc:
                            failure_result = self._materialize_replay_failure_result(
                                "replay_preparation_exception",
                                execution_started=False,
                                execution_error=exc,
                            )
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "direct_call_summary_return"),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-preparation-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="replay_preparation_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                                run_result=failure_result,
                            )
                            stop_reasons["replay_preparation_exception"] += 1
                            child_execution_interventions[
                                "replay_preparation_exception"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=failure_result,
                            )
                            continue
                        try:
                            with self.guided_modules(temp_mmio, temp_tracer):
                                pre_call_result = emulator.run(
                                    entry_point=None,
                                    max_instructions=max(1, len(self.prepared.static_bbs.get(int(pred_bb), [])) + 8),
                                    timeout_seconds=0.25,
                                    preserve_cpu_state=True,
                                    stop_before_pc=branch_pc,
                                )
                        except Exception as exc:
                            pre_call_result = self._materialize_replay_failure_result(
                                "execution_exception",
                                execution_started=True,
                                execution_error=exc,
                            )
                        if bool(pre_call_result.get("execution_failed")) or bool(
                            pre_call_result.get("preflight_failed")
                        ):
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-pre-call-failure-{len(child_execution_records) + 1}"
                                ),
                                reason=str(
                                    pre_call_result.get("stop_reason")
                                    or "pre_call_execution_failed"
                                ),
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=pre_call_result.get("execution_error"),
                                run_result=pre_call_result,
                            )
                            child_execution_records.append(failure_record)
                            child_execution_interventions[
                                "pre_call_execution_failed"
                            ] += 1
                            dispose_temp_emulator(
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                evidence_record=failure_record,
                                run_result=pre_call_result,
                            )
                            continue
                        try:
                            live_pc = int(emulator.uc.reg_read(UC_ARM_REG_PC)) & ~1
                        except Exception as exc:
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-pc-read-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="callsite_pc_read_failed",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=exc,
                                run_result=pre_call_result,
                            )
                            child_execution_records.append(failure_record)
                            child_execution_interventions[
                                "callsite_pc_read_failed"
                            ] += 1
                            dispose_temp_emulator(
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                evidence_record=failure_record,
                                run_result=pre_call_result,
                            )
                            continue
                        if live_pc != branch_pc and str(pre_call_result.get("stop_reason") or "") != "stop_before_pc":
                            callsite_not_reached += 1
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-callsite-not-reached-{len(child_execution_records) + 1}"
                                ),
                                reason="callsite_not_reached",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "callsite_pc": int(branch_pc),
                                    "observed_pc": int(live_pc),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=str(
                                    pre_call_result.get("stop_reason")
                                    or "callsite_not_reached"
                                ),
                                run_result=pre_call_result,
                            )
                            child_execution_records.append(failure_record)
                            child_execution_interventions["callsite_not_reached"] += 1
                            dispose_temp_emulator(
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                evidence_record=failure_record,
                                run_result=pre_call_result,
                            )
                            continue

                        prepared_summary = prepare_summary_return_task(
                            emulator,
                            str(direct_symbol or ""),
                            int(summary_return_value),
                            str(variant_reason),
                            fallthrough_bb,
                            snapshot_entry,
                            pred_bb,
                        )
                        preparation_kind = str(prepared_summary.get("kind") or "")
                        if preparation_kind == "unsupported":
                            unsupported_summary_returns += 1
                            replay_reason = str(
                                prepared_summary.get("reason") or "unsupported"
                            )
                            summary_return_reasons[replay_reason] += 1
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-unsupported-summary-{len(child_execution_records) + 1}"
                                ),
                                reason="unsupported_summary_return",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                    "summary_return_reason": replay_reason,
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=replay_reason,
                                run_result=pre_call_result,
                            )
                            child_execution_interventions[
                                "unsupported_summary_return"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=pre_call_result,
                            )
                            continue
                        if preparation_kind == "unsafe_fallthrough":
                            unsafe_summary_return_fallthroughs += 1
                            summary_return_reasons["unsafe_fallthrough"] += 1
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-unsafe-fallthrough-{len(child_execution_records) + 1}"
                                ),
                                reason="unsafe_summary_return_fallthrough",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                    "fallthrough_bb": int(fallthrough_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error="unsafe summary-return fallthrough",
                                run_result=pre_call_result,
                            )
                            child_execution_interventions[
                                "unsafe_summary_return_fallthrough"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=pre_call_result,
                            )
                            continue
                        if preparation_kind != "ready":
                            preparation_error = prepared_summary.get("error") or (
                                "summary-return task preparation failed"
                            )
                            failure_record = self._execution_failure_evidence_record(
                                phase_name=str(
                                    phase_name or "direct_call_summary_return"
                                ),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}-"
                                    f"task-summary-preparation-failure-{len(child_execution_records) + 1}"
                                ),
                                reason="summary_return_preparation_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": False,
                                    "pred_bb": int(pred_bb),
                                },
                                execution_started=bool(
                                    pre_call_result.get("execution_started", False)
                                ),
                                execution_error=preparation_error,
                                run_result=pre_call_result,
                            )
                            child_execution_interventions[
                                "summary_return_preparation_exception"
                            ] += 1
                            finish_child_record(
                                failure_record,
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                run_result=pre_call_result,
                            )
                            continue

                        effective_summary_value = int(
                            prepared_summary["effective_summary_value"]
                        )
                        effective_variant_reason = str(
                            prepared_summary["effective_variant_reason"]
                        )
                        side_effects = list(
                            prepared_summary.get("side_effects", []) or []
                        )
                        summary_side_effect_writes += len(side_effects)
                        replay_call_registers = prepared_summary.get(
                            "replay_call_registers", {}
                        )
                        summary_return_reasons[
                            f"{summary_return_reason}:{effective_variant_reason}"
                        ] += 1

                        # ``prepare_summary_return_task`` is part of replay
                        # setup.  Establish the adapter baseline only after
                        # the restored prefix and summary side effects are in
                        # place, immediately before executing the suffix.
                        execution_baseline = self._capture_direct_execution_baseline(
                            emulator,
                            str(phase_name or "direct_call_summary_return"),
                            mmio_handler=temp_mmio,
                        )

                        known_before = self.global_coverage | phase_covered
                        previous_quiescence_limit = emulator.stop_after_no_new_bbs
                        emulator.stop_after_no_new_bbs = (
                            max(1, int(no_new_bb_limit))
                            if no_new_bb_limit and no_new_bb_limit > 0
                            else None
                        )
                        trace = SimpleNamespace(covered_bbs=set(), executed_bbs=[])
                        try:
                            with self.guided_modules(temp_mmio, temp_tracer), self.capture_execution_trace(emulator) as captured_trace:
                                trace = captured_trace
                                try:
                                    run_result = emulator.run(
                                        entry_point=None,
                                        max_instructions=max_instructions,
                                        timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                                        preserve_cpu_state=True,
                                    )
                                except Exception as exc:
                                    run_result = self._materialize_replay_failure_result(
                                        "execution_exception",
                                        execution_started=True,
                                        execution_error=exc,
                                    )
                        except Exception as exc:
                            run_result = self._materialize_replay_failure_result(
                                "execution_trace_scope_exception",
                                execution_started=True,
                                execution_error=exc,
                            )
                        finally:
                            emulator.stop_after_no_new_bbs = previous_quiescence_limit

                        execution_failed = bool(run_result.get("execution_failed")) or bool(
                            run_result.get("preflight_failed")
                        )
                        valid = (
                            set()
                            if execution_failed
                            else self.validate_coverage(trace.covered_bbs)
                        )
                        if execution_failed:
                            execution_record = self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "direct_call_summary_return"),
                                execution_id=(
                                    f"{str(phase_name or 'direct_call_summary_return')}"
                                    f"-task-{tasks_run + 1}"
                                ),
                                reason=str(
                                    run_result.get("stop_reason") or "execution_failed"
                                ),
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "pred_bb": int(pred_bb),
                                },
                                covered_bbs=(),
                                execution_started=bool(
                                    run_result.get("execution_started", False)
                                ),
                                execution_error=run_result.get("execution_error"),
                                run_result=run_result,
                            )
                        else:
                            execution_record = self._direct_execution_evidence_record(
                                phase_name=str(phase_name or "direct_call_summary_return"),
                                emulator=emulator,
                                covered_bbs=trace.covered_bbs,
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_direct_call_summary_return"
                                    ),
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "fallthrough_bb": int(fallthrough_bb),
                                },
                                stop_reason=str(
                                    run_result.get("stop_reason")
                                    or "direct_unicorn_execution_completed"
                                ),
                                execution_started=bool(
                                    run_result.get("execution_started", True)
                                ),
                                run_result=run_result,
                                execution_baseline=execution_baseline,
                                execution_id=str(
                                    run_result.get("execution_id")
                                    or f"{str(phase_name or 'direct_call_summary_return')}-task-{tasks_run + 1}"
                                ),
                                mmio_handler=temp_mmio,
                            )
                        child_execution_records.append(execution_record)

                        def safe_postprocess(operation: str, callback, default=None):
                            return self._safe_replay_postprocess(
                                operation,
                                callback,
                                evidence_record=execution_record,
                                run_result=run_result,
                                default=default,
                            )

                        child_execution_interventions.update(
                            execution_record.get("actual_intervention_reasons", {}) or {}
                        )
                        task_new_bbs = valid - known_before
                        task_new_targets = task_new_bbs & (target_bb_set or {fallthrough_bb})

                        tasks_run += 1
                        stop_reason = str(run_result.get("stop_reason") or "unknown")
                        stop_reasons[stop_reason] += 1
                        if stop_reason == "unproven_dynamic_code_target":
                            unproven_dynamic_code_replays += 1
                            summary_return_reasons["unproven_dynamic_code_target"] += 1
                            dispose_temp_emulator(
                                emulator,
                                temp_mmio,
                                temp_tracer,
                                execution_record,
                            )
                            if low_yield_budget_exhausted():
                                low_yield_stop_triggered = True
                                break
                            continue
                        if task_new_bbs:
                            tasks_with_new_bbs += 1
                        if task_new_targets:
                            tasks_with_target_bbs += 1
                            target_bbs_discovered.update(task_new_targets)
                        phase_covered.update(valid)
                        safe_postprocess(
                            "coverage_evidence",
                            lambda: self._record_coverage_evidence(EVIDENCE_E3, valid),
                        )
                        replay_events = safe_postprocess(
                            "branch_event_collection",
                            lambda: emulator.branch_snapshot_manager.get_ordered_events(),
                            default=[],
                        ) or []
                        replay_snapshots = safe_postprocess(
                            "replay_snapshot_collection",
                            lambda: self._ordered_replay_snapshots(emulator),
                            default=[],
                        ) or []
                        task_remembered_branch_events = safe_postprocess(
                            "branch_event_feedback",
                            lambda: self._remember_main_branch_events(
                                replay_events,
                                evidence_class=EVIDENCE_E3,
                            ),
                            default=0,
                        ) or 0
                        task_remembered_branch_root_snapshots = safe_postprocess(
                            "branch_snapshot_feedback",
                            lambda: self._remember_branch_root_snapshots(
                                replay_events,
                                replay_snapshots,
                                source_path_signature=getattr(snapshot_entry, "source_path_signature", tuple()) or tuple(),
                                evidence_class=EVIDENCE_E3,
                            ),
                            default=0,
                        ) or 0
                        task_dynamic_successor_edges = safe_postprocess(
                            "dynamic_successor_feedback",
                            lambda: self._record_dynamic_successors(replay_events),
                            default=0,
                        ) or 0
                        task_dynamic_successor_edges += safe_postprocess(
                            "runtime_successor_feedback",
                            lambda: self._record_emulator_runtime_successors(emulator),
                            default=0,
                        ) or 0
                        remembered_branch_events += task_remembered_branch_events
                        remembered_branch_root_snapshots += task_remembered_branch_root_snapshots
                        dynamic_successor_edges_added += task_dynamic_successor_edges
                        safe_postprocess(
                            "scheduler_feedback",
                            lambda: self._harvest_emulator_feedback(emulator),
                        )
                        safe_postprocess(
                            "register_tracer_merge",
                            lambda: self.register_tracer.merge_from(temp_tracer),
                        )
                        safe_postprocess(
                            "direct_call_summary_outcome_feedback",
                            lambda: self._record_direct_call_summary_outcome(
                                pred_bb,
                                fallthrough_bb,
                                candidate.get("direct_symbol", ""),
                                new_bbs=len(task_new_bbs),
                                target_bbs=len(task_new_targets),
                                stop_reason=stop_reason,
                            ),
                        )
                        task_structural_progress = task_dynamic_successor_edges > 0
                        if task_new_bbs or task_new_targets or task_structural_progress:
                            consecutive_low_yield_tasks = 0
                        else:
                            consecutive_low_yield_tasks += 1
                        if len(candidate_debug_records) < 32:
                            candidate_debug_records.append({
                                "pred_bb": f"0x{pred_bb:08x}",
                                "direct_target": f"0x{int(candidate.get('direct_target', 0) or 0):08x}",
                                "direct_symbol": str(candidate.get("direct_symbol") or ""),
                                "summary_policy": str(candidate.get("summary_policy") or ""),
                                "fallthrough": f"0x{fallthrough_bb:08x}",
                                "summary_return_value": f"0x{effective_summary_value:08x}",
                                "summary_return_reason": f"{summary_return_reason}:{effective_variant_reason}",
                                "summary_return_variant_count": len(summary_variants),
                                "summary_return_variant_limit": summary_value_limit,
                                "summary_symbol_priority": int(candidate.get("summary_symbol_priority", 0) or 0),
                                "summary_yield_penalty": int(candidate.get("summary_yield_penalty", 0) or 0),
                                "summary_category": str(candidate.get("summary_category") or ""),
                                "snapshot_prelude_rank_sample": candidate.get("snapshot_prelude_rank_sample", []),
                                "prelude_memory_stats": replay_prelude_memory_stats,
                                "summary_probe_prelude_memory_stats": prelude_memory_stats,
                                "pointer_arg_repair_stats": replay_pointer_arg_repair_stats,
                                "summary_probe_pointer_arg_repair_stats": pointer_arg_repair_stats,
                                "summary_side_effects": side_effects,
                                "downstream_potential": int(candidate.get("downstream_potential", 0) or 0),
                                "target_matches": int(candidate.get("target_matches", 0) or 0),
                                "new_bbs": len(task_new_bbs),
                                "target_bbs": len(task_new_targets),
                                "stop_reason": stop_reason,
                                "trace_tail": [
                                    f"0x{int(bb):08x}"
                                    for bb in list(getattr(trace, "executed_bbs", []) or [])[-16:]
                                ],
                                "snapshot_origin": str(getattr(snapshot_entry, "origin", "unknown")),
                                "source_path_len": len(
                                    getattr(snapshot_entry, "source_path_signature", tuple()) or tuple()
                                ),
                            })
                        dispose_temp_emulator(
                            emulator,
                            temp_mmio,
                            temp_tracer,
                            execution_record,
                        )
                        if low_yield_budget_exhausted():
                            low_yield_stop_triggered = True
                            break
                        if task_new_bbs:
                            refreshed_after_progress = True
                            break
                    if refreshed_after_progress:
                        break
                if refreshed_after_progress:
                    break
                if low_yield_stop_triggered:
                    break
            if tasks_run == tasks_before_round:
                break

        self._flush_temp_emulator_quarantine()
        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation="entry_derived_direct_call_summary_return",
            direct_call_summary_return_candidates=last_candidate_count,
            direct_call_summary_return_candidate_rounds=candidate_rounds,
            direct_call_summary_return_candidate_total=candidate_count_total,
            direct_call_summary_return_attempts=len(attempted),
            direct_call_summary_return_probe_attempts=int(probe_attempts),
            tasks_run=tasks_run,
            tasks_with_new_bbs=tasks_with_new_bbs,
            tasks_with_target_bbs=tasks_with_target_bbs,
            target_bbs=len(target_bb_set),
            target_bbs_discovered=len(target_bbs_discovered),
            target_bbs_discovered_list=[f"0x{bb:08x}" for bb in sorted(target_bbs_discovered)[:256]],
            restore_failed=restore_failed,
            invalid_snapshots=invalid_snapshots,
            invalid_snapshot_reasons=dict(invalid_reasons),
            callsite_not_reached=callsite_not_reached,
            unsupported_summary_returns=unsupported_summary_returns,
            unsafe_summary_return_fallthroughs=int(unsafe_summary_return_fallthroughs),
            unproven_dynamic_code_replays=int(unproven_dynamic_code_replays),
            summary_return_reasons=dict(summary_return_reasons),
            summary_side_effect_writes=int(summary_side_effect_writes),
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            stop_reasons=dict(stop_reasons),
            summary_return_outcome_count=len(self.direct_call_summary_return_outcomes),
            summary_return_outcome_samples=[
                {
                    "pred_bb": f"0x{int(key[0]):08x}",
                    "fallthrough": f"0x{int(key[1]):08x}",
                    "symbol": key[2],
                    "attempts": int(record.get("attempts", 0) or 0),
                    "new_bbs": int(record.get("new_bbs", 0) or 0),
                    "target_bbs": int(record.get("target_bbs", 0) or 0),
                    "stop_reasons": dict(record.get("stop_reasons") or {}),
                }
                for key, record in sorted(
                    self.direct_call_summary_return_outcomes.items(),
                    key=lambda item: (
                        -int((item[1] or {}).get("attempts", 0) or 0),
                        item[0],
                    ),
                )[:32]
            ],
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            no_new_bb_limit=no_new_bb_limit,
            max_tasks=max_tasks,
            max_targets=max_targets,
            variants_per_call=variants_per_call,
            time_limit_seconds=time_limit_seconds,
            low_yield_stop_tasks=int(low_yield_stop_tasks or 0),
            low_yield_min_tasks=int(low_yield_min_tasks or 0),
            consecutive_low_yield_tasks=int(consecutive_low_yield_tasks),
            low_yield_stop_triggered=bool(low_yield_stop_triggered),
            candidate_debug_records=candidate_debug_records,
            temp_emulator_cleanup_stats=dict(self.temp_emulator_cleanup_stats),
            child_execution_summary=self._child_execution_summary(
                len(child_execution_records),
                child_execution_interventions,
                expected_count=max(
                    len(attempted) + int(probe_attempts),
                    len(child_execution_records),
                ),
                attempted_count=len(attempted) + int(probe_attempts),
                execution_records=child_execution_records,
            ),
        )

    def run_rtos_thread_entry_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        max_tasks: int = 32,
        max_instructions: int = 120000,
        replay_timeout: int = 1_000_000,
        no_new_bb_limit: int = 4096,
        target_bbs: Optional[Set[int]] = None,
        max_targets: int = 32,
        variants_per_call: int = 2,
        phase_name: str = "rtos_thread_entry",
    ) -> Set[int]:
        """
        Replay RTOS-created thread/task entry functions from entry-derived create-call states.

        The entry address and argument are read from the concrete thread_create
        call snapshot reached from reset-entry execution. The phase does not
        count static reachability and does not jump to arbitrary uncovered BBs.
        """
        start_time = time.time()
        probe_diagnostic_start = len(
            list(getattr(self, "probe_diagnostics", []) or [])
        )
        target_bb_set = self.validate_coverage(target_bbs or set())
        phase_covered: Set[int] = set()
        tasks_run = 0
        tasks_with_new_bbs = 0
        tasks_with_target_bbs = 0
        target_bbs_discovered: Set[int] = set()
        candidate_rounds = 0
        candidate_count_total = 0
        last_candidate_count = 0
        restore_failed = 0
        invalid_snapshots = 0
        invalid_reasons: Counter[str] = Counter()
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        stop_reasons: Counter[str] = Counter()
        child_execution_interventions: Counter[str] = Counter()
        child_execution_records: List[Dict[str, object]] = []
        attempt_count = 0
        candidate_debug_records: List[Dict[str, object]] = []
        skip_function_installed_max = 0
        skip_function_applied_total = 0
        skip_function_by_symbol: Counter[str] = Counter()
        skip_function_entry_bbs: Set[int] = set()

        def budget_exhausted() -> bool:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                return True
            return max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks

        while not budget_exhausted():
            candidates = self._rtos_thread_entry_candidates(
                coverage=self.global_coverage | phase_covered,
                target_bbs=target_bb_set if target_bb_set else None,
                max_targets=max_targets,
            )
            candidate_rounds += 1
            last_candidate_count = len(candidates)
            candidate_count_total += len(candidates)
            if not candidates:
                break
            tasks_before_round = tasks_run
            refreshed_after_progress = False
            for candidate in candidates:
                if budget_exhausted() or refreshed_after_progress:
                    break
                pred_bb = int(candidate["pred_bb"])
                entry_items = _segment_rotate_sequence(
                    list(candidate.get("entry_items") or []),
                    f"rtos_thread_entry_items:{pred_bb}",
                )[:max(1, variants_per_call)]
                for snapshot_entry, entry_bb, downstream_potential, target_matches in entry_items:
                    if budget_exhausted():
                        break
                    attempt_key = (
                        int(pred_bb),
                        int(entry_bb),
                        self._snapshot_entry_identity(snapshot_entry),
                    )
                    if attempt_key in self.rtos_thread_entry_attempts_seen:
                        continue
                    self.rtos_thread_entry_attempts_seen.add(attempt_key)
                    attempt_count += 1

                    valid_snapshot, reason = self._validate_root_snapshot_entry(
                        snapshot_entry,
                        root_key=(pred_bb, 1),
                    )
                    if not valid_snapshot:
                        invalid_snapshots += 1
                        invalid_reasons[str(reason)] += 1
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=(
                                    f"{str(phase_name or 'rtos_thread_entry')}-"
                                    f"invalid-snapshot-{attempt_count}"
                                ),
                                reason=f"invalid_snapshot:{reason}",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "entry_bb": int(entry_bb),
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        reason,
                                    ),
                                },
                                execution_started=False,
                                execution_error=str(reason),
                                run_result={"execution_attempted": True},
                            )
                        )
                        child_execution_interventions["invalid_snapshot"] += 1
                        continue

                    try:
                        emulator = self._new_temp_emulator(
                            max_snapshots=max(3, self.max_snapshots),
                            llm_config_path=self._effective_llm_config_path(),
                            constraint_json_path=self.constraint_file,
                            branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                        )
                    except Exception as exc:
                        stop_reasons["emulator_create_exception"] += 1
                        logger.debug("RTOS thread emulator创建失败: %s", exc)
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=(
                                    f"{str(phase_name or 'rtos_thread_entry')}-"
                                    f"create-failure-{attempt_count}"
                                ),
                                reason="emulator_create_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "entry_bb": int(entry_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                            )
                        )
                        child_execution_interventions[
                            "emulator_create_exception"
                        ] += 1
                        continue
                    temp_mmio = None
                    temp_tracer = None
                    try:
                        self._configure_emulator_feedback(emulator)
                        self._configure_replay_skip_function_returns(emulator, include_time=True)
                        emulator.enable_branch_snapshot = True
                        temp_mmio = EnhancedMMIOHandler(
                            emulator.uc,
                            self.constraint_file,
                            branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                        )
                        temp_tracer = self._new_temp_register_tracer(emulator)
                        restored = self._restore_branch_snapshot(
                            emulator,
                            snapshot_entry.snapshot,
                            lineage_source=snapshot_entry,
                        )
                    except Exception as exc:
                        failure_result = self._materialize_replay_failure_result(
                            "replay_setup_exception",
                            execution_started=False,
                            execution_error=exc,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'rtos_thread_entry')}-"
                            f"setup-failure-{attempt_count}"
                        )
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                            run_result=failure_result,
                        )
                        stop_reasons["replay_setup_exception"] += 1
                        logger.debug("RTOS thread replay setup失败: %s", exc)
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=failure_execution_id,
                                reason="replay_setup_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "entry_bb": int(entry_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                                run_result=failure_result,
                            )
                        )
                        child_execution_interventions[
                            "replay_setup_exception"
                        ] += 1
                        continue
                    if not restored:
                        restore_failed += 1
                        stop_reasons["snapshot_restore_failed"] += 1
                        failure_result = self._materialize_replay_failure_result(
                            "snapshot_restore_failed",
                            execution_started=False,
                            execution_error="branch snapshot restore returned false",
                            restore_failed=True,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'rtos_thread_entry')}"
                            f"-restore-failure-{len(child_execution_records) + 1}"
                        )
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                            run_result=failure_result,
                        )
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=failure_execution_id,
                                reason="snapshot_restore_failed",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        "branch snapshot restore returned false",
                                    ),
                                },
                                execution_started=False,
                                execution_error="branch snapshot restore returned false",
                                run_result=failure_result,
                            )
                        )
                        child_execution_interventions["snapshot_restore_failed"] += 1
                        continue

                    if not self._restore_replay_mmio_state(
                        emulator,
                        temp_mmio,
                        snapshot_entry.mmio_state,
                    ):
                        restore_failed += 1
                        stop_reasons["replay_mmio_state_restore_failed"] += 1
                        restore_error = self._replay_mmio_restore_failure_reason(
                            emulator
                        )
                        failure_result = self._materialize_replay_failure_result(
                            "replay_mmio_state_restore_failed",
                            execution_started=False,
                            execution_error=restore_error,
                            restore_failed=True,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'rtos_thread_entry')}"
                            f"-mmio-restore-failure-{len(child_execution_records) + 1}"
                        )
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                            run_result=failure_result,
                        )
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=failure_execution_id,
                                reason="replay_mmio_state_restore_failed",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    **self._snapshot_restore_failure_metadata(
                                        snapshot_entry,
                                        restore_error,
                                    ),
                                },
                                execution_started=False,
                                execution_error=restore_error,
                                run_result=failure_result,
                            )
                        )
                        child_execution_interventions[
                            "replay_mmio_state_restore_failed"
                        ] += 1
                        continue
                    try:
                        self._apply_scoped_branch_constraints(
                            temp_mmio,
                            self._scope_signature_from_snapshot_entry(snapshot_entry),
                            emulator=emulator,
                        )
                    except Exception as exc:
                        failure_result = self._materialize_replay_failure_result(
                            "replay_constraint_setup_exception",
                            execution_started=False,
                            execution_error=exc,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'rtos_thread_entry')}-"
                            f"constraint-setup-failure-{attempt_count}"
                        )
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                            run_result=failure_result,
                        )
                        stop_reasons["replay_constraint_setup_exception"] += 1
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=failure_execution_id,
                                reason="replay_constraint_setup_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "entry_bb": int(entry_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                                run_result=failure_result,
                            )
                        )
                        child_execution_interventions[
                            "replay_constraint_setup_exception"
                        ] += 1
                        continue

                    try:
                        call_args = self._thread_create_call_args_from_live_pre_call(
                            snapshot_entry,
                            pred_bb,
                        ) or self._thread_create_call_args(snapshot_entry.snapshot)
                        thread_arg = int(call_args.get("arg", 0) or 0) & 0xFFFFFFFF
                        stack_size = int(call_args.get("stack_size", 0) or 0) & 0xFFFFFFFF
                        stack_base = int(call_args.get("stack_base", 0) or 0) & 0xFFFFFFFF
                    except Exception as exc:
                        failure_result = self._materialize_replay_failure_result(
                            "thread_call_argument_exception",
                            execution_started=False,
                            execution_error=exc,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'rtos_thread_entry')}-"
                            f"call-argument-failure-{attempt_count}"
                        )
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                            run_result=failure_result,
                        )
                        stop_reasons["thread_call_argument_exception"] += 1
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=failure_execution_id,
                                reason="thread_call_argument_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "entry_bb": int(entry_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                                run_result=failure_result,
                            )
                        )
                        child_execution_interventions[
                            "thread_call_argument_exception"
                        ] += 1
                        continue
                    try:
                        emulator.uc.reg_write(UC_ARM_REG_R0, thread_arg)
                        if stack_base and stack_size and stack_size < 0x100000:
                            thread_sp = (stack_base + stack_size - 0x40) & ~7
                            emulator.uc.reg_write(UC_ARM_REG_SP, thread_sp)
                        emulator.uc.reg_write(UC_ARM_REG_LR, 0xFFFFFFFF)
                        emulator.uc.reg_write(UC_ARM_REG_PC, int(entry_bb) | 1)
                        task_identity = f"rtos_thread:0x{int(entry_bb) & 0xFFFFFFFF:08x}"
                        emulator.causal_context.record_task_wakeup(
                            task_identity,
                            pc=int(pred_bb),
                            source="entry_derived_thread_create",
                        )
                        emulator.causal_context.set_active_task(
                            task_identity,
                            pc=int(entry_bb),
                            source="rtos_thread_entry_replay",
                        )
                    except Exception as exc:
                        failure_result = self._materialize_replay_failure_result(
                            "thread_context_setup_exception",
                            execution_started=False,
                            execution_error=exc,
                        )
                        failure_execution_id = (
                            f"{str(phase_name or 'rtos_thread_entry')}-"
                            f"context-setup-failure-{attempt_count}"
                        )
                        self._safe_dispose_temp_emulator(
                            emulator,
                            mmio_handler=temp_mmio,
                            register_tracer=temp_tracer,
                            quarantine=None,
                            stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                            run_result=failure_result,
                        )
                        stop_reasons["thread_context_setup_exception"] += 1
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name=str(phase_name or "rtos_thread_entry"),
                                execution_id=failure_execution_id,
                                reason="thread_context_setup_exception",
                                metadata={
                                    "entry_derivation": (
                                        "entry_derived_rtos_thread_create_snapshot"
                                    ),
                                    "context_snapshot_mode": True,
                                    "coverage_counted": True,
                                    "pred_bb": int(pred_bb),
                                    "entry_bb": int(entry_bb),
                                },
                                execution_started=False,
                                execution_error=exc,
                                run_result=failure_result,
                            )
                        )
                        child_execution_interventions[
                            "thread_context_setup_exception"
                        ] += 1
                        continue

                    known_before = self.global_coverage | phase_covered
                    previous_quiescence_limit = emulator.stop_after_no_new_bbs
                    emulator.stop_after_no_new_bbs = (
                        max(1, int(no_new_bb_limit))
                        if no_new_bb_limit and no_new_bb_limit > 0
                        else None
                    )
                    run_result: Dict[str, object] = {"stop_reason": "not_started"}
                    run_exception: Optional[BaseException] = None
                    with self.guided_modules(temp_mmio, temp_tracer), self.capture_execution_trace(emulator) as trace:
                        try:
                            run_result = emulator.run(
                                entry_point=None,
                                max_instructions=max_instructions,
                                timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                                preserve_cpu_state=True,
                            )
                        except Exception as exc:
                            run_exception = exc
                            run_result = self._materialize_replay_failure_result(
                                "execution_exception",
                                execution_started=True,
                                execution_error=exc,
                            )
                        finally:
                            emulator.stop_after_no_new_bbs = previous_quiescence_limit

                    execution_failed = bool(run_result.get("execution_failed")) or bool(
                        run_result.get("preflight_failed")
                    )
                    execution_metadata = {
                        "entry_derivation": (
                            "entry_derived_rtos_thread_create_snapshot"
                        ),
                        "context_snapshot_mode": True,
                        "coverage_counted": not execution_failed,
                        "pred_bb": int(pred_bb),
                        "entry_bb": int(entry_bb),
                        "thread_create_symbol": str(
                            candidate.get("thread_create_symbol") or ""
                        ),
                    }
                    execution_id = (
                        f"{str(phase_name or 'rtos_thread_entry')}"
                        f"-task-{attempt_count}"
                    )
                    if execution_failed or run_exception is not None:
                        execution_record = self._execution_failure_evidence_record(
                            phase_name=str(phase_name or "rtos_thread_entry"),
                            execution_id=execution_id,
                            reason=str(
                                run_result.get("stop_reason") or "execution_failed"
                            ),
                            metadata=execution_metadata,
                            covered_bbs=(),
                            execution_started=bool(
                                run_result.get("execution_started", False)
                            ),
                            execution_error=(
                                run_result.get("execution_error")
                                or run_exception
                            ),
                            run_result=run_result,
                        )
                    else:
                        execution_record = build_execution_evidence_record(
                            phase_name=str(phase_name or "rtos_thread_entry"),
                            run_result=run_result,
                            covered_bbs=trace.covered_bbs,
                            metadata=execution_metadata,
                            execution_id=execution_id,
                        )
                    child_execution_records.append(execution_record)

                    def safe_postprocess(operation: str, callback, default=None):
                        return self._safe_replay_postprocess(
                            operation,
                            callback,
                            evidence_record=execution_record,
                            run_result=run_result,
                            default=default,
                        )

                    child_execution_interventions.update(
                        execution_record.get("actual_intervention_reasons", []) or []
                    )

                    skip_stats = dict(getattr(emulator, "skip_function_stats", {}) or {})
                    skip_function_installed_max = max(
                        skip_function_installed_max,
                        int(skip_stats.get("installed", 0) or 0),
                    )
                    skip_function_applied_total += int(skip_stats.get("applied", 0) or 0)
                    for symbol, count in (skip_stats.get("by_symbol", {}) or {}).items():
                        skip_function_by_symbol[str(symbol)] += int(count or 0)
                    skip_function_entry_bbs.update(
                        int(bb) for bb in (getattr(emulator, "skipped_function_entry_bbs", set()) or set())
                    )

                    valid = (
                        set()
                        if execution_failed
                        else self.validate_coverage(trace.covered_bbs)
                    )
                    task_new_bbs = valid - known_before
                    task_new_targets = task_new_bbs & (target_bb_set or {int(entry_bb)})
                    if task_new_bbs:
                        tasks_with_new_bbs += 1
                    if task_new_targets:
                        tasks_with_target_bbs += 1
                        target_bbs_discovered.update(task_new_targets)
                    phase_covered.update(valid)
                    safe_postprocess(
                        "coverage_evidence",
                        lambda: self._record_coverage_evidence(EVIDENCE_E3, valid),
                    )

                    replay_events = safe_postprocess(
                        "branch_event_collection",
                        lambda: emulator.branch_snapshot_manager.get_ordered_events(),
                        default=[],
                    ) or []
                    replay_snapshots = safe_postprocess(
                        "replay_snapshot_collection",
                        lambda: self._ordered_replay_snapshots(emulator),
                        default=[],
                    ) or []
                    remembered_branch_events += safe_postprocess(
                        "branch_event_feedback",
                        lambda: self._remember_main_branch_events(
                            replay_events,
                            evidence_class=EVIDENCE_E3,
                        ),
                        default=0,
                    ) or 0
                    remembered_branch_root_snapshots += safe_postprocess(
                        "branch_snapshot_feedback",
                        lambda: self._remember_branch_root_snapshots(
                            replay_events,
                            replay_snapshots,
                            source_path_signature=getattr(snapshot_entry, "source_path_signature", tuple()) or tuple(),
                            evidence_class=EVIDENCE_E3,
                            occurrence_events=(
                                emulator.branch_snapshot_manager
                                .get_ordered_occurrence_events()
                            ),
                            source_occurrence_signature=(
                                self._snapshot_entry_occurrence_prefix(snapshot_entry)
                            ),
                        ),
                        default=0,
                    ) or 0
                    dynamic_successor_edges_added += safe_postprocess(
                        "dynamic_successor_feedback",
                        lambda: self._record_dynamic_successors(replay_events),
                        default=0,
                    ) or 0
                    dynamic_successor_edges_added += safe_postprocess(
                        "runtime_successor_feedback",
                        lambda: self._record_emulator_runtime_successors(emulator),
                        default=0,
                    ) or 0
                    safe_postprocess(
                        "scheduler_feedback",
                        lambda: self._harvest_emulator_feedback(emulator),
                    )
                    safe_postprocess(
                        "register_tracer_merge",
                        lambda: self.register_tracer.merge_from(temp_tracer),
                    )

                    tasks_run += 1
                    stop_reason = str(run_result.get("stop_reason") or "unknown")
                    stop_reasons[stop_reason] += 1
                    if len(candidate_debug_records) < 32:
                        candidate_debug_records.append({
                            "pred_bb": f"0x{pred_bb:08x}",
                            "thread_create_symbol": str(candidate.get("thread_create_symbol") or ""),
                            "thread_create_target": (
                                f"0x{int(candidate['thread_create_target']):08x}"
                                if candidate.get("thread_create_target") is not None
                                else None
                            ),
                            "entry_bb": f"0x{int(entry_bb):08x}",
                            "entry_symbol": getattr(self.prepared, "symbols_by_addr", {}).get(int(entry_bb), ""),
                            "thread_arg": f"0x{int(thread_arg):08x}",
                            "thread_stack_base": f"0x{int(stack_base):08x}",
                            "thread_stack_size": int(stack_size),
                            "downstream_potential": int(downstream_potential),
                            "target_matches": [
                                f"0x{int(bb):08x}" for bb in list(target_matches or [])[:8]
                            ],
                            "new_bbs": len(task_new_bbs),
                            "target_bbs": len(task_new_targets),
                            "stop_reason": stop_reason,
                            "skip_function_stats": {
                                "installed": int(skip_stats.get("installed", 0) or 0),
                                "applied": int(skip_stats.get("applied", 0) or 0),
                                "by_symbol": dict(skip_stats.get("by_symbol", {}) or {}),
                            },
                            "trace_tail": [
                                f"0x{int(bb):08x}"
                                for bb in list(getattr(trace, "executed_bbs", []) or [])[-16:]
                            ],
                            "snapshot_origin": str(getattr(snapshot_entry, "origin", "unknown")),
                            "source_path_len": len(
                                getattr(snapshot_entry, "source_path_signature", tuple()) or tuple()
                            ),
                        })
                    self._safe_dispose_temp_emulator(
                        emulator,
                        mmio_handler=temp_mmio,
                        register_tracer=temp_tracer,
                        quarantine=None,
                        stage_name=self._temp_stage_for("rtos_thread_entry_task"),
                        evidence_record=execution_record,
                    )
                    if task_new_bbs:
                        refreshed_after_progress = True
                        break
                if refreshed_after_progress:
                    break
            if tasks_run == tasks_before_round:
                break

        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation="entry_derived_rtos_thread_create_snapshot",
            context_snapshot_mode=True,
            child_execution_summary=self._child_execution_summary(
                attempt_count,
                child_execution_interventions,
                expected_count=attempt_count,
                execution_records=child_execution_records,
            ),
            rtos_thread_entry_candidates=last_candidate_count,
            rtos_thread_entry_candidate_rounds=candidate_rounds,
            rtos_thread_entry_candidate_total=candidate_count_total,
            rtos_thread_entry_attempts=len(self.rtos_thread_entry_attempts_seen),
            tasks_run=tasks_run,
            tasks_with_new_bbs=tasks_with_new_bbs,
            tasks_with_target_bbs=tasks_with_target_bbs,
            target_bbs=len(target_bb_set),
            target_bbs_discovered=len(target_bbs_discovered),
            target_bbs_discovered_list=[f"0x{bb:08x}" for bb in sorted(target_bbs_discovered)[:256]],
            restore_failed=restore_failed,
            invalid_snapshots=invalid_snapshots,
            invalid_snapshot_reasons=dict(invalid_reasons),
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            stop_reasons=dict(stop_reasons),
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            no_new_bb_limit=no_new_bb_limit,
            max_tasks=max_tasks,
            max_targets=max_targets,
            variants_per_call=variants_per_call,
            time_limit_seconds=time_limit_seconds,
            skip_function_stats={
                "installed_max": int(skip_function_installed_max),
                "applied_total": int(skip_function_applied_total),
                "by_symbol": dict(skip_function_by_symbol),
                "skipped_entry_bbs": [
                    f"0x{int(bb):08x}" for bb in sorted(skip_function_entry_bbs)[:256]
                ],
            },
            candidate_debug_records=candidate_debug_records,
            probe_diagnostics=(
                list(getattr(self, "probe_diagnostics", []) or [])
                [probe_diagnostic_start:][-64:]
            ),
        )

    def run_isr_reservoir_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        max_instructions: int = 20000,
        replay_timeout: int = 1_000_000,
        max_tasks: int = 500,
        max_tasks_per_isr: int = 64,
        dynamic_frontier_seeding: bool = True,
        context_snapshots: bool = False,
        max_contexts: int = 16,
        include_reservoir_contexts: bool = False,
        max_reservoir_contexts: int = 16,
        max_isrs: int = 0,
        target_bbs: Optional[Set[int]] = None,
        prioritize_target_bbs: bool = False,
        phase_name: str = "isr_reservoir",
    ) -> Set[int]:
        """Explore alternate paths inside dynamically observed ISR handlers."""
        start_time = time.time()
        phase_covered: Set[int] = set()
        baseline_isrs = 0
        isr_with_branches = 0
        tasks_run = 0
        forced_hit_tasks = 0
        forced_missed_tasks = 0
        full_hit_tasks = 0
        partial_hit_tasks = 0
        isr_stack_stats = Counter()
        isr_execution_start_stats = Counter()
        invalid_stack_samples: List[Dict[str, object]] = []
        child_tasks_enqueued = 0
        dynamic_frontier_tasks_enqueued = 0
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        dynamic_successor_edges_added = 0
        target_hit_tasks = 0
        target_bbs_discovered: Set[int] = set()
        target_bb_set = self.validate_coverage(target_bbs or set())
        child_execution_interventions: Counter[str] = Counter()
        child_execution_count = 0
        child_execution_records: List[Dict[str, object]] = []
        probe_error: Optional[str] = None
        learned_irq_candidates: List[Dict[str, object]] = []
        probe_isr_addresses: Dict[int, int] = {}
        contexts = (
            self._select_interrupt_contexts(
                max_contexts=max_contexts,
                include_reservoir_contexts=include_reservoir_contexts,
                max_reservoir_contexts=max_reservoir_contexts,
            )
            if context_snapshots
            else []
        )
        context_items = contexts or [None]
        context_attempts = 0

        def budget_exhausted() -> bool:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                return True
            return max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks

        effective_successors = self._effective_successor_map()
        static_reachable_cache: Dict[int, Set[int]] = {}

        def static_reachable_from(start_bb: Optional[int]) -> Set[int]:
            if start_bb is None or start_bb not in self.prepared.static_bb_set:
                return set()
            cached = static_reachable_cache.get(start_bb)
            if cached is not None:
                return cached
            queue = deque([start_bb])
            seen = {start_bb}
            while queue:
                current = queue.popleft()
                for successor in effective_successors.get(current, set()):
                    if successor not in seen:
                        seen.add(successor)
                        queue.append(successor)
            static_reachable_cache[start_bb] = seen
            return seen

        def static_target_potential(start_bb: Optional[int], known_coverage: Set[int]) -> int:
            if not target_bb_set or start_bb is None:
                return 0
            return len((static_reachable_from(start_bb) & target_bb_set) - known_coverage)

        def static_new_potential(start_bb: Optional[int], known_coverage: Set[int]) -> int:
            if start_bb is None:
                return 0
            return len(static_reachable_from(start_bb) - known_coverage)

        def isr_target_priority(irq_num: int, isr_addr: int, known_coverage: Set[int]) -> Tuple[int, int, int, int]:
            start_bb = self.prepared.resolve_basic_block(isr_addr) or isr_addr
            return (
                static_target_potential(start_bb, known_coverage),
                static_new_potential(start_bb, known_coverage),
                -int(irq_num),
                int(start_bb),
            )

        def successor_should_expand(successor: Optional[int], known_coverage: Set[int]) -> bool:
            if successor is None:
                return False
            if prioritize_target_bbs and target_bb_set:
                return static_target_potential(successor, known_coverage) > 0
            return successor not in known_coverage

        def successor_priority(successor: Optional[int], known_coverage: Set[int], is_switch: bool) -> Tuple[int, int, int, int]:
            return (
                static_target_potential(successor, known_coverage),
                static_new_potential(successor, known_coverage),
                1 if is_switch else 0,
                int(successor or 0),
            )

        def is_switch_event(event) -> bool:
            return _is_switch_frontier_mnemonic(getattr(event, "condition", "")) and bool(getattr(event, "alternatives", []))

        def event_key(event) -> Tuple[int, int]:
            return (event.address, getattr(event, "occurrence_index", 1))

        def event_edge_identity(event):
            if is_switch_event(event):
                return (event.address, getattr(event, "original_index", None))
            if _is_call_frontier_mnemonic(getattr(event, "condition", "")):
                alternatives = tuple(
                    self.prepared.resolve_basic_block(int(target or 0))
                    for target in getattr(event, "alternatives", []) or []
                    if self.prepared.resolve_basic_block(int(target or 0)) is not None
                )
                return (event.address, getattr(event, "condition", ""), alternatives)
            return (event.address, event.original_taken)

        def compact_events(events):
            first_by_edge = {}
            last_order_by_edge = {}
            for event in events:
                edge = event_edge_identity(event)
                first_by_edge.setdefault(edge, event)
                last_order_by_edge[edge] = event.order
            return [
                first_by_edge[edge]
                for edge in sorted(first_by_edge, key=lambda item: last_order_by_edge[item])
            ]

        def choice_values(event) -> List[object]:
            if is_switch_event(event):
                values = []
                seen_targets = set()
                original_index = getattr(event, "original_index", None)
                for index, target in enumerate(getattr(event, "alternatives", [])):
                    if target == 0 or index == original_index or target in seen_targets:
                        continue
                    seen_targets.add(target)
                    values.append(index)
                return values
            if _is_call_frontier_mnemonic(getattr(event, "condition", "")):
                values = []
                seen_successors = set()
                alternatives = list(getattr(event, "alternatives", []) or [])
                if not alternatives:
                    alternatives = [
                        int(getattr(event, "target", 0) or 0),
                        int(getattr(event, "fallthrough", 0) or 0),
                    ]
                for target in alternatives:
                    successor = self.prepared.resolve_basic_block(int(target or 0))
                    if successor is None or successor in seen_successors:
                        continue
                    seen_successors.add(successor)
                    values.append(int(successor))
                return values
            return [not event.original_taken]

        def choice_successor_bb(event, choice: Optional[object] = None) -> Optional[int]:
            if is_switch_event(event):
                alternatives = getattr(event, "alternatives", [])
                if choice is None:
                    for candidate in choice_values(event):
                        successor = choice_successor_bb(event, candidate)
                        if successor is not None and successor not in self.global_coverage:
                            return successor
                    return None
                try:
                    index = int(choice)
                except (TypeError, ValueError):
                    return None
                if index < 0 or index >= len(alternatives) or alternatives[index] == 0:
                    return None
                return self.prepared.resolve_basic_block(alternatives[index])
            if _is_call_frontier_mnemonic(getattr(event, "condition", "")):
                if choice is None:
                    for candidate in choice_values(event):
                        successor = choice_successor_bb(event, candidate)
                        if successor is not None and successor not in self.global_coverage:
                            return successor
                    return None
                try:
                    return self.prepared.resolve_basic_block(int(choice))
                except (TypeError, ValueError):
                    return None
            direction = (not event.original_taken) if choice is None else bool(choice)
            return self.prepared.resolve_basic_block(event.target if direction else event.fallthrough)

        def observed_successor_bb(event) -> Optional[int]:
            if is_switch_event(event):
                target = getattr(event, "target", 0)
                return self.prepared.resolve_basic_block(target) if target else None
            if _is_call_frontier_mnemonic(getattr(event, "condition", "")):
                target = getattr(event, "target", 0)
                return self.prepared.resolve_basic_block(target) if target else None
            return self.prepared.resolve_basic_block(event.target if event.original_taken else event.fallthrough)

        def path_key(choices: Dict[Tuple[int, int], object]):
            return tuple(sorted(choices.items(), key=lambda item: item[0]))

        def ordered_sequence(choices: Dict[Tuple[int, int], object], event_depth: Dict[Tuple[int, int], int]) -> List[Tuple[Tuple[int, int], object]]:
            return [
                (self._ordered_replay_token(key), choice)
                for key, choice in sorted(
                    choices.items(),
                    key=lambda item: (event_depth.get(item[0], 0), item[0]),
                )
            ]

        def ordered_choices_hit(choices: Dict[Tuple[int, int], object], branch_trace: List[Dict[str, int]],
                                event_depth: Dict[Tuple[int, int], int]) -> bool:
            cursor = 0
            for key, choice in sorted(choices.items(), key=lambda item: (event_depth.get(item[0], 0), item[0])):
                wanted = (self._ordered_replay_token(key), int(choice))
                found = False
                while cursor < len(branch_trace):
                    item = branch_trace[cursor]
                    cursor += 1
                    if (
                        self._branch_trace_matches_token(item, wanted[0])
                        and item.get("direction") == wanted[1]
                        and item.get("verified", True)
                    ):
                        found = True
                        break
                if not found:
                    return False
            return True

        def configure_isr_emulator(lease):
            emulator = lease.emulator
            emulator.enable_branch_snapshot = True
            emulator.enable_loop_intervention = False
            temp_mmio = lease.bind_mmio(EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            ))
            # Carry over current MMIO state so ISR replays see initialized
            # peripheral state from the main execution.
            temp_mmio.mmio_state.update(getattr(self.mmio_handler, "mmio_state", {}))
            temp_mmio.mark_mmio_state_explicit()
            explorer = ISRExplorer(
                emulator.uc,
                self.prepared.static_bbs,
                vtor=self._vector_table_base(),
                mmio_handler=temp_mmio,
                instruction_to_bb=self.prepared.instruction_to_bb,
                broad_interrupt_flags=True,
                code_ranges=self._code_address_ranges(),
                start_validator=lambda start_pc: emulator._execution_preflight(start_pc),
                causal_context=emulator.causal_context,
            )
            return emulator, temp_mmio, explorer

        def managed_isr_emulator():
            return self._managed_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=self._effective_llm_config_path(),
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=self._temp_stage_for("contextual_isr_frontier_task"),
            )

        @contextmanager
        def managed_isr_emulator_safe(error_holder: Optional[List[BaseException]] = None):
            """Materialize lease-construction failures without changing replay."""
            manager = managed_isr_emulator()

            def retain_cleanup_errors(lease) -> None:
                if error_holder is None or lease is None:
                    return
                try:
                    retained = self._collect_temp_emulator_cleanup_errors(
                        lease.emulator,
                        mmio_handler=getattr(lease, "mmio_handler", None),
                        register_tracer=getattr(lease, "register_tracer", None),
                    )
                except Exception as exc:
                    retained = [
                        "cleanup_error_collection:"
                        f"{type(exc).__name__}:{str(exc)[:512]}"
                    ]
                existing = {str(error) for error in error_holder}
                for error_text in retained:
                    if error_text and error_text not in existing:
                        error_holder.append(RuntimeError(error_text))
                        existing.add(error_text)
                if retained:
                    # The caller may return from inside the lease scope (for
                    # example after construction/setup failure), in which
                    # case its post-scope bookkeeping is bypassed.  Invalidate
                    # by the emulator-owned execution id here as a backstop;
                    # the normal post-scope path still annotates the exact
                    # child record when one exists.
                    self._invalidate_temp_emulator_snapshot_provenance(
                        lease.emulator,
                        reason="replay_cleanup_exception",
                        error=retained[-1],
                    )

            try:
                lease = manager.__enter__()
            except Exception as exc:
                if error_holder is not None:
                    error_holder.append(exc)
                logger.debug("ISR reservoir emulator creation failed: %s", exc)
                yield None
                return
            try:
                yield lease
            except BaseException as body_error:
                body_type, body_value, body_traceback = sys.exc_info()
                try:
                    suppressed = manager.__exit__(
                        body_type,
                        body_value,
                        body_traceback,
                    )
                except Exception as cleanup_error:
                    if error_holder is not None:
                        error_holder.append(cleanup_error)
                    if lease is not None:
                        self._invalidate_temp_emulator_snapshot_provenance(
                            lease.emulator,
                            reason="replay_cleanup_exception",
                            error=cleanup_error,
                        )
                    logger.debug(
                        "ISR reservoir replay cleanup failed after body error: %s",
                        cleanup_error,
                    )
                    # Preserve the execution/setup exception.  Cleanup is
                    # reported separately so it cannot mask the real cause.
                    raise body_error.with_traceback(body_traceback)
                retain_cleanup_errors(lease)
                if suppressed:
                    return
                raise
            else:
                try:
                    manager.__exit__(None, None, None)
                except Exception as cleanup_error:
                    if error_holder is not None:
                        error_holder.append(cleanup_error)
                    if lease is not None:
                        self._invalidate_temp_emulator_snapshot_provenance(
                            lease.emulator,
                            reason="replay_cleanup_exception",
                            error=cleanup_error,
                        )
                    logger.debug(
                        "ISR reservoir replay cleanup failed: %s",
                        cleanup_error,
                    )
                finally:
                    retain_cleanup_errors(lease)

        def execute_isr(irq_num: int, isr_addr: int, choices: Optional[Dict[Tuple[int, int], object]] = None,
                        event_depth: Optional[Dict[Tuple[int, int], int]] = None,
                        snapshot=None):
            nonlocal invalid_stack_samples, child_execution_count
            nonlocal child_execution_records
            execution_started = False
            execution_error: Optional[str] = None
            covered: Set[int] = set()
            events: List[object] = []
            replay_snapshots: List[object] = []
            branch_trace: List[Dict[str, object]] = []
            runtime_edges_added = 0
            lease_errors: List[BaseException] = []
            execution_baseline: Optional[Mapping[str, object]] = None
            finalization_result: Dict[str, object] = {}
            with managed_isr_emulator_safe(lease_errors) as lease:
                if lease is None:
                    child_execution_count += 1
                    failure_record = self._execution_failure_evidence_record(
                        phase_name=str(phase_name or "isr_reservoir"),
                        execution_id=(
                            f"{str(phase_name or 'isr_reservoir')}-attempt-"
                            f"{child_execution_count}"
                        ),
                        reason="emulator_create_exception",
                        metadata={
                            "entry_derivation": (
                                "entry_derived_context_snapshot_event_replay"
                                if snapshot is not None
                                else "cold_vector_handler_direct_entry"
                            ),
                            "context_snapshot_mode": snapshot is not None,
                            "coverage_counted": True,
                            "irq": int(irq_num),
                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                        },
                        execution_started=False,
                        execution_error=(lease_errors[0] if lease_errors else "lease unavailable"),
                    )
                    child_execution_records.append(failure_record)
                    child_execution_interventions.update(
                        failure_record.get("actual_intervention_reasons", {}) or {}
                    )
                    return (set(), [], [], [], False, 0)
                try:
                    emulator, temp_mmio, explorer = configure_isr_emulator(lease)
                except Exception as exc:
                    child_execution_count += 1
                    failure_record = self._execution_failure_evidence_record(
                        phase_name=str(phase_name or "isr_reservoir"),
                        execution_id=(
                            f"{str(phase_name or 'isr_reservoir')}-attempt-"
                            f"{child_execution_count}"
                        ),
                        reason="replay_setup_exception",
                        metadata={
                            "entry_derivation": (
                                "entry_derived_context_snapshot_event_replay"
                                if snapshot is not None
                                else "cold_vector_handler_direct_entry"
                            ),
                            "context_snapshot_mode": snapshot is not None,
                            "coverage_counted": True,
                            "irq": int(irq_num),
                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                        },
                        execution_started=False,
                        execution_error=exc,
                    )
                    child_execution_records.append(failure_record)
                    child_execution_interventions.update(
                        failure_record.get("actual_intervention_reasons", {}) or {}
                    )
                    return (set(), [], [], [], False, 0)
                if choices:
                    emulator.set_ordered_forced_branch_choices(ordered_sequence(choices, event_depth or {}))
                try:
                    with self.guided_modules(temp_mmio), self.capture_coverage(emulator) as covered:
                        try:
                            if snapshot is not None:
                                context_snapshot = self._interrupt_context_snapshot(snapshot)
                                if context_snapshot is None:
                                    execution_error = "context_snapshot_unavailable"
                                elif not self._restore_branch_snapshot(
                                    emulator,
                                    context_snapshot,
                                    lineage_source=(
                                        snapshot
                                        if isinstance(snapshot, PrefixReplaySnapshot)
                                        else None
                                    ),
                                ):
                                    execution_error = "snapshot_restore_failed"
                                else:
                                    if not self._restore_replay_mmio_state(
                                        emulator,
                                        temp_mmio,
                                        self._interrupt_context_mmio_state(snapshot),
                                    ):
                                        execution_error = (
                                            self._replay_mmio_restore_failure_reason(
                                                emulator
                                            )
                                        )
                                    else:
                                        try:
                                            return_pc = emulator.uc.reg_read(UC_ARM_REG_PC)
                                        except Exception:
                                            return_pc = 0
                                        explorer._setup_isr_context(
                                            isr_addr,
                                            irq_num,
                                            preserve_registers=True,
                                            return_pc=return_pc,
                                        )
                            else:
                                explorer._setup_isr_context(isr_addr, irq_num)

                            if execution_error is None:
                                # Snapshot restoration may replace the
                                # primary handler's cumulative RX counters.
                                # Capture after that restoration and after ISR
                                # context setup so this record contains only
                                # facts produced by the upcoming attempt.
                                execution_baseline = self._capture_direct_execution_baseline(
                                    emulator,
                                    str(phase_name or "isr_reservoir"),
                                    mmio_handler=temp_mmio,
                                )
                                self._begin_direct_execution(emulator)
                                execution_started = bool(
                                    explorer.start_isr_execution(
                                        isr_addr | 1,
                                        timeout=replay_timeout,
                                        count=max_instructions,
                                    )
                                )
                                if not execution_started:
                                    execution_error = "isr_start_failed"
                        except Exception as exc:
                            execution_error = f"{type(exc).__name__}: {str(exc)[:512]}"
                        finally:
                            finalization_result = self._finalize_direct_execution(
                                emulator,
                                execution_baseline,
                                execution_started=execution_started,
                                execution_error=execution_error,
                            )
                    if finalization_result.get("finalization_error"):
                        invalidation = self._invalidate_temp_emulator_snapshot_provenance(
                            emulator,
                            execution_baseline=execution_baseline,
                            reason="direct_execution_finalization_exception",
                            error=finalization_result.get("finalization_error"),
                        )
                        finalization_result["provenance_invalidated"] = True
                        finalization_result[
                            "provenance_invalidation_reasons"
                        ] = ["direct_execution_finalization_exception"]
                        finalization_result[
                            "invalidated_snapshots"
                        ] = int(invalidation.get("invalidated_snapshots", 0) or 0)
                except Exception as exc:
                    # Hook teardown and trace finalization are part of the
                    # execution contract.  A failure there must downgrade the
                    # attempt, but it must not terminate the whole ISR phase.
                    cleanup_error = f"{type(exc).__name__}: {str(exc)[:512]}"
                    if execution_error is None:
                        execution_error = f"trace_scope_exception: {cleanup_error}"
                    else:
                        execution_error = (
                            f"{execution_error}; trace_scope_exception: {cleanup_error}"
                        )

                child_execution_count += 1
                try:
                    explorer_stats = dict(explorer.get_statistics() or {})
                    isr_stack_stats.update(explorer_stats.get("isr_stack", {}) or {})
                    isr_execution_start_stats.update(
                        explorer_stats.get("execution_start", {}) or {}
                    )
                    invalid_stack_samples.extend(
                        explorer_stats.get("invalid_stack_samples", []) or []
                    )
                    if len(invalid_stack_samples) > 32:
                        invalid_stack_samples = invalid_stack_samples[-32:]
                    runtime_edges_added = self._record_emulator_runtime_successors(emulator)
                    events = list(emulator.branch_snapshot_manager.get_ordered_events())
                    replay_snapshots = list(self._ordered_replay_snapshots(emulator))
                    branch_trace = [
                        dict(item)
                        for item in list(emulator.forced_branch_trace or [])
                        if isinstance(item, Mapping)
                    ]
                    additional_reasons = []
                    if any(
                        int(value or 0) > 0
                        for key, value in dict(
                            explorer_stats.get("isr_stack", {}) or {}
                        ).items()
                        if "repair" in str(key).lower()
                    ):
                        additional_reasons.append("isr_stack_repair")
                    execution_record = self._direct_execution_evidence_record(
                        phase_name=str(phase_name or "isr_reservoir"),
                        emulator=emulator,
                        covered_bbs=covered,
                        metadata={
                            "entry_derivation": (
                                "entry_derived_context_snapshot_event_replay"
                                if snapshot is not None
                                else "cold_vector_handler_direct_entry"
                            ),
                            "context_snapshot_mode": snapshot is not None,
                            "coverage_counted": True,
                            "irq": int(irq_num),
                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                        },
                        execution_started=execution_started,
                        execution_error=execution_error,
                        additional_intervention_reasons=additional_reasons,
                        execution_baseline=execution_baseline,
                        mmio_handler=temp_mmio,
                        finalization_result=finalization_result,
                    )
                    child_execution_records.append(execution_record)
                    child_execution_interventions.update(
                        execution_record.get("actual_intervention_reasons", []) or []
                    )
                    result = (
                        self.validate_coverage(set(covered)),
                        events,
                        replay_snapshots,
                        branch_trace,
                        execution_started,
                        runtime_edges_added,
                    )
                except Exception as exc:
                    # Result collection is deliberately fail-closed for
                    # evidence: preserve observed diagnostic facts, but never
                    # let a broken stats/trace adapter abort later ISR tasks or
                    # turn an incomplete attempt into a strict witness.
                    try:
                        observed_covered = self.validate_coverage(set(covered))
                    except Exception:
                        observed_covered = set()
                    failure_record = self._execution_failure_evidence_record(
                        phase_name=str(phase_name or "isr_reservoir"),
                        execution_id=str(
                            execution_baseline.get("execution_id")
                            if isinstance(execution_baseline, Mapping)
                            else ""
                        ),
                        reason="replay_result_collection_exception",
                        metadata={
                            "entry_derivation": (
                                "entry_derived_context_snapshot_event_replay"
                                if snapshot is not None
                                else "cold_vector_handler_direct_entry"
                            ),
                            "context_snapshot_mode": snapshot is not None,
                            "coverage_counted": True,
                            "irq": int(irq_num),
                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                        },
                        covered_bbs=observed_covered,
                        execution_started=execution_started,
                        execution_error=exc,
                    )
                    child_execution_records.append(failure_record)
                    child_execution_interventions.update(
                        failure_record.get("actual_intervention_reasons", {}) or {}
                    )
                    result = (
                        observed_covered,
                        [],
                        [],
                        [],
                        execution_started,
                        runtime_edges_added,
                    )
            # ``_managed_temp_emulator`` performs teardown after the body of
            # this context manager.  If that teardown failed, the body may
            # already have materialized a successful-looking direct-execution
            # record.  Downgrade that exact record before returning so its BBs
            # remain diagnostic but cannot become strict validated evidence.
            cleanup_errors: List[BaseException] = list(lease_errors)
            if lease is not None:
                try:
                    retained_cleanup_errors = self._collect_temp_emulator_cleanup_errors(
                        lease.emulator,
                        mmio_handler=getattr(lease, "mmio_handler", None),
                        register_tracer=getattr(lease, "register_tracer", None),
                    )
                except Exception as exc:
                    retained_cleanup_errors = [
                        "cleanup_error_collection:"
                        f"{type(exc).__name__}:{str(exc)[:512]}"
                    ]
                known_errors = {str(error) for error in cleanup_errors}
                for error_text in retained_cleanup_errors:
                    if error_text and error_text not in known_errors:
                        cleanup_errors.append(RuntimeError(error_text))
                        known_errors.add(error_text)

            if cleanup_errors and lease is not None:
                cleanup_error = cleanup_errors[-1]
                execution_id = str(
                    execution_baseline.get("execution_id")
                    if isinstance(execution_baseline, Mapping)
                    else ""
                )
                matching_record = None
                for candidate_record in reversed(child_execution_records):
                    if execution_id and str(
                        candidate_record.get("execution_id") or ""
                    ) == execution_id:
                        matching_record = candidate_record
                        break
                if matching_record is not None:
                    invalidation = self._invalidate_temp_emulator_snapshot_provenance(
                        lease.emulator,
                        evidence_record=matching_record,
                        execution_baseline=execution_baseline,
                        reason="replay_cleanup_exception",
                        error=cleanup_error,
                    )
                    self._downgrade_execution_evidence_record(
                        matching_record,
                        reason="replay_cleanup_exception",
                        error=cleanup_error,
                    )
                else:
                    cleanup_record = self._execution_failure_evidence_record(
                        phase_name=str(phase_name or "isr_reservoir"),
                        execution_id=(
                            execution_id
                            or f"{str(phase_name or 'isr_reservoir')}-"
                            f"cleanup-{child_execution_count}"
                        ),
                        reason="replay_cleanup_exception",
                        metadata={
                            "entry_derivation": (
                                "entry_derived_context_snapshot_event_replay"
                                if snapshot is not None
                                else "cold_vector_handler_direct_entry"
                            ),
                            "context_snapshot_mode": snapshot is not None,
                            "coverage_counted": True,
                            "irq": int(irq_num),
                            "isr_address": int(isr_addr) & 0xFFFFFFFF,
                        },
                        covered_bbs=covered,
                        execution_started=execution_started,
                        execution_error=cleanup_error,
                    )
                    child_execution_records.append(cleanup_record)
                    invalidation = self._invalidate_temp_emulator_snapshot_provenance(
                        lease.emulator,
                        evidence_record=cleanup_record,
                        execution_baseline=execution_baseline,
                        reason="replay_cleanup_exception",
                        error=cleanup_error,
                    )
                if invalidation.get("invalidated_snapshots"):
                    target_record = (
                        matching_record
                        if matching_record is not None
                        else child_execution_records[-1]
                    )
                    target_record[
                        "snapshot_provenance_invalidated_snapshots"
                    ] = int(invalidation["invalidated_snapshots"])
                child_execution_interventions["replay_cleanup_exception"] += 1
            return result

        probe_lease_errors: List[BaseException] = []
        with managed_isr_emulator_safe(probe_lease_errors) as probe_lease:
            if probe_lease is None:
                probe_error = str(probe_lease_errors[0])[:512] if probe_lease_errors else "lease unavailable"
                _probe_emulator = None
                _probe_mmio = None
                probe_explorer = None
            else:
                try:
                    _probe_emulator, _probe_mmio, probe_explorer = configure_isr_emulator(probe_lease)
                    learned_irq_candidates = [
                        dict(item) for item in probe_explorer.learned_irq_candidates(limit=128)
                    ]
                    probe_isr_addresses = dict(probe_explorer.isr_addresses)
                except Exception as exc:
                    probe_error = f"{type(exc).__name__}: {str(exc)[:512]}"
                    _probe_emulator = None
                    _probe_mmio = None
                    probe_explorer = None
                    logger.debug("ISR reservoir probe setup failed: %s", exc)
        if probe_lease is not None and probe_lease_errors:
            cleanup_errors = [
                str(error)[:512] for error in probe_lease_errors
            ]
            probe_error = (
                f"{probe_error}; probe_cleanup_exception: {cleanup_errors[-1]}"
                if probe_error
                else f"probe_cleanup_exception: {cleanup_errors[-1]}"
            )
        del _probe_emulator, _probe_mmio, probe_explorer, probe_lease
        learned_irq_priority = {
            int(item["irq"]): int(item.get("score", 0) or 0)
            for item in learned_irq_candidates
        }

        for snapshot in context_items:
            if budget_exhausted():
                break
            if snapshot is not None:
                context_attempts += 1

            known_isr_coverage = self.global_coverage | phase_covered
            isr_items = self._prioritized_isr_items(
                probe_isr_addresses.items(),
                coverage=known_isr_coverage,
                target_bbs=target_bb_set if prioritize_target_bbs else None,
                max_isrs=max_isrs,
                irq_priority=learned_irq_priority,
            )

            for irq_num, isr_addr in isr_items:
                if budget_exhausted():
                    break

                baseline_covered, baseline_events, baseline_snapshots, _, isr_started, runtime_edges_added = execute_isr(
                    irq_num,
                    isr_addr,
                    snapshot=snapshot,
                )
                if not isr_started:
                    continue
                baseline_isrs += 1
                phase_covered.update(baseline_covered)
                self._record_coverage_evidence(EVIDENCE_E3, baseline_covered)
                remembered_branch_events += self._remember_main_branch_events(
                    baseline_events,
                    evidence_class=EVIDENCE_E3,
                )
                remembered_branch_root_snapshots += self._remember_branch_root_snapshots(
                    baseline_events,
                    baseline_snapshots,
                    evidence_class=EVIDENCE_E3,
                )
                dynamic_successor_edges_added += self._record_dynamic_successors(baseline_events)
                dynamic_successor_edges_added += runtime_edges_added
                events = compact_events(baseline_events)
                if not events:
                    continue
                isr_with_branches += 1

                event_by_key = {event_key(event): event for event in events}
                event_depth = {event_key(event): getattr(event, "depth", 0) for event in events}
                task_queue = deque()
                pending_paths = set()
                explored_paths = set()
                incomplete_paths = set()
                root_task_items = []
                known_root_coverage = self.global_coverage | phase_covered

                for root_event in reversed(events):
                    root_key = event_key(root_event)
                    for root_choice in choice_values(root_event):
                        successor = choice_successor_bb(root_event, root_choice)
                        if not successor_should_expand(successor, known_root_coverage):
                            continue
                        choices = {root_key: root_choice}
                        signature = path_key(choices)
                        if prioritize_target_bbs and target_bb_set:
                            root_task_items.append((
                                successor_priority(successor, known_root_coverage, is_switch_event(root_event)),
                                root_key,
                                choices,
                                signature,
                            ))
                        else:
                            task_queue.append((root_key, choices))
                            pending_paths.add(signature)
                if prioritize_target_bbs and target_bb_set:
                    for _priority, root_key, choices, signature in sorted(root_task_items, key=lambda item: item[0], reverse=True):
                        task_queue.append((root_key, choices))
                        pending_paths.add(signature)

                isr_tasks = 0
                while task_queue and not budget_exhausted():
                    if max_tasks_per_isr and max_tasks_per_isr > 0 and isr_tasks >= max_tasks_per_isr:
                        break

                    _root_key, choices = task_queue.popleft()
                    signature = path_key(choices)
                    pending_paths.discard(signature)
                    if signature in explored_paths or signature in incomplete_paths:
                        continue

                    known_before = self.global_coverage | phase_covered
                    covered, discovered, discovered_snapshots, branch_trace, isr_started, runtime_edges_added = execute_isr(
                        irq_num,
                        isr_addr,
                        choices,
                        event_depth,
                        snapshot=snapshot,
                    )
                    if not isr_started:
                        continue
                    task_new_bbs = covered - known_before
                    task_new_targets = task_new_bbs & target_bb_set
                    phase_covered.update(covered)
                    self._record_coverage_evidence(EVIDENCE_E3, covered)
                    remembered_branch_events += self._remember_main_branch_events(
                        discovered,
                        evidence_class=EVIDENCE_E3,
                    )
                    remembered_branch_root_snapshots += self._remember_branch_root_snapshots(
                        discovered,
                        discovered_snapshots,
                        source_path_signature=path_key(choices),
                        evidence_class=EVIDENCE_E3,
                    )
                    dynamic_successor_edges_added += self._record_dynamic_successors(discovered)
                    dynamic_successor_edges_added += runtime_edges_added
                    if task_new_targets:
                        target_hit_tasks += 1
                        target_bbs_discovered.update(task_new_targets)
                    tasks_run += 1
                    isr_tasks += 1

                    if branch_trace:
                        forced_hit_tasks += 1
                    else:
                        forced_missed_tasks += 1

                    if ordered_choices_hit(choices, branch_trace, event_depth):
                        full_hit_tasks += 1
                        explored_paths.add(signature)
                    else:
                        partial_hit_tasks += 1
                        incomplete_paths.add(signature)
                        continue

                    forced_addresses = {key[0] for key in choices}
                    known_after = known_before | task_new_bbs
                    deepest_choice_depth = max((event_depth.get(key, 0) for key in choices), default=0)
                    for child in reversed(compact_events(discovered)):
                        child_key = event_key(child)
                        event_by_key[child_key] = child
                        event_depth[child_key] = getattr(child, "depth", 0)
                        if child.address in forced_addresses or child_key in choices:
                            continue

                        observed_successor = observed_successor_bb(child)
                        branch_touches_target_scope = (
                            prioritize_target_bbs
                            and bool(target_bb_set)
                            and any(
                                static_target_potential(choice_successor_bb(child, child_choice), known_after) > 0
                                for child_choice in choice_values(child)
                            )
                        )
                        if not (
                            child.address in task_new_bbs
                            or (observed_successor is not None and observed_successor in task_new_bbs)
                            or branch_touches_target_scope
                        ):
                            continue

                        for child_choice in choice_values(child):
                            successor = choice_successor_bb(child, child_choice)
                            if not successor_should_expand(successor, known_after):
                                continue
                            child_choices = dict(choices)
                            child_choices[child_key] = child_choice
                            child_signature = path_key(child_choices)
                            if (
                                child_signature not in explored_paths
                                and child_signature not in incomplete_paths
                                and child_signature not in pending_paths
                            ):
                                task_queue.appendleft((event_key(child), child_choices))
                                pending_paths.add(child_signature)
                                child_tasks_enqueued += 1
                    if dynamic_frontier_seeding:
                        for child in reversed(compact_events(discovered)):
                            child_key = event_key(child)
                            child_depth = getattr(child, "depth", 0)
                            event_by_key[child_key] = child
                            event_depth[child_key] = child_depth
                            if child.address in forced_addresses or child_key in choices:
                                continue
                            if child_depth < deepest_choice_depth:
                                continue

                            for child_choice in choice_values(child):
                                successor = choice_successor_bb(child, child_choice)
                                if not successor_should_expand(successor, known_after):
                                    continue
                                child_choices = dict(choices)
                                child_choices[child_key] = child_choice
                                child_signature = path_key(child_choices)
                                if (
                                    child_signature not in explored_paths
                                    and child_signature not in incomplete_paths
                                    and child_signature not in pending_paths
                                ):
                                    task_queue.appendleft((event_key(child), child_choices))
                                    pending_paths.add(child_signature)
                                    child_tasks_enqueued += 1
                                    dynamic_frontier_tasks_enqueued += 1

        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation=(
                "entry_derived_context_snapshot_event_replay"
                if context_snapshots
                else "cold_vector_handler_direct_entry"
            ),
            context_snapshot_mode=bool(context_snapshots),
            child_execution_summary=self._child_execution_summary(
                child_execution_count,
                child_execution_interventions,
                expected_count=child_execution_count,
                execution_records=child_execution_records,
            ),
            baseline_isrs=baseline_isrs,
            isr_with_branches=isr_with_branches,
            reservoir_tasks_run=tasks_run,
            forced_hit_tasks=forced_hit_tasks,
            forced_missed_tasks=forced_missed_tasks,
            full_hit_tasks=full_hit_tasks,
            partial_hit_tasks=partial_hit_tasks,
            child_tasks_enqueued=child_tasks_enqueued,
            dynamic_frontier_tasks_enqueued=dynamic_frontier_tasks_enqueued,
            remembered_branch_events=remembered_branch_events,
            remembered_branch_root_snapshots=remembered_branch_root_snapshots,
            known_branch_root_snapshots=len(self.known_branch_root_snapshots),
            known_branch_root_snapshot_variants=self._known_branch_root_snapshot_variant_count(),
            dynamic_successor_edges_added=dynamic_successor_edges_added,
            dynamic_successor_edge_count=sum(len(successors) for successors in self.dynamic_successors.values()),
            target_bbs=len(target_bb_set),
            target_hit_tasks=target_hit_tasks,
            target_bbs_discovered=len(target_bbs_discovered),
            target_bbs_discovered_list=[f"0x{bb:08x}" for bb in sorted(target_bbs_discovered)[:256]],
            prioritize_target_bbs=prioritize_target_bbs,
            max_instructions=max_instructions,
            replay_timeout=replay_timeout,
            time_limit_seconds=time_limit_seconds,
            max_tasks=max_tasks,
            max_tasks_per_isr=max_tasks_per_isr,
            max_isrs=max_isrs,
            dynamic_frontier_seeding=dynamic_frontier_seeding,
            contexts_selected=len(contexts),
            context_attempts=context_attempts,
            include_reservoir_contexts=include_reservoir_contexts,
            reservoir_contexts_available=len(self.reservoir_interrupt_contexts),
            max_reservoir_contexts=max_reservoir_contexts,
            learned_irq_candidates=learned_irq_candidates[:32],
            learned_irq_candidate_count=len(learned_irq_candidates),
            isr_probe_error=probe_error,
            isr_stack=dict(isr_stack_stats),
            isr_execution_start=dict(isr_execution_start_stats),
            invalid_stack_samples=invalid_stack_samples[-32:],
        )

    def _branch_instruction(self, branch_bb_start: int) -> Optional[Dict[str, object]]:
        return self.prepared.get_branch_instruction(branch_bb_start)

    def _static_mmio_candidates(self, branch_pc: int, window: int) -> List[int]:
        candidates = []
        for access in self.result.mmio_accesses:
            if branch_pc - window < access.address < branch_pc and access.target_addr is not None:
                candidates.append(access.target_addr)
        return _dedupe_preserve_order(candidates)

    def _traced_mmio_candidates(self, branch_pc: int, window: int) -> List[int]:
        reads = self.register_tracer.get_recent_mmio_reads(64)
        candidates = [addr for pc, addr, _ in reads if branch_pc - window < pc < branch_pc]
        return _dedupe_preserve_order(candidates)

    def _dependency_mmio_candidates(self, branch_pc: int) -> List[int]:
        deps = self.register_tracer.analyze_branch_mmio_dependency(branch_pc)
        return _dedupe_preserve_order(deps["mmio_addresses"])

    def _dependency_constraint_candidates(self, branch_pc: int) -> List[BranchConstraintCandidate]:
        deps = self.register_tracer.analyze_branch_dependencies(branch_pc)
        candidates: List[BranchConstraintCandidate] = []
        seen = set()
        external_memory_addresses = set(
            getattr(self.emulator, "external_memory_input_addresses", set()) or set()
        )
        for item in deps.get("dependencies", []) or []:
            dep_type = str(item.get("type", "") or "").lower()
            if dep_type not in {"mmio", "memory"}:
                continue
            address = item.get("address")
            if address is None:
                continue
            read_pc = item.get("source_pc")
            try:
                read_pc = int(read_pc) if read_pc is not None else None
            except (TypeError, ValueError):
                read_pc = None
            if read_pc is not None and read_pc <= 0:
                read_pc = None
            read_occurrence = item.get("read_occurrence")
            if dep_type == "memory":
                consumer_pc = self._resolve_memory_consumer_read_pc(
                    int(branch_pc),
                    int(address),
                )
                if consumer_pc is not None:
                    read_pc = consumer_pc
            key = (
                dep_type,
                int(address),
                int(read_pc or 0),
                int(read_occurrence or 0),
                str(item.get("dependency_group") or ""),
            )
            if key in seen:
                continue
            seen.add(key)
            is_external_memory = (
                dep_type == "memory" and int(address) in external_memory_addresses
            )
            source_width = item.get("width")
            if source_width is None and item.get("size") is not None:
                try:
                    source_width = int(item.get("size")) * 8
                except (TypeError, ValueError):
                    source_width = None
            dependency_expression = str(item.get("expression") or "")
            if item.get("opaque_dependency"):
                dependency_expression = (
                    f"{dependency_expression};" if dependency_expression else ""
                ) + "opaque_dependency=true;causal_complete=false"
            candidates.append(
                BranchConstraintCandidate(
                    constraint_type=dep_type,
                    address=int(address),
                    value=0,
                    read_pc=int(read_pc) if read_pc is not None else None,
                    source="dependency",
                    read_occurrence=(
                        max(1, int(read_occurrence))
                        if read_occurrence is not None
                        else None
                    ),
                    input_kind=(
                        "mmio"
                        if dep_type == "mmio"
                        else "external_memory" if is_external_memory else "memory"
                    ),
                    externally_controllable=(
                        True
                        if dep_type == "mmio"
                        else is_external_memory
                    ),
                    dependency_register=(
                        str(item.get("register") or "").lower() or None
                    ),
                    dependency_expression=dependency_expression,
                    dependency_group=str(item.get("dependency_group") or ""),
                    composite_dependency=bool(item.get("composite", False)),
                    width=(int(source_width) if source_width is not None else None),
                ).normalized()
            )
        return candidates

    def _local_constraint_recovery_engine(self) -> LocalConstraintRecovery:
        engine = getattr(self, "local_constraint_recovery", None)
        if engine is None:
            engine = LocalConstraintRecovery(
                self.prepared.static_bbs,
                instruction_to_bb=self.prepared.instruction_to_bb,
                compare_lookup=self.prepared.compare_lookup,
                producer_index=getattr(self.prepared, "producer_index", None),
                solver_timeout_ms=_env_int("LSGEMU_LOCAL_SOLVER_TIMEOUT_MS", 40),
                generic_candidates=not self.constraint_guided_candidates_enabled,
            )
            self.local_constraint_recovery = engine
        return engine

    def _naturalization_dynamic_candidate_sets(
        self,
        branch_key: Tuple[int, int],
        expected_choice: object,
        *,
        max_models: int,
        avoid_values_by_site: Optional[Dict[Tuple[object, ...], Set[int]]] = None,
        baseline_values_by_site: Optional[Dict[Tuple[object, ...], int]] = None,
        source_prefix: str = "naturalization_dynamic_ssa",
    ) -> List[Tuple[BranchConstraintCandidate, ...]]:
        """Build one occurrence-scoped candidate set per dynamic SSA model."""
        if (
            not self._causal_constraint_recovery_available()
            or not isinstance(expected_choice, bool)
            or int(max_models) <= 0
        ):
            return []
        tracer = getattr(self, "register_tracer", None)
        if tracer is None or not hasattr(tracer, "recover_dynamic_branch_inputs"):
            return []
        branch_bb = int(branch_key[0]) & 0xFFFFFFFF
        occurrence = max(1, int(branch_key[1]))
        known_event = dict(
            getattr(self, "known_main_branch_events", {}) or {}
        ).get((branch_bb, occurrence))
        branch_instruction = self._branch_instruction(branch_bb) or {}
        branch_pc = int(
            branch_instruction.get("address")
            or getattr(known_event, "branch_pc", 0)
            or branch_bb
        )
        if branch_pc <= 0:
            return []

        started_at = time.perf_counter()
        # choke point 自解析补绑（方案 A3，round2 第 3 轮）：这里是生产上
        # 唯一向 tracer 提问的入口；默认臂（语义义务开启）的调用方
        # （自然化 bootstrap）从不绑定重放上下文，差分扰动二级定位此前
        # 永远 skipped_no_context。仅在外层（消融臂 generic_dynamic_fallback
        # 的显式绑定）未绑定时就地补绑——消融臂逐字节不变，无需重跑基线；
        # 无可用快照时绑 snapshot_entry=None，solver 自然走
        # skipped_no_context，与旧行为一致。
        probe_solver = getattr(self, "differential_probe_solver", None)
        probe_bound_here = False
        if (
            probe_solver is not None
            and not probe_solver.has_replay_context
        ):
            snapshot_entries = self._branch_snapshot_replay_entries(
                branch_bb,
                max_variants=3,
            )
            probe_solver.bind_replay_context(
                snapshot_entry=(
                    snapshot_entries[0] if snapshot_entries else None
                ),
                # branch_bb 与下方 tracer 请求的 branch_pc 同源（同一个
                # branch_instruction），结构上杜绝请求-上下文错配。
                branch_bb=branch_bb,
                take_branch=bool(expected_choice),
                desired_successor=self._branch_desired_successor_bb(
                    branch_instruction,
                    bool(expected_choice),
                ),
                # 与消融臂外层绑定的重放原语默认（run_mmio_branch_exploration
                # 签名默认 50000/1000000）保持一致：探针单次重放成本跨臂
                # 相同。自然化阶段的 120000 是 entry 重放参数，不适用于
                # 快照短重放；探针另有 timeout_ms deadline 兜底。
                replay_instructions=_env_int(
                    "LSGEMU_DIFF_PROBE_REPLAY_INSTRUCTIONS",
                    50_000,
                ),
                replay_timeout=_env_int(
                    "LSGEMU_DIFF_PROBE_REPLAY_TIMEOUT",
                    1_000_000,
                ),
            )
            probe_bound_here = True
        try:
            result = tracer.recover_dynamic_branch_inputs(
                branch_pc=branch_pc,
                occurrence=occurrence,
                target_taken=bool(expected_choice),
                max_models=max(1, int(max_models)),
                avoid_values_by_site=avoid_values_by_site,
                baseline_values_by_site=baseline_values_by_site,
            )
        finally:
            # 只清理自己绑定的上下文；外层（消融臂）绑定由其自身的
            # finally 负责，不越权清除。
            if probe_bound_here:
                probe_solver.clear_replay_context()
        self.last_dynamic_recovery_result = result
        self.last_dynamic_recovery_key = (branch_bb, occurrence)
        stats = getattr(self, "dynamic_constraint_recovery_stats", None)
        if stats is None:
            stats = Counter()
            self.dynamic_constraint_recovery_stats = stats
        stats["calls"] += 1
        stats["elapsed_seconds"] += max(0.0, time.perf_counter() - started_at)
        stats[f"reason_{result.reason}"] += 1
        stats[f"solver_backend_{result.solver_backend}"] += 1
        stats[f"solver_status_{getattr(result, 'solver_status', 'unknown')}"] += 1
        stats["solver_attempts"] += int(
            getattr(result, "solver_attempts", 1) or 1
        )
        stats["solver_escalations"] += int(
            bool(getattr(result, "escalated", False))
        )
        if getattr(result, "escalated", False):
            stats[
                f"solver_escalation_initial_{getattr(result, 'initial_solver_status', 'unknown')}"
            ] += 1
        stats[f"branch_record_match_{getattr(result, 'branch_record_match', 'none')}"] += 1
        stats["fallback_eligible_results"] += int(
            bool(getattr(result, "fallback_eligible", False))
        )
        stats["omitted_path_predicates"] += int(
            getattr(result, "omitted_path_predicates", 0) or 0
        )
        stats[f"relation_{result.relation_kind}"] += int(bool(result.models))
        stats["models"] += len(result.models)
        stats["target_inputs"] += int(result.target_inputs)
        stats["path_predicates"] += int(result.path_predicates)
        stats["slice_nodes"] += int(result.slice_nodes)

        candidate_sets: List[Tuple[BranchConstraintCandidate, ...]] = []
        for model_index, model in enumerate(result.models):
            dependency_group = (
                f"dynamic_ssa:0x{int(model.branch_pc) & 0xFFFFFFFF:08x}:"
                f"{int(model.branch_occurrence)}:{model_index}:"
                f"{model.relation_kind}"
            )
            candidates: List[BranchConstraintCandidate] = []
            seen_sites = set()
            for assignment in model.assignments:
                is_mmio = str(assignment.kind or "").lower() == "mmio"
                candidate = BranchConstraintCandidate(
                    constraint_type="mmio" if is_mmio else "memory",
                    address=int(assignment.address),
                    value=int(assignment.value),
                    read_pc=int(assignment.read_pc),
                    constraint_pc=self._constraint_compare_pc(branch_pc),
                    source=(
                        f"{str(source_prefix or 'dynamic_ssa')}:{model.strategy}:"
                        f"{model.relation_kind}"
                    ),
                    read_occurrence=(
                        # None = pc 级/全出现语义（差分扰动见证）：走
                        # add_pc_constraint 覆盖该读点全部出现，与探测
                        # 强制范围一致；整数 occurrence 照旧按出现次序。
                        None
                        if assignment.occurrence is None
                        else max(1, int(assignment.occurrence))
                    ),
                    input_kind="mmio" if is_mmio else "external_memory",
                    externally_controllable=True,
                    dependency_expression=(
                        f"dynamic_trace_nodes={int(model.slice_nodes)};"
                        f"path_predicates={int(model.path_predicates)};"
                        f"width={int(assignment.width)};"
                        f"trace_event_id={int(getattr(assignment, 'trace_event_id', 0) or 0)};"
                        f"solver_status={str(getattr(model, 'solver_status', 'sat'))};"
                        f"causal_complete={bool(getattr(model, 'causal_complete', True))};"
                        f"omitted_path_predicates={int(getattr(model, 'omitted_path_predicates', 0) or 0)};"
                        f"branch_record_match={str(getattr(model, 'branch_record_match', 'exact'))}"
                    ),
                    dependency_group=dependency_group,
                    composite_dependency=len(model.assignments) > 1,
                    width=int(assignment.width),
                ).normalized()
                site = constraint_site_identity(candidate)
                if site in seen_sites:
                    continue
                seen_sites.add(site)
                candidates.append(candidate)
            if not candidates:
                continue
            candidate_sets.append(tuple(candidates))
            stats["assignments"] += len(candidates)
            stats["changed_assignments"] += sum(
                int(int(assignment.value) != int(assignment.observed_value))
                for assignment in model.assignments
            )
            stats["baseline_corrections"] += int(
                getattr(model, "baseline_corrections", 0) or 0
            )
            if len(candidates) > 1:
                stats["compound_models"] += 1
        return candidate_sets

    def _naturalization_observed_values(
        self,
        candidate: BranchConstraintCandidate,
        *,
        limit: int = 8,
    ) -> List[int]:
        normalized = candidate.normalized()
        if normalized.constraint_type != "mmio":
            return []
        values: List[int] = []
        histories = [
            list(getattr(getattr(self, "register_tracer", None), "mmio_history", []) or []),
            list(getattr(getattr(self, "mmio_handler", None), "access_history", []) or []),
        ]
        for history in histories:
            for item in reversed(history):
                if not isinstance(item, (tuple, list)) or len(item) < 4:
                    continue
                pc, address, value, is_read = item[:4]
                if not is_read or int(address) != int(normalized.address):
                    continue
                if normalized.read_pc is not None and int(pc) != int(normalized.read_pc):
                    continue
                normalized_value = int(value) & 0xFFFFFFFF
                if normalized_value not in values:
                    values.append(normalized_value)
                if len(values) >= max(1, int(limit)):
                    return values
        return values

    def _align_read_occurrence_to_branch(
        self,
        candidate: BranchConstraintCandidate,
        branch_bb: int,
        branch_occurrence: object,
    ) -> Optional[BranchConstraintCandidate]:
        """Rebind a same-BB read occurrence to the branch occurrence it feeds.

        A basic block is straight-line with a single exit, so its load executes
        exactly once per block execution: read occurrence k feeds branch
        occurrence k.  Dependency tracing otherwise reports loop-depth
        occurrences (85..100 inside a spin loop) whose scoped constraints never
        touch the read the flip task targets; a None occurrence degrades to a
        pc-wide constraint that also perturbs earlier iterations (breaking the
        prefix for occurrence>1 targets).  Cross-BB reads are left untouched —
        their occurrence alignment needs path counting this module does not do.
        """
        if candidate is None or candidate.constraint_type != "mmio":
            return None
        if candidate.read_pc is None:
            return None
        try:
            read_bb = self.prepared.instruction_to_bb.get(int(candidate.read_pc))
        except (AttributeError, TypeError, ValueError):
            return None
        if read_bb is None or int(read_bb) != (int(branch_bb) & 0xFFFFFFFF):
            return None
        try:
            occurrence = max(1, int(branch_occurrence or 1))
        except (TypeError, ValueError):
            return None
        if candidate.read_occurrence is not None and (
            int(candidate.read_occurrence) == occurrence
        ):
            return None
        return dataclass_replace(
            candidate, read_occurrence=occurrence
        ).normalized()

    def _naturalization_bootstrap_candidates(
        self,
        branch_key: Tuple[int, int],
        expected_choice: object,
        *,
        max_candidates: int = 4,
        max_values_per_source: int = 4,
        avoid_values_by_site: Optional[Dict[Tuple[object, ...], Set[int]]] = None,
    ) -> List[BranchConstraintCandidate]:
        """Infer external-input candidates for the first unmatched path edge.

        These candidates are hypotheses only.  They become reusable facts only
        after a paired, force-free entry replay consumes the candidate and
        advances the exact dynamic path prefix.
        """
        branch_bb = int(branch_key[0]) & 0xFFFFFFFF
        known_event = self.known_main_branch_events.get(
            (branch_bb, max(1, int(branch_key[1])))
        )
        branch_instruction = self._branch_instruction(branch_bb) or {}
        branch_pc = int(
            branch_instruction.get("address")
            or getattr(known_event, "branch_pc", 0)
            or branch_bb
        )
        branch_condition = str(
            branch_instruction.get("mnemonic")
            or getattr(known_event, "condition", "")
            or ""
        ).upper()
        if branch_pc <= 0 or not branch_condition:
            return []

        base_candidates = list(self._dependency_constraint_candidates(branch_pc))
        if not base_candidates:
            sources = self._mmio_candidate_sources(branch_pc, candidate_window=128)
            if sources.get("skip_branch_mmio"):
                return []
            precise_read_pcs = dict(sources.get("precise_read_pcs", {}) or {})
            addresses = _dedupe_preserve_order(
                list(sources.get("precise_static", []) or [])
                + list(sources.get("dependency", []) or [])
                + list(sources.get("traced", []) or [])
                + list(sources.get("static", []) or [])
            )
            for address in addresses:
                read_pc = precise_read_pcs.get(int(address))
                if read_pc is None:
                    read_pc = self._find_constraint_read_pc(
                        branch_pc,
                        int(address),
                        128,
                    )
                if read_pc is None:
                    continue
                base_candidates.append(
                    BranchConstraintCandidate(
                        constraint_type="mmio",
                        address=int(address),
                        value=0,
                        read_pc=int(read_pc),
                        constraint_pc=self._constraint_compare_pc(branch_pc),
                        source="naturalization_static_dependency",
                        input_kind="mmio",
                        externally_controllable=True,
                    ).normalized()
                )

        source_limit = max(1, int(max_candidates))
        value_limit = max(1, int(max_values_per_source))
        base_candidates.sort(
            key=lambda candidate: (
                1 if candidate.read_occurrence is not None else 0,
                1 if candidate.read_pc is not None else 0,
                1 if candidate.composite_dependency else 0,
                *self._candidate_dependency_priority(candidate),
            ),
            reverse=True,
        )
        per_source: List[List[BranchConstraintCandidate]] = []
        seen_sites = set()
        for base in base_candidates:
            normalized_base = self._normalize_constraint_candidate(base)
            if normalized_base is None or not normalized_base.is_environment_fact:
                continue
            # r16：同 BB 读的发生号与分支事件发生号 1:1（BB 直线单出口，每执行
            # 一次恰好读一次）——依赖追踪在自旋环深处拿到的 read_occurrence
            # （如 85..100）会把 occurrence 级约束打到环深处那次读上，而翻转
            # 任务针对的是分支 occ=K 的那次执行；不对齐则值永远喂不到目标读。
            aligned_base = self._align_read_occurrence_to_branch(
                normalized_base, branch_bb, branch_key[1]
            )
            if aligned_base is not None:
                normalized_base = aligned_base
            site_identity = constraint_site_identity(normalized_base)
            if site_identity in seen_sites:
                continue
            seen_sites.add(site_identity)
            if len(per_source) >= source_limit:
                break
            inferred_value: Optional[int] = None
            if isinstance(expected_choice, bool):
                if normalized_base.constraint_type == "mmio":
                    inferred_value = self.llm_guide.infer_rule_constraint(
                        branch_pc,
                        branch_condition,
                        bool(expected_choice),
                        normalized_base.address,
                    )
                elif normalized_base.constraint_type == "memory":
                    inferred_value = self._infer_memory_constraint_value(
                        branch_pc,
                        branch_condition,
                        bool(expected_choice),
                        normalized_base,
                    )
            elif isinstance(expected_choice, int):
                # TBB/TBH choices are table indices; indirect dispatch choices
                # are concrete targets.  Applying the observed desired value is
                # only a hypothesis, and exact path replay remains the gate.
                inferred_value = int(expected_choice)
            if inferred_value is None:
                continue
            if isinstance(expected_choice, bool):
                recovery_started = time.perf_counter()
                recovery = self._local_constraint_recovery_engine().recover_values(
                    branch_pc=branch_pc,
                    branch_condition=branch_condition,
                    target_direction=bool(expected_choice),
                    read_pc=normalized_base.read_pc,
                    primary_values=(int(inferred_value),),
                    observed_values=self._naturalization_observed_values(normalized_base),
                    avoid_values=(avoid_values_by_site or {}).get(site_identity, set()),
                    max_values=value_limit,
                    compare_partner_values=self._compare_partner_constants(branch_pc),
                )
                recovery_stats = getattr(
                    self,
                    "local_constraint_recovery_stats",
                    None,
                )
                if recovery_stats is None:
                    recovery_stats = Counter()
                    self.local_constraint_recovery_stats = recovery_stats
                recovery_stats["calls"] += 1
                recovery_stats["elapsed_seconds"] += max(
                    0.0,
                    time.perf_counter() - recovery_started,
                )
                # r42：候选生成模式审计位（constraint_guided / generic），
                # 供报告四指标块按臂分账。
                recovery_stats[
                    f"candidate_generation_mode_{recovery.candidate_generation_mode}"
                ] += 1
                recovery_stats["symbolic_slices"] += int(
                    recovery.symbolic_slice
                )
                recovery_stats[
                    f"solver_backend_{recovery.solver_backend}"
                ] += 1
                recovery_stats["hypotheses"] += len(recovery.hypotheses)
                recovery_stats["smt_hypotheses"] += sum(
                    1 for item in recovery.hypotheses
                    if str(item.strategy).startswith("smt_")
                )
                value_hypotheses = list(recovery.hypotheses)
            else:
                value_hypotheses = [
                    SimpleNamespace(
                        value=int(inferred_value) & 0xFFFFFFFF,
                        strategy="dispatch_choice",
                    )
                ]

            source_candidates: List[BranchConstraintCandidate] = []
            seen_values = set()
            for hypothesis in value_hypotheses:
                value = int(hypothesis.value) & 0xFFFFFFFF
                if value in seen_values:
                    continue
                seen_values.add(value)
                source_candidates.append(
                    BranchConstraintCandidate(
                        constraint_type=normalized_base.constraint_type,
                        address=normalized_base.address,
                        value=value,
                        read_pc=normalized_base.read_pc,
                        constraint_pc=(
                            normalized_base.constraint_pc
                            if normalized_base.constraint_pc is not None
                            else self._constraint_compare_pc(branch_pc)
                        ),
                        source=(
                            "naturalization_bootstrap:"
                            f"{normalized_base.source or 'dependency'}:"
                            f"{hypothesis.strategy}"
                        ),
                        read_occurrence=normalized_base.read_occurrence,
                        input_kind=normalized_base.input_kind,
                        externally_controllable=normalized_base.externally_controllable,
                        dependency_register=normalized_base.dependency_register,
                        dependency_expression=normalized_base.dependency_expression,
                        dependency_group=normalized_base.dependency_group,
                        composite_dependency=normalized_base.composite_dependency,
                        width=normalized_base.width,
                    ).normalized()
                )
            if source_candidates:
                per_source.append(source_candidates)

        # Round-robin ordering gives every causal source one primary candidate
        # before spending replay budget on alternative values for the first one.
        built: List[BranchConstraintCandidate] = []
        for value_index in range(value_limit):
            for source_candidates in per_source:
                if value_index < len(source_candidates):
                    built.append(source_candidates[value_index])
        return built

    def _naturalization_bootstrap_candidate_sets(
        self,
        branch_key: Tuple[int, int],
        expected_choice: object,
        *,
        max_sources: int,
        max_values_per_source: int,
        max_compound_candidates: int,
        avoid_values_by_site: Optional[Dict[Tuple[object, ...], Set[int]]] = None,
        baseline_values_by_site: Optional[Dict[Tuple[object, ...], int]] = None,
    ) -> List[Tuple[BranchConstraintCandidate, ...]]:
        dynamic_candidate_sets = self._naturalization_dynamic_candidate_sets(
            branch_key,
            expected_choice,
            max_models=max(0, int(max_compound_candidates)),
            avoid_values_by_site=avoid_values_by_site,
            baseline_values_by_site=baseline_values_by_site,
        )
        candidates = self._naturalization_bootstrap_candidates(
            branch_key,
            expected_choice,
            max_candidates=max(1, int(max_sources)),
            max_values_per_source=max(1, int(max_values_per_source)),
            avoid_values_by_site=avoid_values_by_site,
        )
        by_site: Dict[Tuple[object, ...], List[BranchConstraintCandidate]] = {}
        site_order: List[Tuple[object, ...]] = []
        for candidate in candidates:
            site = constraint_site_identity(candidate)
            if site not in by_site:
                by_site[site] = []
                site_order.append(site)
            by_site[site].append(candidate)

        candidate_sets: List[Tuple[BranchConstraintCandidate, ...]] = []
        seen_sets = set()

        def remember(items: Iterable[BranchConstraintCandidate]) -> None:
            normalized = tuple(candidate.normalized() for candidate in items)
            signature = self._constraint_items_signature(normalized)
            if not normalized or signature in seen_sets:
                return
            seen_sets.add(signature)
            candidate_sets.append(normalized)

        # Joint dynamic models are complete assignments, so keep each model as
        # one indivisible replay candidate before scalar fallback hypotheses.
        for dynamic_set in dynamic_candidate_sets:
            remember(dynamic_set)

        # Give every source one attempt before allocating more replay budget.
        for site in site_order:
            remember((by_site[site][0],))

        # Compound attempts are admitted only when runtime provenance explicitly
        # marked the dependencies as one composite expression.
        compound_limit = max(0, int(max_compound_candidates))
        composite_groups: Dict[str, List[Tuple[object, ...]]] = defaultdict(list)
        for site in site_order:
            primary = by_site[site][0]
            if primary.composite_dependency and primary.dependency_group:
                composite_groups[primary.dependency_group].append(site)
        compound_count = 0
        eligible_compound_groups: List[List[Tuple[object, ...]]] = []
        for group_sites in composite_groups.values():
            distinct_sites = list(dict.fromkeys(group_sites))
            if len(distinct_sites) < 2 or compound_count >= compound_limit:
                continue
            eligible_compound_groups.append(distinct_sites)
            remember(tuple(by_site[site][0] for site in distinct_sites))
            compound_count += 1

        # The second value is the common C2 -> C3 retry and therefore precedes
        # lower-ranked Cartesian combinations.
        if max(1, int(max_values_per_source)) >= 2:
            for site in site_order:
                if len(by_site[site]) >= 2:
                    remember((by_site[site][1],))

        for distinct_sites in eligible_compound_groups:
            for replace_site in distinct_sites:
                if compound_count >= compound_limit or len(by_site[replace_site]) < 2:
                    break
                variant = [
                    by_site[site][1] if site == replace_site else by_site[site][0]
                    for site in distinct_sites
                ]
                remember(tuple(variant))
                compound_count += 1
            if (
                compound_count < compound_limit
                and all(len(by_site[site]) >= 2 for site in distinct_sites)
            ):
                remember(tuple(by_site[site][1] for site in distinct_sites))
                compound_count += 1

        for value_index in range(2, max(1, int(max_values_per_source))):
            for site in site_order:
                items = by_site[site]
                if value_index < len(items):
                    remember((items[value_index],))
        return candidate_sets

    def _resolve_memory_consumer_read_pc(self, branch_pc: int, memory_addr: int) -> Optional[int]:
        for snapshot_entry in self._branch_snapshot_replay_entries(int(branch_pc), max_variants=8):
            precise = self._snapshot_precise_memory_candidate(
                int(branch_pc),
                int(memory_addr),
                snapshot_entry,
            )
            if precise is not None:
                candidate_pc, _resolved_addr = precise
                return candidate_pc
        return None

    def _default_mmio_candidates(self, branch_index: int) -> List[int]:
        return [0x40000000 + (branch_index % 10) * 0x1000]

    def _mmio_candidate_sources(self, branch_pc: int, candidate_window: int) -> Dict[str, List[int]]:
        precise = self._precise_branch_mmio_analysis(branch_pc)
        dependency = self._dependency_mmio_candidates(branch_pc)
        dependency_constraints = self._dependency_constraint_candidates(branch_pc)
        traced = self._traced_mmio_candidates(branch_pc, candidate_window)
        static = self._static_mmio_candidates(branch_pc, candidate_window)
        precise_static = list(precise.get("candidates", []))
        fallback_merged = _dedupe_preserve_order(dependency + traced + static)
        merged = precise_static if precise_static else fallback_merged
        return {
            "precise_static": precise_static,
            "precise_read_pcs": dict(precise.get("read_pc_by_addr", {})),
            "skip_branch_mmio": bool(precise.get("skip_branch_mmio", False)),
            "skip_reason": precise.get("skip_reason"),
            "analysis": precise,
            "dependency": dependency,
            "dependency_constraints": dependency_constraints,
            "traced": traced,
            "static": static,
            "fallback_merged": fallback_merged,
            "merged": merged,
        }

    def _split_operands(self, operands: str) -> List[str]:
        parts: List[str] = []
        current: List[str] = []
        bracket_depth = 0
        for char in str(operands or ""):
            if char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)
            if char == "," and bracket_depth == 0:
                parts.append("".join(current).strip())
                current = []
            else:
                current.append(char)
        if current:
            parts.append("".join(current).strip())
        return parts

    def _reg_name(self, value: Optional[str]) -> Optional[str]:
        if value is None:
            return None
        match = re.match(r"^(r(?:1[0-5]|[0-9])|sp|lr|pc)\b", str(value).strip().lower())
        return match.group(1) if match else None

    def _parse_immediate(self, value: Optional[str]) -> Optional[int]:
        if value is None:
            return None
        text = str(value).strip().lstrip("#").lower()
        if not text:
            return None
        sign = -1 if text.startswith("-") else 1
        text = text[1:] if text.startswith(("-", "+")) else text
        try:
            parsed = int(text, 16) if text.startswith("0x") else int(text, 10)
            return sign * parsed
        except ValueError:
            return None

    def _candidate_dependency_priority(self, candidate: BranchConstraintCandidate) -> Tuple[int, int, int, int, int]:
        normalized = candidate.normalized()
        source = str(normalized.source or "")
        return (
            1 if normalized.constraint_type == "memory" else 0,
            1 if source.startswith("dependency") else 0,
            1 if normalized.read_pc is not None else 0,
            1 if normalized.constraint_pc is not None else 0,
            1 if source.endswith("snapshot") else 0,
        )

    def _branch_dependency_priority(self, item) -> Tuple[int, int, int, int, int, int]:
        sources = item[2]
        dependency_candidates = [
            candidate.normalized()
            for candidate in list(sources.get("dependency_constraints", []) or [])
            if isinstance(candidate, BranchConstraintCandidate)
        ]
        memory_count = sum(
            1
            for candidate in dependency_candidates
            if candidate.constraint_type == "memory"
        )
        dependency_count = len(dependency_candidates)
        mmio_dependency_count = sum(
            1
            for candidate in dependency_candidates
            if candidate.constraint_type == "mmio"
        )
        typed_dependency_count = memory_count + mmio_dependency_count
        precise_count = len(sources.get("precise_static", []) or [])
        provenance_count = len(item[4] or [])
        return (
            memory_count,
            typed_dependency_count,
            dependency_count,
            precise_count,
            provenance_count,
            len(sources.get("snapshot", []) or []),
        )

    def _operand_registers(self, operand_text: str) -> List[str]:
        registers = []
        for token in re.findall(r"\b(?:r(?:1[0-5]|[0-9])|sp|lr|pc)\b", str(operand_text or "").lower()):
            reg = self._reg_name(token)
            if reg and reg not in registers:
                registers.append(reg)
        return registers

    def _snapshot_register_value(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        reg_name: str,
    ) -> Optional[int]:
        snapshot = getattr(snapshot_entry, "snapshot", None)
        registers = getattr(snapshot, "registers", {}) if snapshot is not None else {}
        if not isinstance(registers, dict):
            return None
        value = registers.get(str(reg_name).lower())
        if value is None:
            return None
        try:
            return int(value) & 0xFFFFFFFF
        except Exception:
            return None

    def _resolve_snapshot_memory_operand(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        operand: str,
    ) -> Optional[int]:
        match = re.search(r"\[([^,\]]+)(?:,\s*([^\]]+))?\]", str(operand or ""))
        if not match:
            return None
        base_reg = self._reg_name(match.group(1))
        if base_reg is None:
            return None
        base_value = self._snapshot_register_value(snapshot_entry, base_reg)
        if base_value is None:
            return None
        offset = self._parse_immediate(match.group(2) or "#0")
        if offset is None:
            return None
        return (base_value + offset) & 0xFFFFFFFF

    def _snapshot_precise_memory_candidate(
        self,
        branch_pc: int,
        memory_addr: int,
        snapshot_entry: PrefixReplaySnapshot,
        lookback: int = 16,
    ) -> Optional[Tuple[int, int]]:
        bb_addr = self.prepared.instruction_to_bb.get(int(branch_pc))
        if bb_addr is None:
            return None
        instructions = self.prepared.static_bbs.get(bb_addr, [])
        if not instructions:
            return None
        compare_insn = (getattr(self.prepared, "compare_lookup", {}) or {}).get(int(branch_pc))
        if compare_insn is None:
            return None

        compare_index = None
        for idx, insn in enumerate(instructions):
            if int(insn.get("address", 0) or 0) == int(compare_insn.get("address", 0) or 0):
                compare_index = idx
                break
        if compare_index is None:
            return None

        compare_parts = self._split_operands(str(compare_insn.get("operands", "")))
        tracked_regs = set()
        for operand in compare_parts[:2]:
            tracked_regs.update(self._operand_registers(operand))
        if not tracked_regs:
            return None

        load_mnemonics = {"LDR", "LDR.W", "LDRB", "LDRH", "LDRSB", "LDRSH"}
        current_regs = set(tracked_regs)
        for insn in reversed(instructions[max(0, compare_index - lookback):compare_index]):
            parts = self._split_operands(str(insn.get("operands", "")))
            if not parts:
                continue
            dest_reg = self._reg_name(parts[0])
            if dest_reg is None or dest_reg not in current_regs:
                continue
            mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
            if mnemonic in load_mnemonics and len(parts) >= 2:
                addr = self._resolve_snapshot_memory_operand(snapshot_entry, parts[1])
                if addr is not None and int(addr) == int(memory_addr):
                    return int(insn.get("address", 0) or 0), int(addr)
                current_regs.discard(dest_reg)
                continue
            source_regs = []
            for operand in parts[1:]:
                source_regs.extend(self._operand_registers(operand))
            current_regs.discard(dest_reg)
            current_regs.update(source_regs)
            if not current_regs:
                break
        return None

    def _snapshot_precise_mmio_candidates(
        self,
        branch_pc: int,
        snapshot_entries: Iterable[PrefixReplaySnapshot],
        lookback: int = 12,
    ) -> List[int]:
        bb_addr = self.prepared.instruction_to_bb.get(int(branch_pc))
        if bb_addr is None:
            return []
        instructions = self.prepared.static_bbs.get(bb_addr, [])
        if not instructions:
            return []
        compare_insn = (getattr(self.prepared, "compare_lookup", {}) or {}).get(int(branch_pc))
        if compare_insn is None:
            return []

        compare_index = None
        for idx, insn in enumerate(instructions):
            if int(insn.get("address", 0) or 0) == int(compare_insn.get("address", 0) or 0):
                compare_index = idx
                break
        if compare_index is None:
            return []

        compare_parts = self._split_operands(str(compare_insn.get("operands", "")))
        if not compare_parts:
            return []
        tracked_regs = set(self._operand_registers(compare_parts[0]))
        if not tracked_regs:
            return []

        candidates: List[int] = []
        for snapshot_entry in snapshot_entries or []:
            current_regs = set(tracked_regs)
            for insn in reversed(instructions[max(0, compare_index - lookback):compare_index]):
                parts = self._split_operands(str(insn.get("operands", "")))
                if not parts:
                    continue
                dest_reg = self._reg_name(parts[0])
                if dest_reg is None or dest_reg not in current_regs:
                    continue
                mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
                if mnemonic in {"LDR", "LDR.W", "LDRB", "LDRH", "LDRSB", "LDRSH"} and len(parts) >= 2:
                    addr = self._resolve_snapshot_memory_operand(snapshot_entry, parts[1])
                    if addr is not None and 0x40000000 <= addr < 0x60000000:
                        candidates.append(addr)
                    current_regs.discard(dest_reg)
                    continue
                source_regs = []
                for operand in parts[1:]:
                    source_regs.extend(self._operand_registers(operand))
                current_regs.discard(dest_reg)
                current_regs.update(source_regs)
                if not current_regs:
                    break
        return _dedupe_preserve_order(candidates)

    def _load_firmware_segments(self) -> List[Tuple[int, bytes]]:
        if self.firmware_load_segments is not None:
            return self.firmware_load_segments

        segments: List[Tuple[int, bytes]] = []
        try:
            from elftools.elf.elffile import ELFFile

            with open(self.prepared.firmware_path, "rb") as f:
                elf = ELFFile(f)
                for segment in elf.iter_segments():
                    if segment["p_type"] == "PT_LOAD":
                        data = bytes(segment.data())
                        vaddr = int(segment["p_vaddr"])
                        paddr = int(segment["p_paddr"])
                        segments.append((vaddr, data))
                        if data and paddr and paddr != vaddr:
                            segments.append((paddr, data))
        except Exception:
            segments = []

        self.firmware_load_segments = segments
        return segments

    def _load_firmware_segment_meta(self) -> List[Dict[str, int]]:
        if self.firmware_load_segment_meta is not None:
            return self.firmware_load_segment_meta

        meta: List[Dict[str, int]] = []
        try:
            from elftools.elf.elffile import ELFFile

            with open(self.prepared.firmware_path, "rb") as f:
                elf = ELFFile(f)
                for segment in elf.iter_segments():
                    if segment["p_type"] != "PT_LOAD":
                        continue
                    vaddr = int(segment["p_vaddr"])
                    filesz = int(segment["p_filesz"])
                    memsz = int(segment["p_memsz"])
                    if max(filesz, memsz) <= 0:
                        continue
                    meta.append({
                        "vaddr": vaddr,
                        "paddr": int(segment["p_paddr"]),
                        "filesz": filesz,
                        "memsz": memsz,
                        "flags": int(segment["p_flags"]),
                    })
        except Exception:
            meta = []
        self.firmware_load_segment_meta = meta
        return meta

    @staticmethod
    def _plausible_vector_sp(value: int) -> bool:
        value = int(value) & 0xFFFFFFFF
        if value & 0x3:
            return False
        return (
            0x1FFF0000 <= value < 0x30000000
            or 0x10000000 <= value < 0x11000000
        )

    def _code_address_ranges(self) -> List[Tuple[int, int]]:
        ranges: List[Tuple[int, int]] = []
        for segment in self._load_firmware_segment_meta():
            if not (int(segment.get("flags", 0)) & 0x1):
                continue
            start = int(segment["vaddr"])
            end = start + max(int(segment.get("filesz", 0)), int(segment.get("memsz", 0)))
            if end > start:
                ranges.append((start, end))
        if not ranges and self.prepared.static_bb_set:
            ranges.append((min(self.prepared.static_bb_set), max(self.prepared.static_bb_set) + 4))
        return ranges

    def _is_code_address(self, address: int) -> bool:
        target = int(address) & ~1
        if target in self.prepared.static_bb_set or target in self.prepared.instruction_to_bb:
            return True
        return any(start <= target < end for start, end in self._code_address_ranges())

    def _vector_table_base(self) -> int:
        if self.firmware_vector_table_base is not None:
            return self.firmware_vector_table_base

        candidates = [int(segment["vaddr"]) for segment in self._load_firmware_segment_meta()]
        entry_segment_start = None
        entry = int(self.prepared.entry_point) & ~1
        for segment in self._load_firmware_segment_meta():
            start = int(segment["vaddr"])
            end = start + max(int(segment.get("filesz", 0)), int(segment.get("memsz", 0)))
            if start <= entry < end:
                entry_segment_start = start
                break
        if entry_segment_start is not None:
            candidates.append(entry_segment_start)
        candidates.append(int(self.prepared.result.arch_info.base_addr))

        seen: Set[int] = set()
        for base in candidates:
            if base in seen:
                continue
            seen.add(base)
            initial_sp = self._read_firmware_word(base)
            reset = self._read_firmware_word(base + 4)
            if initial_sp is None or reset is None:
                continue
            if self._plausible_vector_sp(initial_sp) and self._is_code_address(reset):
                self.firmware_vector_table_base = int(base)
                return int(base)

        self.firmware_vector_table_base = int(self.prepared.result.arch_info.base_addr)
        return self.firmware_vector_table_base

    def _read_firmware_word(self, address: int) -> Optional[int]:
        target = int(address) & 0xFFFFFFFF
        for base, data in self._load_firmware_segments():
            offset = target - int(base)
            if 0 <= offset <= len(data) - 4:
                return int.from_bytes(data[offset:offset + 4], "little") & 0xFFFFFFFF
        return None

    def _resolve_static_memory_operand(
        self,
        operand: str,
        reg_values: Dict[str, int],
        pc_value: Optional[int] = None,
    ) -> Optional[int]:
        match = re.search(r"\[([^,\]]+)(?:,\s*([^\]]+))?\]", str(operand or ""))
        if not match:
            return None

        base_token = str(match.group(1) or "").strip()
        offset_token = str(match.group(2) or "#0").strip()
        base_reg = self._reg_name(base_token)
        if base_reg == "pc":
            # r11 ③：pc 相对字面量原先永远解析失败（reg_values 无 "pc"），
            # 精确扫描因此拿不到 `ldr rX,[pc,#imm]` 的常量基址。
            if pc_value is None:
                return None
            base_value = (int(pc_value) + 4) & ~3  # Thumb 字面量对齐规则
        elif base_reg is not None:
            base_value = reg_values.get(base_reg)
        else:
            base_value = self._parse_immediate(base_token)
        offset = self._parse_immediate(offset_token) if offset_token else 0
        if base_value is None or offset is None:
            return None
        return (int(base_value) + int(offset)) & 0xFFFFFFFF

    def _known_operand_value(
        self,
        operand: str,
        reg_values: Dict[str, int],
    ) -> Optional[int]:
        immediate = self._parse_immediate(operand)
        if immediate is not None:
            return immediate & 0xFFFFFFFF

        regs = self._operand_registers(operand)
        if len(regs) == 1:
            return reg_values.get(regs[0])
        return None

    def _precise_branch_mmio_analysis(
        self,
        branch_pc: int,
        lookback: int = 12,
    ) -> Dict[str, object]:
        cached = self.precise_branch_mmio_cache.get(int(branch_pc))
        if cached is not None:
            return cached

        analysis: Dict[str, object] = {
            "candidates": [],
            "read_pc_by_addr": {},
            "compare_registers": [],
            "constant_register_values": {},
            "pointer_compare": False,
            "skip_branch_mmio": False,
            "skip_reason": None,
        }

        bb_addr = self.prepared.instruction_to_bb.get(int(branch_pc))
        if bb_addr is None:
            self.precise_branch_mmio_cache[int(branch_pc)] = analysis
            return analysis

        instructions = self.prepared.static_bbs.get(bb_addr, [])
        if not instructions:
            self.precise_branch_mmio_cache[int(branch_pc)] = analysis
            return analysis
        compare_insn = (getattr(self.prepared, "compare_lookup", {}) or {}).get(int(branch_pc))
        compare_registers_hint: List[str] = []
        if compare_insn is None:
            # r11 ③：CBZ/CBNZ 与「移位/逻辑设 flags」分支原先从不进精确分析
            #（compare_lookup 只收 CMP/CMN/TST/TEQ），一律退化为窗口启发式——
            # 「MMIO 读后 cbz r0」这类最常见的外设分支模式全部漏掉。
            branch_insn = (
                instructions[-1]
                if int(instructions[-1].get("address", 0) or 0) == int(branch_pc)
                else None
            )
            fallback = self._precise_compare_fallback(branch_insn, instructions)
            if fallback is None:
                self.precise_branch_mmio_cache[int(branch_pc)] = analysis
                return analysis
            compare_insn, compare_registers_hint = fallback

        compare_index = None
        for idx, insn in enumerate(instructions):
            if int(insn.get("address", 0) or 0) == int(compare_insn.get("address", 0) or 0):
                compare_index = idx
                break
        cross_bb_producer = False
        cross_bb_count = 1
        if compare_index is None:
            # r19：产生者索引可给出跨 BB（all_covered）的最近产生者——其地址
            # 不在分支所在 BB。沿唯一前驱链把窗口拼长后在链内定位；定位
            # 不到（多前驱汇合等）保持旧行为（空分析，保守）。
            extended, extended_bbs = self._precise_extend_with_predecessors(
                bb_addr, list(instructions)
            )
            for idx, insn in enumerate(extended):
                if int(insn.get("address", 0) or 0) == int(compare_insn.get("address", 0) or 0):
                    compare_index = idx
                    instructions = extended
                    cross_bb_producer = True
                    cross_bb_count = extended_bbs
                    break
            if compare_index is None:
                self.precise_branch_mmio_cache[int(branch_pc)] = analysis
                return analysis

        scan_instructions = list(
            instructions[max(0, compare_index - lookback):compare_index]
        )
        scan_bb_count = cross_bb_count if cross_bb_producer else 1
        hint_regs = list(compare_registers_hint)
        if not hint_regs:
            for operand in self._split_operands(
                str(compare_insn.get("operands", ""))
            )[:2]:
                hint_regs.extend(self._operand_registers(operand))
        # r11 ③：跨 BB def-use——比较寄存器的定义可能在前驱 BB
        #（现场：chMtxLockS 的 `cmp r1,r5` 在 BB 头，两个 ldr 在上一 BB）。
        # 仅沿静态唯一前驱链回溯（≤3 BB / ≤96 条，确定性 ⇒ 可缓存）。
        # r19：跨 BB 产生者定位时窗口已含前驱链，不重复扩展。
        if hint_regs and not cross_bb_producer:
            scan_instructions, scan_bb_count = self._precise_extend_with_predecessors(
                bb_addr,
                scan_instructions,
                limit_bbs=3,
            )

        reg_values: Dict[str, int] = {}
        reg_sources: Dict[str, Dict[str, int]] = {}
        load_mnemonics = {"LDR", "LDR.W", "LDRB", "LDRH", "LDRSB", "LDRSH"}
        move_mnemonics = {
            "MOV", "MOVS", "MVN", "MVNS",
            "UXTB", "UXTH", "SXTB", "SXTH",
            "REV", "REV16", "REVSH",
        }
        propagate_mnemonics = {
            "ADD", "ADDS", "SUB", "SUBS",
            "AND", "ANDS", "ORR", "ORRS", "EOR", "EORS", "BIC", "BICS",
            "LSL", "LSLS", "LSR", "LSRS", "ASR", "ASRS",
        }

        for insn in scan_instructions:
            parts = self._split_operands(str(insn.get("operands", "")))
            if not parts:
                continue
            dest_reg = self._reg_name(parts[0])
            mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
            if mnemonic in {"BL", "BL.W", "BLX", "BLX.W"}:
                # r11 ③：AAPCS caller-saved 寄存器经调用后不可再信赖旧常量/来源。
                # 跨 BB 回溯后若不失效，前驱 BB 的 r0 常量会错误穿透一次 BL。
                call_pc = int(insn.get("address", 0) or 0)
                for clobbered in ("r0", "r1", "r2", "r3", "r12", "lr"):
                    reg_values.pop(clobbered, None)
                    reg_sources[clobbered] = {
                        "kind": "call_return",
                        "read_pc": call_pc,
                    }
                continue
            if dest_reg is None:
                continue

            def clear_dest() -> None:
                reg_values.pop(dest_reg, None)
                reg_sources.pop(dest_reg, None)

            if mnemonic in load_mnemonics and len(parts) >= 2:
                effective_addr = self._resolve_static_memory_operand(
                    parts[1],
                    reg_values,
                    pc_value=int(insn.get("address", 0) or 0),
                )
                if effective_addr is None:
                    clear_dest()
                    continue
                if 0x40000000 <= effective_addr < 0x60000000:
                    reg_sources[dest_reg] = {
                        "kind": "mmio",
                        "addr": int(effective_addr),
                        "read_pc": int(insn.get("address", 0) or 0),
                    }
                    reg_values.pop(dest_reg, None)
                    continue

                if 0x10000000 <= effective_addr < 0x40000000:
                    # r11 ④：SRAM/CCM 载入记为 internal_ram（内核对象/堆状态），
                    # 只作锥分类证据，不产生外部输入候选。
                    reg_sources[dest_reg] = {
                        "kind": "internal_ram",
                        "addr": int(effective_addr),
                        "read_pc": int(insn.get("address", 0) or 0),
                    }
                    reg_values.pop(dest_reg, None)
                    continue

                literal_value = self._read_firmware_word(effective_addr)
                if literal_value is None:
                    clear_dest()
                    continue
                reg_values[dest_reg] = int(literal_value) & 0xFFFFFFFF
                reg_sources[dest_reg] = {
                    "kind": "const",
                    "addr": int(effective_addr),
                    "value": int(literal_value) & 0xFFFFFFFF,
                    "read_pc": int(insn.get("address", 0) or 0),
                }
                continue

            if mnemonic in move_mnemonics:
                source_regs = []
                if len(parts) >= 2:
                    source_regs = self._operand_registers(parts[1])
                source_value = self._known_operand_value(parts[1], reg_values) if len(parts) >= 2 else None
                if source_value is None:
                    reg_values.pop(dest_reg, None)
                else:
                    if mnemonic in {"MVN", "MVNS"}:
                        source_value = (~source_value) & 0xFFFFFFFF
                    reg_values[dest_reg] = int(source_value) & 0xFFFFFFFF
                if len(source_regs) == 1 and source_regs[0] in reg_sources:
                    reg_sources[dest_reg] = dict(reg_sources[source_regs[0]])
                elif len(source_regs) == 0 and source_value is not None:
                    reg_sources[dest_reg] = {
                        "kind": "const",
                        "value": int(reg_values[dest_reg]) & 0xFFFFFFFF,
                        "read_pc": int(insn.get("address", 0) or 0),
                    }
                else:
                    reg_sources.pop(dest_reg, None)
                continue

            if mnemonic in propagate_mnemonics:
                source_regs: List[str] = []
                for operand in parts[1:]:
                    source_regs.extend(self._operand_registers(operand))
                unique_sources = []
                for reg in source_regs:
                    if reg not in unique_sources:
                        unique_sources.append(reg)

                mmio_sources = []
                for reg in unique_sources:
                    source = reg_sources.get(reg)
                    if source and source.get("kind") == "mmio" and source.get("addr") is not None:
                        mmio_sources.append(source)
                if len({int(source["addr"]) for source in mmio_sources}) == 1 and mmio_sources:
                    reg_sources[dest_reg] = dict(mmio_sources[0])
                else:
                    reg_sources.pop(dest_reg, None)

                computed_value: Optional[int] = None
                if mnemonic in {"ADD", "ADDS", "SUB", "SUBS", "AND", "ANDS", "ORR", "ORRS", "EOR", "EORS", "BIC", "BICS"} and len(parts) >= 3:
                    left_value = self._known_operand_value(parts[1], reg_values)
                    right_value = self._known_operand_value(parts[2], reg_values)
                    if left_value is not None and right_value is not None:
                        if mnemonic in {"ADD", "ADDS"}:
                            computed_value = (left_value + right_value) & 0xFFFFFFFF
                        elif mnemonic in {"SUB", "SUBS"}:
                            computed_value = (left_value - right_value) & 0xFFFFFFFF
                        elif mnemonic in {"AND", "ANDS"}:
                            computed_value = (left_value & right_value) & 0xFFFFFFFF
                        elif mnemonic in {"ORR", "ORRS"}:
                            computed_value = (left_value | right_value) & 0xFFFFFFFF
                        elif mnemonic in {"EOR", "EORS"}:
                            computed_value = (left_value ^ right_value) & 0xFFFFFFFF
                        elif mnemonic in {"BIC", "BICS"}:
                            computed_value = (left_value & (~right_value & 0xFFFFFFFF)) & 0xFFFFFFFF
                elif mnemonic in {"LSL", "LSLS", "LSR", "LSRS", "ASR", "ASRS"} and len(parts) >= 3:
                    left_value = self._known_operand_value(parts[1], reg_values)
                    shift_value = self._known_operand_value(parts[2], reg_values)
                    if left_value is not None and shift_value is not None:
                        shift = int(shift_value) & 0x1F
                        if mnemonic in {"LSL", "LSLS"}:
                            computed_value = (left_value << shift) & 0xFFFFFFFF
                        elif mnemonic in {"LSR", "LSRS"}:
                            computed_value = (left_value >> shift) & 0xFFFFFFFF
                        else:
                            signed_left = left_value if left_value < 0x80000000 else left_value - 0x100000000
                            computed_value = (signed_left >> shift) & 0xFFFFFFFF

                if computed_value is None:
                    reg_values.pop(dest_reg, None)
                else:
                    reg_values[dest_reg] = int(computed_value) & 0xFFFFFFFF
                    if dest_reg not in reg_sources:
                        reg_sources[dest_reg] = {
                            "kind": "const",
                            "value": int(computed_value) & 0xFFFFFFFF,
                            "read_pc": int(insn.get("address", 0) or 0),
                        }
                continue

            clear_dest()

        compare_parts = self._split_operands(str(compare_insn.get("operands", "")))
        compare_registers: List[str] = []
        candidates: List[int] = []
        read_pc_by_addr: Dict[int, int] = {}
        peripheral_constants: List[int] = []

        for operand in compare_parts[:2]:
            regs = self._operand_registers(operand)
            compare_registers.extend(regs)
            immediate = self._parse_immediate(operand)
            if immediate is not None and self._precise_peripheral_compare_constant(immediate):
                peripheral_constants.append(immediate & 0xFFFFFFFF)
            for reg in regs:
                source = reg_sources.get(reg)
                reg_value = reg_values.get(reg)
                if reg_value is not None:
                    analysis["constant_register_values"][reg] = int(reg_value) & 0xFFFFFFFF
                    if self._precise_peripheral_compare_constant(int(reg_value)):
                        peripheral_constants.append(int(reg_value) & 0xFFFFFFFF)
                if not source:
                    continue
                if source.get("kind") == "mmio" and source.get("addr") is not None:
                    addr = int(source["addr"]) & 0xFFFFFFFF
                    candidates.append(addr)
                    read_pc_by_addr.setdefault(addr, int(source.get("read_pc", 0) or 0))

        analysis["compare_registers"] = compare_registers
        analysis["candidates"] = _dedupe_preserve_order(candidates)
        analysis["read_pc_by_addr"] = read_pc_by_addr

        # r11 ④：比较寄存器的锥终分类——mmio/const/internal_ram/call_return/
        # undefined_in_window。翻转账本据此区分「工具限制」的归因证据。
        cone_classification: Dict[str, str] = {}
        for reg in dict.fromkeys(compare_registers):
            source = reg_sources.get(reg)
            if source is not None:
                cone_classification[reg] = str(source.get("kind") or "unknown")
            elif reg_values.get(reg) is not None:
                cone_classification[reg] = "const"
            else:
                cone_classification[reg] = "undefined_in_window"
        analysis["cone_classification"] = cone_classification
        analysis["scan_bb_count"] = int(scan_bb_count)

        if not analysis["candidates"] and peripheral_constants:
            analysis["pointer_compare"] = True
            analysis["skip_branch_mmio"] = True
            analysis["skip_reason"] = "peripheral_pointer_compare"

        self.precise_branch_mmio_cache[int(branch_pc)] = analysis
        return analysis

    def _compare_partner_constants(self, branch_pc: int) -> List[int]:
        """r22：比较寄存器伙伴的静态常量（字面量池/常量链解析产物）。

        数据源就是 ``_precise_branch_mmio_analysis`` 的反向窗口常量传播
        （``ldr rX,[pc,#imm]`` 字面量装载与 mov/alu 常量链，同一套机制，
        已缓存）：``constant_register_values`` 只收窗口内静态解析得出的
        寄存器值，绝无猜测。寄存器-寄存器比较（如 ``cmp r2,r3`` 的 r3）
        拿到该常量后，值合成就有了物理可行的相等比较输入——r21a 诊断腿
        证明 0x081357ec 的翻转值正是字面量池里的 0x20006411。
        候选仍只是假设：必须走外部输入回填 + force-free 重放自证。
        """
        try:
            analysis = self._precise_branch_mmio_analysis(int(branch_pc))
        except Exception:
            return []
        constants = analysis.get("constant_register_values") or {}
        values: List[int] = []
        for reg in analysis.get("compare_registers") or ():
            value = constants.get(reg)
            if value is None:
                continue
            normalized = int(value) & 0xFFFFFFFF
            if normalized not in values:
                values.append(normalized)
        # r23：窗口内解析不到的比较寄存器常量，沿定义可达范围再试一次
        # （undefined_in_window 伙伴的定义常在更早的 BB；仍只收静态解析值）。
        for value in self._definition_reach_partner_constants(int(branch_pc)):
            if value not in values:
                values.append(value)
        return values

    def _definition_reach_partner_constants(self, branch_pc: int) -> List[int]:
        """r23：比较伙伴常量的定义可达范围扩展（有界、可缓存、无猜测）。

        r22 的窗口（lookback 12 + ≤3BB/96 条）对 undefined_in_window 的比较
        寄存器常解析不到常量——定义在更早。这里沿静态唯一前驱链扩到
        ``LSGEMU_PARTNER_REACH_BBS``（默认 12）BB / ≤512 条，用与
        ``_precise_branch_mmio_analysis`` 同一套常量传播规则重扫（字面量
        装载 / mov-alu 常量链 / BL 失效 r0-r3,r12,lr），只收比较寄存器
        的常量。唯一前驱链确定性 ⇒ 可缓存。解析不出就返回空——绝无猜测。
        """
        cached = getattr(self, "_partner_reach_cache", None)
        if cached is None:
            cached = {}
            self._partner_reach_cache = cached
        if int(branch_pc) in cached:
            return list(cached[int(branch_pc)])
        values: List[int] = []
        try:
            analysis = self._precise_branch_mmio_analysis(int(branch_pc))
            compare_regs = list(analysis.get("compare_registers") or ())
            if not compare_regs:
                cached[int(branch_pc)] = values
                return values
            constants = analysis.get("constant_register_values") or {}
            regs_left = [reg for reg in compare_regs if constants.get(reg) is None]
            if not regs_left:
                cached[int(branch_pc)] = values
                return values
            bb_addr = self.prepared.instruction_to_bb.get(int(branch_pc))
            instructions = list(self.prepared.static_bbs.get(bb_addr, []) or [])
            if not instructions:
                cached[int(branch_pc)] = values
                return values
            compare_insn = (getattr(self.prepared, "compare_lookup", {}) or {}).get(
                int(branch_pc)
            )
            if compare_insn is None:
                # 定位不到比较指令 → 常量状态取不到「比较时刻」，保守放弃。
                cached[int(branch_pc)] = values
                return values
            reach_bbs = _env_int("LSGEMU_PARTNER_REACH_BBS", 12)
            scan, _count = self._precise_extend_with_predecessors(
                bb_addr, list(instructions), limit_bbs=reach_bbs,
            )
            # 常量状态必须取「比较执行时刻」：比较之后的写不得污染伙伴常量
            # （cmp r2,r3; mov r3,#5; bne 的 r3≠5）。
            compare_addr = int(compare_insn.get("address", 0) or 0)
            cut = None
            for idx, insn in enumerate(scan):
                if int(insn.get("address", 0) or 0) == compare_addr:
                    cut = idx
                    break
            if cut is None:
                cached[int(branch_pc)] = values
                return values
            scan = scan[: cut + 1]
            if len(scan) > 512:
                scan = scan[-512:]
            reg_values: Dict[str, int] = {}
            load_mnemonics = {"LDR", "LDR.W", "LDRB", "LDRH", "LDRSB", "LDRSH"}
            move_mnemonics = {
                "MOV", "MOVS", "MVN", "MVNS",
                "UXTB", "UXTH", "SXTB", "SXTH",
                "REV", "REV16", "REVSH",
            }
            alu_mnemonics = {
                "ADD", "ADDS", "SUB", "SUBS",
                "AND", "ANDS", "ORR", "ORRS", "EOR", "EORS", "BIC", "BICS",
                "LSL", "LSLS", "LSR", "LSRS", "ASR", "ASRS",
            }
            for insn in scan:
                parts = self._split_operands(str(insn.get("operands", "")))
                if not parts:
                    continue
                mnemonic = _normalize_mnemonic(insn.get("mnemonic"))
                if mnemonic in {"BL", "BL.W", "BLX", "BLX.W"}:
                    for clobbered in ("r0", "r1", "r2", "r3", "r12", "lr"):
                        reg_values.pop(clobbered, None)
                    continue
                dest_reg = self._reg_name(parts[0])
                if dest_reg is None:
                    continue
                if mnemonic in load_mnemonics and len(parts) >= 2:
                    effective_addr = self._resolve_static_memory_operand(
                        parts[1],
                        reg_values,
                        pc_value=int(insn.get("address", 0) or 0),
                    )
                    literal = (
                        self._read_firmware_word(effective_addr)
                        if effective_addr is not None
                        and not (
                            0x40000000 <= effective_addr < 0x60000000
                            or 0x10000000 <= effective_addr < 0x40000000
                        )
                        else None
                    )
                    if literal is None:
                        reg_values.pop(dest_reg, None)
                    else:
                        reg_values[dest_reg] = int(literal) & 0xFFFFFFFF
                    continue
                if mnemonic in move_mnemonics:
                    source_value = (
                        self._known_operand_value(parts[1], reg_values)
                        if len(parts) >= 2 else None
                    )
                    if source_value is None:
                        reg_values.pop(dest_reg, None)
                    else:
                        if mnemonic in {"MVN", "MVNS"}:
                            source_value = (~int(source_value)) & 0xFFFFFFFF
                        reg_values[dest_reg] = int(source_value) & 0xFFFFFFFF
                    continue
                if mnemonic in alu_mnemonics and len(parts) >= 3:
                    left = self._known_operand_value(parts[1], reg_values)
                    right = self._known_operand_value(parts[2], reg_values)
                    if left is None or right is None:
                        reg_values.pop(dest_reg, None)
                        continue
                    left, right = int(left), int(right)
                    if mnemonic in {"ADD", "ADDS"}:
                        reg_values[dest_reg] = (left + right) & 0xFFFFFFFF
                    elif mnemonic in {"SUB", "SUBS"}:
                        reg_values[dest_reg] = (left - right) & 0xFFFFFFFF
                    elif mnemonic in {"AND", "ANDS"}:
                        reg_values[dest_reg] = left & right
                    elif mnemonic in {"ORR", "ORRS"}:
                        reg_values[dest_reg] = left | right
                    elif mnemonic in {"EOR", "EORS"}:
                        reg_values[dest_reg] = left ^ right
                    elif mnemonic in {"BIC", "BICS"}:
                        reg_values[dest_reg] = left & (~right & 0xFFFFFFFF)
                    elif mnemonic in {"LSL", "LSLS"}:
                        reg_values[dest_reg] = (left << (right & 0x1F)) & 0xFFFFFFFF
                    elif mnemonic in {"LSR", "LSRS"}:
                        reg_values[dest_reg] = left >> (right & 0x1F)
                    else:  # ASR/ASRS
                        signed = left if left < 0x80000000 else left - 0x100000000
                        reg_values[dest_reg] = (signed >> (right & 0x1F)) & 0xFFFFFFFF
                    continue
                reg_values.pop(dest_reg, None)
            for reg in regs_left:
                value = reg_values.get(reg)
                if value is None:
                    continue
                normalized = int(value) & 0xFFFFFFFF
                if normalized not in values:
                    values.append(normalized)
        except Exception:
            values = []
        cached[int(branch_pc)] = values
        return list(values)

    _PRECISE_FLAG_CONDITIONAL_MNEMONICS = frozenset(
        CONDITIONAL_BRANCH_MNEMONICS - {"CBZ", "CBNZ", "TBB", "TBH"}
    )
    _PRECISE_FLAG_SETTING_MNEMONICS = frozenset({
        "CMP", "CMN", "TST", "TEQ",
        "SUBS", "ADDS", "ANDS", "ORRS", "EORS", "BICS", "ORNS",
        "LSLS", "LSRS", "ASRS", "RSBS", "SBCS", "ADCS", "MOVS", "MOVNS", "MULS",
    })
    _PRECISE_S_FORM_THREE_OPERAND = frozenset({
        "SUBS", "ADDS", "ANDS", "ORRS", "EORS", "BICS", "ORNS",
        "LSLS", "LSRS", "ASRS", "RSBS", "SBCS", "ADCS", "MOVS", "MOVNS", "MULS",
    })

    def _instruction_at(self, pc: int) -> Optional[Dict[str, object]]:
        """按 pc 取指令字典：先 instruction_lookup，缺则走 BB 视图（shell 兼容）。"""
        pc = int(pc)
        insn = (getattr(self.prepared, "instruction_lookup", {}) or {}).get(pc)
        if insn is not None:
            return insn
        bb = (getattr(self.prepared, "instruction_to_bb", {}) or {}).get(pc)
        if bb is None:
            return None
        for candidate in (getattr(self.prepared, "static_bbs", {}) or {}).get(bb) or ():
            if int(candidate.get("address", 0) or 0) == pc:
                return candidate
        return None

    def _producer_index_fallback(
        self,
        branch_insn: Dict[str, object],
    ) -> Optional[Tuple[Dict[str, object], List[str]]]:
        """r19：NZCV 产生者索引命中的比较指令定位（窗口比 BB 内启发更准、跨 BB 可见）。

        返回 (最近产生者指令, 全部产生者的操作数寄存器并集)；标签站
        （label_fp_opaque/label_msr）与无产生者站返回 None（不产生候选）。
        """
        record = (getattr(self.prepared, "producer_index", None) or {}).get(
            int(branch_insn.get("address", 0) or 0)
        )
        if record is None:
            return None
        producers, paths, _calls_between = record
        if not producers or paths in {"label_fp_opaque", "label_msr"}:
            return None
        nearest = self._instruction_at(int(producers[0][0]))
        if nearest is None:
            return None
        compare_registers_hint: List[str] = []
        three_operand = {
            "SUBS", "ADDS", "ANDS", "ORRS", "EORS", "BICS", "ORNS",
            "LSLS", "LSRS", "ASRS", "RSBS", "SBCS", "ADCS", "MOVS", "MOVNS", "MULS",
        }
        for producer in producers:
            insn = self._instruction_at(int(producer[0]))
            if insn is None:
                continue
            parts = self._split_operands(str(insn.get("operands", "")))
            dest = self._reg_name(parts[0]) if parts else None
            for operand in parts[:3]:
                for reg in self._operand_registers(operand):
                    if reg not in compare_registers_hint:
                        compare_registers_hint.append(reg)
            if str(producer[1]) in three_operand and dest is not None:
                compare_registers_hint = [
                    reg for reg in compare_registers_hint if reg != dest
                ] or compare_registers_hint
        return dict(nearest), compare_registers_hint

    def _precise_compare_fallback(
        self,
        branch_insn: Optional[Dict[str, object]],
        instructions: List[Dict[str, object]],
    ) -> Optional[Tuple[Dict[str, object], List[str]]]:
        """compare_lookup 无命中时的比较指令回退（r11 ③；r19 接产生者索引）。

        - CBZ/CBNZ rX：分支自身即测试（等价 ``cmp rX, #0``），依赖寄存器=第一操作数。
        - Bcc：先查 producer_index（最近产生者 + 全产生者操作数并集，
          含跨 BB all_covered）；索引 miss 再退 BB 内向前最近设 flags 启发。
        返回 (compare_insn, 依赖寄存器提示)；找不到则 None（保持旧行为）。
        """
        if not branch_insn:
            return None
        mnemonic = _normalize_mnemonic(branch_insn.get("mnemonic"))
        if mnemonic in {"CBZ", "CBNZ"}:
            regs = self._operand_registers(str(branch_insn.get("operands", "")))
            if not regs:
                return None
            return dict(branch_insn), [regs[0]]
        if mnemonic not in self._PRECISE_FLAG_CONDITIONAL_MNEMONICS:
            # 仅条件 Bcc 依赖 flags；无条件 B/BX/POP 与 TBB/TBH 派发不适用。
            return None
        indexed = self._producer_index_fallback(branch_insn)
        if indexed is not None:
            return indexed
        branch_index = None
        for idx, insn in enumerate(instructions):
            if int(insn.get("address", 0) or 0) == int(
                branch_insn.get("address", 0) or 0
            ):
                branch_index = idx
                break
        if branch_index is None:
            return None
        for idx in range(branch_index - 1, -1, -1):
            candidate = instructions[idx]
            candidate_mnemonic = _normalize_mnemonic(candidate.get("mnemonic"))
            if candidate_mnemonic not in self._PRECISE_FLAG_SETTING_MNEMONICS:
                continue
            parts = self._split_operands(str(candidate.get("operands", "")))
            dest = self._reg_name(parts[0]) if parts else None
            regs: List[str] = []
            for operand in parts[:3]:
                for reg in self._operand_registers(operand):
                    if reg not in regs:
                        regs.append(reg)
            if (
                candidate_mnemonic in self._PRECISE_S_FORM_THREE_OPERAND
                and dest is not None
            ):
                regs = [reg for reg in regs if reg != dest] or regs
            return dict(candidate), regs
        return None

    # r14：IEEE754 单精度常见幅值带（1.0f ~ 999999.9f 的位模式区间）。
    # 数学库字面量常数（rem_pio2f 的 3π/4=0x4016cbe3 等）落在此带内且
    # 与外设区间 [0x40000000,0x60000000) 重叠，是误判的唯一观测来源。
    _PRECISE_FLOAT_BAND = (0x3F800000, 0x49742400)

    def _precise_peripheral_compare_constant(self, value: int) -> bool:
        """比较操作数能否视为外设地址常量（r14 收紧，仅用于 peripheral_constants）。

        旧口径是裸区间 ``0x40000000 <= v < 0x60000000``，会吞 IEEE754 常数：
        r14 探针实证 211 已执行分支的 3 个 peripheral_pointer_compare 否决
        全部是浮点常数（0x4016cbe3≈2.35619f=3π/4、0x43490f80≈201.06f、
        0x410fc241≈8.98f），无一是真指针比较。收紧规则：
        - 落在固件 PT_LOAD 段（.text/.rodata/字面量池）内的不是外设地址；
        - IEEE754 常见幅值带内未 0x100 对齐的按浮点常数处理——真实外设
          基址在 Cortex-M 上至少 0x100 对齐（本轮实证基址 0x40007000/
          0x40023800/0x40023c00 全部 0x400 对齐）。

        注意：只收紧「比较常量」路径；解引用有效地址（base+offset 的寄存器
        读，如 0x40007004=PWR_CSR）不套对齐规则，否则会误杀真候选。
        """
        candidate = int(value) & 0xFFFFFFFF
        if not (0x40000000 <= candidate < 0x60000000):
            return False
        for base, data in self._load_firmware_segments():
            if 0 <= candidate - int(base) < len(data):
                return False
        lo, hi = self._PRECISE_FLOAT_BAND
        if lo <= candidate < hi and candidate & 0xFF:
            return False
        return True

    def _precise_static_predecessors(self) -> Dict[int, List[int]]:
        """静态 BB 前驱表（static_successors 反转，懒构建缓存）。

        r14：排除 ``src == dst`` 的自环边。外设轮询环（如 ``bpl <自身 BB 头>``）
        的静态前驱={自身,入口}，唯一前驱判定永远失败，跨 BB def-use 扩展被
        整体拒收——即使 MMIO 读就在分支同 BB 内。自环边是回边不是到达路径：
        寄存器若非在本 BB 内定义，其定义必来自环外前驱，排除后沿唯一前驱
        扩展仍保持可靠（多来源语义不变，仍拒绝扩展）。
        """
        cached = getattr(self, "_precise_pred_map", None)
        if cached is not None:
            return cached
        preds: Dict[int, List[int]] = {}
        successors = getattr(self.prepared, "static_successors", {}) or {}
        for src, dsts in dict(successors).items():
            for dst in list(dsts or ()):
                if int(dst) == int(src):
                    continue
                preds.setdefault(int(dst), []).append(int(src))
        self._precise_pred_map = preds
        return preds

    def _precise_extend_with_predecessors(
        self,
        bb_addr: int,
        scan_instructions: List[Dict[str, object]],
        *,
        limit_bbs: int = 3,
    ) -> Tuple[List[Dict[str, object]], int]:
        """沿静态唯一前驱链向前扩展扫描窗口（r11 ③，跨 BB def-use）。

        只在唯一前驱时扩展（到达路径静态唯一 ⇒ 定义信息可靠）；限 ≤3 BB /
        ≥96 条即停，最长 160 条截断。确定性 ⇒ 结果可进 precise 缓存。
        r14：前驱表已排除自环边（见 _precise_static_predecessors），
        「自环 + 唯一入口」在此恢复为唯一前驱，可正常扩展。
        """
        scan = list(scan_instructions)
        count = 1
        current = int(bb_addr)
        preds = self._precise_static_predecessors()
        for _ in range(max(0, int(limit_bbs))):
            plist = preds.get(current) or []
            if len(plist) != 1:
                break
            pred = plist[0]
            pred_insns = list(self.prepared.static_bbs.get(pred, []) or [])
            if not pred_insns:
                break
            scan = pred_insns + scan
            count += 1
            current = pred
            if len(scan) >= 96:
                break
        if len(scan) > 160:
            scan = scan[-160:]
        return scan, count

    def _find_constraint_read_pc(
        self,
        branch_pc: int,
        mmio_addr: int,
        candidate_window: int,
    ) -> Optional[int]:
        precise = self._precise_branch_mmio_analysis(branch_pc)
        precise_read_pc = (precise.get("read_pc_by_addr", {}) or {}).get(int(mmio_addr))
        if precise_read_pc is not None:
            return int(precise_read_pc)

        compare_lookup = getattr(self.prepared, "compare_lookup", {}) or {}
        compare_insn = compare_lookup.get(int(branch_pc))
        if compare_insn is not None:
            snapshot_sources = self.register_tracer.branch_dependency_snapshots.get(int(branch_pc), [])
            for snapshot in reversed(snapshot_sources):
                for source in snapshot.get("register_sources", {}).values():
                    if int(source.get("mmio_address", 0) or 0) == int(mmio_addr):
                        source_pc = source.get("source_pc")
                        if source_pc:
                            return int(source_pc)

            operands = self._split_operands(str(compare_insn.get("operands", "")))
            for operand in operands[:2]:
                for reg in self._operand_registers(operand):
                    source = self.register_tracer.trace_register_back(reg)
                    if (
                        source is not None
                        and int(getattr(source, "mmio_address", 0) or 0) == int(mmio_addr)
                        and getattr(source, "source_pc", None) is not None
                    ):
                        return int(source.source_pc)

        for pc, address, _value, is_read in reversed(self.register_tracer.mmio_history):
            if not is_read or int(address) != int(mmio_addr):
                continue
            pc = int(pc)
            if branch_pc - candidate_window < pc < branch_pc:
                return pc

        best_pc = None
        for access in self.result.mmio_accesses:
            access_pc = int(getattr(access, "address", 0) or 0)
            target_addr = int(getattr(access, "target_addr", 0) or 0)
            if target_addr != int(mmio_addr):
                continue
            if branch_pc - candidate_window < access_pc < branch_pc:
                if best_pc is None or access_pc > best_pc:
                    best_pc = access_pc
        if best_pc is not None:
            return best_pc

        bb_addr = self.prepared.instruction_to_bb.get(int(branch_pc))
        if bb_addr is not None:
            instructions = self.prepared.static_bbs.get(bb_addr, [])
            if instructions and int(instructions[-1].get("address", 0) or 0) == int(branch_pc):
                try:
                    analyzer = StaticConstraintAnalyzer(self.prepared.static_bbs)
                    inferred = analyzer._analyze_basic_block(
                        instructions,
                        _normalize_mnemonic(instructions[-1].get("mnemonic")),
                    )
                except Exception:
                    inferred = None
                if inferred is not None:
                    read_source, _value, _constraint_pc, _reason = inferred
                    if int(read_source.mmio_addr) == int(mmio_addr):
                        return int(read_source.read_pc)
        return best_pc

    def _constraint_compare_pc(self, branch_pc: int) -> int:
        compare_lookup = getattr(self.prepared, "compare_lookup", {}) or {}
        compare_insn = compare_lookup.get(int(branch_pc))
        if compare_insn is not None:
            return int(compare_insn.get("address", branch_pc) or branch_pc)
        return int(branch_pc)

    def _infer_memory_constraint_value(
        self,
        branch_pc: int,
        branch_condition: str,
        target_direction: bool,
        candidate: BranchConstraintCandidate,
    ) -> Optional[int]:
        """
        Infer a concrete value for a memory-backed branch dependency.

        Unlike MMIO inference, this must satisfy the compare/test semantics of
        the RAM-backed value directly. Reusing a dummy MMIO address produces
        values that often validate locally but do not change the replayed path.
        """
        if candidate.read_pc is None:
            return None
        try:
            compare_insn = (getattr(self.prepared, "compare_lookup", {}) or {}).get(int(branch_pc))
            if compare_insn is None:
                return None
            branch_mnemonic = _normalize_mnemonic(branch_condition)
            compare_mnemonic = _normalize_mnemonic(compare_insn.get("mnemonic"))
            if branch_mnemonic == "CBZ":
                return 0 if target_direction else 1
            if branch_mnemonic == "CBNZ":
                return 1 if target_direction else 0

            if compare_mnemonic == "TST":
                bitmask = self.llm_guide._extract_bitmask(compare_insn)
                if bitmask is None:
                    return self.llm_guide._fallback_unknown_tst_value(
                        branch_mnemonic,
                        bool(target_direction),
                    )
                non_zero_value = self.llm_guide._least_significant_bit(bitmask)
                if branch_mnemonic == "BNE":
                    return _sanitize_u32(non_zero_value if target_direction else 0)
                if branch_mnemonic == "BEQ":
                    return _sanitize_u32(0 if target_direction else non_zero_value)
                return _sanitize_u32(non_zero_value if target_direction else 0)

            compare_value = self.llm_guide._extract_compare_value(compare_insn)
            if compare_mnemonic == "TEQ":
                if compare_value is None:
                    return _sanitize_u32(1 if target_direction else 0)
                compare_value &= 0xFFFFFFFF
                if branch_mnemonic == "BEQ":
                    return _sanitize_u32(compare_value if target_direction else (compare_value ^ 1))
                if branch_mnemonic == "BNE":
                    return _sanitize_u32((compare_value ^ 1) if target_direction else compare_value)
                return _sanitize_u32(compare_value if target_direction else (compare_value ^ 1))

            masked_compare = self.llm_guide._find_masked_register_compare(int(branch_pc), compare_insn)
            if masked_compare is not None:
                return _sanitize_u32(
                    self.llm_guide._infer_masked_register_compare_value(
                        masked_compare,
                        branch_mnemonic,
                        bool(target_direction),
                    )
                )

            if compare_value is None:
                compare_value = 0
            compare_value &= 0xFFFFFFFF
            compare_signed = _signed32(compare_value)

            if branch_mnemonic == "BEQ":
                value = compare_value if target_direction else ((compare_value + 1) & 0xFFFFFFFF)
            elif branch_mnemonic == "BNE":
                value = ((compare_value + 1) & 0xFFFFFFFF) if target_direction else compare_value
            elif branch_mnemonic == "BGT":
                value = ((compare_signed + 1) & 0xFFFFFFFF) if target_direction else compare_value
            elif branch_mnemonic == "BGE":
                value = compare_value if target_direction else ((compare_signed - 1) & 0xFFFFFFFF)
            elif branch_mnemonic == "BLT":
                value = ((compare_signed - 1) & 0xFFFFFFFF) if target_direction else compare_value
            elif branch_mnemonic == "BLE":
                value = compare_value if target_direction else ((compare_signed + 1) & 0xFFFFFFFF)
            elif branch_mnemonic == "BHI":
                value = ((compare_value + 1) & 0xFFFFFFFF) if target_direction else compare_value
            elif branch_mnemonic in {"BHS", "BCS"}:
                value = compare_value if target_direction else ((compare_value - 1) & 0xFFFFFFFF)
            elif branch_mnemonic in {"BLO", "BCC"}:
                value = ((compare_value - 1) & 0xFFFFFFFF) if target_direction else compare_value
            elif branch_mnemonic == "BLS":
                value = compare_value if target_direction else ((compare_value + 1) & 0xFFFFFFFF)
            else:
                value = 1 if target_direction else 0
            return _sanitize_u32(value)
        except Exception:
            return None

    def _persist_branch_mmio_constraint(
        self,
        read_pc: Optional[int],
        mmio_addr: int,
        value: int,
        constraint_pc: int,
        branch_pc: int,
        target_direction: bool,
        description: str,
        source: str = "",
        read_occurrence: Optional[int] = None,
    ) -> bool:
        if not self._scoped_replay_available():
            # A2 intentionally has no durable read-PC/occurrence scope. Its
            # global MMIO candidates live only for one paired replay task.
            return False
        if not self.constraint_file or read_pc is None:
            return False

        path = Path(self.constraint_file)
        try:
            if path.exists():
                with path.open("r") as f:
                    data = json.load(f)
            else:
                data = {"constraints": []}
        except Exception:
            data = {"constraints": []}

        if not isinstance(data, dict) or "constraints" not in data or not isinstance(data["constraints"], list):
            data = {"constraints": []}

        new_item = {
            "type": "mmio",
            "read_pc": f"0x{int(read_pc) & 0xFFFFFFFF:08x}",
            "address": f"0x{int(mmio_addr) & 0xFFFFFFFF:08x}",
            "value": f"0x{int(value) & 0xFFFFFFFF:08x}",
            "constraint_pc": f"0x{int(constraint_pc) & 0xFFFFFFFF:08x}",
            "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
            "target_direction": "taken" if target_direction else "not-taken",
            "description": description,
            "added_by": "branch_mmio",
            "source": str(source or "branch_mmio"),
        }
        if read_occurrence is not None:
            new_item["read_occurrence"] = max(1, int(read_occurrence))

        rewritten = []
        updated = False
        for item in data["constraints"]:
            same_read_site = (
                item.get("type") == new_item["type"]
                and item.get("address") == new_item["address"]
                and (item.get("read_pc") or item.get("pc")) == new_item["read_pc"]
                and int(_hex_to_int(item.get("read_occurrence")) or 0)
                == int(new_item.get("read_occurrence") or 0)
            )
            if same_read_site:
                if not updated:
                    rewritten.append(new_item)
                    updated = True
                continue
            rewritten.append(item)
        if not updated:
            rewritten.append(new_item)
        data["constraints"] = rewritten

        atomic_json_dump(data, path, indent=2)

        try:
            self.mmio_handler.load_constraints(str(path))
        except Exception:
            pass
        return True

    def _load_constraint_items(self) -> List[Dict[str, object]]:
        if not self.constraint_file:
            return []

        path = Path(self.constraint_file)
        try:
            with path.open("r") as f:
                data = json.load(f)
        except Exception:
            return []

        if not isinstance(data, dict):
            return []
        items = data.get("constraints", [])
        if not isinstance(items, list):
            return []
        return [item for item in items if isinstance(item, dict)]

    def _constraint_file_stats(self) -> Dict[str, int]:
        items = self._load_constraint_items()
        mmio_items = [item for item in items if item.get("type") == "mmio"]
        pc_items = [item for item in mmio_items if item.get("read_pc") is not None or item.get("pc") is not None]
        branch_mmio_items = [item for item in mmio_items if item.get("added_by") == "branch_mmio"]
        branch_mmio_pc_items = [
            item for item in branch_mmio_items
            if item.get("read_pc") is not None or item.get("pc") is not None
        ]
        return {
            "total_constraints": len(items),
            "mmio_constraints": len(mmio_items),
            "pc_constraints": len(pc_items),
            "address_constraints": len(mmio_items) - len(pc_items),
            "branch_mmio_constraints": len(branch_mmio_items),
            "branch_mmio_pc_constraints": len(branch_mmio_pc_items),
        }

    def _restore_replay_mmio_state(
        self,
        emulator: IntelligentEmulator,
        temp_mmio: EnhancedMMIOHandler,
        mmio_state: Dict[int, int],
    ) -> bool:
        """Restore replay MMIO state as one isolated transaction.

        A replay engine is temporary, but a failed restore can still leave
        occurrence cursors, overlay values, primary-register values, or
        Unicorn bytes partially changed.  Such an engine is not safe to reuse.
        We roll back the Python-visible state where possible and mark the
        engine poisoned so every caller disposes it before another execution.
        """
        errors: List[str] = []
        rollback_errors: List[str] = []
        restored_addresses: List[str] = []
        mapping_skips: List[str] = []
        rolled_back = False

        def mark_poisoned() -> None:
            try:
                emulator.replay_state_poisoned = True
            except Exception:
                pass

        def finish(success: bool) -> bool:
            normalized_errors = list(
                dict.fromkeys(
                    str(item)[:500]
                    for item in (errors + rollback_errors)
                    if str(item)
                )
            )
            payload = {
                "success": bool(success) and not normalized_errors,
                "errors": normalized_errors,
                "restored_addresses": list(restored_addresses),
                "mapping_skips": list(mapping_skips),
                "rolled_back": bool(rolled_back),
                "poisoned": bool(normalized_errors),
                "occurrence_sites": len(
                    getattr(temp_mmio, "read_occurrence_counts", {}) or {}
                )
                if temp_mmio is not None
                else 0,
            }
            if normalized_errors:
                mark_poisoned()
            try:
                emulator.last_replay_mmio_state_restore = dict(payload)
            except Exception:
                pass
            return bool(payload["success"])

        if emulator is None or temp_mmio is None:
            errors.append("mmio_restore_prerequisite_missing")
            return finish(False)
        if bool(getattr(emulator, "replay_state_poisoned", False)):
            errors.append("emulator_replay_state_poisoned")
            return finish(False)

        occurrence_store = getattr(temp_mmio, "read_occurrence_counts", None)
        old_occurrences: Dict[Tuple[int, int], int] = {}
        if occurrence_store is None:
            errors.append("occurrence_state_store_missing")
        else:
            try:
                old_occurrences = dict(occurrence_store)
            except Exception as exc:
                errors.append(f"occurrence_state_not_mapping:{type(exc).__name__}")

        overlay_store = getattr(temp_mmio, "mmio_state", None)
        explicit_store = getattr(temp_mmio, "_explicit_mmio_state_addresses", None)
        old_overlay: Optional[Dict[int, int]] = None
        old_explicit: Optional[Set[int]] = None
        if overlay_store is not None:
            try:
                old_overlay = dict(overlay_store)
            except Exception as exc:
                errors.append(f"overlay_state_not_mapping:{type(exc).__name__}")
        if explicit_store is not None:
            try:
                old_explicit = set(explicit_store)
            except Exception as exc:
                errors.append(f"overlay_explicit_state_not_set:{type(exc).__name__}")

        try:
            raw_occurrences = dict(
                getattr(emulator, "input_occurrence_counts", {}) or {}
            )
        except Exception as exc:
            raw_occurrences = {}
            errors.append(f"occurrence_state_not_mapping:{type(exc).__name__}")
        restored_occurrences: Dict[Tuple[int, int], int] = {}
        for key, value in raw_occurrences.items():
            if not isinstance(key, tuple) or len(key) != 2:
                errors.append("invalid_occurrence_site")
                continue
            try:
                restored_occurrences[
                    (int(key[0]), int(key[1]) & 0xFFFFFFFF)
                ] = max(0, int(value))
            except (TypeError, ValueError, OverflowError):
                errors.append("invalid_occurrence_value")

        try:
            raw_mmio_state = dict(mmio_state or {})
        except Exception as exc:
            raw_mmio_state = {}
            errors.append(f"mmio_state_not_mapping:{type(exc).__name__}")
        normalized: Dict[int, int] = {}
        for address, value in raw_mmio_state.items():
            try:
                normalized[int(address) & 0xFFFFFFFF] = int(value) & 0xFFFFFFFF
            except (TypeError, ValueError, OverflowError):
                errors.append("invalid_mmio_state_value")

        primary = getattr(emulator, "mmio_handler", None)
        primary_states = getattr(primary, "mmio_states", None)
        primary_before: Dict[int, Tuple[object, bool, object]] = {}
        if normalized and primary is None:
            errors.append("primary_mmio_handler_missing")
        if normalized and not callable(getattr(primary, "get_or_create_state", None)):
            errors.append("primary_mmio_state_api_missing")
        if normalized and overlay_store is None:
            errors.append("overlay_mmio_state_store_missing")
        if normalized and not callable(
            getattr(temp_mmio, "mark_mmio_state_explicit", None)
        ):
            errors.append("overlay_mmio_state_marker_missing")
        if occurrence_store is not None and not all(
            callable(getattr(occurrence_store, name, None))
            for name in ("clear", "update")
        ):
            errors.append("occurrence_state_api_missing")

        uc = getattr(emulator, "uc", None)
        ensure_mapping = getattr(emulator, "_ensure_memory_mapped", None)
        is_mapped = getattr(emulator, "_is_memory_mapped", None)
        if normalized and not callable(ensure_mapping):
            errors.append("memory_mapping_api_missing")
        if normalized and uc is None:
            errors.append("unicorn_instance_missing")

        memory_before: Dict[int, bytes] = {}
        newly_mapped_pages: Set[int] = set()
        for address in normalized:
            if isinstance(primary_states, Mapping):
                try:
                    state = primary_states.get(address)
                    if state is None:
                        primary_before[address] = (None, False, None)
                    else:
                        primary_before[address] = (
                            state,
                            True,
                            getattr(state, "current_value"),
                        )
                except Exception as exc:
                    errors.append(
                        f"primary_mmio_state_snapshot_failed:0x{address:08x}:{type(exc).__name__}"
                    )

            if not callable(ensure_mapping) or uc is None:
                continue
            pages = {
                page
                for page in range(
                    address & ~0xFFF,
                    ((address + 3) & ~0xFFF) + 0x1000,
                    0x1000,
                )
            }
            pages_before = set()
            if callable(is_mapped):
                for page in pages:
                    try:
                        if bool(is_mapped(page, 1)):
                            pages_before.add(page)
                    except Exception as exc:
                        errors.append(
                            f"mmio_mapping_probe_failed:0x{address:08x}:{type(exc).__name__}"
                        )
            try:
                mapped = bool(ensure_mapping(address, 4))
            except Exception as exc:
                errors.append(
                    f"mmio_memory_mapping_failed:0x{address:08x}:{type(exc).__name__}"
                )
                continue
            if not mapped:
                try:
                    registered_primary = get_primary_mmio_handler(uc)
                except Exception:
                    registered_primary = None
                primary_owns_unmapped = bool(
                    registered_primary is primary
                    and (
                        callable(getattr(primary, "push_mmio_overlay", None))
                        or callable(getattr(primary, "resolve_bridge_read", None))
                        or bool(getattr(primary, "handles_unmapped_mmio", False))
                    )
                )
                if not primary_owns_unmapped:
                    errors.append(
                        f"mmio_memory_unmapped_without_primary_hook:0x{address:08x}"
                    )
                else:
                    mapping_skips.append(f"0x{address:08x}")
                continue
            if callable(is_mapped):
                for page in pages:
                    try:
                        if page not in pages_before and bool(is_mapped(page, 1)):
                            newly_mapped_pages.add(page)
                    except Exception:
                        pass
            try:
                previous = bytes(uc.mem_read(address, 4))
                if len(previous) != 4:
                    raise ValueError(f"short memory read: {len(previous)}")
                memory_before[address] = previous
            except Exception as exc:
                errors.append(
                    f"mmio_memory_snapshot_failed:0x{address:08x}:{type(exc).__name__}"
                )

        def rollback() -> None:
            nonlocal rolled_back
            rolled_back = True
            if occurrence_store is not None:
                try:
                    occurrence_store.clear()
                    occurrence_store.update(old_occurrences)
                except Exception as exc:
                    rollback_errors.append(
                        f"occurrence_state_rollback_failed:{type(exc).__name__}"
                    )
            if overlay_store is not None and old_overlay is not None:
                try:
                    overlay_store.clear()
                    overlay_store.update(old_overlay)
                except Exception as exc:
                    rollback_errors.append(
                        f"overlay_state_rollback_failed:{type(exc).__name__}"
                    )
            if explicit_store is not None and old_explicit is not None:
                try:
                    explicit_store.clear()
                    explicit_store.update(old_explicit)
                except Exception as exc:
                    rollback_errors.append(
                        f"overlay_explicit_state_rollback_failed:{type(exc).__name__}"
                    )
            for address, (state, existed, old_value) in primary_before.items():
                try:
                    if existed and state is not None:
                        state.current_value = old_value
                    elif isinstance(primary_states, dict):
                        primary_states.pop(address, None)
                except Exception as exc:
                    rollback_errors.append(
                        f"primary_mmio_state_rollback_failed:0x{address:08x}:{type(exc).__name__}"
                    )
            if uc is not None:
                for address, previous in memory_before.items():
                    try:
                        uc.mem_write(address, previous)
                    except Exception as exc:
                        rollback_errors.append(
                            f"mmio_memory_rollback_failed:0x{address:08x}:{type(exc).__name__}"
                        )
                managed_unmap = getattr(emulator, "_managed_mem_unmap", None)
                unmap = getattr(uc, "mem_unmap", None)
                if callable(unmap):
                    for page in sorted(newly_mapped_pages, reverse=True):
                        try:
                            if callable(managed_unmap):
                                managed_unmap(page, 0x1000)
                            else:
                                unmap(page, 0x1000)
                                forget_mapping = getattr(
                                    emulator,
                                    "_forget_mapped_range",
                                    None,
                                )
                                if callable(forget_mapping):
                                    forget_mapping(page, 0x1000)
                        except Exception as exc:
                            rollback_errors.append(
                                f"mmio_mapping_rollback_failed:0x{page:08x}:{type(exc).__name__}"
                            )

        if errors:
            rollback()
            return finish(False)

        try:
            occurrence_store.clear()
            occurrence_store.update(restored_occurrences)
            if overlay_store is not None:
                # Replace rather than update: an ISR replay can have seeded
                # this overlay from a different execution context.
                overlay_store.clear()
                overlay_store.update(normalized)
                temp_mmio.mark_mmio_state_explicit(normalized.keys())
            for address, value in normalized.items():
                internal_state = primary.get_or_create_state(address)
                internal_state.current_value = value
                if address in memory_before:
                    uc.mem_write(
                        address,
                        (value & 0xFFFFFFFF).to_bytes(4, "little"),
                    )
                restored_addresses.append(f"0x{address:08x}")
        except Exception as exc:
            errors.append(f"mmio_state_restore_apply_failed:{type(exc).__name__}")
            rollback()
            return finish(False)

        return finish(True)

    @staticmethod
    def _replay_mmio_restore_failure_reason(emulator: object) -> str:
        """Return a bounded diagnostic suitable for a replay failure record."""
        status = getattr(emulator, "last_replay_mmio_state_restore", {}) or {}
        if not isinstance(status, Mapping):
            return "replay_mmio_state_restore_failed"
        errors = [str(item) for item in list(status.get("errors", []) or []) if str(item)]
        if not errors:
            return "replay_mmio_state_restore_failed"
        return "replay_mmio_state_restore_failed:" + ",".join(errors[:4])

    def _branch_snapshot_replay_entries(
        self,
        branch_bb_start: int,
        max_variants: int = 3,
    ) -> List[PrefixReplaySnapshot]:
        entries: List[PrefixReplaySnapshot] = []
        seen = set()

        def field(source: object, name: str, default: object = None) -> object:
            if isinstance(source, Mapping):
                return source.get(name, default)
            return getattr(source, name, default)

        def values(source: object, name: str) -> Tuple[str, ...]:
            value = field(source, name, ())
            if isinstance(value, str):
                value = (value,)
            elif isinstance(value, Mapping):
                value = tuple(
                    str(key)
                    for key, count in value.items()
                    if count and str(key)
                )
            try:
                return tuple(str(item) for item in (value or ()) if str(item))
            except TypeError:
                return tuple()

        def lineage_kwargs(source_entry: object, snapshot: object) -> Dict[str, object]:
            """Copy wrapper lineage without allowing default fields to erase it."""
            source_status = str(
                field(source_entry, "provenance_status", "unspecified")
                or "unspecified"
            ).strip().lower()
            source_reasons = values(source_entry, "provenance_reasons")
            source_prefix_reasons = values(source_entry, "prefix_intervention_reasons")
            source_execution_id = str(
                field(source_entry, "source_execution_id", "") or ""
            )
            source_has_lineage = bool(
                source_status not in {"", "unknown", "unspecified"}
                or source_reasons
                or source_prefix_reasons
                or source_execution_id
                or field(source_entry, "prefix_telemetry_complete", None) is True
            )
            snapshot_status = str(
                field(snapshot, "provenance_status", "unspecified")
                or "unspecified"
            )
            snapshot_reasons = values(snapshot, "provenance_reasons")
            snapshot_prefix_reasons = values(snapshot, "prefix_intervention_reasons")
            snapshot_execution_id = str(
                field(snapshot, "source_execution_id", "") or ""
            )
            status = source_status if source_has_lineage else snapshot_status
            reasons = tuple(
                dict.fromkeys(
                    (source_reasons if source_has_lineage else tuple())
                    + snapshot_reasons
                )
            )
            prefix_reasons = tuple(
                dict.fromkeys(
                    (source_prefix_reasons if source_has_lineage else tuple())
                    + snapshot_prefix_reasons
                    + reasons
                )
            )
            execution_id = source_execution_id if source_has_lineage else snapshot_execution_id
            source_telemetry = field(source_entry, "prefix_telemetry_complete", None)
            snapshot_telemetry = field(snapshot, "prefix_telemetry_complete", None)
            telemetry = (
                source_telemetry
                if source_has_lineage and source_telemetry is not None
                else snapshot_telemetry
            )
            source_finalized = field(source_entry, "provenance_finalized", None)
            snapshot_finalized = field(snapshot, "provenance_finalized", None)
            if source_has_lineage and source_finalized is not None:
                finalized = bool(source_finalized) and bool(
                    snapshot_finalized if snapshot_finalized is not None else True
                )
            else:
                finalized = bool(snapshot_finalized)
            return {
                "provenance_status": status or "unspecified",
                "provenance_reasons": reasons,
                "source_execution_id": execution_id,
                "prefix_telemetry_complete": bool(telemetry),
                "prefix_intervention_reasons": prefix_reasons,
                "provenance_finalized": finalized,
            }

        direct_snapshot = self.emulator.branch_snapshot_manager.get_snapshot(branch_bb_start)
        if direct_snapshot is not None:
            entry = PrefixReplaySnapshot(
                prefix_signature=tuple(),
                next_branch_key=(int(branch_bb_start), 1),
                snapshot=direct_snapshot,
                mmio_state=self._interrupt_context_mmio_state(direct_snapshot),
                source_path_signature=tuple(),
                branch_depth=int(getattr(direct_snapshot, "depth", 0)),
                origin="direct",
                evidence_class=EVIDENCE_E0,
                **lineage_kwargs(direct_snapshot, direct_snapshot),
            )
            dedupe_key = (
                int(getattr(direct_snapshot, "address", 0)),
                int(getattr(direct_snapshot, "order", 0)),
                tuple(),
            )
            seen.add(dedupe_key)
            entries.append(entry)

        for entry in self.reservoir_prefix_snapshots.values():
            next_branch_key = tuple(getattr(entry, "next_branch_key", (0, 0)) or (0, 0))
            if int(next_branch_key[0]) != int(branch_bb_start):
                continue
            snapshot = getattr(entry, "snapshot", None)
            if snapshot is None:
                continue
            signature = self._ordered_source_path_signature(
                tuple(getattr(entry, "source_path_signature", tuple()) or tuple())
            )
            dedupe_key = (
                int(getattr(snapshot, "address", 0)),
                int(getattr(snapshot, "order", 0)),
                signature,
            )
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            entries.append(
                PrefixReplaySnapshot(
                    prefix_signature=self._ordered_source_path_signature(
                        tuple(getattr(entry, "prefix_signature", tuple()) or tuple())
                    ),
                    next_branch_key=(int(next_branch_key[0]), int(next_branch_key[1])),
                    snapshot=snapshot,
                    mmio_state={
                        int(address): int(value) & 0xFFFFFFFF
                        for address, value in (getattr(entry, "mmio_state", {}) or {}).items()
                    },
                    source_path_signature=signature,
                    branch_depth=int(getattr(entry, "branch_depth", 0)),
                    origin="prefix",
                    evidence_class=self._snapshot_entry_evidence_class(entry),
                    source_occurrence_trace=tuple(
                        getattr(entry, "source_occurrence_trace", tuple())
                        or tuple()
                    ),
                    source_occurrence_prefix_len=int(
                        getattr(
                            entry,
                            "source_occurrence_prefix_len",
                            0,
                        )
                        or 0
                    ),
                    **lineage_kwargs(entry, snapshot),
                )
            )

        for root_key, variants in self.known_branch_root_snapshots.items():
            if int(root_key[0]) != int(branch_bb_start):
                continue
            for entry in variants.values():
                snapshot = getattr(entry, "snapshot", None)
                if snapshot is None:
                    continue
                signature = self._ordered_source_path_signature(
                    tuple(getattr(entry, "source_path_signature", tuple()) or tuple())
                )
                dedupe_key = (
                    int(getattr(snapshot, "address", 0)),
                    int(getattr(snapshot, "order", 0)),
                    signature,
                )
                if dedupe_key in seen:
                    continue
                seen.add(dedupe_key)
                entries.append(entry)

        source_priority = {
            "prefix": 3,
            "root": 2,
            "direct": 1,
            "unknown": 0,
        }
        entries.sort(
            key=lambda entry: (
                source_priority.get(str(getattr(entry, "origin", "unknown")), 0),
                len(tuple(getattr(entry, "source_path_signature", tuple()) or tuple())),
                len(tuple(getattr(entry, "prefix_signature", tuple()) or tuple())),
                int(getattr(entry, "branch_depth", 0)),
                int(getattr(getattr(entry, "snapshot", None), "order", 0)),
            ),
            reverse=True,
        )
        if max_variants > 0:
            prefix_entries = [
                entry for entry in entries
                if str(getattr(entry, "origin", "unknown")) == "prefix"
            ]
            if prefix_entries:
                selected: List[PrefixReplaySnapshot] = []
                selected.extend(prefix_entries[: min(len(prefix_entries), max_variants)])
                if len(selected) < max_variants:
                    seen_selected = {
                        (
                            int(getattr(getattr(entry, "snapshot", None), "address", 0) or 0),
                            int(getattr(getattr(entry, "snapshot", None), "order", 0) or 0),
                            str(getattr(entry, "origin", "unknown")),
                            tuple(getattr(entry, "source_path_signature", tuple()) or tuple()),
                        )
                        for entry in selected
                    }
                    for entry in entries:
                        identity = (
                            int(getattr(getattr(entry, "snapshot", None), "address", 0) or 0),
                            int(getattr(getattr(entry, "snapshot", None), "order", 0) or 0),
                            str(getattr(entry, "origin", "unknown")),
                            tuple(getattr(entry, "source_path_signature", tuple()) or tuple()),
                        )
                        if identity in seen_selected:
                            continue
                        selected.append(entry)
                        seen_selected.add(identity)
                        if len(selected) >= max_variants:
                            break
                return selected[:max_variants]
            return entries[:max_variants]
        return entries

    def _branch_desired_successor_bb(
        self,
        branch_instruction: Dict[str, object],
        take_branch: bool,
    ) -> Optional[int]:
        branch_pc = int(branch_instruction.get("address", 0) or 0)
        size = int(branch_instruction.get("size", 2) or 2)
        if take_branch:
            target = _parse_direct_target(branch_instruction.get("operands"))
            if target is None:
                return None
            return self.prepared.resolve_basic_block(target)
        return self.prepared.resolve_basic_block(branch_pc + size)

    def _static_reachability_cache_limits(self) -> Tuple[int, int]:
        """Return byte and legacy-node limits for the recomputable cache.

        The byte limit is the production guard.  The old node limit remains
        readable only for explicitly configured legacy test/experiment
        environments; its default is zero so stale configurations cannot
        recreate the previous 500k-node behavior.
        """
        try:
            max_bytes = max(
                0,
                _env_int(
                    "LSGEMU_STATIC_REACHABILITY_CACHE_MAX_BYTES",
                    128 * 1024 * 1024,
                ),
            )
        except Exception:
            max_bytes = 128 * 1024 * 1024
        try:
            legacy_max_nodes = max(
                0,
                _env_int("LSGEMU_STATIC_REACHABILITY_CACHE_MAX_NODES", 0),
            )
        except Exception:
            legacy_max_nodes = 0
        return max_bytes, legacy_max_nodes

    def _static_reachable_from_cached_legacy(
        self,
        start_bb: Optional[int],
        successor_map: Dict[int, Set[int]],
        cache: Dict[int, object],
    ) -> Set[int]:
        """Compatibility path used only for controlled representation A/B runs."""
        if start_bb is None or start_bb not in self.prepared.static_bb_set:
            return set()
        effective_cache = getattr(self, "effective_successor_cache", None)
        dynamic_version = int(getattr(self, "dynamic_successor_version", 0) or 0)
        use_global_cache = bool(
            effective_cache is not None
            and int(effective_cache[0]) == dynamic_version
            and successor_map is effective_cache[1]
        )
        global_cache = getattr(
            self,
            "static_reachable_cache_by_successor_version",
            None,
        )
        if not isinstance(global_cache, dict):
            global_cache = {}
            self.static_reachable_cache_by_successor_version = global_cache
        cached = cache.get(start_bb)
        if cached is not None:
            return cached  # type: ignore[return-value]
        if use_global_cache:
            cached = global_cache.get(start_bb)
            if cached is not None:
                if cache is not global_cache:
                    cache[start_bb] = cached
                return cached  # type: ignore[return-value]

        queue = deque([start_bb])
        seen = {start_bb}
        while queue:
            current = queue.popleft()
            for succ in sorted(successor_map.get(current, set())):
                if succ not in seen:
                    seen.add(succ)
                    queue.append(succ)
        if not use_global_cache:
            cache[start_bb] = seen
            return seen

        configured_limit = max(
            0,
            _env_int("LSGEMU_STATIC_REACHABILITY_CACHE_MAX_NODES", 0),
        )
        if configured_limit <= 0 or len(seen) <= configured_limit:
            global_cache[start_bb] = seen
            self.static_reachable_cache_node_count = sum(
                len(value)
                for value in global_cache.values()
                if isinstance(value, (set, frozenset))
            )
        return seen

    def _static_reachable_from_cached(
        self,
        start_bb: Optional[int],
        successor_map: Dict[int, Set[int]],
        cache: Dict[int, object],
    ) -> Set[int] | PackedReachabilitySet:
        if os.environ.get(
            "LSGEMU_STATIC_REACHABILITY_CACHE_REPRESENTATION",
            "packed_array",
        ).strip().lower() in {"set", "legacy"}:
            return self._static_reachable_from_cached_legacy(
                start_bb,
                successor_map,
                cache,
            )
        if start_bb is None or start_bb not in self.prepared.static_bb_set:
            return set()

        effective_cache = getattr(self, "effective_successor_cache", None)
        dynamic_version = int(getattr(self, "dynamic_successor_version", 0) or 0)
        use_global_cache = bool(
            effective_cache is not None
            and int(effective_cache[0]) == dynamic_version
            and successor_map is effective_cache[1]
        )
        global_cache = getattr(
            self,
            "static_reachable_cache_by_successor_version",
            None,
        )
        if not isinstance(global_cache, dict):
            global_cache = {}
            self.static_reachable_cache_by_successor_version = global_cache

        cached = cache.get(start_bb)
        if cached is not None:
            if isinstance(cached, PackedReachabilitySet):
                self.static_reachable_cache_hits = int(
                    getattr(self, "static_reachable_cache_hits", 0) or 0
                ) + 1
            if cache is global_cache:
                try:
                    cache.pop(start_bb)
                    cache[start_bb] = cached
                except (KeyError, AttributeError):
                    pass
            return cached  # type: ignore[return-value]

        if use_global_cache:
            cached = global_cache.get(start_bb)
            if cached is not None:
                self.static_reachable_cache_hits = int(
                    getattr(self, "static_reachable_cache_hits", 0) or 0
                ) + 1
                try:
                    global_cache.pop(start_bb)
                    global_cache[start_bb] = cached
                except (KeyError, AttributeError):
                    pass
                if cache is not global_cache:
                    cache[start_bb] = cached
                    return cached  # type: ignore[return-value]
                return cached  # type: ignore[return-value]
            self.static_reachable_cache_misses = int(
                getattr(self, "static_reachable_cache_misses", 0) or 0
            ) + 1

        queue = deque([start_bb])
        seen = {start_bb}
        while queue:
            current = queue.popleft()
            for succ in sorted(successor_map.get(current, set())):
                if succ not in seen:
                    seen.add(succ)
                    queue.append(succ)

        if not use_global_cache:
            cache[start_bb] = seen
            return seen

        view = PackedReachabilitySet.from_nodes(seen)
        if view is None:
            # Preserve exact behavior if a malformed/legacy successor map
            # contains a node outside the shared universe.
            cache[start_bb] = seen
            self.static_reachable_cache_oversized_skips = int(
                getattr(self, "static_reachable_cache_oversized_skips", 0) or 0
            ) + 1
            return seen

        max_bytes, legacy_max_nodes = self._static_reachability_cache_limits()
        entry_bytes = int(view.storage_bytes)
        too_many_nodes = legacy_max_nodes > 0 and len(view) > legacy_max_nodes
        too_many_bytes = max_bytes > 0 and entry_bytes > max_bytes
        if too_many_nodes or too_many_bytes:
            self.static_reachable_cache_oversized_skips = int(
                getattr(self, "static_reachable_cache_oversized_skips", 0) or 0
            ) + 1
            if cache is not global_cache:
                cache[start_bb] = view
                return view
            return view

        tracked_nodes = int(
            getattr(self, "static_reachable_cache_node_count", 0) or 0
        )
        tracked_bytes = int(
            getattr(self, "static_reachable_cache_bytes", 0) or 0
        )
        if global_cache and tracked_nodes == 0:
            tracked_nodes = sum(len(value) for value in global_cache.values())
        if global_cache and tracked_bytes == 0:
            tracked_bytes = sum(
                int(getattr(value, "storage_bytes", 0) or 0)
                for value in global_cache.values()
            )

        while global_cache and (
            (legacy_max_nodes > 0 and tracked_nodes + len(view) > legacy_max_nodes)
            or (max_bytes > 0 and tracked_bytes + entry_bytes > max_bytes)
        ):
            oldest_key, oldest_value = next(iter(global_cache.items()))
            global_cache.pop(oldest_key, None)
            tracked_nodes = max(0, tracked_nodes - len(oldest_value))
            tracked_bytes = max(
                0,
                tracked_bytes - int(getattr(oldest_value, "storage_bytes", 0) or 0),
            )
            self.static_reachable_cache_evictions = int(
                getattr(self, "static_reachable_cache_evictions", 0) or 0
            ) + 1

        global_cache[start_bb] = view
        tracked_nodes += len(view)
        tracked_bytes += entry_bytes
        self.static_reachable_cache_node_count = tracked_nodes
        self.static_reachable_cache_bytes = tracked_bytes
        if cache is not global_cache:
            cache[start_bb] = view
            return view
        return view

    def _static_target_distance_lookup(
        self,
        target_bbs: Iterable[int],
        successor_map: Dict[int, Set[int]],
        far_distance: int = 1_000_000_000,
    ):
        """
        Return a cached reverse-CFG distance lookup to any target BB.

        This is intentionally static/dynamic-edge based, not execution based:
        it is only a scheduler heuristic for replay candidates.  A smaller
        distance means the successor is closer to a currently desired target;
        unreachable or invalid nodes get far_distance.
        """
        targets = {
            int(bb)
            for bb in target_bbs or set()
            if int(bb) in self.prepared.static_bb_set
        }
        cache: Dict[int, int] = {}
        predecessors: Optional[Dict[int, Set[int]]] = None

        def build_predecessors() -> Dict[int, Set[int]]:
            nonlocal predecessors
            if predecessors is not None:
                return predecessors
            built: Dict[int, Set[int]] = defaultdict(set)
            for bb_addr, successors in successor_map.items():
                source = int(bb_addr)
                if source not in self.prepared.static_bb_set:
                    continue
                for successor in successors:
                    successor = int(successor)
                    if successor in self.prepared.static_bb_set:
                        built[successor].add(source)
            predecessors = built
            return built

        def lookup(start_bb: Optional[int]) -> int:
            if not targets or start_bb is None:
                return far_distance
            try:
                start = int(start_bb)
            except (TypeError, ValueError):
                return far_distance
            if start not in self.prepared.static_bb_set:
                return far_distance
            if not cache:
                preds = build_predecessors()
                queue = deque((target, 0) for target in sorted(targets))
                seen = set(targets)
                while queue:
                    current, distance = queue.popleft()
                    cache[current] = distance
                    for predecessor in sorted(preds.get(current, set())):
                        if predecessor in seen:
                            continue
                        seen.add(predecessor)
                        queue.append((predecessor, distance + 1))
            return int(cache.get(start, far_distance))

        return lookup

    def _branch_direction_static_potential(
        self,
        branch_instruction: Dict[str, object],
        take_branch: bool,
        known_coverage: Set[int],
        successor_map: Dict[int, Set[int]],
        reachable_cache: Dict[int, Set[int]],
    ) -> Dict[str, object]:
        successor_bb = self._branch_desired_successor_bb(branch_instruction, take_branch)
        reachable = self._static_reachable_from_cached(successor_bb, successor_map, reachable_cache)
        uncovered = reachable - known_coverage
        immediate_uncovered = bool(successor_bb is not None and successor_bb not in known_coverage)
        return {
            "successor_bb": successor_bb,
            "reachable_bbs": len(reachable),
            "static_new_potential": len(uncovered),
            "immediate_uncovered": immediate_uncovered,
        }

    def _apply_temp_mmio_constraints(
        self,
        temp_mmio: EnhancedMMIOHandler,
        constraint_items: Iterable[BranchConstraintCandidate],
        emulator: Optional[IntelligentEmulator] = None,
        mmio_added_by: str = "branch_mmio_runtime",
    ) -> None:
        scoped_replay = self._scoped_replay_available()
        for item in constraint_items:
            normalized = item.normalized() if isinstance(item, BranchConstraintCandidate) else None
            if normalized is None:
                continue
            if normalized.constraint_type == "mmio":
                if (
                    scoped_replay
                    and normalized.read_pc is not None
                    and normalized.read_occurrence is not None
                ):
                    temp_mmio.add_occurrence_constraint(
                        normalized.read_pc,
                        normalized.address,
                        normalized.read_occurrence,
                        normalized.value,
                        added_by=mmio_added_by,
                    )
                elif scoped_replay and normalized.read_pc is not None:
                    temp_mmio.add_pc_constraint(
                        normalized.read_pc,
                        normalized.address,
                        normalized.value,
                        added_by=mmio_added_by,
                    )
                else:
                    temp_mmio.add_constraint(
                        normalized.address,
                        normalized.value,
                        added_by=(
                            mmio_added_by
                            if scoped_replay
                            else f"{mmio_added_by}_global_ablation"
                        ),
                    )
                continue

            if normalized.constraint_type == "memory":
                if not scoped_replay:
                    # There is no sound address-global analogue for a dynamic
                    # memory-read constraint. A2 keeps only the declared
                    # address-global MMIO fallback.
                    continue
                if emulator is None or normalized.read_pc is None:
                    continue
                if normalized.is_environment_fact:
                    emulator.external_memory_input_addresses.add(
                        int(normalized.address) & 0xFFFFFFFF
                    )
                raw_constraint = {
                    "type": "memory",
                    "read_pc": normalized.read_pc,
                    "address": normalized.address,
                    "value": normalized.value,
                    "constraint_pc": normalized.constraint_pc,
                    "external_memory": bool(normalized.is_environment_fact),
                    "description": normalized.source or "temporary replay memory constraint",
                }
                checked = emulator._normalize_runtime_constraint(raw_constraint)
                if checked is None:
                    continue
                read_pc = int(checked["read_pc"])
                address = int(checked["address"]) & 0xFFFFFFFF
                value = int(checked["value"]) & 0xFFFFFFFF
                if normalized.read_occurrence is not None:
                    occurrence_key = (
                        read_pc,
                        address,
                        int(normalized.read_occurrence),
                    )
                    emulator.memory_occurrence_constraints[occurrence_key] = value
                    emulator.memory_occurrence_constraint_sites.add(
                        (read_pc, address)
                    )
                else:
                    emulator.memory_read_constraints[(read_pc, address)] = value
                if normalized.read_occurrence is None:
                    try:
                        write_size = emulator._constraint_write_size(read_pc)
                        masked = value & ((1 << (write_size * 8)) - 1)
                        if emulator._ensure_memory_mapped(address, write_size):
                            emulator.uc.mem_write(address, masked.to_bytes(write_size, "little"))
                    except Exception:
                        continue
            else:
                continue

    def _constraint_items_signature(
        self,
        constraint_items: Iterable[BranchConstraintCandidate],
    ) -> Tuple[Tuple[object, ...], ...]:
        signature: List[Tuple[object, ...]] = []
        for item in constraint_items or []:
            normalized = self._normalize_constraint_candidate(item)
            if normalized is None:
                continue
            signature.append((
                *constraint_site_identity(normalized),
                int(normalized.value) & 0xFFFFFFFF,
                bool(normalized.is_environment_fact),
            ))
        return tuple(sorted(signature))

    @staticmethod
    def _replay_eval_signature(
        control_eval: Dict[str, object],
        result_eval: Dict[str, object],
        outcome: str,
    ) -> Tuple[object, ...]:
        return (
            str(outcome or ""),
            bool(control_eval.get("branch_seen")),
            str(control_eval.get("failure_reason") or ""),
            tuple(control_eval.get("observed_directions") or []),
            bool(result_eval.get("branch_seen")),
            str(result_eval.get("failure_reason") or ""),
            tuple(result_eval.get("observed_directions") or []),
        )

    def _collect_constraint_runtime_feedback(
        self,
        temp_mmio: EnhancedMMIOHandler,
        constraint_items: Iterable[BranchConstraintCandidate],
        emulator: Optional[IntelligentEmulator] = None,
    ) -> Dict[str, object]:
        normalized_items = [
            candidate
            for candidate in (
                self._normalize_constraint_candidate(item)
                for item in (constraint_items or [])
            )
            if candidate is not None
        ]
        mmio_items = [candidate for candidate in normalized_items if candidate.constraint_type == "mmio"]
        memory_items = [candidate for candidate in normalized_items if candidate.constraint_type == "memory"]
        access_occurrence_history = list(
            getattr(temp_mmio, "access_occurrence_history", []) or []
        )
        if not access_occurrence_history:
            site_counts: Dict[Tuple[int, int], int] = {}
            for pc, address, value, is_read in list(
                getattr(temp_mmio, "access_history", []) or []
            ):
                occurrence = 0
                if is_read:
                    site = (int(pc), int(address))
                    occurrence = int(site_counts.get(site, 0) or 0) + 1
                    site_counts[site] = occurrence
                access_occurrence_history.append(
                    (pc, address, value, is_read, occurrence)
                )
        memory_history = list(
            getattr(emulator, "memory_constraint_hit_history", []) or []
        ) if emulator is not None else []
        details: List[Dict[str, object]] = []
        matched_reads = 0
        matched_address_reads = 0
        matched_requested_occurrences = 0
        value_delivery_mismatches = 0

        for candidate in normalized_items:
            exact_match = False
            address_seen = False
            requested_occurrence_seen = False
            observed_values: List[int] = []
            observed_pc: Optional[int] = None
            observed_occurrence: Optional[int] = None
            if candidate.constraint_type == "mmio":
                for pc, address, value, is_read, occurrence in reversed(
                    access_occurrence_history
                ):
                    if not is_read or int(address) != int(candidate.address):
                        continue
                    if candidate.read_pc is not None and int(pc) != int(candidate.read_pc):
                        continue
                    address_seen = True
                    observed_pc = int(pc) & 0xFFFFFFFF
                    observed_occurrence = int(occurrence or 0)
                    observed_value = int(value) & 0xFFFFFFFF
                    if observed_value not in observed_values and len(observed_values) < 4:
                        observed_values.append(observed_value)
                    if (
                        candidate.read_occurrence is not None
                        and int(occurrence or 0) != int(candidate.read_occurrence)
                    ):
                        continue
                    requested_occurrence_seen = True
                    effective_value = int(candidate.value) & (
                        (1 << int(candidate.width)) - 1
                        if candidate.width is not None
                        and int(candidate.width) < 32
                        else 0xFFFFFFFF
                    )
                    if observed_value == effective_value:
                        exact_match = True
                        break
            elif candidate.constraint_type == "memory":
                for item in reversed(memory_history):
                    if int(item.get("address", -1)) != int(candidate.address):
                        continue
                    if (
                        candidate.read_pc is not None
                        and int(item.get("pc", -1)) != int(candidate.read_pc)
                    ):
                        continue
                    address_seen = True
                    observed_pc = int(item.get("pc", 0) or 0) & 0xFFFFFFFF
                    observed_occurrence = int(item.get("occurrence", 0) or 0)
                    observed_value = int(item.get("value", 0) or 0) & 0xFFFFFFFF
                    if observed_value not in observed_values and len(observed_values) < 4:
                        observed_values.append(observed_value)
                    if (
                        candidate.read_occurrence is not None
                        and observed_occurrence != int(candidate.read_occurrence)
                    ):
                        continue
                    requested_occurrence_seen = True
                    effective_value = int(candidate.value) & (
                        (1 << int(candidate.width)) - 1
                        if candidate.width is not None
                        and int(candidate.width) < 32
                        else 0xFFFFFFFF
                    )
                    if observed_value == effective_value:
                        exact_match = True
                        break
            if address_seen:
                matched_address_reads += 1
            if requested_occurrence_seen:
                matched_requested_occurrences += 1
            if exact_match:
                matched_reads += 1
            elif requested_occurrence_seen:
                value_delivery_mismatches += 1
            details.append({
                "constraint": self._serialize_constraint_candidate(candidate),
                "address_read_seen": bool(address_seen),
                "requested_occurrence_seen": bool(requested_occurrence_seen),
                "exact_value_seen": bool(exact_match),
                "value_delivery_mismatch": bool(
                    requested_occurrence_seen and not exact_match
                ),
                "observed_pc": f"0x{observed_pc:08x}" if observed_pc is not None else None,
                "observed_occurrence": observed_occurrence,
                "observed_values": [
                    f"0x{observed_value:08x}"
                    for observed_value in observed_values
                ],
            })

        return {
            "constraint_count": len(normalized_items),
            "mmio_constraint_count": len(mmio_items),
            "memory_constraint_count": len(memory_items),
            "matched_constraint_reads": matched_reads,
            "matched_address_reads": matched_address_reads,
            "matched_requested_occurrences": matched_requested_occurrences,
            "value_delivery_mismatches": value_delivery_mismatches,
            "any_constraint_read_matched": bool(matched_reads > 0),
            "all_constraint_reads_matched": bool(normalized_items) and matched_reads == len(normalized_items),
            "all_constraints_external": bool(normalized_items) and all(
                candidate.is_environment_fact for candidate in normalized_items
            ),
            "items": details[:8],
        }

    @staticmethod
    def _constraints_materialized(
        constraint_items: Iterable[BranchConstraintCandidate],
        constraint_feedback: Optional[Dict[str, object]],
        *,
        require_external: bool = False,
    ) -> bool:
        normalized = [
            candidate.normalized()
            for candidate in constraint_items or []
            if isinstance(candidate, BranchConstraintCandidate)
        ]
        if not normalized:
            return False
        feedback = dict(constraint_feedback or {})
        if not feedback.get("all_constraint_reads_matched"):
            return False
        if require_external and not all(candidate.is_environment_fact for candidate in normalized):
            return False
        return True

    @staticmethod
    def _is_strong_no_effect_failure(
        outcome: str,
        control_eval: Dict[str, object],
        result_eval: Dict[str, object],
        constraint_feedback: Optional[Dict[str, object]],
    ) -> bool:
        if str(outcome or "") != "no_effect_same_outcome":
            return False
        if not constraint_feedback or not constraint_feedback.get("all_constraint_reads_matched"):
            return False
        return (
            str(control_eval.get("failure_reason") or "") == str(result_eval.get("failure_reason") or "")
            and tuple(control_eval.get("observed_directions") or []) == tuple(result_eval.get("observed_directions") or [])
            and bool(control_eval.get("branch_seen")) == bool(result_eval.get("branch_seen"))
        )

    def _snapshot_replay_can_revisit_constraints(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        constraint_items: Iterable[BranchConstraintCandidate],
    ) -> bool:
        snapshot = getattr(snapshot_entry, "snapshot", None)
        if snapshot is None:
            return True
        raw_watermarks = getattr(snapshot, "input_occurrence_counts", None)
        if not isinstance(raw_watermarks, dict):
            # Backward-compatible snapshots have no dynamic input timeline.
            # Let runtime consumption validation decide whether replay worked.
            return True
        watermarks = {
            (int(key[0]), int(key[1]) & 0xFFFFFFFF): max(0, int(value))
            for key, value in raw_watermarks.items()
            if isinstance(key, tuple) and len(key) == 2
        }
        for item in constraint_items or []:
            normalized = self._normalize_constraint_candidate(item)
            if (
                normalized is None
                or normalized.read_pc is None
                or normalized.read_occurrence is None
            ):
                continue
            site = (
                int(normalized.read_pc),
                int(normalized.address) & 0xFFFFFFFF,
            )
            consumed_occurrences = int(watermarks.get(site, 0) or 0)
            if consumed_occurrences >= int(normalized.read_occurrence):
                return False
        return True

    def _scope_signature_from_snapshot_entry(
        self,
        snapshot_entry: Optional[PrefixReplaySnapshot],
    ) -> Tuple[Tuple[Tuple[int, int], object], ...]:
        if snapshot_entry is None:
            return tuple()
        occurrence_prefix = self._snapshot_entry_occurrence_prefix(
            snapshot_entry
        )
        if occurrence_prefix:
            return normalize_naturalization_signature(occurrence_prefix)
        return self._ordered_source_path_signature(
            tuple(
                getattr(snapshot_entry, "source_path_signature", tuple())
                or getattr(snapshot_entry, "prefix_signature", tuple())
                or tuple()
            )
        )

    @staticmethod
    def _serialize_debug_signature(
        signature: Tuple[Tuple[Tuple[int, int], object], ...],
    ) -> List[Dict[str, object]]:
        return [
            {
                "branch": f"0x{int(key[0]) & 0xFFFFFFFF:08x}",
                "occurrence": int(key[1]),
                "choice": choice,
            }
            for key, choice in tuple(signature or tuple())
        ]

    def _scoped_branch_constraint_variant_signatures(
        self,
        scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
        branch_key: Optional[Tuple[int, int]] = None,
        branch_choice: Optional[object] = None,
    ) -> List[Tuple[Tuple[Tuple[int, int], object], ...]]:
        base_signature = self._ordered_source_path_signature(tuple(scope_signature or tuple()))
        candidate_signatures: List[Tuple[Tuple[Tuple[int, int], object], ...]] = []
        seen_signatures = set()

        def remember_signature(signature):
            normalized = self._ordered_source_path_signature(tuple(signature or tuple()))
            if not normalized or normalized in seen_signatures:
                return
            seen_signatures.add(normalized)
            candidate_signatures.append(normalized)

        remember_signature(base_signature)
        for tail_len in range(1, min(len(base_signature), 4) + 1):
            remember_signature(base_signature[-tail_len:])

        if branch_key is not None and branch_choice is not None:
            branch_item = (((int(branch_key[0]), int(branch_key[1]))), branch_choice)
            with_branch_signature = self._ordered_source_path_signature(
                tuple(list(base_signature) + [branch_item])
            )
            remember_signature(with_branch_signature)
            for tail_len in range(1, min(len(with_branch_signature), 4) + 1):
                remember_signature(with_branch_signature[-tail_len:])

        return candidate_signatures

    def _remember_scoped_branch_constraint(
        self,
        scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
        candidate: BranchConstraintCandidate,
    ) -> bool:
        if not self._scoped_replay_available():
            return False
        normalized_scope_signature = self._ordered_source_path_signature(
            tuple(scope_signature or tuple())
        )
        normalized_candidate = self._normalize_constraint_candidate(candidate)
        if not normalized_scope_signature or normalized_candidate is None:
            return False
        if normalized_candidate.read_pc is None:
            return False
        items = list(self.scoped_branch_constraints.get(normalized_scope_signature, []))
        rewritten = [
            item
            for item in items
            if not (
                self._normalize_constraint_candidate(item) is not None
                and self._normalize_constraint_candidate(item).constraint_type == normalized_candidate.constraint_type
                and self._normalize_constraint_candidate(item).address == normalized_candidate.address
                and (self._normalize_constraint_candidate(item).read_pc or 0) == (normalized_candidate.read_pc or 0)
                and (self._normalize_constraint_candidate(item).read_occurrence or 0)
                == (normalized_candidate.read_occurrence or 0)
            )
        ]
        rewritten.append(normalized_candidate)
        if len(rewritten) > 16:
            rewritten = rewritten[-16:]
        changed = rewritten != items
        self.scoped_branch_constraints[normalized_scope_signature] = rewritten
        if changed:
            self.scoped_branch_constraint_match_cache.clear()
            self.scoped_branch_constraint_presence_cache.clear()
        return changed

    def _remember_scoped_branch_constraint_variants(
        self,
        scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
        candidate: BranchConstraintCandidate,
        branch_key: Optional[Tuple[int, int]] = None,
        branch_choice: Optional[object] = None,
    ) -> bool:
        if not self._scoped_replay_available():
            return False
        candidate_signatures = self._scoped_branch_constraint_variant_signatures(
            scope_signature,
            branch_key=branch_key,
            branch_choice=branch_choice,
        )
        changed = False
        for signature in candidate_signatures:
            if self._remember_scoped_branch_constraint(signature, candidate):
                changed = True
        return changed

    def _scope_signature_matches(
        self,
        stored_scope: Tuple[Tuple[Tuple[int, int], object], ...],
        requested_scope: Tuple[Tuple[Tuple[int, int], object], ...],
    ) -> bool:
        if not stored_scope or len(stored_scope) > len(requested_scope):
            return False
        if self._scoped_subsequence_match_enabled():
            cursor = 0
            for item in requested_scope:
                if item == stored_scope[cursor]:
                    cursor += 1
                    if cursor >= len(stored_scope):
                        return True
            return False
        return tuple(requested_scope[:len(stored_scope)]) == tuple(stored_scope)

    def _scope_has_matching_constraints(
        self,
        scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
    ) -> bool:
        if not self._scoped_replay_available():
            return False
        normalized_scope_signature = self._ordered_source_path_signature(
            tuple(scope_signature or tuple())
        )
        if not normalized_scope_signature:
            return False
        cached_presence = self.scoped_branch_constraint_presence_cache.get(
            normalized_scope_signature
        )
        if cached_presence is not None:
            return cached_presence
        cached_matches = self.scoped_branch_constraint_match_cache.get(
            normalized_scope_signature
        )
        if cached_matches is not None:
            present = bool(cached_matches)
            self.scoped_branch_constraint_presence_cache[normalized_scope_signature] = present
            return present
        for stored_scope, items in self.scoped_branch_constraints.items():
            if not items:
                continue
            if self._scope_signature_matches(
                tuple(stored_scope),
                normalized_scope_signature,
            ):
                self.scoped_branch_constraint_presence_cache[normalized_scope_signature] = True
                return True
        self.scoped_branch_constraint_presence_cache[normalized_scope_signature] = False
        return False

    def _matching_scoped_branch_constraints(
        self,
        scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
    ) -> List[BranchConstraintCandidate]:
        if not self._scoped_replay_available():
            return []
        normalized_scope_signature = self._ordered_source_path_signature(
            tuple(scope_signature or tuple())
        )
        if not normalized_scope_signature:
            return []
        cached_matches = self.scoped_branch_constraint_match_cache.get(
            normalized_scope_signature
        )
        if cached_matches is not None:
            return list(cached_matches)
        matches: List[BranchConstraintCandidate] = []
        matching_scopes = []

        for stored_scope, items in self.scoped_branch_constraints.items():
            if not stored_scope or len(stored_scope) > len(normalized_scope_signature):
                continue
            if not self._scope_signature_matches(
                tuple(stored_scope),
                normalized_scope_signature,
            ):
                continue
            matching_scopes.append((len(stored_scope), list(items)))

        matching_scopes.sort(key=lambda item: item[0], reverse=True)
        for _scope_len, items in matching_scopes:
            for item in items:
                normalized = self._normalize_constraint_candidate(item)
                if normalized is not None:
                    matches.append(normalized)

        deduped: List[BranchConstraintCandidate] = []
        seen = set()
        for candidate in matches:
            normalized = candidate.normalized()
            key = (
                normalized.constraint_type,
                int(normalized.address),
                int(normalized.read_pc or 0),
                int(normalized.read_occurrence or 0),
            )
            if key in seen:
                continue
            seen.add(key)
            deduped.append(normalized)
        cached_result = tuple(deduped)
        self.scoped_branch_constraint_match_cache[normalized_scope_signature] = cached_result
        self.scoped_branch_constraint_presence_cache[normalized_scope_signature] = bool(
            cached_result
        )
        return list(cached_result)

    def _apply_scoped_branch_constraints(
        self,
        temp_mmio: EnhancedMMIOHandler,
        scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
        emulator: Optional[IntelligentEmulator] = None,
    ) -> int:
        if not self._scoped_replay_available():
            return 0
        scoped_items = self._matching_scoped_branch_constraints(scope_signature)
        if not scoped_items:
            return 0
        self._apply_temp_mmio_constraints(
            temp_mmio,
            scoped_items,
            emulator=emulator,
            mmio_added_by="branch_mmio_scoped_runtime",
        )
        return len(scoped_items)

    def _new_temp_register_tracer(self, emulator: IntelligentEmulator) -> RegisterTracer:
        return RegisterTracer(
            emulator.uc,
            self.prepared.static_bbs,
            instruction_lookup=self.prepared.instruction_lookup,
            compare_lookup=self.prepared.compare_lookup,
            external_memory_input_predicate=(
                emulator._is_external_input_memory_range
            ),
            external_input_event_source=emulator,
            dynamic_graph_enabled=self._causal_constraint_recovery_available(),
            producer_index=getattr(self.prepared, "producer_index", None),
        )

    @staticmethod
    def _snapshot_provenance_record(snapshot: object) -> Dict[str, object]:
        """Extract lineage using the shared wrapper-aware evidence contract."""
        return snapshot_provenance_record(snapshot)

    def _annotate_replay_run_result(
        self,
        run_result: Dict[str, object],
        snapshot_entry: Optional[PrefixReplaySnapshot] = None,
    ) -> Dict[str, object]:
        """Attach snapshot lineage without changing replay behavior."""
        if not isinstance(run_result, dict):
            return run_result
        if snapshot_entry is None:
            # A reset/entry replay has no snapshot ancestor.  Its complete
            # prefix is the execution reported by IntelligentEmulator.run()
            # itself; attaching a synthetic "missing snapshot" ancestor would
            # incorrectly make every naturalization replay diagnostic.
            run_result.setdefault("entry_derivation", "reset_entry")
            return run_result

        # Read the wrapper first.  PrefixReplaySnapshot carries lineage from
        # the context that selected the underlying BranchSnapshot; consulting
        # only the wrapped object can erase a diagnostic ancestor during a
        # wrapper-to-wrapper replay.
        provenance = self._snapshot_provenance_record(snapshot_entry)
        run_result["snapshot_provenance"] = dict(provenance)
        run_result["prefix_provenance_status"] = str(provenance["status"])
        run_result["prefix_intervention_reasons"] = list(provenance["reasons"])
        run_result["prefix_telemetry_complete"] = bool(
            provenance["telemetry_complete"]
        )
        run_result["snapshot_ancestor_validated"] = bool(
            provenance["snapshot_ancestor_validated"]
        )
        run_result["snapshot_source_execution_id"] = str(
            provenance["execution_id"]
        )
        run_result.setdefault("entry_derivation", "entry_derived_snapshot")
        return run_result

    @staticmethod
    def _materialize_replay_failure_result(
        reason: str,
        *,
        execution_started: bool = False,
        execution_error: Optional[BaseException | str] = None,
        restore_failed: bool = False,
        preflight_failed: bool = False,
    ) -> Dict[str, object]:
        """Return one explicit failure result for every replay boundary.

        Replay callers continue to use their historical tuple interfaces, but
        they must never pass a bare stop string to evidence accounting.  This
        record distinguishes an attempted replay from a missing worker result
        and makes it safe for callers to append post-run diagnostics.
        """
        result: Dict[str, object] = {
            "execution_attempted": True,
            "execution_started": bool(execution_started),
            "execution_completed_normally": False,
            "execution_failed": True,
            "preflight_failed": bool(preflight_failed),
            "restore_failed": bool(restore_failed),
            "execution_telemetry_complete": False,
            "stop_reason": str(reason or "replay_failure"),
        }
        if execution_error is not None:
            result["execution_error"] = str(execution_error)[:2000]
        return result

    @classmethod
    def _normalize_replay_run_result(
        cls,
        value: object,
        *,
        execution_started: bool,
        reason: str = "non_mapping_run_result",
    ) -> Dict[str, object]:
        """Keep replay post-processing total even for legacy adapters."""
        if isinstance(value, Mapping):
            return dict(value)
        return cls._materialize_replay_failure_result(
            reason,
            execution_started=execution_started,
            execution_error=(
                f"emulator.run returned {type(value).__name__}, expected a mapping"
            ),
        )

    @staticmethod
    def _replay_result_has_failure(value: object) -> bool:
        """Return whether a replay result cannot be used as a strict witness.

        Replay callers may still retain the observed BBs for diagnostics and
        scheduling after a teardown or telemetry error.  They must not,
        however, treat the branch trace as a completed path.  Keep this check
        intentionally narrower than ``execution_telemetry_complete`` so older
        adapters that omit the optional completeness bit remain usable when no
        explicit failure was reported.
        """
        if not isinstance(value, Mapping):
            return True
        if any(
            coerce_bool(value.get(key), False)
            for key in (
                "execution_failed",
                "runtime_failure",
                "restore_failed",
                "preflight_failed",
            )
        ):
            return True
        if any(
            value.get(key) not in (None, "", False)
            for key in (
                "execution_error",
                "failure_reason",
                "restore_error",
            )
        ):
            return True
        stop_reason = str(value.get("stop_reason") or "").strip().lower()
        if any(
            token in stop_reason
            for token in (
                "exception",
                "restore_failed",
                "preflight_failed",
                "runtime_crash",
                "segmentation fault",
                "native_crash",
                "unmapped",
                "replay_state_poisoned",
            )
        ):
            return True
        if (
            "execution_started" in value
            and not coerce_bool(value.get("execution_started"), False)
            and coerce_bool(value.get("execution_attempted"), False)
        ):
            return True
        return False

    def _replay_mmio_from_snapshot(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        constraint_items: Iterable[BranchConstraintCandidate],
        replay_instructions: int,
        replay_timeout: int,
    ) -> Tuple[Set[int], Dict[str, object], bool, List[object], List[object]]:
        try:
            emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=None,
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=self._temp_stage_for("branch_mmio_snapshot_replay"),
            )
        except BaseException as exc:
            return (
                set(),
                self._materialize_replay_failure_result(
                    "emulator_create_exception",
                    execution_error=exc,
                ),
                False,
                [],
                [],
            )
        temp_mmio = None
        temp_tracer = None
        try:
            self._configure_emulator_feedback(emulator)
            emulator.enable_branch_snapshot = True
            emulator.enable_loop_intervention = False
            temp_mmio = EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            temp_tracer = self._new_temp_register_tracer(emulator)
        except BaseException as exc:
            cleanup_error = None
            try:
                cleanup_error = self._safe_dispose_temp_emulator(
                    emulator,
                    mmio_handler=temp_mmio,
                    register_tracer=temp_tracer,
                    quarantine=None,
                    stage_name=self._temp_stage_for("branch_mmio_snapshot_replay"),
                )
            except Exception as cleanup_exc:
                cleanup_error = f"{type(cleanup_exc).__name__}: {str(cleanup_exc)[:1000]}"
                logger.debug("snapshot replay setup cleanup failed: %s", cleanup_exc)
            failure = self._materialize_replay_failure_result(
                "replay_setup_exception",
                execution_error=exc,
                preflight_failed=True,
            )
            if cleanup_error:
                failure["cleanup_errors"] = [str(cleanup_error)[:2000]]
                failure["execution_error"] = (
                    f"{failure.get('execution_error', '')}; "
                    f"replay_cleanup_exception: {str(cleanup_error)[:1000]}"
                )[:2000]
            return (
                set(),
                failure,
                False,
                [],
                [],
            )

        restored = False
        covered: Set[int] = set()
        run_result: Dict[str, object] = self._materialize_replay_failure_result(
            "snapshot_restore_failed",
            restore_failed=True,
        )
        initial_state_fingerprint: Dict[str, object] = {}
        replay_events: List[object] = []
        replay_snapshots: List[object] = []
        try:
            restored = self._restore_branch_snapshot(
                emulator,
                snapshot_entry.snapshot,
                lineage_source=snapshot_entry,
            )
            if restored:
                if not self._restore_replay_mmio_state(
                    emulator,
                    temp_mmio,
                    snapshot_entry.mmio_state,
                ):
                    raise RuntimeError(
                        self._replay_mmio_restore_failure_reason(emulator)
                    )
                # Capture the state restored from the snapshot before adding
                # candidate-specific overlays or scoped replay rules.  Those
                # rules are recorded separately and must not make an expected
                # control/candidate pair look like two different starting
                # states.
                initial_state_fingerprint = self._replay_state_fingerprint_summary(
                    emulator=emulator,
                    mmio_handler=temp_mmio,
                    snapshot_entry=snapshot_entry,
                    max_dirty_pages=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_MAX_DIRTY_PAGES", 4),
                    ram_sample_bytes=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_RAM_SAMPLE_BYTES", 128),
                    include_candidate_configuration=False,
                    include_observed_constraint_hits=False,
                )
                self._apply_temp_mmio_constraints(
                    temp_mmio,
                    constraint_items,
                    emulator=emulator,
                )
                self._apply_scoped_branch_constraints(
                    temp_mmio,
                    self._scope_signature_from_snapshot_entry(snapshot_entry),
                    emulator=emulator,
                )
                with self.guided_modules(temp_mmio, temp_tracer), self.capture_coverage(emulator) as temp_covered:
                    try:
                        raw_run_result = emulator.run(
                            entry_point=None,
                            max_instructions=replay_instructions,
                            timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                            preserve_cpu_state=True,
                        )
                        run_result = self._normalize_replay_run_result(
                            raw_run_result,
                            execution_started=True,
                        )
                    except Exception as exc:
                        run_result = self._materialize_replay_failure_result(
                            "execution_exception",
                            execution_started=True,
                            execution_error=exc,
                        )
                    run_result["initial_state_fingerprint_summary"] = (
                        initial_state_fingerprint
                    )
                    self._annotate_replay_run_result(run_result, snapshot_entry)
                    covered = self.validate_coverage(temp_covered)
                run_result["runtime_dynamic_edges_added"] = (
                    self._record_emulator_runtime_successors(emulator)
                )
                run_result["constraint_feedback"] = self._collect_constraint_runtime_feedback(
                    temp_mmio,
                    constraint_items,
                    emulator=emulator,
                )
                run_result["forced_branch_trace_count"] = len(
                    list(getattr(emulator, "forced_branch_trace", []) or [])
                )
                run_result["forced_branch_choices_configured"] = (
                    len(dict(getattr(emulator, "forced_branch_choices", {}) or {}))
                    + len(list(getattr(emulator, "forced_branch_sequence", []) or []))
                )
                run_result["state_fingerprint_summary"] = self._replay_state_fingerprint_summary(
                    emulator=emulator,
                    mmio_handler=temp_mmio,
                    snapshot_entry=snapshot_entry,
                    max_dirty_pages=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_MAX_DIRTY_PAGES", 4),
                    ram_sample_bytes=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_RAM_SAMPLE_BYTES", 128),
                )
                replay_events = list(
                    emulator.branch_snapshot_manager.get_ordered_occurrence_events()
                )
                replay_snapshots = self._ordered_replay_snapshots(emulator)
        except Exception as exc:
            restored = False
            run_result = self._materialize_replay_failure_result(
                "replay_mmio_state_restore_failed"
                if str(exc).startswith("replay_mmio_state_restore_failed")
                else "snapshot_replay_exception",
                execution_error=exc,
                restore_failed=(
                    str(exc).startswith("replay_mmio_state_restore_failed")
                ),
            )
        finally:
            self._finalize_temp_replay(
                emulator,
                mmio_handler=temp_mmio,
                register_tracer=temp_tracer,
                run_result=run_result,
                stage_name=self._temp_stage_for("branch_mmio_snapshot_replay"),
            )

        return covered, run_result, restored, replay_events, replay_snapshots

    def _replay_mmio_from_entry(
        self,
        constraint_items: Iterable[BranchConstraintCandidate],
        replay_instructions: int,
        replay_timeout: int,
    ) -> Tuple[Set[int], Dict[str, object], List[object], List[object]]:
        try:
            emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=None,
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=self._temp_stage_for("branch_mmio_entry_replay"),
            )
        except BaseException as exc:
            return (
                set(),
                self._materialize_replay_failure_result(
                    "emulator_create_exception",
                    execution_error=exc,
                ),
                [],
                [],
            )
        temp_mmio = None
        temp_tracer = None
        try:
            self._configure_emulator_feedback(emulator)
            emulator.enable_branch_snapshot = True
            emulator.enable_loop_intervention = False
            temp_mmio = EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            temp_tracer = self._new_temp_register_tracer(emulator)
        except BaseException as exc:
            cleanup_error = None
            try:
                cleanup_error = self._safe_dispose_temp_emulator(
                    emulator,
                    mmio_handler=temp_mmio,
                    register_tracer=temp_tracer,
                    quarantine=None,
                    stage_name=self._temp_stage_for("branch_mmio_entry_replay"),
                )
            except Exception as cleanup_exc:
                cleanup_error = f"{type(cleanup_exc).__name__}: {str(cleanup_exc)[:1000]}"
                logger.debug("entry replay setup cleanup failed: %s", cleanup_exc)
            failure = self._materialize_replay_failure_result(
                "replay_setup_exception",
                execution_error=exc,
                preflight_failed=True,
            )
            if cleanup_error:
                failure["cleanup_errors"] = [str(cleanup_error)[:2000]]
                failure["execution_error"] = (
                    f"{failure.get('execution_error', '')}; "
                    f"replay_cleanup_exception: {str(cleanup_error)[:1000]}"
                )[:2000]
            return (
                set(),
                failure,
                [],
                [],
            )

        covered: Set[int] = set()
        initial_state_fingerprint: Dict[str, object] = {}
        run_result: Dict[str, object] = {"stop_reason": "not_started"}
        replay_events: List[object] = []
        replay_snapshots: List[object] = []
        try:
            initial_state_fingerprint = (
                self._replay_state_fingerprint_summary(
                    emulator=emulator,
                    mmio_handler=temp_mmio,
                    snapshot_entry=None,
                    max_dirty_pages=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_MAX_DIRTY_PAGES", 4),
                    ram_sample_bytes=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_RAM_SAMPLE_BYTES", 128),
                    include_candidate_configuration=False,
                    include_observed_constraint_hits=False,
                )
            )
            self._apply_temp_mmio_constraints(
                temp_mmio,
                constraint_items,
                emulator=emulator,
            )
            with self.guided_modules(temp_mmio, temp_tracer), self.capture_coverage(emulator) as temp_covered:
                try:
                    raw_run_result = emulator.run(
                        entry_point=self.prepared.entry_point,
                        max_instructions=replay_instructions,
                        timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                        preserve_cpu_state=False,
                    )
                    run_result = self._normalize_replay_run_result(
                        raw_run_result,
                        execution_started=True,
                    )
                except Exception as exc:
                    run_result = self._materialize_replay_failure_result(
                        "execution_exception",
                        execution_started=True,
                        execution_error=exc,
                    )
                run_result["initial_state_fingerprint_summary"] = (
                    initial_state_fingerprint
                )
                self._annotate_replay_run_result(run_result)
                covered = self.validate_coverage(temp_covered)
                run_result["runtime_dynamic_edges_added"] = (
                    self._record_emulator_runtime_successors(emulator)
                )
                run_result["constraint_feedback"] = self._collect_constraint_runtime_feedback(
                    temp_mmio,
                    constraint_items,
                    emulator=emulator,
                )
                run_result["forced_branch_trace_count"] = len(
                    list(getattr(emulator, "forced_branch_trace", []) or [])
                )
                run_result["forced_branch_choices_configured"] = (
                    len(dict(getattr(emulator, "forced_branch_choices", {}) or {}))
                    + len(list(getattr(emulator, "forced_branch_sequence", []) or []))
                )
                run_result["state_fingerprint_summary"] = self._replay_state_fingerprint_summary(
                    emulator=emulator,
                    mmio_handler=temp_mmio,
                    snapshot_entry=None,
                    max_dirty_pages=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_MAX_DIRTY_PAGES", 4),
                    ram_sample_bytes=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_RAM_SAMPLE_BYTES", 128),
                )
                replay_events = list(
                    emulator.branch_snapshot_manager.get_ordered_occurrence_events()
                )
                replay_snapshots = self._ordered_replay_snapshots(emulator)
        finally:
            self._finalize_temp_replay(
                emulator,
                mmio_handler=temp_mmio,
                register_tracer=temp_tracer,
                run_result=run_result,
                stage_name=self._temp_stage_for("branch_mmio_entry_replay"),
            )

        return covered, run_result, replay_events, replay_snapshots

    def _replay_mmio_from_entry_provenance(
        self,
        snapshot_entry: PrefixReplaySnapshot,
        constraint_items: Iterable[BranchConstraintCandidate],
        replay_instructions: int,
        replay_timeout: int,
        ordered: bool = False,
    ) -> Tuple[Set[int], Dict[str, object], List[object], List[object]]:
        source_signature = self._ordered_source_path_signature(
            tuple(
                getattr(snapshot_entry, "source_path_signature", tuple())
                or getattr(snapshot_entry, "prefix_signature", tuple())
                or tuple()
            )
        )
        if not source_signature:
            return (
                set(),
                self._materialize_replay_failure_result(
                    "no_provenance",
                    preflight_failed=True,
                ),
                [],
                [],
            )

        try:
            emulator = self._new_temp_emulator(
                max_snapshots=max(3, self.max_snapshots),
                llm_config_path=None,
                constraint_json_path=self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                stage_name=self._temp_stage_for("branch_mmio_entry_provenance_replay"),
            )
        except BaseException as exc:
            return (
                set(),
                self._materialize_replay_failure_result(
                    "emulator_create_exception",
                    execution_error=exc,
                ),
                [],
                [],
            )
        temp_mmio = None
        temp_tracer = None
        try:
            self._configure_emulator_feedback(emulator)
            emulator.enable_branch_snapshot = True
            emulator.enable_loop_intervention = False
            temp_mmio = EnhancedMMIOHandler(
                emulator.uc,
                self.constraint_file,
                branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
            )
            temp_tracer = self._new_temp_register_tracer(emulator)
            if not self._restore_replay_mmio_state(
                emulator,
                temp_mmio,
                snapshot_entry.mmio_state,
            ):
                raise RuntimeError(
                    self._replay_mmio_restore_failure_reason(emulator)
                )
            # The fingerprint below must describe only the restored reset
            # state.  Candidate overlays, scoped rules, and forced choices are
            # replay inputs and are recorded separately in the audit fields.
            # Keep the historical scoped-over-candidate installation order.
            initial_state_fingerprint = self._replay_state_fingerprint_summary(
                emulator=emulator,
                mmio_handler=temp_mmio,
                snapshot_entry=snapshot_entry,
                max_dirty_pages=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_MAX_DIRTY_PAGES", 4),
                ram_sample_bytes=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_RAM_SAMPLE_BYTES", 128),
                include_candidate_configuration=False,
                include_observed_constraint_hits=False,
            )
            self._apply_scoped_branch_constraints(temp_mmio, source_signature, emulator=emulator)
            self._apply_temp_mmio_constraints(temp_mmio, constraint_items, emulator=emulator)

            if ordered:
                emulator.set_ordered_forced_branch_choices(
                    [(self._ordered_replay_token(key), choice) for key, choice in source_signature]
                )
            else:
                emulator.set_forced_branch_choices(
                    {
                        (int(key[0]), int(key[1])): choice
                        for key, choice in source_signature
                    }
                )
        except BaseException as exc:
            cleanup_error = None
            try:
                cleanup_error = self._safe_dispose_temp_emulator(
                    emulator,
                    mmio_handler=temp_mmio,
                    register_tracer=temp_tracer,
                    quarantine=None,
                    stage_name=self._temp_stage_for("branch_mmio_entry_provenance_replay"),
                )
            except Exception as cleanup_exc:
                cleanup_error = f"{type(cleanup_exc).__name__}: {str(cleanup_exc)[:1000]}"
                logger.debug("provenance replay setup cleanup failed: %s", cleanup_exc)
            failure = self._materialize_replay_failure_result(
                "replay_setup_exception",
                execution_error=exc,
                preflight_failed=True,
            )
            if cleanup_error:
                failure["cleanup_errors"] = [str(cleanup_error)[:2000]]
                failure["execution_error"] = (
                    f"{failure.get('execution_error', '')}; "
                    f"replay_cleanup_exception: {str(cleanup_error)[:1000]}"
                )[:2000]
            return (
                set(),
                failure,
                [],
                [],
            )

        covered: Set[int] = set()
        run_result: Dict[str, object] = {"stop_reason": "not_started"}
        replay_events: List[object] = []
        replay_snapshots: List[object] = []
        try:
            with self.guided_modules(temp_mmio, temp_tracer), self.capture_coverage(emulator) as temp_covered:
                try:
                    raw_run_result = emulator.run(
                        entry_point=self.prepared.entry_point,
                        max_instructions=replay_instructions,
                        timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                        preserve_cpu_state=False,
                    )
                    run_result = self._normalize_replay_run_result(
                        raw_run_result,
                        execution_started=True,
                    )
                except Exception as exc:
                    run_result = self._materialize_replay_failure_result(
                        "execution_exception",
                        execution_started=True,
                        execution_error=exc,
                    )
                run_result["initial_state_fingerprint_summary"] = (
                    initial_state_fingerprint
                )
                self._annotate_replay_run_result(run_result, snapshot_entry)
                covered = self.validate_coverage(temp_covered)
                run_result["runtime_dynamic_edges_added"] = (
                    self._record_emulator_runtime_successors(emulator)
                )
                run_result["constraint_feedback"] = self._collect_constraint_runtime_feedback(
                    temp_mmio,
                    constraint_items,
                    emulator=emulator,
                )
                run_result["forced_branch_trace_count"] = len(
                    list(getattr(emulator, "forced_branch_trace", []) or [])
                )
                run_result["forced_branch_choices_configured"] = (
                    len(dict(getattr(emulator, "forced_branch_choices", {}) or {}))
                    + len(list(getattr(emulator, "forced_branch_sequence", []) or []))
                )
                run_result["state_fingerprint_summary"] = self._replay_state_fingerprint_summary(
                    emulator=emulator,
                    mmio_handler=temp_mmio,
                    snapshot_entry=snapshot_entry,
                    max_dirty_pages=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_MAX_DIRTY_PAGES", 4),
                    ram_sample_bytes=_env_int("LSGEMU_REPLAY_ATTEMPT_FP_RAM_SAMPLE_BYTES", 128),
                )
                replay_events = list(
                    emulator.branch_snapshot_manager.get_ordered_occurrence_events()
                )
                replay_snapshots = self._ordered_replay_snapshots(emulator)
        finally:
            self._finalize_temp_replay(
                emulator,
                mmio_handler=temp_mmio,
                register_tracer=temp_tracer,
                run_result=run_result,
                stage_name=self._temp_stage_for("branch_mmio_entry_provenance_replay"),
            )

        return covered, run_result, replay_events, replay_snapshots

    @staticmethod
    def _naturalization_candidate_copy(
        candidate: BranchConstraintCandidate,
        *,
        value: Optional[int] = None,
        read_occurrence: Optional[int] = None,
        replace_occurrence: bool = False,
        source_suffix: str = "",
    ) -> BranchConstraintCandidate:
        normalized = candidate.normalized()
        return BranchConstraintCandidate(
            constraint_type=normalized.constraint_type,
            address=normalized.address,
            value=(normalized.value if value is None else int(value)),
            read_pc=normalized.read_pc,
            constraint_pc=normalized.constraint_pc,
            source=(
                f"{normalized.source}:{source_suffix}"
                if source_suffix
                else normalized.source
            ),
            read_occurrence=(
                read_occurrence
                if replace_occurrence
                else normalized.read_occurrence
            ),
            input_kind=normalized.input_kind,
            externally_controllable=normalized.externally_controllable,
            dependency_register=normalized.dependency_register,
            dependency_expression=normalized.dependency_expression,
            dependency_group=normalized.dependency_group,
            composite_dependency=normalized.composite_dependency,
            width=normalized.width,
        ).normalized()

    def _naturalization_occurrence_retargets(
        self,
        constraints: Iterable[BranchConstraintCandidate],
        constraint_feedback: Optional[Dict[str, object]],
    ) -> List[Tuple[BranchConstraintCandidate, ...]]:
        normalized = tuple(candidate.normalized() for candidate in constraints or ())
        details = list(dict(constraint_feedback or {}).get("items", []) or [])
        variants: List[Tuple[BranchConstraintCandidate, ...]] = []
        seen = set()
        for index, candidate in enumerate(normalized):
            if candidate.read_pc is None or candidate.read_occurrence is None:
                continue
            detail: Dict[str, object] = {}
            for raw_detail in details:
                if not isinstance(raw_detail, dict):
                    continue
                raw_constraint = dict(raw_detail.get("constraint", {}) or {})
                if (
                    str(raw_constraint.get("type") or "").lower()
                    == candidate.constraint_type
                    and int(_hex_to_int(raw_constraint.get("address")) or -1)
                    == int(candidate.address)
                    and int(_hex_to_int(raw_constraint.get("read_pc")) or -1)
                    == int(candidate.read_pc)
                    and int(raw_constraint.get("read_occurrence") or 0)
                    == int(candidate.read_occurrence)
                ):
                    detail = raw_detail
                    break
            if not detail.get("address_read_seen") or detail.get("exact_value_seen"):
                continue
            observed_occurrence = detail.get("observed_occurrence")
            try:
                observed_occurrence = int(observed_occurrence)
            except (TypeError, ValueError):
                continue
            if observed_occurrence <= 0 or observed_occurrence == int(candidate.read_occurrence):
                continue
            replacement = self._naturalization_candidate_copy(
                candidate,
                read_occurrence=observed_occurrence,
                replace_occurrence=True,
                source_suffix="observed_occurrence_retarget",
            )
            variant = list(normalized)
            variant[index] = replacement
            signature = self._constraint_items_signature(variant)
            if signature in seen:
                continue
            seen.add(signature)
            variants.append(tuple(variant))
        return variants

    def _naturalization_llm_alternatives(
        self,
        branch_key: Tuple[int, int],
        expected_choice: object,
        constraints: Iterable[BranchConstraintCandidate],
        *,
        failure_context: Optional[Dict[str, object]],
        avoid_values_by_site: Dict[Tuple[object, ...], Set[int]],
    ) -> List[Tuple[BranchConstraintCandidate, ...]]:
        if not isinstance(expected_choice, bool):
            return []
        guide = getattr(self, "llm_guide", None)
        if guide is None or not bool(getattr(guide, "use_llm", False)):
            return []
        branch_bb = int(branch_key[0]) & 0xFFFFFFFF
        event = getattr(self, "known_main_branch_events", {}).get(
            (branch_bb, max(1, int(branch_key[1])))
        )
        instruction = self._branch_instruction(branch_bb) or {}
        branch_pc = int(
            instruction.get("address")
            or getattr(event, "branch_pc", 0)
            or branch_bb
        )
        condition = str(
            instruction.get("mnemonic")
            or getattr(event, "condition", "")
            or ""
        ).upper()
        if branch_pc <= 0 or not condition:
            return []

        normalized = tuple(candidate.normalized() for candidate in constraints or ())
        variants: List[Tuple[BranchConstraintCandidate, ...]] = []
        dynamic_result = getattr(self, "last_dynamic_recovery_result", None)
        dynamic_key = getattr(self, "last_dynamic_recovery_key", None)
        proven_unsat_for_exact_slice = bool(
            dynamic_key == (branch_bb, max(1, int(branch_key[1])))
            and getattr(dynamic_result, "solver_status", None) == "unsat"
            and getattr(dynamic_result, "branch_record_match", "exact") == "exact"
            and int(getattr(dynamic_result, "omitted_path_predicates", 0) or 0) == 0
        )
        # 重试反馈（切片升级链）：上一轮候选若来自大模型切片求解且重放失败，
        # 把真实重放结果回写适配器，下一次升级就成为携带「上次值 + 重放结果」
        # 的重试提示词，要求给出替代值与理由。
        llm_slice_solver = getattr(self, "llm_slice_solver", None)
        if (
            llm_slice_solver is not None
            and dynamic_key == (branch_bb, max(1, int(branch_key[1])))
            and str(getattr(dynamic_result, "solver_backend", "")) == "llm"
        ):
            try:
                llm_slice_solver.note_replay_failure(
                    int(branch_pc),
                    max(1, int(branch_key[1])),
                    failure_context,
                )
            except Exception:
                logger.debug("llm_slice 重放反馈记录失败", exc_info=True)

        # The scalar LLM fallback below can only replace one MMIO read.  Give
        # a compound provider a bounded catalog of already observed causal
        # sites first, so checksum/protocol-prefix hypotheses can change more
        # than one input while remaining occurrence-scoped and replay-gated.
        compound_sites: List[BranchConstraintCandidate] = list(normalized)
        try:
            dependency_candidates = self._dependency_constraint_candidates(branch_pc)
        except Exception:
            dependency_candidates = []
        seen_compound_sites = {
            constraint_site_identity(candidate)
            for candidate in compound_sites
        }
        for dependency in dependency_candidates:
            normalized_dependency = dependency.normalized()
            if not normalized_dependency.is_environment_fact:
                continue
            site = constraint_site_identity(normalized_dependency)
            if site in seen_compound_sites:
                continue
            seen_compound_sites.add(site)
            compound_sites.append(normalized_dependency)
            if len(compound_sites) >= max(2, _env_int("LSGEMU_LLM_COMPOUND_MAX_SITES", 8)):
                break

        compound_variants: List[Tuple[BranchConstraintCandidate, ...]] = []
        compound_provider = getattr(guide, "infer_compound_alternative_constraints", None)
        compound_introduces_new_sites = len(compound_sites) > len(normalized)
        if callable(compound_provider) and len(compound_sites) >= 2 and (
            not proven_unsat_for_exact_slice or compound_introduces_new_sites
        ):
            site_descriptions: List[Dict[str, object]] = []
            for site_index, candidate in enumerate(compound_sites):
                site = constraint_site_identity(candidate)
                observed_values = self._naturalization_observed_values(candidate, limit=1)
                current_value = (
                    observed_values[0]
                    if observed_values
                    else int(candidate.value) & 0xFFFFFFFF
                )
                site_descriptions.append({
                    "type": candidate.constraint_type,
                    "kind": candidate.input_kind,
                    "address": candidate.address,
                    "read_pc": candidate.read_pc,
                    "occurrence": candidate.read_occurrence,
                    "width": candidate.width or 32,
                    "current_value": current_value,
                    "failed_values": sorted(
                        int(value) & 0xFFFFFFFF
                        for value in avoid_values_by_site.get(site, set())
                    ),
                    "dependency_register": candidate.dependency_register,
                    "dependency_expression": candidate.dependency_expression,
                    "dependency_group": candidate.dependency_group,
                })
            try:
                compound_assignments = compound_provider(
                    branch_pc,
                    condition,
                    bool(expected_choice),
                    site_descriptions,
                    failure_context=failure_context,
                    max_assignments=max(
                        1,
                        _env_int("LSGEMU_LLM_COMPOUND_MAX_ASSIGNMENTS", 4),
                    ),
                )
            except Exception as exc:
                logger.debug("复合LLM候选生成失败，继续标量回退: %s", exc)
                compound_assignments = []
            if compound_assignments:
                variant = list(normalized)
                for assignment in compound_assignments:
                    try:
                        site_index = int(assignment["site_index"])
                        value = int(assignment["value"])
                    except (KeyError, TypeError, ValueError):
                        continue
                    if site_index < 0 or site_index >= len(compound_sites):
                        continue
                    replacement = self._naturalization_candidate_copy(
                        compound_sites[site_index],
                        value=value,
                        source_suffix="llm_compound_feedback",
                    )
                    replacement_site = constraint_site_identity(replacement)
                    replaced = False
                    for index, existing in enumerate(variant):
                        if constraint_site_identity(existing) == replacement_site:
                            variant[index] = replacement
                            replaced = True
                            break
                    if not replaced:
                        variant.append(replacement)
                if variant != list(normalized):
                    compound_variants.append(tuple(variant))
        if compound_variants:
            # A compound hypothesis already covers the complete causal set;
            # avoid spending another LLM call on scalar alternatives in the
            # same replay attempt.
            return compound_variants
        if proven_unsat_for_exact_slice:
            # A mathematically proven unsat result cannot be repaired by
            # guessing another value for the same complete causal leaf set.
            # New evidence sites were handled by the compound provider above.
            return variants

        for index, candidate in enumerate(normalized):
            if candidate.constraint_type != "mmio":
                continue
            site = constraint_site_identity(candidate)
            avoid = set(avoid_values_by_site.get(site, set()))
            avoid.add(int(candidate.value) & 0xFFFFFFFF)
            candidate_failure_context = dict(failure_context or {})
            candidate_failure_context.update({
                "read_pc": (
                    f"0x{int(candidate.read_pc) & 0xFFFFFFFF:08x}"
                    if candidate.read_pc is not None
                    else None
                ),
                "read_occurrence": candidate.read_occurrence,
                "dependency_register": candidate.dependency_register,
                "dependency_expression": candidate.dependency_expression or None,
                "dependency_group": candidate.dependency_group or None,
            })
            alternative = guide.infer_alternative_constraint(
                branch_pc,
                condition,
                bool(expected_choice),
                candidate.address,
                previous_value=candidate.value,
                failure_context=candidate_failure_context,
                avoid_values=avoid,
                allow_replay_validation_override=True,
            )
            if alternative is None or (int(alternative) & 0xFFFFFFFF) in avoid:
                continue
            replacement = self._naturalization_candidate_copy(
                candidate,
                value=int(alternative) & 0xFFFFFFFF,
                source_suffix="llm_feedback_alternative",
            )
            variant = list(normalized)
            variant[index] = replacement
            variants.append(tuple(variant))
        return variants

    def run_path_naturalization(
        self,
        *,
        time_limit_seconds: Optional[int] = 60,
        max_paths: int = 32,
        max_attempts_per_path: int = 8,
        max_fact_candidates_per_edge: int = 4,
        max_values_per_source: int = 4,
        max_compound_candidates: int = 4,
        replay_instructions: int = 120000,
        replay_timeout: int = 1_000_000,
        phase_name: str = "path_naturalization",
    ) -> Set[int]:
        """Validate forced-path discoveries from reset entry without control forcing.

        Counterfactual replay remains a discovery mechanism.  This stage reuses
        locally paired environment facts or bootstraps a candidate from the
        first mismatching branch dependency, grows a force-free prefix
        monotonically, and promotes an E2 obligation to E1 only after the exact
        dynamic occurrence signature and a discovered target are reproduced.
        """
        if not getattr(self, "semantic_obligation_enabled", True):
            return self._record_phase(
                phase_name,
                set(),
                entry_derivation="disabled_semantic_obligation_ablation",
                counterfactual_control=False,
                skipped=True,
                skip_reason="semantic_obligation_ablation_disabled",
            )
        ledger = self._path_naturalization_ledger()
        started_at = time.time()
        recovery_stats_before = Counter(
            getattr(self, "local_constraint_recovery_stats", Counter()) or Counter()
        )
        dynamic_recovery_stats_before = Counter(
            getattr(self, "dynamic_constraint_recovery_stats", Counter()) or Counter()
        )
        llm_history_start = len(
            list(getattr(getattr(self, "llm_guide", None), "inference_history", []) or [])
        )
        phase_covered: Set[int] = set()
        control_replays = 0
        candidate_replays = 0
        cache_hits = 0
        promoted_paths = 0
        already_natural_paths = 0
        partial_prefix_advances = 0
        force_free_harvests = 0
        facts_considered = 0
        bootstrap_candidates_generated = 0
        bootstrap_candidate_replays = 0
        bootstrap_facts_registered = 0
        bootstrap_edges_without_candidates = 0
        bootstrap_candidate_sets_generated = 0
        compound_candidate_sets_generated = 0
        compound_candidate_replays = 0
        occurrence_retargets_generated = 0
        llm_feedback_candidates_generated = 0
        constraint_refinement_candidates = 0
        constraint_refinement_replays = 0
        accepted_constraint_refinements = 0
        rejected_constraint_refinements = 0
        discovery_scoped_facts_generated = 0
        discovery_prefix_provenance_harvests = 0
        exploratory_prefix_harvests = 0
        contextual_candidate_duplicates_skipped = 0
        blocked_site_candidates_skipped = 0
        upstream_discovery_mismatches_selected = 0
        discovery_prefix_advances = 0
        reason_counts: Counter[str] = Counter()
        failure_category_counts: Counter[str] = Counter()
        attempted_candidate_sets: Set[Tuple[object, ...]] = set()
        blocked_sites: Set[Tuple[object, ...]] = set()
        failed_values: Dict[Tuple[object, ...], Set[int]] = defaultdict(set)
        llm_sites_attempted: Set[Tuple[object, ...]] = set()
        replay_cache: Dict[
            Tuple[Tuple[object, ...], ...],
            Tuple[Set[int], Dict[str, object], List[object], List[object]],
        ] = {}
        naturalization_replay_entries: Dict[int, Dict[str, object]] = {}
        naturalization_execution_records: List[Dict[str, object]] = []

        def budget_exhausted() -> bool:
            if time_limit_seconds is None or int(time_limit_seconds) <= 0:
                return False
            return (time.time() - started_at) >= float(time_limit_seconds)

        def run_from_entry(
            constraints: Iterable[BranchConstraintCandidate],
        ) -> Tuple[
            Tuple[Set[int], Dict[str, object], List[object], List[object]],
            bool,
        ]:
            nonlocal cache_hits
            normalized = tuple(
                candidate.normalized()
                for candidate in constraints or tuple()
                if isinstance(candidate, BranchConstraintCandidate)
            )
            signature = self._constraint_items_signature(normalized)
            cached = replay_cache.get(signature)
            if cached is not None:
                cache_hits += 1
                return cached, True
            result = self._replay_mmio_from_entry(
                normalized,
                replay_instructions=max(1, int(replay_instructions)),
                replay_timeout=max(1, int(replay_timeout)),
            )
            replay_cache[signature] = result
            run_result = result[1]
            naturalization_replay_entries[id(run_result)] = {
                "run_result": run_result,
                "covered_bbs": set(result[0]),
                "execution_id": str(
                    run_result.get("execution_id")
                    or f"{phase_name}.replay-{len(naturalization_replay_entries)}"
                ),
                "record": None,
            }
            return result, False

        def finalize_naturalization_pair(
            control_run_result: Optional[Dict[str, object]],
            result_run_result: Optional[Dict[str, object]],
            evaluation: Mapping[str, object],
        ) -> None:
            """Attach paired-start proof before a replay can own strict BBs."""
            state = state_equivalence_record(
                control_run_result,
                result_run_result,
            )
            pair_complete = bool(
                control_run_result is not None and result_run_result is not None
            )
            same_initial = bool(state.get("same_initial_fingerprint"))
            pair_valid = bool(
                pair_complete
                and same_initial
                and evaluation.get("success")
            )
            reason = str(
                evaluation.get("reason")
                or (
                    "paired_validation_succeeded"
                    if pair_valid
                    else "paired_validation_incomplete"
                )
            )
            seen: Set[int] = set()
            for run_result in (control_run_result, result_run_result):
                if not isinstance(run_result, Mapping):
                    continue
                identity = id(run_result)
                if identity in seen:
                    continue
                seen.add(identity)
                entry = naturalization_replay_entries.get(identity)
                if entry is None:
                    # A legacy adapter may return a fresh mapping for a cached
                    # result.  Do not invent BB ownership without a registered
                    # replay input; the phase remains conservative.
                    continue
                existing = entry.get("record")
                if (
                    isinstance(existing, Mapping)
                    and str(existing.get("status") or "") == VALIDATED_REPLAY
                    and compact_record_is_verified_validated(existing)
                    and not pair_valid
                ):
                    # A previously accepted witness is not invalidated by a
                    # later, weaker pairing of the same concrete replay.
                    continue
                metadata = {
                    "entry_derivation": str(
                        run_result.get("entry_derivation") or "reset_entry"
                    ),
                    "counterfactual_control": False,
                    "paired_validation_required": True,
                    "paired_validation_complete": pair_valid,
                    "paired_initial_state_same": same_initial if pair_complete else False,
                    "paired_validation_reason": reason,
                }
                record = build_execution_evidence_record(
                    phase_name=phase_name,
                    run_result=run_result,
                    covered_bbs=entry.get("covered_bbs", set()),
                    metadata=metadata,
                    execution_id=entry.get("execution_id"),
                )
                record["paired_state_equivalence"] = {
                    "initial_state_fingerprint_available": bool(
                        state.get("initial_state_fingerprint_available")
                    ),
                    "same_initial_fingerprint": same_initial,
                }
                record["paired_validation_reason"] = reason
                if isinstance(existing, dict):
                    existing.clear()
                    existing.update(record)
                else:
                    naturalization_execution_records.append(record)
                    entry["record"] = record

        def finalize_unpaired_naturalization_replays() -> None:
            """Materialize attempts that never reached a paired decision."""
            for entry in naturalization_replay_entries.values():
                if isinstance(entry.get("record"), Mapping):
                    continue
                run_result = entry.get("run_result")
                if not isinstance(run_result, Mapping):
                    continue
                record = build_execution_evidence_record(
                    phase_name=phase_name,
                    run_result=run_result,
                    covered_bbs=entry.get("covered_bbs", set()),
                    metadata={
                        "entry_derivation": str(
                            run_result.get("entry_derivation") or "reset_entry"
                        ),
                        "counterfactual_control": False,
                        "paired_validation_required": True,
                        "paired_validation_complete": False,
                        "paired_initial_state_same": False,
                        "paired_validation_reason": "missing_paired_validation",
                    },
                    execution_id=entry.get("execution_id"),
                )
                naturalization_execution_records.append(record)
                entry["record"] = record

        def force_metadata(run_result: Dict[str, object]) -> Tuple[int, int]:
            """Return ``(actual_hits, configured_choices)`` for one replay.

            A configured choice is a request made to the emulator; it is not
            evidence that the corresponding instruction was encountered or
            that the path was changed.  Naturalization must use only actual
            hits for its force-free checks, while retaining the configured
            count for audit output.
            """
            result = run_result if isinstance(run_result, Mapping) else {}
            actual_hits = 0
            try:
                actual_hits = max(
                    0,
                    int(result.get("forced_branch_trace_count", 0) or 0),
                )
            except (TypeError, ValueError, OverflowError):
                actual_hits = 0
            actual_reasons = set(execution_intervention_reasons(result))
            if "forced_branch" in actual_reasons and actual_hits == 0:
                actual_hits = 1

            configured = 0
            try:
                configured_map = configured_intervention_counts(result)
                configured = max(
                    0,
                    int(configured_map.get("forced_branch", 0) or 0),
                )
            except (TypeError, ValueError, OverflowError):
                configured = 0
            # Preserve the historical scalar when an old adapter does not
            # expose the normalized configuration map.
            try:
                configured = max(
                    configured,
                    int(result.get("forced_branch_choices_configured", 0) or 0),
                )
            except (TypeError, ValueError, OverflowError):
                pass
            return actual_hits, configured

        def candidate_context_key(obligation, branch_key, choice) -> Tuple[object, ...]:
            return (
                tuple(obligation.signature),
                tuple(obligation.discovery_trace_signature),
                (int(branch_key[0]) & 0xFFFFFFFF, max(1, int(branch_key[1]))),
                repr(choice),
                self._constraint_items_signature(obligation.accepted_constraints),
            )

        def attempted_key(context_key, constraints) -> Tuple[object, ...]:
            return (
                *tuple(context_key),
                self._constraint_items_signature(constraints),
            )

        def baseline_values(obligation) -> Dict[Tuple[object, ...], int]:
            return {
                constraint_site_identity(candidate): int(candidate.value)
                & 0xFFFFFFFF
                for candidate in tuple(obligation.accepted_constraints or tuple())
            }

        def repair_scope_signature(
            obligation,
            repair_key,
            *,
            matched_prefix_len: int,
            matched_discovery_prefix_len: int,
        ):
            for trace, matched_len in (
                (
                    obligation.discovery_trace_signature,
                    matched_discovery_prefix_len,
                ),
                (obligation.signature, matched_prefix_len),
            ):
                for index, (key, _choice) in enumerate(trace):
                    if key != repair_key:
                        continue
                    if index <= max(0, int(matched_len)):
                        return trace[:index]
                    break
            return obligation.signature[: max(0, int(matched_prefix_len))]

        def bootstrap_extension_records(
            obligation,
            repair_key,
            repair_choice,
            *,
            context_key,
            scope_signature,
        ):
            nonlocal bootstrap_candidates_generated
            nonlocal bootstrap_candidate_sets_generated
            nonlocal compound_candidate_sets_generated
            nonlocal discovery_scoped_facts_generated
            avoid_values_by_site = {
                site_key: set(values)
                for (stored_context, site_key), values in failed_values.items()
                if stored_context == context_key
            }
            candidate_sets = self._naturalization_bootstrap_candidate_sets(
                repair_key,
                repair_choice,
                max_sources=max(1, int(max_fact_candidates_per_edge)),
                max_values_per_source=max(1, int(max_values_per_source)),
                max_compound_candidates=max(0, int(max_compound_candidates)),
                avoid_values_by_site=avoid_values_by_site,
                baseline_values_by_site=baseline_values(obligation),
            )
            bootstrap_candidate_sets_generated += len(candidate_sets)
            bootstrap_candidates_generated += sum(len(items) for items in candidate_sets)
            compound_candidate_sets_generated += sum(
                1 for items in candidate_sets if len(items) > 1
            )
            expected_prefix = normalize_naturalization_signature(
                tuple(scope_signature or tuple())
            )
            records = []
            conflicts = 0
            for candidate_set in candidate_sets:
                merged_constraints, _merge_reason, _refinements = refine_constraint_sets(
                    obligation.accepted_constraints,
                    candidate_set,
                )
                if merged_constraints is None:
                    conflicts += 1
                    continue
                records.append((
                    merged_constraints,
                    NaturalizationFact(
                        branch_key=repair_key,
                        choice=repair_choice,
                        constraints=tuple(candidate_set),
                        scope_signature=expected_prefix,
                        source_phase=phase_name,
                        strategy=(
                            "entry_causal_dynamic_ssa_bootstrap"
                            if any(
                                "dynamic_ssa" in str(candidate.source or "")
                                for candidate in candidate_set
                            )
                            else "entry_causal_compound_bootstrap"
                            if len(candidate_set) > 1
                            else "entry_causal_value_domain_bootstrap"
                        ),
                        paired_control=False,
                        candidate_consumed=False,
                        local_success=False,
                    ),
                    True,
                ))
                if expected_prefix and expected_prefix == tuple(
                    obligation.discovery_trace_signature[: len(expected_prefix)]
                ):
                    discovery_scoped_facts_generated += 1
            return records, conflicts, candidate_sets

        def record_attempt(
            obligation,
            *,
            kind: str,
            reason: str,
            control_run_result: Dict[str, object],
            result_run_result: Dict[str, object],
            evaluation: Dict[str, object],
            constraints: Iterable[BranchConstraintCandidate],
            fact: Optional[NaturalizationFact] = None,
        ) -> None:
            reason_counts[str(reason or "unknown")] += 1
            obligation.record_reason(str(reason or "unknown"))
            ledger.record_attempt({
                "phase": str(phase_name),
                "kind": str(kind),
                "signature": serialize_naturalization_signature(obligation.signature),
                "signature_length": len(obligation.signature),
                "status": obligation.status,
                "reason": str(reason or "unknown"),
                "matched_prefix_len": int(obligation.matched_prefix_len),
                "matched_discovery_prefix_len": int(
                    obligation.matched_discovery_prefix_len
                ),
                "constraints": [
                    self._serialize_constraint_candidate(candidate)
                    for candidate in constraints or tuple()
                ],
                "fact": (
                    {
                        "branch": f"0x{int(fact.branch_key[0]) & 0xFFFFFFFF:08x}",
                        "occurrence": int(fact.branch_key[1]),
                        "choice": fact.choice,
                        "source_phase": fact.source_phase,
                        "strategy": fact.strategy,
                        "scope_signature": serialize_naturalization_signature(fact.scope_signature),
                    }
                    if fact is not None
                    else None
                ),
                "evaluation": dict(evaluation or {}),
                "control_stop_reason": (control_run_result or {}).get("stop_reason"),
                "result_stop_reason": (result_run_result or {}).get("stop_reason"),
                "constraint_feedback": dict(
                    (result_run_result or {}).get("constraint_feedback", {}) or {}
                ),
            })

        def harvest_force_free_prefix(
            events: Iterable[object],
            snapshots: Iterable[object],
            coverage: Iterable[int],
            signature,
            discovery_signature=tuple(),
            *,
            validated: bool = True,
        ) -> None:
            nonlocal force_free_harvests
            nonlocal discovery_prefix_provenance_harvests
            nonlocal exploratory_prefix_harvests
            event_list = list(events or [])
            snapshot_list = list(snapshots or [])
            normalized_signature = normalize_naturalization_signature(signature)
            normalized_discovery_signature = normalize_naturalization_signature(
                discovery_signature
            )
            occurrence_trace = self._extend_occurrence_signature(
                tuple(),
                event_list,
            )
            source_prefixes = [
                self._occurrence_trace_through_signature(
                    occurrence_trace,
                    candidate_signature,
                    fallback_prefix=candidate_signature,
                )
                for candidate_signature in (
                    normalized_signature,
                    normalized_discovery_signature,
                )
                if candidate_signature
            ]
            source_path_signature = max(
                source_prefixes,
                key=len,
                default=normalized_signature,
            )
            phase_covered.update(self.validate_coverage(coverage))
            evidence_class = EVIDENCE_E1 if validated else EVIDENCE_E2
            if validated:
                self._record_coverage_evidence(EVIDENCE_E1, coverage)
            evidence_signatures = {
                item
                for item in (
                    normalized_signature,
                    normalized_discovery_signature,
                    source_path_signature,
                )
                if item
            }
            for evidence_signature in evidence_signatures:
                ledger.register_path_evidence(
                    evidence_signature,
                    evidence_class,
                    source_phase=phase_name,
                    assumptions=(
                        "force_free_replay" if validated else "exploratory_prefix",
                        "consumed_environment_fact" if validated else "paired_validation_pending",
                    ),
                )
            self._remember_main_branch_events(
                event_list,
                overwrite_existing=False,
                evidence_class=evidence_class,
            )
            self._remember_branch_root_snapshots(
                event_list,
                snapshot_list,
                source_path_signature=source_path_signature,
                evidence_class=evidence_class,
                occurrence_events=event_list,
            )
            self._record_dynamic_successors(event_list)
            if normalized_discovery_signature and (
                len(source_path_signature) > len(normalized_signature)
                or not normalized_signature
            ):
                discovery_prefix_provenance_harvests += 1
            if validated:
                force_free_harvests += 1
            else:
                exploratory_prefix_harvests += 1

        obligations = ledger.pending_obligations(
            max_paths=max(0, int(max_paths)),
            max_attempts_per_path=max(1, int(max_attempts_per_path)),
        )
        selected_obligations = len(obligations)

        for obligation in obligations:
            if budget_exhausted():
                break

            while (
                obligation.attempts < max(1, int(max_attempts_per_path))
                and not budget_exhausted()
            ):
                control_constraints = tuple(obligation.accepted_constraints)
                (control_valid, control_run_result, control_events, control_snapshots), control_cached = run_from_entry(
                    control_constraints
                )
                if not control_cached:
                    control_replays += 1
                control_match = match_path_signature(obligation.signature, control_events)
                control_discovery_match = (
                    match_path_signature(
                        obligation.discovery_trace_signature,
                        control_events,
                    )
                    if obligation.discovery_trace_signature
                    else None
                )
                obligation.matched_prefix_len = max(
                    int(obligation.matched_prefix_len),
                    int(control_match.matched_prefix_len),
                )
                if control_discovery_match is not None:
                    obligation.matched_discovery_prefix_len = max(
                        int(obligation.matched_discovery_prefix_len),
                        int(control_discovery_match.matched_prefix_len),
                    )
                control_trace_count, control_choices_configured = force_metadata(control_run_result)
                control_evaluation = evaluate_force_free_replay(
                    signature=obligation.signature,
                    target_bbs=obligation.target_bbs,
                    discovered_bbs=obligation.discovered_bbs,
                    control_events=control_events,
                    control_coverage=control_valid,
                    result_events=control_events,
                    result_coverage=control_valid,
                    constraints=control_constraints,
                    constraint_feedback=dict(
                        (control_run_result or {}).get("constraint_feedback", {}) or {}
                    ),
                    forced_trace_count=control_trace_count,
                    control_forced_trace_count=control_trace_count,
                    forced_choices_configured=control_choices_configured,
                    control_forced_choices_configured=control_choices_configured,
                    result_run_result=control_run_result,
                    control_run_result=control_run_result,
                )
                finalize_naturalization_pair(
                    control_run_result,
                    control_run_result,
                    control_evaluation,
                )

                if control_evaluation.get("success") and control_evaluation.get("already_natural"):
                    promoted = set(control_evaluation.get("promoted_bbs", []) or [])
                    obligation.matched_prefix_len = len(obligation.signature)
                    ledger.promote(
                        obligation,
                        promoted_bbs=promoted,
                        evidence_class=EVIDENCE_E1,
                        source_phase=phase_name,
                        already_natural=True,
                    )
                    self.naturalized_coverage.update(self.validate_coverage(promoted))
                    harvest_force_free_prefix(
                        control_events,
                        control_snapshots,
                        control_valid,
                        obligation.signature,
                        (
                            obligation.discovery_trace_signature[
                                : int(control_discovery_match.matched_prefix_len)
                            ]
                            if control_discovery_match is not None
                            else tuple()
                        ),
                    )
                    already_natural_paths += 1
                    record_attempt(
                        obligation,
                        kind="control",
                        reason="already_natural_control",
                        control_run_result=control_run_result,
                        result_run_result=control_run_result,
                        evaluation=control_evaluation,
                        constraints=control_constraints,
                    )
                    break

                # A configured-but-unhit choice is harmless.  Only an actual
                # forced trace makes this control execution diagnostic.
                if control_trace_count:
                    obligation.status = "deferred"
                    record_attempt(
                        obligation,
                        kind="control",
                        reason="forced_control_observed_in_validation",
                        control_run_result=control_run_result,
                        result_run_result=control_run_result,
                        evaluation=control_evaluation,
                        constraints=control_constraints,
                    )
                    break

                mismatch_key = control_match.mismatch_key
                if mismatch_key is None:
                    obligation.status = "deferred"
                    record_attempt(
                        obligation,
                        kind="control",
                        reason="target_not_reached_after_complete_signature",
                        control_run_result=control_run_result,
                        result_run_result=control_run_result,
                        evaluation=control_evaluation,
                        constraints=control_constraints,
                    )
                    break

                expected_choice = None
                for expected_key, choice in obligation.signature:
                    if expected_key == mismatch_key:
                        expected_choice = choice
                        break
                repair_key = mismatch_key
                repair_choice = expected_choice
                repair_mismatch_reason = control_match.mismatch_reason
                if (
                    control_discovery_match is not None
                    and control_discovery_match.mismatch_key is not None
                    and control_discovery_match.mismatch_reason
                    == "wrong_natural_choice"
                ):
                    discovery_repair_key = control_discovery_match.mismatch_key
                    discovery_repair_choice = next(
                        (
                            choice
                            for key, choice
                            in obligation.discovery_trace_signature
                            if key == discovery_repair_key
                        ),
                        None,
                    )
                    if discovery_repair_choice is not None:
                        repair_key = discovery_repair_key
                        repair_choice = discovery_repair_choice
                        repair_mismatch_reason = (
                            control_discovery_match.mismatch_reason
                        )
                        upstream_discovery_mismatches_selected += 1
                control_evaluation["causal_alignment"] = {
                    "obligation_mismatch": (
                        {
                            "branch": f"0x{int(mismatch_key[0]) & 0xFFFFFFFF:08x}",
                            "occurrence": int(mismatch_key[1]),
                            "reason": control_match.mismatch_reason,
                        }
                        if mismatch_key is not None
                        else None
                    ),
                    "selected_repair_edge": {
                        "branch": f"0x{int(repair_key[0]) & 0xFFFFFFFF:08x}",
                        "occurrence": int(repair_key[1]),
                        "choice": repair_choice,
                        "reason": repair_mismatch_reason,
                    },
                    "discovery_matched_prefix_len": (
                        int(control_discovery_match.matched_prefix_len)
                        if control_discovery_match is not None
                        else 0
                    ),
                }
                if (
                    control_match.mismatch_reason
                    == "branch_occurrence_not_reached"
                    and repair_key == mismatch_key
                ):
                    bootstrap_edges_without_candidates += 1
                    obligation.status = "blocked_no_fact"
                    alignment_reason = (
                        control_discovery_match.mismatch_reason
                        if control_discovery_match is not None
                        else "missing_discovery_trace"
                    )
                    record_attempt(
                        obligation,
                        kind="control",
                        reason=(
                            "missing_observed_upstream_divergence:"
                            f"{alignment_reason or 'complete_discovery_prefix'}"
                        ),
                        control_run_result=control_run_result,
                        result_run_result=control_run_result,
                        evaluation=control_evaluation,
                        constraints=control_constraints,
                    )
                    break
                extensions, extension_status = ledger.candidate_extensions(
                    obligation,
                    repair_key,
                    repair_choice,
                )
                extension_records = [
                    (merged_constraints, fact, False)
                    for merged_constraints, fact in extensions[
                        : max(1, int(max_fact_candidates_per_edge))
                    ]
                ]
                context_key = candidate_context_key(
                    obligation,
                    repair_key,
                    repair_choice,
                )
                selected_repair_scope = repair_scope_signature(
                    obligation,
                    repair_key,
                    matched_prefix_len=int(control_match.matched_prefix_len),
                    matched_discovery_prefix_len=(
                        int(control_discovery_match.matched_prefix_len)
                        if control_discovery_match is not None
                        else 0
                    ),
                )
                bootstrap_loaded = False
                bootstrap_conflicts = 0
                bootstrap_candidate_sets = []
                if not extension_records:
                    bootstrap_records, bootstrap_conflicts, bootstrap_candidate_sets = (
                        bootstrap_extension_records(
                            obligation,
                            repair_key,
                            repair_choice,
                            context_key=context_key,
                            scope_signature=selected_repair_scope,
                        )
                    )
                    bootstrap_loaded = True
                    extension_records.extend(bootstrap_records)
                if not extension_records:
                    bootstrap_edges_without_candidates += 1
                    obligation.status = "blocked_no_fact"
                    effective_status = (
                        "constraint_conflict"
                        if bootstrap_conflicts and bootstrap_candidate_sets
                        else extension_status
                    )
                    missing_reason = (
                        f"{effective_status}:{repair_mismatch_reason}"
                        if repair_mismatch_reason
                        else effective_status
                    )
                    record_attempt(
                        obligation,
                        kind="control",
                        reason=missing_reason,
                        control_run_result=control_run_result,
                        result_run_result=control_run_result,
                        evaluation=control_evaluation,
                        constraints=control_constraints,
                    )
                    break

                advanced = False
                terminal = False
                extension_queue = deque(extension_records)
                while extension_queue:
                    if obligation.attempts >= max(1, int(max_attempts_per_path)):
                        break
                    merged_constraints, fact, is_bootstrap = extension_queue.popleft()
                    if budget_exhausted():
                        terminal = True
                        break
                    attempt_identity = attempted_key(context_key, merged_constraints)
                    if attempt_identity in attempted_candidate_sets:
                        contextual_candidate_duplicates_skipped += 1
                        continue
                    new_constraints = tuple(getattr(fact, "constraints", tuple()) or tuple())
                    new_sites = [constraint_site_identity(item) for item in new_constraints]
                    if new_sites and all(
                        (context_key, site) in blocked_sites
                        for site in new_sites
                    ):
                        blocked_site_candidates_skipped += 1
                        continue
                    attempted_candidate_sets.add(attempt_identity)
                    facts_considered += 1
                    obligation.attempts += 1
                    _refined_constraints, _refinement_reason, candidate_refinements = (
                        refine_constraint_sets(
                            control_constraints,
                            tuple(fact.constraints or tuple()),
                        )
                    )
                    if candidate_refinements:
                        constraint_refinement_candidates += 1
                    (result_valid, result_run_result, result_events, result_snapshots), result_cached = run_from_entry(
                        merged_constraints
                    )
                    if not result_cached:
                        candidate_replays += 1
                        if candidate_refinements:
                            constraint_refinement_replays += 1
                        if is_bootstrap:
                            bootstrap_candidate_replays += 1
                            if len(tuple(fact.constraints or tuple())) > 1:
                                compound_candidate_replays += 1
                    result_trace_count, result_choices_configured = force_metadata(result_run_result)
                    evaluation = evaluate_force_free_replay(
                        signature=obligation.signature,
                        target_bbs=obligation.target_bbs,
                        discovered_bbs=obligation.discovered_bbs,
                        control_events=control_events,
                        control_coverage=control_valid,
                        result_events=result_events,
                        result_coverage=result_valid,
                        constraints=merged_constraints,
                        constraint_feedback=dict(
                            (result_run_result or {}).get("constraint_feedback", {}) or {}
                        ),
                        forced_trace_count=result_trace_count,
                        control_forced_trace_count=control_trace_count,
                        forced_choices_configured=result_choices_configured,
                        control_forced_choices_configured=control_choices_configured,
                        result_run_result=result_run_result,
                        control_run_result=control_run_result,
                    )
                    finalize_naturalization_pair(
                        control_run_result,
                        result_run_result,
                        evaluation,
                    )
                    evaluation["causal_alignment"] = dict(
                        control_evaluation.get("causal_alignment", {}) or {}
                    )
                    evaluation["constraint_refinements"] = [
                        {
                            "site": list(refinement.site_identity),
                            "previous_value": (
                                f"0x{int(refinement.previous.value) & 0xFFFFFFFF:08x}"
                            ),
                            "replacement_value": (
                                f"0x{int(refinement.replacement.value) & 0xFFFFFFFF:08x}"
                            ),
                            "previous_source": refinement.previous.source or None,
                            "replacement_source": refinement.replacement.source or None,
                        }
                        for refinement in candidate_refinements
                    ]
                    result_match = dict(evaluation.get("result_match", {}) or {})
                    result_prefix_len = int(result_match.get("matched_prefix_len", 0) or 0)
                    result_discovery_match = (
                        match_path_signature(
                            obligation.discovery_trace_signature,
                            result_events,
                        )
                        if obligation.discovery_trace_signature
                        else None
                    )
                    result_discovery_prefix_len = (
                        int(result_discovery_match.matched_prefix_len)
                        if result_discovery_match is not None
                        else 0
                    )
                    previous_prefix_len = max(
                        int(obligation.matched_prefix_len),
                        int(control_match.matched_prefix_len),
                    )
                    previous_discovery_prefix_len = max(
                        int(obligation.matched_discovery_prefix_len),
                        (
                            int(control_discovery_match.matched_prefix_len)
                            if control_discovery_match is not None
                            else 0
                        ),
                    )
                    evaluation["discovery_alignment"] = {
                        "control_matched_prefix_len": (
                            int(control_discovery_match.matched_prefix_len)
                            if control_discovery_match is not None
                            else 0
                        ),
                        "result_matched_prefix_len": (
                            result_discovery_prefix_len
                        ),
                        "expected_count": len(
                            obligation.discovery_trace_signature
                        ),
                        "result_mismatch_reason": (
                            result_discovery_match.mismatch_reason
                            if result_discovery_match is not None
                            else None
                        ),
                    }

                    if evaluation.get("success"):
                        if is_bootstrap and self._remember_naturalization_fact(
                            branch_key=repair_key,
                            branch_choice=repair_choice,
                            constraints=fact.constraints,
                            scope_signature=fact.scope_signature,
                            source_phase=phase_name,
                            strategy=(fact.strategy or "entry_causal_bootstrap"),
                            constraint_feedback=dict(
                                (result_run_result or {}).get("constraint_feedback", {}) or {}
                            ),
                            paired_control=True,
                            local_success=True,
                        ):
                            bootstrap_facts_registered += 1
                        ledger.accept_progress(
                            obligation,
                            constraints=merged_constraints,
                            matched_prefix_len=len(obligation.signature),
                            matched_discovery_prefix_len=(
                                result_discovery_prefix_len
                            ),
                            refinements=candidate_refinements,
                        )
                        accepted_constraint_refinements += len(
                            candidate_refinements
                        )
                        promoted = set(evaluation.get("promoted_bbs", []) or [])
                        ledger.promote(
                            obligation,
                            promoted_bbs=promoted,
                            evidence_class=EVIDENCE_E1,
                            source_phase=phase_name,
                        )
                        self.naturalized_coverage.update(self.validate_coverage(promoted))
                        harvest_force_free_prefix(
                            result_events,
                            result_snapshots,
                            result_valid,
                            obligation.signature,
                            obligation.discovery_trace_signature[
                                :result_discovery_prefix_len
                            ],
                        )
                        promoted_paths += 1
                        record_attempt(
                            obligation,
                            kind="candidate",
                            reason="promoted",
                            control_run_result=control_run_result,
                            result_run_result=result_run_result,
                            evaluation=evaluation,
                            constraints=merged_constraints,
                            fact=fact,
                        )
                        terminal = True
                        break

                    forced_prefix_advanced = (
                        result_prefix_len > previous_prefix_len
                    )
                    discovery_prefix_advanced = (
                        result_discovery_prefix_len
                        > previous_discovery_prefix_len
                    )
                    if (
                        evaluation.get("constraints_consumed")
                        and result_trace_count == 0
                        and (
                            forced_prefix_advanced
                            or discovery_prefix_advanced
                        )
                    ):
                        if is_bootstrap and self._remember_naturalization_fact(
                            branch_key=repair_key,
                            branch_choice=repair_choice,
                            constraints=fact.constraints,
                            scope_signature=fact.scope_signature,
                            source_phase=phase_name,
                            strategy=(fact.strategy or "entry_causal_bootstrap"),
                            constraint_feedback=dict(
                                (result_run_result or {}).get("constraint_feedback", {}) or {}
                            ),
                            paired_control=True,
                            local_success=True,
                        ):
                            bootstrap_facts_registered += 1
                        ledger.accept_progress(
                            obligation,
                            constraints=merged_constraints,
                            matched_prefix_len=result_prefix_len,
                            matched_discovery_prefix_len=(
                                result_discovery_prefix_len
                            ),
                            refinements=candidate_refinements,
                        )
                        accepted_constraint_refinements += len(
                            candidate_refinements
                        )
                        obligation.status = "partial"
                        partial_signature = obligation.signature[:result_prefix_len]
                        harvest_force_free_prefix(
                            result_events,
                            result_snapshots,
                            result_valid,
                            partial_signature,
                            obligation.discovery_trace_signature[
                                :result_discovery_prefix_len
                            ],
                            validated=False,
                        )
                        partial_prefix_advances += 1
                        if discovery_prefix_advanced:
                            discovery_prefix_advances += 1
                        record_attempt(
                            obligation,
                            kind="candidate",
                            reason=(
                                "force_free_prefix_advanced"
                                if forced_prefix_advanced
                                else "force_free_discovery_prefix_advanced"
                            ),
                            control_run_result=control_run_result,
                            result_run_result=result_run_result,
                            evaluation=evaluation,
                            constraints=merged_constraints,
                            fact=fact,
                        )
                        advanced = True
                        break

                    constraint_feedback = dict(
                        (result_run_result or {}).get("constraint_feedback", {}) or {}
                    )
                    failure = classify_replay_failure(
                        evaluation,
                        constraint_feedback,
                        previous_prefix_len=previous_prefix_len,
                        result_prefix_len=result_prefix_len,
                        previous_discovery_prefix_len=previous_discovery_prefix_len,
                        result_discovery_prefix_len=result_discovery_prefix_len,
                    )
                    if candidate_refinements:
                        rejected_constraint_refinements += len(
                            candidate_refinements
                        )
                    failure_category_counts[failure.category] += 1
                    evaluation["failure_classification"] = {
                        "category": failure.category,
                        "retry_values": bool(failure.retry_values),
                        "retry_site": bool(failure.retry_site),
                        "retry_compound": bool(failure.retry_compound),
                    }
                    for candidate in tuple(fact.constraints or tuple()):
                        site = constraint_site_identity(candidate)
                        failed_values[(context_key, site)].add(
                            int(candidate.value) & 0xFFFFFFFF
                        )
                        if not failure.retry_values:
                            blocked_sites.add((context_key, site))

                    if failure.retry_site:
                        occurrence_variants = self._naturalization_occurrence_retargets(
                            tuple(fact.constraints or tuple()),
                            constraint_feedback,
                        )
                        for variant in occurrence_variants:
                            merged_variant, _merge_reason, _variant_refinements = refine_constraint_sets(
                                obligation.accepted_constraints,
                                variant,
                            )
                            if merged_variant is None:
                                continue
                            variant_identity = attempted_key(context_key, merged_variant)
                            if variant_identity in attempted_candidate_sets:
                                continue
                            occurrence_retargets_generated += 1
                            extension_queue.appendleft((
                                merged_variant,
                                NaturalizationFact(
                                    branch_key=repair_key,
                                    choice=repair_choice,
                                    constraints=tuple(variant),
                                    scope_signature=fact.scope_signature,
                                    source_phase=phase_name,
                                    strategy="entry_causal_occurrence_retarget",
                                    paired_control=False,
                                    candidate_consumed=False,
                                    local_success=False,
                                ),
                                True,
                            ))

                    if failure.retry_values and not extension_queue and not bootstrap_loaded:
                        retry_records, _retry_conflicts, _retry_candidate_sets = (
                            bootstrap_extension_records(
                                obligation,
                                repair_key,
                                repair_choice,
                                context_key=context_key,
                                scope_signature=selected_repair_scope,
                            )
                        )
                        bootstrap_loaded = True
                        extension_queue.extend(
                            record for record in retry_records
                            if attempted_key(context_key, record[0])
                            not in attempted_candidate_sets
                        )

                    if failure.retry_values and not extension_queue:
                        llm_input_sites = {
                            constraint_site_identity(candidate)
                            for candidate in tuple(fact.constraints or tuple())
                            if candidate.is_environment_fact
                        }
                        untried_llm_sites = {
                            site for site in llm_input_sites
                            if (context_key, site) not in llm_sites_attempted
                        }
                        if untried_llm_sites:
                            for site in untried_llm_sites:
                                llm_sites_attempted.add((context_key, site))
                            llm_avoid = {
                                site: set(failed_values.get((context_key, site), set()))
                                for site in llm_input_sites
                            }
                            llm_failure_context = {
                                "failure_reason": evaluation.get("reason"),
                                "branch_seen": result_match.get("matched_prefix_len", 0),
                                "matched_constraint_reads": constraint_feedback.get(
                                    "matched_constraint_reads", 0
                                ),
                                "matched_address_reads": constraint_feedback.get(
                                    "matched_address_reads", 0
                                ),
                                "all_constraint_reads_matched": constraint_feedback.get(
                                    "all_constraint_reads_matched", False
                                ),
                                "stop_reason": (result_run_result or {}).get("stop_reason"),
                                "strategy": fact.strategy,
                                "dynamic_solver_status": getattr(
                                    getattr(self, "last_dynamic_recovery_result", None),
                                    "solver_status",
                                    None,
                                ),
                                "dynamic_solver_reason": getattr(
                                    getattr(self, "last_dynamic_recovery_result", None),
                                    "reason",
                                    None,
                                ),
                                "dynamic_fallback_eligible": getattr(
                                    getattr(self, "last_dynamic_recovery_result", None),
                                    "fallback_eligible",
                                    None,
                                ),
                                "dynamic_omitted_path_predicates": getattr(
                                    getattr(self, "last_dynamic_recovery_result", None),
                                    "omitted_path_predicates",
                                    0,
                                ),
                                "dynamic_branch_record_match": getattr(
                                    getattr(self, "last_dynamic_recovery_result", None),
                                    "branch_record_match",
                                    None,
                                ),
                            }
                            for variant in self._naturalization_llm_alternatives(
                                repair_key,
                                repair_choice,
                                tuple(fact.constraints or tuple()),
                                failure_context=llm_failure_context,
                                avoid_values_by_site=llm_avoid,
                            ):
                                merged_variant, _merge_reason, _variant_refinements = refine_constraint_sets(
                                    obligation.accepted_constraints,
                                    variant,
                                )
                                if merged_variant is None:
                                    continue
                                variant_identity = attempted_key(
                                    context_key,
                                    merged_variant,
                                )
                                if variant_identity in attempted_candidate_sets:
                                    continue
                                llm_feedback_candidates_generated += 1
                                extension_queue.append((
                                    merged_variant,
                                    NaturalizationFact(
                                        branch_key=repair_key,
                                        choice=repair_choice,
                                        constraints=tuple(variant),
                                        scope_signature=fact.scope_signature,
                                        source_phase=phase_name,
                                        strategy="entry_causal_llm_feedback",
                                        paired_control=False,
                                        candidate_consumed=False,
                                        local_success=False,
                                    ),
                                    True,
                                ))

                    failure_reason = str(evaluation.get("reason") or "candidate_rejected")
                    obligation.status = "deferred"
                    record_attempt(
                        obligation,
                        kind="candidate",
                        reason=failure_reason,
                        control_run_result=control_run_result,
                        result_run_result=result_run_result,
                        evaluation=evaluation,
                        constraints=merged_constraints,
                        fact=fact,
                    )

                if terminal:
                    break
                if advanced:
                    continue
                break

            if (
                obligation.status not in {"promoted", "already_natural"}
                and obligation.attempts >= max(1, int(max_attempts_per_path))
                and not budget_exhausted()
            ):
                obligation.status = "exhausted"
                obligation.record_reason("attempt_budget_exhausted")

        finalize_unpaired_naturalization_replays()
        elapsed = max(0.0, time.time() - started_at)
        ledger_summary = ledger.summary()
        recovery_stats_after = Counter(
            getattr(self, "local_constraint_recovery_stats", Counter()) or Counter()
        )
        recovery_stats_delta = {
            key: recovery_stats_after.get(key, 0) - recovery_stats_before.get(key, 0)
            for key in sorted(
                set(recovery_stats_before) | set(recovery_stats_after)
            )
        }
        dynamic_recovery_stats_after = Counter(
            getattr(self, "dynamic_constraint_recovery_stats", Counter()) or Counter()
        )
        dynamic_recovery_stats_delta = {
            key: dynamic_recovery_stats_after.get(key, 0)
            - dynamic_recovery_stats_before.get(key, 0)
            for key in sorted(
                set(dynamic_recovery_stats_before) | set(dynamic_recovery_stats_after)
            )
        }
        llm_history = list(
            getattr(getattr(self, "llm_guide", None), "inference_history", []) or []
        )[llm_history_start:]
        naturalization_llm_method_counts = Counter(
            str(item.get("method") or "unknown")
            for item in llm_history
            if isinstance(item, dict)
        )
        return self._record_phase(
            phase_name,
            phase_covered,
            entry_derivation="reset_entry_force_free_path_naturalization",
            counterfactual_control=False,
            selected_obligations=selected_obligations,
            control_replays=control_replays,
            candidate_replays=candidate_replays,
            replay_cache_hits=cache_hits,
            promoted_paths=promoted_paths,
            already_natural_paths=already_natural_paths,
            partial_prefix_advances=partial_prefix_advances,
            force_free_harvests=force_free_harvests,
            exploratory_prefix_harvests=exploratory_prefix_harvests,
            facts_considered=facts_considered,
            bootstrap_candidates_generated=bootstrap_candidates_generated,
            bootstrap_candidate_sets_generated=bootstrap_candidate_sets_generated,
            bootstrap_candidate_replays=bootstrap_candidate_replays,
            bootstrap_facts_registered=bootstrap_facts_registered,
            bootstrap_edges_without_candidates=bootstrap_edges_without_candidates,
            compound_candidate_sets_generated=compound_candidate_sets_generated,
            compound_candidate_replays=compound_candidate_replays,
            occurrence_retargets_generated=occurrence_retargets_generated,
            llm_feedback_candidates_generated=llm_feedback_candidates_generated,
            constraint_refinement_candidates=constraint_refinement_candidates,
            constraint_refinement_replays=constraint_refinement_replays,
            accepted_constraint_refinements=accepted_constraint_refinements,
            rejected_constraint_refinements=rejected_constraint_refinements,
            discovery_scoped_facts_generated=discovery_scoped_facts_generated,
            discovery_prefix_provenance_harvests=(
                discovery_prefix_provenance_harvests
            ),
            contextual_candidate_duplicates_skipped=(
                contextual_candidate_duplicates_skipped
            ),
            blocked_site_candidates_skipped=blocked_site_candidates_skipped,
            failure_category_counts=dict(failure_category_counts),
            local_constraint_recovery=recovery_stats_delta,
            dynamic_constraint_recovery=dynamic_recovery_stats_delta,
            dynamic_tracer_summary=(
                getattr(self, "register_tracer").get_statistics()
                if getattr(self, "register_tracer", None) is not None
                and hasattr(getattr(self, "register_tracer"), "get_statistics")
                else {}
            ),
            # solver 侧探针计数（skipped_* / probes / elapsed 等）与 tracer
            # 侧 differential_probe 字典分开并入，避免键名互相覆盖。
            differential_probe_solver=(
                getattr(self, "differential_probe_solver").get_statistics()
                if getattr(self, "differential_probe_solver", None) is not None
                and hasattr(
                    getattr(self, "differential_probe_solver"),
                    "get_statistics",
                )
                else {}
            ),
            llm_inference_method_counts=dict(naturalization_llm_method_counts),
            llm_actual_calls=sum(
                int(naturalization_llm_method_counts.get(method, 0) or 0)
                for method in (
                    "llm",
                    "llm_rejected",
                    "llm_error",
                    "llm_compound",
                    "llm_compound_error",
                )
            ),
            upstream_discovery_mismatches_selected=(
                upstream_discovery_mismatches_selected
            ),
            discovery_prefix_advances=discovery_prefix_advances,
            reason_counts=dict(reason_counts),
            elapsed_seconds=elapsed,
            time_limit_seconds=time_limit_seconds,
            max_paths=max_paths,
            max_attempts_per_path=max_attempts_per_path,
            max_sources_per_edge=max_fact_candidates_per_edge,
            max_values_per_source=max_values_per_source,
            max_compound_candidates=max_compound_candidates,
            replay_instructions=replay_instructions,
            replay_timeout=replay_timeout,
            ledger_status_counts=dict(ledger_summary.get("status_counts", {}) or {}),
            ledger_promoted_bbs=int(ledger_summary.get("promoted_bbs", 0) or 0),
            execution_records=naturalization_execution_records,
        )

    def _warm_branch_provenance(
        self,
        branch_bb_start: int,
        branch_pc: int,
        snapshot_entries: Iterable[PrefixReplaySnapshot],
        replay_instructions: int,
        replay_timeout: int,
    ) -> Dict[str, object]:
        before = len(self.register_tracer.branch_dependency_snapshots.get(int(branch_pc), []))
        if before > 0:
            return {"attempted": False, "collected": False, "delta": 0, "strategy": "already_cached"}

        short_instructions = min(int(replay_instructions), 15000)
        short_timeout = min(int(replay_timeout), 300000)
        ordered_entries = sorted(
            list(snapshot_entries or []),
            key=lambda entry: (
                0 if str(getattr(entry, "origin", "")) == "prefix" else 1,
                int(getattr(entry, "branch_depth", 0) or 0),
                int(getattr(getattr(entry, "snapshot", None), "order", 0) or 0),
            ),
        )
        attempted = False

        for snapshot_entry in ordered_entries[:2]:
            attempted = True
            _covered, _run_result, restored, _events, _snapshots = self._replay_mmio_from_snapshot(
                snapshot_entry,
                [],
                replay_instructions=short_instructions,
                replay_timeout=short_timeout,
            )
            after = len(self.register_tracer.branch_dependency_snapshots.get(int(branch_pc), []))
            if restored and after > before:
                return {
                    "attempted": True,
                    "collected": True,
                    "delta": after - before,
                    "strategy": f"snapshot:{getattr(snapshot_entry, 'origin', 'unknown')}",
                }

            source_signature = self._ordered_source_path_signature(
                tuple(
                    getattr(snapshot_entry, "source_path_signature", tuple())
                    or getattr(snapshot_entry, "prefix_signature", tuple())
                    or tuple()
                )
            )
            if not source_signature:
                continue

            attempted = True
            _covered, _run_result, _events, _snapshots = self._replay_mmio_from_entry_provenance(
                snapshot_entry,
                [],
                replay_instructions=short_instructions,
                replay_timeout=short_timeout,
                ordered=True,
            )
            after = len(self.register_tracer.branch_dependency_snapshots.get(int(branch_pc), []))
            if after > before:
                return {
                    "attempted": True,
                    "collected": True,
                    "delta": after - before,
                    "strategy": "entry_ordered_provenance",
                }

        after = len(self.register_tracer.branch_dependency_snapshots.get(int(branch_pc), []))
        return {
            "attempted": attempted,
            "collected": after > before,
            "delta": max(0, after - before),
            "strategy": "none",
        }

    def run_mmio_branch_exploration(
        self,
        max_branches: Optional[int] = None,
        time_limit_seconds: Optional[int] = None,
        replay_instructions: int = 50000,
        replay_timeout: int = 1_000_000,
        candidate_window: int = 0x200,
        candidates_per_branch: int = 3,
        allow_default_candidates: bool = False,
        snapshot_variants_per_branch: int = 3,
        skip_zero_potential_directions: bool = True,
        exact_state_first: bool = True,
        exact_state_branch_quota: int = 0,
        phase_name: str = "branch_mmio",
    ) -> Set[int]:
        scoped_replay = self._scoped_replay_available()
        generic_dynamic_fallback = bool(
            not getattr(self, "semantic_obligation_enabled", True)
            and self._causal_constraint_recovery_available()
            and scoped_replay
        )
        if not scoped_replay:
            # A2 uses reset-entry, address-global MMIO candidates only. It
            # must not select a branch-specific snapshot or provenance path.
            exact_state_first = False
        candidate_branches = []
        skipped_no_candidates = 0
        skipped_unsupported = 0
        skipped_zero_potential_branches = 0
        skipped_non_mmio_branches = 0
        initial_known_coverage = set(self.global_coverage)
        successor_map = self._effective_successor_map()
        reachable_cache: Dict[int, Set[int]] = {}
        branch_dependency_stats: Counter[str] = Counter()
        for bb in self.conditional_branches():
            branch_instruction = self._branch_instruction(bb.start_addr)
            if not branch_instruction:
                continue
            branch_pc = branch_instruction["address"]
            condition = _normalize_mnemonic(branch_instruction["mnemonic"])
            if condition in SWITCH_DISPATCH_MNEMONICS:
                skipped_unsupported += 1
                continue
            sources = self._mmio_candidate_sources(branch_pc, candidate_window)
            snapshot_entries = (
                self._branch_snapshot_replay_entries(
                    bb.start_addr,
                    max_variants=snapshot_variants_per_branch,
                )
                if scoped_replay
                else []
            )
            snapshot_precise = (
                self._snapshot_precise_mmio_candidates(
                    branch_pc,
                    snapshot_entries,
                )
                if scoped_replay
                else []
            )
            sources["snapshot"] = snapshot_precise
            precise_candidates = _dedupe_preserve_order(snapshot_precise + sources.get("precise_static", []))
            dependency_constraint_candidates = list(sources.get("dependency_constraints", []) or [])
            if not scoped_replay:
                dependency_constraint_candidates = [
                    candidate
                    for candidate in dependency_constraint_candidates
                    if isinstance(candidate, BranchConstraintCandidate)
                    and candidate.normalized().constraint_type == "mmio"
                ]
                sources["dependency_constraints"] = dependency_constraint_candidates
            for candidate in dependency_constraint_candidates:
                if not isinstance(candidate, BranchConstraintCandidate):
                    continue
                normalized = candidate.normalized()
                branch_dependency_stats["dependency_total"] += 1
                if normalized.constraint_type == "memory":
                    branch_dependency_stats["dependency_memory"] += 1
                elif normalized.constraint_type == "mmio":
                    branch_dependency_stats["dependency_mmio"] += 1
            if any(
                isinstance(candidate, BranchConstraintCandidate)
                and candidate.normalized().constraint_type == "memory"
                for candidate in dependency_constraint_candidates
            ):
                branch_dependency_stats["branches_with_memory_dependency"] += 1
            if any(
                isinstance(candidate, BranchConstraintCandidate)
                and candidate.normalized().constraint_type == "mmio"
                for candidate in dependency_constraint_candidates
            ):
                branch_dependency_stats["branches_with_mmio_dependency"] += 1
            has_non_mmio_dependencies = any(
                isinstance(candidate, BranchConstraintCandidate)
                and str(candidate.constraint_type or "").lower() in {"memory", "mmio"}
                for candidate in dependency_constraint_candidates
            )
            if sources.get("skip_branch_mmio") and not precise_candidates and not has_non_mmio_dependencies:
                skipped_non_mmio_branches += 1
                continue
            real_candidates = precise_candidates if precise_candidates else _dedupe_preserve_order(
                snapshot_precise + sources["merged"]
            )
            if not real_candidates and not allow_default_candidates and not has_non_mmio_dependencies:
                skipped_no_candidates += 1
                continue
            if not real_candidates:
                real_candidates = self._default_mmio_candidates(len(candidate_branches))
            direction_potentials = {
                True: self._branch_direction_static_potential(
                    branch_instruction,
                    True,
                    initial_known_coverage,
                    successor_map,
                    reachable_cache,
                ),
                False: self._branch_direction_static_potential(
                    branch_instruction,
                    False,
                    initial_known_coverage,
                    successor_map,
                    reachable_cache,
                ),
            }
            max_potential = max(
                int(item["static_new_potential"])
                for item in direction_potentials.values()
            )
            if skip_zero_potential_directions and max_potential <= 0:
                skipped_zero_potential_branches += 1
                continue
            candidate_branches.append(
                (bb, branch_instruction, sources, real_candidates, snapshot_entries, direction_potentials)
            )

        def branch_max_static_potential(item) -> int:
            return max(
                int(item[5][True]["static_new_potential"]),
                int(item[5][False]["static_new_potential"]),
            )

        def branch_immediate_uncovered(item) -> bool:
            return bool(item[5][True]["immediate_uncovered"] or item[5][False]["immediate_uncovered"])

        def branch_prefix_entries(item) -> List[PrefixReplaySnapshot]:
            return [
                entry
                for entry in item[4]
                if str(getattr(entry, "origin", "unknown")) == "prefix"
            ]

        def branch_has_provenance(item) -> bool:
            return any(tuple(getattr(entry, "source_path_signature", tuple()) or tuple()) for entry in item[4])

        def branch_dependency_priority(item) -> Tuple[int, int, int, int, int, int]:
            return self._branch_dependency_priority(item)

        candidate_branches.sort(
            key=lambda item: (
                -branch_dependency_priority(item)[0],
                -branch_dependency_priority(item)[1],
                -branch_dependency_priority(item)[2],
                -branch_max_static_potential(item),
                -int(branch_immediate_uncovered(item)),
                -len(item[2].get("precise_static", [])),
                -int(bool(branch_prefix_entries(item))),
                -int(branch_has_provenance(item)),
                -len(item[4]),
                item[0].start_addr not in self.global_coverage,
                -len(item[2].get("snapshot", [])),
                -len(item[2]["dependency"]),
                -len(item[2]["traced"]),
                -len(item[2]["static"]),
                item[0].start_addr,
            ),
        )
        prefix_branch_candidates = [
            item
            for item in candidate_branches
            if branch_prefix_entries(item)
        ]
        prefix_branch_candidates.sort(
            key=lambda item: (
                -branch_dependency_priority(item)[0],
                -branch_dependency_priority(item)[1],
                -len(branch_prefix_entries(item)),
                -max(
                    len(tuple(getattr(entry, "source_path_signature", tuple()) or tuple()))
                    for entry in branch_prefix_entries(item)
                ),
                -len(item[2].get("precise_static", [])),
                -branch_max_static_potential(item),
                -int(branch_immediate_uncovered(item)),
                -len(item[4]),
                item[0].start_addr,
            ),
        )
        base_candidate_branches = list(candidate_branches)
        if max_branches is not None and max_branches > 0:
            base_candidate_branches = base_candidate_branches[:max_branches]
        round_match = re.search(r"round_(\d+)$", str(phase_name or ""))
        branch_mmio_round = int(round_match.group(1)) if round_match else 0
        try:
            observed_retry_min_round = int(
                os.environ.get("LSGEMU_BRANCH_MMIO_OBSERVED_RETRY_MIN_ROUND", "1")
            )
        except ValueError:
            observed_retry_min_round = 1
        try:
            observed_retry_front_limit = int(
                os.environ.get("LSGEMU_BRANCH_MMIO_OBSERVED_RETRY_FRONT_LIMIT", "0")
            )
        except ValueError:
            observed_retry_front_limit = 0
        try:
            observed_retry_direction_limit = int(
                os.environ.get("LSGEMU_BRANCH_MMIO_OBSERVED_RETRY_DIRECTION_LIMIT", "1")
            )
        except ValueError:
            observed_retry_direction_limit = 1
        observed_retry_requested = (
            str(os.environ.get("LSGEMU_BRANCH_MMIO_OBSERVED_RETRY", "0")).strip().lower()
            not in {"", "0", "false", "no"}
        )
        observed_retry_enabled = (
            observed_retry_requested
            and (
                observed_retry_min_round <= 0
                or (branch_mmio_round and branch_mmio_round >= observed_retry_min_round)
            )
        )
        try:
            branch_mmio_success_limit = int(os.environ.get("LSGEMU_BRANCH_MMIO_SUCCESS_LIMIT", "0"))
        except ValueError:
            branch_mmio_success_limit = 0
        try:
            round1_success_limit = int(os.environ.get("LSGEMU_BRANCH_MMIO_ROUND1_SUCCESS_LIMIT", "0"))
        except ValueError:
            round1_success_limit = 0
        phase_success_limit = branch_mmio_success_limit
        if branch_mmio_round == 1 and round1_success_limit > 0:
            phase_success_limit = round1_success_limit
        observed_retry_candidate_branches = []
        if observed_retry_enabled:
            observed_retry_candidate_branches = [
                item
                for item in base_candidate_branches
                if item[4]
            ]
        if observed_retry_front_limit > 0:
            prioritized_observed_retry_candidate_branches = sorted(
                observed_retry_candidate_branches,
                key=lambda item: (
                    -int(bool(branch_prefix_entries(item))),
                    -int(branch_has_provenance(item)),
                    -len(item[4]),
                    -branch_max_static_potential(item),
                    -int(branch_immediate_uncovered(item)),
                    item[0].start_addr,
                ),
            )
            front_observed_retry_candidate_branches = prioritized_observed_retry_candidate_branches[:observed_retry_front_limit]
            front_ids = {id(item) for item in front_observed_retry_candidate_branches}
            tail_observed_retry_candidate_branches = [
                item
                for item in observed_retry_candidate_branches
                if id(item) not in front_ids
            ]
        else:
            front_observed_retry_candidate_branches = []
            tail_observed_retry_candidate_branches = observed_retry_candidate_branches

        exact_state_candidate_branches: List[Tuple[object, Dict[str, object], Dict[str, List[int]], List[int], List[PrefixReplaySnapshot], Dict[bool, Dict[str, object]]]] = []
        exact_state_branches_scheduled = 0
        if exact_state_first and prefix_branch_candidates:
            if exact_state_branch_quota and exact_state_branch_quota > 0:
                exact_state_budget = min(len(prefix_branch_candidates), exact_state_branch_quota)
            elif max_branches is not None and max_branches > 0:
                exact_state_budget = min(
                    len(prefix_branch_candidates),
                    1 if max_branches <= 8 else max(1, max_branches // 4),
                )
            else:
                exact_state_budget = min(len(prefix_branch_candidates), 4)
            exact_state_candidate_branches = prefix_branch_candidates[:exact_state_budget]
            exact_state_branches_scheduled = len(exact_state_candidate_branches)

        branch_work_items = [
            ("exact_state", item)
            for item in exact_state_candidate_branches
        ] + [
            ("general_retry", item)
            for item in front_observed_retry_candidate_branches
        ] + [
            ("general", item)
            for item in base_candidate_branches
        ] + [
            ("general_retry", item)
            for item in tail_observed_retry_candidate_branches
        ]

        start_time = time.time()
        phase_covered: Set[int] = set()
        changed_branch_starts: Set[int] = set()
        explored_directions = 0
        constraints_applied = 0
        llm_calls_before = len(self.llm_guide.get_inference_history())
        snapshot_replays = 0
        snapshot_successes = 0
        snapshot_prefix_replays = 0
        snapshot_root_replays = 0
        snapshot_direct_replays = 0
        snapshot_restore_failures = 0
        entry_fallback_replays = 0
        entry_provenance_replays = 0
        entry_provenance_successes = 0
        entry_ordered_provenance_replays = 0
        entry_ordered_provenance_successes = 0
        skipped_zero_potential_directions_count = 0
        skipped_exhausted_weak_directions = 0
        exact_state_directions_replayed = 0
        exact_state_snapshot_replays = 0
        exact_state_snapshot_successes = 0
        exact_state_successful_branch_starts: Set[int] = set()
        exact_state_generalized_branch_starts: Set[int] = set()
        persisted_constraints = 0
        persisted_constraint_write_skips = 0
        persisted_multi_candidate_skips = 0
        scoped_constraints_added = 0
        persisted_exact_state_skips = 0
        exact_state_scoped_constraints_added = 0
        persistence_validation_replays = 0
        persistence_validation_successes = 0
        persistence_validation_already_success = 0
        persistence_validation_scoped_fallbacks = 0
        harvested_branch_events = 0
        harvested_branch_root_snapshots = 0
        harvested_dynamic_successor_edges = 0
        harvested_seed_roots = 0
        harvested_child_tasks = 0
        harvested_observed_direction_updates = 0
        skipped_observed_directions = 0
        deferred_observed_directions = 0
        retried_observed_directions = 0
        persisted_same_direction_skips = 0
        persisted_suspicious_value_skips = 0
        persisted_constraint_details: List[Dict[str, object]] = []
        scoped_constraint_debug_records: List[Dict[str, object]] = []
        attempt_failure_reasons: Counter[str] = Counter()
        attempt_records: List[Dict[str, object]] = []
        hypothesis_audit_records: List[Dict[str, object]] = []
        hypothesis_generated_candidate_ids: Set[str] = set()
        hypothesis_audit_indices_by_candidate: Dict[str, List[int]] = defaultdict(list)
        attempt_source_stats: Counter[str] = Counter()
        replayed_attempt_source_stats: Counter[str] = Counter()
        successful_attempt_source_stats: Counter[str] = Counter()
        attempt_new_bbs_vs_control_by_source: Counter[str] = Counter()
        attempt_new_bbs_vs_global_by_source: Counter[str] = Counter()
        attempt_new_bbs_vs_phase_by_source: Counter[str] = Counter()
        control_replays = 0
        control_restore_failures = 0
        control_success_without_constraint = 0
        provenance_warmup_attempts = 0
        provenance_warmup_successes = 0
        built_constraint_stats: Counter[str] = Counter()
        built_constraint_source_stats: Counter[str] = Counter()
        replay_constraint_stats: Counter[str] = Counter()
        replay_constraint_source_stats: Counter[str] = Counter()
        successful_constraint_source_stats: Counter[str] = Counter()
        persisted_constraint_source_stats: Counter[str] = Counter()
        scoped_constraint_source_stats: Counter[str] = Counter()
        inference_method_stats: Counter[str] = Counter()
        inference_cache_method_stats: Counter[str] = Counter()
        inference_metric_stats: Counter[str] = Counter()
        replay_mode_pruned_attempts = 0
        replay_window_skips = 0
        snapshot_control_cache: Dict[
            Tuple[object, ...],
            Tuple[Set[int], Dict[str, object], bool, List[object]],
        ] = {}
        provenance_control_cache: Dict[
            Tuple[object, ...],
            Tuple[Set[int], Dict[str, object], List[object]],
        ] = {}
        entry_fallback_control_cache: Dict[
            str,
            Tuple[Set[int], Dict[str, object], List[object]],
        ] = {}
        constraint_stats_before = self._constraint_file_stats()
        direction_attempt_outcomes: Optional[List[str]] = None
        provenance_warmup_cache: Dict[int, Dict[str, object]] = {}
        candidate_inference_metadata: Dict[Tuple[object, ...], Dict[str, object]] = {}
        llm_second_opinion_calls = 0
        enable_branch_mmio_harvest = (
            str(os.environ.get("LSGEMU_BRANCH_MMIO_HARVEST", "0")).strip().lower()
            not in {"", "0", "false", "no"}
        )
        enable_llm_second_opinion = (
            self.use_llm
            and str(os.environ.get("LSGEMU_BRANCH_MMIO_LLM_SECOND_OPINION", "1")).strip().lower()
            not in {"", "0", "false", "no"}
        )
        try:
            llm_second_opinion_budget = int(
                float(os.environ.get("LSGEMU_BRANCH_MMIO_LLM_SECOND_OPINION_BUDGET", "8") or 8)
            )
        except (TypeError, ValueError):
            llm_second_opinion_budget = 8
        harvest_persisted_branch_mmio = (
            str(os.environ.get("LSGEMU_BRANCH_MMIO_HARVEST_PERSISTED", "1")).strip().lower()
            not in {"", "0", "false", "no"}
        )
        harvest_observed_retry_branch_mmio = (
            str(os.environ.get("LSGEMU_BRANCH_MMIO_OBSERVED_RETRY_HARVEST", "0")).strip().lower()
            not in {"", "0", "false", "no"}
        )

        def _meta_int(meta: Dict[str, object], key: str) -> int:
            try:
                return int(meta.get(key, 0) or 0)
            except (TypeError, ValueError):
                return 0

        def record_inference_metadata() -> Dict[str, object]:
            meta = getattr(self.llm_guide, "last_inference_metadata", None)
            if not isinstance(meta, dict):
                meta = {}
            method = str(meta.get("inference_method") or "unknown")
            inference_method_stats[method] += 1
            if bool(meta.get("cache_hit")):
                cached_method = str(meta.get("cached_inference_method") or method)
                inference_cache_method_stats[cached_method] += 1
                inference_metric_stats["inference_cache_hits"] += 1
            inference_metric_stats["inference_history_entries"] += _meta_int(meta, "history_entries")
            inference_metric_stats["llm_actual_calls"] += _meta_int(meta, "actual_llm_calls")
            inference_metric_stats["llm_successful_values"] += _meta_int(meta, "llm_successful_values")
            inference_metric_stats["llm_rejected"] += _meta_int(meta, "llm_rejected")
            inference_metric_stats["llm_errors"] += _meta_int(meta, "llm_errors")
            inference_metric_stats["rule_inference_entries"] += _meta_int(meta, "rule_inference_entries")
            return meta

        def source_label_from_inference(prefix: str, meta: Dict[str, object], default_suffix: str = "rules") -> str:
            method = str(meta.get("inference_method") or default_suffix or "unknown")
            origin_method = str(meta.get("cached_inference_method") or method)
            cache_suffix = "_cache" if bool(meta.get("cache_hit")) else ""
            if origin_method in {"llm", "llm_alternative"}:
                suffix = f"llm{cache_suffix}"
            elif origin_method == "rules":
                suffix = f"rules{cache_suffix}"
            elif "rules" in origin_method:
                # The value came from deterministic fallback after an LLM failure/rejection.
                # Do not label it as LLM-derived for accepted-constraint attribution.
                suffix = f"rules_fallback{cache_suffix}"
            else:
                suffix = f"{default_suffix or 'unknown'}{cache_suffix}"
            return f"{prefix}_{suffix}"

        def llm_second_opinion_failure_context(
            *,
            target_direction: bool,
            source: str,
            read_pc: Optional[int],
            value: Optional[int],
        ) -> Dict[str, object]:
            return {
                "outcome": "pre_replay_second_opinion",
                "strategy": "candidate_generation",
                "target_direction": "taken" if target_direction else "not-taken",
                "source": source,
                "read_pc": f"0x{int(read_pc) & 0xFFFFFFFF:08x}" if read_pc is not None else None,
                "previous_value": f"0x{int(value) & 0xFFFFFFFF:08x}" if value is not None else None,
                "note": "generate an additional semantic value; replay/control validation decides acceptance",
            }

        def maybe_add_llm_second_opinion(
            *,
            built: List[BranchConstraintCandidate],
            seen: Set[Tuple[str, int, int, int, int]],
            constraint_type: str,
            address: int,
            read_pc: Optional[int],
            read_occurrence: Optional[int],
            previous_value: Optional[int],
            target_direction: bool,
            source_prefix: str,
        ) -> None:
            nonlocal llm_second_opinion_calls
            if not enable_llm_second_opinion:
                return
            if llm_second_opinion_budget > 0 and llm_second_opinion_calls >= llm_second_opinion_budget:
                return
            if constraint_type != "mmio":
                return
            llm_second_opinion_calls += 1
            alternative = self.llm_guide.infer_alternative_constraint(
                branch_pc,
                condition,
                target_direction,
                int(address),
                previous_value=previous_value,
                failure_context=llm_second_opinion_failure_context(
                    target_direction=target_direction,
                    source=source_prefix,
                    read_pc=read_pc,
                    value=previous_value,
                ),
                avoid_values=[previous_value] if previous_value is not None else [],
            )
            inference_meta = record_inference_metadata()
            if alternative is None:
                return
            candidate = BranchConstraintCandidate(
                constraint_type="mmio",
                address=int(address),
                value=int(alternative) & 0xFFFFFFFF,
                read_pc=int(read_pc) if read_pc is not None else None,
                constraint_pc=self._constraint_compare_pc(branch_pc),
                source=f"{source_prefix}_{source_label_from_inference('second_opinion', inference_meta, 'llm')}",
                read_occurrence=read_occurrence,
                input_kind="mmio",
                externally_controllable=True,
            ).normalized()
            dedupe_key = (
                candidate.constraint_type,
                candidate.address,
                int(candidate.read_pc or 0),
                int(candidate.read_occurrence or 0),
                candidate.value,
            )
            if dedupe_key in seen:
                return
            seen.add(dedupe_key)
            remember_candidate_inference(candidate, inference_meta)
            record_built_candidate(candidate)
            built.append(candidate)

        def record_built_candidate(candidate: BranchConstraintCandidate) -> None:
            normalized = candidate.normalized()
            built_constraint_stats[f"built_{normalized.constraint_type}"] += 1
            built_constraint_source_stats[normalized.source or "unknown"] += 1

        def record_candidate_source(counter: Counter[str], candidate: BranchConstraintCandidate) -> None:
            normalized = candidate.normalized()
            counter[normalized.source or "unknown"] += 1

        def remember_candidate_inference(candidate: BranchConstraintCandidate, meta: Dict[str, object]) -> None:
            if not isinstance(meta, dict) or not meta:
                return
            signature = self._constraint_items_signature([candidate])
            if not signature:
                return
            candidate_inference_metadata[signature[0]] = {
                "inference_method": meta.get("inference_method"),
                "cached_inference_method": meta.get("cached_inference_method"),
                "cache_hit": bool(meta.get("cache_hit")),
                "actual_llm_calls": int(meta.get("actual_llm_calls", 0) or 0),
                "llm_successful_values": int(meta.get("llm_successful_values", 0) or 0),
                "llm_rejected": int(meta.get("llm_rejected", 0) or 0),
                "llm_errors": int(meta.get("llm_errors", 0) or 0),
                "latest_root_cause": meta.get("latest_root_cause"),
                "latest_recommended_action": meta.get("latest_recommended_action"),
                "root_cause_counts": dict(meta.get("root_cause_counts", {}) or {}),
                "recommended_action_counts": dict(meta.get("recommended_action_counts", {}) or {}),
            }

        def constraint_inference_metadata(candidate) -> Dict[str, object]:
            normalized = self._normalize_constraint_candidate(candidate)
            if normalized is None:
                return {}
            signature = self._constraint_items_signature([normalized])
            if not signature:
                return {}
            return dict(candidate_inference_metadata.get(signature[0], {}) or {})

        def source_counter_total(counter: Counter[str], marker: str) -> int:
            return sum(int(value) for key, value in counter.items() if marker in str(key))

        def serialized_constraint_source_counts(items: Iterable[object]) -> Counter[str]:
            counts: Counter[str] = Counter()
            for item in list(items or []):
                source = None
                if isinstance(item, BranchConstraintCandidate):
                    source = item.normalized().source
                elif isinstance(item, dict):
                    source = item.get("source")
                source_text = str(source or "unknown")
                counts[source_text] += 1
            if not counts:
                counts["none"] += 1
            return counts

        def source_counts_has_marker(counts: Counter[str], marker: str) -> bool:
            marker_text = str(marker)
            return any(marker_text in str(source) for source in counts)

        def hex_bb_sample(values: Iterable[int], limit: int = 32) -> List[str]:
            return [f"0x{int(value) & 0xFFFFFFFF:08x}" for value in sorted(set(values))[:limit]]

        def coverage_attribution_record(
            *,
            control_valid_bbs: Optional[Set[int]] = None,
            result_valid_bbs: Optional[Set[int]] = None,
            phase_known_before: Optional[Set[int]] = None,
        ) -> Dict[str, object]:
            control_set = {int(value) for value in (control_valid_bbs or set())}
            result_set = {int(value) for value in (result_valid_bbs or set())}
            global_before_set = {int(value) for value in self.global_coverage}
            phase_before_set = {int(value) for value in (phase_known_before or global_before_set)}
            new_vs_control = result_set - control_set
            new_vs_global = result_set - global_before_set
            new_vs_phase = result_set - phase_before_set
            return {
                "control_valid_bbs": len(control_set),
                "result_valid_bbs": len(result_set),
                "new_bbs_vs_control": len(new_vs_control),
                "new_bbs_vs_global": len(new_vs_global),
                "new_bbs_vs_phase_before": len(new_vs_phase),
                "new_bbs_vs_control_sample": hex_bb_sample(new_vs_control),
                "new_bbs_vs_global_sample": hex_bb_sample(new_vs_global),
                "new_bbs_vs_phase_before_sample": hex_bb_sample(new_vs_phase),
            }

        def _current_desired_successor_hex() -> Optional[str]:
            try:
                if desired_successor is None:
                    return None
                return f"0x{int(desired_successor) & 0xFFFFFFFF:08x}"
            except Exception:
                return None

        def _current_branch_start_hex() -> Optional[str]:
            try:
                return f"0x{int(branch_start) & 0xFFFFFFFF:08x}"
            except Exception:
                return None

        def _candidate_scope_record(serialized_item: Dict[str, object]) -> Dict[str, object]:
            read_pc = serialized_item.get("read_pc")
            constraint_pc = serialized_item.get("constraint_pc")
            if read_pc:
                scope_class = "read_pc_scoped"
            elif constraint_pc:
                scope_class = "constraint_pc_scoped"
            else:
                scope_class = "address_or_global"
            return {
                "class": scope_class,
                "constraint_type": serialized_item.get("type") or "unknown",
                "address": serialized_item.get("address"),
                "read_pc": read_pc,
                "constraint_pc": constraint_pc,
            }

        def _candidate_source(serialized_item: Dict[str, object]) -> str:
            return str(serialized_item.get("source") or "unknown")

        def _target_obligation_record(
            *,
            work_phase: Optional[str],
            strategy: Optional[str],
            branch_pc_value: object,
            target_direction: object,
        ) -> Dict[str, object]:
            # This is the replay acceptance/audit target, not an obligation-
            # discovery queue. It remains in every ablation to preserve RQ4.
            if isinstance(branch_pc_value, str):
                branch_pc_text = branch_pc_value
            else:
                try:
                    branch_pc_text = f"0x{int(branch_pc_value) & 0xFFFFFFFF:08x}"
                except Exception:
                    branch_pc_text = None
            if isinstance(target_direction, str):
                direction_text = target_direction
            else:
                direction_text = "taken" if bool(target_direction) else "not-taken"
            return {
                "kind": "branch_direction",
                "phase": str(phase_name),
                "work_phase": str(work_phase or ""),
                "strategy": str(strategy or ""),
                "branch_bb": _current_branch_start_hex(),
                "branch_pc": branch_pc_text,
                "target_direction": direction_text,
                "desired_successor": _current_desired_successor_hex(),
            }

        def _hypothesis_candidate_id(
            serialized_item: Dict[str, object],
            target_obligation: Dict[str, object],
        ) -> str:
            stable = {
                "phase": str(phase_name),
                "branch_pc": target_obligation.get("branch_pc"),
                "target_direction": target_obligation.get("target_direction"),
                "type": serialized_item.get("type"),
                "address": serialized_item.get("address"),
                "value": serialized_item.get("value"),
                "read_pc": serialized_item.get("read_pc"),
                "constraint_pc": serialized_item.get("constraint_pc"),
                "source": serialized_item.get("source"),
            }
            digest = hashlib.sha1(json.dumps(stable, sort_keys=True).encode("utf-8")).hexdigest()[:16]
            return f"hyp_{digest}"

        def _hypothesis_group_id(
            serialized_items: List[Dict[str, object]],
            target_obligation: Dict[str, object],
            strategy: Optional[str],
        ) -> str:
            stable = {
                "phase": str(phase_name),
                "target_obligation": target_obligation,
                "strategy": str(strategy or ""),
                "items": serialized_items,
            }
            digest = hashlib.sha1(json.dumps(stable, sort_keys=True).encode("utf-8")).hexdigest()[:16]
            return f"group_{digest}"

        def _replay_summary(eval_record: object, stop_reason: object) -> Dict[str, object]:
            eval_dict = eval_record if isinstance(eval_record, dict) else {}
            available = bool(eval_dict or stop_reason)
            return {
                "available": available,
                "success": bool(eval_dict.get("success")) if eval_dict else False,
                "branch_seen": bool(eval_dict.get("branch_seen")) if eval_dict else False,
                "desired_successor_seen": bool(eval_dict.get("desired_successor_seen")) if eval_dict else False,
                "failure_reason": eval_dict.get("failure_reason") if eval_dict else None,
                "observed_directions": eval_dict.get("observed_directions") if eval_dict else None,
                "stop_reason": stop_reason,
            }

        def _new_bb_delta_record(coverage: object) -> Dict[str, object]:
            coverage_dict = coverage if isinstance(coverage, dict) else {}
            return {
                "control_valid_bbs": int(coverage_dict.get("control_valid_bbs", 0) or 0),
                "candidate_valid_bbs": int(coverage_dict.get("result_valid_bbs", 0) or 0),
                "new_bbs_vs_control": int(coverage_dict.get("new_bbs_vs_control", 0) or 0),
                "new_bbs_vs_global": int(coverage_dict.get("new_bbs_vs_global", 0) or 0),
                "new_bbs_vs_phase_before": int(coverage_dict.get("new_bbs_vs_phase_before", 0) or 0),
                "new_bbs_vs_control_sample": list(coverage_dict.get("new_bbs_vs_control_sample", []) or []),
                "new_bbs_vs_global_sample": list(coverage_dict.get("new_bbs_vs_global_sample", []) or []),
                "new_bbs_vs_phase_before_sample": list(coverage_dict.get("new_bbs_vs_phase_before_sample", []) or []),
            }

        def _record_generated_hypothesis(
            candidate: object,
            *,
            work_phase: str,
            branch_pc_value: int,
            target_direction: bool,
        ) -> None:
            serialized_item = self._serialize_constraint_candidate(candidate)
            target_obligation = _target_obligation_record(
                work_phase=work_phase,
                strategy="candidate_generation",
                branch_pc_value=branch_pc_value,
                target_direction=target_direction,
            )
            candidate_id = _hypothesis_candidate_id(serialized_item, target_obligation)
            if candidate_id in hypothesis_generated_candidate_ids:
                return
            hypothesis_generated_candidate_ids.add(candidate_id)
            hypothesis_audit_records.append({
                "schema": "hypothesis_audit.v1",
                "stage": "generated",
                "candidate_id": candidate_id,
                "candidate_group_id": None,
                "source": _candidate_source(serialized_item),
                "scope": _candidate_scope_record(serialized_item),
                "target_obligation": target_obligation,
                "candidate": serialized_item,
                "generated": True,
                "replayed": False,
                "control_replay": {"available": False},
                "candidate_replay": {"available": False},
                "new_bb_delta": _new_bb_delta_record({}),
                "accepted_by_replay": False,
                "persisted": False,
                "scoped": False,
                "accept_reason": None,
                "reject_reason": None,
                "persistence_outcome": None,
            })

        def _record_hypothesis_replay_audit(record: Dict[str, object]) -> None:
            raw_items = record.get("constraint_items") if isinstance(record.get("constraint_items"), list) else []
            serialized_items = [
                dict(item)
                for item in raw_items
                if isinstance(item, dict)
            ]
            if not serialized_items:
                return
            target_obligation = _target_obligation_record(
                work_phase=str(record.get("phase") or ""),
                strategy=str(record.get("strategy") or ""),
                branch_pc_value=record.get("branch_pc"),
                target_direction=record.get("target_direction"),
            )
            group_id = _hypothesis_group_id(
                serialized_items,
                target_obligation,
                str(record.get("strategy") or ""),
            )
            result_eval = record.get("result_eval") if isinstance(record.get("result_eval"), dict) else {}
            control_eval = record.get("control_eval") if isinstance(record.get("control_eval"), dict) else {}
            outcome_text = str(record.get("outcome") or "unknown")
            replayed = bool(result_eval or control_eval)
            success = outcome_text == "success" or bool(result_eval.get("success"))
            reject_reason = None if success else outcome_text
            if not success and not reject_reason:
                reject_reason = str(result_eval.get("failure_reason") or "unknown")
            for serialized_item in serialized_items:
                candidate_id = _hypothesis_candidate_id(serialized_item, target_obligation)
                entry = {
                    "schema": "hypothesis_audit.v1",
                    "stage": "replay",
                    "candidate_id": candidate_id,
                    "candidate_group_id": group_id,
                    "source": _candidate_source(serialized_item),
                    "scope": _candidate_scope_record(serialized_item),
                    "target_obligation": target_obligation,
                    "work_phase": str(record.get("phase") or ""),
                    "strategy": str(record.get("strategy") or ""),
                    "candidate": serialized_item,
                    "generated": True,
                    "replayed": replayed,
                    "control_replay": _replay_summary(control_eval, record.get("control_stop_reason")),
                    "candidate_replay": _replay_summary(result_eval, record.get("result_stop_reason")),
                    "new_bb_delta": _new_bb_delta_record(record.get("coverage")),
                    "constraint_feedback": dict(record.get("constraint_feedback") or {}),
                    "state_equivalence": dict(record.get("state_equivalence") or {}),
                    "environment_feasibility": dict(record.get("environment_feasibility") or {}),
                    "accepted_by_replay": bool(success),
                    "persisted": False,
                    "scoped": False,
                    "accept_reason": "replay_reaches_target" if success else None,
                    "reject_reason": reject_reason,
                    "persistence_outcome": None,
                }
                hypothesis_audit_indices_by_candidate[candidate_id].append(len(hypothesis_audit_records))
                hypothesis_audit_records.append(entry)

        def _mark_successful_hypothesis_persistence(
            candidates: Iterable[object],
            *,
            work_phase: str,
            strategy: Optional[str],
            branch_pc_value: int,
            target_direction: bool,
            persisted: bool,
            scoped: bool,
            outcome: str,
            accept_reason: Optional[str] = None,
            reject_reason: Optional[str] = None,
        ) -> None:
            target_obligation = _target_obligation_record(
                work_phase=work_phase,
                strategy=strategy,
                branch_pc_value=branch_pc_value,
                target_direction=target_direction,
            )
            for candidate in list(candidates or []):
                serialized_item = self._serialize_constraint_candidate(candidate)
                candidate_id = _hypothesis_candidate_id(serialized_item, target_obligation)
                for index in reversed(hypothesis_audit_indices_by_candidate.get(candidate_id, [])):
                    entry = hypothesis_audit_records[index]
                    if entry.get("stage") != "replay":
                        continue
                    if not entry.get("accepted_by_replay"):
                        continue
                    if strategy is not None and str(entry.get("strategy") or "") != str(strategy):
                        continue
                    if entry.get("persistence_outcome"):
                        continue
                    entry["persisted"] = bool(persisted)
                    entry["scoped"] = bool(scoped)
                    entry["persistence_outcome"] = outcome
                    if accept_reason:
                        entry["accept_reason"] = accept_reason
                    if reject_reason:
                        if persisted or scoped:
                            entry["post_replay_reject_reason"] = reject_reason
                        else:
                            entry["reject_reason"] = reject_reason
                    break

        def record_branch_mmio_harvest(
            branch_key: Tuple[int, int],
            branch_choice: object,
            scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
            replay_events: Iterable[object],
            replay_snapshots: Iterable[object],
            *,
            evidence_class: object,
            remember_main_events: bool = True,
            overwrite_main_events: bool = True,
        ) -> Dict[str, int]:
            nonlocal harvested_branch_events
            nonlocal harvested_branch_root_snapshots
            nonlocal harvested_dynamic_successor_edges
            nonlocal harvested_seed_roots
            nonlocal harvested_child_tasks
            nonlocal harvested_observed_direction_updates

            harvest_info = self._harvest_branch_mmio_success(
                branch_key,
                branch_choice,
                scope_signature,
                replay_events,
                replay_snapshots,
                evidence_class=evidence_class,
                enqueue_child_tasks=enable_branch_mmio_harvest,
                remember_main_events=remember_main_events,
                overwrite_main_events=overwrite_main_events,
            )
            harvested_branch_events += int(harvest_info.get("remembered_branch_events", 0) or 0)
            harvested_observed_direction_updates += int(harvest_info.get("observed_direction_updates", 0) or 0)
            harvested_branch_root_snapshots += int(harvest_info.get("remembered_branch_root_snapshots", 0) or 0)
            harvested_dynamic_successor_edges += int(harvest_info.get("dynamic_successor_edges_added", 0) or 0)
            harvested_seed_roots += int(harvest_info.get("harvested_seed_roots", 0) or 0)
            harvested_child_tasks += int(harvest_info.get("child_tasks_enqueued", 0) or 0)
            return harvest_info

        def maybe_record_attempt(record: Dict[str, object]) -> None:
            if "constraint_source_counts" not in record:
                source_counts = serialized_constraint_source_counts(record.get("constraint_items", []))
                record["constraint_source_counts"] = dict(source_counts)
                record["constraint_sources"] = sorted(source_counts)
                record["constraint_item_count"] = sum(int(value) for value in source_counts.values())
                record["llm_derived"] = source_counts_has_marker(source_counts, "llm")
                record["rule_derived"] = source_counts_has_marker(source_counts, "rules")
            else:
                source_counts = Counter({
                    str(source): int(count)
                    for source, count in dict(record.get("constraint_source_counts") or {}).items()
                })
            if "constraint_inference_metadata" not in record:
                metadata_items = []
                for serialized_item in list(record.get("constraint_items", []) or []):
                    if not isinstance(serialized_item, dict):
                        continue
                    try:
                        normalized = BranchConstraintCandidate(
                            constraint_type=str(serialized_item.get("type") or "mmio"),
                            address=int(str(serialized_item.get("address") or "0"), 16),
                            value=int(str(serialized_item.get("value") or "0"), 16),
                            read_pc=(
                                int(str(serialized_item.get("read_pc")), 16)
                                if serialized_item.get("read_pc")
                                else None
                            ),
                            constraint_pc=(
                                int(str(serialized_item.get("constraint_pc")), 16)
                                if serialized_item.get("constraint_pc")
                                else None
                            ),
                            source=str(serialized_item.get("source") or ""),
                            read_occurrence=(
                                int(serialized_item.get("read_occurrence"))
                                if serialized_item.get("read_occurrence") is not None
                                else None
                            ),
                            input_kind=str(serialized_item.get("input_kind") or ""),
                            externally_controllable=bool(
                                serialized_item.get("externally_controllable", False)
                            ),
                            dependency_register=serialized_item.get("dependency_register"),
                            dependency_expression=str(
                                serialized_item.get("dependency_expression") or ""
                            ),
                            dependency_group=str(
                                serialized_item.get("dependency_group") or ""
                            ),
                            composite_dependency=bool(
                                serialized_item.get("composite_dependency", False)
                            ),
                            width=(
                                int(serialized_item.get("width"))
                                if serialized_item.get("width") is not None
                                else None
                            ),
                        ).normalized()
                    except Exception:
                        normalized = None
                    if normalized is None:
                        continue
                    meta = constraint_inference_metadata(normalized)
                    if meta:
                        metadata_items.append(meta)
                if metadata_items:
                    record["constraint_inference_metadata"] = metadata_items[:8]
            outcome_text = str(record.get("outcome") or "")
            result_eval = record.get("result_eval") if isinstance(record.get("result_eval"), dict) else {}
            replayed = bool(result_eval or record.get("control_eval"))
            success = outcome_text == "success" or bool(result_eval.get("success"))
            coverage = record.get("coverage") if isinstance(record.get("coverage"), dict) else {}
            if "environment_feasibility" not in record:
                record["environment_feasibility"] = self._environment_feasibility_record(
                    strategy=str(record.get("strategy") or ""),
                    outcome=str(record.get("outcome") or ""),
                    constraint_items=list(record.get("constraint_items", []) or []),
                    constraint_feedback=dict(record.get("constraint_feedback") or {}),
                    result_eval=result_eval,
                    state_equivalence=dict(record.get("state_equivalence") or {}),
                    coverage=coverage,
                )
            for source in sorted(source_counts):
                attempt_source_stats[source] += 1
                if replayed:
                    replayed_attempt_source_stats[source] += 1
                if success:
                    successful_attempt_source_stats[source] += 1
                attempt_new_bbs_vs_control_by_source[source] += int(coverage.get("new_bbs_vs_control", 0) or 0)
                attempt_new_bbs_vs_global_by_source[source] += int(coverage.get("new_bbs_vs_global", 0) or 0)
                attempt_new_bbs_vs_phase_by_source[source] += int(coverage.get("new_bbs_vs_phase_before", 0) or 0)
            _record_hypothesis_replay_audit(record)
            if len(attempt_records) >= 128:
                return
            attempt_records.append(record)

        def maybe_record_scoped_constraint_debug(
            *,
            work_phase: str,
            strategy: Optional[str],
            branch_pc: int,
            branch_key: Tuple[int, int],
            target_direction: bool,
            candidate: BranchConstraintCandidate,
            scope_signature: Tuple[Tuple[Tuple[int, int], object], ...],
            changed: bool,
        ) -> None:
            if len(scoped_constraint_debug_records) >= 32:
                return
            normalized_candidate = candidate.normalized()
            variant_signatures = self._scoped_branch_constraint_variant_signatures(
                scope_signature,
                branch_key=branch_key,
                branch_choice=target_direction,
            )
            scoped_constraint_debug_records.append({
                "phase": work_phase,
                "strategy": strategy,
                "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                "branch_key": {
                    "branch": f"0x{int(branch_key[0]) & 0xFFFFFFFF:08x}",
                    "occurrence": int(branch_key[1]),
                },
                "target_direction": "taken" if target_direction else "not-taken",
                "constraint": self._serialize_constraint_candidate(normalized_candidate),
                "base_scope_signature": self._serialize_debug_signature(scope_signature),
                "variant_signatures": [
                    self._serialize_debug_signature(signature)
                    for signature in variant_signatures[:8]
                ],
                "variant_count": len(variant_signatures),
                "changed": bool(changed),
            })

        def record_attempt(
            *,
            phase: str,
            strategy: str,
            branch_pc_value: int,
            target_direction: bool,
            constraint_items,
            control_eval: Dict[str, object],
            result_eval: Dict[str, object],
            constraint_feedback: Optional[Dict[str, object]] = None,
            control_stop_reason: Optional[str],
            result_stop_reason: Optional[str],
            outcome: str,
            control_valid_bbs: Optional[Set[int]] = None,
            result_valid_bbs: Optional[Set[int]] = None,
            phase_known_before: Optional[Set[int]] = None,
            control_run_result_full: Optional[Dict[str, object]] = None,
            result_run_result_full: Optional[Dict[str, object]] = None,
        ) -> None:
            reason = outcome
            if direction_attempt_outcomes is not None:
                direction_attempt_outcomes.append(reason)
            if reason != "success":
                attempt_failure_reasons[reason] += 1
            serialized_items = [
                self._serialize_constraint_candidate(item)
                for item in list(constraint_items or [])
            ]
            serialized_metadata = [
                meta
                for item in list(constraint_items or [])
                for meta in [constraint_inference_metadata(item)]
                if meta
            ]
            source_counts = serialized_constraint_source_counts(serialized_items)
            coverage_record = coverage_attribution_record(
                control_valid_bbs=control_valid_bbs,
                result_valid_bbs=result_valid_bbs,
                phase_known_before=phase_known_before,
            )
            state_record = self._state_equivalence_record(
                control_run_result_full,
                result_run_result_full,
            )
            environment_record = self._environment_feasibility_record(
                strategy=str(strategy),
                outcome=str(outcome),
                constraint_items=serialized_items,
                constraint_feedback=dict(constraint_feedback or {}),
                result_eval=dict(result_eval),
                state_equivalence=state_record,
                coverage=coverage_record,
            )
            maybe_record_attempt({
                "phase": phase,
                "strategy": strategy,
                "branch_pc": f"0x{int(branch_pc_value) & 0xFFFFFFFF:08x}",
                "target_direction": "taken" if target_direction else "not-taken",
                "constraint_items": serialized_items,
                "constraint_source_counts": dict(source_counts),
                "constraint_sources": sorted(source_counts),
                "constraint_item_count": sum(int(value) for value in source_counts.values()),
                "constraint_inference_metadata": serialized_metadata[:8],
                "llm_derived": source_counts_has_marker(source_counts, "llm"),
                "rule_derived": source_counts_has_marker(source_counts, "rules"),
                "control_eval": dict(control_eval),
                "result_eval": dict(result_eval),
                "constraint_feedback": dict(constraint_feedback or {}),
                "control_stop_reason": control_stop_reason,
                "result_stop_reason": result_stop_reason,
                "desired_successor": _current_desired_successor_hex(),
                "outcome": outcome,
                "coverage": coverage_record,
                "state_equivalence": state_record,
                "environment_feasibility": environment_record,
            })

        for branch_index, (work_phase_name, branch_item) in enumerate(branch_work_items):
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                break
            if phase_success_limit > 0 and len(changed_branch_starts) >= phase_success_limit:
                break
            phase_is_exact_state = work_phase_name == "exact_state"
            phase_is_observed_retry = work_phase_name == "general_retry"
            bb, branch_instruction, candidate_sources, candidates, snapshot_entries, direction_potentials = branch_item
            branch_start = int(bb.start_addr)
            if not phase_is_exact_state and branch_start in exact_state_generalized_branch_starts:
                continue
            active_snapshot_entries = snapshot_entries
            allow_provenance_replay = scoped_replay
            allow_entry_fallback = True
            if not scoped_replay:
                active_snapshot_entries = []
            if phase_is_exact_state:
                active_snapshot_entries = branch_prefix_entries(branch_item)
                allow_provenance_replay = False
                allow_entry_fallback = False
                if not active_snapshot_entries:
                    continue

            branch_pc = branch_instruction["address"]
            condition = branch_instruction["mnemonic"].upper()
            observed_directions = self._observed_branch_directions(branch_start)
            current_candidate_sources = candidate_sources
            current_candidates = list(candidates)
            current_constraint_candidates = list(current_candidate_sources.get("dependency_constraints", []) or [])

            if (
                not current_candidate_sources.get("precise_static")
                and not current_candidate_sources.get("dependency")
                and active_snapshot_entries
                and int(branch_pc) not in provenance_warmup_cache
            ):
                warmup = self._warm_branch_provenance(
                    branch_start,
                    branch_pc,
                    active_snapshot_entries,
                    replay_instructions=replay_instructions,
                    replay_timeout=replay_timeout,
                )
                provenance_warmup_cache[int(branch_pc)] = warmup
                if warmup.get("attempted"):
                    provenance_warmup_attempts += 1
                if warmup.get("collected"):
                    provenance_warmup_successes += 1
                    refreshed_sources = self._mmio_candidate_sources(branch_pc, candidate_window)
                    refreshed_snapshot_precise = self._snapshot_precise_mmio_candidates(branch_pc, active_snapshot_entries)
                    refreshed_sources["snapshot"] = refreshed_snapshot_precise
                    refreshed_precise = _dedupe_preserve_order(
                        refreshed_snapshot_precise + refreshed_sources.get("precise_static", [])
                    )
                    refreshed_candidates = (
                        refreshed_precise
                        if refreshed_precise
                        else _dedupe_preserve_order(refreshed_snapshot_precise + refreshed_sources["merged"])
                    )
                    if refreshed_candidates:
                        current_candidate_sources = refreshed_sources
                        current_candidates = refreshed_candidates
                        current_constraint_candidates = list(
                            current_candidate_sources.get("dependency_constraints", []) or []
                        )

            def build_constraint_candidates(target_direction: bool) -> List[BranchConstraintCandidate]:
                built: List[BranchConstraintCandidate] = []
                seen = set()

                for base_candidate in current_constraint_candidates:
                    if not isinstance(base_candidate, BranchConstraintCandidate):
                        continue
                    normalized_base = base_candidate.normalized()
                    candidate_type = str(normalized_base.constraint_type or "").lower()
                    inferred_value: Optional[int] = None
                    inference_meta: Dict[str, object] = {}
                    source_label = normalized_base.source or "dependency"
                    if candidate_type == "memory":
                        inferred_value = self._infer_memory_constraint_value(
                            branch_pc,
                            condition,
                            target_direction,
                            normalized_base,
                        )
                        source_label = "dependency_memory"
                    elif candidate_type == "mmio":
                        inferred_value = self.llm_guide.infer_constraint(
                            branch_pc,
                            condition,
                            target_direction,
                            normalized_base.address,
                        )
                        inference_meta = record_inference_metadata()
                        source_label = source_label_from_inference("dependency_mmio", inference_meta)
                    if inferred_value is None:
                        continue
                    candidate = BranchConstraintCandidate(
                        constraint_type=candidate_type,
                        address=int(normalized_base.address),
                        value=int(inferred_value) & 0xFFFFFFFF,
                        read_pc=int(normalized_base.read_pc) if normalized_base.read_pc is not None else None,
                        constraint_pc=self._constraint_compare_pc(branch_pc),
                        source=source_label,
                        read_occurrence=normalized_base.read_occurrence,
                        input_kind=normalized_base.input_kind,
                        externally_controllable=normalized_base.externally_controllable,
                        dependency_register=normalized_base.dependency_register,
                        dependency_expression=normalized_base.dependency_expression,
                        dependency_group=normalized_base.dependency_group,
                        composite_dependency=normalized_base.composite_dependency,
                        width=normalized_base.width,
                    ).normalized()
                    dedupe_key = (
                        candidate.constraint_type,
                        candidate.address,
                        int(candidate.read_pc or 0),
                        int(candidate.read_occurrence or 0),
                        candidate.value,
                    )
                    if dedupe_key in seen:
                        continue
                    seen.add(dedupe_key)
                    remember_candidate_inference(candidate, inference_meta)
                    built.append(candidate)
                    maybe_add_llm_second_opinion(
                        built=built,
                        seen=seen,
                        constraint_type=candidate_type,
                        address=int(normalized_base.address),
                        read_pc=int(normalized_base.read_pc) if normalized_base.read_pc is not None else None,
                        read_occurrence=normalized_base.read_occurrence,
                        previous_value=int(inferred_value) & 0xFFFFFFFF,
                        target_direction=target_direction,
                        source_prefix=source_label,
                    )

                if built:
                    for item in built:
                        record_built_candidate(item)
                    ranked = sorted(
                        built,
                        key=lambda item: (
                            *self._candidate_dependency_priority(item),
                        ),
                        reverse=True,
                    )
                    return ranked[: max(1, candidates_per_branch)]

                for mmio_addr in current_candidates[:candidates_per_branch]:
                    read_pc = (current_candidate_sources.get("precise_read_pcs", {}) or {}).get(int(mmio_addr))
                    if read_pc is None:
                        read_pc = self._find_constraint_read_pc(branch_pc, mmio_addr, candidate_window)
                    value = self.llm_guide.infer_constraint(branch_pc, condition, target_direction, mmio_addr)
                    inference_meta = record_inference_metadata()
                    if value is None:
                        continue
                    candidate = BranchConstraintCandidate(
                        constraint_type="mmio",
                        address=int(mmio_addr),
                        value=int(value) & 0xFFFFFFFF,
                        read_pc=int(read_pc) if read_pc is not None else None,
                        constraint_pc=self._constraint_compare_pc(branch_pc),
                        source=source_label_from_inference("branch_mmio", inference_meta),
                        input_kind="mmio",
                        externally_controllable=True,
                    ).normalized()
                    dedupe_key = (
                        candidate.constraint_type,
                        candidate.address,
                        int(candidate.read_pc or 0),
                        int(candidate.read_occurrence or 0),
                        candidate.value,
                    )
                    if dedupe_key in seen:
                        continue
                    seen.add(dedupe_key)
                    remember_candidate_inference(candidate, inference_meta)
                    record_built_candidate(candidate)
                    built.append(candidate)
                    maybe_add_llm_second_opinion(
                        built=built,
                        seen=seen,
                        constraint_type="mmio",
                        address=int(mmio_addr),
                        read_pc=int(read_pc) if read_pc is not None else None,
                        read_occurrence=None,
                        previous_value=int(value) & 0xFFFFFFFF,
                        target_direction=target_direction,
                        source_prefix="branch_mmio",
                    )
                return built

            branch_changed = False
            for take_branch in (True, False):
                direction_attempt_outcomes = []
                direction_previously_observed = bool(take_branch in observed_directions)
                if phase_is_observed_retry:
                    if not direction_previously_observed:
                        continue
                    if (
                        observed_retry_direction_limit > 0
                        and retried_observed_directions >= observed_retry_direction_limit
                    ):
                        continue
                    retried_observed_directions += 1
                elif direction_previously_observed:
                    if phase_is_exact_state:
                        skipped_observed_directions += 1
                    else:
                        deferred_observed_directions += 1
                    continue
                direction_potential = direction_potentials[bool(take_branch)]
                if (
                    skip_zero_potential_directions
                    and int(direction_potential["static_new_potential"]) <= 0
                ):
                    skipped_zero_potential_directions_count += 1
                    continue
                weak_direction = not bool(current_candidate_sources.get("precise_static")) and not bool(current_candidate_sources.get("snapshot"))
                if weak_direction and (int(branch_pc), bool(take_branch)) in self.branch_mmio_exhausted_weak_directions:
                    skipped_exhausted_weak_directions += 1
                    continue
                candidate_constraint_items = build_constraint_candidates(bool(take_branch))

                dynamic_candidate_sets: List[
                    Tuple[BranchConstraintCandidate, ...]
                ] = []
                if generic_dynamic_fallback:
                    # 差分扰动（二级定位）需要可重放的快照上下文：把当前
                    # 方向的首个可用快照绑给探针，tracer 内表达式图无该分支
                    # 记录时按需触发；无图命中则探针不运行，行为与原先一致。
                    probe_solver = getattr(self, "differential_probe_solver", None)
                    if probe_solver is not None:
                        probe_solver.bind_replay_context(
                            snapshot_entry=(
                                active_snapshot_entries[0]
                                if active_snapshot_entries
                                else None
                            ),
                            branch_bb=int(bb.start_addr) & 0xFFFFFFFF,
                            take_branch=bool(take_branch),
                            desired_successor=direction_potential.get(
                                "successor_bb"
                            ),
                            replay_instructions=int(replay_instructions),
                            replay_timeout=int(replay_timeout),
                        )
                    try:
                        dynamic_candidate_sets = self._naturalization_dynamic_candidate_sets(
                            self._branch_root_key_for_start(branch_start),
                            bool(take_branch),
                            max_models=max(1, min(4, int(candidates_per_branch))),
                            source_prefix="generic_dynamic_ssa",
                        )
                    finally:
                        if probe_solver is not None:
                            probe_solver.clear_replay_context()

                if not candidate_constraint_items and not dynamic_candidate_sets:
                    continue

                constraint_map_candidates: List[List[BranchConstraintCandidate]] = [
                    [item]
                    for item in candidate_constraint_items
                ]
                if len(candidate_constraint_items) > 1:
                    combined_constraint_items = list(candidate_constraint_items)
                    if combined_constraint_items not in constraint_map_candidates:
                        constraint_map_candidates.append(combined_constraint_items)
                for dynamic_set in dynamic_candidate_sets:
                    dynamic_items = list(dynamic_set)
                    if dynamic_items and dynamic_items not in constraint_map_candidates:
                        constraint_map_candidates.insert(0, dynamic_items)

                desired_successor = direction_potential["successor_bb"]
                for candidate_item in candidate_constraint_items:
                    _record_generated_hypothesis(
                        candidate_item,
                        work_phase=work_phase_name,
                        branch_pc_value=branch_pc,
                        target_direction=bool(take_branch),
                    )
                for dynamic_set in dynamic_candidate_sets:
                    for candidate_item in dynamic_set:
                        _record_generated_hypothesis(
                            candidate_item,
                            work_phase=work_phase_name,
                            branch_pc_value=branch_pc,
                            target_direction=bool(take_branch),
                        )
                direction_succeeded = False
                successful_constraint_items: Optional[List[BranchConstraintCandidate]] = None
                successful_scope_signature: Tuple[Tuple[Tuple[int, int], object], ...] = tuple()
                successful_strategy: Optional[str] = None
                successful_branch_key: Tuple[int, int] = self._branch_root_key_for_start(branch_start)
                successful_replay_events: List[object] = []
                successful_replay_snapshots: List[object] = []
                successful_control_events: List[object] = []
                successful_replay_coverage: Set[int] = set()
                successful_constraint_feedback: Dict[str, object] = {}
                successful_replay_evidence = EVIDENCE_UNKNOWN
                equivalent_no_effect_modes: Set[str] = set()
                if phase_is_exact_state:
                    exact_state_directions_replayed += 1
                provenance_available = any(
                    self._ordered_source_path_signature(
                        tuple(
                            getattr(snapshot_entry, "source_path_signature", tuple())
                            or getattr(snapshot_entry, "prefix_signature", tuple())
                            or tuple()
                        )
                    )
                    for snapshot_entry in active_snapshot_entries
                )

                for constraint_items in constraint_map_candidates:
                    for item in constraint_items:
                        if isinstance(item, BranchConstraintCandidate):
                            normalized_item = item.normalized()
                            replay_constraint_stats[f"replay_{normalized_item.constraint_type}"] += 1
                            replay_constraint_source_stats[normalized_item.source or "unknown"] += 1
                    for snapshot_entry in active_snapshot_entries:
                        cached_skip = self._branch_mmio_cached_skip_reason(
                            branch_pc,
                            bool(take_branch),
                            "snapshot",
                            constraint_items,
                            snapshot_entry=snapshot_entry,
                        )
                        if cached_skip is not None:
                            replay_mode_pruned_attempts += 1
                            if direction_attempt_outcomes is not None:
                                direction_attempt_outcomes.append(cached_skip)
                            attempt_failure_reasons[cached_skip] += 1
                            maybe_record_attempt({
                                "phase": work_phase_name,
                                "strategy": "snapshot",
                                "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                "target_direction": "taken" if take_branch else "not-taken",
                                "constraint_items": [
                                    self._serialize_constraint_candidate(item)
                                    for item in list(constraint_items or [])
                                ],
                                "outcome": cached_skip,
                            })
                            continue
                        if not self._snapshot_replay_can_revisit_constraints(snapshot_entry, constraint_items):
                            replay_window_skips += 1
                            if direction_attempt_outcomes is not None:
                                direction_attempt_outcomes.append("replay_window_skip")
                            attempt_failure_reasons["replay_window_skip"] += 1
                            maybe_record_attempt({
                                "phase": work_phase_name,
                                "strategy": "snapshot",
                                "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                "target_direction": "taken" if take_branch else "not-taken",
                                "desired_successor": _current_desired_successor_hex(),
                                "constraint_items": [
                                    self._serialize_constraint_candidate(item)
                                    for item in list(constraint_items or [])
                                ],
                                "outcome": "replay_window_skip",
                            })
                            continue
                        snapshot_identity = self._snapshot_entry_identity(snapshot_entry)
                        control_key = ("snapshot",) + snapshot_identity
                        control_result = snapshot_control_cache.get(control_key)
                        if control_result is None:
                            control_replays += 1
                            control_result = self._replay_mmio_from_snapshot(
                                snapshot_entry,
                                [],
                                replay_instructions=replay_instructions,
                                replay_timeout=replay_timeout,
                            )
                            snapshot_control_cache[control_key] = control_result
                        control_valid, control_run_result, control_restored, control_events, _control_snapshots = control_result
                        if not control_restored:
                            control_restore_failures += 1
                            attempt_failure_reasons["control_restore_failed"] += 1
                            maybe_record_attempt({
                                "phase": work_phase_name,
                                "strategy": "snapshot",
                                "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                "target_direction": "taken" if take_branch else "not-taken",
                                "constraint_items": [
                                    self._serialize_constraint_candidate(item)
                                    for item in list(constraint_items or [])
                                ],
                                "control_stop_reason": control_run_result.get("stop_reason"),
                                "outcome": "control_restore_failed",
                            })
                            continue
                        control_eval = self._evaluate_branch_replay(
                            control_events,
                            bb.start_addr,
                            take_branch,
                            desired_successor,
                            control_valid,
                        )
                        if control_eval["success"]:
                            control_success_without_constraint += 1

                        valid, _run_result, restored, replay_events, replay_snapshots = self._replay_mmio_from_snapshot(
                            snapshot_entry,
                            constraint_items,
                            replay_instructions=replay_instructions,
                            replay_timeout=replay_timeout,
                        )
                        if not restored:
                            snapshot_restore_failures += 1
                            attempt_failure_reasons["snapshot_restore_failed"] += 1
                            maybe_record_attempt({
                                "phase": work_phase_name,
                                "strategy": "snapshot",
                                "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                "target_direction": "taken" if take_branch else "not-taken",
                                "desired_successor": _current_desired_successor_hex(),
                                "constraint_items": [
                                    self._serialize_constraint_candidate(item)
                                    for item in list(constraint_items or [])
                                ],
                                "snapshot_identity": repr(
                                    self._snapshot_entry_identity(snapshot_entry)
                                )[:2000],
                                "snapshot_origin": str(
                                    getattr(snapshot_entry, "origin", "unknown")
                                ),
                                "outcome": "snapshot_restore_failed",
                                "execution_started": False,
                                "execution_failed": True,
                                "restore_failed": True,
                                "execution_telemetry_complete": False,
                                "execution_error": str(
                                    (_run_result or {}).get("execution_error")
                                    or "snapshot restore returned false"
                                )[:2000],
                            })
                            continue
                        snapshot_replays += 1
                        if phase_is_exact_state:
                            exact_state_snapshot_replays += 1
                        origin = str(getattr(snapshot_entry, "origin", "unknown"))
                        if origin == "prefix":
                            snapshot_prefix_replays += 1
                        elif origin == "root":
                            snapshot_root_replays += 1
                        elif origin == "direct":
                            snapshot_direct_replays += 1
                        phase_known_before = set(self.global_coverage | phase_covered)
                        phase_covered.update(valid)
                        explored_directions += 1
                        constraints_applied += len(constraint_items)
                        result_eval = self._evaluate_branch_replay(
                            replay_events,
                            bb.start_addr,
                            take_branch,
                            desired_successor,
                            valid,
                        )
                        constraint_feedback = dict((_run_result or {}).get("constraint_feedback", {}) or {})
                        candidate_materialized = self._constraints_materialized(
                            constraint_items,
                            constraint_feedback,
                        )
                        if (
                            result_eval["success"]
                            and not control_eval["success"]
                            and candidate_materialized
                        ):
                            snapshot_successes += 1
                            if phase_is_exact_state:
                                exact_state_snapshot_successes += 1
                            direction_succeeded = True
                            successful_constraint_items = list(constraint_items)
                            successful_scope_signature = self._scope_signature_from_snapshot_entry(snapshot_entry)
                            successful_strategy = "snapshot"
                            successful_branch_key = tuple(getattr(snapshot_entry, "next_branch_key", successful_branch_key) or successful_branch_key)
                            successful_replay_events = list(replay_events or [])
                            successful_replay_snapshots = list(replay_snapshots or [])
                            successful_control_events = list(control_events or [])
                            successful_replay_coverage = set(valid)
                            successful_constraint_feedback = dict(constraint_feedback)
                            external_candidate_materialized = self._constraints_materialized(
                                constraint_items,
                                constraint_feedback,
                                require_external=True,
                            )
                            successful_replay_evidence = derived_replay_evidence(
                                self._snapshot_entry_evidence_class(snapshot_entry),
                                forced_control=not external_candidate_materialized,
                                consumed_environment_fact=external_candidate_materialized,
                            )
                            if successful_replay_evidence == EVIDENCE_UNKNOWN:
                                successful_replay_evidence = EVIDENCE_E2
                            record_attempt(
                                phase=work_phase_name,
                                strategy="snapshot",
                                branch_pc_value=branch_pc,
                                target_direction=take_branch,
                                constraint_items=list(constraint_items),
                                control_eval=control_eval,
                                result_eval=result_eval,
                                constraint_feedback=constraint_feedback,
                                control_stop_reason=control_run_result.get("stop_reason"),
                                result_stop_reason=_run_result.get("stop_reason"),
                                outcome="success",
                                control_valid_bbs=control_valid,
                                result_valid_bbs=valid,
                                phase_known_before=phase_known_before,
                                control_run_result_full=control_run_result,
                                result_run_result_full=_run_result,
                            )
                            break
                        outcome = "candidate_not_consumed" if (
                            result_eval["success"] and not candidate_materialized
                        ) else "already_target_without_constraint" if control_eval["success"] else (
                            "branch_lost_after_constraint"
                            if control_eval.get("branch_seen") and not result_eval.get("branch_seen")
                            else (
                                "no_effect_same_outcome"
                                if control_eval.get("observed_directions") == result_eval.get("observed_directions")
                                and control_eval.get("failure_reason") == result_eval.get("failure_reason")
                                else str(result_eval.get("failure_reason") or "unknown_failure")
                            )
                        )
                        record_attempt(
                            phase=work_phase_name,
                            strategy="snapshot",
                            branch_pc_value=branch_pc,
                            target_direction=take_branch,
                            constraint_items=list(constraint_items),
                            control_eval=control_eval,
                            result_eval=result_eval,
                            constraint_feedback=constraint_feedback,
                            control_stop_reason=control_run_result.get("stop_reason"),
                            result_stop_reason=_run_result.get("stop_reason"),
                            outcome=outcome,
                            control_valid_bbs=control_valid,
                            result_valid_bbs=valid,
                            phase_known_before=phase_known_before,
                            control_run_result_full=control_run_result,
                            result_run_result_full=_run_result,
                        )
                        if outcome == "already_target_without_constraint":
                            if self._snapshot_entry_evidence_class(snapshot_entry) in {
                                EVIDENCE_E0,
                                EVIDENCE_E1,
                            }:
                                self._remember_single_observed_branch_direction(
                                    branch_start,
                                    bool(take_branch),
                                )
                            self._remember_branch_mmio_already_target(
                                branch_pc,
                                bool(take_branch),
                                "snapshot",
                                snapshot_entry=snapshot_entry,
                            )
                        elif (
                            str(result_eval.get("failure_reason") or "") == "branch_not_reached"
                            and int(constraint_feedback.get("matched_constraint_reads", 0) or 0) == 0
                            and int(constraint_feedback.get("matched_address_reads", 0) or 0) == 0
                        ):
                            self._remember_branch_mmio_unreachable_replay(
                                branch_pc,
                                bool(take_branch),
                                "snapshot",
                                constraint_items,
                                snapshot_entry=snapshot_entry,
                            )
                        if self._is_strong_no_effect_failure(outcome, control_eval, result_eval, constraint_feedback):
                            equivalent_no_effect_modes.add("provenance")
                    if direction_succeeded:
                        break

                    if allow_provenance_replay:
                        if "provenance" in equivalent_no_effect_modes:
                            replay_mode_pruned_attempts += 1
                        else:
                            seen_provenance = set()
                            for snapshot_entry in active_snapshot_entries:
                                source_signature = self._ordered_source_path_signature(
                                    tuple(
                                        getattr(snapshot_entry, "source_path_signature", tuple())
                                        or getattr(snapshot_entry, "prefix_signature", tuple())
                                        or tuple()
                                    )
                                )
                                if not source_signature or source_signature in seen_provenance:
                                    continue
                                seen_provenance.add(source_signature)

                                cached_skip = self._branch_mmio_cached_skip_reason(
                                    branch_pc,
                                    bool(take_branch),
                                    "entry_provenance",
                                    constraint_items,
                                    snapshot_entry=snapshot_entry,
                                )
                                if cached_skip is not None:
                                    replay_mode_pruned_attempts += 1
                                    if direction_attempt_outcomes is not None:
                                        direction_attempt_outcomes.append(cached_skip)
                                    attempt_failure_reasons[cached_skip] += 1
                                    maybe_record_attempt({
                                        "phase": work_phase_name,
                                        "strategy": "entry_provenance",
                                        "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                        "target_direction": "taken" if take_branch else "not-taken",
                                        "constraint_items": [
                                            self._serialize_constraint_candidate(item)
                                            for item in list(constraint_items or [])
                                        ],
                                        "outcome": cached_skip,
                                    })
                                    continue

                                provenance_identity = self._snapshot_entry_identity(snapshot_entry)
                                control_key = ("entry_provenance", False) + provenance_identity
                                control_result = provenance_control_cache.get(control_key)
                                if control_result is None:
                                    control_replays += 1
                                    control_result = self._replay_mmio_from_entry_provenance(
                                        snapshot_entry,
                                        [],
                                        replay_instructions=replay_instructions,
                                        replay_timeout=replay_timeout,
                                        ordered=False,
                                    )
                                    provenance_control_cache[control_key] = control_result
                                control_valid, control_run_result, control_events, control_snapshots = control_result
                                control_eval = self._evaluate_branch_replay(
                                    control_events,
                                    bb.start_addr,
                                    take_branch,
                                    desired_successor,
                                    control_valid,
                                )
                                if control_eval["success"]:
                                    control_success_without_constraint += 1

                                valid, _run_result, replay_events, replay_snapshots = self._replay_mmio_from_entry_provenance(
                                    snapshot_entry,
                                    constraint_items,
                                    replay_instructions=replay_instructions,
                                    replay_timeout=replay_timeout,
                                    ordered=False,
                                )
                                entry_provenance_replays += 1
                                phase_known_before = set(self.global_coverage | phase_covered)
                                phase_covered.update(valid)
                                explored_directions += 1
                                constraints_applied += len(constraint_items)
                                result_eval = self._evaluate_branch_replay(
                                    replay_events,
                                    bb.start_addr,
                                    take_branch,
                                    desired_successor,
                                    valid,
                                )
                                constraint_feedback = dict((_run_result or {}).get("constraint_feedback", {}) or {})
                                candidate_materialized = self._constraints_materialized(
                                    constraint_items,
                                    constraint_feedback,
                                )
                                if (
                                    result_eval["success"]
                                    and not control_eval["success"]
                                    and candidate_materialized
                                ):
                                    entry_provenance_successes += 1
                                    direction_succeeded = True
                                    successful_constraint_items = list(constraint_items)
                                    successful_scope_signature = self._scope_signature_from_snapshot_entry(snapshot_entry)
                                    successful_strategy = "entry_provenance"
                                    successful_branch_key = tuple(getattr(snapshot_entry, "next_branch_key", successful_branch_key) or successful_branch_key)
                                    successful_replay_events = list(replay_events or [])
                                    successful_replay_snapshots = list(replay_snapshots or [])
                                    successful_control_events = list(control_events or [])
                                    successful_replay_coverage = set(valid)
                                    successful_constraint_feedback = dict(constraint_feedback)
                                    successful_replay_evidence = derived_replay_evidence(
                                        self._snapshot_entry_evidence_class(snapshot_entry),
                                        forced_control=True,
                                        consumed_environment_fact=True,
                                    )
                                    if successful_replay_evidence == EVIDENCE_UNKNOWN:
                                        successful_replay_evidence = EVIDENCE_E2
                                    record_attempt(
                                        phase=work_phase_name,
                                        strategy="entry_provenance",
                                        branch_pc_value=branch_pc,
                                        target_direction=take_branch,
                                        constraint_items=list(constraint_items),
                                        control_eval=control_eval,
                                        result_eval=result_eval,
                                        constraint_feedback=constraint_feedback,
                                        control_stop_reason=control_run_result.get("stop_reason"),
                                        result_stop_reason=_run_result.get("stop_reason"),
                                        outcome="success",
                                        control_valid_bbs=control_valid,
                                        result_valid_bbs=valid,
                                        phase_known_before=phase_known_before,
                                        control_run_result_full=control_run_result,
                                        result_run_result_full=_run_result,
                                    )
                                    break
                                outcome = "candidate_not_consumed" if (
                                    result_eval["success"] and not candidate_materialized
                                ) else "already_target_without_constraint" if control_eval["success"] else (
                                    "branch_lost_after_constraint"
                                    if control_eval.get("branch_seen") and not result_eval.get("branch_seen")
                                    else (
                                        "no_effect_same_outcome"
                                        if control_eval.get("observed_directions") == result_eval.get("observed_directions")
                                        and control_eval.get("failure_reason") == result_eval.get("failure_reason")
                                        else str(result_eval.get("failure_reason") or "unknown_failure")
                                    )
                                )
                                record_attempt(
                                    phase=work_phase_name,
                                    strategy="entry_provenance",
                                    branch_pc_value=branch_pc,
                                    target_direction=take_branch,
                                    constraint_items=list(constraint_items),
                                    control_eval=control_eval,
                                    result_eval=result_eval,
                                    constraint_feedback=constraint_feedback,
                                    control_stop_reason=control_run_result.get("stop_reason"),
                                    result_stop_reason=_run_result.get("stop_reason"),
                                    outcome=outcome,
                                    control_valid_bbs=control_valid,
                                    result_valid_bbs=valid,
                                    phase_known_before=phase_known_before,
                                    control_run_result_full=control_run_result,
                                    result_run_result_full=_run_result,
                                )
                                if outcome == "already_target_without_constraint":
                                    self._remember_branch_mmio_already_target(
                                        branch_pc,
                                        bool(take_branch),
                                        "entry_provenance",
                                        snapshot_entry=snapshot_entry,
                                    )
                                elif (
                                    str(result_eval.get("failure_reason") or "") == "branch_not_reached"
                                    and int(constraint_feedback.get("matched_constraint_reads", 0) or 0) == 0
                                    and int(constraint_feedback.get("matched_address_reads", 0) or 0) == 0
                                ):
                                    self._remember_branch_mmio_unreachable_replay(
                                        branch_pc,
                                        bool(take_branch),
                                        "entry_provenance",
                                        constraint_items,
                                        snapshot_entry=snapshot_entry,
                                    )
                                if self._is_strong_no_effect_failure(outcome, control_eval, result_eval, constraint_feedback):
                                    equivalent_no_effect_modes.add("ordered_provenance")

                                if "ordered_provenance" in equivalent_no_effect_modes:
                                    replay_mode_pruned_attempts += 1
                                    continue

                                cached_skip = self._branch_mmio_cached_skip_reason(
                                    branch_pc,
                                    bool(take_branch),
                                    "entry_ordered_provenance",
                                    constraint_items,
                                    snapshot_entry=snapshot_entry,
                                )
                                if cached_skip is not None:
                                    replay_mode_pruned_attempts += 1
                                    if direction_attempt_outcomes is not None:
                                        direction_attempt_outcomes.append(cached_skip)
                                    attempt_failure_reasons[cached_skip] += 1
                                    maybe_record_attempt({
                                        "phase": work_phase_name,
                                        "strategy": "entry_ordered_provenance",
                                        "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                        "target_direction": "taken" if take_branch else "not-taken",
                                        "constraint_items": [
                                            self._serialize_constraint_candidate(item)
                                            for item in list(constraint_items or [])
                                        ],
                                        "outcome": cached_skip,
                                    })
                                    continue

                                ordered_control_key = ("entry_provenance", True) + provenance_identity
                                ordered_control_result = provenance_control_cache.get(ordered_control_key)
                                if ordered_control_result is None:
                                    control_replays += 1
                                    ordered_control_result = self._replay_mmio_from_entry_provenance(
                                        snapshot_entry,
                                        [],
                                        replay_instructions=replay_instructions,
                                        replay_timeout=replay_timeout,
                                        ordered=True,
                                    )
                                    provenance_control_cache[ordered_control_key] = ordered_control_result
                                ordered_control_valid, ordered_control_run_result, ordered_control_events, _ordered_control_snapshots = ordered_control_result
                                ordered_control_eval = self._evaluate_branch_replay(
                                    ordered_control_events,
                                    bb.start_addr,
                                    take_branch,
                                    desired_successor,
                                    ordered_control_valid,
                                )
                                if ordered_control_eval["success"]:
                                    control_success_without_constraint += 1

                                valid, _run_result, replay_events, replay_snapshots = self._replay_mmio_from_entry_provenance(
                                    snapshot_entry,
                                    constraint_items,
                                    replay_instructions=replay_instructions,
                                    replay_timeout=replay_timeout,
                                    ordered=True,
                                )
                                entry_ordered_provenance_replays += 1
                                phase_known_before = set(self.global_coverage | phase_covered)
                                phase_covered.update(valid)
                                explored_directions += 1
                                constraints_applied += len(constraint_items)
                                result_eval = self._evaluate_branch_replay(
                                    replay_events,
                                    bb.start_addr,
                                    take_branch,
                                    desired_successor,
                                    valid,
                                )
                                constraint_feedback = dict((_run_result or {}).get("constraint_feedback", {}) or {})
                                candidate_materialized = self._constraints_materialized(
                                    constraint_items,
                                    constraint_feedback,
                                )
                                if (
                                    result_eval["success"]
                                    and not ordered_control_eval["success"]
                                    and candidate_materialized
                                ):
                                    entry_ordered_provenance_successes += 1
                                    direction_succeeded = True
                                    successful_constraint_items = list(constraint_items)
                                    successful_scope_signature = self._scope_signature_from_snapshot_entry(snapshot_entry)
                                    successful_strategy = "entry_ordered_provenance"
                                    successful_branch_key = tuple(getattr(snapshot_entry, "next_branch_key", successful_branch_key) or successful_branch_key)
                                    successful_replay_events = list(replay_events or [])
                                    successful_replay_snapshots = list(replay_snapshots or [])
                                    successful_control_events = list(ordered_control_events or [])
                                    successful_replay_coverage = set(valid)
                                    successful_constraint_feedback = dict(constraint_feedback)
                                    successful_replay_evidence = derived_replay_evidence(
                                        self._snapshot_entry_evidence_class(snapshot_entry),
                                        forced_control=True,
                                        consumed_environment_fact=True,
                                    )
                                    if successful_replay_evidence == EVIDENCE_UNKNOWN:
                                        successful_replay_evidence = EVIDENCE_E2
                                    record_attempt(
                                        phase=work_phase_name,
                                        strategy="entry_ordered_provenance",
                                        branch_pc_value=branch_pc,
                                        target_direction=take_branch,
                                        constraint_items=list(constraint_items),
                                        control_eval=ordered_control_eval,
                                        result_eval=result_eval,
                                        constraint_feedback=constraint_feedback,
                                        control_stop_reason=ordered_control_run_result.get("stop_reason"),
                                        result_stop_reason=_run_result.get("stop_reason"),
                                        outcome="success",
                                        control_valid_bbs=ordered_control_valid,
                                        result_valid_bbs=valid,
                                        phase_known_before=phase_known_before,
                                        control_run_result_full=ordered_control_run_result,
                                        result_run_result_full=_run_result,
                                    )
                                    break
                                outcome = "candidate_not_consumed" if (
                                    result_eval["success"] and not candidate_materialized
                                ) else "already_target_without_constraint" if ordered_control_eval["success"] else (
                                    "branch_lost_after_constraint"
                                    if ordered_control_eval.get("branch_seen") and not result_eval.get("branch_seen")
                                    else (
                                        "no_effect_same_outcome"
                                        if ordered_control_eval.get("observed_directions") == result_eval.get("observed_directions")
                                        and ordered_control_eval.get("failure_reason") == result_eval.get("failure_reason")
                                        else str(result_eval.get("failure_reason") or "unknown_failure")
                                    )
                                )
                                record_attempt(
                                    phase=work_phase_name,
                                    strategy="entry_ordered_provenance",
                                    branch_pc_value=branch_pc,
                                    target_direction=take_branch,
                                    constraint_items=list(constraint_items),
                                    control_eval=ordered_control_eval,
                                    result_eval=result_eval,
                                    constraint_feedback=constraint_feedback,
                                    control_stop_reason=ordered_control_run_result.get("stop_reason"),
                                    result_stop_reason=_run_result.get("stop_reason"),
                                    outcome=outcome,
                                    control_valid_bbs=ordered_control_valid,
                                    result_valid_bbs=valid,
                                    phase_known_before=phase_known_before,
                                    control_run_result_full=ordered_control_run_result,
                                    result_run_result_full=_run_result,
                                )
                                if outcome == "already_target_without_constraint":
                                    self._remember_branch_mmio_already_target(
                                        branch_pc,
                                        bool(take_branch),
                                        "entry_ordered_provenance",
                                        snapshot_entry=snapshot_entry,
                                    )
                                elif (
                                    str(result_eval.get("failure_reason") or "") == "branch_not_reached"
                                    and int(constraint_feedback.get("matched_constraint_reads", 0) or 0) == 0
                                    and int(constraint_feedback.get("matched_address_reads", 0) or 0) == 0
                                ):
                                    self._remember_branch_mmio_unreachable_replay(
                                        branch_pc,
                                        bool(take_branch),
                                        "entry_ordered_provenance",
                                        constraint_items,
                                        snapshot_entry=snapshot_entry,
                                    )
                        if direction_succeeded:
                            break

                    if (
                        allow_entry_fallback
                        and (not active_snapshot_entries or not provenance_available)
                    ):
                        cached_skip = self._branch_mmio_cached_skip_reason(
                            branch_pc,
                            bool(take_branch),
                            "entry_fallback",
                            constraint_items,
                            snapshot_entry=None,
                        )
                        if cached_skip is not None:
                            replay_mode_pruned_attempts += 1
                            if direction_attempt_outcomes is not None:
                                direction_attempt_outcomes.append(cached_skip)
                            attempt_failure_reasons[cached_skip] += 1
                            maybe_record_attempt({
                                "phase": work_phase_name,
                                "strategy": "entry_fallback",
                                "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                "target_direction": "taken" if take_branch else "not-taken",
                                "constraint_items": [
                                    self._serialize_constraint_candidate(item)
                                    for item in list(constraint_items or [])
                                ],
                                "outcome": cached_skip,
                            })
                            continue
                        control_result = entry_fallback_control_cache.get("entry_fallback")
                        if control_result is None:
                            control_replays += 1
                            control_result = self._replay_mmio_from_entry(
                                [],
                                replay_instructions=replay_instructions,
                                replay_timeout=replay_timeout,
                            )
                            entry_fallback_control_cache["entry_fallback"] = control_result
                        control_valid, control_run_result, control_events, _control_snapshots = control_result
                        control_eval = self._evaluate_branch_replay(
                            control_events,
                            bb.start_addr,
                            take_branch,
                            desired_successor,
                            control_valid,
                        )
                        if control_eval["success"]:
                            control_success_without_constraint += 1

                        entry_fallback_replays += 1
                        valid, run_result, replay_events, replay_snapshots = self._replay_mmio_from_entry(
                            constraint_items,
                            replay_instructions=replay_instructions,
                            replay_timeout=replay_timeout,
                        )
                        phase_known_before = set(self.global_coverage | phase_covered)
                        phase_covered.update(valid)
                        explored_directions += 1
                        constraints_applied += len(constraint_items)
                        result_eval = self._evaluate_branch_replay(
                            replay_events,
                            bb.start_addr,
                            take_branch,
                            desired_successor,
                            valid,
                        )
                        constraint_feedback = dict(
                            (run_result or {}).get("constraint_feedback", {}) or {}
                        )
                        candidate_materialized = self._constraints_materialized(
                            constraint_items,
                            constraint_feedback,
                            require_external=True,
                        )
                        if (
                            result_eval["success"]
                            and not control_eval["success"]
                            and candidate_materialized
                        ):
                            direction_succeeded = True
                            successful_constraint_items = list(constraint_items)
                            successful_strategy = "entry_fallback"
                            successful_replay_events = list(replay_events or [])
                            successful_replay_snapshots = list(replay_snapshots or [])
                            successful_control_events = list(control_events or [])
                            successful_replay_coverage = set(valid)
                            successful_constraint_feedback = dict(constraint_feedback)
                            successful_replay_evidence = EVIDENCE_E1
                            record_attempt(
                                phase=work_phase_name,
                                strategy="entry_fallback",
                                branch_pc_value=branch_pc,
                                target_direction=take_branch,
                                constraint_items=list(constraint_items),
                                control_eval=control_eval,
                                result_eval=result_eval,
                                constraint_feedback=constraint_feedback,
                                control_stop_reason=control_run_result.get("stop_reason"),
                                result_stop_reason=run_result.get("stop_reason"),
                                outcome="success",
                                control_valid_bbs=control_valid,
                                result_valid_bbs=valid,
                                phase_known_before=phase_known_before,
                                control_run_result_full=control_run_result,
                                result_run_result_full=run_result,
                            )
                            break
                        outcome = "candidate_not_consumed" if (
                            result_eval["success"] and not candidate_materialized
                        ) else "already_target_without_constraint" if control_eval["success"] else (
                            "branch_lost_after_constraint"
                            if control_eval.get("branch_seen") and not result_eval.get("branch_seen")
                            else (
                                "no_effect_same_outcome"
                                if control_eval.get("observed_directions") == result_eval.get("observed_directions")
                                and control_eval.get("failure_reason") == result_eval.get("failure_reason")
                                else str(result_eval.get("failure_reason") or "unknown_failure")
                            )
                        )
                        record_attempt(
                            phase=work_phase_name,
                            strategy="entry_fallback",
                            branch_pc_value=branch_pc,
                            target_direction=take_branch,
                            constraint_items=list(constraint_items),
                            control_eval=control_eval,
                            result_eval=result_eval,
                            constraint_feedback=constraint_feedback,
                            control_stop_reason=control_run_result.get("stop_reason"),
                            result_stop_reason=run_result.get("stop_reason"),
                            outcome=outcome,
                            control_valid_bbs=control_valid,
                            result_valid_bbs=valid,
                            phase_known_before=phase_known_before,
                            control_run_result_full=control_run_result,
                            result_run_result_full=run_result,
                        )
                        constraint_feedback = dict((run_result or {}).get("constraint_feedback", {}) or {})
                        if outcome == "already_target_without_constraint":
                            self._remember_single_observed_branch_direction(branch_start, bool(take_branch))
                        if outcome == "already_target_without_constraint":
                            self._remember_branch_mmio_already_target(
                                branch_pc,
                                bool(take_branch),
                                "entry_fallback",
                                snapshot_entry=None,
                            )
                        elif (
                            str(result_eval.get("failure_reason") or "") == "branch_not_reached"
                            and int(constraint_feedback.get("matched_constraint_reads", 0) or 0) == 0
                            and int(constraint_feedback.get("matched_address_reads", 0) or 0) == 0
                        ):
                            self._remember_branch_mmio_unreachable_replay(
                                branch_pc,
                                bool(take_branch),
                                "entry_fallback",
                                constraint_items,
                                snapshot_entry=None,
                            )

                if direction_succeeded and successful_constraint_items:
                    successful_constraints_external = bool(
                        successful_constraint_items
                        and all(
                            isinstance(item, BranchConstraintCandidate)
                            and item.normalized().is_environment_fact
                            for item in successful_constraint_items
                        )
                    )
                    if successful_replay_evidence == EVIDENCE_UNKNOWN:
                        successful_source_evidence = self._capture_evidence_class(
                            successful_scope_signature
                        )
                        successful_replay_evidence = derived_replay_evidence(
                            successful_source_evidence,
                            forced_control=str(successful_strategy or "").startswith(
                                "entry_"
                            ) and successful_strategy != "entry_fallback",
                            consumed_environment_fact=successful_constraints_external,
                        )
                        if not successful_constraints_external:
                            successful_replay_evidence = EVIDENCE_E2
                    if successful_replay_evidence == EVIDENCE_UNKNOWN:
                        successful_replay_evidence = EVIDENCE_E2
                    self._record_coverage_evidence(
                        successful_replay_evidence,
                        successful_replay_coverage,
                    )
                    fact_branch_key = self._paired_replay_changed_branch_key(
                        branch_bb_start=branch_start,
                        target_direction=bool(take_branch),
                        control_events=successful_control_events,
                        result_events=successful_replay_events,
                        fallback_key=successful_branch_key,
                        allow_snapshot_occurrence_translation=(successful_strategy == "snapshot"),
                    )
                    if fact_branch_key is not None:
                        self._remember_naturalization_fact(
                            branch_key=fact_branch_key,
                            branch_choice=bool(take_branch),
                            constraints=successful_constraint_items,
                            scope_signature=successful_scope_signature,
                            source_phase=work_phase_name,
                            strategy=str(successful_strategy or "unknown"),
                            constraint_feedback=successful_constraint_feedback,
                            paired_control=True,
                            local_success=True,
                        )
                    for successful_item in successful_constraint_items:
                        if isinstance(successful_item, BranchConstraintCandidate):
                            record_candidate_source(successful_constraint_source_stats, successful_item)
                    if len(successful_constraint_items) == 1:
                        persisted_candidate = successful_constraint_items[0]
                        if isinstance(persisted_candidate, BranchConstraintCandidate):
                            persisted_candidate = persisted_candidate.normalized()
                            persisted_addr = int(persisted_candidate.address)
                            persisted_value = int(persisted_candidate.value) & 0xFFFFFFFF
                            read_pc = int(persisted_candidate.read_pc) if persisted_candidate.read_pc is not None else None
                            constraint_type = str(persisted_candidate.constraint_type or "")
                            constraint_pc = int(persisted_candidate.constraint_pc) if persisted_candidate.constraint_pc is not None else self._constraint_compare_pc(branch_pc)
                            constraint_source = str(persisted_candidate.source or "")
                        else:
                            persisted_addr, persisted_value, read_pc = persisted_candidate
                            persisted_candidate = BranchConstraintCandidate(
                                constraint_type="mmio",
                                address=int(persisted_addr),
                                value=int(persisted_value),
                                read_pc=int(read_pc) if read_pc is not None else None,
                                constraint_pc=self._constraint_compare_pc(branch_pc),
                                source="legacy_tuple",
                                input_kind="mmio",
                                externally_controllable=True,
                            ).normalized()
                            constraint_type = persisted_candidate.constraint_type
                            constraint_pc = int(persisted_candidate.constraint_pc or branch_pc)
                            constraint_source = persisted_candidate.source
                        constraint_pc = self._constraint_compare_pc(branch_pc)
                        scoped_candidate = BranchConstraintCandidate(
                            constraint_type=constraint_type,
                            address=persisted_addr,
                            value=persisted_value,
                            read_pc=read_pc,
                            constraint_pc=constraint_pc,
                            source=constraint_source,
                            read_occurrence=persisted_candidate.read_occurrence,
                            input_kind=persisted_candidate.input_kind,
                            externally_controllable=persisted_candidate.externally_controllable,
                            dependency_register=persisted_candidate.dependency_register,
                            dependency_expression=persisted_candidate.dependency_expression,
                            dependency_group=persisted_candidate.dependency_group,
                            composite_dependency=persisted_candidate.composite_dependency,
                            width=persisted_candidate.width,
                        ).normalized()
                        description = (
                            f"Learned by branch_constraint ({work_phase_name}) for "
                            f"{condition} @ 0x{branch_pc:08x}, target={'taken' if take_branch else 'not-taken'}"
                        )
                        harvested_this_success = False
                        should_persist_globally = False
                        if direction_previously_observed:
                            persisted_same_direction_skips += 1
                            _mark_successful_hypothesis_persistence(
                                successful_constraint_items,
                                work_phase=work_phase_name,
                                strategy=successful_strategy,
                                branch_pc_value=branch_pc,
                                target_direction=take_branch,
                                persisted=False,
                                scoped=False,
                                outcome="same_direction_observed",
                                accept_reason="replay_reaches_target_observed_direction",
                                reject_reason="already_observed_direction",
                            )
                            if harvest_observed_retry_branch_mmio:
                                record_branch_mmio_harvest(
                                    successful_branch_key,
                                    take_branch,
                                    successful_scope_signature,
                                    successful_replay_events,
                                    successful_replay_snapshots,
                                    evidence_class=successful_replay_evidence,
                                    remember_main_events=False,
                                )
                            harvested_this_success = True
                        elif phase_is_exact_state:
                            # Exact-state replays prove a branch is locally solvable under a
                            # restored snapshot, but the learned MMIO value may be invalid when
                            # replayed globally from entry. Keep the coverage and harvested
                            # branch/snapshot feedback, but do not globalize the constraint.
                            persisted_exact_state_skips += 1
                            scoped_changed = False
                            scoped_changed = self._remember_scoped_branch_constraint_variants(
                                successful_scope_signature,
                                scoped_candidate,
                                branch_key=successful_branch_key,
                                branch_choice=take_branch,
                            )
                            if scoped_changed:
                                scoped_constraints_added += 1
                                exact_state_scoped_constraints_added += 1
                                scoped_constraint_source_stats[constraint_source or "unknown"] += 1
                            _mark_successful_hypothesis_persistence(
                                successful_constraint_items,
                                work_phase=work_phase_name,
                                strategy=successful_strategy,
                                branch_pc_value=branch_pc,
                                target_direction=take_branch,
                                persisted=False,
                                scoped=bool(scoped_changed),
                                outcome="exact_state_scoped" if scoped_changed else "exact_state_not_globalized",
                                accept_reason="replay_reaches_target_exact_state",
                                reject_reason=None if scoped_changed else "exact_state_replay_not_globalized",
                            )
                            maybe_record_scoped_constraint_debug(
                                work_phase=work_phase_name,
                                strategy=successful_strategy,
                                branch_pc=branch_pc,
                                branch_key=successful_branch_key,
                                target_direction=take_branch,
                                candidate=scoped_candidate,
                                scope_signature=successful_scope_signature,
                                changed=scoped_changed,
                            )
                            # Keep the branch eligible for the later general phase so the
                            # same direction can still be validated from a broader replay
                            # context and promoted into durable constraints if possible.
                        elif constraint_type == "mmio" and int(persisted_value) == int(persisted_addr):
                            persisted_suspicious_value_skips += 1
                            _mark_successful_hypothesis_persistence(
                                successful_constraint_items,
                                work_phase=work_phase_name,
                                strategy=successful_strategy,
                                branch_pc_value=branch_pc,
                                target_direction=take_branch,
                                persisted=False,
                                scoped=False,
                                outcome="suspicious_value_rejected",
                                accept_reason="replay_reaches_target",
                                reject_reason="value_equals_address",
                            )
                        else:
                            should_persist_globally = successful_strategy == "entry_fallback" and constraint_type == "mmio"
                            if not should_persist_globally:
                                persistence_validation_replays += 1
                                control_result = entry_fallback_control_cache.get("entry_fallback")
                                if control_result is None:
                                    control_replays += 1
                                    control_result = self._replay_mmio_from_entry(
                                        [],
                                        replay_instructions=replay_instructions,
                                        replay_timeout=replay_timeout,
                                    )
                                    entry_fallback_control_cache["entry_fallback"] = control_result
                                control_valid, control_run_result, control_events, _control_snapshots = control_result
                                control_eval = self._evaluate_branch_replay(
                                    control_events,
                                    bb.start_addr,
                                    take_branch,
                                    desired_successor,
                                    control_valid,
                                )
                                if control_eval["success"]:
                                    control_success_without_constraint += 1
                                    persistence_validation_already_success += 1
                                    self._record_coverage_evidence(EVIDENCE_E1, control_valid)
                                    self._remember_main_branch_events(
                                        control_events,
                                        overwrite_existing=False,
                                        evidence_class=EVIDENCE_E1,
                                    )
                                    self._remember_branch_root_snapshots(
                                        control_events,
                                        control_snapshots,
                                        evidence_class=EVIDENCE_E1,
                                    )
                                    self._record_dynamic_successors(control_events)
                                else:
                                    validation_valid, validation_run_result, validation_events, validation_snapshots = self._replay_mmio_from_entry(
                                        successful_constraint_items,
                                        replay_instructions=replay_instructions,
                                        replay_timeout=replay_timeout,
                                    )
                                    phase_covered.update(validation_valid)
                                    validation_eval = self._evaluate_branch_replay(
                                        validation_events,
                                        bb.start_addr,
                                        take_branch,
                                        desired_successor,
                                        validation_valid,
                                    )
                                    if validation_eval["success"]:
                                        persistence_validation_successes += 1
                                        should_persist_globally = True
                                        self._record_coverage_evidence(EVIDENCE_E1, validation_valid)
                                        self._remember_main_branch_events(
                                            validation_events,
                                            overwrite_existing=False,
                                            evidence_class=EVIDENCE_E1,
                                        )
                                        self._remember_branch_root_snapshots(
                                            validation_events,
                                            validation_snapshots,
                                            evidence_class=EVIDENCE_E1,
                                        )
                                        self._record_dynamic_successors(validation_events)
                                    else:
                                        persistence_validation_scoped_fallbacks += 1
                            if should_persist_globally and self._persist_branch_mmio_constraint(
                                read_pc,
                                persisted_addr,
                                persisted_value,
                                constraint_pc,
                                branch_pc,
                                take_branch,
                                description,
                                source=constraint_source,
                                read_occurrence=scoped_candidate.read_occurrence,
                            ):
                                persisted_constraints += 1
                                persisted_constraint_source_stats[constraint_source or "unknown"] += 1
                                if len(persisted_constraint_details) < 64:
                                    persisted_constraint_details.append({
                                        "phase": work_phase_name,
                                        "branch_pc": f"0x{int(branch_pc) & 0xFFFFFFFF:08x}",
                                        "target_direction": "taken" if take_branch else "not-taken",
                                        "mmio_addr": f"0x{int(persisted_addr) & 0xFFFFFFFF:08x}",
                                        "read_pc": f"0x{int(read_pc) & 0xFFFFFFFF:08x}" if read_pc is not None else None,
                                        "read_occurrence": scoped_candidate.read_occurrence,
                                        "constraint_pc": f"0x{int(constraint_pc) & 0xFFFFFFFF:08x}",
                                        "value": f"0x{int(persisted_value) & 0xFFFFFFFF:08x}",
                                        "strategy": successful_strategy,
                                        "type": constraint_type,
                                        "source": constraint_source or None,
                                    })
                                if harvest_persisted_branch_mmio:
                                    # Persisted branch-MMIO constraints are filtered from runtime
                                    # loading by default, so harvesting them remains useful for
                                    # downstream root/snapshot discovery without reintroducing the
                                    # old global-constraint pollution.
                                    record_branch_mmio_harvest(
                                        successful_branch_key,
                                        take_branch,
                                        successful_scope_signature,
                                        successful_replay_events,
                                        successful_replay_snapshots,
                                        evidence_class=successful_replay_evidence,
                                    )
                                    harvested_this_success = True
                                if successful_strategy != "snapshot" or not phase_is_exact_state:
                                    exact_state_generalized_branch_starts.add(branch_start)
                                _mark_successful_hypothesis_persistence(
                                    successful_constraint_items,
                                    work_phase=work_phase_name,
                                    strategy=successful_strategy,
                                    branch_pc_value=branch_pc,
                                    target_direction=take_branch,
                                    persisted=True,
                                    scoped=False,
                                    outcome="persisted_global_constraint",
                                    accept_reason="replay_reaches_target_and_persisted",
                                )
                            elif should_persist_globally:
                                persisted_constraint_write_skips += 1
                                _mark_successful_hypothesis_persistence(
                                    successful_constraint_items,
                                    work_phase=work_phase_name,
                                    strategy=successful_strategy,
                                    branch_pc_value=branch_pc,
                                    target_direction=take_branch,
                                    persisted=False,
                                    scoped=False,
                                    outcome="persist_write_skipped",
                                    accept_reason="replay_reaches_target",
                                    reject_reason="constraint_write_skipped",
                                )
                            else:
                                scoped_changed = False
                                scoped_changed = self._remember_scoped_branch_constraint_variants(
                                    successful_scope_signature,
                                    scoped_candidate,
                                    branch_key=successful_branch_key,
                                    branch_choice=take_branch,
                                )
                                maybe_record_scoped_constraint_debug(
                                    work_phase=work_phase_name,
                                    strategy=successful_strategy,
                                    branch_pc=branch_pc,
                                    branch_key=successful_branch_key,
                                    target_direction=take_branch,
                                    candidate=scoped_candidate,
                                    scope_signature=successful_scope_signature,
                                    changed=scoped_changed,
                                )
                                if scoped_changed:
                                    scoped_constraints_added += 1
                                    scoped_constraint_source_stats[constraint_source or "unknown"] += 1
                                else:
                                    persisted_constraint_write_skips += 1
                                _mark_successful_hypothesis_persistence(
                                    successful_constraint_items,
                                    work_phase=work_phase_name,
                                    strategy=successful_strategy,
                                    branch_pc_value=branch_pc,
                                    target_direction=take_branch,
                                    persisted=False,
                                    scoped=bool(scoped_changed),
                                    outcome="scoped_constraint" if scoped_changed else "scoped_write_skipped",
                                    accept_reason="replay_reaches_target",
                                    reject_reason=None if scoped_changed else "scoped_constraint_write_skipped",
                                )
                        if not harvested_this_success and (
                            direction_previously_observed
                            or phase_is_exact_state
                            or not should_persist_globally
                        ):
                            record_branch_mmio_harvest(
                                successful_branch_key,
                                take_branch,
                                successful_scope_signature,
                                successful_replay_events,
                                successful_replay_snapshots,
                                evidence_class=successful_replay_evidence,
                                remember_main_events=not direction_previously_observed,
                                overwrite_main_events=not direction_previously_observed,
                            )
                    else:
                        record_branch_mmio_harvest(
                            successful_branch_key,
                            take_branch,
                            successful_scope_signature,
                            successful_replay_events,
                            successful_replay_snapshots,
                            evidence_class=successful_replay_evidence,
                            remember_main_events=not direction_previously_observed,
                            overwrite_main_events=not direction_previously_observed,
                        )
                        persisted_multi_candidate_skips += 1
                        _mark_successful_hypothesis_persistence(
                            successful_constraint_items,
                            work_phase=work_phase_name,
                            strategy=successful_strategy,
                            branch_pc_value=branch_pc,
                            target_direction=take_branch,
                            persisted=False,
                            scoped=False,
                            outcome="multi_candidate_not_persisted",
                            accept_reason="replay_reaches_target",
                            reject_reason="multi_candidate_constraint",
                        )
                elif (
                    weak_direction
                    and direction_attempt_outcomes
                    and all(outcome == "no_effect_same_outcome" for outcome in direction_attempt_outcomes)
                ):
                    self.branch_mmio_exhausted_weak_directions.add((int(branch_pc), bool(take_branch)))

                if direction_succeeded:
                    branch_changed = True

            if branch_changed:
                changed_branch_starts.add(branch_start)
                if phase_is_exact_state:
                    exact_state_successful_branch_starts.add(branch_start)

        constraint_stats_after = self._constraint_file_stats()
        llm_history_entries_delta = len(self.llm_guide.get_inference_history()) - llm_calls_before
        llm_actual_calls = int(inference_metric_stats.get("llm_actual_calls", 0) or 0)
        return self._record_phase(
            phase_name,
            phase_covered,
            branches_considered=len(branch_work_items),
            unique_branches_considered=len({
                int(item[0].start_addr)
                for _phase, item in branch_work_items
            }),
            general_branches_considered=len(base_candidate_branches),
            observed_retry_branches_scheduled=len(observed_retry_candidate_branches),
            observed_retry_front_branches_scheduled=len(front_observed_retry_candidate_branches),
            observed_retry_tail_branches_scheduled=len(tail_observed_retry_candidate_branches),
            observed_retry_min_round=observed_retry_min_round,
            observed_retry_front_limit=observed_retry_front_limit,
            observed_retry_direction_limit=observed_retry_direction_limit,
            observed_retry_requested=observed_retry_requested,
            harvest_observed_retry_branch_mmio=harvest_observed_retry_branch_mmio,
            branch_mmio_success_limit=branch_mmio_success_limit,
            round1_success_limit=round1_success_limit,
            phase_success_limit=phase_success_limit,
            branch_mmio_round=branch_mmio_round,
            branches_changed=len(changed_branch_starts),
            directions_replayed=explored_directions,
            constraints_applied=constraints_applied,
            replay_instructions=replay_instructions,
            time_limit_seconds=time_limit_seconds,
            branches_skipped_no_candidates=skipped_no_candidates,
            branches_skipped_unsupported=skipped_unsupported,
            branches_skipped_zero_potential=skipped_zero_potential_branches,
            branches_skipped_non_mmio=skipped_non_mmio_branches,
            allow_default_candidates=allow_default_candidates,
            llm_inference_calls=llm_actual_calls,
            llm_actual_calls=llm_actual_calls,
            llm_inference_history_entries=llm_history_entries_delta,
            llm_successful_values=int(inference_metric_stats.get("llm_successful_values", 0) or 0),
            llm_rejected=int(inference_metric_stats.get("llm_rejected", 0) or 0),
            llm_errors=int(inference_metric_stats.get("llm_errors", 0) or 0),
            rule_inference_entries=int(inference_metric_stats.get("rule_inference_entries", 0) or 0),
            inference_cache_hits=int(inference_metric_stats.get("inference_cache_hits", 0) or 0),
            inference_method_stats=dict(inference_method_stats),
            inference_cache_method_stats=dict(inference_cache_method_stats),
            available_prefix_branch_candidates=len(prefix_branch_candidates),
            exact_state_first=exact_state_first,
            exact_state_branch_quota=exact_state_branch_quota,
            exact_state_branches_scheduled=exact_state_branches_scheduled,
            exact_state_branches_changed=len(exact_state_successful_branch_starts),
            exact_state_directions_replayed=exact_state_directions_replayed,
            exact_state_snapshot_replays=exact_state_snapshot_replays,
            exact_state_snapshot_successes=exact_state_snapshot_successes,
            persisted_constraints=persisted_constraints,
            persisted_constraint_write_skips=persisted_constraint_write_skips,
            persisted_multi_candidate_skips=persisted_multi_candidate_skips,
            scoped_constraints_added=scoped_constraints_added,
            persisted_exact_state_skips=persisted_exact_state_skips,
            exact_state_scoped_constraints_added=exact_state_scoped_constraints_added,
            persistence_validation_replays=persistence_validation_replays,
            persistence_validation_successes=persistence_validation_successes,
            persistence_validation_already_success=persistence_validation_already_success,
            persistence_validation_scoped_fallbacks=persistence_validation_scoped_fallbacks,
            harvested_branch_events=harvested_branch_events,
            harvested_observed_direction_updates=harvested_observed_direction_updates,
            harvested_branch_root_snapshots=harvested_branch_root_snapshots,
            harvested_dynamic_successor_edges=harvested_dynamic_successor_edges,
            harvested_seed_roots=harvested_seed_roots,
            harvested_child_tasks=harvested_child_tasks,
            skipped_observed_directions=skipped_observed_directions,
            deferred_observed_directions=deferred_observed_directions,
            retried_observed_directions=retried_observed_directions,
            persisted_same_direction_skips=persisted_same_direction_skips,
            persisted_suspicious_value_skips=persisted_suspicious_value_skips,
            persisted_constraint_details=persisted_constraint_details,
            scoped_constraint_debug_records=scoped_constraint_debug_records,
            attempt_failure_reasons=dict(attempt_failure_reasons),
            attempt_records=attempt_records,
            hypothesis_audit_schema="hypothesis_audit.v1",
            hypothesis_audit_records=hypothesis_audit_records,
            hypothesis_audit_record_count=len(hypothesis_audit_records),
            attempt_source_stats=dict(attempt_source_stats),
            replayed_attempt_source_stats=dict(replayed_attempt_source_stats),
            successful_attempt_source_stats=dict(successful_attempt_source_stats),
            attempt_new_bbs_vs_control_by_source=dict(attempt_new_bbs_vs_control_by_source),
            attempt_new_bbs_vs_global_by_source=dict(attempt_new_bbs_vs_global_by_source),
            attempt_new_bbs_vs_phase_before_by_source=dict(attempt_new_bbs_vs_phase_by_source),
            llm_derived_attempts=source_counter_total(attempt_source_stats, "llm"),
            llm_derived_replayed_attempts=source_counter_total(replayed_attempt_source_stats, "llm"),
            llm_derived_success_attempts=source_counter_total(successful_attempt_source_stats, "llm"),
            llm_derived_new_bbs_vs_control=source_counter_total(attempt_new_bbs_vs_control_by_source, "llm"),
            llm_derived_new_bbs_vs_global=source_counter_total(attempt_new_bbs_vs_global_by_source, "llm"),
            llm_derived_new_bbs_vs_phase_before=source_counter_total(attempt_new_bbs_vs_phase_by_source, "llm"),
            rule_derived_attempts=source_counter_total(attempt_source_stats, "rules"),
            rule_derived_replayed_attempts=source_counter_total(replayed_attempt_source_stats, "rules"),
            rule_derived_success_attempts=source_counter_total(successful_attempt_source_stats, "rules"),
            rule_derived_new_bbs_vs_control=source_counter_total(attempt_new_bbs_vs_control_by_source, "rules"),
            rule_derived_new_bbs_vs_global=source_counter_total(attempt_new_bbs_vs_global_by_source, "rules"),
            rule_derived_new_bbs_vs_phase_before=source_counter_total(attempt_new_bbs_vs_phase_by_source, "rules"),
            control_replays=control_replays,
            control_restore_failures=control_restore_failures,
            control_success_without_constraint=control_success_without_constraint,
            provenance_warmup_attempts=provenance_warmup_attempts,
            provenance_warmup_successes=provenance_warmup_successes,
            constraint_file_before=constraint_stats_before,
            constraint_file_after=constraint_stats_after,
            constraint_file_added=max(
                0,
                int(constraint_stats_after.get("total_constraints", 0))
                - int(constraint_stats_before.get("total_constraints", 0)),
            ),
            branch_mmio_constraints_added=max(
                0,
                int(constraint_stats_after.get("branch_mmio_constraints", 0))
                - int(constraint_stats_before.get("branch_mmio_constraints", 0)),
            ),
            snapshot_variants_per_branch=snapshot_variants_per_branch,
            snapshot_replays=snapshot_replays,
            snapshot_successes=snapshot_successes,
            snapshot_prefix_replays=snapshot_prefix_replays,
            snapshot_root_replays=snapshot_root_replays,
            snapshot_direct_replays=snapshot_direct_replays,
            snapshot_restore_failures=snapshot_restore_failures,
            entry_fallback_replays=entry_fallback_replays,
            entry_provenance_replays=entry_provenance_replays,
            entry_provenance_successes=entry_provenance_successes,
            entry_ordered_provenance_replays=entry_ordered_provenance_replays,
            entry_ordered_provenance_successes=entry_ordered_provenance_successes,
            skipped_zero_potential_directions=skipped_zero_potential_directions_count,
            skipped_exhausted_weak_directions=skipped_exhausted_weak_directions,
            skip_zero_potential_directions=skip_zero_potential_directions,
            dependency_candidate_stats=dict(branch_dependency_stats),
            built_constraint_stats=dict(built_constraint_stats),
            built_constraint_source_stats=dict(built_constraint_source_stats),
            llm_derived_candidates_built=source_counter_total(built_constraint_source_stats, "llm"),
            rule_derived_candidates_built=source_counter_total(built_constraint_source_stats, "rules"),
            replay_constraint_stats=dict(replay_constraint_stats),
            replay_constraint_source_stats=dict(replay_constraint_source_stats),
            llm_derived_candidates_replayed=source_counter_total(replay_constraint_source_stats, "llm"),
            rule_derived_candidates_replayed=source_counter_total(replay_constraint_source_stats, "rules"),
            successful_constraint_source_stats=dict(successful_constraint_source_stats),
            llm_derived_constraints_successful=source_counter_total(successful_constraint_source_stats, "llm"),
            rule_derived_constraints_successful=source_counter_total(successful_constraint_source_stats, "rules"),
            persisted_constraint_source_stats=dict(persisted_constraint_source_stats),
            llm_derived_constraints_persisted=source_counter_total(persisted_constraint_source_stats, "llm"),
            rule_derived_constraints_persisted=source_counter_total(persisted_constraint_source_stats, "rules"),
            scoped_constraint_source_stats=dict(scoped_constraint_source_stats),
            llm_derived_constraints_scoped=source_counter_total(scoped_constraint_source_stats, "llm"),
            llm_second_opinion_enabled=enable_llm_second_opinion,
            llm_second_opinion_budget=llm_second_opinion_budget,
            llm_second_opinion_calls=llm_second_opinion_calls,
            rule_derived_constraints_scoped=source_counter_total(scoped_constraint_source_stats, "rules"),
            replay_mode_pruned_attempts=replay_mode_pruned_attempts,
            branch_mmio_unreachable_replay_cache_entries=len(self.branch_mmio_unreachable_replays),
            branch_mmio_already_target_cache_entries=len(self.branch_mmio_already_target_replays),
            replay_window_skips=replay_window_skips,
        )

    def run_interleaved_reservoir_mmio_exploration(
        self,
        total_time_seconds: Optional[int] = None,
        reservoir_round_seconds: int = 180,
        mmio_round_seconds: int = 60,
        frontier_round_seconds: int = 0,
        frontier_max_targets: int = 128,
        frontier_min_uncovered_successors: int = 1,
        frontier_switch_only: bool = False,
        max_rounds: int = 0,
        stale_round_limit: int = 2,
        min_progress_bbs: int = 1,
        reservoir_max_tasks: int = 400,
        reservoir_replay_instructions: int = 50000,
        reservoir_replay_timeout: int = 1_000_000,
        mmio_max_branches: int = 8,
        mmio_replay_instructions: int = 50000,
        mmio_replay_timeout: int = 1_000_000,
        mmio_snapshot_variants_per_branch: int = 4,
        adaptive_plateau_round_limit: int = 0,
        adaptive_plateau_min_rounds: int = 0,
    ) -> Set[int]:
        start_time = time.time()
        phase_covered: Set[int] = set()
        rounds = []
        stale_rounds = 0
        adaptive_plateau_idle_rounds = 0
        round_index = 0
        stop_reason = "budget_exhausted_or_completed"

        def round_phase_summary(meta: Dict[str, object]) -> Dict[str, object]:
            """Keep round accounting without embedding a second phase report."""
            keys = (
                "covered_bbs",
                "new_bbs",
                "tasks_run",
                "tasks_with_new_bbs",
                "remembered_branch_events",
                "remembered_branch_root_snapshots",
                "priority_root_tasks_seeded",
                "dynamic_successor_edges_added",
                "persisted_constraints",
                "scoped_constraints_added",
                "stage_wall_seconds",
                "stage_process_cpu_seconds",
                "stop_reason",
            )
            return {
                key: meta[key]
                for key in keys
                if key in meta
            }
        try:
            interleaved_stale_replay_interval = int(
                os.environ.get("LSGEMU_INTERLEAVED_STALE_REPLAY_INTERVAL", "16")
            )
        except ValueError:
            interleaved_stale_replay_interval = 16
        try:
            interleaved_edge_zero_new_limit = int(
                os.environ.get("LSGEMU_INTERLEAVED_EDGE_ZERO_NEW_LIMIT", "1")
            )
        except ValueError:
            interleaved_edge_zero_new_limit = 1
        try:
            interleaved_frontier_new_bbs_threshold = int(
                os.environ.get("LSGEMU_INTERLEAVED_FRONTIER_NEW_BBS_THRESHOLD", "128")
            )
        except ValueError:
            interleaved_frontier_new_bbs_threshold = 128
        try:
            interleaved_frontier_min_budget_seconds = int(
                os.environ.get("LSGEMU_INTERLEAVED_FRONTIER_MIN_BUDGET_SECONDS", "15")
            )
        except ValueError:
            interleaved_frontier_min_budget_seconds = 15
        interleaved_proportional_budget = (
            str(os.environ.get("LSGEMU_INTERLEAVED_PROPORTIONAL_BUDGET", "0")).strip().lower()
            not in {"", "0", "false", "no"}
        )

        while True:
            if max_rounds and round_index >= max_rounds:
                stop_reason = "max_rounds_reached"
                break
            elapsed = time.time() - start_time
            if total_time_seconds is not None and elapsed >= total_time_seconds:
                stop_reason = "time_budget_exhausted"
                break

            remaining = None
            if total_time_seconds is not None:
                remaining = max(0, int(total_time_seconds - elapsed))
                if remaining <= 0:
                    stop_reason = "time_budget_exhausted"
                    break

            reservoir_budget = max(0, int(reservoir_round_seconds))
            mmio_budget = max(0, int(mmio_round_seconds))
            frontier_budget = max(0, int(frontier_round_seconds))
            if remaining is not None:
                if remaining <= 0:
                    break
                total_requested = reservoir_budget + mmio_budget + frontier_budget
                if interleaved_proportional_budget and total_requested > 0 and total_requested > remaining:
                    active_buckets = sum(1 for value in (reservoir_budget, mmio_budget, frontier_budget) if value > 0)
                    min_reserved = max(0, active_buckets - 1)
                    if active_buckets >= 2 and remaining > min_reserved:
                        scaled_reservoir = max(
                            0,
                            int(round((remaining * reservoir_budget) / total_requested)),
                        )
                        scaled_mmio = max(
                            0,
                            int(round((remaining * mmio_budget) / total_requested)),
                        )
                        scaled_frontier = max(0, remaining - scaled_reservoir - scaled_mmio)
                        positive_indices = [index for index, value in enumerate((reservoir_budget, mmio_budget, frontier_budget)) if value > 0]
                        scaled_values = [scaled_reservoir, scaled_mmio, scaled_frontier]
                        for index in positive_indices:
                            if scaled_values[index] <= 0 and remaining >= active_buckets:
                                scaled_values[index] = 1
                        total_scaled = sum(scaled_values)
                        while total_scaled > remaining:
                            for index in sorted(
                                positive_indices,
                                key=lambda idx: scaled_values[idx],
                                reverse=True,
                            ):
                                if scaled_values[index] > 1:
                                    scaled_values[index] -= 1
                                    total_scaled -= 1
                                    if total_scaled <= remaining:
                                        break
                            else:
                                break
                        while total_scaled < remaining:
                            best_index = max(
                                positive_indices,
                                key=lambda idx: (reservoir_budget, mmio_budget, frontier_budget)[idx],
                            )
                            scaled_values[best_index] += 1
                            total_scaled += 1
                        scaled_reservoir, scaled_mmio, scaled_frontier = scaled_values
                        reservoir_budget = scaled_reservoir
                        mmio_budget = scaled_mmio
                        frontier_budget = scaled_frontier
                    elif reservoir_budget > 0:
                        reservoir_budget = remaining
                        mmio_budget = 0
                        frontier_budget = 0
                    else:
                        if mmio_budget > 0:
                            mmio_budget = remaining
                            frontier_budget = 0
                        else:
                            frontier_budget = remaining
                else:
                    if reservoir_budget > remaining:
                        reservoir_budget = remaining
                    remaining_after_reservoir = max(0, remaining - reservoir_budget)
                    if mmio_budget > remaining_after_reservoir:
                        mmio_budget = remaining_after_reservoir
                    remaining_after_mmio = max(0, remaining_after_reservoir - mmio_budget)
                    if frontier_budget > remaining_after_mmio:
                        frontier_budget = remaining_after_mmio

            if reservoir_budget <= 0 and mmio_budget <= 0 and frontier_budget <= 0:
                stop_reason = "no_stage_budget_remaining"
                break

            round_index += 1
            constraint_stats_before_round = self._constraint_file_stats()
            round_info: Dict[str, object] = {
                "round": round_index,
                "coverage_before_round": len(self.global_coverage),
                "reservoir_budget_seconds": reservoir_budget,
                "mmio_budget_seconds": mmio_budget,
                "frontier_budget_seconds": frontier_budget,
                "constraint_stats_before_round": constraint_stats_before_round,
            }
            reservoir_meta: Dict[str, object] = {}
            mmio_meta: Dict[str, object] = {}
            frontier_meta: Dict[str, object] = {}

            if reservoir_budget > 0:
                before_reservoir = len(self.global_coverage)
                reservoir_phase_name = f"branch_reservoir_round_{round_index}"
                reservoir_valid = self.run_reservoir_branch_exploration(
                    time_limit_seconds=reservoir_budget,
                    replay_instructions=reservoir_replay_instructions,
                    replay_timeout=reservoir_replay_timeout,
                    max_tasks=reservoir_max_tasks,
                    stale_replay_interval=interleaved_stale_replay_interval,
                    edge_zero_new_limit=interleaved_edge_zero_new_limit,
                    # cycle2 k.5 C4：round_N 装配预算旗标——装配吃光预算时
                    # 也发 bootstrap 窗口（触发判据 r-分母 v2 = finalize 报告
                    # phase_metadata 的 budget_zeroed_phases 谓词，None 守卫）。
                    setup_budget_target_bootstrap=True,
                    phase_name=reservoir_phase_name,
                )
                phase_covered.update(reservoir_valid)
                reservoir_meta = dict(self.phase_metadata.get(reservoir_phase_name, {}))
                round_info["reservoir_phase_name"] = reservoir_phase_name
                round_info["reservoir_new_bbs"] = len(self.global_coverage) - before_reservoir
                round_info["reservoir_summary"] = round_phase_summary(reservoir_meta)
            else:
                round_info["reservoir_new_bbs"] = 0

            round_info["constraint_stats_before_mmio"] = self._constraint_file_stats()

            if mmio_budget > 0:
                before_mmio = len(self.global_coverage)
                mmio_phase_name = f"branch_mmio_round_{round_index}"
                mmio_valid = self.run_mmio_branch_exploration(
                    max_branches=mmio_max_branches,
                    time_limit_seconds=mmio_budget,
                    replay_instructions=mmio_replay_instructions,
                    replay_timeout=mmio_replay_timeout,
                    snapshot_variants_per_branch=mmio_snapshot_variants_per_branch,
                    skip_zero_potential_directions=True,
                    exact_state_first=True,
                    phase_name=mmio_phase_name,
                )
                phase_covered.update(mmio_valid)
                mmio_meta = dict(self.phase_metadata.get(mmio_phase_name, {}))
                round_info["mmio_phase_name"] = mmio_phase_name
                round_info["mmio_new_bbs"] = len(self.global_coverage) - before_mmio
                round_info["mmio_summary"] = round_phase_summary(mmio_meta)
            else:
                round_info["mmio_new_bbs"] = 0

            should_run_frontier = (
                frontier_budget > 0
                and frontier_budget >= max(1, interleaved_frontier_min_budget_seconds)
                and (
                    int(round_info.get("reservoir_new_bbs", 0)) <= max(0, interleaved_frontier_new_bbs_threshold)
                    or int(round_info.get("mmio_new_bbs", 0)) > 0
                )
            )
            round_info["frontier_budget_triggered"] = should_run_frontier

            if should_run_frontier:
                current_targets = self.frontier_target_bbs(
                    min_uncovered_successors=max(1, int(frontier_min_uncovered_successors)),
                    switch_only=bool(frontier_switch_only),
                    max_targets=max(0, int(frontier_max_targets)),
                )
                round_info["frontier_candidate_targets"] = len(current_targets)
                if current_targets:
                    before_frontier = len(self.global_coverage)
                    frontier_phase_name = f"frontier_targeted_round_{round_index}"
                    frontier_valid = self.run_reservoir_branch_exploration(
                        time_limit_seconds=frontier_budget,
                        replay_instructions=reservoir_replay_instructions,
                        replay_timeout=reservoir_replay_timeout,
                        max_tasks=reservoir_max_tasks,
                        stale_replay_interval=interleaved_stale_replay_interval,
                        edge_zero_new_limit=interleaved_edge_zero_new_limit,
                        dynamic_frontier_seeding=True,
                        target_bbs=current_targets,
                        prioritize_target_bbs=True,
                        continue_target_merges=True,
                        target_probe_bbs=min(512, max(64, reservoir_replay_instructions // 100)),
                        phase_name=frontier_phase_name,
                        reset_state=True,
                    )
                    phase_covered.update(frontier_valid)
                    frontier_meta = dict(self.phase_metadata.get(frontier_phase_name, {}))
                    round_info["frontier_phase_name"] = frontier_phase_name
                    round_info["frontier_new_bbs"] = len(self.global_coverage) - before_frontier
                    round_info["frontier_summary"] = round_phase_summary(frontier_meta)
                else:
                    round_info["frontier_new_bbs"] = 0
            else:
                round_info["frontier_new_bbs"] = 0

            round_total_new = (
                int(round_info.get("reservoir_new_bbs", 0))
                + int(round_info.get("mmio_new_bbs", 0))
                + int(round_info.get("frontier_new_bbs", 0))
            )
            round_info["round_new_bbs"] = round_total_new
            round_info["coverage_after_round"] = len(self.global_coverage)
            constraint_stats_after_round = self._constraint_file_stats()
            round_info["constraint_stats_after_round"] = constraint_stats_after_round
            round_info["constraints_added_this_round"] = max(
                0,
                int(constraint_stats_after_round.get("total_constraints", 0))
                - int(constraint_stats_before_round.get("total_constraints", 0)),
            )
            round_info["branch_mmio_constraints_added_this_round"] = max(
                0,
                int(constraint_stats_after_round.get("branch_mmio_constraints", 0))
                - int(constraint_stats_before_round.get("branch_mmio_constraints", 0)),
            )
            round_structural_progress = any((
                round_total_new > 0,
                int(round_info.get("constraints_added_this_round", 0)) > 0,
                int(round_info.get("branch_mmio_constraints_added_this_round", 0)) > 0,
                int(reservoir_meta.get("remembered_branch_events", 0) or 0) > 0,
                int(reservoir_meta.get("remembered_branch_root_snapshots", 0) or 0) > 0,
                int(reservoir_meta.get("priority_root_tasks_seeded", 0) or 0) > 0,
                int(reservoir_meta.get("dynamic_successor_edges_added", 0) or 0) > 0,
                int(mmio_meta.get("remembered_branch_events", 0) or 0) > 0,
                int(mmio_meta.get("remembered_branch_root_snapshots", 0) or 0) > 0,
                int(mmio_meta.get("priority_root_tasks_seeded", 0) or 0) > 0,
                int(mmio_meta.get("dynamic_successor_edges_added", 0) or 0) > 0,
                int(frontier_meta.get("remembered_branch_events", 0) or 0) > 0,
                int(frontier_meta.get("remembered_branch_root_snapshots", 0) or 0) > 0,
                int(frontier_meta.get("priority_root_tasks_seeded", 0) or 0) > 0,
                int(frontier_meta.get("dynamic_successor_edges_added", 0) or 0) > 0,
            ))
            round_info["adaptive_plateau_progress"] = bool(round_structural_progress)
            rounds.append(round_info)

            if round_total_new < max(0, int(min_progress_bbs)):
                stale_rounds += 1
            else:
                stale_rounds = 0
            if round_structural_progress:
                adaptive_plateau_idle_rounds = 0
            else:
                adaptive_plateau_idle_rounds += 1
            round_info["adaptive_plateau_idle_rounds"] = adaptive_plateau_idle_rounds

            if stale_round_limit > 0 and stale_rounds >= stale_round_limit:
                stop_reason = "stale_round_limit_reached"
                round_info["stop_reason"] = stop_reason
                round_info["stop_triggered"] = True
                round_info["stop_trigger"] = "stale_round_limit"
                break
            if (
                adaptive_plateau_round_limit > 0
                and round_index >= max(0, int(adaptive_plateau_min_rounds))
                and adaptive_plateau_idle_rounds >= max(1, int(adaptive_plateau_round_limit))
            ):
                stop_reason = "adaptive_plateau_reached"
                round_info["stop_reason"] = stop_reason
                round_info["stop_triggered"] = True
                round_info["stop_trigger"] = "adaptive_plateau"
                break

        return self._record_phase(
            "branch_interleaved",
            phase_covered,
            rounds_completed=round_index,
            stale_round_limit=stale_round_limit,
            min_progress_bbs=min_progress_bbs,
            reservoir_round_seconds=reservoir_round_seconds,
            mmio_round_seconds=mmio_round_seconds,
            frontier_round_seconds=frontier_round_seconds,
            frontier_max_targets=frontier_max_targets,
            frontier_min_uncovered_successors=frontier_min_uncovered_successors,
            frontier_switch_only=frontier_switch_only,
            interleaved_stale_replay_interval=interleaved_stale_replay_interval,
            interleaved_edge_zero_new_limit=interleaved_edge_zero_new_limit,
            interleaved_proportional_budget=interleaved_proportional_budget,
            max_rounds=max_rounds,
            total_time_seconds=total_time_seconds,
            adaptive_plateau_round_limit=adaptive_plateau_round_limit,
            adaptive_plateau_min_rounds=adaptive_plateau_min_rounds,
            stop_reason=stop_reason,
            constraint_file_after=self._constraint_file_stats(),
            rounds=rounds,
        )

    def run_snapshot_branch_exploration(
        self,
        max_branches: Optional[int] = None,
        time_limit_seconds: Optional[int] = None,
        replay_instructions: int = 50000,
        replay_timeout: int = 1_000_000,
    ) -> Set[int]:
        branches = sorted(
            [
                bb for bb in self.conditional_branches()
                if self.emulator.branch_snapshot_manager.has_snapshot(bb.start_addr)
            ],
            key=lambda bb: (all(successor in self.global_coverage for successor in bb.successors), bb.start_addr),
        )
        if max_branches is not None:
            branches = branches[:max_branches]

        start_time = time.time()
        phase_covered: Set[int] = set()
        flipped_directions = 0
        child_execution_records: List[Dict[str, object]] = []
        child_attempt_count = 0

        for bb in branches:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                break

            snapshot = self.emulator.branch_snapshot_manager.get_snapshot(bb.start_addr)
            if snapshot is None:
                continue

            for take_branch in (True, False):
                target = snapshot.target if take_branch else snapshot.fallthrough
                if target in self.global_coverage:
                    continue

                child_attempt_count += 1
                execution_id = (
                    f"branch_snapshot-{child_attempt_count}"
                )
                try:
                    temp_emulator = self._new_temp_emulator(
                        max_snapshots=max(3, self.max_snapshots),
                        llm_config_path=self._effective_llm_config_path(),
                        constraint_json_path=self.constraint_file,
                        branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                        stage_name=self._temp_stage_for("branch_snapshot_replay"),
                    )
                except Exception as exc:
                    child_execution_records.append(
                        self._execution_failure_evidence_record(
                            phase_name="branch_snapshot",
                            execution_id=execution_id,
                            reason="emulator_create_exception",
                            metadata={
                                "entry_derivation": "reset_entry_branch_snapshot_probe",
                                "coverage_counted": True,
                                "branch": int(snapshot.address),
                                "requested_direction": bool(take_branch),
                            },
                            execution_started=False,
                            execution_error=exc,
                        )
                    )
                    logger.debug("branch snapshot emulator creation failed: %s", exc)
                    continue
                temp_mmio = None
                try:
                    temp_emulator.enable_branch_snapshot = True
                    temp_emulator.set_forced_branch_choices({snapshot.address: take_branch})
                    temp_mmio = EnhancedMMIOHandler(
                        temp_emulator.uc,
                        self.constraint_file,
                        branch_mmio_file_mode=self.runtime_branch_mmio_file_mode,
                    )
                except Exception as exc:
                    failure_result = self._materialize_replay_failure_result(
                        "replay_setup_exception",
                        execution_started=False,
                        execution_error=exc,
                    )
                    try:
                        self._safe_dispose_temp_emulator(
                            temp_emulator,
                            mmio_handler=temp_mmio,
                            quarantine=None,
                            stage_name=self._temp_stage_for("branch_snapshot_replay"),
                            run_result=failure_result,
                        )
                    except Exception as cleanup_error:
                        logger.debug("branch snapshot setup cleanup failed: %s", cleanup_error)
                    child_execution_records.append(
                        self._execution_failure_evidence_record(
                            phase_name="branch_snapshot",
                            execution_id=execution_id,
                            reason="replay_setup_exception",
                            metadata={
                                "entry_derivation": "reset_entry_branch_snapshot_probe",
                                "coverage_counted": True,
                                "branch": int(snapshot.address),
                                "requested_direction": bool(take_branch),
                            },
                            execution_started=False,
                            execution_error=exc,
                            run_result=failure_result,
                        )
                    )
                    continue

                covered: Set[int] = set()
                run_result: Dict[str, object] = self._materialize_replay_failure_result(
                    "execution_not_started",
                    execution_started=False,
                )
                run_exception: Optional[BaseException] = None
                try:
                    with self.guided_modules(temp_mmio), self.capture_coverage(temp_emulator) as trace:
                        try:
                            raw_run_result = temp_emulator.run(
                                entry_point=self.prepared.entry_point,
                                max_instructions=replay_instructions,
                                timeout_seconds=replay_timeout / 1_000_000 if replay_timeout else None,
                            )
                            run_result = self._normalize_replay_run_result(
                                raw_run_result,
                                execution_started=True,
                            )
                        except Exception as exc:
                            run_exception = exc
                            run_result = self._materialize_replay_failure_result(
                                "execution_exception",
                                execution_started=True,
                                execution_error=exc,
                            )
                        covered = self.validate_coverage(trace.covered_bbs)

                    if run_exception is not None:
                        child_execution_records.append(
                            self._execution_failure_evidence_record(
                                phase_name="branch_snapshot",
                                execution_id=execution_id,
                                reason="execution_exception",
                                metadata={
                                    "entry_derivation": "reset_entry_branch_snapshot_probe",
                                    "coverage_counted": True,
                                    "branch": int(snapshot.address),
                                    "requested_direction": bool(take_branch),
                                },
                                covered_bbs=(),
                                execution_started=True,
                                execution_error=run_exception,
                                run_result=run_result,
                            )
                        )
                    else:
                        child_execution_records.append(
                            build_execution_evidence_record(
                                phase_name="branch_snapshot",
                                run_result=run_result,
                                covered_bbs=covered,
                                metadata={
                                    "entry_derivation": "reset_entry_branch_snapshot_probe",
                                    "coverage_counted": True,
                                    "branch": int(snapshot.address),
                                    "requested_direction": bool(take_branch),
                                },
                                execution_id=execution_id,
                            )
                        )
                    phase_covered.update(covered)
                    flipped_directions += 1
                except Exception as exc:
                    # Trace/metadata collection must not leak a poisoned
                    # temporary engine into the next direction.
                    child_execution_records.append(
                        self._execution_failure_evidence_record(
                            phase_name="branch_snapshot",
                            execution_id=execution_id,
                            reason="replay_result_collection_exception",
                            metadata={
                                "entry_derivation": "reset_entry_branch_snapshot_probe",
                                "coverage_counted": True,
                                "branch": int(snapshot.address),
                                "requested_direction": bool(take_branch),
                            },
                            execution_started=True,
                            execution_error=exc,
                        )
                    )
                finally:
                    cleanup_record = None
                    for candidate_record in reversed(child_execution_records):
                        if str(candidate_record.get("execution_id") or "") == str(
                            execution_id
                        ):
                            cleanup_record = candidate_record
                            break
                    try:
                        cleanup_error = self._safe_dispose_temp_emulator(
                            temp_emulator,
                            mmio_handler=temp_mmio,
                            quarantine=None,
                            stage_name=self._temp_stage_for("branch_snapshot_replay"),
                            evidence_record=cleanup_record,
                        )
                        if cleanup_error:
                            # ``_safe_dispose_temp_emulator`` has already
                            # downgraded a materialized record.  If the child
                            # failed before producing one, retain a separate
                            # diagnostic record so the attempt is accounted
                            # for without promoting its observed BBs.
                            if cleanup_record is None:
                                child_execution_records.append(
                                    self._execution_failure_evidence_record(
                                        phase_name="branch_snapshot",
                                        execution_id=f"{execution_id}-cleanup",
                                        reason="replay_cleanup_exception",
                                        metadata={
                                            "entry_derivation": "reset_entry_branch_snapshot_probe",
                                            "coverage_counted": True,
                                            "branch": int(snapshot.address),
                                            "requested_direction": bool(take_branch),
                                        },
                                        execution_started=bool(
                                            run_result.get("execution_started", False)
                                            if isinstance(run_result, Mapping)
                                            else False
                                        ),
                                        execution_error=cleanup_error,
                                        run_result=(
                                            run_result
                                            if isinstance(run_result, Mapping)
                                            else None
                                        ),
                                    )
                                )
                            logger.debug(
                                "branch snapshot replay cleanup failed: %s",
                                cleanup_error,
                            )
                    except Exception as cleanup_error:
                        # Cleanup is outside the replay result itself, but a
                        # failed teardown means the child cannot be reported
                        # as fully accounted for.  Materialize a separate
                        # diagnostic record and continue with the next branch
                        # direction instead of aborting the whole phase.
                        logger.debug(
                            "branch snapshot replay cleanup failed: %s",
                            cleanup_error,
                        )
                        if cleanup_record is not None:
                            # The replay already has a materialized record.  A
                            # teardown failure belongs to that same attempt;
                            # downgrade it in place so its observed BBs cannot
                            # remain a strict witness through the earlier
                            # success record.
                            cleanup_record["status"] = DIAGNOSTIC_REPLAY
                            cleanup_record["telemetry_complete"] = False
                            cleanup_record["execution_telemetry_complete"] = False
                            cleanup_record["execution_failed"] = True
                            cleanup_record["execution_completed_normally"] = False
                            cleanup_record["failure_reason"] = (
                                "replay_cleanup_exception"
                            )
                            cleanup_record["execution_error"] = str(
                                cleanup_error
                            )[:2000]
                            cleanup_record["reasons"] = list(
                                dict.fromkeys(
                                    list(cleanup_record.get("reasons", []) or [])
                                    + ["replay_cleanup_exception"]
                                )
                            )
                        else:
                            child_execution_records.append(
                                self._execution_failure_evidence_record(
                                    phase_name="branch_snapshot",
                                    execution_id=f"{execution_id}-cleanup",
                                    reason="replay_cleanup_exception",
                                    metadata={
                                        "entry_derivation": "reset_entry_branch_snapshot_probe",
                                        "coverage_counted": True,
                                        "branch": int(snapshot.address),
                                        "requested_direction": bool(take_branch),
                                    },
                                    execution_started=bool(
                                        run_result.get("execution_started", False)
                                        if isinstance(run_result, Mapping)
                                        else False
                                    ),
                                    execution_error=cleanup_error,
                                    run_result=(
                                        run_result
                                        if isinstance(run_result, Mapping)
                                        else None
                                    ),
                                )
                            )

        return self._record_phase(
            "branch_snapshot",
            phase_covered,
            child_execution_summary=self._child_execution_summary(
                child_attempt_count,
                {},
                expected_count=child_attempt_count,
                execution_records=child_execution_records,
            ),
            branches_considered=len(branches),
            flipped_directions=flipped_directions,
            replay_instructions=replay_instructions,
            time_limit_seconds=time_limit_seconds,
        )

    def run_reservoir_branch_exploration(
        self,
        time_limit_seconds: Optional[int] = None,
        replay_instructions: int = 50000,
        replay_timeout: int = 1_000_000,
        max_tasks: int = 1000,
        max_tasks_per_root: int = 0,
        merge_probe_bbs: int = 128,
        relax_root_occurrences: bool = True,
        ordered_path_constraints: bool = False,
        strict_subtree_pruning: bool = False,
        prioritize_static_potential: bool = False,
        skip_stale_tasks: bool = False,
        defer_stale_tasks: bool = True,
        stale_replay_interval: int = 16,
        state_signature_pruning: bool = True,
        state_probe_bbs: int = 512,
        edge_saturation_pruning: bool = True,
        edge_zero_new_limit: int = 3,
        dynamic_frontier_seeding: bool = True,
        isolate_path_coverage: bool = False,
        target_bbs: Optional[Set[int]] = None,
        known_coverage_seed: Optional[Set[int]] = None,
        prioritize_target_bbs: bool = False,
        continue_target_merges: bool = False,
        # cycle2 k.5 C4（装配预算旗标）：True 时即使本相位不带 target
        # 引导（prioritize_target_bbs/continue_target_merges 皆 False），
        # 装配段吃光预算（setup_budget_exhausted_before_loop）也照发
        # bootstrap 窗口（≤30s、至少 1 任务）——不改任务选择/覆盖语义，
        # 只把「零任务相位」从 r-分母 v2 的 budget_zeroed_phases 里救回。
        setup_budget_target_bootstrap: bool = False,
        target_probe_bbs: int = 2048,
        phase_name: str = "branch_reservoir",
        reset_state: bool = False,
    ) -> Set[int]:
        """
        Bottom-up branch exploration.

        Start from the deepest branch in the main path, force its opposite
        direction, run that subtree, then enqueue newly discovered subtree
        branches from deepest to shallowest. After the current subtree is
        drained, move one level up in the original main path.
        """
        baseline_main_path = list(self.emulator.branch_snapshot_manager.get_ordered_events())
        baseline_occurrence_path = list(
            self.emulator.branch_snapshot_manager.get_ordered_occurrence_events()
        )
        if baseline_main_path:
            self._remember_main_branch_events(
                baseline_main_path,
                evidence_class=EVIDENCE_E0,
            )
            self._remember_branch_root_snapshots(
                baseline_main_path,
                self._ordered_replay_snapshots(self.emulator),
                evidence_class=EVIDENCE_E0,
                occurrence_events=baseline_occurrence_path,
            )
        main_path = list(baseline_main_path)
        if not main_path and self.known_main_branch_events:
            main_path = sorted(
                self.known_main_branch_events.values(),
                key=lambda event: (
                    int(getattr(event, "depth", 0)),
                    int(getattr(event, "order", 0)),
                    int(getattr(event, "address", 0)),
                    int(getattr(event, "occurrence_index", 1)),
                ),
            )
        seeded_known_coverage = self.validate_coverage(known_coverage_seed or set())
        runtime_base_coverage = (
            set(self.phase_coverage.get("baseline", set()))
            if isolate_path_coverage
            else set(self.global_coverage)
        )
        path_base_coverage = runtime_base_coverage | seeded_known_coverage
        target_bb_set = self.validate_coverage(target_bbs or set())
        reservoir_initialized_at_entry = bool(self.reservoir_initialized and not reset_state)
        start_time = time.time()
        phase_covered: Set[int] = set()
        tasks_run = 0
        forced_hit_tasks = 0
        forced_missed_tasks = 0
        full_hit_tasks = 0
        partial_hit_tasks = 0
        relaxed_hit_tasks = 0
        merge_stopped_tasks = 0
        zero_new_tasks = 0
        partial_zero_new_tasks = 0
        stale_skipped_tasks = 0
        stale_deferred_tasks = 0
        stale_replayed_tasks = 0
        state_signature_new = 0
        state_signature_repeated = 0
        state_signature_stops = 0
        state_fingerprint_samples: List[Dict[str, object]] = []
        state_probe_stops = 0
        edge_saturated_tasks = 0
        edge_pruned_tasks = 0
        edge_pruned_pending_tasks = 0
        dynamic_frontier_tasks_added = 0
        same_root_tasks_promoted = 0
        target_reachable_merge_bbs = 0
        target_probe_stops = 0
        target_hit_tasks = 0
        target_bbs_discovered: Set[int] = set()
        reservoir_interrupt_contexts_added = 0
        remembered_branch_events = 0
        remembered_branch_root_snapshots = 0
        forced_choices_requested = 0
        forced_choices_hit = 0
        fatal_terminal_tasks = 0
        phase_started_root_keys: Set[Tuple[int, int]] = set()
        prefix_replay_tasks = 0
        targeted_root_snapshot_replay_tasks = 0
        direct_snapshot_risky_tasks = 0
        direct_snapshot_risky_fallback_tasks = 0
        direct_snapshot_risky_reasons: Counter[str] = Counter()
        direct_snapshot_available_tasks = 0
        direct_snapshot_missing_tasks = 0
        direct_snapshot_invalid_tasks = 0
        direct_snapshot_invalid_reasons: Counter[str] = Counter()
        direct_snapshot_retry_attempts = 0
        direct_snapshot_retry_used = 0
        direct_snapshot_retry_no_better = 0
        deep_branch_snapshot_available_tasks = 0
        deep_branch_snapshot_replay_tasks = 0
        dynamic_dispatch_snapshot_attempt_tasks = 0
        dynamic_dispatch_snapshot_replay_tasks = 0
        dynamic_dispatch_snapshot_selected = 0
        dynamic_dispatch_snapshot_successes = 0
        retry_dispatch_frontier_tasks_executed = 0
        retry_dispatch_frontier_tasks_with_new_bbs = 0
        retry_dispatch_frontier_tasks_with_target_bbs = 0
        retry_dispatch_frontier_forced_hit_tasks = 0
        retry_dispatch_frontier_ordered_hit_tasks = 0
        retry_dispatch_frontier_zero_new_tasks = 0
        retry_dispatch_frontier_fastlane_pops = 0
        retry_call_frontier_fastlane_pops = 0
        retry_dispatch_frontier_new_bbs = 0
        retry_dispatch_frontier_target_bbs = 0
        retry_dispatch_frontier_elapsed_seconds = 0.0
        retry_dispatch_frontier_max_elapsed_seconds = 0.0
        retry_dispatch_frontier_stop_reasons = Counter()
        retry_dispatch_frontier_root_tasks = Counter()
        retry_dispatch_frontier_root_new_bbs = Counter()
        retry_dispatch_frontier_root_target_bbs = Counter()
        retry_dispatch_frontier_root_zero_new_tasks = Counter()
        retry_dispatch_frontier_successor_attempts = Counter()
        retry_dispatch_frontier_successor_new_bbs = Counter()
        retry_dispatch_frontier_successor_zero_new_tasks = Counter()
        retry_dispatch_frontier_root_stop_reasons: Dict[str, Counter] = defaultdict(Counter)
        retry_dispatch_frontier_debug_records: List[Dict[str, object]] = []
        task_context_kind_counts = Counter()
        task_context_stop_reasons: Dict[str, Counter] = defaultdict(Counter)
        task_context_elapsed_seconds: Dict[str, float] = defaultdict(float)
        task_context_new_bbs = Counter()
        task_context_target_bbs = Counter()
        reservoir_constraint_hits = 0
        reservoir_pc_constraint_hits = 0
        reservoir_global_constraint_hits = 0
        reservoir_branch_mmio_constraint_hits = 0
        reservoir_branch_mmio_pc_constraint_hits = 0
        reservoir_branch_mmio_scoped_constraint_hits = 0
        reservoir_branch_mmio_scoped_pc_constraint_hits = 0
        reservoir_scoped_constraints_loaded = 0
        reservoir_scoped_prefix_snapshot_suppressed = 0
        reservoir_tasks_with_constraint_hits = 0
        reservoir_tasks_with_pc_constraint_hits = 0
        reservoir_tasks_with_branch_mmio_hits = 0
        reservoir_tasks_with_branch_mmio_scoped_hits = 0
        reservoir_tasks_with_scoped_constraints_loaded = 0
        reservoir_unique_pc_constraint_sites: Set[Tuple[int, int]] = set()
        reservoir_unique_branch_mmio_pc_constraint_sites: Set[Tuple[int, int]] = set()
        reservoir_unique_branch_mmio_scoped_pc_constraint_sites: Set[Tuple[int, int]] = set()
        scoped_strict_replay_tasks = 0
        scoped_strict_replay_successes = 0
        scoped_strict_replay_selected = 0
        scoped_strict_replay_fallbacks = 0
        scoped_strict_replay_pc_hit_tasks = 0
        scoped_strict_replay_ordered_hit_tasks = 0
        scoped_strict_replay_debug_records: List[Dict[str, object]] = []
        scoped_compressed_tasks_enqueued = 0
        edge_attempts: Dict[Tuple[int, object], int] = {}
        edge_zero_new_streak: Dict[Tuple[int, object], int] = {}
        progress_path = os.environ.get("LSGEMU_RESERVOIR_PROGRESS")
        checkpoint_path = os.environ.get("LSGEMU_COVERAGE_CHECKPOINT")
        state_path = os.environ.get("LSGEMU_RESERVOIR_STATE")
        resume_state = os.environ.get("LSGEMU_RESERVOIR_RESUME", "").lower() in {"1", "true", "yes"}
        target_provenance_path = os.environ.get("LSGEMU_TARGET_PROVENANCE")
        try:
            checkpoint_interval = int(os.environ.get("LSGEMU_COVERAGE_CHECKPOINT_INTERVAL", "300"))
        except ValueError:
            checkpoint_interval = 300
        last_checkpoint_time = start_time
        # write_timing 首行的 prev_append_post_perf 占位戳（writer 定义前
        # 取一次，非每写成本；此后由每次 append 后的 post 戳滚动接管）。
        prev_checkpoint_append_post_perf = time.perf_counter()
        current_path_signature = tuple()
        current_root_key = None
        current_terminal_successor = None
        current_task_started_at = None
        last_completed_path_signature = tuple()
        last_completed_root_key = None
        last_completed_terminal_successor = None
        last_completed_new_bbs = 0
        last_completed_branch_trace = []
        last_completed_stop_reason = None
        setup_elapsed_seconds = 0.0
        setup_budget_exhausted_before_loop = False
        setup_budget_bootstrap_used = False
        setup_budget_bootstrap_seconds = 0.0
        setup_budget_bootstrap_deadline = None
        setup_budget_bootstrap_min_tasks = 0
        last_completed_task_elapsed_seconds = 0.0

        def budget_exhausted() -> bool:
            if time_limit_seconds and time.time() - start_time > time_limit_seconds:
                if (
                    setup_budget_bootstrap_deadline is not None
                    and tasks_run < setup_budget_bootstrap_min_tasks
                    and time.time() <= setup_budget_bootstrap_deadline
                ):
                    return False
                return True
            return max_tasks is not None and max_tasks > 0 and tasks_run >= max_tasks

        def write_coverage_checkpoint(status: str, force: bool = False):
            nonlocal last_checkpoint_time, prev_checkpoint_append_post_perf
            if not checkpoint_path:
                return
            now = time.time()
            if not force and checkpoint_interval > 0 and now - last_checkpoint_time < checkpoint_interval:
                return
            last_checkpoint_time = now
            # cycle2 k.5 H1（write_timing，R5 §1-H4 逐字例外条款）：每写
            # 至多 8 次 time.perf_counter()——四个重组件（covered 双列表、
            # scheduler_feedback、probe+fingerprint、append）前后各一对；
            # 落盘 8 个原始 float 戳，写路径不做减法（差值由分析侧读时
            # 派生）。append 的 post 戳在行落盘之后才能取到，随闭包带进
            # 下一行的 prev_append_post_perf 键（末行丢失，首行=writer
            # 定义前的构造戳）。
            wt_entry_perf = time.perf_counter()
            phase_covered_bb_list = sorted(self.validate_coverage(phase_covered))
            global_covered_bb_list = sorted(
                self.validate_coverage(self.global_coverage | phase_covered)
            )
            wt_covered_lists_post_perf = time.perf_counter()
            wt_scheduler_feedback_pre_perf = time.perf_counter()
            scheduler_feedback_summary = self.scheduler_feedback_summary_for_progress()
            wt_scheduler_feedback_post_perf = time.perf_counter()
            wt_probe_fingerprint_pre_perf = time.perf_counter()
            differential_probe_summary = self.differential_probe_progress_summary()
            replay_fingerprint_summary = self.current_replay_state_fingerprint_summary()
            wt_probe_fingerprint_post_perf = time.perf_counter()
            try:
                checkpoint = {
                    "status": status,
                    "timestamp": now,
                    "elapsed_seconds": now - start_time,
                    "tasks_run": tasks_run,
                    # cycle2 k.5 H1：相位级 5 字段（全部取自既有局部变量，
                    # 零新增查询；作用域=参数 phase_name/time_limit_seconds
                    # 与装配段赋值的 setup_* 三元）。
                    "phase_name": phase_name,
                    "time_limit_seconds": time_limit_seconds,
                    "setup_elapsed_seconds": setup_elapsed_seconds,
                    "setup_budget_exhausted_before_loop": setup_budget_exhausted_before_loop,
                    "setup_budget_bootstrap_used": setup_budget_bootstrap_used,
                    "phase_covered_bbs": len(phase_covered),
                    "global_covered_bbs": len(self.global_coverage | phase_covered),
                    "phase_covered_bb_list": phase_covered_bb_list,
                    "global_covered_bb_list": global_covered_bb_list,
                    "queued_tasks": len(self.reservoir_task_queue),
                    "deferred_tasks": len(self.reservoir_deferred_tasks),
                    "scoped_probe_tasks": len(self.reservoir_scoped_probe_tasks),
                    "pending_paths": len(self.reservoir_pending_paths),
                    "explored_paths": len(self.reservoir_explored_paths),
                    "incomplete_paths": len(self.reservoir_incomplete_paths),
                    "retry_dispatch_frontier_tasks_executed": retry_dispatch_frontier_tasks_executed,
                    "retry_dispatch_frontier_new_bbs": retry_dispatch_frontier_new_bbs,
                    "retry_dispatch_frontier_target_bbs": retry_dispatch_frontier_target_bbs,
                    "retry_dispatch_frontier_elapsed_seconds": retry_dispatch_frontier_elapsed_seconds,
                    "retry_dispatch_frontier_fastlane_pops": retry_dispatch_frontier_fastlane_pops,
                    "retry_call_frontier_fastlane_pops": retry_call_frontier_fastlane_pops,
                    "retry_dispatch_frontier_stop_reasons": dict(retry_dispatch_frontier_stop_reasons),
                    "retry_dispatch_frontier_root_tasks": dict(retry_dispatch_frontier_root_tasks),
                    "retry_dispatch_frontier_root_zero_new_tasks": dict(
                        retry_dispatch_frontier_root_zero_new_tasks
                    ),
                    "retry_dispatch_frontier_successor_zero_new_tasks": dict(
                        retry_dispatch_frontier_successor_zero_new_tasks
                    ),
                    "stale_deferred_tasks": stale_deferred_tasks,
                    "stale_replayed_tasks": stale_replayed_tasks,
                    "state_signature_new": state_signature_new,
                    "state_signature_repeated": state_signature_repeated,
                    "constraint_hits": reservoir_constraint_hits,
                    "pc_constraint_hits": reservoir_pc_constraint_hits,
                    "branch_mmio_constraint_hits": reservoir_branch_mmio_constraint_hits,
                    "tasks_with_constraint_hits": reservoir_tasks_with_constraint_hits,
                    "tasks_with_pc_constraint_hits": reservoir_tasks_with_pc_constraint_hits,
                    "tasks_with_branch_mmio_hits": reservoir_tasks_with_branch_mmio_hits,
                    "unique_pc_constraint_sites": len(reservoir_unique_pc_constraint_sites),
                    "unique_branch_mmio_pc_constraint_sites": len(reservoir_unique_branch_mmio_pc_constraint_sites),
                    "edge_saturated_edges": len(self.reservoir_saturated_edges),
                    "current_root_key": (
                        [int(current_root_key[0]), int(current_root_key[1])]
                        if current_root_key is not None
                        else None
                    ),
                    "current_path": serialize_signature(current_path_signature),
                    "current_path_length": len(current_path_signature),
                    "current_terminal_successor": (
                        f"0x{int(current_terminal_successor):08x}"
                        if current_terminal_successor is not None
                        else None
                    ),
                    "current_task_elapsed_seconds": (
                        max(0.0, now - current_task_started_at)
                        if current_task_started_at is not None
                        else 0.0
                    ),
                    "last_completed_root_key": (
                        [int(last_completed_root_key[0]), int(last_completed_root_key[1])]
                        if last_completed_root_key is not None
                        else None
                    ),
                    "last_completed_path": serialize_signature(last_completed_path_signature),
                    "last_completed_path_length": len(last_completed_path_signature),
                    "last_completed_terminal_successor": (
                        f"0x{int(last_completed_terminal_successor):08x}"
                        if last_completed_terminal_successor is not None
                        else None
                    ),
                    "last_completed_new_bbs": last_completed_new_bbs,
                    "last_completed_task_elapsed_seconds": last_completed_task_elapsed_seconds,
                    "last_completed_branch_trace": last_completed_branch_trace,
                    "last_completed_stop_reason": last_completed_stop_reason,
                    "scheduler_feedback": scheduler_feedback_summary,
                    # 探针计数周期落盘（SIGTERM 安全）：campaign attempt 被
                    # SIGTERM 收尾时 finalize 报告会丢，这是唯一可靠观测点。
                    "differential_probe": differential_probe_summary,
                    "current_replay_state_fingerprint": replay_fingerprint_summary,
                    "run_profile_hash": str((getattr(self, "run_profile", {}) or {}).get("profile_hash") or ""),
                }
                wt_append_pre_perf = time.perf_counter()
                checkpoint["write_timing"] = {
                    "entry_perf": wt_entry_perf,
                    "covered_lists_post_perf": wt_covered_lists_post_perf,
                    "scheduler_feedback_pre_perf": wt_scheduler_feedback_pre_perf,
                    "scheduler_feedback_post_perf": wt_scheduler_feedback_post_perf,
                    "probe_fingerprint_pre_perf": wt_probe_fingerprint_pre_perf,
                    "probe_fingerprint_post_perf": wt_probe_fingerprint_post_perf,
                    "append_pre_perf": wt_append_pre_perf,
                    "prev_append_post_perf": prev_checkpoint_append_post_perf,
                }
                append_jsonl(Path(checkpoint_path), checkpoint)
                prev_checkpoint_append_post_perf = time.perf_counter()
            except Exception:
                pass

        def write_progress(status: str):
            write_coverage_checkpoint(status)
            if not progress_path:
                return
            try:
                progress = {
                    "status": status,
                    "elapsed_seconds": time.time() - start_time,
                    "tasks_run": tasks_run,
                    "phase_covered_bbs": len(phase_covered),
                    "global_covered_bbs": len(self.global_coverage | phase_covered),
                    "path_covered_bbs": len(path_base_coverage | phase_covered),
                    "target_bbs": len(target_bb_set),
                    "branch_snapshot_hot_targets": len(hot_target_bb_set()),
                    "effective_priority_targets": len(effective_priority_target_bb_set()),
                    "priority_targeting_enabled": priority_targeting_enabled(),
                    "target_covered_bbs": len(target_bb_set & (path_base_coverage | phase_covered)),
                    "target_remaining_bbs": len(target_bb_set - (path_base_coverage | phase_covered)),
                    "target_reachable_merge_bbs": target_reachable_merge_bbs,
                    "target_probe_stops": target_probe_stops,
                    "target_hit_tasks": target_hit_tasks,
                    "target_bbs_discovered": len(target_bbs_discovered),
                    "reservoir_interrupt_contexts": len(self.reservoir_interrupt_contexts),
                    "forced_hit_tasks": forced_hit_tasks,
                    "forced_missed_tasks": forced_missed_tasks,
                    "full_hit_tasks": full_hit_tasks,
                    "partial_hit_tasks": partial_hit_tasks,
                    "relaxed_hit_tasks": relaxed_hit_tasks,
                    "merge_stopped_tasks": merge_stopped_tasks,
                    "zero_new_tasks": zero_new_tasks,
                    "partial_zero_new_tasks": partial_zero_new_tasks,
                    "retry_dispatch_frontier_tasks_executed": retry_dispatch_frontier_tasks_executed,
                    "retry_dispatch_frontier_new_bbs": retry_dispatch_frontier_new_bbs,
                    "retry_dispatch_frontier_target_bbs": retry_dispatch_frontier_target_bbs,
                    "retry_dispatch_frontier_elapsed_seconds": retry_dispatch_frontier_elapsed_seconds,
                    "retry_dispatch_frontier_fastlane_pops": retry_dispatch_frontier_fastlane_pops,
                    "retry_call_frontier_fastlane_pops": retry_call_frontier_fastlane_pops,
                    "retry_dispatch_frontier_stop_reasons": dict(retry_dispatch_frontier_stop_reasons),
                    "retry_dispatch_frontier_root_tasks": dict(retry_dispatch_frontier_root_tasks),
                    "retry_dispatch_frontier_root_zero_new_tasks": dict(
                        retry_dispatch_frontier_root_zero_new_tasks
                    ),
                    "retry_dispatch_frontier_successor_zero_new_tasks": dict(
                        retry_dispatch_frontier_successor_zero_new_tasks
                    ),
                    "stale_skipped_tasks": stale_skipped_tasks,
                    "stale_deferred_tasks": stale_deferred_tasks,
                    "stale_replayed_tasks": stale_replayed_tasks,
                    "state_signature_new": state_signature_new,
                    "state_signature_repeated": state_signature_repeated,
                    "state_signature_stops": state_signature_stops,
                    "state_probe_stops": state_probe_stops,
                    "constraint_hits": reservoir_constraint_hits,
                    "pc_constraint_hits": reservoir_pc_constraint_hits,
                    "global_constraint_hits": reservoir_global_constraint_hits,
                    "branch_mmio_constraint_hits": reservoir_branch_mmio_constraint_hits,
                    "branch_mmio_pc_constraint_hits": reservoir_branch_mmio_pc_constraint_hits,
                    "tasks_with_constraint_hits": reservoir_tasks_with_constraint_hits,
                    "tasks_with_pc_constraint_hits": reservoir_tasks_with_pc_constraint_hits,
                    "tasks_with_branch_mmio_hits": reservoir_tasks_with_branch_mmio_hits,
                    "unique_pc_constraint_sites": len(reservoir_unique_pc_constraint_sites),
                    "unique_branch_mmio_pc_constraint_sites": len(reservoir_unique_branch_mmio_pc_constraint_sites),
                    "edge_saturated_tasks": edge_saturated_tasks,
                    "edge_pruned_tasks": edge_pruned_tasks,
                    "edge_pruned_pending_tasks": edge_pruned_pending_tasks,
                    "edge_saturated_edges": len(self.reservoir_saturated_edges),
                    "dynamic_frontier_tasks_added": dynamic_frontier_tasks_added,
                    "priority_root_tasks_seeded": priority_root_tasks_seeded,
                    "dynamic_successor_edge_count": sum(len(successors) for successors in self.dynamic_successors.values()),
                    "prefix_replay_tasks": prefix_replay_tasks,
                    "prefix_snapshot_cache_entries": len(self.reservoir_prefix_snapshots),
                    "forced_choices_requested": forced_choices_requested,
                    "forced_choices_hit": forced_choices_hit,
                    "queued_tasks": len(self.reservoir_task_queue),
                    "deferred_tasks": len(self.reservoir_deferred_tasks),
                    "scoped_probe_tasks": len(self.reservoir_scoped_probe_tasks),
                    "explored_paths": len(self.reservoir_explored_paths),
                    "incomplete_paths": len(self.reservoir_incomplete_paths),
                    "pending_paths": len(self.reservoir_pending_paths),
                }
                atomic_json_dump(progress, Path(progress_path), indent=2)
            except Exception:
                pass

        def event_key(event) -> Tuple[int, int]:
            return (event.address, event.occurrence_index)

        event_depth_by_key: Dict[Tuple[int, int], int] = {
            event_key(event): getattr(event, "depth", 0)
            for event in main_path
        }
        event_by_key = {
            event_key(event): event
            for event in main_path
        }

        def serialize_choice(value):
            if isinstance(value, bool):
                return bool(value)
            if isinstance(value, int):
                return int(value)
            return value

        def choice_identity(value):
            """Stable hash key for branch choices; keep switch table indexes distinct."""
            if isinstance(value, bool):
                return bool(value)
            if isinstance(value, int):
                return int(value)
            try:
                return int(value)
            except (TypeError, ValueError):
                return str(value)

        exact_switch_choice_compaction_enabled = (
            os.environ.get("LSGEMU_EXACT_SWITCH_CHOICE_COMPACTION", "1").lower()
            not in {"0", "false", "no"}
        )

        def compact_choice_identity(event, value):
            if is_switch_event(event) and not exact_switch_choice_compaction_enabled:
                return int(bool(value))
            return choice_identity(value)

        def serialize_event(event) -> Dict[str, object]:
            return {
                "address": int(getattr(event, "address", 0)),
                "branch_pc": int(getattr(event, "branch_pc", 0)),
                "target": int(getattr(event, "target", 0) or 0),
                "fallthrough": int(getattr(event, "fallthrough", 0) or 0),
                "condition": str(getattr(event, "condition", "")),
                "original_taken": bool(getattr(event, "original_taken", False)),
                "order": int(getattr(event, "order", 0)),
                "depth": int(getattr(event, "depth", 0)),
                "occurrence_index": int(getattr(event, "occurrence_index", 1)),
                "alternatives": [int(item or 0) for item in getattr(event, "alternatives", [])],
                "original_index": getattr(event, "original_index", None),
                "first_order": int(getattr(event, "first_order", getattr(event, "order", 0))),
                "first_depth": int(getattr(event, "first_depth", getattr(event, "depth", 0))),
                "first_occurrence_index": int(getattr(event, "first_occurrence_index", getattr(event, "occurrence_index", 1))),
                "original_direction_known": bool(
                    getattr(event, "original_direction_known", True)
                ),
                "direction_provenance": str(
                    getattr(event, "direction_provenance", "unicorn_execution")
                    or "unicorn_execution"
                ),
                "synthetic": bool(getattr(event, "synthetic", False)),
                "context_signature": dict(
                    getattr(event, "context_signature", {}) or {}
                ),
            }

        def restore_event(data: Dict[str, object]):
            from types import SimpleNamespace

            return SimpleNamespace(
                address=int(data.get("address", 0)),
                branch_pc=int(data.get("branch_pc", 0)),
                target=int(data.get("target", 0) or 0),
                fallthrough=int(data.get("fallthrough", 0) or 0),
                condition=str(data.get("condition", "")),
                original_taken=bool(data.get("original_taken", False)),
                order=int(data.get("order", 0)),
                depth=int(data.get("depth", 0)),
                occurrence_index=int(data.get("occurrence_index", 1)),
                alternatives=[int(item or 0) for item in data.get("alternatives", [])],
                original_index=data.get("original_index"),
                first_order=int(data.get("first_order", data.get("order", 0))),
                first_depth=int(data.get("first_depth", data.get("depth", 0))),
                first_occurrence_index=int(data.get("first_occurrence_index", data.get("occurrence_index", 1))),
                original_direction_known=bool(
                    data.get("original_direction_known", True)
                ),
                direction_provenance=str(
                    data.get("direction_provenance", "unicorn_execution")
                    or "unicorn_execution"
                ),
                synthetic=bool(data.get("synthetic", False)),
                context_signature=dict(data.get("context_signature", {}) or {}),
            )
        baseline_instruction_budget = (
            self.phase_metadata.get("baseline", {}).get("max_instructions")
            or replay_instructions
        )
        # bb_history is a bounded diagnostic tail; use the exact path depth for
        # instruction-to-BB calibration so retention does not distort replay
        # budgeting or diagnostics.
        depth_getter = getattr(self.emulator, "_bb_history_depth", None)
        if callable(depth_getter):
            baseline_bb_depth = max(1, int(depth_getter() or 0))
        else:
            baseline_bb_depth = max(1, len(getattr(self.emulator, "bb_history", [])))
        bb_to_unicorn_count = max(1.0, min(8.0, baseline_instruction_budget / baseline_bb_depth))

        def is_switch_event(event) -> bool:
            return _is_switch_frontier_mnemonic(getattr(event, "condition", "")) and bool(getattr(event, "alternatives", []))

        def event_edge_identity(event):
            if is_switch_event(event):
                return (event.address, getattr(event, "original_index", None))
            if is_call_like_event(event):
                alternatives = tuple(
                    self.prepared.resolve_basic_block(int(target or 0))
                    for target in getattr(event, "alternatives", []) or []
                    if self.prepared.resolve_basic_block(int(target or 0)) is not None
                )
                observed = observed_successor_bb(event)
                return (
                    event.address,
                    getattr(event, "condition", ""),
                    observed,
                    alternatives,
                )
            return (event.address, event.original_taken)

        def compact_events(events):
            """
            Collapse hot loop iterations while preserving occurrence precision.

            A branch that fires thousands of times in a wait loop should not
            generate thousands of reservoir roots. We keep the first occurrence
            for each observed (branch address, direction), because forcing that
            occurrence explores the same alternate edge much earlier, and order
            the candidates by their last appearance for bottom-up scheduling.
            """
            first_by_edge = {}
            last_order_by_edge = {}
            recent_by_edge = {}
            for event in events:
                edge = event_edge_identity(event)
                first_by_edge.setdefault(edge, event)
                last_order_by_edge[edge] = event.order
                if (
                    frontier_multi_occurrence_limit > 1
                    and event_uncovered_successor_count(event, path_base_coverage) > 0
                ):
                    recent_by_edge.setdefault(edge, []).append(event)

            selected = []
            for edge in sorted(first_by_edge, key=lambda item: last_order_by_edge[item]):
                recent = recent_by_edge.get(edge)
                if recent:
                    recent = sorted(
                        recent,
                        key=lambda event: (
                            int(getattr(event, "order", 0)),
                            int(getattr(event, "occurrence_index", 1)),
                        ),
                    )
                    selected.extend(recent[-max(1, frontier_multi_occurrence_limit):])
                else:
                    selected.append(first_by_edge[edge])
            return selected

        def choice_values(event) -> List[object]:
            if is_switch_event(event):
                values = []
                original_index = getattr(event, "original_index", None)
                for index, target in enumerate(getattr(event, "alternatives", [])):
                    if target == 0 or index == original_index:
                        continue
                    values.append(index)
                return values
            if is_call_like_event(event):
                values = []
                seen_successors = set()
                alternatives = list(getattr(event, "alternatives", []) or [])
                if not alternatives:
                    alternatives = [
                        int(getattr(event, "target", 0) or 0),
                        int(getattr(event, "fallthrough", 0) or 0),
                    ]
                for target in alternatives:
                    successor = self.prepared.resolve_basic_block(int(target or 0))
                    if successor is None or successor in seen_successors:
                        continue
                    seen_successors.add(successor)
                    values.append(int(successor))
                return values
            return [not event.original_taken]

        def choice_successor_bb(event, choice: Optional[object] = None) -> Optional[int]:
            if is_switch_event(event):
                alternatives = getattr(event, "alternatives", [])
                if choice is None:
                    for candidate in choice_values(event):
                        successor = choice_successor_bb(event, candidate)
                        if successor is not None and successor not in path_base_coverage:
                            return successor
                    return None
                try:
                    index = int(choice)
                except (TypeError, ValueError):
                    return None
                if index < 0 or index >= len(alternatives) or alternatives[index] == 0:
                    return None
                return self.prepared.resolve_basic_block(alternatives[index])

            if is_call_like_event(event):
                if choice is None:
                    for candidate in choice_values(event):
                        successor = choice_successor_bb(event, candidate)
                        if successor is not None and successor not in path_base_coverage:
                            return successor
                    return None
                try:
                    return self.prepared.resolve_basic_block(int(choice))
                except (TypeError, ValueError):
                    return None

            direction = (not event.original_taken) if choice is None else bool(choice)
            alternate_addr = event.target if direction else event.fallthrough
            return self.prepared.resolve_basic_block(alternate_addr)

        def observed_successor_bb(event) -> Optional[int]:
            if is_switch_event(event):
                target = getattr(event, "target", 0)
                if not target:
                    return None
                return self.prepared.resolve_basic_block(target)
            observed_addr = event.target if event.original_taken else event.fallthrough
            return self.prepared.resolve_basic_block(observed_addr)

        dynamic_successor_edges_added = self._record_dynamic_successors(main_path)
        successor_map = self._effective_successor_map()
        predecessors: Dict[int, Set[int]] = {}
        static_reachable_cache: Dict[int, Set[int]] = {}
        target_distance_cache: Dict[int, int] = {}
        hotset_state = {
            "key": (),
            "bbs": set(),
            "distance_cache": {},
            "seeded_root_signatures": set(),
        }
        prefix_snapshot_limit = self._prefix_snapshot_limit()
        target_aware_prefix_replay_enabled = (
            os.environ.get("LSGEMU_TARGET_AWARE_PREFIX_REPLAY", "1").lower()
            not in {"0", "false", "no"}
        )
        enable_prefix_replay = (
            prefix_snapshot_limit > 0
            and (
                (
                    not bool(target_bb_set)
                    and not prioritize_target_bbs
                    and not continue_target_merges
                )
                or target_aware_prefix_replay_enabled
            )
        )

        def rebuild_successor_model():
            nonlocal successor_map, predecessors
            successor_map = self._effective_successor_map()
            predecessors = {bb: set() for bb in self.prepared.static_bb_set}
            for bb_addr, successors in successor_map.items():
                for successor in successors:
                    predecessors.setdefault(successor, set()).add(bb_addr)
            static_reachable_cache.clear()
            target_distance_cache.clear()
            hotset_state["distance_cache"] = {}

        rebuild_successor_model()

        def hot_target_bb_set() -> Set[int]:
            if not self.semantic_obligation_enabled:
                return set()
            current = tuple(sorted(self.validate_coverage(self.branch_snapshot_hotset)))
            if current != hotset_state["key"]:
                hotset_state["key"] = current
                hotset_state["bbs"] = set(current)
                hotset_state["distance_cache"] = {}
                hotset_state["seeded_root_signatures"] = set()
            return hotset_state["bbs"]

        def priority_targeting_enabled() -> bool:
            return bool(hot_target_bb_set()) or (prioritize_target_bbs and bool(target_bb_set))

        def effective_priority_target_bb_set() -> Set[int]:
            return set(target_bb_set) | hot_target_bb_set()

        def static_reachable_from(start_bb: Optional[int]) -> Set[int]:
            if start_bb is None or start_bb not in self.prepared.static_bb_set:
                return set()
            cached = static_reachable_cache.get(start_bb)
            if cached is not None:
                return cached
            queue = deque([start_bb])
            seen = {start_bb}
            while queue:
                current = queue.popleft()
                for succ in sorted(successor_map.get(current, set())):
                    if succ not in seen:
                        seen.add(succ)
                        queue.append(succ)
            static_reachable_cache[start_bb] = seen
            return seen

        def static_new_potential(start_bb: Optional[int], known_coverage: Set[int]) -> int:
            return len(static_reachable_from(start_bb) - known_coverage)

        def static_target_potential(start_bb: Optional[int], known_coverage: Set[int]) -> int:
            if not target_bb_set:
                return 0
            return len((static_reachable_from(start_bb) & target_bb_set) - known_coverage)

        def static_hot_target_potential(start_bb: Optional[int]) -> int:
            hot_targets = hot_target_bb_set()
            if start_bb is None or start_bb not in self.prepared.static_bb_set or not hot_targets:
                return 0
            return len(static_reachable_from(start_bb) & hot_targets)

        def target_distance(start_bb: Optional[int]) -> int:
            if start_bb is None or start_bb not in self.prepared.static_bb_set or not target_bb_set:
                return 1_000_000_000
            cached = target_distance_cache.get(start_bb)
            if cached is not None:
                return cached

            queue = deque((target, 0) for target in sorted(target_bb_set) if target in self.prepared.static_bb_set)
            seen = {target for target, _distance in queue}
            while queue:
                current, distance = queue.popleft()
                target_distance_cache[current] = distance
                for predecessor in sorted(predecessors.get(current, set())):
                    if predecessor not in seen:
                        seen.add(predecessor)
                        queue.append((predecessor, distance + 1))
            return target_distance_cache.get(start_bb, 1_000_000_000)

        def hot_target_distance(start_bb: Optional[int]) -> int:
            hot_targets = hot_target_bb_set()
            if start_bb is None or start_bb not in self.prepared.static_bb_set or not hot_targets:
                return 1_000_000_000
            cache = hotset_state["distance_cache"]
            if not cache:
                queue = deque((target, 0) for target in sorted(hot_targets) if target in self.prepared.static_bb_set)
                seen = {target for target, _distance in queue}
                while queue:
                    current, distance = queue.popleft()
                    cache[current] = distance
                    for predecessor in sorted(predecessors.get(current, set())):
                        if predecessor not in seen:
                            seen.add(predecessor)
                            queue.append((predecessor, distance + 1))
            return cache.get(start_bb, 1_000_000_000)

        def static_priority(start_bb: Optional[int], known_coverage: Set[int]) -> Tuple[int, int, int, int, int]:
            hot_target_potential = static_hot_target_potential(start_bb)
            target_potential = static_target_potential(start_bb, known_coverage)
            return (
                1 if hot_target_potential > 0 else 0,
                1 if target_potential > 0 else 0,
                -hot_target_distance(start_bb) if hot_target_potential > 0 else -target_distance(start_bb),
                hot_target_potential if hot_target_potential > 0 else target_potential,
                static_new_potential(start_bb, known_coverage),
            )

        def event_mnemonic(event) -> str:
            return _normalize_mnemonic(getattr(event, "condition", ""))

        def is_call_like_event(event) -> bool:
            return _is_call_frontier_mnemonic(event_mnemonic(event))

        def event_dispatch_bias(event, known_coverage: Set[int]) -> Tuple[int, int, int]:
            mnemonic = event_mnemonic(event)
            uncovered_count = event_uncovered_successor_count(event, known_coverage)
            return (
                1 if _is_switch_frontier_mnemonic(mnemonic) and uncovered_count > 0 else 0,
                1 if _is_call_frontier_mnemonic(mnemonic) and uncovered_count > 0 else 0,
                uncovered_count,
            )

        state_reg_pairs = (
            (UC_ARM_REG_R0, "r0"),
            (UC_ARM_REG_R1, "r1"),
            (UC_ARM_REG_R2, "r2"),
            (UC_ARM_REG_R3, "r3"),
            (UC_ARM_REG_R4, "r4"),
            (UC_ARM_REG_R5, "r5"),
            (UC_ARM_REG_R6, "r6"),
            (UC_ARM_REG_R7, "r7"),
            (UC_ARM_REG_R8, "r8"),
            (UC_ARM_REG_R9, "r9"),
            (UC_ARM_REG_R10, "r10"),
            (UC_ARM_REG_R11, "r11"),
            (UC_ARM_REG_R12, "r12"),
            (UC_ARM_REG_SP, "sp"),
            (UC_ARM_REG_LR, "lr"),
            (UC_ARM_REG_PC, "pc"),
            (UC_ARM_REG_CPSR, "cpsr"),
        )
        state_fingerprint_v2_enabled = (
            os.environ.get("LSGEMU_REPLAY_STATE_FINGERPRINT_V2", "1").strip().lower()
            not in {"", "0", "false", "no", "off"}
        )

        def dynamic_state_signature(
            uc,
            bb_addr: int,
            mmio_handler: EnhancedMMIOHandler,
            snapshot_entry: Optional[PrefixReplaySnapshot] = None,
            emulator_obj: Optional[IntelligentEmulator] = None,
            call_stack: Optional[Iterable[object]] = None,
        ) -> Tuple[object, ...]:
            registers = []
            reg_values: Dict[str, int] = {}
            for reg_id, reg_name in state_reg_pairs:
                try:
                    value = uc.reg_read(reg_id) & 0xFFFFFFFF
                except Exception:
                    value = 0
                registers.append(value)
                reg_values[reg_name] = value

            mmio_state = tuple(
                sorted(
                    (address & 0xFFFFFFFF, value & 0xFFFFFFFF)
                    for address, value in mmio_handler.mmio_state.items()
                )
            )
            if state_fingerprint_v2_enabled:
                constraint_hits = []
                for attr_name in (
                    "pc_constraint_hit_keys",
                    "branch_mmio_pc_constraint_hit_keys",
                    "branch_mmio_scoped_pc_constraint_hit_keys",
                ):
                    try:
                        constraint_hits.extend(list(getattr(mmio_handler, attr_name, set()) or []))
                    except Exception:
                        continue
                fingerprint = build_replay_state_fingerprint(
                    uc=uc,
                    bb_addr=bb_addr,
                    mmio_handler=mmio_handler,
                    emulator=emulator_obj,
                    snapshot_entry=snapshot_entry,
                    reg_values=reg_values,
                    constraint_hit_keys=constraint_hits,
                    call_stack=call_stack,
                    max_dirty_pages=max(0, _env_int("LSGEMU_REPLAY_STATE_FP_MAX_DIRTY_PAGES", 8)),
                    ram_sample_bytes=max(4, _env_int("LSGEMU_REPLAY_STATE_FP_RAM_SAMPLE_BYTES", 256)),
                    include_ram=(
                        os.environ.get("LSGEMU_REPLAY_STATE_FP_INCLUDE_RAM", "1").strip().lower()
                        not in {"", "0", "false", "no", "off"}
                    ),
                )
                if len(state_fingerprint_samples) < 16:
                    state_fingerprint_samples.append({
                        "bb_addr": fingerprint.get("bb_addr"),
                        "fingerprint_sha256": fingerprint.get("fingerprint_sha256"),
                        "ram_dirty_sha256": fingerprint.get("ram_dirty_sha256"),
                        "dirty_pages": len(fingerprint.get("dirty_pages", []) or []),
                        "mmio_state_entries": len(fingerprint.get("mmio_state", {}) or {}),
                        "constraint_hit_keys": len(fingerprint.get("constraint_hits", []) or []),
                        "context_hard_sha256": dict(
                            fingerprint.get("causal_context", {}) or {}
                        ).get("hard_compatibility_sha256"),
                        "context_transition_digest": dict(
                            fingerprint.get("causal_context", {}) or {}
                        ).get("transition_digest"),
                        "snapshot": fingerprint.get("snapshot"),
                    })
                return ("v2", str(fingerprint.get("bb_addr")), str(fingerprint.get("fingerprint_sha256")))
            return (bb_addr, tuple(registers), mmio_state)

        def successor_keeps_priority_potential(successor: Optional[int], known_coverage: Set[int]) -> bool:
            if successor is None:
                return False
            if static_hot_target_potential(successor) > 0:
                return True
            return (
                prioritize_target_bbs
                and bool(target_bb_set)
                and static_target_potential(successor, known_coverage) > 0
            )

        def successor_should_expand(successor: Optional[int], known_coverage: Set[int]) -> bool:
            if successor is None:
                return False
            return successor not in known_coverage or successor_keeps_priority_potential(successor, known_coverage)

