            edge_saturated_edges=len(self.reservoir_saturated_edges),
            dynamic_frontier_tasks_added=dynamic_frontier_tasks_added,
            strict_dynamic_frontier_exhaustive_enabled=strict_dynamic_frontier_exhaustive_enabled,
            strict_dynamic_frontier_exhaustive_per_task=strict_dynamic_frontier_exhaustive_per_task,
