    def _runtime_diagnostics_summary(self) -> Dict[str, object]:
        loop_type_counts: Counter[str] = Counter()
        intervention_counts: Counter[str] = Counter()
        runtime_loop_branch_force_counts: Counter[str] = Counter()
        constraint_validation_counts: Counter[str] = Counter()
        constraint_validation_history: List[Dict[str, object]] = []
        phases_with_loop_stats = 0
        phases_with_constraint_validation = 0

        for phase_name, phase in self.phase_metadata.items():
            if not isinstance(phase, dict):
                continue
            run_result = phase.get("run_result")
            if not isinstance(run_result, dict):
                continue

            loop_stats = run_result.get("loop_classifier_stats")
            if isinstance(loop_stats, dict):
                by_type = loop_stats.get("by_type")
                if isinstance(by_type, dict):
                    phases_with_loop_stats += 1
                    for key, value in by_type.items():
                        loop_type_counts[str(key)] += int(value or 0)

            by_intervention = run_result.get("intervention_by_type")
            if isinstance(by_intervention, dict):
                for key, value in by_intervention.items():
                    intervention_counts[str(key)] += int(value or 0)

            force_stats = run_result.get("runtime_loop_branch_force_stats")
            if isinstance(force_stats, dict):
                for key, value in force_stats.items():
                    runtime_loop_branch_force_counts[str(key)] += int(value or 0)

            validation_stats = run_result.get("constraint_validation_stats")
            if isinstance(validation_stats, dict):
                if any(int(value or 0) for value in validation_stats.values()):
                    phases_with_constraint_validation += 1
                for key, value in validation_stats.items():
                    constraint_validation_counts[str(key)] += int(value or 0)

            history = run_result.get("constraint_validation_history")
            if isinstance(history, list):
                for item in history:
                    if not isinstance(item, dict):
                        continue
                    copied = dict(item)
                    copied.setdefault("phase", str(phase_name))
                    constraint_validation_history.append(copied)
                    if len(constraint_validation_history) >= 256:
                        break
            if len(constraint_validation_history) >= 256:
                break

        return {
            "loop_classifier": {
                "phases_with_stats": phases_with_loop_stats,
                "by_type": dict(loop_type_counts),
                "interventions_by_type": dict(intervention_counts),
            },
            "runtime_loop_branch_force": dict(runtime_loop_branch_force_counts),
            "static_reachability_cache": {
                "representation": (
                    "python_set_legacy"
                    if os.environ.get(
                        "LSGEMU_STATIC_REACHABILITY_CACHE_REPRESENTATION",
                        "packed_array",
                    ).strip().lower() in {"set", "legacy"}
                    else "packed_address_array"
                ),
                "entries": len(
                    getattr(self, "static_reachable_cache_by_successor_version", {})
                    or {}
                ),
                "retained_nodes": int(
                    getattr(self, "static_reachable_cache_node_count", 0) or 0
                ),
                "retained_bytes": int(
                    getattr(self, "static_reachable_cache_bytes", 0) or 0
                ),
                "max_bytes": int(self._static_reachability_cache_limits()[0]),
                "max_nodes": max(
                    0,
                    int(self._static_reachability_cache_limits()[1]),
                ),
                "hits": int(getattr(self, "static_reachable_cache_hits", 0) or 0),
                "misses": int(getattr(self, "static_reachable_cache_misses", 0) or 0),
                "evictions": int(
                    getattr(self, "static_reachable_cache_evictions", 0) or 0
                ),
                "oversized_skips": int(
                    getattr(self, "static_reachable_cache_oversized_skips", 0) or 0
                ),
            },
            "constraint_validation": {
                "phases_with_stats": phases_with_constraint_validation,
                "stats": dict(constraint_validation_counts),
                "history_sample": constraint_validation_history,
            },
        }

    def _scheduler_feedback_summary(self) -> Dict[str, object]:
        # Finalization is read-only. Reusing this already-derived diagnostic
        # avoids rebuilding all downstream reachability candidates several
        # times while writing the report, without changing feedback during
        # any exploratory stage.
        if str(getattr(self, "current_stage_name", "") or "") == "finalize":
            cached = getattr(self, "scheduler_feedback", None)
            if (
                getattr(self, "scheduler_feedback_cached_stage", "") == "finalize"
                and isinstance(cached, dict)
                and cached
            ):
                return cached
        feedback = self._scheduler_component("outcome_feedback", OutcomeFeedback)
        result = feedback.scheduler_feedback_summary()
        if str(getattr(self, "current_stage_name", "") or "") == "finalize":
            self.scheduler_feedback_cached_stage = "finalize"
        return result

    def _environment_feasibility_summary(self) -> Dict[str, object]:
        counters: Counter[str] = Counter()
        reject_reasons: Counter[str] = Counter()
        accepted_samples: List[Dict[str, object]] = []
        rejected_samples: List[Dict[str, object]] = []
        for phase_name, phase in (self.phase_metadata or {}).items():
            if not str(phase_name).startswith("branch_mmio"):
                continue
            if not isinstance(phase, dict):
                continue
            for record in phase.get("attempt_records", []) or []:
                if not isinstance(record, dict):
                    continue
                feasibility = record.get("environment_feasibility")
                if not isinstance(feasibility, dict):
                    feasibility = self._environment_feasibility_record(
                        strategy=str(record.get("strategy") or ""),
                        outcome=str(record.get("outcome") or ""),
                        constraint_items=list(record.get("constraint_items", []) or []),
                        constraint_feedback=dict(record.get("constraint_feedback") or {}),
                        result_eval=dict(record.get("result_eval") or {}),
                        state_equivalence=dict(record.get("state_equivalence") or {}),
                        coverage=dict(record.get("coverage") or {}),
                    )
                counters["attempts"] += 1
                if feasibility.get("accepted"):
                    counters["accepted"] += 1
                else:
                    counters["rejected"] += 1
                    for reason in feasibility.get("reject_reasons", []) or ["unknown"]:
                        reject_reasons[str(reason)] += 1
                if feasibility.get("entry_derived_state"):
                    counters["entry_derived_state"] += 1
                if feasibility.get("mmio_constraints_satisfied"):
                    counters["mmio_constraints_satisfied"] += 1
                if feasibility.get("target_obligation_hit"):
                    counters["target_obligation_hit"] += 1
                if feasibility.get("valid_dynamic_execution"):
                    counters["valid_dynamic_execution"] += 1
                if feasibility.get("state_fingerprint_available"):
                    counters["state_fingerprint_available"] += 1
                if feasibility.get("state_compatible"):
                    counters["state_compatible"] += 1
                sample = {
                    "phase": str(phase_name),
                    "strategy": record.get("strategy"),
                    "branch_pc": record.get("branch_pc"),
                    "target_direction": record.get("target_direction"),
                    "desired_successor": record.get("desired_successor"),
                    "outcome": record.get("outcome"),
                    "environment_feasibility": feasibility,
                }
                if feasibility.get("accepted") and len(accepted_samples) < 8:
                    accepted_samples.append(sample)
                elif not feasibility.get("accepted") and len(rejected_samples) < 8:
                    rejected_samples.append(sample)
        return {
            "schema": "environment_feasibility_summary.v1",
            "coverage_credit_policy": "only Unicorn-observed valid BBs are counted",
            "counts": dict(counters),
            "reject_reasons": dict(reject_reasons),
            "accepted_samples": accepted_samples,
            "rejected_samples": rejected_samples,
        }

    @staticmethod
    def _evaluation_int(value: object, default: int = 0) -> int:
        try:
            return int(value)  # type: ignore[arg-type]
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _evaluation_float(value: object, default: float = 0.0) -> float:
        try:
            return float(value)  # type: ignore[arg-type]
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _evaluation_phase_category(phase_name: str) -> str:
        name = str(phase_name).lower()
        if name in {"ablation_config", "branch_interleaved_budget"}:
            return "run_metadata"
        if name == "baseline" or name == "semantic_entry_prefix":
            return "baseline"
        if name in {"interleaved", "branch_interleaved"}:
            return "branch"
        if "stream_input" in name:
            return "stream"
        if "rtos_thread_entry" in name:
            return "thread"
        if "contextual_isr" in name or name == "isr" or "vector" in name:
            return "isr"
        if "summary_return" in name or "direct_call" in name:
            return "summary"
        if "branch_mmio" in name:
            return "mmio"
        if (
            "frontier_successor" in name
            or "switch_frontier" in name
            or "dispatch" in name
        ):
            return "dispatch"
        if "frontier" in name:
            return "dispatch"
        if "reservoir" in name or "branch" in name:
            return "branch"
        return "other"

    @staticmethod
    def _evaluation_counter_dict(counter: Counter) -> Dict[str, int]:
        return {str(key): int(value) for key, value in counter.items() if int(value) != 0}

    def _evaluation_metrics_summary(self, execution_time_seconds: Optional[float] = None) -> Dict[str, object]:
        """Aggregate report fields used by the paper evaluation.

        This summary is intentionally derived from already-recorded phase
        metadata. It does not feed back into scheduling or coverage accounting.
        """
        phase_map = self.phase_metadata if isinstance(self.phase_metadata, dict) else {}
        legacy_evidence_partitions = self._coverage_evidence_partitions()
        legacy_evidence_sets = legacy_evidence_partitions["evidence_sets"]
        legacy_witness_coverage = legacy_evidence_partitions["witness"]
        legacy_exploratory_only = legacy_evidence_partitions["e2_only"]
        legacy_context_only = legacy_evidence_partitions["e3_only"]
        legacy_e2_e3_shared = legacy_evidence_partitions["e2_e3_shared"]
        canonical_evidence = self._canonical_evidence_partitions()
        witness_coverage = set(canonical_evidence["validated"])
        exploratory_only = set(canonical_evidence["diagnostic_only"])
        # Canonical evidence intentionally does not split diagnostics by the
        # historical E2/E3 mechanism.  Those labels are retained below only
        # for compatibility with old evaluation parsers.
        context_only: Set[int] = set()
        e2_e3_shared: Set[int] = set()
        observed_coverage = self.validate_coverage(self.global_coverage)
        category_order = [
            "baseline",
            "mmio",
            "branch",
            "dispatch",
            "isr",
            "thread",
            "stream",
            "summary",
            "memory",
            "indirect",
            "other",
        ]

        def empty_category() -> Dict[str, object]:
            return {
                "phase_count": 0,
                "new_bbs_sum": 0,
                "covered_bbs_sum": 0,
                "stage_wall_seconds": 0.0,
                "stage_process_cpu_seconds": 0.0,
                "tasks_run": 0,
                "candidate_or_obligation_count": 0,
                "replay_attempt_count": 0,
                "successful_replay_count": 0,
                "target_hit_count": 0,
                "dynamic_successor_edges_added": 0,
                "remembered_branch_events": 0,
                "remembered_branch_root_snapshots": 0,
                "persisted_constraints": 0,
                "scoped_constraints_added": 0,
                "constraint_hits": 0,
                "llm_calls": 0,
                "phase_names": [],
            }

        categories: Dict[str, Dict[str, object]] = {
            name: empty_category()
            for name in category_order
        }
        phase_to_category: Dict[str, str] = {}
        stage_wall_by_phase: Dict[str, float] = {}
        stage_cpu_by_phase: Dict[str, float] = {}
        skipped_by_reason: Counter[str] = Counter()
        stop_reasons: Counter[str] = Counter()
        validation_reject_reasons: Counter[str] = Counter()

        replay_candidate_keys = (
            "branches_considered",
            "frontier_successor_candidates",
            "frontier_successor_candidate_total",
            "direct_call_frontier_candidates",
            "direct_call_candidate_total",
            "target_bbs",
            "stream_contexts",
            "selected_contexts",
            "contextual_isr_contexts",
            "available_prefix_branch_candidates",
            "selected_obligations",
        )
        replay_attempt_keys = (
            "tasks_run",
            "directions_replayed",
            "frontier_successor_edges_attempted",
            "frontier_successor_snapshot_attempts",
            "direct_call_snapshot_attempts",
            "snapshot_replays",
            "exact_state_snapshot_replays",
            "entry_fallback_replays",
            "entry_provenance_replays",
            "control_replays",
            "candidate_replays",
        )
        replay_success_keys = (
            "tasks_with_new_bbs",
            "tasks_with_target_bbs",
            "branches_changed",
            "exact_state_snapshot_successes",
            "snapshot_successes",
            "entry_provenance_successes",
            "persistence_validation_successes",
            "promoted_paths",
            "already_natural_paths",
        )
        target_hit_keys = (
            "target_hit_tasks",
            "tasks_with_target_bbs",
            "target_bbs_discovered",
            "forced_choices_verified",
        )

        hypothesis_by_candidate: Dict[str, Dict[str, object]] = {}
        branch_mmio_attempts = Counter()
        branch_mmio_reject_reasons: Counter[str] = Counter()
        structural_replay_attempts = Counter()
        structural_reject_reasons: Counter[str] = Counter()
        memory_stats = Counter()
        indirect_stats = Counter()

        def add_category_value(category: str, key: str, value: int | float) -> None:
            if category not in categories:
                categories[category] = empty_category()
            current = categories[category].get(key, 0)
            categories[category][key] = current + value  # type: ignore[operator]

        def remember_phase(category: str, phase_name: str) -> None:
            names = categories[category].setdefault("phase_names", [])
            if isinstance(names, list) and len(names) < 64:
                names.append(str(phase_name))

        def scan_memory_stats(obj: object) -> None:
            if not isinstance(obj, dict):
                return
            for key in (
                "pointer_arg_repair_stats",
                "summary_probe_pointer_arg_repair_stats",
                "prelude_memory_stats",
                "pointer_repair_stats",
            ):
                stats = obj.get(key)
                if not isinstance(stats, dict):
                    continue
                for stat_key in (
                    "repairs",
                    "pointer_repairs",
                    "writes",
                    "mapped_pages",
                    "records",
                    "valid_pointers",
                    "invalid_pointers",
                ):
                    value = stats.get(stat_key)
                    if isinstance(value, list):
                        memory_stats[f"{key}.{stat_key}"] += len(value)
                    else:
                        memory_stats[f"{key}.{stat_key}"] += self._evaluation_int(value)

        for phase_name, phase in phase_map.items():
            if not isinstance(phase, dict):
                continue
            category = self._evaluation_phase_category(str(phase_name))
            phase_to_category[str(phase_name)] = category
            if category in {"run_metadata"}:
                continue
            if category not in categories:
                categories[category] = empty_category()
            categories[category]["phase_count"] = self._evaluation_int(categories[category].get("phase_count")) + 1
            remember_phase(category, str(phase_name))
            if phase.get("coverage_counted", True) is not False:
                add_category_value(category, "new_bbs_sum", self._evaluation_int(phase.get("new_bbs")))
            add_category_value(category, "covered_bbs_sum", self._evaluation_int(phase.get("covered_bbs")))
            wall_seconds = self._evaluation_float(phase.get("stage_wall_seconds"))
            cpu_seconds = self._evaluation_float(phase.get("stage_process_cpu_seconds"))
            if wall_seconds > 0.0:
                stage_wall_by_phase[str(phase_name)] = round(wall_seconds, 3)
                add_category_value(category, "stage_wall_seconds", wall_seconds)
            if cpu_seconds > 0.0:
                stage_cpu_by_phase[str(phase_name)] = round(cpu_seconds, 3)
                add_category_value(category, "stage_process_cpu_seconds", cpu_seconds)
            if phase.get("skipped"):
                skipped_by_reason[str(phase.get("skip_reason") or "unknown")] += 1
            for key in replay_candidate_keys:
                add_category_value(category, "candidate_or_obligation_count", self._evaluation_int(phase.get(key)))
            for key in replay_attempt_keys:
                add_category_value(category, "replay_attempt_count", self._evaluation_int(phase.get(key)))
            for key in replay_success_keys:
                add_category_value(category, "successful_replay_count", self._evaluation_int(phase.get(key)))
            for key in target_hit_keys:
                add_category_value(category, "target_hit_count", self._evaluation_int(phase.get(key)))
            for key in (
                "dynamic_successor_edges_added",
                "remembered_branch_events",
                "remembered_branch_root_snapshots",
                "persisted_constraints",
                "scoped_constraints_added",
                "constraint_hits",
                "reservoir_constraint_hits",
                "reservoir_branch_mmio_constraint_hits",
            ):
                mapped_key = "constraint_hits" if key.startswith("reservoir_") else key
                add_category_value(category, mapped_key, self._evaluation_int(phase.get(key)))
            add_category_value(category, "llm_calls", self._evaluation_int(phase.get("llm_actual_calls", phase.get("llm_inference_calls"))))

            stop_reason_obj = phase.get("stop_reasons")
            if isinstance(stop_reason_obj, dict):
                for reason, value in stop_reason_obj.items():
                    stop_reasons[str(reason)] += self._evaluation_int(value)
            attempt_failure_obj = phase.get("attempt_failure_reasons")
            if isinstance(attempt_failure_obj, dict):
                for reason, value in attempt_failure_obj.items():
                    validation_reject_reasons[str(reason)] += self._evaluation_int(value)

            for record in phase.get("hypothesis_audit_records", []) or []:
                if not isinstance(record, dict):
                    continue
                candidate_id = str(record.get("candidate_id") or f"{phase_name}:audit:{len(hypothesis_by_candidate)}")
                state = hypothesis_by_candidate.setdefault(
                    candidate_id,
                    {
                        "phase": str(phase_name),
                        "generated": False,
                        "replayed": False,
                        "replay_succeeded": False,
                        "static_successor_matched": False,
                        "accepted": False,
                        "persisted": False,
                        "scoped": False,
                        "reject_reasons": set(),
                    },
                )
                state["generated"] = bool(state.get("generated")) or bool(record.get("generated")) or str(record.get("stage") or "") == "generated"
                state["replayed"] = bool(state.get("replayed")) or bool(record.get("replayed"))
                candidate_replay = record.get("candidate_replay")
                if isinstance(candidate_replay, dict):
                    state["replayed"] = bool(state.get("replayed")) or bool(candidate_replay.get("available"))
                    state["replay_succeeded"] = bool(state.get("replay_succeeded")) or bool(candidate_replay.get("success"))
                result_eval = record.get("result_eval")
                if isinstance(result_eval, dict):
                    state["replay_succeeded"] = bool(state.get("replay_succeeded")) or bool(result_eval.get("success"))
                state["static_successor_matched"] = (
                    bool(state.get("static_successor_matched"))
                    or bool(record.get("accepted_by_replay"))
                    or bool(record.get("target_obligation_hit"))
                    or bool(state.get("replay_succeeded"))
                )
                state["accepted"] = (
                    bool(state.get("accepted"))
                    or bool(record.get("accepted_by_replay"))
                    or bool(record.get("persisted"))
                    or bool(record.get("scoped"))
                )
                state["persisted"] = bool(state.get("persisted")) or bool(record.get("persisted"))
                state["scoped"] = bool(state.get("scoped")) or bool(record.get("scoped"))
                reject_reason = record.get("reject_reason")
                if reject_reason:
                    reasons = state.get("reject_reasons")
                    if isinstance(reasons, set):
                        reasons.add(str(reject_reason))
                candidate = record.get("candidate")
                if isinstance(candidate, dict) and str(candidate.get("type") or "").lower() == "memory":
                    memory_stats["hypothesis_memory_constraints"] += 1

            for record in phase.get("attempt_records", []) or []:
                if not isinstance(record, dict):
                    continue
                branch_mmio_attempts["attempted"] += 1
                result_eval = record.get("result_eval")
                result_success = isinstance(result_eval, dict) and bool(result_eval.get("success"))
                if result_success:
                    branch_mmio_attempts["replay_succeeded"] += 1
                    branch_mmio_attempts["static_successor_matched"] += 1
                feasibility = record.get("environment_feasibility")
                accepted = isinstance(feasibility, dict) and bool(feasibility.get("accepted"))
                if accepted:
                    branch_mmio_attempts["accepted"] += 1
                else:
                    branch_mmio_attempts["rejected"] += 1
                    reasons = (
                        list(feasibility.get("reject_reasons", []) or [])
                        if isinstance(feasibility, dict)
                        else []
                    )
                    if not reasons:
                        reasons = [str(record.get("outcome") or "unknown")]
                    for reason in reasons:
                        branch_mmio_reject_reasons[str(reason)] += 1
                for item in record.get("constraint_items", []) or []:
                    if isinstance(item, dict) and str(item.get("type") or "").lower() == "memory":
                        memory_stats["attempt_memory_constraints"] += 1

            for list_key in ("candidate_debug_records", "debug_records", "materialized_records", "records"):
                for record in phase.get(list_key, []) or []:
                    if not isinstance(record, dict):
                        continue
                    scan_memory_stats(record)
                    if list_key in {"candidate_debug_records", "debug_records"}:
                        structural_replay_attempts["attempted"] += 1
                        new_bbs = self._evaluation_int(record.get("new_bbs"))
                        target_bbs = self._evaluation_int(record.get("target_bbs", record.get("target_bbs_hit")))
                        forced_verified = bool(record.get("forced_verified"))
                        if new_bbs > 0 or target_bbs > 0 or forced_verified:
                            structural_replay_attempts["succeeded"] += 1
                        if target_bbs > 0 or forced_verified:
                            structural_replay_attempts["static_successor_matched"] += 1
                        else:
                            structural_replay_attempts["rejected"] += 1
                            structural_reject_reasons[str(record.get("stop_reason") or "zero_new_bbs")] += 1

            if "unproven_dynamic_code_targets" in phase:
                indirect_stats["unproven_dynamic_code_targets"] += self._evaluation_int(phase.get("unproven_dynamic_code_targets"))
            for key in (
                "dynamic_dispatch_snapshot_attempt_tasks",
                "dynamic_dispatch_snapshot_replay_tasks",
                "dynamic_dispatch_snapshot_successes",
                "retry_dispatch_frontier_tasks_executed",
                "retry_dispatch_frontier_tasks_with_new_bbs",
                "retry_dispatch_frontier_tasks_with_target_bbs",
            ):
                indirect_stats[key] += self._evaluation_int(phase.get(key))

        for key, value in memory_stats.items():
            add_category_value("memory", key, int(value))
        categories["memory"]["phase_count"] = self._evaluation_int(categories["memory"].get("phase_count")) + (1 if memory_stats else 0)
        categories["memory"]["phase_names"] = ["nested_memory_repair_stats"] if memory_stats else []

        indirect_stats["unproven_dynamic_code_targets"] += len(getattr(self, "unproven_dynamic_code_targets", {}) or {})
        for key, value in indirect_stats.items():
            add_category_value("indirect", key, int(value))
        categories["indirect"]["phase_count"] = self._evaluation_int(categories["indirect"].get("phase_count")) + (1 if indirect_stats else 0)
        categories["indirect"]["phase_names"] = ["dynamic_dispatch_and_indirect_target_stats"] if indirect_stats else []

        for category in categories.values():
            category["stage_wall_seconds"] = round(self._evaluation_float(category.get("stage_wall_seconds")), 3)
            category["stage_process_cpu_seconds"] = round(self._evaluation_float(category.get("stage_process_cpu_seconds")), 3)

        hypothesis_funnel = Counter()
        hypothesis_reject_reasons: Counter[str] = Counter()
        for state in hypothesis_by_candidate.values():
            if state.get("generated"):
                hypothesis_funnel["generated"] += 1
            if state.get("replayed"):
                hypothesis_funnel["replay_attempted"] += 1
            if state.get("replay_succeeded"):
                hypothesis_funnel["replay_succeeded"] += 1
            if state.get("static_successor_matched"):
                hypothesis_funnel["static_successor_matched"] += 1
            if state.get("accepted"):
                hypothesis_funnel["accepted"] += 1
            else:
                hypothesis_funnel["rejected"] += 1
                reasons = state.get("reject_reasons")
                if isinstance(reasons, set) and reasons:
                    for reason in reasons:
                        hypothesis_reject_reasons[str(reason)] += 1
                elif state.get("generated"):
                    hypothesis_reject_reasons["not_accepted"] += 1
            if state.get("persisted"):
                hypothesis_funnel["persisted"] += 1
            if state.get("scoped"):
                hypothesis_funnel["scoped"] += 1

        top_stage_wall = sorted(
            (
                {"phase": phase, "stage_wall_seconds": seconds}
                for phase, seconds in stage_wall_by_phase.items()
            ),
            key=lambda item: float(item["stage_wall_seconds"]),
            reverse=True,
        )[:32]

        ablation_config = phase_map.get("ablation_config", {})
        if not isinstance(ablation_config, dict):
            ablation_config = {}
        path_naturalization = self._path_naturalization_ledger().summary()
        dynamic_recovery_totals: Counter[str] = Counter()
        local_recovery_totals: Counter[str] = Counter()
        for phase in phase_map.values():
            if not isinstance(phase, dict):
                continue
            for key, value in dict(
                phase.get("dynamic_constraint_recovery", {}) or {}
            ).items():
                if isinstance(value, (int, float)):
                    dynamic_recovery_totals[str(key)] += value
            for key, value in dict(
                phase.get("local_constraint_recovery", {}) or {}
            ).items():
                if isinstance(value, (int, float)):
                    local_recovery_totals[str(key)] += value

        return {
            "schema": "lsgemu.evaluation_metrics.v1",
            "source": "derived_from_phase_metadata",
            "coverage_credit_policy": "Only valid BBs observed by Unicorn execution are counted; static CFG data is used for scheduling and denominators.",
            "ablation": {
                "active": bool(ablation_config),
                "disable_semantic_obligation_stages": bool(ablation_config.get("disable_semantic_obligation_stages", False)),
                "disable_scoped_replay_stages": bool(ablation_config.get("disable_scoped_replay_stages", False)),
                "disable_context_event_replay_stages": bool(ablation_config.get("disable_context_event_replay_stages", False)),
                "disable_constraint_guided_candidates": bool(ablation_config.get("disable_constraint_guided_candidates", False)),
                "effective_internal_switches": dict(ablation_config.get("effective_internal_switches", {}) or {}),
                "argument_overrides": dict(ablation_config.get("argument_overrides", {}) or {}),
                "fallback_policy": dict(ablation_config.get("fallback_policy", {}) or {}),
            },
            "stage_runtime": {
                "execution_time_seconds": execution_time_seconds,
                "recorded_stage_wall_seconds": round(sum(stage_wall_by_phase.values()), 3),
                "recorded_stage_process_cpu_seconds": round(sum(stage_cpu_by_phase.values()), 3),
                "stage_count_with_wall_time": len(stage_wall_by_phase),
                "top_stage_wall_seconds": top_stage_wall,
                "by_category": {
                    name: {
                        "stage_wall_seconds": categories[name]["stage_wall_seconds"],
                        "stage_process_cpu_seconds": categories[name]["stage_process_cpu_seconds"],
                    }
                    for name in category_order
                    if name in categories
                },
            },
            "contribution_validation": {
                "skipped_stage_count": sum(skipped_by_reason.values()),
                "skipped_by_reason": self._evaluation_counter_dict(skipped_by_reason),
                "phase_to_category": phase_to_category,
            },
            "coverage_evidence": {
                "all_unicorn_observed_bbs": len(observed_coverage),
                "witness_backed_bbs": len(witness_coverage),
                "validated_replay_bbs": len(witness_coverage),
                "diagnostic_replay_bbs": len(exploratory_only),
                "canonical_unclassified_bbs": len(
                    set(canonical_evidence["unclassified"])
                ),
                "reset_entry_e0_bbs": len(legacy_evidence_sets[EVIDENCE_E0]),
                "force_free_input_witness_e1_bbs": len(legacy_evidence_sets[EVIDENCE_E1]),
                "forced_exploration_e2_only_bbs": len(exploratory_only),
                "context_recovery_e3_only_bbs": len(context_only),
                "forced_and_context_shared_bbs": len(e2_e3_shared),
                "valid_all_unicorn_observed_bbs": len(
                    self.prepared.valid_coverage(observed_coverage)
                ),
                "valid_witness_backed_bbs": len(
                    self.prepared.valid_coverage(witness_coverage)
                ),
                "valid_forced_exploration_e2_only_bbs": len(
                    self.prepared.valid_coverage(exploratory_only)
                ),
                "valid_context_recovery_e3_only_bbs": len(
                    self.prepared.valid_coverage(context_only)
                ),
                "valid_forced_and_context_shared_bbs": len(
                    self.prepared.valid_coverage(e2_e3_shared)
                ),
                "legacy_evidence_partition": {
                    "deprecated": True,
                    "witness_backed_bbs": len(legacy_witness_coverage),
                    "e2_only_bbs": len(legacy_exploratory_only),
                    "e3_only_bbs": len(legacy_context_only),
                    "e2_e3_shared_bbs": len(legacy_e2_e3_shared),
                },
            },
            "repair_distribution": {
                "note": (
                    "Counts are activity counters grouped by semantic mechanism. "
                    "new_bbs_sum is counted only from coverage-counted phases; "
                    "other counters preserve raw replay/model activity for RQ3."
                ),
                "categories": categories,
            },
            # r42：候选生成消融机制面（原目标到达/候选尝试/提前偏离/恢复耗时）。
            "candidate_generation": candidate_generation_mechanism_metrics(phase_map),
            "replay_validation": {
                "hypothesis_audit_candidates": self._evaluation_counter_dict(hypothesis_funnel),
                "hypothesis_audit_reject_reasons": self._evaluation_counter_dict(hypothesis_reject_reasons),
                "branch_mmio_attempts": self._evaluation_counter_dict(branch_mmio_attempts),
                "branch_mmio_reject_reasons": self._evaluation_counter_dict(branch_mmio_reject_reasons),
                "structural_replay_attempts": self._evaluation_counter_dict(structural_replay_attempts),
                "structural_reject_reasons": self._evaluation_counter_dict(structural_reject_reasons),
                "phase_attempt_failure_reasons": self._evaluation_counter_dict(validation_reject_reasons),
                "stop_reasons": self._evaluation_counter_dict(stop_reasons),
                "snapshot_provenance": self._snapshot_provenance_summary(),
                "path_naturalization": {
                    "schema": path_naturalization.get("schema"),
                    "obligations": self._evaluation_int(path_naturalization.get("obligations")),
                    "unique_path_signatures": self._evaluation_int(
                        path_naturalization.get("unique_path_signatures")
                    ),
                    "signatures_with_multiple_discovery_contexts": self._evaluation_int(
                        path_naturalization.get(
                            "signatures_with_multiple_discovery_contexts"
                        )
                    ),
                    "facts": self._evaluation_int(path_naturalization.get("facts")),
                    "externally_replayable_facts": self._evaluation_int(
                        path_naturalization.get("externally_replayable_facts")
                    ),
                    "attempts": self._evaluation_int(path_naturalization.get("attempts")),
                    "promoted_bbs": self._evaluation_int(path_naturalization.get("promoted_bbs")),
                    "accepted_progress_steps": self._evaluation_int(
                        path_naturalization.get("accepted_progress_steps")
                    ),
                    "accepted_constraint_refinements": self._evaluation_int(
                        path_naturalization.get(
                            "accepted_constraint_refinements"
                        )
                    ),
                    "status_counts": dict(path_naturalization.get("status_counts", {}) or {}),
                    "reason_counts": dict(path_naturalization.get("reason_counts", {}) or {}),
                    "reason_category_counts": dict(
                        path_naturalization.get("reason_category_counts", {}) or {}
                    ),
                },
            },
            "overhead_inputs": {
                "llm_actual_calls": sum(
                    self._evaluation_int(phase.get("llm_actual_calls", phase.get("llm_inference_calls")))
                    for phase in phase_map.values()
                    if isinstance(phase, dict)
                ),
                "constraint_validation_stats": self._runtime_diagnostics_summary().get("constraint_validation", {}),
                "dynamic_constraint_recovery": dict(dynamic_recovery_totals),
                "local_constraint_recovery": dict(local_recovery_totals),
                "dynamic_tracer": (
                    self.register_tracer.get_statistics()
                    if getattr(self, "register_tracer", None) is not None
                    and hasattr(getattr(self, "register_tracer"), "get_statistics")
                    else {}
                ),
                # solver 侧探针计数并入（与 tracer 侧 dynamic_tracer 里的
                # differential_probe 字典互补：这里含 skipped_* 全套与
                # elapsed_seconds_total）。
                "differential_probe_solver": (
                    self.differential_probe_solver.get_statistics()
                    if getattr(self, "differential_probe_solver", None) is not None
                    and hasattr(
                        getattr(self, "differential_probe_solver"),
                        "get_statistics",
                    )
                    else {}
                ),
                "stage_wall_seconds_by_phase": stage_wall_by_phase,
                "stage_process_cpu_seconds_by_phase": stage_cpu_by_phase,
            },
        }

    def dispatch_case_status_summary(
        self,
        *,
        coverage: Optional[Iterable[int]] = None,
        max_roots: int = 32,
        max_successors_per_root: int = 16,
    ) -> Dict[str, object]:
        """Summarize per-case status for TBB/TBH/LDRPC/BLX/BX frontiers."""
        covered = self.validate_coverage(coverage if coverage is not None else self.global_coverage)
        effective_successors = self._effective_successor_map()
        scope = self.prepared.valid_bb_set if self.prepared.valid_bb_set else self.prepared.static_bb_set
        scope = set(scope)
        attempted: Dict[Tuple[int, int], Dict[str, object]] = {}
        for phase_name, phase in (self.phase_metadata or {}).items():
            if not isinstance(phase, dict):
                continue
            for record in phase.get("candidate_debug_records", []) or []:
                if not isinstance(record, dict):
                    continue
                try:
                    pred = int(str(record.get("pred_bb")), 16)
                    succ = int(str(record.get("successor_bb")), 16)
                except Exception:
                    continue
                key = (pred & 0xFFFFFFFF, succ & 0xFFFFFFFF)
                info = attempted.setdefault(
                    key,
                    {
                        "attempts": 0,
                        "target_hits": 0,
                        "new_bbs_total": 0,
                        "zero_new": 0,
                        "stop_reasons": Counter(),
                        "phases": set(),
                    },
                )
                info["attempts"] = int(info.get("attempts", 0) or 0) + 1
                new_bbs = int(record.get("new_bbs", 0) or 0)
                target_bbs = int(record.get("target_bbs", 0) or 0)
                info["new_bbs_total"] = int(info.get("new_bbs_total", 0) or 0) + new_bbs
                if target_bbs:
                    info["target_hits"] = int(info.get("target_hits", 0) or 0) + 1
                if new_bbs <= 0:
                    info["zero_new"] = int(info.get("zero_new", 0) or 0) + 1
                stop_reason = str(record.get("stop_reason") or "unknown")
                info["stop_reasons"][stop_reason] += 1
                info["phases"].add(str(phase_name))

        roots = []
        counters: Counter[str] = Counter()
        for pred_bb, successors in sorted(effective_successors.items()):
            pred_bb = int(pred_bb)
            insn = self.prepared.branch_instruction_by_bb.get(pred_bb, {})
            mnemonic = _dispatch_mnemonic_for_instruction(insn)
            if not (
                _is_switch_frontier_mnemonic(mnemonic)
                or _is_call_frontier_mnemonic(mnemonic)
                or _is_pc_load_dispatch_instruction(insn)
            ):
                continue
            root_keys = [key for key in self.known_branch_root_snapshots if int(key[0]) == pred_bb]
            snapshot_count = sum(len(self._root_snapshot_entries(key)) for key in root_keys)
            successor_rows = []
            for successor in sorted(int(bb) for bb in successors if int(bb) in scope)[: max(0, int(max_successors_per_root))]:
                choice = self._frontier_successor_choice(pred_bb, successor)
                info = attempted.get((pred_bb, successor), {})
                covered_successor = successor in covered
                if int(info.get("attempts", 0) or 0) > 0:
                    status = "hit" if int(info.get("target_hits", 0) or 0) > 0 or covered_successor else "attempted_zero_new"
                elif choice is None:
                    status = "choice_unmapped"
                elif snapshot_count <= 0:
                    status = "no_snapshot"
                elif covered_successor:
                    status = "already_covered"
                else:
                    status = "ready_unattempted"
                counters[status] += 1
                successor_rows.append({
                    "successor_bb": f"0x{successor & 0xFFFFFFFF:08x}",
                    "covered": bool(covered_successor),
                    "choice": choice if isinstance(choice, bool) else (int(choice) if choice is not None and isinstance(choice, int) else str(choice) if choice is not None else None),
                    "status": status,
                    "attempts": int(info.get("attempts", 0) or 0),
                    "target_hits": int(info.get("target_hits", 0) or 0),
                    "new_bbs_total": int(info.get("new_bbs_total", 0) or 0),
                    "zero_new": int(info.get("zero_new", 0) or 0),
                    "stop_reasons": dict((info.get("stop_reasons") or Counter()).most_common(4)) if info else {},
                    "phases": sorted(info.get("phases", set()))[:4] if info else [],
                })
            if not successor_rows:
                continue
            roots.append({
                "pred_bb": f"0x{pred_bb & 0xFFFFFFFF:08x}",
                "mnemonic": mnemonic,
                "function": self._function_name_for_addr(pred_bb) or None,
                "known_snapshot_variants": int(snapshot_count),
                "known_root_events": sum(1 for key in self.known_main_branch_events if int(key[0]) == pred_bb),
                "successor_count": len(set(successors) & scope),
                "successors": successor_rows,
            })
        roots.sort(
            key=lambda item: (
                sum(1 for row in item.get("successors", []) if row.get("status") in {"ready_unattempted", "choice_unmapped", "no_snapshot"}),
                int(item.get("known_snapshot_variants", 0) or 0),
                int(item.get("successor_count", 0) or 0),
                item.get("pred_bb", ""),
            ),
            reverse=True,
        )
        return {
            "root_count": len(roots),
            "status_counts": dict(counters),
            "roots": roots[: max(0, int(max_roots))],
        }

    def _reachable_bb_file_sha256(self) -> Optional[str]:
        """r40 P4：angr 可达分母文件的 sha256（分母必须可溯源）。"""
        path = getattr(self.prepared, "angr_reachable_bb_path", None)
        if not path:
            return None
        try:
            digest = hashlib.sha256()
            with open(path, "rb") as handle:
                for chunk in iter(lambda: handle.read(65536), b""):
                    digest.update(chunk)
            return digest.hexdigest()
        except OSError:
            return None

    def build_report(self, execution_time_seconds: Optional[float] = None, extra: Optional[Dict[str, object]] = None) -> Dict[str, object]:
        active_cleaned = self._dispose_active_temp_emulators(reason="report_finalize")
        self._flush_temp_emulator_quarantine(reason="report_finalize")
        covered_valid_bbs = self.prepared.valid_coverage(self.global_coverage)
        # angr 可达基线（可选分母）：未启用时 reachable_total_bbs 为 None，
        # 对应报告字段输出 null，保持与旧报告的向后兼容。
        covered_reachable_bbs = self.prepared.reachable_coverage(self.global_coverage)
        reachable_total_bbs = self.prepared.reachable_total_bbs
        # E0--E3 are retained as a compatibility/debug view only.  The
        # authoritative report metrics below are derived from per-execution
        # canonical evidence records, so an environment input or an observed
        # event context is not confused with a control-flow intervention.
        legacy_evidence_partitions = self._coverage_evidence_partitions()
        legacy_evidence_sets = legacy_evidence_partitions["evidence_sets"]
        legacy_naturally_supported = legacy_evidence_partitions["witness"]
        legacy_remaining_e2_only = legacy_evidence_partitions["e2_only"]
        legacy_remaining_e3_only = legacy_evidence_partitions["e3_only"]
        legacy_remaining_e2_e3_shared = legacy_evidence_partitions["e2_e3_shared"]
        legacy_classified_coverage = set().union(*legacy_evidence_sets.values())
        legacy_unclassified_coverage = (
            self.validate_coverage(self.global_coverage) - legacy_classified_coverage
        )
        legacy_counterfactual_only = legacy_evidence_partitions["counterfactual_only"]
        all_observed_coverage = self.validate_coverage(self.global_coverage)
        canonical_evidence = self._canonical_evidence_partitions()
        canonical_validated = set(canonical_evidence["validated"])
        canonical_diagnostic = set(canonical_evidence["diagnostic"])
        canonical_diagnostic_only = set(canonical_evidence["diagnostic_only"])
        canonical_unclassified = set(canonical_evidence["unclassified"])
        # These names are intentionally canonical.  Keep the legacy values
        # under explicit ``legacy_*`` names below rather than letting old
        # evidence labels drive the paper-facing coverage numbers.
        naturally_supported = canonical_validated
        diagnostic_supported = canonical_diagnostic_only
        unclassified_coverage = canonical_unclassified
        counterfactual_only = canonical_diagnostic_only
        provenance_mode = (
            "validated_only"
            if not diagnostic_supported and not unclassified_coverage
            else "mixed_validated_and_diagnostic"
            if naturally_supported
            else "diagnostic_or_unclassified_only"
        )
        # P0-C（cycle3 k.5 C5）：记账三数 schema（见模块级
        # coverage_accounting_three_number）。cycle4 k.5 C3：counterfactual
        # 减数改集合合法基数 len(cf∩V)（水位 268 只作 face 只读披露），
        # validated_bbs=|V∖cf| 与 natural_supported 口径自洽。
        coverage_three_number = coverage_accounting_three_number(
            covered_bbs=len(all_observed_coverage),
            validated_bbs=len(canonical_validated),
            canonical_counterfactual_only_bbs=len(
                legacy_counterfactual_only & canonical_validated
            ),
            counterfactual_face_bbs=len(legacy_counterfactual_only),
        )
        coverage_three_number["cf_subset_validated"] = (
            coverage_three_number[
                "direction_confirmed_counterfactual_only_bbs"
            ]
            == len(legacy_counterfactual_only & canonical_validated)
        )
        naturalization_summary = self._path_naturalization_ledger().summary()
        naturalization_summary.update({
            "naturalized_coverage_bbs": len(self.validate_coverage(self.naturalized_coverage)),
            "naturalized_coverage_bb_list": sorted(self.validate_coverage(self.naturalized_coverage)),
            # Deprecated diagnostic breakdown retained for historical
            # naturalization analyses; it is not used for headline coverage.
            "remaining_e2_only_bbs": len(legacy_remaining_e2_only),
            "remaining_e2_only_bb_list": sorted(legacy_remaining_e2_only),
            "remaining_e3_only_bbs": len(legacy_remaining_e3_only),
            "remaining_e3_only_bb_list": sorted(legacy_remaining_e3_only),
            "remaining_e2_e3_shared_bbs": len(legacy_remaining_e2_e3_shared),
            "remaining_e2_e3_shared_bb_list": sorted(legacy_remaining_e2_e3_shared),
            "canonical_validated_replay_bbs": len(canonical_validated),
            "canonical_validated_replay_bb_list": sorted(canonical_validated),
            "canonical_diagnostic_replay_bbs": len(canonical_diagnostic_only),
            "canonical_diagnostic_replay_bb_list": sorted(canonical_diagnostic_only),
            "canonical_unclassified_bbs": len(canonical_unclassified),
            "canonical_unclassified_bb_list": sorted(canonical_unclassified),
            "unclassified_coverage_bbs": len(unclassified_coverage),
            "unclassified_coverage_bb_list": sorted(unclassified_coverage),
        })
        input_provenance = json.loads(
            json.dumps(self.firmware_input_provenance or {}, ensure_ascii=True)
        )
        source_input = dict(input_provenance.get("source") or {})
        analysis_input = dict(input_provenance.get("analysis") or {})
        report = {
            "coverage_schema": "lsgemu.dynamic_coverage.v2",
            "firmware": str(self.prepared.firmware_path),
            "firmware_input": input_provenance,
            "source_firmware": str(source_input.get("path") or self.prepared.firmware_path),
            "source_firmware_sha256": str(source_input.get("sha256") or ""),
            "analysis_firmware": str(analysis_input.get("path") or self.prepared.firmware_path),
            "analysis_firmware_sha256": str(
                analysis_input.get("sha256")
                or getattr(self.prepared, "firmware_sha256", "")
                or ""
            ),
            "total_bbs": self.prepared.total_bbs,
            "covered_bbs": len(self.global_coverage),
            "coverage_rate": (len(self.global_coverage) / self.prepared.total_bbs * 100) if self.prepared.total_bbs else 0.0,
            # angr 从入口可达 BB 基线口径（可选分母，LSGEMU_ANGR_REACHABILITY=1
            # 且 <stem>_angr_reachable.txt 存在时启用；未启用时三字段为 null）。
            # 可达基线由 python -m lsgemu.angr_reachability 离线生成，粒度对齐
            # 规则见 PreparedFirmware.reachable_coverage。
            "reachable_bb_file": (
                str(self.prepared.angr_reachable_bb_path)
                if getattr(self.prepared, "angr_reachable_bb_path", None)
                else None
            ),
            # r40 P4：分母必须可溯源——文件 sha256 与 validated∩angr 同场披露。
            "reachable_bb_file_sha256": (
                self._reachable_bb_file_sha256()
                if reachable_total_bbs is not None
                else None
            ),
            "reachable_total_bbs": reachable_total_bbs,
            "covered_reachable_bbs": (
                len(covered_reachable_bbs) if reachable_total_bbs is not None else None
            ),
            "reachable_coverage_rate": (
                len(covered_reachable_bbs) / reachable_total_bbs * 100
                if reachable_total_bbs
                else None
            ),
            # r40 P4/C1：validated（干净谱系）∩ angr 可达——真实性优先口径。
            # 双口径并列（k.4 P0-3a 条款）：粒度对齐（reachable_coverage）+
            # 严格集合交集（离线复算用）。
            "validated_reachable_bbs": (
                len(self.prepared.reachable_coverage(canonical_validated))
                if reachable_total_bbs is not None
                else None
            ),
            "validated_reachable_bbs_strict_intersection": (
                len(
                    canonical_validated
                    & set(
                        getattr(
                            self.prepared, "angr_reachable_bb_set", set()
                        )
                        or set()
                    )
                )
                if reachable_total_bbs is not None
                else None
            ),
            "covered_reachable_bbs_strict_intersection": (
                len(
                    self.validate_coverage(self.global_coverage)
                    & set(
                        getattr(
                            self.prepared, "angr_reachable_bb_set", set()
                        )
                        or set()
                    )
                )
                if reachable_total_bbs is not None
                else None
            ),
            "execution_time_seconds": execution_time_seconds,
            "phase_metadata": self.phase_metadata,
            "phase_metadata_contract": {
                "canonical_field": "phase_metadata",
                "legacy_duplicate_field_omitted": "phases",
                "latest_value_compatibility": True,
                "history_field": "phase_metadata_history",
                "execution_evidence_field": "phase_execution_records",
            },
            "phase_metadata_history": {
                str(name): [dict(item) for item in list(entries or [])]
                for name, entries in dict(
                    getattr(self, "phase_metadata_history", {}) or {}
                ).items()
            },
            "phase_execution_records": [
                dict(record)
                for record in list(
                    getattr(self, "phase_execution_records", []) or []
                )
            ],
            "phase_execution_records_dropped": int(
                getattr(self, "execution_evidence_records_dropped", 0) or 0
            ),
            "covered_bb_list": sorted(self.global_coverage),
            "coverage_model": "refined_static_bbs",
            "coverage_source": "dynamic_unicorn_execution",
            "coverage_entry_derived": bool(
                not canonical_diagnostic_only and not canonical_unclassified
            ),
            "coverage_provenance_mode": provenance_mode,
            "canonical_coverage_provenance_mode": (
                "validated_only"
                if not canonical_diagnostic_only and not canonical_unclassified
                else "mixed_validated_and_diagnostic"
                if canonical_validated
                else "diagnostic_or_unclassified_only"
            ),
            "coverage_counting_rule": (
                "covered_bb_list is discovery coverage: the union of BBs observed "
                "by Unicorn hooks during reset-entry execution, force-free input "
                "replay, explicitly forced branch/dispatch exploration, contextual "
                "event recovery, and direct-call summary-return continuations. "
                "The canonical evidence view then separates validated replay from "
                "diagnostic replay using execution facts. MMIO/stream values and "
                "events delivered from an observed context are environment inputs; "
                "forced control flow, execution shortcuts, architecture repairs, "
                "and cold vector entry remain diagnostic. Summary-return phases do "
                "not credit skipped callee bodies; they only count BBs actually "
                "executed after the call fallthrough. Static reachability is used "
                "only for prioritization and denominator filtering."
            ),
            "evidence_schema": EVIDENCE_SCHEMA,
            "coverage_by_status": {
                VALIDATED_REPLAY: {
                    "covered_bbs": len(canonical_validated),
                    "covered_bb_list": sorted(canonical_validated),
                },
                DIAGNOSTIC_REPLAY: {
                    "covered_bbs": len(canonical_diagnostic_only),
                    "covered_bb_list": sorted(canonical_diagnostic_only),
                },
                UNCLASSIFIED_REPLAY: {
                    "covered_bbs": len(canonical_unclassified),
                    "covered_bb_list": sorted(canonical_unclassified),
                },
            },
            "validated_replay_bbs": len(canonical_validated),
            "validated_replay_bb_list": sorted(canonical_validated),
            "diagnostic_replay_bbs": len(canonical_diagnostic_only),
            "diagnostic_replay_bb_list": sorted(canonical_diagnostic_only),
            "diagnostic_replay_observed_bbs": len(canonical_diagnostic),
            "canonical_unclassified_bbs": len(canonical_unclassified),
            "canonical_unclassified_bb_list": sorted(canonical_unclassified),
            "canonical_evidence_by_phase": canonical_evidence["status_by_phase"],
            # 相位层 validated_bbs=各相位自身证据计数（:3776/faf2aa8:3699），非全局 |V∖cf|；勿与三数槽混读
            "canonical_evidence_by_phase_scope": "per_phase_evidence_partition_not_global_totals",
            # r36 K4：灰账按原因的 BB 计数（纯增量；不改任何分级口径）。
            "canonical_unclassified_reason_counts": canonical_evidence.get(
                "unclassified_reason_counts"
            ),
            "ghidra_total_bbs": self.prepared.ghidra_total_bbs,
            "dynamic_successor_sources": len(self.dynamic_successors),
            "dynamic_successor_edges": sum(len(successors) for successors in self.dynamic_successors.values()),
            "known_main_branch_events": len(self.known_main_branch_events),
            "known_branch_root_snapshots": len(self.known_branch_root_snapshots),
            "known_branch_root_snapshot_variants": self._known_branch_root_snapshot_variant_count(),
            "snapshot_provenance": self._snapshot_provenance_summary(),
            "snapshot_resources": self._snapshot_resource_summary(),
            "unproven_dynamic_code_targets": {
                f"0x{int(address) & 0xFFFFFFFF:08x}": int(count)
                for address, count in self.unproven_dynamic_code_targets.most_common(64)
            },
            "runtime_bootstrap": dict(RUNTIME_BOOTSTRAP_INFO),
            "loaded_unicorn_library": _loaded_unicorn_library_path(),
            # 向量表检测诊断：fast path 命中时为 null；fast path 失败后触发
            # 全扫描时记录 method/score/signals/offset 等定位依据。
            "vector_table_detection": getattr(
                self.emulator, "vector_table_detection", None
            ),
            # Cortex-M CPU 型号自动匹配结果（MCLASS 模式启用时非 null）：
            # 记录 unicorn 常量名/数值、来源（mcu_name|elf_flags|fallback|env_force）
            # 与决策依据；ctl 切换失败回退 M33 时 source=fallback。
            "cortex_m_cpu_profile": cpu_profile_to_dict(
                getattr(self.emulator, "cortex_m_cpu_profile", None)
            ),
            "runtime_diagnostics": self._runtime_diagnostics_summary(),
            "scheduler_components": self.scheduler_component_summary(),
            "causal_input_model": {
                "scope": "primary_emulator",
                "recorded_events": len(
                    list(getattr(self.emulator, "causal_input_events", []) or [])
                ),
                "total_event_count": int(
                    getattr(self.emulator, "causal_input_event_count", 0) or 0
                ),
                "pre_read_snapshots": len(
                    list(getattr(self.emulator, "causal_input_snapshots", []) or [])
                ),
                "input_occurrence_sites": len(
                    dict(getattr(self.emulator, "input_occurrence_counts", {}) or {})
                ),
                "external_memory_addresses": len(
                    set(
                        getattr(
                            self.emulator,
                            "external_memory_input_addresses",
                            set(),
                        )
                        or set()
                    )
                ),
                "memory_occurrence_constraint_sites": len(
                    set(
                        getattr(
                            self.emulator,
                            "memory_occurrence_constraint_sites",
                            set(),
                        )
                        or set()
                    )
                ),
                "branch_trace": self.emulator.branch_snapshot_manager.get_statistics(),
                "all_emulator_aggregate": dict(
                    getattr(self, "causal_input_feedback_stats", Counter())
                ),
            },
            "stream_summary_reachability": self.stream_summary_reachability_diagnostics(),
            "temp_emulator_lifecycle": self.temp_emulator_lifecycle_summary(),
            "active_temp_emulators_cleaned_before_report": int(active_cleaned),
            "coverage_by_evidence": {
                evidence: {
                    "covered_bbs": len(covered),
                    "covered_bb_list": sorted(covered),
                    "valid_covered_bbs": len(self.prepared.valid_coverage(covered)),
                }
                for evidence, covered in legacy_evidence_sets.items()
            },
            "natural_coverage_lower_bound_bbs": len(naturally_supported),
            "natural_coverage_lower_bound_bb_list": sorted(naturally_supported),
            # cycle4 k.5 C2：natural 撞名治理——顶层本键（canonical E 轴）
            # 与 legacy_evidence_partition 同名键（E0∪E1 轴）同名异值；禁同
            # 名改值，双写下界别名并标记旧键 deprecated（k.6 门控一轮后
            # 下线旧键）。
            "natural_coverage_lower_bound_deprecated": True,
            "validated_replay_lower_bound_bbs": len(canonical_validated),
            "validated_replay_lower_bound_bb_list": sorted(canonical_validated),
            # cycle4 k.5 C1（R3-B (b) 标量形态）：入口自然支撑面口径注记
            # （1448 = |E0∪E1|，不加 bb_list——lep 同名列表已承载该集合）。
            "entry_natural_bbs": len(legacy_naturally_supported),
            "entry_natural_definition": "E0_union_E1",
            "validated_replay_includes_snapshot_counterfactual": True,
            # cycle4 k.5 C1′：validated 与 legacy 反事实分区的交（107 =
            # |V∩cf|；标量，列表可由 validated_replay_bb_list ∩
            # legacy_evidence_partition.counterfactual_only_bb_list 导出）。
            "counterfactual_entry_validated_bbs": len(
                canonical_validated & legacy_counterfactual_only
            ),
            "witness_covered_bbs": len(naturally_supported),
            "witness_covered_bb_list": sorted(naturally_supported),
            "exploratory_only_covered_bbs": len(diagnostic_supported),
            "exploratory_only_covered_bb_list": sorted(diagnostic_supported),
            # There is no canonical E2/E3 split.  Keep the old field as a
            # zero-valued compatibility alias and expose the historical split
            # below for consumers that still need it.
            "context_recovery_only_covered_bbs": 0,
            "context_recovery_only_covered_bb_list": [],
            "forced_and_context_shared_covered_bbs": 0,
            "forced_and_context_shared_covered_bb_list": [],
            "counterfactual_only_coverage_bbs": len(counterfactual_only),
            "counterfactual_only_coverage_bb_list": sorted(counterfactual_only),
            # cycle4 k.5 X1：counterfactual 同名族口径注记（本键=canonical
            # diagnostic_only，161；勿与三数 V∩cf 槽/水位 268 混读）。
            "counterfactual_only_coverage_definition": "canonical_diagnostic_only",
            # P0-C（cycle3 k.5 C5）新旧键**双写一轮**：上两行为旧键
            #（canonical diagnostic_only 口径，消费者迁移期间保留；下线
            # 时点 k.6 再议），本键为新键（记账三数 schema）。
            "coverage_accounting_three_number": coverage_three_number,
            "unclassified_evidence_coverage_bbs": len(unclassified_coverage),
            "unclassified_evidence_coverage_bb_list": sorted(unclassified_coverage),
            "canonical_coverage_summary": {
                "schema": EVIDENCE_SCHEMA,
                "validated_replay_bbs": len(canonical_validated),
                "validated_replay_bb_list": sorted(canonical_validated),
                "diagnostic_replay_bbs": len(canonical_diagnostic_only),
                "diagnostic_replay_bb_list": sorted(canonical_diagnostic_only),
                "diagnostic_replay_observed_bbs": len(canonical_diagnostic),
                "unclassified_bbs": len(canonical_unclassified),
                "unclassified_bb_list": sorted(canonical_unclassified),
                "observed_bbs": len(all_observed_coverage),
                "authoritative": True,
            },
            "legacy_evidence_partition": {
                "deprecated": True,
                "description": "Compatibility-only E0--E3 evidence buckets; not a final coverage grade.",
                "natural_coverage_lower_bound_bbs": len(legacy_naturally_supported),
                "natural_coverage_lower_bound_bb_list": sorted(legacy_naturally_supported),
                # cycle4 k.5 C2：E0∪E1 口径注记（1448；与顶层 canonical E 轴
                # 同名键 1555 同名异值，读数前先看本行）。
                "natural_coverage_lower_bound_definition": "E0_union_E1",
                "e2_only_bbs": len(legacy_remaining_e2_only),
                "e2_only_bb_list": sorted(legacy_remaining_e2_only),
                "e3_only_bbs": len(legacy_remaining_e3_only),
                "e3_only_bb_list": sorted(legacy_remaining_e3_only),
                "e2_e3_shared_bbs": len(legacy_remaining_e2_e3_shared),
                "e2_e3_shared_bb_list": sorted(legacy_remaining_e2_e3_shared),
                "counterfactual_only_bbs": len(legacy_counterfactual_only),
                "counterfactual_only_bb_list": sorted(legacy_counterfactual_only),
                # cycle4 k.5 X1：legacy 268 整脸口径注记（(E2∪E3)∖natural；
                # 勿与三数 cf 槽 107 / canonical diagnostic_only 161 混读）。
                "counterfactual_only_definition": "E2_union_E3_minus_natural",
                "unclassified_bbs": len(legacy_unclassified_coverage),
                "unclassified_bb_list": sorted(legacy_unclassified_coverage),
            },
            "path_naturalization_summary": naturalization_summary,
            "coverage_evidence_summary": {
                "all_unicorn_observed_bbs": len(all_observed_coverage),
                "witness_backed_bbs": len(naturally_supported),
                "validated_replay_bbs": len(canonical_validated),
                "diagnostic_replay_bbs": len(canonical_diagnostic_only),
                "canonical_unclassified_bbs": len(canonical_unclassified),
                "reset_entry_e0_bbs": len(legacy_evidence_sets[EVIDENCE_E0]),
                "force_free_input_witness_e1_bbs": len(legacy_evidence_sets[EVIDENCE_E1]),
                "forced_exploration_e2_only_bbs": len(legacy_remaining_e2_only),
                "context_recovery_e3_only_bbs": len(legacy_remaining_e3_only),
                "forced_and_context_shared_bbs": len(legacy_remaining_e2_e3_shared),
                "unclassified_bbs": len(unclassified_coverage),
                "provenance_mode": provenance_mode,
                "legacy_partition_deprecated": True,
            },
        }
        try:
            main_mmio_handler = getattr(getattr(self, "emulator", None), "mmio_handler", None)
            if main_mmio_handler is not None:
                stats_fn = getattr(main_mmio_handler, "get_mmio_statistics", None)
                if callable(stats_fn):
                    report["mmio_model_statistics"] = stats_fn()
                summary_fn = getattr(main_mmio_handler, "get_state_summary", None)
                if callable(summary_fn):
                    state_summary = summary_fn()
                    if isinstance(state_summary, dict):
                        report["mmio_semantic_summary"] = state_summary.get("semantic_profiles", {})
                causal_context = getattr(
                    getattr(self, "emulator", None),
                    "causal_context",
                    None,
                )
                context_summary_fn = getattr(
                    causal_context,
                    "fingerprint_components",
                    None,
                )
                if callable(context_summary_fn):
                    report["causal_context_summary"] = context_summary_fn()
        except Exception:
            pass
        run_profile = getattr(self, "run_profile", {}) or {}
        report["run_profile"] = dict(run_profile)
        report["run_profile_hash"] = str(run_profile.get("profile_hash") or "")
        report["attempt_id"] = str(os.environ.get("LSGEMU_ATTEMPT_ID") or "")
        report["campaign_fingerprint"] = str(
            os.environ.get("LSGEMU_CAMPAIGN_FINGERPRINT") or ""
        )
        report["source_tree_sha256"] = str(
            os.environ.get("LSGEMU_SOURCE_TREE_SHA256") or ""
        )
        report["firmware_sha256"] = str(
            getattr(self.prepared, "firmware_sha256", "") or ""
        )
        toolchain_fingerprint = dict(
            getattr(self.prepared, "toolchain_fingerprint", {}) or {}
        )
        # ---- validated-only 结论口径（用户 2026-10-09 拍板）----
        # diagnostic / unclassified 一律不进结论。若同时设
        # LSGEMU_COVERAGE_MODE=validated_only，则把头条 covered_bb_list 也切成 validated。
        report["coverage_validated_only"] = {
            "schema": "lsgemu.coverage_validated_only.v1",
            "validated_bbs": len(canonical_validated),
            "validated_bb_list": sorted(canonical_validated),
            "excluded_diagnostic_bbs": len(canonical_diagnostic_only),
            "excluded_unclassified_bbs": len(canonical_unclassified),
            "authoritative": True,
            "policy": (
                "Conclusion-level coverage counts only validated replay BBs. "
                "Diagnostic replay (forced control flow, execution shortcuts, "
                "architecture repairs, cold vector entry, summary-skipped callees, "
                "lineage-contaminated snapshots) and unclassified BBs are excluded "
                "and must not be quoted as coverage."
            ),
        }
        report["coverage_authoritative_bb_list"] = sorted(canonical_validated)
        coverage_mode = str(os.environ.get("LSGEMU_COVERAGE_MODE", "") or "").strip().lower()
        if coverage_mode in {"validated", "validated_only", "validated-only"}:
            report["coverage_mode"] = "validated_only"
            report["covered_bb_list"] = sorted(canonical_validated)
            report["coverage_counting_rule"] = (
                "LSGEMU_COVERAGE_MODE=validated_only: covered_bb_list is restricted to "
                "validated replay BBs; diagnostic and unclassified BBs are excluded "
                "(see coverage_validated_only and canonical_coverage_summary)."
            )
        else:
            report["coverage_mode"] = "discovery_plus_validated"
        report["toolchain_fingerprint"] = toolchain_fingerprint
        report["toolchain_runtime_fingerprint"] = str(
            toolchain_fingerprint.get("runtime_fingerprint") or ""
        )
        prepared_toolchain_identity_hash = str(
            toolchain_fingerprint.get("fingerprint") or ""
        )
        campaign_toolchain_identity_hash = str(
            os.environ.get("LSGEMU_TOOLCHAIN_IDENTITY_HASH") or ""
        )
        report["toolchain_identity_hash"] = (
            campaign_toolchain_identity_hash
            or prepared_toolchain_identity_hash
        )
        report["prepared_toolchain_identity_hash"] = (
            prepared_toolchain_identity_hash
        )
        report["toolchain_identity_scope"] = (
            "campaign_runtime_without_firmware_denominator"
            if campaign_toolchain_identity_hash
            else "prepared_firmware_with_valid_bb_identity"
        )
        static_cache_identity = dict(
            getattr(self.prepared, "static_cache_identity", {}) or {}
        )
        report["static_cache_identity"] = static_cache_identity
        report["static_cache_identity_hash"] = str(
            static_cache_identity.get("identity_hash") or ""
        )
        denominator_bytes = b"".join(
            int(address).to_bytes(4, "little", signed=False)
            for address in sorted(self.prepared.valid_bb_set)
        )
        report["valid_bb_denominator_hash"] = hashlib.sha256(
            denominator_bytes
        ).hexdigest()
        phase_map = self.phase_metadata if isinstance(self.phase_metadata, dict) else {}
        report["crash_triage_summary"] = self._crash_triage_summary(phase_map)
        invalid_real_entry_phases = []
        counted_phases = []
        for phase_name, phase in phase_map.items():
            if not isinstance(phase, dict):
                continue
            if phase.get("coverage_counted", True) is False:
                continue
            counted_phases.append(str(phase_name))
            entry_derivation = str(phase.get("entry_derivation") or "")
            if str(phase_name) == "isr":
                invalid_real_entry_phases.append({
                    "phase": str(phase_name),
                    "reason": entry_derivation or "cold_vector_handler_direct_entry",
                })
                continue
            if "isr" in str(phase_name) and phase.get("context_snapshot_mode") is False:
                invalid_real_entry_phases.append({
                    "phase": str(phase_name),
                    "reason": "isr_without_entry_derived_context_snapshot",
                })
        # Canonical strictness is binary: clean environment/input/event
        # replays are validated; forced control, shortcuts, cold entries and
        # incomplete telemetry remain diagnostic.  The legacy E0--E3
        # partitions above are retained only for report compatibility.
        validated_replayable = bool(
            not canonical_diagnostic_only
            and not canonical_unclassified
        )
        # Keep the historical key for scripts that consume existing reports;
        # the binary status is the authoritative field for new consumers.
        report["validated_replayable"] = validated_replayable
        report["strict_real_entry_replayable"] = validated_replayable
        report["strict_real_entry_replay_contract"] = {
            "schema": EVIDENCE_SCHEMA,
            "accepted_status": VALIDATED_REPLAY,
            "diagnostic_status": DIAGNOSTIC_REPLAY,
            "validated_replay_bbs": len(canonical_validated),
            "diagnostic_replay_bbs": len(canonical_diagnostic_only),
            "diagnostic_replay_observed_bbs": len(canonical_diagnostic),
            "unclassified_bbs": len(canonical_unclassified),
            "diagnostic_reasons_by_phase": {
                name: list(details.get("reasons", []))
                for name, details in canonical_evidence["status_by_phase"].items()
                if details.get("reasons")
            },
            "environment_inputs_allowed": [
                "occurrence-scoped MMIO and external-memory values",
                "stream input consumed at the recorded occurrence",
                "interrupt/event delivery from an observed replay context",
            ],
            "execution_changes_not_accepted": [
                "forced branch or dispatch decisions",
                "polling-loop intervention",
                "function summary-return or skipped callee",
                "SVC/Thumb/indirect-branch execution repair",
                "cold vector-handler direct entry",
            ],
            "coverage_credit_policy": (
                "A BB is first observed by Unicorn and filtered through the valid-BB oracle. "
                "It is reported as validated only when its phase has no execution "
                "intervention under the declared environment model."
            ),
            "legacy_alias": "strict_real_entry_replayable",
        }
        report["legacy_strict_real_entry_replay_contract"] = {
            "entry_point": f"0x{int(self.prepared.entry_point) & 0xFFFFFFFF:08x}",
                "allowed_external_nondeterminism": [
                    "MMIO read values supplied by scoped/global constraints",
                    "occurrence-scoped external memory and stream input values",
                    "interrupt timing from entry-derived dynamic snapshots",
                "callee summary return at direct-call sites already reached from entry-derived snapshots",
            ],
            "coverage_credit_policy": (
                "A BB is counted only if observed by Unicorn execution and, for valid coverage, "
                "present in valid_basic_blocks.txt. Static CFG and static constraints are only "
                "scheduler/model inputs; dynamic_replay_required constraints must be replayed "
                "from reset-entry or entry-derived snapshots before any BB receives credit."
            ),
            "natural_replay_policy": (
                "Deprecated compatibility description of the former E0--E3 labels. "
                "Use strict_real_entry_replay_contract and the binary validated/diagnostic "
                "status fields for new analysis."
            ),
            "natural_supported_bbs": len(naturally_supported),
            # P1-C（cycle3 k.5 C7）：本键为**刷新值**——naturally_supported
            # 即 canonical_validated（上方赋值），非 legacy E0--E3 派生；
            # 进度/报告读者以本键为准（同名旧读者不改）。
            "natural_supported_bbs_refreshed_from": "canonical_validated",
            # cycle4 k.5 C2：natural 撞名 alias 注记（水位/legacy 读者面）。
            "natural_supported_bbs_alias_of": "validated_replay",
            "counterfactual_only_bbs": len(counterfactual_only),
            # cycle4 k.5 X1：本键=canonical diagnostic_only 口径注记（161；
            # 与水位 ledger_watermarks.counterfactual_only_bbs=268 同名异值）。
            "counterfactual_only_bbs_caliber": "canonical_diagnostic_only",
            "unclassified_evidence_bbs": len(unclassified_coverage),
            "counted_phases": counted_phases,
            "excluded_diagnostic_phases": [
                str(name)
                for name, phase in phase_map.items()
                if isinstance(phase, dict) and phase.get("coverage_counted", True) is False
            ],
            "invalid_counted_phases": invalid_real_entry_phases,
        }
        branch_root_causes = summarize_branch_mmio_root_causes(phase_map)
        if branch_root_causes:
            report["branch_mmio_root_causes"] = branch_root_causes
        report["environment_feasibility_summary"] = self._environment_feasibility_summary()
        report["scheduler_feedback"] = self._scheduler_feedback_summary()
        report["evaluation_metrics"] = self._evaluation_metrics_summary(
            execution_time_seconds=execution_time_seconds
        )
        if self.prepared.valid_bb_set:
            reachability_summary = self.static_reachability_summary()
            valid_witness_coverage = self.prepared.valid_coverage(
                naturally_supported
            )
            valid_diagnostic_coverage = self.prepared.valid_coverage(
                diagnostic_supported
            )
            # The old E2/E3 split remains available for compatibility, but is
            # deliberately kept out of canonical coverage fields.
            valid_legacy_witness_coverage = self.prepared.valid_coverage(
                legacy_naturally_supported
            )
            valid_legacy_exploratory_only = self.prepared.valid_coverage(
                legacy_remaining_e2_only
            )
            valid_legacy_context_recovery_only = self.prepared.valid_coverage(
                legacy_remaining_e3_only
            )
            valid_legacy_forced_and_context_shared = self.prepared.valid_coverage(
                legacy_remaining_e2_e3_shared
            )
            report.update({
                "valid_basic_blocks_path": str(self.prepared.valid_bb_path) if self.prepared.valid_bb_path else None,
                "valid_total_bbs": self.prepared.valid_total_bbs,
                "valid_covered_bbs": len(covered_valid_bbs),
                "valid_coverage_rate": (
                    len(covered_valid_bbs) / self.prepared.valid_total_bbs * 100
                    if self.prepared.valid_total_bbs else 0.0
                ),
                "valid_witness_covered_bbs": len(valid_witness_coverage),
                "valid_witness_coverage_rate": (
                    len(valid_witness_coverage)
                    / self.prepared.valid_total_bbs
                    * 100
                    if self.prepared.valid_total_bbs else 0.0
                ),
                "valid_witness_covered_bb_list": sorted(valid_witness_coverage),
                "valid_exploratory_only_covered_bbs": len(valid_diagnostic_coverage),
                "valid_exploratory_only_covered_bb_list": sorted(valid_diagnostic_coverage),
                "valid_context_recovery_only_covered_bbs": 0,
                "valid_context_recovery_only_covered_bb_list": [],
                "valid_forced_and_context_shared_covered_bbs": 0,
                "valid_forced_and_context_shared_covered_bb_list": [],
                "valid_canonical_validated_replay_bbs": len(valid_witness_coverage),
                "valid_canonical_validated_replay_bb_list": sorted(valid_witness_coverage),
                "valid_canonical_diagnostic_replay_bbs": len(valid_diagnostic_coverage),
                "valid_canonical_diagnostic_replay_bb_list": sorted(valid_diagnostic_coverage),
                "valid_legacy_evidence_partition": {
                    "deprecated": True,
                    "witness_bbs": len(valid_legacy_witness_coverage),
                    "e2_only_bbs": len(valid_legacy_exploratory_only),
                    "e3_only_bbs": len(valid_legacy_context_recovery_only),
                    "e2_e3_shared_bbs": len(valid_legacy_forced_and_context_shared),
                },
                "valid_entry_static_reachable_bbs": int(reachability_summary.get("valid_entry_static_reachable_bbs", 0) or 0),
                "valid_entry_static_reachable_covered_bbs": int(reachability_summary.get("valid_entry_static_reachable_covered_bbs", 0) or 0),
                "valid_entry_static_reachable_coverage_rate": float(reachability_summary.get("valid_entry_static_reachable_coverage_rate", 0.0) or 0.0),
                "valid_entry_plus_vector_static_reachable_bbs": int(reachability_summary.get("valid_entry_plus_vector_static_reachable_bbs", 0) or 0),
                "valid_entry_plus_vector_static_reachable_covered_bbs": int(reachability_summary.get("valid_entry_plus_vector_static_reachable_covered_bbs", 0) or 0),
                "valid_entry_plus_vector_reachable_coverage_rate": float(reachability_summary.get("valid_entry_plus_vector_reachable_coverage_rate", 0.0) or 0.0),
                "valid_static_unreachable_from_entry_or_vectors": int(reachability_summary.get("valid_static_unreachable_from_entry_or_vectors", 0) or 0),
                "extended_static_roots_available": bool(reachability_summary.get("extended_static_roots_available", False)),
                "extended_static_root_bbs": int(reachability_summary.get("extended_static_root_bbs", 0) or 0),
                "extended_static_root_categories": reachability_summary.get("extended_static_root_categories", {}) or {},
                "extended_static_root_examples": reachability_summary.get("extended_static_root_examples", {}) or {},
                "extended_static_reachable_bbs": int(reachability_summary.get("extended_static_reachable_bbs", 0) or 0),
                "extended_static_reachable_covered_bbs": int(reachability_summary.get("extended_static_reachable_covered_bbs", 0) or 0),
                "extended_static_reachable_coverage_rate": float(reachability_summary.get("extended_static_reachable_coverage_rate", 0.0) or 0.0),
                "static_unreachable_from_extended_roots": int(reachability_summary.get("static_unreachable_from_extended_roots", 0) or 0),
                "valid_extended_static_reachable_bbs": int(reachability_summary.get("valid_extended_static_reachable_bbs", 0) or 0),
                "valid_extended_static_reachable_covered_bbs": int(reachability_summary.get("valid_extended_static_reachable_covered_bbs", 0) or 0),
                "valid_extended_static_reachable_uncovered_bbs": int(reachability_summary.get("valid_extended_static_reachable_uncovered_bbs", 0) or 0),
                "valid_extended_static_reachable_coverage_rate": float(reachability_summary.get("valid_extended_static_reachable_coverage_rate", 0.0) or 0.0),
                "valid_static_unreachable_from_extended_roots": int(reachability_summary.get("valid_static_unreachable_from_extended_roots", 0) or 0),
                "covered_valid_bb_list": sorted(covered_valid_bbs),
                "valid_bb_denominator_status": "available",
            })
        else:
            # r40 P4/P0-3b（主代理裁决：fail-closed）：设备侧 valid_* 分母未
            # 接线，空集读数必须带 unavailable 状态位，不冒充数字。
            report["valid_bb_denominator_status"] = "unavailable"
        # r40 P4/C1（k.4 口径条款）：四层分母并列披露 + 分母 hash + 已知口径
        # 缺口声明。任何百分比必须带分母名与 sha256；禁止把任何一层单独
        # 写作"覆盖率"头条。
        try:
            static_layers = self.static_reachability_summary()
        except Exception:
            static_layers = {}
        report["denominator_disclosure"] = {
            "L0_total_static_bbs": int(
                static_layers.get("total_static_bbs", 0) or 0
            ),
            "L1_entry_plus_vector_static_reachable_bbs": int(
                static_layers.get("entry_plus_vector_static_reachable_bbs", 0) or 0
            ),
            "L2_angr_symbol_confirmed_reachable_bbs": reachable_total_bbs,
            "L2_reachable_bb_file": (
                str(self.prepared.angr_reachable_bb_path)
                if getattr(self.prepared, "angr_reachable_bb_path", None)
                else None
            ),
            "L2_reachable_bb_file_sha256": self._reachable_bb_file_sha256(),
            "L3_validated_replay_bbs": len(canonical_validated),
            "L3_validated_replay_reachable_bbs": report.get(
                "validated_reachable_bbs"
            ),
            # P1-E（cycle3 k.5 C8）：终止条件合并计分母（denominator_
            # disclosure 邻位）。桶口径：cf 取 C5 三数口径（cycle4 k.5
            # 起为集合基数 |V∩cf|，lockstep 同步）；exploration=canonical
            # diagnostic_only；fidelity_gap=
            # unclassified（E4 红面记录数在桶内披露，k.6 离线喂入）；
            # 不接受项默认 0（r38/r40 零 force 默认，不新增）。
            "termination_merged_denominator": termination_merged_denominator(
                covered_bbs=len(all_observed_coverage),
                validated_bbs=len(canonical_validated),
                counterfactual_only_bbs=int(
                    coverage_three_number[
                        "direction_confirmed_counterfactual_only_bbs"
                    ]
                ),
                exploration_only_bbs=len(diagnostic_supported),
                unclassified_bbs=len(unclassified_coverage),
                e4_red_face_records=0,
                not_accepted_bbs=0,
            ),
            "notes": [
                "L2 = angr CFGEmulated 不动点（符号确认子集，实测欠近似："
                "grace 4h 臂 1448 条 validated 中 1131 条在 L2 之外）；"
                "禁止单独作覆盖率头条分母。",
                "用户定义的可达性（经外部 MMIO 输入/中断从入口可达）目前无任何"
                "产物可给出，是已知口径缺口。",
                "valid_* 设备侧分母未接线（fail-closed）：denominator=unavailable。",
            ],
        }
        if extra:
            report.update(extra)
        return report

    def save_report(self, output_path: str | Path, execution_time_seconds: Optional[float] = None, extra: Optional[Dict[str, object]] = None) -> Dict[str, object]:
        report = self.build_report(execution_time_seconds=execution_time_seconds, extra=extra)
        output_path = Path(output_path)
        atomic_json_dump(report, output_path, indent=None)
        return report

    @staticmethod
    def _phase_crash_triage_items(phase_name: str, phase: Dict[str, object]) -> List[Dict[str, object]]:
        items: List[Dict[str, object]] = []

        def add_report(report: object, source: str) -> None:
            if not isinstance(report, dict):
                return
            item = dict(report)
            item.setdefault("phase", phase_name)
            item.setdefault("phase_name", phase_name)
            item.setdefault("phase_source", source)
            items.append(item)

        add_report(phase.get("crash_triage"), "phase")
        run_result = phase.get("run_result")
        if isinstance(run_result, dict):
            add_report(run_result.get("crash_triage"), "run_result")

        for list_key in ("debug_records", "candidate_debug_records", "materialized_records", "records"):
            for index, record in enumerate(phase.get(list_key) or []):
                if not isinstance(record, dict):
                    continue
                add_report(record.get("crash_triage"), f"{list_key}[{index}]")
                nested = record.get("run_result")
                if isinstance(nested, dict):
                    add_report(nested.get("crash_triage"), f"{list_key}[{index}].run_result")
        return items

    def _crash_triage_summary(self, phase_map: Dict[str, object]) -> Dict[str, object]:
        reports: List[Dict[str, object]] = []
        for phase_name, phase in (phase_map or {}).items():
            if isinstance(phase, dict):
                reports.extend(self._phase_crash_triage_items(str(phase_name), phase))

        categories: Counter[str] = Counter()
        classifications: Counter[str] = Counter()
        buckets: Counter[str] = Counter()
        validation_required = 0
        samples: List[Dict[str, object]] = []
        for report in reports:
            category = str(report.get("category") or "unknown")
            classification = str(report.get("classification") or "unknown")
            bucket = str(report.get("bucket_key") or f"{classification}:unknown")
            categories[category] += 1
            classifications[classification] += 1
            buckets[bucket] += 1
            if report.get("requires_replay_validation"):
                validation_required += 1
            if len(samples) < 32 and category != "normal":
                samples.append({
                    "phase": report.get("phase") or report.get("phase_name"),
                    "phase_source": report.get("phase_source"),
                    "category": category,
                    "classification": classification,
                    "confidence": report.get("confidence"),
                    "severity": report.get("severity"),
                    "evidence_level": report.get("evidence_level"),
                    "pc": report.get("pc"),
                    "lr": report.get("lr"),
                    "sp": report.get("sp"),
                    "access_address": report.get("access_address"),
                    "stop_reason": report.get("stop_reason"),
                    "bucket_key": bucket,
                })

        return {
            "enabled": True,
            "total_reports": len(reports),
            "firmware_crashes": sum(1 for item in reports if item.get("is_crash")),
            "hangs": sum(1 for item in reports if item.get("is_hang")),
            "model_artifacts": int(categories.get("model_or_harness_artifact", 0)),
            "tooling_failures": int(categories.get("tooling_or_runtime_failure", 0)),
            "requires_replay_validation": validation_required,
            "unique_buckets": len(buckets),
            "categories": dict(categories),
            "classifications": dict(classifications),
            "buckets": dict(buckets.most_common(64)),
            "samples": samples,
        }
